-- =============================================================================
-- 365 — LES EXERCICES DE 6e, TROIS NIVEAUX PAR FICHE (Lucas, 17/09/2026)
--
-- 402 sujets écrits d'avance et relus : pour chacune des 134 fiches de 6e
-- (toutes matières), un sujet Facile, un Moyen, un Difficile, chacun avec son
-- barème sur 20 et son corrigé type (`contenu.corrige`, jamais envoyé à
-- l'élève avant sa copie). L'IA ne fait plus que les corriger.
--
-- Fichier GÉNÉRÉ (scratchpad exo/generer-sql.mjs) : ne pas l'éditer à la main,
-- le régénérer. L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer
-- la migration met le sujet à jour au lieu de le dupliquer. Une fiche absente
-- de la base est simplement sautée (jointure sur chapters).
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('a2dd6f82-d9ec-57b4-ac59-63700189c6a2'::uuid, 1, 'redaction', $exo${"titre":"Règle ou loi : faire la différence","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Explique la différence entre une **règle** et une **loi** : à qui chacune s'applique-t-elle ?\n2. Qui écrit une règle ? Qui vote une loi ? Nomme les deux chambres concernées.\n3. Où une loi est-elle publiée ?\n4. Cite les **trois rôles** des règles et des lois vus en cours.","bareme":[{"critere":"Différence règle / loi selon le groupe concerné","points":8},{"critere":"Auteurs de la règle et de la loi, publication au Journal officiel","points":7},{"critere":"Les trois rôles des règles et des lois","points":5}],"dureeMin":6,"corrige":"1. Une **règle** s'applique à un **groupe précis** (un collège, un jeu, une famille). Une **loi** s'applique à **tous**, sur tout le territoire.\n2. La règle est faite par **le groupe lui-même**. La loi est votée par le **Parlement**, composé de l'**Assemblée nationale** et du **Sénat**.\n3. La loi est publiée au **Journal officiel**.\n4. Les règles et les lois servent à **protéger** (le plus faible du plus fort), à **organiser** la vie commune (ex. le code de la route rend possible la liberté de circuler) et à **sanctionner** ce qui porte atteinte à autrui."}$exo$::jsonb),
  ('a2dd6f82-d9ec-57b4-ac59-63700189c6a2'::uuid, 2, 'redaction', $exo${"titre":"Une sanction juste au collège","consigne":"Lis la situation, puis réponds aux questions en rédigeant des phrases complètes et en t'appuyant sur le cours.","enonce":"**Situation**\n\n> Au collège, Tom a volontairement déchiré plusieurs livres du CDI. Le règlement intérieur prévoit que toute dégradation de matériel est sanctionnée. Après avoir expliqué à Tom pourquoi son geste est grave, le principal décide qu'il devra réparer et recouvrir des livres du CDI pendant deux heures.\n>\n> Un camarade de Tom proteste : « Il aurait fallu l'humilier devant toute la classe, pour qu'il paie ! »\n\n1. Le règlement intérieur du collège est-il une règle ou une loi ? Justifie.\n2. La sanction de Tom respecte-t-elle les trois conditions d'une sanction juste vues en cours ? Nomme-les et vérifie chacune.\n3. Pourquoi la proposition du camarade ne correspond-elle pas au but d'une sanction ? Explique ce que la sanction cherche aussi à faire.","bareme":[{"critere":"Identification du règlement intérieur comme règle, avec justification","points":5},{"critere":"Les trois conditions de la sanction nommées et appliquées à la situation","points":9},{"critere":"Distinction entre sanction et vengeance, idée de réparation","points":6}],"dureeMin":10,"corrige":"1. C'est une **règle** : elle s'applique à un **groupe précis** (les membres du collège) et elle est faite par ce groupe, pas par le Parlement pour tout le territoire.\n2. Oui, la sanction est juste :\n- elle est **proportionnée** à la faute : Tom a abîmé des livres, il répare des livres pendant deux heures ;\n- elle est **prévue à l'avance** : le règlement intérieur prévoyait déjà une sanction pour les dégradations, elle n'est pas inventée après coup ;\n- elle est **expliquée** : le principal a expliqué à Tom pourquoi son geste est grave.\n3. Humilier Tom serait une **vengeance** : on chercherait seulement à le faire souffrir. Or la sanction n'est pas une vengeance : elle vise aussi à **réparer** le tort causé, et à rendre l'élève responsable de ses actes. C'est le sens des **mesures de responsabilisation** au collège."}$exo$::jsonb),
  ('a2dd6f82-d9ec-57b4-ac59-63700189c6a2'::uuid, 3, 'redaction', $exo${"titre":"La loi : au-dessus des règles, mais pas éternelle","consigne":"Analyse les documents puis réponds aux questions en justifiant chaque réponse avec les notions du cours.","enonce":"**Document 1 – Un projet de règlement**\n\n> Des élèves proposent d'ajouter au règlement intérieur de leur collège : « Les élèves de 3e pourront punir eux-mêmes les élèves de 6e qui les dérangent. »\n\n**Document 2 – Deux dates**\n\n- 1848 : abolition définitive de l'esclavage\n- 1981 : abolition de la peine de mort\n\n1. Classe dans l'ordre, de la plus haute à la plus basse : les décrets, la Constitution, les règlements, les lois.\n2. Le projet du document 1 pourrait-il être accepté ? Explique en utilisant la hiérarchie des normes et le rôle protecteur de la loi.\n3. Décris les étapes qui permettent à une loi d'exister, depuis la proposition jusqu'à la promulgation.\n4. Que montrent les dates du document 2 sur la loi ? Explique pourquoi une loi peut être changée.","bareme":[{"critere":"Ordre correct de la hiérarchie des normes","points":3},{"critere":"Analyse du projet de règlement : norme supérieure et protection du plus faible","points":6},{"critere":"Étapes de fabrication d'une loi","points":5},{"critere":"Une loi peut être modifiée : exemples et lien avec les élus","points":4},{"critere":"Rédaction et justification des réponses","points":2}],"dureeMin":16,"corrige":"1. La **Constitution** → les **lois** → les **décrets** → les **règlements**.\n2. Non. Une règle ne peut **jamais contredire une norme supérieure** : le règlement intérieur d'un collège ne peut pas aller contre la loi. Or ce projet laisse des élèves plus âgés punir des plus jeunes : ce serait le **rapport de force** qui compte, les plus forts contre les plus faibles. La loi existe justement pour **protéger le plus faible du plus fort**. De plus, une sanction doit être prévue, proportionnée et expliquée, pas décidée par des camarades.\n3. Une **proposition** (par des parlementaires) ou un **projet** (par le gouvernement) → le texte est **discuté et voté par les deux chambres** (Assemblée nationale et Sénat) → il peut être contrôlé par le **Conseil constitutionnel** → il est **promulgué par le président de la République**, puis publié au Journal officiel.\n4. Ces dates montrent qu'une loi **n'est pas éternelle** : en 1848, la loi a aboli définitivement l'esclavage ; en 1981, elle a aboli la peine de mort. La loi est votée par des **représentants élus** : elle peut donc être **modifiée ou abrogée** quand ils le décident."}$exo$::jsonb),
  ('9875e9aa-116d-5019-85f1-667cf8385bb8'::uuid, 1, 'redaction', $exo${"titre":"Le délégué de classe","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Comment le délégué de classe est-il élu ?\n2. Dans quelle instance représente-t-il ses camarades ?\n3. Cite les **trois devoirs** du délégué.","bareme":[{"critere":"Mode d'élection du délégué","points":6},{"critere":"Le conseil de classe comme lieu de représentation","points":5},{"critere":"Les trois devoirs du délégué","points":9}],"dureeMin":6,"corrige":"1. Le délégué est **élu par ses camarades** au **scrutin secret** : chacun vote sans que les autres voient son choix.\n2. Il **représente** ses camarades au **conseil de classe**.\n3. Le délégué doit :\n- porter la parole **du groupe**, et non la sienne ;\n- **rendre compte** ensuite à la classe de ce qui a été dit ;\n- ne pas révéler ce qui est **confidentiel**."}$exo$::jsonb),
  ('9875e9aa-116d-5019-85f1-667cf8385bb8'::uuid, 2, 'redaction', $exo${"titre":"Porter secours à un camarade","consigne":"Lis la situation puis réponds aux questions en rédigeant des phrases complètes.","enonce":"**Situation**\n\n> Pendant un match au stade, Yanis s'effondre et ne bouge plus. Ses camarades Léa et Hugo sont à côté de lui. Hugo hésite : « Ce n'est pas mon problème, je n'ai que 11 ans. »\n\n1. Quel numéro Léa peut-elle appeler pour une urgence médicale ? Quel numéro d'urgence européen peut-elle aussi composer depuis n'importe quel téléphone ?\n2. Un témoin sourd voudrait prévenir les secours : quel numéro peut-il utiliser, et comment ?\n3. Donne, dans l'ordre, les trois gestes appris lors de la formation PSC1.\n4. Hugo a-t-il raison de ne rien faire ? Explique en t'appuyant sur la loi.","bareme":[{"critere":"Numéros 15 et 112 correctement associés","points":5},{"critere":"Numéro 114 et son usage par SMS","points":3},{"critere":"Les trois gestes dans l'ordre","points":6},{"critere":"Explication du devoir de porter secours","points":6}],"dureeMin":10,"corrige":"1. Léa peut appeler le **15**, le **SAMU**, pour une urgence médicale. Elle peut aussi composer le **112**, le numéro d'urgence **européen**, depuis n'importe quel téléphone.\n2. Il peut utiliser le **114**, qui permet de joindre les urgences **par SMS** : il est prévu pour les personnes sourdes ou malentendantes.\n3. **Alerter** → **masser** → **utiliser un défibrillateur**.\n4. Non. On n'attend pas d'avoir 18 ans pour agir. **Ne pas porter secours quand on le peut est un délit.** Hugo n'a pas besoin de tout faire seul : **appeler, c'est déjà secourir**. Il peut par exemple alerter les secours pendant que Léa reste auprès de Yanis."}$exo$::jsonb),
  ('9875e9aa-116d-5019-85f1-667cf8385bb8'::uuid, 3, 'redaction', $exo${"titre":"Une déléguée qui se trompe de rôle","consigne":"Analyse le document, puis réponds aux questions en justifiant avec les notions du cours.","enonce":"**Document – Le récit de Nora, élève de 6e**\n\n> « Inès, notre déléguée, est allée au conseil de classe. Elle n'a parlé que de ce qu'elle voulait, elle, sans dire ce que la classe avait demandé. Ensuite, elle ne nous a rien raconté de la réunion. Par contre, elle a répété à tout le monde ce que les professeurs avaient dit, en privé, sur un élève. Moi, je voudrais plutôt m'occuper du tri des déchets et du gaspillage à la cantine, et je fais déjà de l'aide aux devoirs dans une association, sans être payée. »\n\n1. Relève les **trois erreurs** d'Inès et explique, pour chacune, le devoir du délégué qu'elle n'a pas respecté.\n2. Pourquoi dit-on que l'élection du délégué est une première expérience de **démocratie représentative** ? Qu'est-ce que la classe a le droit de faire face à Inès ?\n3. Quelle instance du collège correspond au souhait de Nora de s'occuper du tri et du gaspillage ? Cite une autre instance où les élèves proposent des projets.\n4. Qu'est-ce qu'une association loi 1901 ? Montre que l'engagement de Nora dans une association correspond à cette définition.\n5. Selon le cours, qu'est-ce que l'engagement change dans le rapport d'un élève à son établissement ?","bareme":[{"critere":"Les trois erreurs d'Inès reliées aux devoirs du délégué","points":6},{"critere":"Explication de la démocratie représentative et du droit de demander des comptes","points":4},{"critere":"Identification des éco-délégués et du CVC","points":3},{"critere":"Définition de l'association loi 1901 appliquée à Nora","points":4},{"critere":"Ce que l'engagement apporte","points":3}],"dureeMin":18,"corrige":"1. Les trois erreurs :\n- Inès n'a parlé que de son avis : or le délégué doit porter la parole **du groupe**, pas la sienne ;\n- elle n'a rien raconté après la réunion : or le délégué doit **rendre compte** ensuite ;\n- elle a répété ce qui avait été dit en privé sur un élève : or le délégué ne doit pas révéler ce qui est **confidentiel**.\n2. C'est de la **démocratie représentative** parce que les élèves **choisissent quelqu'un pour parler en leur nom**. En échange, la classe a le droit de **lui demander des comptes** : elle peut demander à Inès ce qui s'est dit et pourquoi elle n'a pas transmis ses demandes.\n3. Le souhait de Nora correspond aux **éco-délégués** (tri, gaspillage alimentaire, énergie). Autre instance : le **CVC** (conseil de la vie collégienne), où les élèves proposent des projets sur la vie de l'établissement (on peut aussi citer le foyer socio-éducatif, les clubs ou l'AS).\n4. Une **association loi 1901** réunit des personnes autour d'un **but non lucratif** : on ne cherche pas à gagner de l'argent. Nora fait de l'**aide aux devoirs sans être payée** : c'est du **bénévolat** au service d'un but non lucratif.\n5. L'engagement change le rapport à l'établissement : on cesse de **subir** un lieu pour en devenir **responsable**. Et l'engagement **s'apprend**, comme tout le reste."}$exo$::jsonb),
  ('74137f62-de99-5c1d-a450-5a479535c67b'::uuid, 1, 'redaction', $exo${"titre":"Reconnaître les symboles de la République","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Donne la devise de la République française.\n2. Explique l'origine des trois couleurs du drapeau tricolore.\n3. Quelle coiffure porte Marianne ? Que représente-t-elle ?","bareme":[{"critere":"La devise complète","points":5},{"critere":"Origine des couleurs du drapeau","points":8},{"critere":"Marianne : le bonnet phrygien et ce qu'elle représente","points":7}],"dureeMin":6,"corrige":"1. La devise est **« Liberté, Égalité, Fraternité »**.\n2. Le **bleu** et le **rouge** sont les couleurs de la ville de **Paris** ; le **blanc** est la couleur du **roi**. Le drapeau, né en **1790**, réunit ainsi la ville et la monarchie.\n3. Marianne porte le **bonnet phrygien**, que portaient les esclaves affranchis de Rome. Elle représente la **liberté** et la **République**."}$exo$::jsonb),
  ('74137f62-de99-5c1d-a450-5a479535c67b'::uuid, 2, 'redaction', $exo${"titre":"La Marseillaise et le 14 Juillet","consigne":"Réponds aux questions en rédigeant des phrases complètes et en donnant les dates exactes.","enonce":"1. Qui a écrit la Marseillaise ? En quelle année, dans quelle ville et pour quel usage ?\n2. Pourquoi ce chant s'appelle-t-il « la Marseillaise » ? En quelle année devient-il l'hymne national ?\n3. Depuis quelle année le 14 Juillet est-il la fête nationale ?\n4. Le 14 Juillet commémore **deux** événements : nomme-les en donnant leur date, et explique ce que célébrait le second.","bareme":[{"critere":"Auteur, date, lieu et usage de la Marseillaise","points":6},{"critere":"Origine du nom et date de l'hymne national","points":5},{"critere":"Date de la fête nationale","points":3},{"critere":"Les deux événements commémorés et leur sens","points":6}],"dureeMin":10,"corrige":"1. La Marseillaise a été écrite par **Rouget de Lisle** en **1792**, à **Strasbourg**, comme **chant de guerre**.\n2. Elle doit son nom aux **fédérés marseillais** qui la chantaient en montant à Paris. Elle devient **hymne national en 1879**.\n3. Le 14 Juillet est la fête nationale depuis **1880**.\n4. Il commémore la **prise de la Bastille** (14 juillet **1789**) **et** la **Fête de la Fédération** (**1790**). La Fête de la Fédération célébrait l'**unité de la Nation**."}$exo$::jsonb),
  ('74137f62-de99-5c1d-a450-5a479535c67b'::uuid, 3, 'redaction', $exo${"titre":"Corriger un exposé sur les symboles","consigne":"Repère les erreurs du document, corrige-les en justifiant, puis explique à quoi servent les symboles.","enonce":"**Document – Extrait de l'exposé de Sacha**\n\n> « Le coq gaulois est le symbole officiel le plus important de la France. La devise Liberté, Égalité, Fraternité a été inventée en 1950. Le 14 Juillet rappelle seulement la prise de la Bastille. Les symboles, ce sont juste des décorations pour faire joli sur les mairies. »\n\n1. Le document contient **quatre erreurs**. Recopie chaque phrase fausse et corrige-la en justifiant avec le cours.\n2. D'où vient le lien entre le coq et la France ? Explique le jeu de mots.\n3. Où peut-on voir la devise et Marianne dans la vie de tous les jours ? Donne au moins deux lieux ou objets.\n4. Explique en quelques phrases pourquoi les symboles sont visibles partout, et ce qu'ils disent des citoyens.","bareme":[{"critere":"Correction justifiée des quatre erreurs","points":8},{"critere":"Explication du jeu de mots gallus","points":3},{"critere":"Lieux où l'on voit la devise et Marianne","points":3},{"critere":"Rôle des symboles : communauté politique et rappel quotidien","points":6}],"dureeMin":16,"corrige":"1. Les corrections :\n- Le coq gaulois n'est **pas officiel** : c'est un symbole plus ancien et **non officiel**, qu'on voit surtout dans le sport.\n- La devise n'a pas été inventée en 1950 : elle est **apparue pendant la Révolution** et est devenue **officielle sous la Troisième République**.\n- Le 14 Juillet ne rappelle pas seulement la prise de la Bastille (1789) : il commémore **aussi la Fête de la Fédération** (1790), qui célébrait l'unité de la Nation.\n- Un symbole **n'est pas une décoration** : c'est un **raccourci qui rappelle une histoire commune**.\n2. Le lien vient d'un **jeu de mots latin** : le mot *gallus* signifie à la fois **« coq »** et **« gaulois »**.\n3. La devise est **gravée au fronton des mairies et des écoles**. Marianne se trouve **dans toutes les mairies** et **sur les timbres**.\n4. Les symboles disent qu'**au-delà de leurs différences**, les citoyens appartiennent à une **même communauté politique**. Ils sont visibles partout (bâtiments publics, mairies, écoles, timbres) **précisément pour être un rappel quotidien** de cette appartenance et de l'histoire commune."}$exo$::jsonb),
  ('fcdb2e20-7248-5c26-b40a-566f95c96d13'::uuid, 1, 'redaction', $exo${"titre":"Les trois mots de la devise","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Cite trois libertés dont dispose chaque personne.\n2. Complète et explique la phrase : « La liberté des uns s'arrête… »\n3. Que signifie être **égaux devant la loi** ?\n4. Définis la **fraternité** avec tes mots.","bareme":[{"critere":"Trois libertés citées","points":4},{"critere":"Limite de la liberté complétée et expliquée","points":5},{"critere":"Sens de l'égalité devant la loi","points":6},{"critere":"Définition de la fraternité","points":5}],"dureeMin":7,"corrige":"1. Par exemple : la liberté de **penser**, de **croire**, de **s'exprimer**, de **circuler**, de **se réunir** (trois suffisent).\n2. « La liberté des uns s'arrête **où commence celle des autres**. » Cela veut dire qu'on ne peut pas utiliser sa liberté pour nuire aux autres.\n3. Tous les citoyens ont **les mêmes droits, les mêmes devoirs et la même justice**, quels que soient leur origine, leur religion, leur sexe ou leur fortune.\n4. La fraternité est le **lien qui fait qu'on se sent concerné par les autres** : l'entraide, la solidarité, le refus de laisser quelqu'un de côté."}$exo$::jsonb),
  ('fcdb2e20-7248-5c26-b40a-566f95c96d13'::uuid, 2, 'redaction', $exo${"titre":"La devise dans la vie du collège","consigne":"Pour chaque situation, indique la valeur de la devise concernée et explique ta réponse en une ou deux phrases.","enonce":"**Situations**\n\n- **A.** Pendant une heure de vie de classe, Emma donne son avis sur le règlement, même s'il n'est pas celui de la majorité.\n- **B.** Le même barème de notation est appliqué à tous les élèves de la classe.\n- **C.** Karim reste avec un camarade qui mange seul à la cantine depuis la rentrée.\n- **D.** Sur un groupe de discussion, Léo insulte une élève et répond : « J'ai le droit, c'est la liberté d'expression ! »\n\n1. Pour les situations A, B et C, nomme la valeur de la devise mise en pratique et justifie.\n2. Situation D : Léo a-t-il raison ? Explique quelles sont les limites de la liberté d'expression et qui les fixe.","bareme":[{"critere":"Situation A : liberté d'expression identifiée et justifiée","points":4},{"critere":"Situation B : égalité de traitement identifiée et justifiée","points":4},{"critere":"Situation C : fraternité identifiée et justifiée","points":4},{"critere":"Situation D : limites de la liberté d'expression fixées par la loi","points":8}],"dureeMin":11,"corrige":"1.\n- **A** : la **liberté**. Emma utilise sa liberté de **s'exprimer** et de donner son avis.\n- **B** : l'**égalité**. Tous les élèves sont traités de la même manière, avec les mêmes règles : c'est l'égalité de traitement entre élèves.\n- **C** : la **fraternité**. Karim se sent concerné par son camarade et refuse de le laisser de côté : c'est de l'entraide.\n2. Non, Léo a tort. La liberté des uns s'arrête où commence celle des autres. Au nom de la liberté d'expression, on ne peut **ni insulter, ni menacer, ni diffamer, ni appeler à la haine**. Ces limites sont **fixées par la loi**."}$exo$::jsonb),
  ('fcdb2e20-7248-5c26-b40a-566f95c96d13'::uuid, 3, 'redaction', $exo${"titre":"Égalité, équité et fraternité : tenir les trois ensemble","consigne":"Analyse le dialogue puis réponds aux questions en argumentant avec les notions du cours.","enonce":"**Document – Un dialogue en classe**\n\n> **Jules** : « Ce n'est pas juste ! Lina, qui est dyslexique, a eu dix minutes de plus pour le contrôle. L'égalité, c'est que tout le monde ait exactement la même chose. »\n>\n> **Lina** : « Moi, je ne demande pas un privilège. »\n>\n> **Maël** : « Et puis l'égalité, ça voudrait dire qu'on doit tous être pareils ? »\n\n1. Définis l'**équité** avec le cours.\n2. Réponds à Jules : le temps supplémentaire de Lina est-il un privilège ? Explique.\n3. Réponds à Maël : que ne veut **pas** dire le mot égalité ? Utilise l'exemple de l'école gratuite.\n4. Explique ce que produirait une liberté totale, puis une égalité absolue, et le rôle de la fraternité entre les deux.\n5. La fraternité s'impose-t-elle par la loi ? Nuance ta réponse avec un exemple tiré du droit.","bareme":[{"critere":"Définition de l'équité","points":3},{"critere":"Réponse argumentée sur le temps supplémentaire","points":5},{"critere":"Égalité n'est ni identité ni égalité des situations","points":4},{"critere":"Liberté totale, égalité absolue et rôle de la fraternité","points":5},{"critere":"La fraternité et la non-assistance à personne en danger","points":3}],"dureeMin":18,"corrige":"1. L'équité, c'est reconnaître que **traiter également des personnes en situation inégale ne suffit pas** : il faut parfois donner plus à ceux qui partent avec une difficulté.\n2. Non, ce n'est **pas un privilège**. La dyslexie met Lina en situation inégale devant un contrôle écrit. Le temps supplémentaire **rétablit l'égalité réelle** : il lui permet de montrer ce qu'elle sait, comme les autres.\n3. **L'égalité ne veut pas dire identité** : les gens restent différents. Elle ne veut pas dire non plus **égalité des situations** : l'**école gratuite** existe justement parce que les familles ne sont pas également riches. L'égalité, c'est être **égaux devant la loi** (mêmes droits, mêmes devoirs).\n4. Une **liberté totale**, seule, **creuse les écarts** entre les personnes. Une **égalité absolue**, seule, **supprime les choix**. Liberté et égalité peuvent donc s'opposer : la **fraternité** est ce qui permet de **tenir les deux ensemble**, parce qu'on se sent concerné par les autres.\n5. La fraternité est **la seule des trois qui ne s'impose pas par la loi** : elle se pratique. Elle est pourtant inscrite dans le droit : la **non-assistance à personne en danger est un délit**."}$exo$::jsonb),
  ('ebc93d31-f95a-5be1-a7e6-27c3575ae336'::uuid, 1, 'redaction', $exo${"titre":"Ce que garantit la laïcité","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Cite les **trois garanties** de la laïcité et explique chacune en quelques mots.\n2. Quelle loi de **1905** est à la base de la laïcité ? Donne deux choses qu'elle prévoit.","bareme":[{"critere":"Les trois garanties nommées et expliquées","points":12},{"critere":"La loi de 1905 et son contenu","points":8}],"dureeMin":6,"corrige":"1. La laïcité garantit :\n- la **liberté de conscience** : chacun peut croire, ne pas croire ou changer d'avis ;\n- la **séparation** entre l'État et les religions ;\n- l'**égalité** de tous devant la loi, quelle que soit la croyance.\n2. C'est la loi de **séparation des Églises et de l'État** (1905). Elle **met fin au financement public des cultes** et **garantit le libre exercice** de chacun."}$exo$::jsonb),
  ('ebc93d31-f95a-5be1-a7e6-27c3575ae336'::uuid, 2, 'redaction', $exo${"titre":"La laïcité au quotidien à l'école publique","consigne":"Lis chaque situation et explique, en t'appuyant sur le cours, si elle respecte la laïcité à l'école publique.","enonce":"**Situations dans un collège public**\n\n- **A.** Un professeur de mathématiques explique à ses élèves quelle religion il pratique et leur conseille de la suivre.\n- **B.** Une famille demande que son enfant ne suive pas un cours d'histoire à cause de ses croyances.\n- **C.** Un élève dit en classe qu'il ne croit en aucune religion ; une camarade dit qu'elle est croyante.\n- **D.** Le professeur de français fait étudier un récit tiré d'un texte religieux ancien.\n\n1. Pour chaque situation, dis si elle est conforme ou non à la laïcité, et justifie.\n2. Quelle règle la loi du 15 mars 2004 fixe-t-elle pour les élèves ?","bareme":[{"critere":"Situation A : neutralité des enseignants","points":4},{"critere":"Situation B : mêmes programmes pour tous","points":4},{"critere":"Situations C et D : liberté de conscience et étude des religions","points":7},{"critere":"Contenu de la loi de 2004","points":5}],"dureeMin":11,"corrige":"1.\n- **A** : **non conforme**. Les enseignants sont des **agents de l'État** : ils doivent une **stricte neutralité** et ne peuvent pas promouvoir une croyance.\n- **B** : **non conforme**. Les **programmes sont les mêmes pour tous** : il n'y a **pas de dispense au nom d'une croyance**.\n- **C** : **conforme**. La **liberté de conscience** permet de croire ou de ne pas croire ; les élèves sont libres de leurs convictions.\n- **D** : **conforme**. **Parler des religions en cours est prévu par les programmes** (en histoire, en français, en arts). **Connaître** les religions est un savoir ; les **pratiquer** est un choix privé.\n2. La loi du **15 mars 2004** **interdit les signes religieux ostensibles** dans les écoles, collèges et lycées publics. Les élèves restent libres de croire."}$exo$::jsonb),
  ('ebc93d31-f95a-5be1-a7e6-27c3575ae336'::uuid, 3, 'redaction', $exo${"titre":"Corriger des idées fausses sur la laïcité","consigne":"Analyse les affirmations du document, montre qu'elles sont fausses, puis explique pourquoi la laïcité compte particulièrement à l'école.","enonce":"**Document – Ce qu'on entend dans la cour**\n\n> **Affirmation 1** : « La laïcité, c'est être contre les religions. »\n>\n> **Affirmation 2** : « Dans une école laïque, on n'a pas le droit de parler de religion en classe. »\n>\n> **Affirmation 3** : « L'État devrait payer pour toutes les religions, comme ça c'est égal. »\n\n1. Montre, pour chaque affirmation, pourquoi elle est fausse, en utilisant le cours.\n2. Explique la phrase : « C'est parce que l'État ne croit rien qu'il peut accueillir tout le monde. »\n3. Pourquoi l'école est-elle un lieu important pour la laïcité ? Explique l'idée de ne pas voir un élève comme le représentant d'un groupe.\n4. Quel document, créé en 2013, rappelle ces principes dans les établissements ? Combien d'articles compte-t-il ?","bareme":[{"critere":"Réfutation des trois affirmations avec le cours","points":9},{"critere":"Explication de la neutralité de l'État","points":4},{"critere":"Rôle particulier de l'école","points":4},{"critere":"La Charte de la laïcité de 2013","points":3}],"dureeMin":17,"corrige":"1.\n- **Affirmation 1** : faux. La laïcité **n'est pas l'interdiction des religions**, ni une opinion contre elles. L'État ne se mêle pas des croyances : il **ne les impose pas** et **ne les combat pas**. Elle garantit au contraire la **liberté de conscience**.\n- **Affirmation 2** : faux. **Parler des religions en cours est prévu par les programmes**, en histoire, en français, en arts. Les connaître est un **savoir** ; les pratiquer est un **choix privé**.\n- **Affirmation 3** : faux. Depuis la loi de **1905**, l'État **ne finance aucun culte** : la loi a mis fin au financement public des cultes. L'égalité, c'est que tous soient égaux devant la loi quelle que soit leur croyance.\n2. L'État reste **neutre** : il ne choisit aucune croyance. Ainsi, aucun citoyen n'est favorisé ou rejeté à cause de ce qu'il croit ou ne croit pas : **tout le monde peut y trouver sa place**. La laïcité ne demande à personne de renoncer à ce qu'il croit.\n3. L'école est le lieu où l'on **apprend ensemble, avant de choisir**. En mettant les croyances à distance dans la classe, on fait en sorte qu'**aucun élève ne soit d'abord vu comme le représentant d'un groupe** : il est vu comme un élève parmi les autres.\n4. C'est la **Charte de la laïcité**, affichée dans tous les établissements depuis **2013**. Elle compte **15 articles**."}$exo$::jsonb),
  ('ac90145b-f5e8-5758-a693-20adf8c54b69'::uuid, 1, 'redaction', $exo${"titre":"Respect, dignité, stéréotype et préjugé","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Qu'est-ce que respecter quelqu'un ? Respecter, est-ce forcément être d'accord avec lui ?\n2. Complète et explique : « La dignité ne se mérite pas et… »\n3. Définis un **stéréotype** et un **préjugé**.","bareme":[{"critere":"Définition du respect","points":6},{"critere":"La dignité : phrase complétée et expliquée","points":6},{"critere":"Définitions du stéréotype et du préjugé","points":8}],"dureeMin":7,"corrige":"1. Respecter quelqu'un, c'est **reconnaître qu'il a la même valeur que soi**, même s'il ne pense pas, ne croit pas ou ne vit pas comme soi. Ce n'est **pas forcément être d'accord** avec lui : c'est **refuser de le rabaisser**.\n2. « La dignité ne se mérite pas et **ne se perd pas**. » Elle ne dépend ni des notes, ni de l'argent, ni de l'apparence, ni de l'origine.\n3. Un **stéréotype** est une **idée toute faite sur un groupe** (ex. « les filles sont… »). Un **préjugé** est un **jugement porté avant de connaître** la personne."}$exo$::jsonb),
  ('ac90145b-f5e8-5758-a693-20adf8c54b69'::uuid, 2, 'redaction', $exo${"titre":"Accueillir un nouvel élève","consigne":"Lis la situation, puis réponds aux questions en rédigeant des phrases complètes.","enonce":"**Situation**\n\n> Samir arrive en cours d'année dans la classe. Avant même de lui parler, Enzo déclare : « Il a l'air bizarre, il ne sera pas sympa. » Plus tard, Enzo lui donne un surnom sans lui demander son avis, et plusieurs élèves se moquent de lui en le coupant quand il parle.\n\n1. La phrase d'Enzo est-elle un stéréotype ou un préjugé ? Justifie.\n2. Pourquoi ce genre de jugement fait-il mal ? Explique avec le cours.\n3. Relève dans la situation deux comportements contraires au respect, puis propose, dans l'ordre du cours, les quatre gestes du respect en actes.","bareme":[{"critere":"Identification du préjugé avec justification","points":5},{"critere":"Explication du mal causé par le préjugé","points":5},{"critere":"Deux comportements irrespectueux relevés","points":4},{"critere":"Les quatre gestes du respect en actes","points":6}],"dureeMin":10,"corrige":"1. C'est un **préjugé** : Enzo porte un **jugement avant de connaître** Samir. Ce n'est pas une idée toute faite sur un groupe entier.\n2. Les préjugés se répandent **sans preuve**. Ils font mal parce qu'ils traitent une personne comme un **exemplaire de son groupe**, sans la connaître. On ne choisit pas d'avoir des préjugés, mais on peut choisir de les **vérifier** avant d'agir dessus.\n3. Comportements contraires au respect : **surnommer Samir sans son accord** ; **se moquer de lui** ; **le couper quand il parle**.\nLes gestes du respect : **écouter sans couper** → **ne pas se moquer** → **ne pas surnommer sans accord** → **s'excuser quand on a blessé**. Le respect n'est pas une intention : c'est une suite de gestes qui se voient."}$exo$::jsonb),
  ('ac90145b-f5e8-5758-a693-20adf8c54b69'::uuid, 3, 'redaction', $exo${"titre":"De la différence à la discrimination","consigne":"Analyse le document puis réponds aux questions en argumentant avec les notions du cours.","enonce":"**Document – Une affiche de club**\n\n> Un club de loisirs affiche : « Inscriptions refusées aux personnes en situation de handicap. » Un adhérent explique : « C'est normal, on veut un groupe où tout le monde est pareil. »\n\n1. Définis la **discrimination**. Le refus du club en est-il une ? Justifie.\n2. Que dit la loi sur la discrimination ? Est-ce seulement une question de politesse ?\n3. Réponds à l'adhérent : un groupe où tout le monde est identique peut-il exister ? Quelle est la vraie question à se poser ?\n4. Explique pourquoi la **dignité** est le fondement de tous les droits, et pourquoi une personne en situation de handicap a la même dignité que les autres.","bareme":[{"critere":"Définition de la discrimination appliquée au document","points":5},{"critere":"La discrimination est un délit interdit par la loi","points":4},{"critere":"Les différences sont normales : réponse argumentée","points":5},{"critere":"La dignité comme fondement des droits","points":4},{"critere":"Rédaction et justification","points":2}],"dureeMin":16,"corrige":"1. La **discrimination**, c'est **traiter quelqu'un moins bien à cause de son origine, son sexe, sa religion, son handicap ou son apparence**. Oui, le refus du club en est une : il écarte des personnes **à cause de leur handicap**.\n2. La discrimination n'est pas seulement impolie : elle est **interdite par la loi**, c'est un **délit**.\n3. Non. Les différences (origine, religion ou absence de religion, famille, santé, handicap, goûts) sont **normales**, et **un groupe où tout le monde serait identique n'existe pas**. La vraie question n'est donc jamais « faut-il des différences ? », mais **« comment vit-on avec ? »**.\n4. La dignité **ne se mérite pas et ne se perd pas** : elle ne dépend ni des notes, ni de l'argent, ni de l'apparence, ni de l'origine, ni de la santé. C'est le **fondement de tous les droits** : si la dignité se méritait, **les droits pourraient se retirer**. Une personne en situation de handicap a donc exactement la même dignité, et les mêmes droits, que les autres."}$exo$::jsonb),
  ('0165dc05-4a53-5233-b1a2-4a0dbe4ac780'::uuid, 1, 'redaction', $exo${"titre":"Définir le harcèlement","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Donne la définition du harcèlement.\n2. Cite les **trois éléments** qui le caractérisent.\n3. Nomme trois **formes** de harcèlement et donne un exemple pour chacune.","bareme":[{"critere":"Définition du harcèlement","points":5},{"critere":"Les trois critères du harcèlement","points":9},{"critere":"Trois formes avec un exemple chacune","points":6}],"dureeMin":7,"corrige":"1. Le harcèlement est une **violence répétée**, exercée contre quelqu'un **qui ne peut pas se défendre**.\n2. Les trois éléments : la **répétition** ; l'**intention de nuire** ; le **déséquilibre de force** (en nombre, en popularité ou en âge).\n3. Par exemple (trois au choix) :\n- **verbale** : moqueries, insultes, surnoms ;\n- **sociale** : mise à l'écart, rumeurs ;\n- **matérielle** : vol ou dégradation d'affaires ;\n- **physique** : coups, bousculades ;\n- **cyber** : messages, photos, comptes créés pour nuire."}$exo$::jsonb),
  ('0165dc05-4a53-5233-b1a2-4a0dbe4ac780'::uuid, 2, 'redaction', $exo${"titre":"Harcèlement ou pas ?","consigne":"Analyse chaque situation avec les trois critères du cours, puis réponds aux questions.","enonce":"**Situations**\n\n- **A.** Lucie et Manon, deux amies de la même classe, se disputent une fois à propos d'un jeu, puis se réconcilient le lendemain.\n- **B.** Depuis un mois, un groupe de cinq élèves de 4e cache chaque jour le sac de Théo, un élève de 6e, et rit quand il le cherche.\n\n1. Pour chaque situation, vérifie les trois critères du harcèlement et conclus.\n2. Dans la situation B, quelle forme de harcèlement reconnais-tu ?\n3. Théo veut appeler un numéro gratuit et anonyme pour le harcèlement. Lequel ? Quel autre numéro existe pour l'enfance en danger ?","bareme":[{"critere":"Situation A analysée avec les trois critères","points":6},{"critere":"Situation B analysée avec les trois critères","points":7},{"critere":"Forme matérielle identifiée","points":3},{"critere":"Numéros 3018 et 119","points":4}],"dureeMin":11,"corrige":"1.\n- **A** : il n'y a **pas de répétition** (une seule dispute), **pas de déséquilibre** (deux élèves **à égalité**), et rien n'indique une intention durable de nuire. Ce **n'est pas du harcèlement**, c'est une dispute.\n- **B** : il y a **répétition** (chaque jour depuis un mois), **intention de nuire** (ils cachent le sac et se moquent de lui), et **déséquilibre de force** (un groupe de cinq contre un seul, des élèves plus âgés). Les trois critères sont réunis : **c'est du harcèlement**.\n2. C'est une forme **matérielle** (on s'en prend à ses affaires), avec aussi une part **verbale** ou de moquerie quand le groupe rit de lui.\n3. Le **3018** (harcèlement et cyberharcèlement, gratuit et anonyme). Le **119** est le numéro de l'**enfance en danger**."}$exo$::jsonb),
  ('0165dc05-4a53-5233-b1a2-4a0dbe4ac780'::uuid, 3, 'redaction', $exo${"titre":"Une photo qui circule : le rôle des témoins","consigne":"Analyse la situation puis réponds aux questions en justifiant avec le cours.","enonce":"**Situation**\n\n> Une photo gênante de Chloé circule sur le groupe de discussion de la classe. Chaque soir, de nouveaux messages moqueurs sont ajoutés. Plusieurs élèves envoient des émojis qui rient ; d'autres lisent sans rien dire. Un élève pense : « Si je préviens un adulte, je vais passer pour un rapporteur. » L'auteur de la photo, lui, est sûr qu'on ne le retrouvera jamais derrière son écran.\n\n1. Donne **trois raisons** pour lesquelles le cyberharcèlement est particulièrement grave, en les reliant à la situation.\n2. L'auteur de la photo a-t-il raison de se croire protégé ? Explique.\n3. Quel est le rôle des élèves qui rient, et de ceux qui ne disent rien ? Explique pourquoi les témoins peuvent tout faire basculer.\n4. Réponds à l'élève qui a peur d'être un « rapporteur ».\n5. Donne, dans l'ordre, les quatre choses que Chloé ou un témoin peut faire. Que dit la loi depuis 2022 ?","bareme":[{"critere":"Trois raisons de la gravité du cyberharcèlement reliées à la situation","points":5},{"critere":"L'adresse IP s'identifie","points":2},{"critere":"Rôle des témoins analysé","points":5},{"critere":"Distinction signaler / rapporter","points":3},{"critere":"Les quatre actions et la loi de 2022","points":5}],"dureeMin":18,"corrige":"1. Le cyberharcèlement est pire parce que :\n- **il ne s'arrête pas à la grille** : il suit Chloé **chez elle, la nuit** (les messages arrivent chaque soir) ;\n- **les traces restent** : la photo peut être **rediffusée indéfiniment** ;\n- **l'écran** donne au harceleur l'impression d'être protégé, ce qui l'encourage.\n2. Non. Il se croit protégé par l'écran, mais **une adresse IP s'identifie** : on peut le retrouver.\n3. Les élèves qui rient **encouragent** le harcèlement : ils forment un public. Ceux qui ne disent rien ne sont pas neutres : **ne rien faire, c'est déjà choisir un camp**. Les témoins font tout basculer : **un groupe qui refuse arrête** le harcèlement, qui s'effondre presque toujours quand les témoins cessent d'être un public. Et Chloé ne « l'a pas cherché » : **personne ne mérite d'être harcelé**.\n4. **Signaler n'est pas rapporter.** Rapporter, c'est chercher à nuire à quelqu'un ; **signaler, c'est protéger** Chloé.\n5. **En parler à un adulte** → **conserver les preuves** (captures d'écran) → **ne pas répondre aux provocations** → **bloquer**. On peut aussi appeler le **3018**. Depuis **2022**, le harcèlement scolaire est un **délit puni par la loi, y compris pour les mineurs**."}$exo$::jsonb),
  ('fe11dd4d-cfdf-5a34-8513-38a2d70c829d'::uuid, 1, 'redaction', $exo${"titre":"Égalité filles-garçons : le principe","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Quels droits ont les filles et les garçons ? Où ce principe est-il inscrit ?\n2. Définis le **sexisme** et donne un exemple.\n3. Qu'est-ce que le **consentement** ? Donne ses caractéristiques.","bareme":[{"critere":"Principe d'égalité et textes qui l'inscrivent","points":7},{"critere":"Définition du sexisme avec un exemple","points":6},{"critere":"Le consentement et ses caractéristiques","points":7}],"dureeMin":7,"corrige":"1. Filles et garçons ont **les mêmes droits** : même école, mêmes matières, mêmes métiers possibles, même liberté de choisir. Ce principe est inscrit dans la **Constitution** et dans la **loi**.\n2. Le **sexisme**, c'est **traiter quelqu'un moins bien, ou le juger, à cause de son sexe**. Exemples : une blague rabaissante, une remarque sur le corps, une insulte genrée.\n3. Le **consentement**, c'est l'**accord** d'une personne. Personne n'a le droit de toucher quelqu'un sans son accord. Le consentement est **libre**, **clair**, et peut être **retiré à tout moment**, à tout âge et dans toutes les situations."}$exo$::jsonb),
  ('fe11dd4d-cfdf-5a34-8513-38a2d70c829d'::uuid, 2, 'redaction', $exo${"titre":"Repérer les obstacles à l'égalité au collège","consigne":"Lis les situations, identifie l'obstacle à l'égalité dans chacune, puis propose une manière d'agir.","enonce":"**Situations**\n\n- **A.** Jade adore les maths, mais un camarade lui dit : « Laisse tomber, les maths c'est pour les garçons. »\n- **B.** À chaque récréation, le terrain central de la cour est occupé par un groupe de garçons ; les filles restent sur les côtés.\n- **C.** Sur le groupe de la classe, une blague sexiste sur une élève circule et beaucoup rient.\n\n1. Pour les situations A et B, nomme l'obstacle à l'égalité et explique comment il agit.\n2. Pourquoi l'obstacle de la situation A peut-il avoir des conséquences importantes sur l'avenir de Jade ?\n3. Situation C : est-ce une simple maladresse ? Donne, dans l'ordre, les quatre manières d'agir vues en cours.","bareme":[{"critere":"Obstacles des situations A et B identifiés et expliqués","points":7},{"critere":"Conséquence des stéréotypes sur les choix d'études","points":4},{"critere":"La blague sexiste est une atteinte","points":3},{"critere":"Les quatre manières d'agir","points":6}],"dureeMin":11,"corrige":"1.\n- **A** : un **stéréotype**. « Les maths, c'est pour les garçons » n'est fondé sur rien, mais cette idée peut décourager Jade.\n- **B** : le **partage de l'espace**. Dans une cour de récréation, le terrain central est le plus souvent occupé par des garçons, et les filles en sont écartées.\n2. Rien ne fonde ces stéréotypes, et pourtant **ils orientent des choix d'études dès 15 ans** : Jade pourrait renoncer à une voie qu'elle aime, alors qu'elle a **la même liberté de choisir** que les garçons.\n3. Non. Les blagues rabaissantes **ne sont pas des maladresses : ce sont des atteintes**. Pour agir : **ne pas rire d'une blague sexiste** → **ne pas relayer une image** → **dire quand ce n'est pas normal** → **en parler à un adulte**."}$exo$::jsonb),
  ('fe11dd4d-cfdf-5a34-8513-38a2d70c829d'::uuid, 3, 'redaction', $exo${"titre":"Entre la loi et la réalité : l'égalité au travail","consigne":"Analyse le document puis réponds aux questions en argumentant avec les notions du cours.","enonce":"**Document – Une discussion en famille**\n\n> **Paul** : « L'égalité entre les femmes et les hommes, c'est réglé ! Il y a une loi depuis 1972, donc on n'a plus besoin d'en parler. »\n>\n> **Sa sœur Alice** : « Pourtant, dans l'entreprise de maman, les postes de direction sont presque tous occupés par des hommes. »\n\n1. Que prévoit la loi de 1972 ?\n2. Paul a-t-il raison de dire que tout est réglé ? Explique la situation actuelle dans le monde du travail en utilisant l'exemple d'Alice.\n3. Explique la phrase du cours : « Un droit inscrit dans la loi n'est pas encore une réalité dans les faits. » Pourquoi continue-t-on d'en parler ?\n4. Montre, avec un exemple, comment les stéréotypes vus en cours peuvent contribuer à ces inégalités, dès le collège.","bareme":[{"critere":"Contenu de la loi de 1972","points":3},{"critere":"Égalité salariale non atteinte et accès aux postes de direction","points":6},{"critere":"Distinction entre droit et réalité","points":5},{"critere":"Lien entre stéréotypes et inégalités","points":4},{"critere":"Rédaction et argumentation","points":2}],"dureeMin":16,"corrige":"1. Depuis **1972**, la loi **impose l'égalité salariale** en France : à travail égal, salaire égal.\n2. Non, Paul a tort. L'égalité salariale **n'est toujours pas atteinte** : **à travail comparable, les femmes gagnent encore moins**, et **les postes de direction leur sont moins ouverts**. L'exemple d'Alice le montre : dans l'entreprise de sa mère, les postes de direction sont presque tous occupés par des hommes.\n3. Une loi fixe un **droit**, mais cela ne suffit pas à changer tout de suite les **habitudes** et les **comportements**. Il y a un écart entre ce que dit la loi et ce qui se passe réellement. **C'est justement pour cela qu'on continue d'en parler** : pour que ce droit devienne une réalité.\n4. Par exemple, le stéréotype « **les maths, c'est pour les garçons** » ou « **le soin, c'est pour les filles** » n'est fondé sur rien, mais il **oriente des choix d'études à 15 ans**. Des filles peuvent alors renoncer à certaines études ou à certains métiers, ce qui entretient les inégalités plus tard dans le monde du travail."}$exo$::jsonb),
  ('6aa853fb-a3a8-5790-b22e-1ffedca7aeee'::uuid, 1, 'redaction', $exo${"titre":"Les littoraux : un espace très peuplé","consigne":"Réponds à chaque question par une ou deux phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Quelle part de l’humanité vit à moins de 100 km d’une côte ?\n2. Comment appelle-t-on ce mouvement de concentration des hommes et des activités vers les côtes ? Donne sa définition.\n3. Cite les deux grands types de littoraux étudiés et donne un exemple de lieu pour chacun.","bareme":[{"critere":"Part de l’humanité vivant près des côtes","points":5},{"critere":"Mot littoralisation et sa définition","points":7},{"critere":"Deux types de littoraux avec un exemple chacun","points":8}],"dureeMin":6,"corrige":"1. Environ **60 %** de l’humanité (six humains sur dix) vit à moins de 100 km d’une côte.\n\n2. Ce mouvement s’appelle la **littoralisation** : c’est la concentration de la population et des activités sur les littoraux.\n\n3. Les deux grands types sont :\n- le **littoral industrialo-portuaire** (ports en eau profonde, terminaux à conteneurs, raffineries, ZIP), par exemple **Shanghai**, premier port mondial (ou Rotterdam, Singapour, Le Havre) ;\n- le **littoral touristique** (hôtels, résidences, marinas, plages équipées), par exemple la **Côte d’Azur** (ou les Baléares, Cancún, Bali)."}$exo$::jsonb),
  ('6aa853fb-a3a8-5790-b22e-1ffedca7aeee'::uuid, 2, 'redaction', $exo${"titre":"Étudier une station balnéaire","consigne":"Lis le document puis réponds aux questions en phrases complètes, en t’appuyant sur le texte et sur le cours.","enonce":"**Document — Une station balnéaire au bord de la Méditerranée (texte imaginé)**\n\n> « L’été, la ville déborde de vacanciers. Le long de la plage équipée, les hôtels et les résidences se succèdent sans interruption, et la marina est pleine de bateaux de plaisance. Un petit aéroport accueille les vols venus de toute l’Europe. Mais dès octobre, beaucoup d’hôtels et de restaurants ferment, et les serveurs, les maîtres-nageurs et les vendeurs doivent chercher un autre travail. Des habitants regrettent que les dunes aient disparu sous le béton. »\n\n1. De quel type de littoral s’agit-il ? Justifie ta réponse en relevant **trois** aménagements cités dans le texte.\n2. Quel avantage ce littoral apporte-t-il aux habitants ? Quelle est la limite de cet avantage d’après le texte ? Utilise le mot du cours qui convient.\n3. Quel problème les habitants dénoncent-ils à la fin du texte ? Nomme-le avec le mot du cours et explique-le.","bareme":[{"critere":"Identification du littoral touristique justifiée par trois aménagements","points":7},{"critere":"Emplois créés mais saisonniers","points":6},{"critere":"Bétonisation du rivage nommée et expliquée","points":5},{"critere":"Rédaction en phrases complètes","points":2}],"dureeMin":10,"corrige":"1. Il s’agit d’un **littoral touristique**. Le texte cite des **hôtels et des résidences**, une **plage équipée**, une **marina** et un **aéroport** (trois suffisent).\n\n2. Le tourisme **crée des emplois** (serveurs, maîtres-nageurs, vendeurs). Mais ces emplois sont souvent **saisonniers** : ils n’existent que pendant l’été, et dès octobre les travailleurs doivent chercher un autre emploi.\n\n3. Les habitants dénoncent la **bétonisation** du rivage : les constructions (hôtels, résidences) ont recouvert le bord de mer et fait disparaître les milieux naturels comme les dunes."}$exo$::jsonb),
  ('6aa853fb-a3a8-5790-b22e-1ffedca7aeee'::uuid, 3, 'redaction', $exo${"titre":"Un littoral convoité et fragile : usages, menaces et protections","consigne":"Réponds aux questions en rédigeant des phrases complètes. Pour la dernière question, rédige un petit paragraphe argumenté.","enonce":"**Document — Une phrase du cours**\n\n> « Un littoral est une ligne : ce qu’on y ajoute d’un côté se retire presque toujours de l’autre. »\n\n1. En dehors de l’industrie et du tourisme, cite **trois** autres usages du littoral. Explique pourquoi ces usages entrent souvent en **concurrence**.\n2. Environ quelle part des marchandises mondiales voyage par la mer ? Explique pourquoi cela rend les littoraux industrialo-portuaires si importants.\n3. Choisis **deux** fragilités des littoraux et explique pour chacune ce qu’elle produit.\n4. Explique la phrase du document à l’aide d’un exemple tiré du cours.\n5. Présente **deux** moyens de protéger les littoraux. Explique pourquoi les **mangroves** sont précieuses.","bareme":[{"critere":"Trois autres usages et explication de leur concurrence","points":4},{"critere":"Part des marchandises par mer et rôle des ports","points":3},{"critere":"Deux fragilités expliquées","points":4},{"critere":"Explication argumentée de la phrase du document avec un exemple","points":5},{"critere":"Deux moyens de protection et rôle des mangroves","points":4}],"dureeMin":18,"corrige":"1. Autres usages : la **pêche**, l’**aquaculture**, les **énergies marines**, l’**extraction de granulats**, la **conservation de la nature** (trois suffisent). Ils se concurrencent parce que le littoral est un **espace étroit** : ce qui est occupé par une activité ne peut pas l’être par une autre. C’est le principal enjeu d’aménagement du littoral.\n\n2. Environ **80 %** des marchandises mondiales voyagent par la mer. Les ports (ports en eau profonde, terminaux à conteneurs) sont donc indispensables au commerce mondial, comme **Shanghai**, premier port mondial.\n\n3. Exemples attendus (deux au choix) :\n- l’**érosion** du trait de côte, qui fait reculer le rivage et est aggravée par les aménagements eux-mêmes ;\n- les **pollutions** : marées noires, plastiques, rejets urbains et agricoles ;\n- la destruction des **milieux** : mangroves, dunes, zones humides ;\n- la **montée du niveau de la mer**, qui menace des dizaines de millions de personnes ;\n- la **submersion** lors des tempêtes et des cyclones.\n\n4. Le littoral est très étroit : quand on y **ajoute** des constructions (hôtels, ports, résidences), on **retire** autre chose, par exemple des dunes, des zones humides ou des mangroves. La **bétonisation** fait disparaître les milieux naturels, et les aménagements **aggravent l’érosion** : on gagne des équipements mais on perd la protection naturelle de la côte.\n\n5. Moyens de protection (deux au choix) : la **loi Littoral** en France, le **Conservatoire du littoral**, les **aires marines protégées**, le **réensablement**, la **restauration des dunes et des mangroves**. Les mangroves sont précieuses car elles sont **les meilleures protections naturelles contre les tempêtes**."}$exo$::jsonb),
  ('f6af420e-b05d-5f7f-9d41-10c5c568fbeb'::uuid, 1, 'redaction', $exo${"titre":"Densité et contraintes naturelles","consigne":"Réponds à chaque question par une ou deux phrases complètes en utilisant le vocabulaire du cours.","enonce":"1. Définis la **densité de population**.\n2. Qu’est-ce qu’un espace de **faible densité** ? Donne l’ordre de grandeur indiqué dans le cours.\n3. Cite **deux** grandes contraintes naturelles et, pour chacune, un lieu où on la rencontre.","bareme":[{"critere":"Définition de la densité de population","points":6},{"critere":"Espace de faible densité et ordre de grandeur","points":6},{"critere":"Deux contraintes localisées","points":8}],"dureeMin":6,"corrige":"1. La **densité de population** est le **nombre d’habitants par km²**.\n\n2. Un espace de faible densité compte **peu d’habitants par km²** : moins de **30 hab./km²** environ.\n\n3. Deux contraintes au choix :\n- le **froid** : Sibérie, Grand Nord canadien, Groenland ;\n- la **sécheresse** : Sahara, Australie centrale, Atacama ;\n- l’**altitude** : Himalaya, Andes ;\n- la **forêt dense** : Amazonie, bassin du Congo."}$exo$::jsonb),
  ('f6af420e-b05d-5f7f-9d41-10c5c568fbeb'::uuid, 2, 'redaction', $exo${"titre":"Trois sociétés face à leur milieu","consigne":"Pour chaque situation, identifie la contrainte naturelle et explique la réponse humaine, en phrases complètes.","enonce":"Lis les trois situations (imaginées d’après le cours).\n\n- **Situation A** — Dans un village de l’Himalaya, les champs ressemblent à de grands escaliers taillés dans la montagne.\n- **Situation B** — En plein Sahara, des palmiers et des jardins poussent autour d’un puits très profond.\n- **Situation C** — En Mongolie, une famille déplace ses tentes et ses troupeaux plusieurs fois par an pour trouver de l’herbe.\n\n1. Pour chaque situation, nomme la **contrainte** à laquelle les habitants font face.\n2. Pour chaque situation, nomme la **réponse humaine** (avec le mot du cours) et explique comment elle aide à vivre dans ce milieu.\n3. D’après le cours, pourquoi une contrainte n’est-elle « jamais un obstacle absolu » ?","bareme":[{"critere":"Trois contraintes identifiées","points":6},{"critere":"Trois réponses humaines nommées et expliquées","points":9},{"critere":"Explication de l’idée d’obstacle non absolu","points":5}],"dureeMin":10,"corrige":"1. A : l’**altitude** (pentes fortes). B : la **sécheresse** (le désert, l’eau commande tout). C : des **ressources rares et mobiles** (l’herbe pour les troupeaux).\n\n2. A : les **cultures en terrasses** ; elles retiennent la terre et l’eau sur les pentes et permettent de cultiver.\nB : l’**oasis** avec un **puits profond** ; on va chercher l’eau en profondeur pour cultiver et vivre dans le désert.\nC : le **nomadisme pastoral** ; en se déplaçant, la famille trouve de nouveaux pâturages pour ses bêtes (comme les Mongols, les Touaregs ou les Sames).\n\n3. Parce qu’une contrainte est un **problème auquel une société a répondu**, souvent depuis très longtemps : les hommes s’**adaptent** et inventent des solutions, comme le montrent les terrasses, les oasis ou le nomadisme."}$exo$::jsonb),
  ('f6af420e-b05d-5f7f-9d41-10c5c568fbeb'::uuid, 3, 'redaction', $exo${"titre":"Des espaces à fortes contraintes qui changent","consigne":"Réponds aux questions en phrases complètes, puis rédige un court paragraphe pour la dernière question.","enonce":"**Document — Une phrase du cours**\n\n> « La montagne, longtemps obstacle, est devenue une ressource touristique majeure. Un même trait change de nature selon l’époque. »\n\n1. Explique pourquoi la montagne a longtemps été un **obstacle** (cite deux difficultés du cours).\n2. Explique comment elle est devenue une **ressource**. Quelle est la limite de ce changement ?\n3. Cite **deux** autres changements qui touchent aujourd’hui les espaces à fortes contraintes et donne leur effet.\n4. Explique pourquoi on peut dire que ces milieux subissent une **injustice** face au réchauffement climatique.\n5. En quelques lignes, explique la phrase « Un même trait change de nature selon l’époque ».","bareme":[{"critere":"La montagne comme obstacle : deux difficultés","points":4},{"critere":"La montagne comme ressource et sa limite","points":4},{"critere":"Deux changements actuels et leurs effets","points":4},{"critere":"Injustice face au réchauffement expliquée","points":4},{"critere":"Paragraphe expliquant la phrase du document","points":4}],"dureeMin":16,"corrige":"1. La montagne impose des contraintes : **air raréfié**, **pentes fortes**, **isolement**. Il y est difficile de cultiver et de circuler.\n\n2. Aujourd’hui le **tourisme** apporte des **revenus** aux habitants des montagnes. Mais il a une limite : il **fragilise les milieux**.\n\n3. Deux au choix :\n- l’exploitation des **ressources** (pétrole, minerais, bois), qui provoque des transformations brutales ;\n- le **changement climatique** : fonte du permafrost, recul des glaciers, sécheresses aggravées ;\n- l’**exode des jeunes** : les villages se vident.\n\n4. Ces milieux sont frappés **les premiers** par le réchauffement (fonte du permafrost, recul des glaciers, sécheresses), alors qu’ils y **contribuent le moins**, car ils sont peu peuplés. Ils subissent donc des conséquences dont ils ne sont presque pas responsables.\n\n5. Un même élément du milieu, comme la montagne, n’est pas bon ou mauvais pour toujours : autrefois, ses pentes et son isolement la rendaient difficile à habiter ; aujourd’hui, ses paysages et sa neige attirent les touristes. C’est la **société**, à une **époque** donnée, qui fait d’un trait naturel une contrainte ou un atout."}$exo$::jsonb),
  ('c1adbe71-f57b-5c1e-81f8-5b785feaaf39'::uuid, 1, 'redaction', $exo${"titre":"La biodiversité et ses hauts lieux","consigne":"Réponds à chaque question par une ou deux phrases complètes en utilisant le vocabulaire du cours.","enonce":"1. Définis la **biodiversité**.\n2. Que signifie le mot **endémique** ? Cite le lieu du cours qui compte 80 % d’espèces endémiques.\n3. Cite **deux** autres hauts lieux de la biodiversité et dis ce que chacun abrite.","bareme":[{"critere":"Définition de la biodiversité","points":6},{"critere":"Définition d’endémique et exemple de Madagascar","points":6},{"critere":"Deux hauts lieux et ce qu’ils abritent","points":8}],"dureeMin":6,"corrige":"1. La **biodiversité** est la **variété du vivant** : la diversité des **espèces**, des **gènes** et des **milieux**.\n\n2. Une espèce **endémique** est une espèce **qui ne vit nulle part ailleurs**. **Madagascar** compte 80 % d’espèces endémiques.\n\n3. Deux au choix :\n- l’**Amazonie** abrite environ **10 %** des espèces connues sur Terre ;\n- la **Grande Barrière de corail** (Australie) abrite **1 500** espèces de poissons ;\n- le bassin du **Congo** et **Bornéo** abritent des **forêts denses**."}$exo$::jsonb),
  ('c1adbe71-f57b-5c1e-81f8-5b785feaaf39'::uuid, 2, 'redaction', $exo${"titre":"Une forêt amazonienne menacée","consigne":"Lis le témoignage puis réponds aux questions en phrases complètes, en t’appuyant sur le document et sur le cours.","enonce":"**Document — Témoignage d’un habitant d’Amazonie (texte imaginé)**\n\n> « Mon peuple vit dans cette forêt depuis toujours. Nous chassons selon des règles décidées ensemble, et nous ne brûlons que de petites parcelles pour nos jardins. Mais des chercheurs d’or sont arrivés : les poissons de la rivière sont empoisonnés. Plus au sud, des machines abattent la forêt pour planter du soja et faire paître des troupeaux. »\n\n1. À quel groupe d’habitants appartient l’auteur ? Relève **deux** de ses pratiques et explique pourquoi elles ne détruisent pas la forêt.\n2. Relève **deux** menaces décrites dans le texte. Pour chacune, donne son nom dans le cours et sa cause.\n3. Quelle substance empoisonne probablement la rivière ? Justifie avec le cours.\n4. Explique pourquoi une forêt tropicale abattue ne peut pas simplement être « replantée ».","bareme":[{"critere":"Peuple autochtone et pratiques compatibles avec le milieu","points":5},{"critere":"Deux menaces nommées avec leur cause","points":6},{"critere":"Le mercure de l’orpaillage","points":3},{"critere":"Explication de l’impossibilité de replanter l’écosystème","points":6}],"dureeMin":11,"corrige":"1. L’auteur appartient à un **peuple autochtone d’Amazonie**. Ses pratiques : la **chasse réglée collectivement** et le **brûlis à petite échelle**. Elles sont **compatibles** avec le maintien du milieu, car elles prélèvent peu et laissent la forêt se reconstituer.\n\n2. - Les chercheurs d’or : c’est l’**orpaillage**, qui pollue les fleuves.\n- Les machines qui abattent la forêt : c’est la **déforestation**, causée ici par la culture du **soja** et l’**élevage**.\n\n3. Il s’agit du **mercure** : d’après le cours, l’orpaillage et les mines polluent les fleuves au mercure.\n\n4. On peut **remettre des arbres**, mais pas **l’écosystème** : l’ensemble des espèces et des relations entre elles a mis **des millénaires à s’installer**. Une plantation ne remplace pas la forêt détruite."}$exo$::jsonb),
  ('c1adbe71-f57b-5c1e-81f8-5b785feaaf39'::uuid, 3, 'redaction', $exo${"titre":"Protéger ou développer : le dilemme des espaces de grande biodiversité","consigne":"Réponds aux questions en phrases complètes ; pour la dernière, rédige un paragraphe argumenté.","enonce":"**Document — Une phrase du cours**\n\n> « La meilleure protection n’est pas toujours la mise sous cloche, c’est souvent la reconnaissance de ceux qui y vivent. »\n\n1. Cite **deux** moyens de protéger les espaces de grande biodiversité et explique ce que fait chacun.\n2. L’**écotourisme** peut aider à protéger la nature. À quelle condition ? Pourquoi cette condition est-elle importante ?\n3. Explique le sens de l’expression « mise sous cloche ».\n4. Pourquoi la reconnaissance des droits des peuples autochtones protège-t-elle bien la nature ? Appuie-toi sur le cours.\n5. Qu’est-ce que le **développement durable** ? Explique en quelques lignes pourquoi il répond au dilemme « protéger ou développer ».","bareme":[{"critere":"Deux moyens de protection expliqués","points":4},{"critere":"Condition de l’écotourisme justifiée","points":3},{"critere":"Sens de la mise sous cloche","points":3},{"critere":"Rôle des peuples autochtones argumenté","points":5},{"critere":"Développement durable défini et relié au dilemme","points":5}],"dureeMin":16,"corrige":"1. Deux au choix :\n- les **parcs nationaux et réserves**, qui **interdisent ou encadrent** les activités ;\n- le **patrimoine mondial de l’UNESCO**, qui **classe** un lieu et **attire l’attention** sur lui ;\n- l’**écotourisme**, qui **finance** la protection ;\n- les **droits des peuples autochtones**, qui protègent les territoires qu’ils gèrent.\n\n2. L’écotourisme doit **rester à faible impact**. Sinon, trop de visiteurs abîmeraient le milieu qu’ils viennent admirer.\n\n3. « Mettre sous cloche » signifie **fermer un espace aux hommes** pour le protéger, comme si on le mettait sous un couvercle.\n\n4. Les peuples autochtones ont des pratiques **compatibles** avec le milieu (brûlis à petite échelle, chasse réglée, pêche saisonnière) et dépendent de la forêt pour vivre. Le cours indique que les territoires qu’ils gèrent sont **mieux préservés que la moyenne**. Reconnaître leurs droits, c’est donc confier la protection à ceux qui connaissent et entretiennent le milieu.\n\n5. Le **développement durable** consiste à **permettre aux habitants de vivre correctement sans détruire ce dont ils dépendent**. Il répond au dilemme car il refuse de choisir entre les deux : les habitants doivent pouvoir améliorer leur vie (se développer), mais sans épuiser la forêt, les récifs ou les espèces qui les font vivre (protéger)."}$exo$::jsonb),
  ('a4d37634-b247-53a0-9661-049ad775c8f6'::uuid, 1, 'redaction', $exo${"titre":"Les espaces ruraux et leurs visages","consigne":"Réponds à chaque question par une ou deux phrases complètes en utilisant le vocabulaire du cours.","enonce":"1. Donne **deux** caractéristiques d’un espace rural.\n2. Cite les **trois** types de campagnes étudiés.\n3. Choisis l’un de ces types et explique ce qui s’y passe.","bareme":[{"critere":"Deux caractéristiques de l’espace rural","points":6},{"critere":"Les trois types de campagnes","points":6},{"critere":"Explication d’un type de campagne","points":8}],"dureeMin":6,"corrige":"1. Un espace rural a une **faible densité** ; son paysage est dominé par les **champs, les prés ou les forêts** ; l’**agriculture** y a un poids important, mais plus jamais exclusif (deux suffisent).\n\n2. Les campagnes **périurbaines**, les campagnes **agricoles productives** et les campagnes **en déclin**.\n\n3. Exemples :\n- campagnes **périurbaines** : proches des villes, elles **gagnent des habitants** ; on travaille en ville et on loge à la campagne ;\n- campagnes **agricoles productives** : grandes cultures mécanisées, peu d’actifs, forte production (Beauce, Grand Ouest) ;\n- campagnes **en déclin** : **exode rural**, vieillissement, fermeture de l’école, du commerce, du médecin."}$exo$::jsonb),
  ('a4d37634-b247-53a0-9661-049ad775c8f6'::uuid, 2, 'redaction', $exo${"titre":"Moins d’agriculteurs, plus de production","consigne":"Observe le tableau puis réponds aux questions en phrases complètes.","enonce":"**Document — La place des agriculteurs parmi les actifs français (d’après le cours)**\n\n| Année | Part des agriculteurs parmi les actifs |\n|---|---|\n| 1950 | Plus de 30 % |\n| Aujourd’hui | Moins de 2 % |\n\n1. Décris l’évolution montrée par le tableau.\n2. Pendant ce temps, la production agricole a fortement augmenté. Explique ce paradoxe en citant les **deux** causes du cours.\n3. Dans quel type de campagne cette agriculture est-elle la plus visible ? Décris-la et donne **un** exemple de région française.\n4. Complète : « Moins d’agriculteurs ne veut pas dire… ». Explique cette phrase avec tes mots.","bareme":[{"critere":"Description de la baisse de la part des agriculteurs","points":4},{"critere":"Paradoxe expliqué par la mécanisation et l’agrandissement","points":6},{"critere":"Campagne agricole productive décrite avec un exemple","points":5},{"critere":"Phrase complétée et expliquée","points":5}],"dureeMin":10,"corrige":"1. La part des agriculteurs parmi les actifs français a **fortement baissé** : plus de **30 %** en 1950, moins de **2 %** aujourd’hui.\n\n2. La production a augmenté grâce à la **mécanisation** (les machines font le travail de nombreux ouvriers) et à l’**agrandissement des exploitations**. Avec moins de personnes, on produit donc davantage.\n\n3. Dans les campagnes **agricoles productives** : **grandes cultures mécanisées**, **peu d’actifs** et **forte production**. Exemple : la **Beauce** (ou le Grand Ouest).\n\n4. « Moins d’agriculteurs ne veut pas dire **moins d’agriculture**. » Même s’il y a beaucoup moins de personnes qui travaillent dans l’agriculture, les champs sont toujours cultivés et la production est même plus forte qu’avant."}$exo$::jsonb),
  ('a4d37634-b247-53a0-9661-049ad775c8f6'::uuid, 3, 'redaction', $exo${"titre":"Deux villages, deux destins","consigne":"Compare les deux villages décrits, puis réponds aux questions en phrases complètes ; la dernière demande un court paragraphe.","enonce":"**Document — Deux villages de France (situations imaginées)**\n\n- **Village A** : à 20 minutes d’une grande ville. De nouveaux lotissements se construisent ; la plupart des habitants partent travailler en ville chaque matin.\n- **Village B** : à 1 h 30 de la ville la plus proche. L’école a fermé l’an dernier, le médecin est parti à la retraite sans être remplacé, aucun bus ne passe et internet fonctionne mal. La population est âgée.\n\n1. À quel type de campagne appartient chaque village ? Justifie.\n2. Relève **trois** difficultés du village B et nomme-les avec les mots du cours.\n3. Explique la phrase du cours : « Dans un espace peu dense, la distance devient une inégalité. »\n4. Quels **atouts** le village B pourrait-il mettre en avant pour attirer de nouveaux habitants ? Explique le rôle du **télétravail**.\n5. En quelques lignes, montre que les espaces ruraux n’ont plus seulement une fonction agricole.","bareme":[{"critere":"Types de campagnes identifiés et justifiés","points":4},{"critere":"Trois difficultés nommées avec le vocabulaire du cours","points":4},{"critere":"Explication de la distance comme inégalité","points":4},{"critere":"Atouts du rural et rôle du télétravail","points":4},{"critere":"Nouvelles fonctions des espaces ruraux","points":4}],"dureeMin":17,"corrige":"1. Le village A est une **campagne périurbaine** : proche de la ville, il **gagne des habitants** qui travaillent en ville et logent à la campagne. Le village B est une **campagne en déclin** : éloigné, il connaît le **vieillissement** et la **fermeture des services** (école, médecin).\n\n2. - Le médecin non remplacé : un **désert médical**.\n- Aucun bus : la **dépendance à la voiture**.\n- Internet qui fonctionne mal : une **zone blanche**.\n(La fermeture de l’école est aussi acceptée comme signe de déclin.)\n\n3. Le service existe, mais il est **loin** : à quarante minutes de route ou plus. Les habitants des campagnes isolées, surtout les personnes âgées ou sans voiture, y ont donc **plus difficilement accès** que les habitants des villes. L’éloignement crée une inégalité.\n\n4. Atouts : le **cadre de vie**, le **prix du logement** plus bas, l’**espace**, le **lien social**, le **patrimoine**, la **nature**. Le **télétravail** permet de travailler depuis chez soi : on peut habiter loin de la ville sans faire le trajet chaque jour, ce qui a renforcé l’attractivité de certaines campagnes (à condition d’avoir une bonne connexion internet).\n\n5. Les espaces ruraux sont passés d’une fonction **productive** (agricole) à des fonctions **résidentielle** (on y habite), **touristique** et **récréative** (on s’y détend), et **énergétique** : ils produisent de l’énergie grâce à l’**éolien**, au **solaire** et à la **méthanisation**."}$exo$::jsonb),
  ('71d64eba-5487-5da4-b60d-2f1e1f70afd8'::uuid, 1, 'redaction', $exo${"titre":"Métropoles et mégapoles","consigne":"Réponds à chaque question par une ou deux phrases complètes en utilisant le vocabulaire du cours.","enonce":"1. Qu’est-ce qu’une **métropole** ? Cite **deux** fonctions de commandement qu’on y trouve.\n2. Qu’est-ce qu’une **mégapole** ? Donne **deux** exemples.\n3. Que se passe-t-il en **2007** ?","bareme":[{"critere":"Définition de la métropole et deux fonctions","points":8},{"critere":"Définition de la mégapole et deux exemples","points":7},{"critere":"Événement de 2007","points":5}],"dureeMin":6,"corrige":"1. Une **métropole** est une grande ville qui **concentre les fonctions de commandement** et **rayonne** bien au-delà de ses limites. Fonctions (deux au choix) : sièges d’entreprises, universités, hôpitaux, musées, aéroports, administrations.\n\n2. Une **mégapole** est une agglomération de **plus de 10 millions d’habitants**. Exemples (deux au choix) : Tokyo, Delhi, Shanghai, São Paulo, Mexico, Le Caire, Lagos.\n\n3. En 2007, **pour la première fois, plus de la moitié de l’humanité vit en ville**."}$exo$::jsonb),
  ('71d64eba-5487-5da4-b60d-2f1e1f70afd8'::uuid, 2, 'redaction', $exo${"titre":"Le trajet quotidien de Karim","consigne":"Lis la situation puis réponds aux questions en phrases complètes, en utilisant le vocabulaire du cours.","enonce":"**Situation (imaginée)** — Karim habite une maison dans une commune de banlieue, loin du centre de Paris. Chaque matin, il prend le train puis le métro pour aller travailler dans une tour de bureaux à La Défense. Le soir, il fait le trajet inverse. Aux heures de pointe, les trains sont bondés.\n\n1. Comment appelle-t-on les déplacements quotidiens de Karim ? Donne la définition.\n2. Dans quelle zone de la métropole Karim habite-t-il ? Dans quelle zone travaille-t-il ? Décris chacune de ces zones.\n3. Quelle conséquence de ces déplacements le texte montre-t-il ?\n4. La commune de Karim ne fait pas partie de la ville de Paris. Fait-elle pourtant partie de la métropole ? Justifie avec la notion d’**aire urbaine**.","bareme":[{"critere":"Migrations pendulaires nommées et définies","points":5},{"critere":"Banlieue et quartier d’affaires identifiés et décrits","points":6},{"critere":"Saturation des transports aux heures de pointe","points":4},{"critere":"Appartenance à l’aire urbaine justifiée","points":5}],"dureeMin":10,"corrige":"1. Ce sont des **migrations pendulaires** : les **navettes quotidiennes entre le domicile et le lieu de travail**.\n\n2. Karim habite en **banlieue**, zone surtout composée de **logements**, organisée en couronnes successives autour du centre. Il travaille dans le **quartier d’affaires** (CBD) de La Défense, fait de **tours de bureaux**.\n\n3. Ces déplacements **saturent les transports aux heures de pointe** : les trains sont bondés.\n\n4. Oui. La métropole ne s’arrête pas aux limites de la commune-centre : l’ensemble du centre, des banlieues et des périphéries forme une **aire urbaine**, bien plus étendue que la commune-centre. Comme Karim se rend chaque jour à La Défense, sa commune fait partie de cette aire. Une métropole se mesure à la **distance que ses habitants parcourent chaque matin**."}$exo$::jsonb),
  ('71d64eba-5487-5da4-b60d-2f1e1f70afd8'::uuid, 3, 'redaction', $exo${"titre":"Organisation et inégalités d’une métropole","consigne":"Lis le document puis réponds aux questions en phrases complètes ; la dernière question demande un court paragraphe.","enonce":"**Document — Rio de Janeiro (description)**\n\n> À Rio de Janeiro, au Brésil, des *favelas* s’accrochent aux collines. Leurs maisons sont construites par les habitants eux-mêmes. À quelques rues de là, des immeubles de luxe font face à la mer.\n\n1. Qu’est-ce qu’une *favela* ? Donne le mot général du cours et un autre exemple de ce type de quartier dans une autre métropole.\n2. Dans les pays en développement, quelle part des citadins vit dans ce type de quartier ?\n3. Que montre ce document sur les métropoles ?\n4. Cite les **quatre** zones de l’organisation d’une métropole, du centre vers l’extérieur, et ce qu’on trouve dans chacune.\n5. Qu’est-ce qu’une **ville mondiale** ? Cite-en **trois** et explique en quoi elles se distinguent des autres métropoles.","bareme":[{"critere":"Bidonville défini avec un autre exemple","points":4},{"critere":"Part des citadins vivant en bidonville","points":2},{"critere":"Inégalités dans une même métropole","points":4},{"critere":"Les quatre zones de la métropole décrites dans l’ordre","points":6},{"critere":"Villes mondiales définies et citées","points":4}],"dureeMin":16,"corrige":"1. Une *favela* est un **bidonville**, un quartier d’habitat pauvre construit par ses habitants. Autre exemple : les *slums* de **Mumbai**.\n\n2. Environ **un citadin sur quatre** vit dans un bidonville dans les pays en développement.\n\n3. Le document montre que dans une **même métropole** coexistent des **quartiers très riches** et des **bidonvilles**, parfois très proches : les métropoles sont marquées par de fortes **inégalités**.\n\n4. - Le **centre-ville** : commerces, services, patrimoine ; souvent le plus cher.\n- Le **quartier d’affaires** (CBD) : des tours de bureaux (La Défense, Manhattan).\n- Les **banlieues** : des logements, en couronnes successives.\n- Les **périphéries** : zones commerciales, industrielles, aéroports.\n\n5. Une **ville mondiale** est une métropole qui **commande l’économie mondiale**. Exemples (trois au choix) : **New York**, **Londres**, **Tokyo**, **Paris**, **Shanghai**. Toutes les métropoles concentrent des fonctions de commandement, mais les villes mondiales rayonnent sur **le monde entier**, et non seulement sur leur pays ou leur région."}$exo$::jsonb),
  ('7a0ce9e3-53ba-5f81-aef8-870f44c0bd5b'::uuid, 1, 'redaction', $exo${"titre":"Les métropoles du Sud : une croissance explosive","consigne":"Réponds à chaque question par une ou deux phrases complètes en utilisant le vocabulaire du cours.","enonce":"1. Compare la croissance des métropoles des pays développés et celle des métropoles des pays en développement.\n2. Qu’est-ce qu’un **bidonville** ? Combien de personnes environ y vivent dans le monde ?\n3. Selon le cours, d’où naissent tous les défis des métropoles du Sud ?","bareme":[{"critere":"Comparaison des deux types de croissance","points":6},{"critere":"Définition du bidonville et nombre d’habitants","points":8},{"critere":"Origine des défis : le décalage avec les équipements","points":6}],"dureeMin":6,"corrige":"1. Les métropoles des pays **développés** sont **anciennes** et ont une croissance **lente** ; celles des pays **en développement** ont une croissance **explosive**.\n\n2. Un **bidonville** est un quartier d’**habitat auto-construit**, **sans titre de propriété**, souvent **privé d’eau courante, d’électricité et d’égouts**. Environ **un milliard** de personnes y vivent dans le monde.\n\n3. Ils naissent du **décalage** entre la croissance de la population et celle des **équipements** : les métropoles du Sud grandissent bien plus vite que leurs logements, transports et réseaux."}$exo$::jsonb),
  ('7a0ce9e3-53ba-5f81-aef8-870f44c0bd5b'::uuid, 2, 'redaction', $exo${"titre":"Lagos : loger et transporter des millions d’habitants","consigne":"Utilise les données et le cours pour répondre aux questions en phrases complètes ; écris ton calcul.","enonce":"**Données** — Lagos (Nigeria) comptait **300 000** habitants en 1950. Elle en compte aujourd’hui **plus de 15 millions**.\n\n1. Par combien la population de Lagos a-t-elle été au moins multipliée depuis 1950 ? Écris ton calcul.\n2. Explique pourquoi une croissance aussi rapide provoque la multiplication des **bidonvilles**.\n3. Cite **deux** problèmes de transport que connaît une telle métropole.\n4. Propose **trois** réponses possibles à ces problèmes de transport, tirées du cours, et explique l’intérêt de l’une d’elles.","bareme":[{"critere":"Calcul du coefficient multiplicateur","points":4},{"critere":"Lien entre croissance rapide et bidonvilles","points":6},{"critere":"Deux problèmes de transport","points":4},{"critere":"Trois réponses et intérêt de l’une d’elles","points":6}],"dureeMin":10,"corrige":"1. 15 000 000 ÷ 300 000 = **50**. La population de Lagos a été multipliée **au moins par 50** depuis 1950.\n\n2. La population augmente beaucoup plus vite que la construction de **logements abordables**. Faute de logement, les nouveaux habitants construisent eux-mêmes leur maison : l’**habitat auto-construit** se multiplie, souvent sans titre de propriété, sans eau courante, sans électricité ni égouts.\n\n3. Deux au choix : les **embouteillages**, les **trajets démesurés**, la **pollution**.\n\n4. Réponses (trois au choix) : le **métro**, le **tramway**, les **bus en site propre**, les **pistes cyclables**, le **télétravail**, les **péages urbains**. Exemple d’intérêt : le métro transporte beaucoup de voyageurs sans utiliser la route, ce qui réduit les embouteillages et la pollution."}$exo$::jsonb),
  ('7a0ce9e3-53ba-5f81-aef8-870f44c0bd5b'::uuid, 3, 'redaction', $exo${"titre":"Environnement, inégalités et risques dans les métropoles","consigne":"Réponds aux questions en phrases complètes ; la dernière question demande un court paragraphe argumenté.","enonce":"**Document — Une phrase du cours**\n\n> « Une ville peut concentrer les plus grandes richesses du pays et sa plus grande pauvreté, à quelques centaines de mètres de distance. »\n\n1. Explique ce qu’est l’**îlot de chaleur urbain** et pourquoi il se produit.\n2. Qu’est-ce que l’**étalement urbain** ? Quelle est sa conséquence ?\n3. Cite **deux** autres problèmes environnementaux des métropoles et leurs effets.\n4. Explique la phrase du document. Que signifie l’expression « la métropole rassemble sans mélanger » ?\n5. Pourquoi une forte densité rend-elle les risques plus graves ? Illustre ta réponse avec **deux** exemples de métropoles et le risque qui les menace.","bareme":[{"critere":"Îlot de chaleur urbain expliqué","points":4},{"critere":"Étalement urbain et sa conséquence","points":3},{"critere":"Deux autres problèmes environnementaux","points":3},{"critere":"Analyse des inégalités et de la phrase du document","points":5},{"critere":"Densité et risques illustrés par deux exemples","points":5}],"dureeMin":17,"corrige":"1. L’**îlot de chaleur urbain** est le fait qu’il fait **plusieurs degrés de plus** en ville qu’à la campagne. Il se produit parce que le **béton et l’asphalte stockent la chaleur**.\n\n2. L’**étalement urbain** est l’extension de la ville vers l’extérieur. Conséquence : la ville **grignote les terres agricoles et les milieux naturels**.\n\n3. - La **pollution de l’air** provoque des **millions de décès prématurés** par an.\n- Les **déchets** : leur collecte et leur traitement deviennent un **problème majeur**.\n\n4. Dans une même métropole, on trouve les **quartiers les plus riches** et les **quartiers les plus pauvres** du pays, parfois tout proches. D’un côté des **quartiers fermés**, de l’autre des **bidonvilles** : les riches et les pauvres vivent dans la même ville, mais **ne se côtoient pas**. La métropole « rassemble » beaucoup de monde au même endroit, « sans mélanger » les populations.\n\n5. Plus la densité est forte, plus le **nombre de personnes exposées** à une catastrophe est élevé. Exemples (deux au choix) : les **séismes** à **Tokyo** ; les **cyclones** à **Manille** ; les **inondations** et la **montée du niveau de la mer** à **Jakarta**, **Lagos** ou **Miami**."}$exo$::jsonb),
  ('cbca8654-757d-5463-84d4-a5ce5e0774fe'::uuid, 1, 'redaction', $exo${"titre":"Les trois exigences de la ville durable","consigne":"Réponds à chaque question par une ou deux phrases complètes en utilisant le vocabulaire du cours.","enonce":"1. D’ici 2050, quelle part de l’humanité vivra en ville ?\n2. Cite les **trois** exigences que cherche à concilier la ville durable et explique ce que demande chacune.\n3. Qu’est-ce qu’un **écoquartier** ? Cite-en **un** exemple en France.","bareme":[{"critere":"Part de citadins en 2050","points":4},{"critere":"Trois exigences de la ville durable expliquées","points":10},{"critere":"Écoquartier et exemple français","points":6}],"dureeMin":7,"corrige":"1. D’ici 2050, **sept habitants sur dix** vivront en ville.\n\n2. - **Environnementale** : moins d’énergie, moins de pollution, plus de nature.\n- **Sociale** : des logements accessibles, de la mixité, des services pour tous.\n- **Économique** : des emplois et des activités sur place.\n\n3. Un **écoquartier** est un quartier conçu selon les principes de la ville durable ; il sert de **laboratoire**. Exemple en France : **Confluence**, à **Lyon**."}$exo$::jsonb),
  ('cbca8654-757d-5463-84d4-a5ce5e0774fe'::uuid, 2, 'redaction', $exo${"titre":"Un projet pour une ancienne usine","consigne":"Lis le projet puis réponds aux questions en phrases complètes, en utilisant le vocabulaire du cours.","enonce":"**Document — Projet d’une municipalité (texte imaginé)**\n\n> « Sur le terrain de l’ancienne usine textile, abandonnée depuis vingt ans, nous construirons un nouveau quartier. Les immeubles auront des toits couverts de plantes et un grand parc sera planté d’arbres. Les panneaux solaires produiront plus d’énergie que les logements n’en consomment. École, commerces et médecin seront à moins de 15 minutes à pied. Une partie des logements sera réservée aux familles modestes. »\n\n1. Comment appelle-t-on un terrain industriel abandonné ? Pourquoi est-il préférable de construire à cet endroit ?\n2. Relève dans le texte **trois** pistes concrètes de la ville durable et nomme-les avec les mots du cours.\n3. À quoi servent les toits végétalisés et le parc ?\n4. Montre que ce projet répond à l’exigence **sociale** de la ville durable.","bareme":[{"critere":"Friche industrielle et intérêt de la réhabiliter","points":5},{"critere":"Trois pistes relevées et nommées","points":6},{"critere":"Rôle de la végétalisation contre l’îlot de chaleur","points":4},{"critere":"Exigence sociale justifiée","points":5}],"dureeMin":11,"corrige":"1. C’est une **friche industrielle**. La **réhabiliter** permet de **ne pas construire sur du neuf** : on évite de s’étaler sur les terres agricoles ou naturelles.\n\n2. Trois au choix :\n- l’ancienne usine transformée : **réhabiliter les friches** ;\n- les toits de plantes et le parc : **végétaliser** ;\n- les panneaux solaires qui produisent plus que la consommation : **bâtiments à énergie positive** ;\n- école, commerces et médecin à moins de 15 minutes à pied : la **ville du quart d’heure**.\n\n3. La végétalisation sert à **combattre l’îlot de chaleur urbain** : les plantes et les arbres rafraîchissent la ville, et elle ramène de la nature en ville.\n\n4. Le projet réserve une partie des logements aux familles modestes : ce sont des **logements accessibles** qui favorisent la **mixité**. Il place aussi l’école, les commerces et le médecin à proximité : des **services pour tous**."}$exo$::jsonb),
  ('cbca8654-757d-5463-84d4-a5ce5e0774fe'::uuid, 3, 'redaction', $exo${"titre":"Ville intelligente, ville durable ?","consigne":"Réponds aux questions en phrases complètes ; la dernière question demande un court paragraphe argumenté.","enonce":"**Document — Deux phrases du cours**\n\n> « Une ville n’est pas durable parce qu’elle est équipée de capteurs. Elle l’est parce que ses habitants peuvent y vivre bien, longtemps, sans épuiser ce qui les entoure. »\n>\n> « Une ville se fait **avec** ceux qui y vivent, pas seulement pour eux. »\n\n1. Qu’est-ce qu’une **smart city** ? Donne **deux** exemples de ce qu’elle permet d’optimiser.\n2. Quel problème la smart city pose-t-elle ? Explique-le.\n3. Explique la première phrase du document.\n4. Cite **deux** façons d’associer les habitants à un projet de ville, puis explique la seconde phrase du document.\n5. Densifier ou s’étaler ? Explique quel choix fait la ville durable et pourquoi, puis cite **deux** écoquartiers étrangers qui servent de modèles.","bareme":[{"critere":"Smart city définie avec deux exemples","points":4},{"critere":"Protection des données expliquée","points":3},{"critere":"Analyse de la première phrase","points":4},{"critere":"Participation des habitants et seconde phrase","points":5},{"critere":"Densification justifiée et écoquartiers étrangers","points":4}],"dureeMin":17,"corrige":"1. La **smart city** (ville intelligente) **utilise le numérique** pour optimiser le fonctionnement de la ville : l’**éclairage**, la **circulation**, la **collecte des déchets**, la **consommation d’eau** (deux au choix).\n\n2. Elle pose un problème de **protection des données** : tout ce qui est mesuré peut être **suivi**. Les habitants pourraient être surveillés dans leurs déplacements ou leurs habitudes.\n\n3. Les capteurs et le numérique ne suffisent pas : une ville est durable si ses habitants y ont une **bonne qualité de vie**, **sur le long terme**, **sans épuiser les ressources** et la nature qui les entourent. La technique n’est qu’un outil.\n\n4. Façons d’associer les habitants (deux au choix) : la **concertation**, les **budgets participatifs**, les **jardins partagés**. La seconde phrase signifie que les habitants doivent **participer dès la conception** des projets : ce sont eux qui connaissent leurs besoins, et les projets réussis sont ceux qui les associent.\n\n5. La ville durable choisit de **densifier plutôt que s’étaler**, afin de **préserver les terres agricoles**. Écoquartiers étrangers (deux au choix) : **Vauban** à Fribourg (Allemagne), **Hammarby** à Stockholm, **BedZED** à Londres."}$exo$::jsonb),
  ('718743bb-7386-5fa1-bc49-9e5c7b7e87e4'::uuid, 1, 'redaction', $exo${"titre":"Les grandes étapes de la conquête romaine","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"Voici quatre événements dans le désordre :\n- Octave devient Auguste, le premier empereur.\n- Les guerres puniques contre Carthage.\n- L’Empire atteint son extension maximale sous Trajan.\n- César conquiert la Gaule.\n\n1. Range ces événements dans l’ordre chronologique et associe à chacun sa date ou sa période.\n2. Que se passe-t-il à **Alésia** en 52 av. J.-C. ?\n3. Comment les Romains appellent-ils la Méditerranée ? Que signifie ce nom ?","bareme":[{"critere":"Ordre chronologique et dates","points":10},{"critere":"Alésia et la reddition de Vercingétorix","points":5},{"critere":"Mare Nostrum et son sens","points":5}],"dureeMin":7,"corrige":"1. Dans l’ordre :\n- **264-146 av. J.-C.** : les guerres puniques contre Carthage ;\n- **58-51 av. J.-C.** : César conquiert la Gaule ;\n- **27 av. J.-C.** : Octave devient Auguste, le premier empereur ;\n- **117 apr. J.-C.** : sous Trajan, l’Empire atteint son extension maximale, de la Bretagne à la Mésopotamie.\n\n2. À **Alésia**, en 52 av. J.-C., César l’emporte et **Vercingétorix se rend** (reddition), pendant la conquête de la Gaule.\n\n3. Les Romains l’appellent ***Mare Nostrum***, ce qui signifie **« notre mer »** : Rome domine alors toutes ses rives."}$exo$::jsonb),
  ('718743bb-7386-5fa1-bc49-9e5c7b7e87e4'::uuid, 2, 'redaction', $exo${"titre":"Les pouvoirs de l’empereur","consigne":"Lis le document puis réponds aux questions en phrases complètes, en utilisant le vocabulaire du cours.","enonce":"**Document — Les titres d’un empereur romain (d’après le cours)**\n\n| Titre porté | Traduction |\n|---|---|\n| *Imperator* | Général vainqueur |\n| *Pontifex maximus* | Grand prêtre |\n| Maître de l’État | — |\n\n1. Qui est le premier empereur romain et en quelle année le devient-il ?\n2. Pour chacun des trois titres, explique ce que l’empereur commande.\n3. Que deviennent les **institutions républicaines** sous l’Empire ?\n4. Qu’est-ce que le **culte impérial** ? Pourquoi est-il utile à l’empereur ?","bareme":[{"critere":"Auguste en 27 av. J.-C.","points":3},{"critere":"Les pouvoirs associés aux trois titres","points":7},{"critere":"Institutions républicaines vidées de leur pouvoir","points":4},{"critere":"Culte impérial défini et son rôle politique","points":6}],"dureeMin":10,"corrige":"1. Le premier empereur est **Octave**, qui devient **Auguste** en **27 av. J.-C.**\n\n2. - *Imperator* : il commande l’**armée**.\n- *Pontifex maximus* : il dirige la **religion**.\n- Maître de l’État : il contrôle l’**administration** et la **justice**.\nL’empereur concentre donc tous les pouvoirs.\n\n3. Les institutions républicaines **subsistent**, mais elles sont **vidées de leur pouvoir réel** : c’est l’empereur qui décide.\n\n4. Le **culte impérial** consiste à **rendre un culte à l’empereur et à Rome**. Il devient un **ciment politique** : en honorant l’empereur, tous les habitants de l’Empire montrent leur loyauté et se sentent unis autour de lui."}$exo$::jsonb),
  ('718743bb-7386-5fa1-bc49-9e5c7b7e87e4'::uuid, 3, 'redaction', $exo${"titre":"Tenir un immense empire : armée, provinces et routes","consigne":"Réponds aux questions en phrases complètes ; la dernière question demande un court paragraphe argumenté.","enonce":"**Document — Une phrase du cours**\n\n> « Les routes romaines n’ont pas été construites pour les marchands : elles ont été construites pour les légions. Le commerce a suivi. »\n\n1. Compare les **légions** et les **auxiliaires** : qui sont ces soldats et que gagnent les auxiliaires après leur service ?\n2. Qu’est-ce que le ***limes*** ? Donne un exemple de fortification.\n3. Comment l’Empire est-il administré ? Précise l’étendue du réseau de routes.\n4. Explique la phrase du document.\n5. Qu’est-ce que la *Pax Romana* ? Montre qu’elle a des avantages, mais qu’elle repose aussi sur la force.","bareme":[{"critere":"Légions et auxiliaires comparés","points":4},{"critere":"Limes défini avec le mur d’Hadrien","points":3},{"critere":"Provinces, gouverneurs et routes","points":4},{"critere":"Explication de la phrase sur les routes","points":4},{"critere":"Pax Romana : avantages et usage de la force","points":5}],"dureeMin":17,"corrige":"1. Les **légions** sont composées de **citoyens** romains et stationnent aux frontières. Les **auxiliaires** sont **recrutés parmi les peuples conquis** ; après leur service, ils **obtiennent la citoyenneté** romaine. L’armée compte en tout **300 000 à 400 000 hommes**.\n\n2. Le ***limes*** est la **frontière fortifiée** de l’Empire, le long de laquelle sont installées les légions. Exemple : le **mur d’Hadrien**, en Bretagne.\n\n3. L’Empire est découpé en **provinces**, dirigées par des **gouverneurs nommés**. Il est parcouru par **plus de 80 000 km de routes**, jalonnées de bornes milliaires.\n\n4. Les routes servaient d’abord à **déplacer rapidement les légions** pour défendre les frontières et contrôler les provinces : leur but était **militaire**. Mais une fois construites, elles ont aussi servi aux **marchands**, et le commerce s’est développé grâce à elles.\n\n5. La *Pax Romana* (« paix romaine »), du **Ier au IIe siècle**, est une longue période de **stabilité intérieure**. Avantages : elle **favorise le commerce, les villes et les échanges**. Mais cette paix est **imposée et maintenue par la force** : elle repose sur l’armée, les légions et les frontières fortifiées."}$exo$::jsonb),
  ('f83d440f-a345-50f5-9c39-9a87c83109b3'::uuid, 1, 'redaction', $exo${"titre":"La romanisation et les équipements de la ville romaine","consigne":"Réponds à chaque question par une ou deux phrases complètes en utilisant le vocabulaire du cours.","enonce":"1. Définis la **romanisation**.\n2. Cite **trois** équipements d’une ville romaine et donne la fonction de chacun.\n3. Cite **deux** villes romaines de Gaule en donnant leur nom latin et leur nom actuel.","bareme":[{"critere":"Définition de la romanisation","points":6},{"critere":"Trois équipements et leur fonction","points":9},{"critere":"Deux villes de Gaule avec nom latin et nom actuel","points":5}],"dureeMin":7,"corrige":"1. La **romanisation** est la **diffusion du mode de vie romain** (langue, droit, urbanisme, religion, techniques) dans les provinces conquises.\n\n2. Trois au choix :\n- le **forum** : la place publique ;\n- le **temple** : le culte ;\n- les **thermes** : les bains ;\n- le **théâtre**, l’**amphithéâtre**, le **cirque** : les spectacles ;\n- les **aqueducs** et les **égouts** : l’eau.\n\n3. Deux au choix : **Lugdunum** (Lyon), **Nemausus** (Nîmes), **Arelate** (Arles)."}$exo$::jsonb),
  ('f83d440f-a345-50f5-9c39-9a87c83109b3'::uuid, 2, 'redaction', $exo${"titre":"Décrire le plan d’une ville gallo-romaine","consigne":"Lis la description puis réponds aux questions en phrases complètes, en utilisant le vocabulaire du cours.","enonce":"**Document — Une ville de Gaule romaine (description imaginée)**\n\n> Les rues se coupent à angle droit. Deux grandes rues traversent la ville : l’une va du nord au sud, l’autre de l’est à l’ouest. Près de leur croisement s’étend une grande place entourée de bâtiments publics et d’un temple. Un long ouvrage à arches amène l’eau des collines jusqu’aux bains publics.\n\n1. Comment s’appelle ce type de plan ?\n2. Donne le nom de la rue nord-sud et celui de la rue est-ouest.\n3. Nomme la grande place et les bains publics avec les mots du cours. À quoi sert la grande place ?\n4. Comment s’appelle l’ouvrage qui amène l’eau ? Cite un exemple célèbre en Gaule.\n5. Pourquoi Rome construit-elle partout des villes sur ce même modèle ?","bareme":[{"critere":"Plan en damier, cardo et decumanus","points":6},{"critere":"Forum et thermes nommés, rôle du forum","points":5},{"critere":"Aqueduc et pont du Gard","points":4},{"critere":"La ville comme instrument de romanisation","points":5}],"dureeMin":11,"corrige":"1. C’est un **plan en damier**.\n\n2. La rue nord-sud est le **cardo** ; la rue est-ouest est le **decumanus**. Ils se croisent au cœur de la ville.\n\n3. La grande place est le **forum** : c’est la **place publique**, le centre de la vie de la cité. Les bains publics sont les **thermes**.\n\n4. C’est un **aqueduc**. Exemple célèbre : le **pont du Gard**.\n\n5. La ville est l’**instrument principal de la romanisation** : en construisant partout des villes sur le même modèle, avec forum, temple, thermes et spectacles, Rome diffuse son **mode de vie** dans les provinces conquises."}$exo$::jsonb),
  ('f83d440f-a345-50f5-9c39-9a87c83109b3'::uuid, 3, 'redaction', $exo${"titre":"Devenir romain sans cesser d’être soi","consigne":"Réponds aux questions en phrases complètes ; la dernière question demande un court paragraphe argumenté.","enonce":"**Document — Une phrase du cours**\n\n> « La citoyenneté est le plus puissant instrument d’adhésion dont Rome dispose : elle transforme un vaincu en participant. »\n\n1. Qu’est-ce que le **syncrétisme religieux** pratiqué par Rome ? Cite **deux** cultes orientaux qui se diffusent dans l’Empire.\n2. Quelle est la seule exigence religieuse de Rome ? Pour quels groupes pose-t-elle problème ?\n3. Montre que le **latin** et le **droit romain** ont laissé des traces jusqu’à aujourd’hui.\n4. Que décide l’**édit de Caracalla** en 212 apr. J.-C. ? Explique la phrase du document.\n5. La romanisation a-t-elle touché tout le monde de la même façon ? Rédige un court paragraphe qui montre à la fois pourquoi elle a été adoptée et quelles sont ses limites.","bareme":[{"critere":"Syncrétisme religieux et cultes orientaux","points":4},{"critere":"Culte impérial et groupes concernés","points":3},{"critere":"Héritage du latin et du droit romain","points":3},{"critere":"Édit de Caracalla et explication de la phrase","points":5},{"critere":"Paragraphe sur l’adoption et les limites de la romanisation","points":5}],"dureeMin":17,"corrige":"1. Le **syncrétisme** consiste à **assimiler** les dieux des peuples conquis aux dieux romains, au lieu d’imposer ces derniers : les divinités gauloises sont associées aux divinités romaines. Cultes orientaux : **Isis** et **Mithra**.\n\n2. La seule exigence est le **culte impérial**, marque de **loyauté politique**. Il pose problème aux **juifs** et aux **chrétiens**.\n\n3. Le **latin** devient la langue de l’administration et du commerce en Occident ; il a donné le **français**, l’**espagnol**, l’**italien**, le **portugais** et le **roumain**. Le **droit romain** structure encore nos codes de lois.\n\n4. L’édit de Caracalla étend la **citoyenneté romaine à tous les hommes libres de l’Empire**. Devenir citoyen donne des droits et ouvre des carrières : un peuple autrefois vaincu par Rome devient membre à part entière de l’Empire et a intérêt à le soutenir. C’est pourquoi la citoyenneté « transforme un vaincu en participant ».\n\n5. La romanisation n’est pas seulement imposée : elle est **adoptée**, car elle **ouvre des carrières** et donne accès à la citoyenneté. Mais elle touche surtout les **villes** et les **élites**. Dans les **campagnes**, les **langues et les coutumes locales** se maintiennent longtemps. On peut donc devenir romain sans cesser complètement d’être soi."}$exo$::jsonb),
  ('2ceb91e7-2feb-5970-8f1e-c1c588744cd2'::uuid, 1, 'redaction', $exo${"titre":"Jésus de Nazareth et la naissance du christianisme","consigne":"Réponds à chaque question par une ou deux phrases complètes en utilisant le vocabulaire du cours.","enonce":"1. Qui est Jésus ? Où et vers quelle date prêche-t-il ?\n2. Résume son message en citant **deux** idées qu’il annonce.\n3. Où et sous quel gouverneur romain est-il crucifié ? Quel message de ses disciples fonde la nouvelle religion ?","bareme":[{"critere":"Identité de Jésus, lieu et date de sa prédication","points":6},{"critere":"Deux idées de son message","points":6},{"critere":"Crucifixion et message de la résurrection","points":8}],"dureeMin":7,"corrige":"1. Jésus de Nazareth est un **juif de Galilée**. Il prêche en **Galilée** vers **28-30 apr. J.-C.**, dans la province romaine de Judée.\n\n2. Deux idées au choix : il annonce le **royaume de Dieu** ; il s’adresse aux **humbles** ; il appelle à l’**amour du prochain**.\n\n3. Il est crucifié à **Jérusalem** sous **Ponce Pilate**. Selon ses disciples, il est **ressuscité** : c’est ce message qui fonde la nouvelle religion."}$exo$::jsonb),
  ('2ceb91e7-2feb-5970-8f1e-c1c588744cd2'::uuid, 2, 'redaction', $exo${"titre":"Deux sources pour connaître les débuts du christianisme","consigne":"Lis les deux documents puis réponds aux questions en phrases complètes.","enonce":"**Document 1 — Extrait de l’Évangile selon Marc**\n\n> « Tu aimeras ton prochain comme toi-même. »\n\n**Document 2 — Tacite, historien romain, Annales (vers 115 apr. J.-C.)**\n\n> « Ce nom [de chrétiens] leur vient de Christ, que, sous le règne de Tibère, le procurateur Ponce Pilate avait livré au supplice. »\n\n1. Présente chaque document : qui en est l’auteur ? L’auteur est-il chrétien ?\n2. Quelle est la nature des **Évangiles** ? Quand ont-ils été rédigés ? Cite les **quatre** évangélistes.\n3. Que nous apprend le document 1 sur le message de Jésus ?\n4. Que prouve le document 2 ? Pourquoi est-il précieux pour l’historien ?\n5. Explique la phrase du cours : « Les Évangiles disent ce que l’on croyait ; Tacite atteste que l’on y croyait. »","bareme":[{"critere":"Présentation des deux documents","points":4},{"critere":"Nature et rédaction des Évangiles","points":5},{"critere":"Apport de chaque document","points":6},{"critere":"Explication des deux usages des sources","points":5}],"dureeMin":12,"corrige":"1. Le document 1 est tiré de l’**Évangile selon Marc**, un texte **chrétien**. Le document 2 est écrit par **Tacite**, un historien romain **non chrétien**.\n\n2. Les Évangiles sont des **textes de foi**, rédigés entre **70 et 100 apr. J.-C.**, soit des décennies après la mort de Jésus. Les quatre évangélistes sont **Matthieu, Marc, Luc et Jean**.\n\n3. Il montre que Jésus appelle à l’**amour du prochain**.\n\n4. Il prouve que **le mouvement chrétien a existé** et que Jésus (le Christ) a été **exécuté sous Ponce Pilate**. Il est précieux car son auteur **n’est pas chrétien** : il n’a aucune raison de défendre cette religion.\n\n5. Les Évangiles nous renseignent sur **le contenu de la foi** des premiers chrétiens (ce qu’ils croyaient), mais ce ne sont pas des preuves historiques. Tacite, lui, ne partage pas cette foi, mais il **confirme que des chrétiens existaient** et croyaient en Christ. Les deux types de sources ont donc **deux usages différents**."}$exo$::jsonb),
  ('2ceb91e7-2feb-5970-8f1e-c1c588744cd2'::uuid, 3, 'redaction', $exo${"titre":"D’un mouvement juif à une religion universelle","consigne":"Réponds aux questions en phrases complètes ; la dernière question demande un court paragraphe argumenté.","enonce":"1. Cite les **trois** facteurs qui expliquent la diffusion rapide du christianisme et explique l’effet de chacun.\n2. Qui est le principal artisan de cette diffusion ?\n3. Recopie et complète le tableau suivant :\n\n| Hérité du judaïsme | Propre au christianisme |\n|---|---|\n| … | … |\n| … | … |\n\n4. Décris les **premières communautés chrétiennes** : où vivent-elles, que font-elles, comment sont-elles organisées ?\n5. Explique pourquoi l’ouverture aux **non-juifs** est considérée comme la décision **majeure** des débuts du christianisme.","bareme":[{"critere":"Trois facteurs de diffusion et leurs effets","points":5},{"critere":"Paul de Tarse","points":2},{"critere":"Tableau héritage et nouveautés","points":4},{"critere":"Description des premières communautés","points":4},{"critere":"Importance de l’ouverture aux non-juifs argumentée","points":5}],"dureeMin":16,"corrige":"1. - Les **routes** et la **sécurité** de l’Empire : on **circule** facilement.\n- Le **grec**, langue commune de l’Orient : on **se comprend**.\n- L’**ouverture aux non-juifs** : le christianisme devient **universel**.\n\n2. **Paul de Tarse**.\n\n3. | Hérité du judaïsme | Propre au christianisme |\n|---|---|\n| Le **monothéisme** | La foi en **Jésus-Christ**, fils de Dieu, mort et ressuscité |\n| La **Bible** | Le **baptême**, qui remplace la circoncision |\n\n4. Les premières communautés sont **urbaines** et **modestes**, et se réunissent **dans des maisons**. Elles partagent un repas, l’**eucharistie**, et pratiquent l’**entraide**. Elles ont des responsables : **diacres**, **prêtres** et **évêques**.\n\n5. Au départ, les disciples de Jésus forment un **mouvement juif**. En s’ouvrant aux **non-juifs**, le christianisme peut toucher **tous les peuples** de l’Empire : il devient une **religion universelle**. Grâce aux routes et à la langue grecque, et avec l’action de Paul de Tarse, le message se répand alors bien au-delà de la Judée. Sans cette décision, il serait sans doute resté limité à une petite partie de la population."}$exo$::jsonb),
  ('319cde17-8032-5331-9e3e-728d758e3a99'::uuid, 1, 'redaction', $exo${"titre":"Trois dates des chrétiens dans l’Empire romain","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"Pour chacune des dates suivantes, explique ce qui se passe et nomme l’empereur concerné.\n\n1. **64 apr. J.-C.**\n2. **313**\n3. **380**","bareme":[{"critere":"64 : Néron accuse les chrétiens de l’incendie de Rome","points":6},{"critere":"313 : édit de Milan de Constantin","points":7},{"critere":"380 : édit de Thessalonique de Théodose","points":7}],"dureeMin":6,"corrige":"1. En **64 apr. J.-C.**, sous **Néron**, les chrétiens sont **accusés de l’incendie de Rome** et persécutés.\n\n2. En **313**, par l’**édit de Milan**, **Constantin** accorde la **liberté de culte à tous**, y compris aux chrétiens.\n\n3. En **380**, par l’**édit de Thessalonique**, **Théodose** fait du christianisme la **religion officielle** de l’Empire."}$exo$::jsonb),
  ('319cde17-8032-5331-9e3e-728d758e3a99'::uuid, 2, 'redaction', $exo${"titre":"Pourquoi les chrétiens sont-ils persécutés ?","consigne":"Lis le document puis réponds aux questions en phrases complètes, en utilisant le vocabulaire du cours.","enonce":"**Document — Face au gouverneur (dialogue imaginé)**\n\n> — Le gouverneur : « Offre de l’encens devant la statue de l’empereur, et tu seras libre. »\n> — Le chrétien : « Je respecte l’empereur, mais je n’adore qu’un seul Dieu. Je ne peux pas faire ce que tu demandes. »\n> — Le gouverneur : « Alors tu es un ennemi de Rome. »\n\n1. Quelle est la condition posée par Rome pour tolérer tous les cultes ?\n2. Pourquoi le chrétien refuse-t-il d’obéir ? Utilise le mot du cours qui désigne la croyance en un seul Dieu.\n3. Pourquoi le gouverneur considère-t-il ce refus comme un acte d’ennemi ? Cite **une** autre raison de la méfiance envers les chrétiens.\n4. Comment appelle-t-on un chrétien tué pour sa foi ? Que signifie ce mot ?","bareme":[{"critere":"Condition de tolérance de Rome","points":4},{"critere":"Refus lié au monothéisme","points":5},{"critere":"Refus perçu comme déloyauté politique et autre raison","points":6},{"critere":"Martyr et sens du mot","points":5}],"dureeMin":10,"corrige":"1. Rome tolère tous les cultes à condition d’**honorer l’empereur et les dieux de Rome** (le culte impérial).\n\n2. Le chrétien est **monothéiste** : il n’adore qu’**un seul Dieu**. Il refuse donc de **rendre un culte à l’empereur**.\n\n3. Pour Rome, ce refus n’est pas une simple opinion religieuse : c’est un acte de **déloyauté politique**, car le culte impérial montre la fidélité à l’empereur. Autres raisons (une au choix) : les **rumeurs** nées du secret de leurs réunions ; la **méfiance** envers un groupe qui se tient à l’écart des **fêtes civiques**.\n\n4. C’est un **martyr**. Ce mot grec signifie **« témoin »**."}$exo$::jsonb),
  ('319cde17-8032-5331-9e3e-728d758e3a99'::uuid, 3, 'redaction', $exo${"titre":"De la persécution à la religion officielle","consigne":"Réponds aux questions en phrases complètes ; la question 4 demande un court paragraphe argumenté.","enonce":"**Document — Une phrase du cours**\n\n> « Persécuter une croyance en fabrique les héros. Rome l’a expérimenté à ses dépens. »\n\n1. Les persécutions ont-elles été continues ? Cite **deux** persécutions en précisant l’empereur et la date ou le siècle.\n2. Explique la phrase du document.\n3. Présente les **trois** étapes du tournant du IVe siècle (dates, empereurs, décisions). Qu’arrive-t-il ensuite aux cultes païens ?\n4. Compare, en quelques lignes, la situation des chrétiens en 64 et en 380.\n5. Explique le sens du mot **Église** et le rôle des **évêques** et des **conciles**. Cite **deux** traces laissées par les premiers chrétiens.","bareme":[{"critere":"Persécutions intermittentes et deux exemples","points":4},{"critere":"Explication de la phrase sur les martyrs","points":3},{"critere":"Les trois étapes du IVe siècle et les cultes païens","points":5},{"critere":"Comparaison argumentée entre 64 et 380","points":4},{"critere":"Organisation de l’Église et traces","points":4}],"dureeMin":18,"corrige":"1. Non : les persécutions sont **intermittentes** et souvent **locales**. Exemples (deux au choix) : sous **Néron** en **64 apr. J.-C.** ; les persécutions générales sous **Dèce** au **IIIe siècle** ; la persécution de **Dioclétien** en **303-311**, la plus violente.\n\n2. En tuant des chrétiens, Rome en fait des **martyrs**, vénérés par les autres chrétiens comme des **témoins** de leur foi. Au lieu de faire disparaître le christianisme, les persécutions lui ont donné des **héros** qui ont renforcé la foi des croyants.\n\n3. - **313** : l’**édit de Milan** de **Constantin** accorde la **liberté de culte** à tous.\n- **325** : **Constantin** convoque le **concile de Nicée**.\n- **380** : l’**édit de Thessalonique** de **Théodose** fait du christianisme la **religion officielle**.\nEnsuite, les **cultes païens sont interdits**.\n\n4. En **64**, les chrétiens sont une minorité **persécutée** : Néron les accuse de l’incendie de Rome. En **380**, le christianisme devient la **religion officielle** de l’Empire. **En moins d’un siècle** après la dernière grande persécution (303-311), les persécutés sont devenus la religion d’État : la situation s’est complètement **renversée**.\n\n5. L’**Église** (*ekklesia*) désigne d’abord la **communauté** des chrétiens. Les **évêques** dirigent les communautés urbaines ; l’évêque de **Rome** acquiert une autorité particulière. Les **conciles** réunissent les évêques pour **fixer la doctrine**. Traces (deux au choix) : les **catacombes**, les premières **basiliques**, les **sarcophages sculptés**, le **poisson** (*ichthus*), symbole discret."}$exo$::jsonb),
  ('8090486b-a1d1-5e4f-9d10-f55838f83069'::uuid, 1, 'redaction', $exo${"titre":"La Chine des Han : dates et vocabulaire","consigne":"Réponds à chaque question par une ou deux phrases complètes, en t'appuyant sur ton cours.","enonce":"1. Qui est Qin Shi Huangdi et que se passe-t-il en 221 av. J.-C. ?\n2. Entre quelles dates règne la dynastie Han ?\n3. Donne la définition du **mandat céleste**.\n4. Cite deux inventions chinoises de l'époque des Han.","bareme":[{"critere":"Qin Shi Huangdi et l'unification de 221 av. J.-C.","points":6},{"critere":"Dates de la dynastie Han et définition du mandat céleste","points":8},{"critere":"Deux inventions chinoises citées","points":6}],"dureeMin":6,"corrige":"1. Qin Shi Huangdi est le **premier empereur** de Chine : en 221 av. J.-C., il **unifie la Chine** et prend le titre de premier empereur.\n2. La dynastie Han règne de **206 av. J.-C. à 220 apr. J.-C.**\n3. Le mandat céleste est le pouvoir que le Ciel confie à l'empereur, appelé **Fils du Ciel**. Ce mandat peut se **perdre** : une catastrophe naturelle ou une révolte peut être vue comme son retrait.\n4. Deux inventions parmi : le **papier** (vers 105 apr. J.-C.), la **brouette**, le **gouvernail d'étambot**, le **sismographe**, la **fonte du fer**, la **boussole**."}$exo$::jsonb),
  ('8090486b-a1d1-5e4f-9d10-f55838f83069'::uuid, 2, 'redaction', $exo${"titre":"Gouverner un immense empire : l'organisation de la Chine des Han","consigne":"Lis le document puis réponds aux questions en phrases complètes.","enonce":"**Document** – Un fonctionnaire imaginé à l'époque des Han\n\n> « Je suis né dans une famille modeste. J'ai étudié pendant des années les textes de Confucius. J'ai réussi le concours et je suis devenu fonctionnaire. Je sers le Fils du Ciel et je veille à ce que chacun respecte ses aînés et fasse son devoir. »\n\n1. Comment ce personnage est-il devenu fonctionnaire ? Explique pourquoi cette façon de recruter est originale par rapport à Rome.\n2. Qui est le « Fils du Ciel » ? D'où vient son pouvoir ?\n3. Relève dans le document les idées qui viennent de la pensée de Confucius.\n4. Explique en une phrase pourquoi le pouvoir de l'empereur est « absolu, mais jamais garanti ».","bareme":[{"critere":"Recrutement sur concours et comparaison avec Rome","points":6},{"critere":"Identification de l'empereur et du mandat céleste","points":5},{"critere":"Idées de Confucius relevées dans le document","points":5},{"critere":"Explication du pouvoir absolu mais fragile","points":4}],"dureeMin":10,"corrige":"1. Il est devenu fonctionnaire en **réussissant un concours**, après avoir étudié longtemps : c'est un **fonctionnaire lettré**. Ce recrutement sur concours est une **invention chinoise** qui n'a **aucun équivalent à Rome**.\n2. Le Fils du Ciel est **l'empereur**. Son pouvoir vient du **Ciel** : il détient le **mandat céleste**.\n3. Idées de Confucius : le **respect des aînés**, le **devoir** (« fasse son devoir »), et plus largement l'**ordre social**.\n4. L'empereur a tous les pouvoirs, mais le mandat céleste peut **se perdre** : une **catastrophe naturelle** ou une **révolte** peut être comprise comme le signe que le Ciel lui retire son mandat."}$exo$::jsonb),
  ('8090486b-a1d1-5e4f-9d10-f55838f83069'::uuid, 3, 'redaction', $exo${"titre":"Rome et la Chine des Han : deux empires aux deux bouts du monde","consigne":"Réponds aux questions en t'appuyant sur le cours, puis rédige un court paragraphe argumenté.","enonce":"**Document** – La route de la soie\n\n| Ce qui circule | Exemples |\n|---|---|\n| Des marchandises | Soie, épices, verre, métaux |\n| Des idées | Religions, techniques |\n| Et aussi | Des épidémies |\n\nTrajet : la Chine → l'Asie centrale → la Perse → la Méditerranée.\n\n1. Qin Shi Huangdi prend le titre de premier empereur en 221 av. J.-C. et la dynastie Han commence en 206 av. J.-C. Calcule combien d'années a duré la dynastie Qin. Quelle phrase du cours ce résultat confirme-t-il ?\n2. Cite deux mesures de Qin Shi Huangdi qui ont servi à unifier la Chine.\n3. À l'aide du document, explique ce que la route de la soie fait circuler entre la Chine et la Méditerranée. Pourquoi dit-on que presque personne ne la parcourait en entier ?\n4. Rédige un paragraphe de 5 à 6 lignes pour comparer la manière dont Rome et la Chine des Han rassemblent (intègrent) les peuples de leur empire.","bareme":[{"critere":"Calcul de la durée de la dynastie Qin et lien avec le cours","points":4},{"critere":"Deux mesures d'unification de Qin Shi Huangdi","points":4},{"critere":"Analyse du document sur la route de la soie","points":5},{"critere":"Paragraphe comparant Rome et la Chine","points":5},{"critere":"Qualité de la rédaction","points":2}],"dureeMin":18,"corrige":"1. 221 − 206 = **15 ans**. Les deux dates sont avant J.-C., on soustrait. Cela confirme que sa dynastie « **tombe très vite** ».\n2. Deux mesures parmi : il unifie **l'écriture**, les **poids et mesures**, la **monnaie** ; il lance aussi la **Grande Muraille**.\n3. La route de la soie fait circuler des **marchandises** (la soie, les épices, le verre, les métaux), des **idées** (des religions, des techniques) et aussi des **épidémies**. Elle traverse l'Asie centrale et la Perse : elle est très longue, et les marchandises passent de marchand en marchand. Presque personne ne fait tout le trajet, c'est pourquoi les deux empires **se connaissent à peine**.\n4. Paragraphe modèle : « Rome et la Chine des Han sont deux empires de taille comparable, situés aux deux bouts du même continent. Pourtant, ils ne rassemblent pas leurs peuples de la même façon. Rome intègre les peuples par la **citoyenneté** et le **droit**. La Chine, elle, les intègre grâce à une **administration de fonctionnaires lettrés**, recrutés sur concours, et à une **morale commune**, celle de **Confucius**, qui enseigne l'ordre social, le respect des aînés et le devoir. »"}$exo$::jsonb),
  ('6673b42e-c53c-5b4f-934a-5036903c6dc9'::uuid, 1, 'redaction', $exo${"titre":"Les premiers humains : qui, quand, comment ?","consigne":"Réponds à chaque question par une phrase complète.","enonce":"1. Sur quel continent commence l'histoire de l'humanité, et il y a environ combien d'années ?\n2. Comment s'appelle la période qui occupe plus de 99 % du temps humain ?\n3. Quelle espèce fabrique les premiers outils taillés, vers 2,5 millions d'années ?\n4. Explique ce que veulent dire les mots **chasseurs-cueilleurs** et **nomades**.","bareme":[{"critere":"Lieu, date et nom de la période","points":8},{"critere":"Espèce des premiers outils","points":4},{"critere":"Définitions de chasseurs-cueilleurs et nomades","points":8}],"dureeMin":6,"corrige":"1. L'histoire de l'humanité commence en **Afrique**, il y a environ **3 millions d'années**.\n2. C'est le **Paléolithique**.\n3. C'est *Homo habilis*, vers 2,5 millions d'années.\n4. Les **chasseurs-cueilleurs** prélèvent ce que la nature offre (gibier, fruits, plantes) **sans rien produire**. Les **nomades** **se déplacent** au rythme du gibier et des saisons ; ils n'ont pas d'habitat fixe."}$exo$::jsonb),
  ('6673b42e-c53c-5b4f-934a-5036903c6dc9'::uuid, 2, 'redaction', $exo${"titre":"Ce que les grandes acquisitions ont changé","consigne":"Réponds aux questions en expliquant avec tes propres mots.","enonce":"Voici les quatre grandes acquisitions des premiers humains, dans l'ordre : la bipédie → l'outil taillé → le feu → le langage, puis l'art.\n\n1. Qu'est-ce que la **bipédie** ? Quel avantage apporte-t-elle ?\n2. Cite deux formes d'outils taillés en allant du plus simple au plus élaboré.\n3. Le feu est maîtrisé par *Homo erectus*. Donne trois choses que le feu permet de faire.\n4. Pourquoi le langage est-il une acquisition importante pour un groupe humain ?","bareme":[{"critere":"Définition et avantage de la bipédie","points":5},{"critere":"Évolution des outils taillés","points":4},{"critere":"Utilités du feu","points":6},{"critere":"Rôle du langage expliqué","points":5}],"dureeMin":10,"corrige":"1. La bipédie est le fait de **marcher debout sur deux jambes**. Elle **libère les mains**, qui peuvent alors porter, tailler, fabriquer.\n2. On passe du **galet aménagé** (le plus simple) au **biface** (plus élaboré).\n3. Le feu permet de **se protéger** (des animaux), de **se chauffer**, de **s'éclairer** et de **cuire** les aliments (trois réponses parmi les quatre).\n4. Le langage permet de **transmettre** : les savoirs, les techniques, les expériences passent d'une personne à l'autre et des adultes aux enfants. Le groupe n'a pas besoin de tout réinventer à chaque génération."}$exo$::jsonb),
  ('6673b42e-c53c-5b4f-934a-5036903c6dc9'::uuid, 3, 'redaction', $exo${"titre":"L'art pariétal et le travail de l'historien de la Préhistoire","consigne":"Analyse les données proposées, fais les calculs demandés et justifie tes réponses.","enonce":"**Document** – Deux grottes ornées en France\n\n| La grotte | Son âge |\n|---|---|\n| Chauvet | environ 36 000 ans |\n| Lascaux | environ 18 000 ans |\n\n1. Quelle grotte est la plus ancienne ? Calcule l'écart d'âge entre les deux grottes. Combien de fois la plus ancienne est-elle plus âgée que l'autre ?\n2. *Homo neanderthalensis* disparaît d'Europe vers 40 000 ans. Quelle espèce humaine a donc probablement peint les deux grottes ? Justifie.\n3. Ces peintures d'animaux montrent une pensée **symbolique**. Explique cette idée à l'aide de l'exemple d'une main peinte sur une paroi.\n4. Il n'existe aucun texte écrit sur cette période. Explique comment l'historien peut quand même la connaître : quelles traces utilise-t-il, qui les met au jour, et comment leur donne-t-on un âge ?","bareme":[{"critere":"Comparaison et calculs sur les deux grottes","points":5},{"critere":"Identification de l'espèce avec justification","points":4},{"critere":"Explication de la pensée symbolique","points":5},{"critere":"Méthode de l'historien : traces, archéologie, carbone 14","points":6}],"dureeMin":16,"corrige":"1. **Chauvet** est la plus ancienne. Écart : 36 000 − 18 000 = **18 000 ans**. 36 000 ÷ 18 000 = **2** : Chauvet est **deux fois** plus âgée que Lascaux.\n2. Vers 40 000 ans, Néandertal a disparu d'Europe. Les deux grottes sont plus récentes (36 000 et 18 000 ans) : elles ont donc probablement été peintes par *Homo sapiens*, notre espèce, apparue vers 300 000 ans en Afrique.\n3. Une pensée symbolique, c'est la capacité à représenter une idée par une image ou un signe. Une main peinte n'est pas un objet utile : c'est un **message**, comme pour dire « j'étais là ». Les peintures d'animaux, très réalistes, montrent aussi que ces humains pensaient et représentaient le monde.\n4. L'historien travaille sur des **traces** : outils, ossements, foyers, peintures. L'**archéologie** les met au jour par des fouilles, et le **carbone 14** permet de leur donner un **âge**."}$exo$::jsonb),
  ('35dc3602-2b63-5b54-8133-cb1904a11de1'::uuid, 1, 'redaction', $exo${"titre":"Les grandes étapes du peuplement de la Terre","consigne":"Réponds à chaque question par une phrase complète.","enonce":"1. De quel continent *Homo sapiens* est-il parti pour peupler la planète ?\n2. Classe dans l'ordre chronologique l'arrivée des humains sur ces trois continents : l'Amérique, l'Europe, l'Australie. Donne une date approximative pour chacun.\n3. Cite deux raisons qui poussent les premiers humains à se déplacer.","bareme":[{"critere":"Continent de départ","points":4},{"critere":"Ordre chronologique et dates","points":9},{"critere":"Deux causes des migrations","points":7}],"dureeMin":7,"corrige":"1. *Homo sapiens* est parti d'**Afrique** (entre environ 100 000 et 60 000 ans, vers le Proche-Orient puis l'Asie).\n2. Ordre : l'**Australie** (vers 50 000 ans), puis l'**Europe** (vers 45 000 ans), puis l'**Amérique** (entre 20 000 et 15 000 ans).\n3. Deux raisons parmi : suivre le **gibier et les ressources** ; les **variations du climat** (une région devient vivable, une autre non) ; l'**augmentation des groupes**, qui ont besoin de place."}$exo$::jsonb),
  ('35dc3602-2b63-5b54-8133-cb1904a11de1'::uuid, 2, 'redaction', $exo${"titre":"Comment les humains ont atteint l'Australie et l'Amérique","consigne":"Réponds aux questions en expliquant et en justifiant.","enonce":"1. Les humains atteignent l'Australie vers 50 000 ans en franchissant des bras de mer. Qu'est-ce que cela nous apprend sur leurs techniques ?\n2. Vers 20 000 à 15 000 ans, les humains entrent en Amérique par le détroit de Béring. Explique pourquoi ils ont pu y passer **à pied**.\n3. Un camarade écrit : « Un groupe d'humains est parti d'Afrique pour aller en Australie. » Explique pourquoi cette phrase est fausse et corrige-la.","bareme":[{"critere":"Déduction sur la navigation","points":5},{"critere":"Explication du passage de Béring par la glaciation","points":7},{"critere":"Correction de l'idée reçue sur le voyage","points":6},{"critere":"Rédaction claire","points":2}],"dureeMin":10,"corrige":"1. Pour franchir des bras de mer, il fallait **naviguer** : ces humains savaient donc fabriquer des embarcations.\n2. Pendant la **glaciation**, une grande quantité d'eau était **piégée dans les glaces**. Le **niveau des mers avait baissé** : le détroit de Béring était **à sec**. Ce n'était pas une traversée en mer, mais un passage à pied entre l'Asie et l'Amérique.\n3. La phrase est fausse car ces déplacements se comptent en **millénaires**. Personne n'est « parti pour l'Australie » : **chaque génération s'installait un peu plus loin**. Correction : « De génération en génération, les humains se sont installés de plus en plus loin de l'Afrique, jusqu'à atteindre l'Australie. »"}$exo$::jsonb),
  ('35dc3602-2b63-5b54-8133-cb1904a11de1'::uuid, 3, 'redaction', $exo${"titre":"S'adapter à tous les milieux, une seule humanité","consigne":"Réponds aux questions puis rédige un court paragraphe argumenté.","enonce":"**Document** – Des humains dans des milieux très différents\n\n| Le milieu | La solution technique |\n|---|---|\n| Le froid | Vêtements cousus, lampes à graisse |\n| Les tropiques | Habitats légers |\n| Les côtes | Techniques de pêche |\n\n1. Choisis deux milieux du tableau et explique en quoi la solution technique aide les humains à y vivre.\n2. Explique la phrase : « L'humain n'est pas fait pour un milieu : il fabrique de quoi vivre dans tous. »\n3. Quelle science a confirmé que l'humanité est partie d'Afrique ? Qu'étudie-t-elle ?\n4. Rédige un paragraphe de 4 à 5 lignes expliquant ce que la génétique nous apprend sur les différences entre les groupes humains d'aujourd'hui.","bareme":[{"critere":"Analyse de deux solutions techniques","points":6},{"critere":"Explication de la phrase sur l'adaptation","points":4},{"critere":"La génétique et l'étude de l'ADN","points":4},{"critere":"Paragraphe sur l'unité de l'espèce humaine","points":6}],"dureeMin":15,"corrige":"1. Exemples : dans le **froid**, les **vêtements cousus** gardent la chaleur du corps et les **lampes à graisse** éclairent et réchauffent l'abri. Sous les **tropiques**, il fait chaud : des **habitats légers** suffisent et se construisent vite. Sur les **côtes**, les **techniques de pêche** permettent de se nourrir des ressources de la mer.\n2. Le corps humain n'est pas adapté à tous les climats, mais les humains **inventent des techniques** (vêtements, abris, outils) qui leur permettent de vivre partout.\n3. C'est la **génétique** : elle étudie l'**ADN**. Elle confirme le scénario africain et retrace les routes du peuplement.\n4. Paragraphe modèle : « L'étude de l'ADN montre que tous les humains actuels descendent d'ancêtres venus d'Afrique. Elle montre aussi que les différences génétiques entre les groupes humains sont **très faibles**. L'humanité forme donc **une seule espèce**, et il n'existe **pas de races biologiques** chez les humains. »"}$exo$::jsonb),
  ('2b58a6c6-e44d-5f29-b556-1b1d91239d83'::uuid, 1, 'redaction', $exo${"titre":"La révolution néolithique : l'essentiel","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Vers quelle date et dans quelle région commence la révolution néolithique ?\n2. Quelles sont les deux grandes inventions du Néolithique ? Donne un exemple pour chacune.\n3. Que signifie le mot **sédentarisation** ?","bareme":[{"critere":"Date et lieu de la révolution néolithique","points":6},{"critere":"Agriculture et élevage avec exemples","points":8},{"critere":"Définition de la sédentarisation","points":6}],"dureeMin":6,"corrige":"1. Elle commence vers **10 000 av. J.-C.**, au **Proche-Orient**, dans le **Croissant fertile**.\n2. L'**agriculture** : on sème et on récolte, par exemple le blé, l'orge ou les lentilles. L'**élevage** : on domestique des animaux, par exemple la chèvre, le mouton, le bœuf ou le porc.\n3. La sédentarisation, c'est le fait de **s'installer durablement au même endroit** : les humains construisent des **villages permanents** au lieu de se déplacer."}$exo$::jsonb),
  ('2b58a6c6-e44d-5f29-b556-1b1d91239d83'::uuid, 2, 'redaction', $exo${"titre":"Du champ au village : la chaîne du Néolithique","consigne":"Réponds aux questions en expliquant chaque étape du raisonnement.","enonce":"1. Le Néolithique apparaît au Proche-Orient vers 10 000 av. J.-C. et gagne l'Europe à partir de 7000 av. J.-C. Calcule combien d'années séparent ces deux dates.\n2. Le Néolithique apparaît aussi en Chine, en Afrique et en Amérique. Est-ce que les habitants du Proche-Orient le leur ont appris ? Justifie.\n3. Explique en deux ou trois étapes pourquoi le fait de produire sa nourriture pousse les humains à se sédentariser.\n4. Qu'est-ce que la **domestication** ?","bareme":[{"critere":"Calcul de l'écart entre les deux dates","points":4},{"critere":"Plusieurs foyers indépendants justifiés","points":4},{"critere":"Enchaînement production, surveillance, village","points":7},{"critere":"Définition de la domestication","points":5}],"dureeMin":10,"corrige":"1. Les deux dates sont avant J.-C. : 10 000 − 7000 = **3 000 ans**.\n2. **Non** : le Néolithique y est apparu **indépendamment**. Il y a eu **plusieurs foyers**, **sans contact** entre eux.\n3. Les humains **produisent leur nourriture** (champs, troupeaux) → ils doivent **rester sur place pour surveiller** les champs et les troupeaux → ils construisent des **villages permanents**, avec des maisons en terre et des greniers : on ne repart plus.\n4. La domestication est la **sélection, de génération en génération, des plantes et des animaux les plus utiles** aux humains."}$exo$::jsonb),
  ('2b58a6c6-e44d-5f29-b556-1b1d91239d83'::uuid, 3, 'redaction', $exo${"titre":"Le grenier, naissance de la richesse et de l'inégalité","consigne":"Analyse la citation, explique les conséquences du Néolithique et justifie tes réponses.","enonce":"**Document** – Une phrase à réfléchir\n\n> « Tant qu'on ne stocke rien, il n'y a rien à posséder. Le grenier est aussi la naissance de la richesse — et de l'inégalité. »\n\n1. Qu'est-ce qu'un **surplus** ? Pourquoi les paysans du Néolithique peuvent-ils en avoir ?\n2. Explique pourquoi la population augmente au Néolithique.\n3. Pourquoi certaines personnes peuvent-elles devenir potiers, tisserands ou forgerons au lieu de cultiver ? Comment appelle-t-on ce phénomène ?\n4. Explique la citation du document : pourquoi le stockage peut-il créer des inégalités, alors que chez les chasseurs-cueilleurs nomades ce n'était pas le cas ?\n5. Les dolmens et menhirs de Carnac ou de Stonehenge montrent une société capable d'organiser de grands chantiers. Explique en une phrase le lien avec les surplus.","bareme":[{"critere":"Définition du surplus","points":3},{"critere":"Hausse de la population expliquée","points":3},{"critere":"La spécialisation des métiers","points":4},{"critere":"Analyse de la citation sur les inégalités","points":6},{"critere":"Lien entre surplus et monuments","points":4}],"dureeMin":18,"corrige":"1. Un surplus est une **quantité de nourriture produite en plus** de ce dont on a besoin tout de suite. Grâce à l'agriculture et à l'élevage, les paysans peuvent en produire et **les stocker** dans des greniers.\n2. Avec **plus de nourriture**, on peut nourrir **plus d'humains** : la population augmente.\n3. Les surplus permettent de nourrir des personnes qui ne cultivent pas : elles peuvent se consacrer à un métier (poterie, tissage, travail des métaux). C'est la **spécialisation**.\n4. Les chasseurs-cueilleurs nomades prélèvent ce que la nature offre et **ne stockent presque rien** : il n'y a rien à accumuler. Au Néolithique, ce qui se **stocke peut s'accumuler** : certains ont plus de réserves que d'autres, donc plus de **richesse**. Les **inégalités** apparaissent.\n5. Grâce aux surplus, la société peut **nourrir de nombreux travailleurs** pendant qu'ils construisent ces monuments, au lieu qu'ils cherchent leur nourriture."}$exo$::jsonb),
  ('9555367a-73aa-5b4e-a021-80e3d9a728c4'::uuid, 1, 'redaction', $exo${"titre":"Les premiers États : où et quand ?","consigne":"Réponds à chaque question par une phrase complète.","enonce":"1. Vers quelle date apparaissent les premiers États, et dans quelles deux régions ?\n2. Quel fleuve traverse l'Égypte ? Entre quels fleuves se trouve la Mésopotamie ?\n3. Cite deux choses que le fleuve apporte aux habitants.","bareme":[{"critere":"Date et régions des premiers États","points":6},{"critere":"Les fleuves de l'Égypte et de la Mésopotamie","points":8},{"critere":"Apports du fleuve","points":6}],"dureeMin":6,"corrige":"1. Les premiers États apparaissent vers **3500-3000 av. J.-C.**, en **Mésopotamie** et en **Égypte**.\n2. L'Égypte est traversée par le **Nil**. La Mésopotamie (l'Irak actuel) se trouve entre le **Tigre** et l'**Euphrate**.\n3. Deux apports parmi : l'**eau** ; des **crues** qui fertilisent les terres ; une **voie de transport**."}$exo$::jsonb),
  ('9555367a-73aa-5b4e-a021-80e3d9a728c4'::uuid, 2, 'redaction', $exo${"titre":"Qu'est-ce qu'un État ? L'exemple de l'Égypte des pharaons","consigne":"Réponds aux questions en t'appuyant sur le cours et sur le document.","enonce":"**Document** – L'Égypte des pharaons (d'après le cours)\n\n> Vers 3100 av. J.-C., la Haute et la Basse-Égypte sont unifiées. Le pharaon, roi divin, est maître des terres et des hommes. Des scribes tiennent les comptes et l'impôt est prélevé sur les récoltes. Vers 2500 av. J.-C., les pyramides de Gizeh sont construites.\n\n1. Cite les quatre éléments qui définissent un État.\n2. Relève dans le document deux éléments qui montrent que l'Égypte est un État.\n3. Calcule combien d'années séparent l'unification de l'Égypte et la construction des pyramides de Gizeh.\n4. À quoi servent les pyramides ?","bareme":[{"critere":"Les quatre éléments d'un État","points":6},{"critere":"Éléments relevés dans le document","points":6},{"critere":"Calcul de l'écart de dates","points":4},{"critere":"Fonction des pyramides","points":4}],"dureeMin":10,"corrige":"1. Un État, c'est : un **territoire** délimité, une **population**, un **pouvoir** (qui commande, prélève l'impôt, rend la justice), des **lois** et des **fonctionnaires**.\n2. Deux éléments parmi : un **pouvoir** (le pharaon, maître des terres et des hommes) ; des **fonctionnaires** (les scribes) ; l'**impôt** prélevé ; un **territoire** unifié (Haute et Basse-Égypte).\n3. Les deux dates sont avant J.-C. : 3100 − 2500 = **600 ans**.\n4. Les pyramides sont des **tombeaux** pour les pharaons."}$exo$::jsonb),
  ('9555367a-73aa-5b4e-a021-80e3d9a728c4'::uuid, 3, 'redaction', $exo${"titre":"L'eau, le travail et le pouvoir en Mésopotamie et en Égypte","consigne":"Explique les liens entre les notions et justifie chaque réponse.","enonce":"1. Explique en trois étapes comment le besoin d'**irriguer** les terres conduit à la naissance d'un pouvoir central.\n2. Décris une cité mésopotamienne : cite deux exemples de cités et trois éléments que possède chacune d'elles.\n3. Explique la phrase : « Une pyramide ne dit pas seulement la foi dans l'au-delà : elle dit qu'un homme pouvait mobiliser des dizaines de milliers de bras pendant vingt ans. »\n4. Décris la hiérarchie de la société, du haut vers le bas. Quel groupe forme l'immense majorité de la population ?","bareme":[{"critere":"Enchaînement irrigation, organisation, pouvoir central","points":6},{"critere":"Description de la cité mésopotamienne","points":4},{"critere":"Analyse de la phrase sur les pyramides","points":5},{"critere":"Hiérarchie sociale décrite dans l'ordre","points":5}],"dureeMin":16,"corrige":"1. Pour irriguer, il faut **creuser des canaux** → cela demande d'**organiser le travail de milliers de personnes** → un **pouvoir central** devient nécessaire pour commander et coordonner. Le besoin d'organisation collective « appelle » l'État.\n2. Exemples de cités : **Ur**, **Uruk**, **Lagash**. Chaque cité a son **roi**, son **dieu** et sa **ziggurat**, un temple à degrés qui domine la ville.\n3. Les pyramides sont des tombeaux liés à la croyance en l'au-delà. Mais leur construction montre aussi la **puissance du pharaon** : il pouvait faire travailler un nombre immense d'hommes pendant très longtemps. C'est la preuve d'un **pouvoir très fort et très organisé**.\n4. De haut en bas : le **roi** → les **prêtres, scribes et guerriers** → les **paysans et artisans** → les **esclaves**. Les **paysans et artisans** forment l'immense majorité."}$exo$::jsonb),
  ('1976076f-7fc1-5f7a-aba7-5626baff0252'::uuid, 1, 'redaction', $exo${"titre":"Cité-État, royaume, empire","consigne":"Réponds à chaque question par une phrase complète.","enonce":"1. Situe le Croissant fertile : de quelle région à quelle région s'étend-il ?\n2. Donne la définition d'une **cité-État** et cite un exemple.\n3. Donne la définition d'un **empire** et cite un exemple.","bareme":[{"critere":"Localisation du Croissant fertile","points":6},{"critere":"Définition et exemple de la cité-État","points":7},{"critere":"Définition et exemple de l'empire","points":7}],"dureeMin":6,"corrige":"1. Le Croissant fertile est une bande de terres en forme d'arc qui va du **golfe Persique** à l'**Égypte**, en passant par la **Mésopotamie** et le **Levant**.\n2. Une cité-État est **une ville et son territoire, dirigés par un roi**. Exemple : **Ur**, Uruk ou Mari.\n3. Un empire est **la domination d'un peuple sur beaucoup d'autres peuples**. Exemple : **Akkad**, Babylone ou l'Assyrie."}$exo$::jsonb),
  ('1976076f-7fc1-5f7a-aba7-5626baff0252'::uuid, 2, 'redaction', $exo${"titre":"Le code de Hammurabi : une loi écrite","consigne":"Lis le document et réponds aux questions en phrases complètes.","enonce":"**Document** – Le code de Hammurabi\n\n> Vers 1750 av. J.-C., le roi Hammurabi fait graver à Babylone près de 300 articles de loi sur une stèle de pierre, exposée à la vue de tous. Les peines dépendent de la gravité de la faute, mais aussi du rang social de la victime et du coupable.\n\n1. Qui est Hammurabi ? Où et quand fait-il graver son code ?\n2. Sur quel support le code est-il gravé ? Combien d'articles contient-il environ ?\n3. Relève trois nouveautés apportées par ce code.\n4. Ce code rend-il tous les habitants égaux devant la loi ? Justifie à l'aide du document.","bareme":[{"critere":"Présentation de Hammurabi, lieu et date","points":4},{"critere":"Support et nombre d'articles","points":4},{"critere":"Trois nouveautés du code","points":6},{"critere":"Réponse justifiée sur l'inégalité des peines","points":6}],"dureeMin":10,"corrige":"1. Hammurabi est un **roi de Babylone**. Il fait graver son code à **Babylone** vers **1750 av. J.-C.**\n2. Le code est gravé sur une **stèle de pierre** ; il contient près de **300 articles**.\n3. La loi est **écrite** (la même pour des cas semblables) ; elle est **publique** (exposée à la vue de tous) ; les **peines sont graduées** selon la gravité de la faute.\n4. **Non**. Le document dit que les peines dépendent aussi du **rang social** de la victime et du coupable. Écrire la loi la rend **connaissable**, mais **pas égalitaire**."}$exo$::jsonb),
  ('1976076f-7fc1-5f7a-aba7-5626baff0252'::uuid, 3, 'redaction', $exo${"titre":"Des empires fragiles, des inventions qui durent","consigne":"Réponds aux questions puis rédige un paragraphe argumenté.","enonce":"1. Sargon fonde l'empire d'Akkad vers 2300 av. J.-C. et Hammurabi fait graver son code vers 1750 av. J.-C. Calcule le nombre d'années entre ces deux événements.\n2. Explique la différence entre un **royaume** et un **empire**.\n3. Cite deux produits qui circulent dans le Croissant fertile et leur région d'origine. Qu'est-ce que le commerce diffuse en plus des marchandises ?\n4. Cite deux raisons qui expliquent pourquoi ces empires ne durent pas.\n5. Rédige un paragraphe de 4 à 5 lignes pour expliquer ce qui subsiste de ces empires disparus.","bareme":[{"critere":"Calcul de l'écart entre Sargon et Hammurabi","points":3},{"critere":"Différence entre royaume et empire","points":4},{"critere":"Échanges et diffusion des techniques et idées","points":5},{"critere":"Causes de la fragilité des empires","points":3},{"critere":"Paragraphe sur l'héritage de ces empires","points":5}],"dureeMin":17,"corrige":"1. Les deux dates sont avant J.-C. : 2300 − 1750 = **550 ans**.\n2. Un **royaume** est un ensemble plus large qu'une cité, placé sous un même roi. Un **empire** est la **domination d'un peuple sur beaucoup d'autres peuples**.\n3. Exemples : le **bois du Liban**, les **métaux d'Anatolie** (on peut aussi citer les pierres précieuses). Le commerce diffuse aussi les **techniques**, les **écritures** et les **croyances**.\n4. Deux raisons parmi : les **conquêtes**, les **révoltes**, les **sécheresses**, les **invasions**.\n5. Paragraphe modèle : « Les empires du Croissant fertile, comme Akkad ou Babylone, n'ont pas duré. Pourtant, leurs **inventions** ont traversé le temps : l'**écriture**, le **droit**, dont le code de Hammurabi est un exemple, et l'**administration**. Ces inventions ont été reprises par les peuples suivants. »"}$exo$::jsonb),
  ('37f2fa20-b39b-54b2-8e0f-f66709d451a9'::uuid, 1, 'redaction', $exo${"titre":"L'invention de l'écriture","consigne":"Réponds à chaque question par une phrase complète.","enonce":"1. Où et vers quelle date l'écriture est-elle inventée ?\n2. Quelle grande période se termine avec l'invention de l'écriture, et laquelle commence ?\n3. À quoi servaient les premières tablettes écrites ?","bareme":[{"critere":"Lieu et date de l'invention","points":6},{"critere":"Fin de la Préhistoire et début de l'Histoire","points":6},{"critere":"Usage comptable des premières tablettes","points":8}],"dureeMin":5,"corrige":"1. L'écriture est inventée en **Mésopotamie**, vers **3300 av. J.-C.**\n2. L'invention de l'écriture marque la **fin de la Préhistoire** et le **début de l'Histoire**.\n3. Les premières tablettes servaient à **compter** : ce sont des **comptes** (sacs de grain, têtes de bétail, dettes). L'écriture naît d'un **besoin d'administration**, pas pour la littérature."}$exo$::jsonb),
  ('37f2fa20-b39b-54b2-8e0f-f66709d451a9'::uuid, 2, 'redaction', $exo${"titre":"Cunéiforme, hiéroglyphes, alphabet : trois écritures","consigne":"Complète tes connaissances en répondant aux questions par des phrases.","enonce":"1. Décris l'écriture **cunéiforme** : où l'utilise-t-on, sur quel support, avec quel outil ? D'où vient son nom ?\n2. Où utilise-t-on les **hiéroglyphes** et sur quels supports ? Quels types de signes utilisent-ils ?\n3. Qui a déchiffré les hiéroglyphes, en quelle année et grâce à quel objet ?\n4. Pourquoi a-t-on retrouvé des centaines de milliers de tablettes cunéiformes ?","bareme":[{"critere":"Description du cunéiforme et origine du nom","points":6},{"critere":"Description des hiéroglyphes","points":5},{"critere":"Déchiffrement par Champollion","points":5},{"critere":"Conservation des tablettes d'argile","points":4}],"dureeMin":10,"corrige":"1. Le cunéiforme est utilisé en **Mésopotamie**. On écrit sur de l'**argile fraîche** avec un **calame**, qui imprime des signes en forme de **coins**. Le mot vient du latin *cuneus*, qui veut dire « **coin** ».\n2. Les hiéroglyphes sont utilisés en **Égypte**, sur les **murs des temples** et sur du **papyrus**. Ils mêlent des **signes de sons** et des **signes de choses**.\n3. C'est **Champollion**, en **1822**, grâce à la **pierre de Rosette**.\n4. Les tablettes d'**argile séchée se conservent** très bien dans le temps : c'est pourquoi il en subsiste des centaines de milliers."}$exo$::jsonb),
  ('37f2fa20-b39b-54b2-8e0f-f66709d451a9'::uuid, 3, 'redaction', $exo${"titre":"De l'alphabet au pouvoir des scribes","consigne":"Analyse et justifie chacune de tes réponses, puis rédige un court paragraphe.","enonce":"1. L'écriture est inventée vers 3300 av. J.-C. et les Phéniciens mettent au point l'alphabet vers 1200-1000 av. J.-C. Calcule combien d'années séparent l'invention de l'écriture du début de la mise au point de l'alphabet (vers 1200 av. J.-C.).\n2. Explique ce que les Phéniciens puis les Grecs ont apporté à l'alphabet.\n3. Explique la phrase : « Passer de plusieurs centaines de signes à une vingtaine, c'est mettre l'écriture à la portée de bien plus de gens. »\n4. Rédige un paragraphe de 4 à 5 lignes pour expliquer pourquoi, dans ces sociétés, « savoir écrire, c'est détenir un pouvoir ». Appuie-toi sur le métier de scribe.","bareme":[{"critere":"Calcul de l'écart de dates","points":3},{"critere":"Apports des Phéniciens et des Grecs","points":5},{"critere":"Explication de la simplification de l'écriture","points":5},{"critere":"Paragraphe sur le pouvoir des scribes","points":5},{"critere":"Qualité de la rédaction","points":2}],"dureeMin":16,"corrige":"1. Les deux dates sont avant J.-C. : 3300 − 1200 = **2 100 ans**, soit environ deux millénaires.\n2. Les **Phéniciens** créent un alphabet d'une **vingtaine de signes** qui notent les **consonnes**. Les **Grecs** y ajoutent les **voyelles**. C'est l'**ancêtre direct de notre alphabet**.\n3. Le cunéiforme et les hiéroglyphes demandent d'apprendre **des centaines de signes** : seuls quelques spécialistes y arrivent. Avec une vingtaine de signes, l'écriture est **beaucoup plus facile à apprendre**, donc **plus de personnes** peuvent lire et écrire.\n4. Paragraphe modèle : « Dans les premiers États, écrire est un **métier** réservé à quelques-uns : les **scribes**, longuement formés. Ils **tiennent les comptes**, **rédigent les lois** et **les contrats**. Ils sont indispensables au roi pour administrer et prélever l'impôt. Ils occupent donc une **position sociale élevée** : savoir écrire donne un pouvoir. »"}$exo$::jsonb),
  ('6cf3b2bf-2e25-5d98-b8be-0697e54e7ef7'::uuid, 1, 'redaction', $exo${"titre":"Où vivent les humains ?","consigne":"Réponds à chaque question par une phrase complète.","enonce":"1. Combien d'habitants compte environ la Terre ?\n2. Que signifie le mot **écoumène** ?\n3. Cite les trois grands foyers de peuplement du monde.\n4. Cite deux types de « vides » humains et un exemple pour chacun.","bareme":[{"critere":"Population mondiale et définition de l'écoumène","points":6},{"critere":"Les trois grands foyers de peuplement","points":6},{"critere":"Deux types de vides avec exemples","points":8}],"dureeMin":7,"corrige":"1. La Terre compte environ **8 milliards** d'habitants.\n2. L'écoumène est **la partie de la Terre habitée en permanence** par les humains.\n3. L'**Asie du Sud** (Inde, Pakistan, Bangladesh), l'**Asie de l'Est** (Chine, Japon, Corées) et l'**Europe**.\n4. Deux types parmi : les **déserts chauds** (Sahara, Arabie, Australie centrale) ; les **déserts froids** (Sibérie, Groenland, Antarctique) ; les **hautes montagnes** (Himalaya, Andes) ; les **forêts denses** (Amazonie, Congo)."}$exo$::jsonb),
  ('6cf3b2bf-2e25-5d98-b8be-0697e54e7ef7'::uuid, 2, 'redaction', $exo${"titre":"Expliquer la répartition de la population","consigne":"Réponds aux questions en expliquant avec des exemples tirés du cours.","enonce":"1. Les terres émergées couvrent 30 % de la planète. Quelle part de la surface de la planète est donc couverte par les mers et les océans ?\n2. Cite trois facteurs **naturels** qui favorisent le peuplement.\n3. La vallée du Nil est très peuplée. Explique pourquoi, en utilisant un facteur naturel et un facteur historique.\n4. Explique pourquoi le Sahara et le Groenland sont presque vides d'habitants.","bareme":[{"critere":"Calcul de la part des mers et océans","points":3},{"critere":"Trois facteurs naturels","points":6},{"critere":"Explication de la densité de la vallée du Nil","points":6},{"critere":"Explication des vides du Sahara et du Groenland","points":5}],"dureeMin":10,"corrige":"1. 100 % − 30 % = **70 %** de la planète est couverte par les mers et les océans.\n2. Trois facteurs parmi : un **climat tempéré**, la présence d'**eau**, des **sols fertiles**, un **relief accessible**, la **proximité de la mer**.\n3. Facteur naturel : le **fleuve** apporte l'**eau** et des terres fertiles dans une région désertique. Facteur historique : la vallée est **peuplée depuis 5 000 ans** ; les foyers anciens restent peuplés. C'est cette **histoire**, autant que le fleuve, qui explique sa densité.\n4. Le **Sahara** est un **désert chaud** : il y fait très chaud et l'eau manque. Le **Groenland** est un **désert froid** : le climat glacial rend la vie très difficile. Les conditions naturelles y sont trop dures pour un peuplement dense."}$exo$::jsonb),
  ('6cf3b2bf-2e25-5d98-b8be-0697e54e7ef7'::uuid, 3, 'redaction', $exo${"titre":"Lire et comparer deux cartes de densité","consigne":"Analyse les deux légendes, justifie ta réponse, puis rédige un paragraphe sur les dynamiques du peuplement.","enonce":"**Document** – Les légendes de deux cartes de densité (cartes imaginaires)\n\n| Couleur | Carte A | Carte B |\n|---|---|---|\n| Jaune clair | moins de 10 hab./km² | moins de 50 hab./km² |\n| Orange | de 10 à 100 hab./km² | de 50 à 500 hab./km² |\n| Rouge foncé | plus de 100 hab./km² | plus de 500 hab./km² |\n\nUne région R est en **rouge foncé** sur la carte A. Une région S est en **rouge foncé** sur la carte B.\n\n1. Rappelle les trois étapes pour lire une carte de densité.\n2. Que peut-on affirmer sur la densité de la région R ? Et sur celle de la région S ?\n3. Un élève dit : « R et S sont en rouge foncé, donc elles ont la même densité. » A-t-il raison ? Justifie.\n4. Une région T a une densité de 80 hab./km². Donne sa couleur sur la carte A, puis sur la carte B.\n5. Rédige un paragraphe de 3 à 4 lignes : pourquoi la répartition de la population est-elle un « phénomène qui bouge » ?","bareme":[{"critere":"Étapes de lecture d'une carte de densité","points":3},{"critere":"Lecture des légendes pour R et S","points":4},{"critere":"Réfutation justifiée de l'affirmation","points":5},{"critere":"Couleur de la région T sur chaque carte","points":4},{"critere":"Paragraphe sur les évolutions du peuplement","points":4}],"dureeMin":17,"corrige":"1. **Repérer les aplats de couleur** → **lire la légende** → **comparer**.\n2. La région R a une densité de **plus de 100 hab./km²**. La région S a une densité de **plus de 500 hab./km²**.\n3. **Non**. Les deux cartes utilisent la même couleur mais **des seuils très différents**. R peut avoir par exemple 150 hab./km², ce qui est rouge foncé sur la carte A mais seulement orange sur la carte B. Sans lire la légende, une carte de densité ne se lit pas.\n4. 80 est entre 10 et 100 : sur la carte A, T est **orange**. 80 est entre 50 et 500 : sur la carte B, T est aussi **orange**.\n5. Paragraphe modèle : « La répartition des humains change avec le temps. L'**urbanisation** concentre la population dans les villes, les **migrations** déplacent des habitants d'une région à une autre, et la **croissance démographique** est très inégale selon les régions : certaines gagnent beaucoup d'habitants, d'autres peu. »"}$exo$::jsonb),
  ('e5de074a-b0ba-58c1-825e-eeade04e8a46'::uuid, 1, 'redaction', $exo${"titre":"Les mots de la démographie","consigne":"Réponds à chaque question par une phrase complète.","enonce":"1. Écris la formule de l'**accroissement naturel**.\n2. Écris la formule du **solde migratoire**.\n3. Combien d'humains y avait-il vers 1800, en 1950 et aujourd'hui ?\n4. Que mesure l'**indice de fécondité** ? Quel est le seuil de renouvellement des générations ?","bareme":[{"critere":"Formules de l'accroissement naturel et du solde migratoire","points":8},{"critere":"Évolution de la population mondiale","points":6},{"critere":"Indice de fécondité et seuil de renouvellement","points":6}],"dureeMin":6,"corrige":"1. Accroissement naturel = **natalité − mortalité** (naissances moins décès).\n2. Solde migratoire = **entrées − sorties** (personnes qui arrivent moins personnes qui partent).\n3. Vers 1800 : **1 milliard** ; en 1950 : **2,5 milliards** ; aujourd'hui : **8 milliards**.\n4. L'indice de fécondité mesure le **nombre moyen d'enfants par femme**. Le seuil de renouvellement est de **2,1** enfants par femme."}$exo$::jsonb),
  ('e5de074a-b0ba-58c1-825e-eeade04e8a46'::uuid, 2, 'redaction', $exo${"titre":"Calculer la variation de population d'un territoire","consigne":"Fais les calculs en montrant chaque étape, puis conclus par une phrase.","enonce":"**Données** – Un territoire imaginaire de 1 000 000 d'habitants, pendant une année\n\n| | Nombre |\n|---|---|\n| Naissances | 30 000 |\n| Décès | 10 000 |\n| Personnes arrivées (entrées) | 5 000 |\n| Personnes parties (sorties) | 8 000 |\n\n1. Calcule l'accroissement naturel de ce territoire.\n2. Calcule le solde migratoire. Est-il positif ou négatif ? Que cela signifie-t-il ?\n3. Calcule la variation totale de la population. Combien d'habitants le territoire compte-t-il à la fin de l'année ?\n4. Le taux de natalité se compte pour 1 000 habitants. Sachant que 30 000 naissances pour 1 000 000 d'habitants font 30 naissances pour 1 000 habitants, calcule de la même façon le taux de mortalité.","bareme":[{"critere":"Calcul de l'accroissement naturel","points":4},{"critere":"Calcul et interprétation du solde migratoire","points":5},{"critere":"Variation totale et population finale","points":6},{"critere":"Calcul du taux de mortalité","points":5}],"dureeMin":12,"corrige":"1. Accroissement naturel = naissances − décès = 30 000 − 10 000 = **+ 20 000** habitants.\n2. Solde migratoire = entrées − sorties = 5 000 − 8 000 = **− 3 000**. Il est **négatif** : **plus de personnes sont parties que de personnes arrivées**.\n3. Variation totale = accroissement naturel + solde migratoire = 20 000 + (− 3 000) = **+ 17 000** habitants. Population finale : 1 000 000 + 17 000 = **1 017 000 habitants**.\n4. 1 000 000 d'habitants, c'est 1 000 fois 1 000 habitants. 10 000 ÷ 1 000 = 10. Le taux de mortalité est de **10 décès pour 1 000 habitants** (10 ‰)."}$exo$::jsonb),
  ('e5de074a-b0ba-58c1-825e-eeade04e8a46'::uuid, 3, 'redaction', $exo${"titre":"La transition démographique et les idées reçues","consigne":"Analyse le tableau, fais les calculs et justifie tes réponses par des arguments du cours.","enonce":"**Document** – La transition démographique\n\n| Le régime | Natalité | Mortalité | Population |\n|---|---|---|---|\n| Ancien | Forte | Forte | Stable |\n| En transition | Forte | Elle chute | Elle explose |\n| Moderne | Faible | Faible | Stable, à un niveau plus élevé |\n\n1. Entre 1950 et aujourd'hui, de combien de milliards la population mondiale a-t-elle augmenté ?\n2. À l'aide du tableau, explique pourquoi la population « explose » pendant la transition. Qu'est-ce qui baisse en premier ?\n3. Un camarade affirme : « La population mondiale a explosé parce que les gens faisaient plus d'enfants. » Explique pourquoi c'est faux.\n4. Compare la situation de l'Afrique subsaharienne et celle de l'Europe ou du Japon. Cite un enjeu posé par le vieillissement.\n5. Environ 280 millions de personnes vivent hors de leur pays de naissance. Vérifie par un calcul que cela fait bien 3,5 % de 8 milliards. Puis corrige l'idée reçue : « La plupart des migrants vont des pays pauvres vers les pays riches. »","bareme":[{"critere":"Calcul de l'augmentation depuis 1950","points":3},{"critere":"Explication du décalage de la transition","points":5},{"critere":"Réfutation de l'idée d'un excès de naissances","points":4},{"critere":"Comparaison des régions et enjeu du vieillissement","points":4},{"critere":"Calcul du pourcentage et idée reçue sur les migrations","points":4}],"dureeMin":20,"corrige":"1. 8 − 2,5 = **5,5 milliards** d'humains en plus.\n2. Pendant la transition, la **mortalité chute** alors que la **natalité reste forte** : il y a beaucoup plus de naissances que de décès, donc la population augmente très vite. La clé est le **décalage** : la **mortalité baisse avant la natalité**.\n3. C'est faux : dans le régime ancien, la natalité était déjà forte. La population a explosé parce qu'**on mourait moins**, pas parce qu'on faisait plus d'enfants. C'est un **recul de la mort**.\n4. L'**Afrique subsaharienne** connaît une **forte croissance** et une population **très jeune** ; elle pourrait **doubler d'ici 2050**. L'**Europe** et le **Japon** ont une population qui **vieillit**, voire diminue. Enjeu : les **retraites**, la **santé** ou la **main-d'œuvre**.\n5. 8 milliards = 8 000 millions. 1 % de 8 000 millions = 80 millions ; 3,5 % = 3,5 × 80 = **280 millions**. C'est juste. Correction : **la majorité des migrations se font entre pays voisins**, et non des pays pauvres vers les pays riches."}$exo$::jsonb),
  ('62d1c622-02dd-5720-995f-b00bee66f852'::uuid, 1, 'redaction', $exo${"titre":"Les espaces urbains, périurbains et ruraux","consigne":"Réponds à chaque question par une phrase complète.","enonce":"1. En géographie, que veut dire **habiter** ? Cite au moins trois actions.\n2. Donne deux caractères de l'espace **urbain** et deux caractères de l'espace **rural**.\n3. Qu'est-ce qu'un espace **périurbain** ?","bareme":[{"critere":"Définition géographique de habiter","points":6},{"critere":"Caractères des espaces urbain et rural","points":8},{"critere":"Définition du périurbain","points":6}],"dureeMin":7,"corrige":"1. Habiter, ce n'est pas seulement loger : c'est **occuper, pratiquer, aménager et se représenter un espace**. Par exemple : y **dormir**, y **travailler**, s'y **déplacer**, s'y **divertir**.\n2. Urbain : **forte densité**, **bâti continu**, **services** (de la petite ville à la mégapole). Rural : **faible densité**, **agriculture**, **forêts**, **villages**.\n3. L'espace périurbain se trouve **entre la ville et la campagne** : on y trouve surtout des **maisons individuelles**, et ses habitants **travaillent en ville**."}$exo$::jsonb),
  ('62d1c622-02dd-5720-995f-b00bee66f852'::uuid, 2, 'redaction', $exo${"titre":"Les formes d'habitat et les liens entre ville et campagne","consigne":"Lis la situation, puis réponds aux questions en justifiant.","enonce":"**Situation** – Trois descriptions de paysages\n\n- **A** : des maisons serrées autour d'une place et d'une église.\n- **B** : des fermes isolées, séparées par des champs entourés de haies, dans l'Ouest de la France.\n- **C** : des maisons alignées le long d'une route.\n\n1. Nomme la forme d'habitat de chaque paysage (groupé, dispersé ou linéaire).\n2. Cite deux facteurs qui expliquent ces différentes formes d'habitat.\n3. Explique en deux phrases pourquoi la ville et la campagne dépendent l'une de l'autre.\n4. Cite trois réseaux qui relient les espaces entre eux.","bareme":[{"critere":"Identification des trois formes d'habitat","points":6},{"critere":"Facteurs expliquant les formes d'habitat","points":4},{"critere":"Dépendance entre ville et campagne","points":6},{"critere":"Trois réseaux cités","points":4}],"dureeMin":10,"corrige":"1. A : habitat **groupé**. B : habitat **dispersé** (le bocage de l'Ouest français). C : habitat **linéaire**.\n2. Deux facteurs parmi : l'**histoire**, l'**agriculture pratiquée**, le **relief**.\n3. La ville **dépend des campagnes pour se nourrir**. Les campagnes **dépendent de la ville pour les services** (commerces, hôpitaux, administrations…). Aucun espace n'est autosuffisant.\n4. Trois réseaux parmi : les **routes**, les **voies ferrées**, les **lignes aériennes**, les **câbles numériques**, les **réseaux électriques**."}$exo$::jsonb),
  ('62d1c622-02dd-5720-995f-b00bee66f852'::uuid, 3, 'redaction', $exo${"titre":"Des espaces qui se transforment : habiter demain","consigne":"Analyse le document, relie chaque situation au bon mot du cours et rédige un paragraphe argumenté.","enonce":"**Document** – Quatre situations (imaginaires)\n\n1. Autour d'une grande ville, des lotissements remplacent des champs dans les villages voisins.\n2. Dans une vallée de montagne, des maisons sont abandonnées et les friches avancent.\n3. Une grande métropole accueille les sièges des grandes entreprises, les grands hôpitaux et les universités.\n4. Une ville s'agrandit et ses quartiers neufs couvrent des terres autrefois agricoles.\n\n**Questions**\n\n1. Associe chaque situation à l'un de ces mots, en justifiant : urbanisation, périurbanisation, déprise, métropolisation.\n2. Dans la situation 1, explique pourquoi les nouveaux habitants se déplacent beaucoup. Quel problème cela pose-t-il pour l'environnement ?\n3. Explique la phrase : « la géographie est d'abord une affaire de relations ».\n4. Rédige un paragraphe de 4 à 6 lignes présentant trois défis pour « habiter demain ». Pense à la vallée de la situation 2.","bareme":[{"critere":"Association justifiée des situations et des notions","points":6},{"critere":"Déplacements périurbains et émissions","points":4},{"critere":"Explication des relations entre espaces","points":4},{"critere":"Paragraphe sur les défis pour habiter demain","points":6}],"dureeMin":18,"corrige":"1. Situation 1 : **périurbanisation**, la ville s'étale sur les campagnes proches. Situation 2 : **déprise**, l'espace se vide et les friches gagnent. Situation 3 : **métropolisation**, les fonctions rares se concentrent dans une très grande ville. Situation 4 : **urbanisation**, la ville gagne du terrain.\n2. Dans l'espace périurbain, les habitants vivent dans des maisons individuelles mais **travaillent en ville** : ils font chaque jour des trajets. Ces déplacements, souvent en voiture, produisent des **émissions** qui polluent.\n3. Aucun espace n'est **autosuffisant** : la ville a besoin des campagnes pour se nourrir, les campagnes ont besoin de la ville pour les services, et les espaces sont reliés par des réseaux (routes, voies ferrées, câbles…).\n4. Paragraphe modèle : « Pour habiter demain, il faudra d'abord **limiter l'étalement** des villes et **préserver les terres agricoles**. Il faudra aussi **réduire les émissions liées aux déplacements** et **adapter les territoires au changement climatique**. Enfin, il faudra **maintenir des services accessibles à tous**, même dans les espaces qui se vident, comme la vallée de montagne de la situation 2, où il y a peu d'habitants. »"}$exo$::jsonb),
  ('a6649dcc-ab84-5313-aa72-9c6129ad3fed'::uuid, 1, 'redaction', $exo${"titre":"La cité grecque : définitions","consigne":"Réponds à chaque question par une phrase complète.","enonce":"1. Comment dit-on « cité » en grec ? Cite deux cités grecques.\n2. Qu'est-ce que l'**acropole** ?\n3. Qu'est-ce que l'**agora** ?","bareme":[{"critere":"Mot grec polis et exemples de cités","points":6},{"critere":"Définition de l'acropole","points":7},{"critere":"Définition de l'agora","points":7}],"dureeMin":5,"corrige":"1. En grec, la cité se dit ***polis***. Exemples : **Athènes**, **Sparte**, Corinthe, Thèbes.\n2. L'acropole est la « **ville haute** », où se trouvent les **temples**.\n3. L'agora est la **place publique** de la cité : c'est un lieu de **marché** et de **débat**."}$exo$::jsonb),
  ('a6649dcc-ab84-5313-aa72-9c6129ad3fed'::uuid, 2, 'redaction', $exo${"titre":"Des cités indépendantes mais un même monde grec","consigne":"Réponds aux questions en t'appuyant sur le cours et en donnant des exemples.","enonce":"1. Chaque cité grecque est indépendante. Cite trois choses que chaque cité possède en propre.\n2. Quelle raison géographique explique que la Grèce soit divisée en nombreuses cités ?\n3. Cite trois éléments qui unissent pourtant tous les Grecs, avec un exemple pour chacun.\n4. Comment les Grecs se nomment-ils eux-mêmes ? Comment appellent-ils ceux qui ne parlent pas leur langue ?","bareme":[{"critere":"Ce que possède chaque cité","points":5},{"critere":"Explication par le relief et les îles","points":3},{"critere":"Trois éléments d'unité avec exemples","points":8},{"critere":"Hellènes et Barbares","points":4}],"dureeMin":10,"corrige":"1. Trois éléments parmi : ses **lois**, sa **monnaie**, son **armée**, ses **dieux protecteurs**.\n2. Le **relief montagneux** et les nombreuses **îles** séparent les territoires.\n3. Trois éléments parmi : une **langue commune** ; une **religion commune** (les dieux de l'**Olympe**) ; des **récits fondateurs** (l'*Iliade* et l'*Odyssée*, attribuées à **Homère**) ; des **sanctuaires communs** (**Delphes**) ; des **jeux communs** (les **Jeux olympiques**).\n4. Ils se nomment les **Hellènes**. Ils appellent **Barbares** ceux qui ne parlent pas leur langue."}$exo$::jsonb),
  ('a6649dcc-ab84-5313-aa72-9c6129ad3fed'::uuid, 3, 'redaction', $exo${"titre":"Les colonies grecques et l'héritage des cités","consigne":"Analyse la citation, fais le calcul demandé et rédige un paragraphe argumenté.","enonce":"**Document** – Une image célèbre\n\n> Les Grecs se sont installés « comme des grenouilles autour d'une mare », écrivait Platon de cette Méditerranée.\n\n1. Les premiers Jeux olympiques ont lieu, selon la tradition, en 776 av. J.-C., et Massalia est fondée vers 600 av. J.-C. Calcule combien d'années séparent ces deux événements. Quel est le nom actuel de Massalia ?\n2. Explique l'image de Platon : que représente la « mare » ? Que représentent les « grenouilles » ?\n3. Pourquoi les cités grecques fondent-elles des colonies ? Quels liens gardent-elles avec leur colonie ?\n4. Rédige un paragraphe de 4 à 5 lignes pour montrer ce que nous devons encore aujourd'hui aux cités grecques. Utilise au moins un exemple de mot.","bareme":[{"critere":"Calcul de l'écart et nom actuel de Massalia","points":4},{"critere":"Explication de l'image de Platon","points":5},{"critere":"Causes des colonies et liens avec la cité mère","points":5},{"critere":"Paragraphe sur l'héritage grec","points":6}],"dureeMin":16,"corrige":"1. Les deux dates sont avant J.-C. : 776 − 600 = **176 ans**. Massalia est aujourd'hui **Marseille**.\n2. La « mare » représente la **mer Méditerranée**. Les « grenouilles » sont les **colonies grecques**, installées tout **autour** de la mer, sur ses côtes.\n3. Les cités fondent des colonies parce qu'elles **manquent de terres**. Entre les VIIIe et VIe siècles av. J.-C., elles en fondent sur tout le pourtour méditerranéen. La cité mère et sa colonie gardent des **liens religieux et commerciaux**.\n4. Paragraphe modèle : « Les cités grecques nous ont laissé un riche héritage. Le mot **politique** vient du grec ***polis***, qui veut dire cité. Une grande partie de notre **vocabulaire**, mais aussi notre **théâtre**, notre **philosophie** et nos **sciences** descendent directement du monde grec. Des villes comme Marseille sont même d'anciennes colonies grecques. »"}$exo$::jsonb),
  ('beace87c-920d-5f74-a684-77bac0549bd0'::uuid, 1, 'redaction', $exo${"titre":"Les dieux de l’Olympe","consigne":"Réponds à chaque question par des phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Explique ce qu’est une religion **polythéiste**. Pourquoi peut-on dire que la religion des Grecs est polythéiste ?\n2. Indique le domaine de chacun de ces dieux : **Zeus**, **Poséidon**, **Athéna**, **Déméter**.\n3. Les dieux grecs sont dits **anthropomorphes**. Explique ce mot, puis indique ce qui les distingue des mortels.","bareme":[{"critere":"Définition du polythéisme appliquée aux Grecs","points":6},{"critere":"Domaines des quatre dieux","points":6},{"critere":"Anthropomorphisme et différence avec les mortels","points":8}],"dureeMin":7,"corrige":"1. Une religion polythéiste est une religion qui croit en **plusieurs dieux**. La religion grecque est polythéiste car les Grecs honorent de nombreux dieux ; les douze principaux siègent sur le mont Olympe.\n\n2. **Zeus** est le roi des dieux, dieu du ciel. **Poséidon** est le dieu de la mer. **Athéna** est la déesse de la sagesse et de la guerre juste. **Déméter** est la déesse de l’agriculture.\n\n3. « Anthropomorphe » signifie qui a une **forme humaine**. Les dieux grecs ont un corps humain et des sentiments humains : jalousie, colère, amour, vengeance. Ils se distinguent des mortels par leur **immortalité** et leur **puissance**, et non par leur vertu : un dieu grec peut être injuste."}$exo$::jsonb),
  ('beace87c-920d-5f74-a684-77bac0549bd0'::uuid, 2, 'redaction', $exo${"titre":"Une fête pour Athéna sur l’acropole","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le texte et sur le cours.","enonce":"**Document** (récit imaginé à partir des connaissances des historiens)\n\n> Ce jour-là, toute la cité d’Athènes monte vers l’acropole pour les Panathénées. Devant le Parthénon, les prêtres conduisent un bœuf jusqu’à l’autel et le sacrifient à la déesse. La foule reste dehors pendant la cérémonie. Plus tard, la viande est partagée entre les participants. À l’intérieur du temple, seule se dresse la grande statue d’Athéna.\n\n1. Quelle déesse est honorée dans ce document ? Quel est son domaine ?\n2. Décris la pratique religieuse présentée dans le document et nomme-la.\n3. D’après le document et le cours, à quoi sert le temple ? Pourquoi la foule reste-t-elle dehors ?\n4. Explique pourquoi cette fête est à la fois un acte religieux et un acte civique.","bareme":[{"critere":"Identification de la déesse et de son domaine","points":4},{"critere":"Description et nom du sacrifice","points":5},{"critere":"Rôle du temple, maison du dieu","points":6},{"critere":"Lien entre religion et cité","points":5}],"dureeMin":10,"corrige":"1. La déesse honorée est **Athéna**, déesse de la sagesse et de la guerre juste. Les Panathénées sont la grande fête d’Athènes en son honneur.\n\n2. Il s’agit d’un **sacrifice** : un animal (ici un bœuf) est tué sur un autel en l’honneur de la déesse, puis sa viande est partagée entre les participants.\n\n3. Le temple (ici le Parthénon) est la **maison de la déesse** : il abrite sa statue. Ce n’est pas un lieu de rassemblement des fidèles. C’est pourquoi les cérémonies se déroulent **dehors**, devant l’autel, et la foule reste à l’extérieur.\n\n4. Cette fête est religieuse car elle honore une déesse par un sacrifice. Elle est aussi civique car toute la cité y participe : pour les Grecs, religion et cité ne se séparent pas, et honorer les dieux est un **devoir de citoyen** autant qu’un acte de foi."}$exo$::jsonb),
  ('beace87c-920d-5f74-a684-77bac0549bd0'::uuid, 3, 'redaction', $exo${"titre":"Héros, oracles, jeux et théâtre : la religion dans la vie des Grecs","consigne":"Réponds aux questions, puis rédige un court paragraphe argumenté qui mobilise plusieurs exemples du cours.","enonce":"1. Qu’est-ce qu’un **héros** dans la religion grecque ? Cite deux héros et explique quel rôle ils jouent pour les Grecs.\n2. Un Grec veut savoir s’il doit partir en voyage. Où peut-il aller consulter les dieux ? Qui lui répondra, et au nom de quel dieu ?\n3. Explique pourquoi les **Jeux olympiques** et le **théâtre** ne sont pas de simples divertissements pour les Grecs.\n4. **Paragraphe** (6 à 8 lignes) : montre, à l’aide d’au moins trois exemples différents du cours, que chez les Grecs la religion est présente dans toute la vie de la cité.","bareme":[{"critere":"Définition du héros et exemples","points":4},{"critere":"L’oracle de Delphes","points":3},{"critere":"Caractère religieux des jeux et du théâtre","points":5},{"critere":"Paragraphe argumenté avec trois exemples","points":6},{"critere":"Rédaction et vocabulaire historique","points":2}],"dureeMin":18,"corrige":"1. Un héros est un être **entre les dieux et les hommes**, souvent né d’un dieu et d’une mortelle. Exemples : **Héraclès**, **Thésée** (aussi Achille, Ulysse). Ils accomplissent des exploits, servent de **modèles** aux Grecs et sont parfois considérés comme les **fondateurs de cités**.\n\n2. Il peut consulter l’**oracle de Delphes**. C’est la **Pythie** qui rend les réponses du dieu **Apollon**.\n\n3. Les **Jeux olympiques** sont une **fête religieuse en l’honneur de Zeus** ; une **trêve sacrée** est respectée pendant les jeux. Le **théâtre** est né des fêtes de **Dionysos** : assister à une pièce est un acte religieux et civique.\n\n4. Paragraphe modèle : Chez les Grecs, la religion est partout dans la vie de la cité. D’abord, les citoyens participent à des fêtes civiques, comme les Panathénées à Athènes, où l’on sacrifie un animal à Athéna devant le Parthénon avant de partager la viande. Ensuite, les Grecs consultent les dieux avant de prendre une décision, par exemple à Delphes, où la Pythie transmet les réponses d’Apollon. Enfin, même les jeux et le théâtre sont religieux : les Jeux olympiques honorent Zeus et le théâtre est né des fêtes de Dionysos. Honorer les dieux est donc un devoir civique autant qu’un acte de foi.\n\n(Accepter d’autres exemples justes du cours : les héros fondateurs de cités, les offrandes et libations.)"}$exo$::jsonb),
  ('912f051f-db72-5bf8-8656-492869f99abb'::uuid, 1, 'redaction', $exo${"titre":"Le mot démocratie et ses trois étapes","consigne":"Réponds par des phrases complètes en utilisant les dates et le vocabulaire du cours.","enonce":"1. De quels deux mots grecs vient le mot **démocratie** ? Que signifie-t-il ?\n2. Complète la chronologie en indiquant ce qu’a fait chaque homme :\n   - vers 594 av. J.-C. : **Solon**\n   - 508 av. J.-C. : **Clisthène**\n   - Ve siècle av. J.-C. : **Périclès**\n3. Qu’est-ce que le **misthos** ? À qui est-il utile ?","bareme":[{"critere":"Étymologie et sens du mot démocratie","points":5},{"critere":"Rôle de Solon, Clisthène et Périclès","points":9},{"critere":"Définition et utilité du misthos","points":6}],"dureeMin":7,"corrige":"1. Démocratie vient de **dêmos** (le peuple) et **kratos** (le pouvoir). La démocratie est le régime où le **pouvoir appartient au peuple**.\n\n2. - Vers 594 av. J.-C., **Solon** supprime l’esclavage pour dettes.\n   - En 508 av. J.-C., **Clisthène** réorganise la cité : c’est l’acte de naissance de la démocratie.\n   - Au Ve siècle av. J.-C., **Périclès** porte la démocratie à son apogée et crée le misthos.\n\n3. Le **misthos** est une **indemnité** (une somme d’argent) versée aux citoyens qui participent aux institutions. Il permet aux **citoyens les plus pauvres** de siéger sans perdre leur journée de travail."}$exo$::jsonb),
  ('912f051f-db72-5bf8-8656-492869f99abb'::uuid, 2, 'redaction', $exo${"titre":"Une journée de citoyen dans les institutions d’Athènes","consigne":"Pour chaque situation, identifie l’institution concernée et explique son rôle, puis réponds aux dernières questions.","enonce":"Voici quatre citoyens athéniens au Ve siècle av. J.-C. :\n\n- **Situation A** : Criton se rend sur la colline de la Pnyx avec des milliers d’autres citoyens pour voter la paix.\n- **Situation B** : Lysias a été tiré au sort parmi les jurés et doit juger un procès.\n- **Situation C** : Démos fait partie des 500 citoyens tirés au sort qui préparent les débats.\n- **Situation D** : Nicias a été élu pour commander l’armée.\n\n1. Pour chaque situation, nomme l’institution (ou la fonction) et indique son rôle.\n2. Pourquoi les Athéniens préfèrent-ils le **tirage au sort** à l’élection pour la plupart des fonctions ? Pourquoi Nicias, lui, est-il élu ?\n3. Un citoyen est jugé dangereux pour la cité. Que peut faire l’assemblée ? Explique comment.","bareme":[{"critere":"Identification des quatre institutions et de leur rôle","points":8},{"critere":"Explication du tirage au sort et de l’élection des stratèges","points":6},{"critere":"Explication de l’ostracisme","points":4},{"critere":"Rédaction en phrases complètes","points":2}],"dureeMin":11,"corrige":"1. - **A** : l’**Ecclésia**, assemblée de tous les citoyens réunie sur la Pnyx (environ 40 fois par an) ; elle vote les lois, la guerre et la paix.\n   - **B** : l’**Héliée**, tribunal populaire de 6 000 jurés tirés au sort ; elle rend la justice.\n   - **C** : la **Boulè**, conseil de 500 citoyens tirés au sort ; elle prépare les débats de l’Ecclésia.\n   - **D** : Nicias est **stratège** ; les 10 stratèges sont des magistrats élus qui commandent l’armée.\n\n2. Pour les Grecs, l’**élection favorise les riches** et les notables, alors que le **tirage au sort réalise l’égalité** entre citoyens : chacun a la même chance d’exercer une fonction. Seuls les postes qui demandent une **compétence technique**, comme commander l’armée, sont pourvus par élection : c’est pourquoi Nicias est élu.\n\n3. L’assemblée peut **ostraciser** ce citoyen, c’est-à-dire le **bannir pendant dix ans**. Chaque citoyen écrit le nom de l’homme à bannir sur un **tesson de poterie**, l’*ostrakon*. C’est un moyen pour la démocratie de se protéger."}$exo$::jsonb),
  ('912f051f-db72-5bf8-8656-492869f99abb'::uuid, 3, 'redaction', $exo${"titre":"Une démocratie directe mais réservée : analyser des chiffres","consigne":"Analyse le tableau, fais les calculs demandés en les détaillant, puis rédige une réponse argumentée.","enonce":"**Document** : la population d’Athènes au Ve siècle av. J.-C. (chiffres approximatifs)\n\n| Groupe | Effectif | Droits politiques |\n|---|---|---|\n| Population totale | 300 000 | |\n| Citoyens | 40 000 | oui |\n| Esclaves | environ la moitié de la population | non |\n| Femmes, enfants, métèques | le reste | non |\n\n1. Calcule le nombre approximatif d’esclaves à Athènes.\n2. Calcule combien d’habitants il y a pour un citoyen (divise la population totale par le nombre de citoyens). Que peux-tu en conclure ?\n3. Cite les groupes exclus de la vie politique.\n4. Explique pourquoi on dit que la démocratie athénienne est **directe**.\n5. En t’appuyant sur tes réponses et sur le cours (misthos, tirage au sort), rédige un paragraphe de 5 à 7 lignes : la démocratie athénienne est-elle égalitaire ?","bareme":[{"critere":"Calculs justes et détaillés","points":5},{"critere":"Groupes exclus de la citoyenneté","points":3},{"critere":"Explication du caractère direct","points":3},{"critere":"Paragraphe nuancé : égalité entre citoyens, exclusion des autres","points":7},{"critere":"Rédaction et vocabulaire","points":2}],"dureeMin":16,"corrige":"1. La moitié de 300 000 : 300 000 ÷ 2 = **150 000 esclaves** environ.\n\n2. 300 000 ÷ 40 000 = **7,5**. Il y a environ un citoyen pour 7 ou 8 habitants : seule une **petite minorité** de la population participe à la vie politique.\n\n3. Sont exclus : les **femmes**, les **métèques** (étrangers libres) et les **esclaves** (ainsi que les enfants).\n\n4. Elle est **directe** car les citoyens votent **eux-mêmes** les lois, la guerre et la paix à l’Ecclésia, sans élire de représentants.\n\n5. Paragraphe modèle : La démocratie athénienne cherche l’égalité entre les citoyens. Le tirage au sort donne à chacun la même chance de siéger à la Boulè ou à l’Héliée, alors que l’élection favoriserait les riches. Le misthos, créé par Périclès, permet même aux plus pauvres de participer. Mais cette égalité ne concerne qu’une minorité : environ 40 000 citoyens sur 300 000 habitants. Les femmes, les métèques et les esclaves, qui forment environ la moitié de la population, sont exclus. C’est donc une démocratie **directe mais réservée** : égalitaire entre citoyens, très inégalitaire pour l’ensemble des habitants."}$exo$::jsonb),
  ('8d83c77b-c970-54e6-84b1-5915fdb531bb'::uuid, 1, 'redaction', $exo${"titre":"Les quatre groupes de la société athénienne","consigne":"Réponds aux questions par des phrases complètes.","enonce":"1. Nomme les **quatre groupes** qui composent la société athénienne.\n2. Quelles conditions faut-il remplir pour être **citoyen** à Athènes ? Qu’a ajouté Périclès en 451 av. J.-C. ?\n3. Qu’est-ce qu’un **métèque** ? Peut-il devenir citoyen ?","bareme":[{"critere":"Les quatre groupes","points":6},{"critere":"Conditions de la citoyenneté et loi de 451","points":8},{"critere":"Définition et situation du métèque","points":6}],"dureeMin":6,"corrige":"1. La société athénienne compte les **citoyens**, les **femmes**, les **métèques** et les **esclaves**.\n\n2. Pour être citoyen, il faut être un **homme de plus de 18 ans**, **né d’un père citoyen**. En **451 av. J.-C.**, Périclès exige en plus que la **mère soit fille de citoyen**.\n\n3. Un métèque est un **étranger libre** installé à Athènes, souvent commerçant ou artisan. Il paie un impôt et sert dans l’armée, mais il ne peut **jamais** devenir citoyen."}$exo$::jsonb),
  ('8d83c77b-c970-54e6-84b1-5915fdb531bb'::uuid, 2, 'redaction', $exo${"titre":"Quatre habitants d’Athènes : droits et devoirs","consigne":"Pour chaque personnage, indique son groupe social et explique sa situation en t’appuyant sur le cours.","enonce":"Au Ve siècle av. J.-C., à Athènes, vivent :\n\n- **Aristos**, 20 ans, fils d’un citoyen et d’une fille de citoyen, qui vient de terminer ses deux années de service militaire ;\n- **Philé**, fille d’un citoyen, qui vit dans la maison de son père ;\n- **Kalias**, un marchand venu d’une autre cité grecque, installé au Pirée depuis vingt ans ;\n- **Manès**, un prisonnier de guerre acheté pour travailler dans les mines d’argent du Laurion.\n\n1. Pour chacun, indique le groupe auquel il appartient.\n2. Aristos est-il citoyen ? Justifie, puis décris les étapes qu’il a suivies pour le devenir.\n3. Cite deux droits et deux devoirs d’Aristos.\n4. Compare la situation de Philé, de Kalias et de Manès : qu’ont-ils en commun, qu’est-ce qui les distingue ?","bareme":[{"critere":"Groupe de chaque personnage","points":4},{"critere":"Citoyenneté d’Aristos et étapes pour la devenir","points":5},{"critere":"Deux droits et deux devoirs du citoyen","points":5},{"critere":"Comparaison des trois non-citoyens","points":6}],"dureeMin":12,"corrige":"1. Aristos est un **citoyen** ; Philé est une **femme** libre ; Kalias est un **métèque** ; Manès est un **esclave**.\n\n2. Oui, Aristos est citoyen : c’est un homme de plus de 18 ans, son père est citoyen et sa mère est fille de citoyen (condition exigée depuis 451 av. J.-C.). Il a été **inscrit dans son dème à 18 ans**, a fait l’**éphébie** (deux ans de service militaire) et a prêté le **serment de défendre la cité**.\n\n3. Droits (deux parmi) : voter à l’Ecclésia, être tiré au sort, posséder la terre, être jugé par ses pairs. Devoirs (deux parmi) : servir dans l’armée comme hoplite ou rameur, participer aux cultes de la cité, payer l’impôt et financer une liturgie s’il est riche.\n\n4. Tous trois sont **exclus de la vie politique** : ils ne votent pas. Mais leur situation diffère : Philé est **libre** mais vit **sous l’autorité d’un tuteur** ; Kalias est **libre**, il paie un impôt et sert à l’armée, mais ne sera jamais citoyen ; Manès **n’est pas libre** : juridiquement, l’esclave est un **bien** qui appartient à son maître, et le travail dans les mines du Laurion est terrible."}$exo$::jsonb),
  ('8d83c77b-c970-54e6-84b1-5915fdb531bb'::uuid, 3, 'redaction', $exo${"titre":"Être citoyen à Athènes et aujourd’hui","consigne":"Analyse le document, puis réponds aux questions en justifiant tes réponses avec le cours.","enonce":"**Document** : extrait adapté du serment des éphèbes athéniens\n\n> « Je ne déshonorerai pas les armes sacrées, je n’abandonnerai pas mon compagnon de rang. Je défendrai la cité et ses dieux. J’obéirai aux lois et je respecterai les cultes de ma patrie. »\n\n1. Qui prononce ce serment, et à quel moment de sa vie ?\n2. Relève dans le document deux **devoirs** du citoyen et relie-les au cours.\n3. Explique la phrase : « Être citoyen, à Athènes, ce n’est pas d’abord avoir des droits : c’est appartenir et devoir. »\n4. Pendant les Panathénées, chaque groupe a sa place dans la procession, métèques compris. Pourquoi peut-on dire que cette fête met en scène l’**ordre social** ?\n5. Compare la démocratie athénienne et la nôtre sur deux points (façon de voter les lois, personnes concernées).","bareme":[{"critere":"Identification de l’auteur du serment et du moment","points":3},{"critere":"Devoirs relevés et reliés au cours","points":4},{"critere":"Explication de la citation","points":4},{"critere":"Les Panathénées et l’ordre social","points":4},{"critere":"Comparaison argumentée avec aujourd’hui","points":5}],"dureeMin":18,"corrige":"1. Ce serment est prononcé par un **jeune Athénien** qui devient citoyen : inscrit dans son **dème à 18 ans**, il fait l’**éphébie** (deux ans de service militaire) et prête ce serment de défendre la cité.\n\n2. Devoirs : « je n’abandonnerai pas mon compagnon de rang », « je défendrai la cité » → **servir dans l’armée** (comme hoplite ou rameur) ; « je respecterai les cultes » → **participer aux cultes** de la cité.\n\n3. À Athènes, le citoyen appartient d’abord à une **communauté** : il doit la défendre, participer à ses cultes, et, s’il est riche, payer l’impôt et financer une **liturgie** (une trière ou un chœur). Ses droits (voter, être tiré au sort, posséder la terre) viennent avec ces **obligations** envers la cité.\n\n4. Dans la procession, chaque groupe occupe une **place précise** : les citoyens, les femmes, les métèques. La fête ne fait pas que réunir les habitants : elle **montre la hiérarchie** de la société, qui est à sa place et qui ne l’est pas.\n\n5. - **Vote des lois** : à Athènes, la démocratie est **directe** (les citoyens votent eux-mêmes les lois à l’Ecclésia) ; aujourd’hui, elle est **représentative** (on élit des représentants qui votent les lois).\n   - **Personnes concernées** : à Athènes, elle est **restreinte** (environ un habitant sur sept ; femmes, métèques et esclaves exclus) ; aujourd’hui, le suffrage est **universel**."}$exo$::jsonb),
  ('398eb840-05be-56e9-ad42-d9b337f684d2'::uuid, 1, 'redaction', $exo${"titre":"La légende de Romulus et Rémus","consigne":"Réponds aux questions par des phrases complètes.","enonce":"1. Quelle est la date légendaire de la fondation de Rome ? Qui l’aurait fondée ?\n2. Raconte en quelques lignes la légende de Romulus et Rémus.\n3. Selon Virgile, de quel héros descendent les Romains ? D’où vient ce héros ?","bareme":[{"critere":"Date légendaire et fondateur","points":5},{"critere":"Récit de la légende","points":10},{"critere":"Le lien avec Énée et Troie","points":5}],"dureeMin":7,"corrige":"1. Selon la légende, Rome a été fondée le **21 avril 753 av. J.-C.** par **Romulus**.\n\n2. Romulus et son frère jumeau **Rémus** sont les fils du dieu **Mars**. Abandonnés sur le **Tibre**, ils sont **allaités par une louve**. Devenus adultes, ils fondent une ville ; ils se disputent, et **Romulus tue Rémus**. Il donne son nom à la ville : Rome.\n\n3. Dans l’**Énéide** (Ier siècle av. J.-C.), **Virgile** fait descendre les Romains d’**Énée**, un **prince troyen** qui a fui sa ville, Troie, en flammes."}$exo$::jsonb),
  ('398eb840-05be-56e9-ad42-d9b337f684d2'::uuid, 2, 'redaction', $exo${"titre":"Pourquoi Rome raconte-t-elle sa naissance ainsi ?","consigne":"Lis le document, puis réponds aux questions en t’appuyant sur le document et sur le cours.","enonce":"**Document** : résumé d’un passage de l’historien romain Tite-Live (Ier siècle av. J.-C.)\n\n> Les jumeaux, fils du dieu Mars, furent abandonnés au bord du Tibre. Une louve, attirée par leurs cris, vint les allaiter. Plus tard, Romulus fonda la ville qui porte son nom et devint son premier roi. Les dieux avaient voulu que Rome devienne la maîtresse du monde.\n\n1. Qui est l’auteur de ce texte ? À quelle époque écrit-il ?\n2. Combien de siècles environ séparent l’écriture de ce texte de la date légendaire de la fondation de Rome ? Qu’en conclus-tu sur la valeur de ce récit ?\n3. Relève la phrase qui montre que ce récit sert à justifier la puissance de Rome. Explique-la.\n4. Explique la phrase du cours : « Un récit fondateur n’est pas un mensonge : c’est un portrait que le présent fait de son passé. »","bareme":[{"critere":"Identification de l’auteur et de l’époque","points":3},{"critere":"Écart de sept siècles et conséquence","points":5},{"critere":"Phrase relevée et expliquée","points":6},{"critere":"Explication de la citation","points":6}],"dureeMin":11,"corrige":"1. L’auteur est **Tite-Live**, un historien romain qui écrit au **Ier siècle av. J.-C.**\n\n2. Environ **sept siècles** séparent le texte de la date légendaire (753 av. J.-C.). Tite-Live n’a donc pas vu les faits : il rapporte une **légende** transmise, pas un témoignage. Son récit nous renseigne surtout sur les **croyances de son époque**.\n\n3. « Les dieux avaient voulu que Rome devienne la maîtresse du monde. » Au Ier siècle av. J.-C., Rome **domine la Méditerranée** : en disant que sa naissance a été voulue par les dieux (Romulus est fils de Mars), le récit **justifie cette domination**.\n\n4. Le récit fondateur n’est pas une invention pour tromper : il montre **comment les Romains veulent se voir** (descendants d’un dieu, peuple guerrier, destiné à dominer). Il dit donc surtout quelque chose de l’époque où il est écrit, et non de ce qui s’est vraiment passé."}$exo$::jsonb),
  ('398eb840-05be-56e9-ad42-d9b337f684d2'::uuid, 3, 'redaction', $exo${"titre":"Du village à l’Empire : chronologie et confrontation des sources","consigne":"Réponds aux questions en détaillant tes calculs et en justifiant tes réponses avec le cours.","enonce":"1. Cite les **trois périodes** de l’histoire de Rome avec leurs dates.\n2. Calcule la durée de la **Royauté** puis celle de la **République** (les deux périodes se situent avant J.-C. : on soustrait les dates).\n3. Que montrent les fouilles du **Palatin** ? La date légendaire de 753 av. J.-C. est-elle absurde ? Justifie.\n4. D’après l’archéologie, comment Rome est-elle devenue une ville ? Quel peuple voisin l’a influencée, et comment ?\n5. Un élève affirme : « Puisque la louve n’a pas existé, les textes de Tite-Live et de Virgile ne servent à rien pour l’historien. » Explique en quelques lignes pourquoi il a tort, en comparant ce qu’apportent les textes et les traces matérielles.","bareme":[{"critere":"Les trois périodes et leurs dates","points":4},{"critere":"Calcul des durées","points":4},{"critere":"Apport des fouilles du Palatin","points":3},{"critere":"Formation de la ville et influence étrusque","points":3},{"critere":"Argumentation sur la confrontation des sources","points":6}],"dureeMin":18,"corrige":"1. - La **Royauté** : 753-509 av. J.-C. (sept rois selon la tradition)\n   - La **République** : 509-27 av. J.-C.\n   - L’**Empire** : 27 av. J.-C. - 476 apr. J.-C. (en Occident)\n\n2. Royauté : 753 − 509 = **244 ans**. République : 509 − 27 = **482 ans**.\n\n3. Les fouilles du Palatin montrent des **cabanes de bergers dès le VIIIe siècle av. J.-C.** La date de 753 av. J.-C. n’est donc **pas absurde** : il y avait bien des habitants à cette époque.\n\n4. Rome s’est formée progressivement : des **villages sur les collines** se sont **regroupés** peu à peu pour former **une ville**. Elle a subi l’influence des **Étrusques**, à qui elle a emprunté des **techniques** et les **insignes du pouvoir**.\n\n5. L’élève a tort : les textes et les traces matérielles sont **deux types de sources** qui ne répondent pas à la même question. Les **textes** (Tite-Live, Virgile) ne disent pas ce qui s’est passé en 753 av. J.-C., mais ils nous renseignent sur les **croyances** des Romains du Ier siècle av. J.-C. et sur la façon dont ils voulaient se voir. Les **traces matérielles** (cabanes du Palatin) montrent **ce qui a été**. L’historien a besoin des deux et les confronte."}$exo$::jsonb),
  ('378ff142-faa2-5f28-9faf-2425b369d638'::uuid, 1, 'redaction', $exo${"titre":"Le vocabulaire de l’archéologue","consigne":"Définis chaque notion par une phrase complète et donne un exemple quand c’est demandé.","enonce":"1. Qu’est-ce que l’**archéologie** ? Cite trois exemples de traces matérielles qu’elle étudie.\n2. Qu’est-ce que la **stratigraphie** ? Quelles couches sont les plus anciennes ?\n3. Explique la différence entre une **datation relative** et une **datation absolue**, avec un exemple de méthode pour chacune.","bareme":[{"critere":"Définition de l’archéologie et exemples","points":6},{"critere":"Stratigraphie et ordre des couches","points":6},{"critere":"Datation relative et absolue avec exemples","points":8}],"dureeMin":7,"corrige":"1. L’**archéologie** est la science qui étudie le passé à partir des **traces matérielles** laissées par les hommes. Exemples : murs, tombes, poteries, ossements, outils.\n\n2. La **stratigraphie** est l’étude des **couches** du sol. Les couches **les plus profondes** sont **les plus anciennes** ; les couches proches de la surface sont les plus récentes. Lire ces couches, c’est lire une chronologie.\n\n3. Une **datation relative** permet de dire qu’un objet est **plus ancien ou plus récent** qu’un autre, sans donner de date précise : par exemple par la stratigraphie ou la comparaison des styles de poterie. Une **datation absolue** donne une **date** (ou une période chiffrée) : par exemple le **carbone 14**, la **dendrochronologie** (étude des cernes des arbres) ou les **monnaies**."}$exo$::jsonb),
  ('378ff142-faa2-5f28-9faf-2425b369d638'::uuid, 2, 'redaction', $exo${"titre":"Lire les couches d’une fouille à Rome","consigne":"Étudie le relevé de fouille, puis réponds aux questions en justifiant avec le cours.","enonce":"**Document** : relevé simplifié d’une fouille imaginaire au pied d’une colline de Rome (de la surface vers le fond)\n\n| Couche | Profondeur | Ce que l’on a trouvé |\n|---|---|---|\n| A | la plus proche de la surface | un dallage de pierre et une monnaie |\n| B | au milieu | des tombes avec des poteries grecques et étrusques |\n| C | la plus profonde | des trous de poteaux dessinant une cabane, un morceau de poteau en bois |\n\n1. Classe les trois couches de la plus ancienne à la plus récente. Justifie.\n2. Quelle méthode de datation absolue pourrait-on utiliser pour le morceau de bois de la couche C ? et pour la couche A ?\n3. Que nous apprennent les poteries grecques et étrusques de la couche B ?\n4. Un visiteur ramasse la monnaie et l’emporte sans noter où elle était. Pourquoi est-ce une perte pour les archéologues ?","bareme":[{"critere":"Classement chronologique justifié par la stratigraphie","points":6},{"critere":"Choix des méthodes de datation absolue","points":5},{"critere":"Interprétation des importations","points":4},{"critere":"Importance du contexte","points":5}],"dureeMin":11,"corrige":"1. Ordre : **C** (la plus ancienne), puis **B**, puis **A** (la plus récente). En stratigraphie, les couches les plus **profondes** se sont déposées en premier : elles sont les plus **anciennes**.\n\n2. Pour le bois de la couche C : le **carbone 14** ou la **dendrochronologie** (lecture des cernes du bois). Pour la couche A : la **monnaie**, qui porte souvent des indications permettant de la dater.\n\n3. Les poteries grecques et étrusques ont été fabriquées ailleurs : elles montrent que les habitants avaient des **échanges** précoces avec les Grecs et les Étrusques.\n\n4. Pour l’archéologue, c’est le **contexte** (la couche, la position exacte) qui donne son sens à l’objet. Sortie de sa couche sans relevé, la monnaie ne permet plus de dater la couche A : elle **perd presque tout intérêt scientifique**. C’est pourquoi les fouilles sont lentes et méthodiques."}$exo$::jsonb),
  ('378ff142-faa2-5f28-9faf-2425b369d638'::uuid, 3, 'redaction', $exo${"titre":"L’archéologie déplace la question de la fondation de Rome","consigne":"Réponds aux questions, puis rédige un paragraphe argumenté qui croise les textes et les fouilles.","enonce":"1. Présente ce que les archéologues ont trouvé sur le **Palatin** et sur le **Forum**. Que nous apprend chaque découverte ?\n2. Le Forum était d’abord un marécage. Explique comment les fouilles montrent sa transformation.\n3. Que signifie : « L’archéologie ne confirme ni n’infirme Romulus : elle **déplace la question** » ?\n4. Complète ce tableau dans ta réponse (recopie-le avec deux exemples par colonne) :\n\n| Les textes donnent | Les fouilles donnent |\n|---|---|\n| … | … |\n\n5. **Paragraphe** (5 à 7 lignes) : explique pourquoi l’historien a besoin à la fois des textes et des fouilles pour étudier la naissance de Rome.","bareme":[{"critere":"Découvertes du Palatin et du Forum","points":4},{"critere":"Transformation du Forum","points":3},{"critere":"Explication de la phrase sur Romulus","points":4},{"critere":"Tableau textes et fouilles","points":3},{"critere":"Paragraphe argumenté croisant les sources","points":6}],"dureeMin":18,"corrige":"1. Sur le **Palatin** : des **trous de poteaux** dessinant des **cabanes du VIIIe siècle av. J.-C.** → des gens habitaient déjà là à cette époque. Sur le **Forum** : une **nécropole** (un cimetière), puis un **dallage** → l’endroit change de fonction. Partout, des importations grecques et étrusques montrent des **échanges** précoces.\n\n2. Au fond, on trouve une nécropole ; au-dessus, un dallage. Le lieu, d’abord un marécage en bordure, est aménagé et **devient un espace public**, signe qu’un village devient une ville.\n\n3. Les fouilles ne peuvent pas prouver que Romulus a existé ni qu’il n’a pas existé. Elles posent une **autre question** : non plus « qui a fondé Rome ? », mais « **comment** Rome s’est-elle formée ? ». Réponse : Rome n’est pas née d’un acte fondateur unique, mais d’un **processus** progressif, au fil du VIIe siècle.\n\n4. Textes : des **noms**, des **intentions**, des **récits**. Fouilles : des **dates**, des **objets**, des **réalités matérielles**.\n\n5. Paragraphe modèle : Pour étudier la naissance de Rome, l’historien croise deux types de sources. Les textes, comme ceux de Tite-Live ou Virgile, donnent des noms et des récits, et montrent ce que les Romains croyaient de leurs origines. Les fouilles, elles, donnent des dates et des objets : les cabanes du Palatin prouvent une occupation au VIIIe siècle av. J.-C., le dallage du Forum montre la naissance d’un espace public. Seules, les sources ne répondent pas aux mêmes questions ; ensemble, elles montrent que Rome est née d’un lent regroupement de villages, que la légende a ensuite raconté à sa manière."}$exo$::jsonb),
  ('485427dc-e28f-5cfc-a3c1-855d7966a203'::uuid, 1, 'redaction', $exo${"titre":"SPQR et la naissance de la République","consigne":"Réponds aux questions par des phrases complètes.","enonce":"1. En quelle année les Romains fondent-ils la **République** ? Que s’est-il passé ?\n2. Que signifie l’expression latine *res publica* ?\n3. Que signifient les lettres **SPQR** ?\n4. Que veut dire le mot **veto** ? Qui peut l’utiliser à Rome ?","bareme":[{"critere":"Date et événement de 509 av. J.-C.","points":5},{"critere":"Sens de res publica et de SPQR","points":8},{"critere":"Sens du veto et tribuns de la plèbe","points":7}],"dureeMin":7,"corrige":"1. En **509 av. J.-C.**, les Romains **chassent leur dernier roi** et fondent la République.\n\n2. *Res publica* signifie « **la chose publique** » : le pouvoir n’appartient plus à un seul homme, mais à la **communauté des citoyens**.\n\n3. SPQR signifie *Senatus PopulusQue Romanus* : « **le Sénat et le peuple romain** ».\n\n4. « Veto » signifie « **je m’oppose** ». À Rome, ce sont les **tribuns de la plèbe** qui disposent du droit de veto, pour défendre les plébéiens."}$exo$::jsonb),
  ('485427dc-e28f-5cfc-a3c1-855d7966a203'::uuid, 2, 'redaction', $exo${"titre":"Qui gouverne la République romaine ?","consigne":"Lis les situations, puis réponds aux questions en t’appuyant sur le cours.","enonce":"Rome, IIe siècle av. J.-C.\n\n- **Situation A** : Marcus, citoyen riche, et Caius, citoyen pauvre, se rendent aux **comices** pour élire les magistrats.\n- **Situation B** : deux **consuls** viennent d’être élus ; l’un part commander une armée.\n- **Situation C** : un ancien consul siège au **Sénat** depuis vingt ans.\n\n1. Quel est le rôle des comices ? Le vote de Marcus et celui de Caius ont-ils le même poids ? Explique.\n2. Pour combien de temps les consuls sont-ils élus ? Pourquoi sont-ils deux ? Quel est leur rôle ?\n3. Qui siège au Sénat, et pour combien de temps ? Quel est son pouvoir réel ?\n4. Caius est **plébéien**. Qu’ont obtenu les plébéiens face aux **patriciens** ?","bareme":[{"critere":"Rôle des comices et vote pondéré par la richesse","points":6},{"critere":"Magistrats : durée, collégialité, rôle des consuls","points":5},{"critere":"Composition et pouvoir du Sénat","points":4},{"critere":"Conquêtes des plébéiens","points":5}],"dureeMin":11,"corrige":"1. Les **comices** sont des assemblées de citoyens qui **élisent les magistrats et votent les lois**. Les votes n’ont pas le même poids : on vote par **groupes pondérés selon la richesse**, ce qui **favorise les riches** comme Marcus.\n\n2. Les consuls sont élus pour **un an**. Ils sont **deux** (collégialité) : la **brièveté** du mandat et le **partage** du pouvoir empêchent un homme de confisquer le pouvoir. Les consuls sont les **chefs de l’État et de l’armée**.\n\n3. Le Sénat réunit **environ 300 anciens magistrats**, nommés **à vie**. Officiellement, il ne fait que donner des avis (il est consultatif), mais **en fait il dirige** la République.\n\n4. Les patriciens (grandes familles) ont longtemps été seuls à exercer les magistratures. Les plébéiens ont obtenu des **tribuns de la plèbe**, qui ont un **droit de veto**, puis l’**accès aux magistratures**."}$exo$::jsonb),
  ('485427dc-e28f-5cfc-a3c1-855d7966a203'::uuid, 3, 'redaction', $exo${"titre":"Une République oligarchique, de 509 à 27 av. J.-C.","consigne":"Réponds aux questions en justifiant chaque réponse, puis rédige un paragraphe argumenté.","enonce":"1. Calcule combien de temps a duré la République romaine (de 509 à 27 av. J.-C.). Détaille ton calcul.\n2. Quels habitants sont exclus de la citoyenneté à Rome ? Sur ce point, que peux-tu dire en comparant avec Athènes ?\n3. Explique pourquoi on qualifie la République romaine d’**oligarchique**, en donnant deux arguments tirés des institutions.\n4. Remets dans l’ordre les étapes de la fin de la République et explique le lien entre elles : *guerre civile* – *les conquêtes enrichissent une minorité* – *l’Empire* – *les généraux s’appuient sur leurs armées* – *la crise sociale s’aggrave*.\n5. Quels événements marquent les années **44** et **27 av. J.-C.** ?","bareme":[{"critere":"Calcul de la durée","points":2},{"critere":"Exclus et comparaison avec Athènes","points":4},{"critere":"Deux arguments sur le caractère oligarchique","points":6},{"critere":"Enchaînement des causes de la fin de la République","points":5},{"critere":"Dates de 44 et 27 av. J.-C.","points":3}],"dureeMin":17,"corrige":"1. Les deux dates sont avant J.-C. : 509 − 27 = **482 ans**.\n\n2. Les **femmes**, les **esclaves** et les **étrangers** sont exclus. C’est **comme à Athènes**, où les femmes, les métèques et les esclaves n’étaient pas citoyens.\n\n3. Oligarchique signifie que le pouvoir est aux mains d’un **petit groupe**. Arguments :\n   - dans les **comices**, le vote se fait par **groupes pondérés selon la richesse** : les riches pèsent plus que les pauvres ;\n   - le **Sénat**, composé d’environ 300 anciens magistrats **nommés à vie**, dirige en fait la République ;\n   - (accepter aussi) les **patriciens** ont longtemps été seuls à accéder aux magistratures.\n\n4. Ordre : **les conquêtes enrichissent une minorité** → **la crise sociale s’aggrave** → **les généraux s’appuient sur leurs armées** → **guerre civile** → **l’Empire**. Les richesses des conquêtes profitent à peu de gens, ce qui creuse les inégalités ; des généraux utilisent alors la fidélité de leurs soldats pour prendre le pouvoir ; ils s’affrontent dans des guerres civiles, qui s’achèvent avec l’installation d’un pouvoir personnel : l’Empire.\n\n5. En **44 av. J.-C.**, **César est assassiné**. En **27 av. J.-C.**, **Auguste installe l’Empire**."}$exo$::jsonb),
  ('0167f885-4726-5db9-8eed-8b09a19bcd39'::uuid, 1, 'redaction', $exo${"titre":"Qu’est-ce que la Bible hébraïque ?","consigne":"Réponds aux questions par des phrases complètes.","enonce":"1. Qu’est-ce que la **Bible hébraïque** ? Entre quels siècles a-t-elle été rédigée ?\n2. Comment les chrétiens appellent-ils ce texte ?\n3. Nomme les **trois parties** de la Bible hébraïque. Que contient la **Torah** ?","bareme":[{"critere":"Définition et période de rédaction","points":7},{"critere":"Nom donné par les chrétiens","points":3},{"critere":"Les trois parties et le contenu de la Torah","points":10}],"dureeMin":6,"corrige":"1. La Bible hébraïque est une **collection de textes** (récits, lois, poèmes, prophéties) : c’est une véritable bibliothèque. Elle a été rédigée entre le **VIIIe et le IIe siècle av. J.-C.**\n\n2. Les chrétiens l’appellent l’**Ancien Testament**.\n\n3. Ses trois parties sont : la **Torah**, les **Prophètes** et les **Écrits**. La Torah regroupe les **cinq premiers livres** (le Pentateuque) : c’est la **Loi**, qui raconte l’histoire de la Création jusqu’à la mort de Moïse."}$exo$::jsonb),
  ('0167f885-4726-5db9-8eed-8b09a19bcd39'::uuid, 2, 'redaction', $exo${"titre":"Les grands récits de la Bible","consigne":"Remets les récits dans l’ordre, puis explique le rôle de chaque personnage en t’appuyant sur le cours.","enonce":"Voici quatre grands récits de la Bible, dans le désordre :\n\n- Moïse et l’Exode\n- La Création et le Déluge\n- David et Salomon\n- Abraham et l’Alliance\n\n1. Classe ces récits dans l’ordre où la Bible les raconte.\n2. Qu’est-ce que l’**Alliance** ? Avec qui Dieu la conclut-il, et que lui promet-il ?\n3. Qu’est-ce que l’**Exode** ? Que se passe-t-il au mont **Sinaï** ?\n4. Qui sont David et Salomon ? Qu’a construit Salomon, et où ?","bareme":[{"critere":"Ordre des récits","points":4},{"critere":"Abraham et l’Alliance","points":5},{"critere":"Moïse, l’Exode et le Sinaï","points":6},{"critere":"David, Salomon et le Temple","points":5}],"dureeMin":10,"corrige":"1. Ordre : **la Création et le Déluge** → **Abraham et l’Alliance** → **Moïse et l’Exode** → **David et Salomon**.\n\n2. L’**Alliance** est le pacte entre Dieu et **Abraham** : Dieu lui **promet une terre et une descendance**.\n\n3. L’**Exode** est la **sortie d’Égypte** des Hébreux, conduits par **Moïse**. Au mont **Sinaï**, Moïse reçoit les **Dix Commandements**.\n\n4. **David** et **Salomon** sont des **rois de Jérusalem**. **Salomon** a bâti le **Temple**, à **Jérusalem**."}$exo$::jsonb),
  ('0167f885-4726-5db9-8eed-8b09a19bcd39'::uuid, 3, 'redaction', $exo${"titre":"La Bible, un texte de foi et une source pour l’historien","consigne":"Réponds aux questions en justifiant tes réponses et en détaillant ton calcul.","enonce":"1. Que se passe-t-il en **587 av. J.-C.** ? et en **515 av. J.-C.** ?\n2. Calcule combien d’années séparent ces deux événements (les deux dates sont avant J.-C.).\n3. Pourquoi l’exil à Babylone est-il un moment important pour l’écriture de la Bible ?\n4. Explique la phrase : « Un texte sacré est toujours une source historique — mais sur **ceux qui l’écrivent**, pas nécessairement sur ce qu’il raconte. » Appuie-toi sur un élément confirmé par l’archéologie et sur un élément qu’elle n’atteste pas.\n5. Pourquoi parle-t-on de « **religions abrahamiques** » ? Quelle est l’importance du judaïsme dans l’histoire des religions ?","bareme":[{"critere":"Les événements de 587 et 515 av. J.-C.","points":4},{"critere":"Calcul de l’écart","points":2},{"critere":"Rôle de l’exil dans l’écriture des textes","points":3},{"critere":"Analyse du texte sacré comme source avec exemples","points":7},{"critere":"Héritage et religions abrahamiques","points":4}],"dureeMin":17,"corrige":"1. En **587 av. J.-C.**, **Nabuchodonosor** prend Jérusalem, **détruit le Temple** et **déporte** les habitants : c’est l’**exil à Babylone**. En **515 av. J.-C.**, c’est le **retour** et la **reconstruction du Temple**.\n\n2. 587 − 515 = **72 ans**.\n\n3. C’est **pendant l’exil** que beaucoup de textes sont **mis par écrit** : loin de leur terre et privés du Temple, les exilés rassemblent leurs récits et leurs lois.\n\n4. La Bible est d’abord un texte de **foi**, pas un reportage. L’**archéologie confirme** certains éléments, comme l’**existence du royaume de Juda** ou les **destructions de Jérusalem**. Mais elle **n’atteste pas** d’autres récits, comme l’**Exode** tel qu’il est raconté. Le texte ne prouve donc pas toujours ce qu’il raconte ; en revanche, il nous apprend beaucoup sur **ceux qui l’ont écrit** : leurs croyances, leurs lois, ce qu’ils ont vécu (comme l’exil).\n\n5. Le judaïsme est le **premier monothéisme durable**. Le **christianisme** et l’**islam** s’y rattachent : les trois religions partagent la figure d’**Abraham**, d’où l’expression « religions abrahamiques »."}$exo$::jsonb),
  ('09192cab-822a-5621-a072-c282cd2fb857'::uuid, 1, 'redaction', $exo${"titre":"Un Dieu unique","consigne":"Réponds aux questions par des phrases complètes.","enonce":"1. Qu’est-ce que le **monothéisme** ? En quoi la religion des Hébreux est-elle différente de celle des peuples voisins ?\n2. Que les Hébreux s’interdisent-ils de faire à propos de Dieu ?\n3. Nomme les deux royaumes des Hébreux et situe-les. D’où vient le mot « **juif** » ?","bareme":[{"critere":"Définition du monothéisme et différence avec les voisins","points":8},{"critere":"Interdiction de représenter Dieu","points":4},{"critere":"Les deux royaumes et l’origine du mot juif","points":8}],"dureeMin":6,"corrige":"1. Le **monothéisme** est la croyance en un **Dieu unique**. Les peuples voisins des Hébreux sont **polythéistes** : ils honorent des dizaines de dieux, alors que les Hébreux n’en reconnaissent qu’un. Dans le monde antique, c’est une position très singulière.\n\n2. Dieu n’a ni corps ni image : sa **représentation est interdite**.\n\n3. Le royaume d’**Israël** est **au nord** ; le royaume de **Juda** est **au sud**, avec pour capitale **Jérusalem**. Le mot « juif » vient de « **Juda** »."}$exo$::jsonb),
  ('09192cab-822a-5621-a072-c282cd2fb857'::uuid, 2, 'redaction', $exo${"titre":"Les pratiques du judaïsme dans une famille","consigne":"Lis le document, relève les pratiques religieuses et explique-les avec le vocabulaire du cours.","enonce":"**Document** : récit imaginé\n\n> Samuel vit à Alexandrie. Le septième jour de la semaine, sa famille ne travaille pas. Au printemps, elle célèbre la fête qui rappelle la sortie d’Égypte. Chaque semaine, Samuel se rend dans un bâtiment où l’on prie et où l’on étudie les textes, sous la conduite d’un maître. À table, sa mère respecte des règles strictes sur ce que l’on peut manger.\n\n1. Relève les **quatre pratiques** religieuses décrites et donne leur nom exact.\n2. Qui dirige la prière et l’étude dans le bâtiment où se rend Samuel ?\n3. Samuel vit à Alexandrie, loin de Jérusalem. Quel mot désigne la dispersion des Juifs hors de Judée ? Cite une autre ville où vivaient des Juifs.\n4. Cite une autre pratique du judaïsme qui n’est pas dans le document, et explique ce qu’elle signifie.","bareme":[{"critere":"Quatre pratiques relevées et nommées","points":8},{"critere":"Rôle du rabbin","points":3},{"critere":"La diaspora","points":4},{"critere":"Autre pratique expliquée","points":5}],"dureeMin":10,"corrige":"1. - « le septième jour… ne travaille pas » → le **shabbat**, repos du septième jour ;\n   - « la fête qui rappelle la sortie d’Égypte » → **Pessah** ;\n   - « un bâtiment où l’on prie et où l’on étudie » → la **synagogue** ;\n   - « des règles strictes sur ce que l’on peut manger » → la ***cacherout***, les interdits alimentaires.\n\n2. C’est un **rabbin** qui dirige la synagogue.\n\n3. C’est la **diaspora** : la dispersion des Juifs hors de Judée. Autre ville : **Rome** (puis toute l’Europe et le monde entier).\n\n4. Réponses possibles : la **circoncision**, signe de l’**Alliance** ; **Yom Kippour**, la fête du **Grand Pardon** ; **Hanoucca**, une autre fête juive."}$exo$::jsonb),
  ('09192cab-822a-5621-a072-c282cd2fb857'::uuid, 3, 'redaction', $exo${"titre":"Comment le judaïsme a survécu sans Temple ni territoire","consigne":"Réponds aux questions, puis rédige un paragraphe argumenté en t’appuyant sur le cours.","enonce":"1. Que se passe-t-il pour le Temple de Jérusalem en **587 av. J.-C.** puis en **70 apr. J.-C.** ? Qu’en reste-t-il aujourd’hui ?\n2. Cite les empires qui ont dominé les Juifs au cours de l’Antiquité. Sur quoi les Juifs s’appuient-ils pour conserver leur identité, faute d’État ?\n3. Explique comment le judaïsme se réorganise après la destruction du Temple.\n4. Explique la phrase : « Une religion qui tient dans un livre peut voyager. »\n5. **Paragraphe** (5 à 7 lignes) : montre que le judaïsme a laissé un héritage important, en citant au moins deux éléments.","bareme":[{"critere":"Destructions du Temple et Mur occidental","points":4},{"critere":"Empires dominants et fondements de l’identité juive","points":4},{"critere":"Réorganisation autour des textes et de la synagogue","points":4},{"critere":"Explication de la citation","points":3},{"critere":"Paragraphe sur l’héritage du judaïsme","points":5}],"dureeMin":18,"corrige":"1. En **587 av. J.-C.**, le Temple de Jérusalem est **détruit une première fois** (par Nabuchodonosor). En **70 apr. J.-C.**, les **Romains le détruisent définitivement**. Il n’en subsiste que le **Mur occidental**.\n\n2. Les Juifs ont été dominés par les empires **assyrien**, **babylonien**, **perse**, puis **romain**. Ils conservent leur identité grâce à leur **religion** et à leur **Livre**, plutôt que grâce à un État.\n\n3. Privé de Temple, le judaïsme se réorganise autour de l’**étude des textes** et de la **synagogue**, lieu de prière et d’étude dirigé par un rabbin. Il peut ainsi **survivre partout, sans territoire**.\n\n4. Le judaïsme ne dépend plus d’un lieu (le Temple) mais d’un **livre** que l’on peut emporter partout. Les Juifs dispersés (la **diaspora** : Alexandrie, Rome, puis toute l’Europe) peuvent donc pratiquer leur religion où qu’ils soient. C’est ce qui lui a permis de traverser **vingt siècles de dispersion**.\n\n5. Paragraphe modèle : Le judaïsme a laissé un héritage très important. D’abord, il a apporté le **monothéisme**, la croyance en un Dieu unique, qui est aussi au cœur du christianisme et de l’islam. Ensuite, il a transmis une **loi morale** commune, les **Dix Commandements**. Enfin, il a donné une grande place à l’**écrit** : pour les Juifs, étudier les textes est un acte religieux. Cet héritage a traversé les siècles malgré la destruction du Temple et la dispersion."}$exo$::jsonb),
  ('0b0d579c-326a-57ff-a214-05f4f1be73dd'::uuid, 1, 'application', $exo${"titre":"Les trois états de la matière et leurs changements","consigne":"Lis chaque situation, puis réponds aux questions en rédigeant des phrases complètes.","enonce":"Dans la cuisine, Nora observe trois objets : **un glaçon** posé dans une assiette, **du jus de pomme** dans un verre, et **l'air** enfermé dans un ballon de baudruche.\n\n1. Donne l'état physique (solide, liquide ou gaz) de chacun des trois.\n2. Pour le jus de pomme, explique s'il a une forme propre et un volume propre. Décris aussi sa surface libre quand le verre est posé sur la table.\n3. Donne le nom du changement d'état dans chaque cas :\n   - a) la neige fond au soleil ;\n   - b) une flaque d'eau disparaît en devenant de la vapeur ;\n   - c) de l'eau placée au congélateur devient de la glace ;\n   - d) de la vapeur d'eau se transforme en gouttelettes sur une vitre froide.","bareme":[{"critere":"États physiques des trois objets","points":6},{"critere":"Forme, volume et surface libre du liquide","points":6},{"critere":"Noms des quatre changements d'état","points":8}],"dureeMin":6,"corrige":"1. Le glaçon est **solide**, le jus de pomme est **liquide**, l'air du ballon est un **gaz**.\n\n2. Le jus de pomme n'a **pas de forme propre** : il prend la forme du verre. Il a en revanche un **volume propre** : si on le verse dans un autre récipient, il occupe le même volume. Quand le verre est posé, sa surface libre est **horizontale**.\n\n3.\n- a) solide → liquide : **fusion** ;\n- b) liquide → gaz : **vaporisation** ;\n- c) liquide → solide : **solidification** ;\n- d) gaz → liquide : **liquéfaction**."}$exo$::jsonb),
  ('0b0d579c-326a-57ff-a214-05f4f1be73dd'::uuid, 2, 'application', $exo${"titre":"Suivre la fusion de glaçons","consigne":"Analyse le tableau de mesures de Léa, puis réponds aux questions en justifiant avec le cours.","enonce":"Léa place **200 g de glace** pure dans un bécher et le chauffe doucement. Elle relève la température toutes les 2 minutes.\n\n| Temps (min) | 0 | 2 | 4 | 6 | 8 | 10 |\n|---|---|---|---|---|---|---|\n| Température (°C) | −10 | 0 | 0 | 0 | 20 | 40 |\n| Ce qu'elle voit | glace | glace + eau | glace + eau | glace + eau | eau | eau |\n\n1. Quel changement d'état se produit entre 2 et 6 minutes ? Donne son nom.\n2. Que remarques-tu sur la température pendant ce changement d'état ? Explique pourquoi elle ne monte pas alors que Léa continue de chauffer.\n3. À la fin, quelle est la masse d'eau liquide dans le bécher ? Justifie.\n4. Le volume de l'eau liquide obtenue est-il le même que celui de la glace de départ ? Explique.","bareme":[{"critere":"Nom du changement d'état (fusion)","points":4},{"critere":"Palier de température à 0 °C et son explication","points":6},{"critere":"Conservation de la masse (200 g)","points":5},{"critere":"Variation du volume expliquée","points":5}],"dureeMin":10,"corrige":"1. Entre 2 et 6 minutes, on voit de la glace et de l'eau : la glace passe de l'état solide à l'état liquide. C'est la **fusion**.\n\n2. La température reste **bloquée à 0 °C** tant qu'il reste de la glace (c'est la température de fusion de l'eau pure). Chauffer ne la fait pas monter, car l'énergie apportée sert à **faire fondre** la glace. Quand toute la glace a fondu (après 6 min), la température recommence à monter.\n\n3. La masse se conserve lors d'un changement d'état : 200 g de glace donnent **200 g d'eau liquide**.\n\n4. Non. Le volume **change** pendant un changement d'état : la glace occupe **plus de place** que l'eau liquide. L'eau liquide obtenue occupe donc un volume un peu **plus petit** que la glace de départ. C'est toujours la même matière : de l'eau."}$exo$::jsonb),
  ('0b0d579c-326a-57ff-a214-05f4f1be73dd'::uuid, 3, 'application', $exo${"titre":"La bouteille oubliée au congélateur","consigne":"Utilise tes connaissances sur les états de la matière pour expliquer chaque observation. Rédige des réponses justifiées.","enonce":"Hugo remplit **à ras bord** une bouteille en verre avec **1 500 g d'eau** pure, la ferme et la met au congélateur. Le lendemain, la bouteille est **fendue** et contient un bloc de glace.\n\n1. Quel changement d'état l'eau a-t-elle subi ? Donne son nom.\n2. Quelle est la masse du bloc de glace ? Justifie avec une règle du cours.\n3. Explique pourquoi la bouteille s'est fendue.\n4. Hugo dit : « Ce n'est plus de l'eau, c'est une autre matière : de la glace. » A-t-il raison ? Justifie.\n5. Pour caler la bouteille, Hugo verse du **sable sec** dans un bac : le sable s'écoule et prend la forme du bac. Sa sœur affirme : « Le sable est un liquide. » Explique pourquoi elle se trompe.","bareme":[{"critere":"Nom du changement d'état (solidification)","points":3},{"critere":"Masse conservée : 1 500 g de glace","points":4},{"critere":"Explication de la bouteille fendue par l'augmentation du volume","points":5},{"critere":"Même matière dans les trois états","points":3},{"critere":"Le sable, un solide divisé","points":5}],"dureeMin":15,"corrige":"1. L'eau est passée de l'état liquide à l'état solide : c'est la **solidification**.\n\n2. Lors d'un changement d'état, la **masse se conserve**. 1 500 g d'eau liquide donnent donc **1 500 g de glace**.\n\n3. Le volume, lui, **ne se conserve pas** : la glace occupe **plus de place** que l'eau liquide. La bouteille était pleine et fermée : la glace n'avait pas la place de s'étendre, elle a poussé sur le verre, qui s'est fendu.\n\n4. Non, Hugo a tort. Un changement d'état **ne change pas la matière** : la glace, l'eau liquide et la vapeur sont toutes de l'eau.\n\n5. Le sable est un **solide divisé**. Il est formé de très nombreux petits grains : l'ensemble s'écoule comme un liquide et prend la forme du bac, mais **chaque grain garde sa forme propre**, comme tout solide. Ce n'est donc pas un liquide."}$exo$::jsonb),
  ('5a33fa8b-f075-5ef8-9867-08b15f235f26'::uuid, 1, 'application', $exo${"titre":"Instruments, unités et conversions","consigne":"Réponds aux questions et écris chaque conversion avec son unité.","enonce":"1. Recopie et complète : pour mesurer une **masse**, on utilise … et l'unité est … ; pour mesurer un **volume** de liquide, on utilise … et l'unité est … ; pour mesurer une **température**, on utilise … et l'unité est … .\n2. Convertis :\n   - a) 2,5 kg en g ;\n   - b) 3 g en mg ;\n   - c) 750 mL en L ;\n   - d) 40 cm³ en mL.\n3. Un objet a une masse de 2 kg sur Terre. Quelle est sa masse sur la Lune ? Justifie.","bareme":[{"critere":"Instruments et unités des trois grandeurs","points":6},{"critere":"Quatre conversions justes","points":8},{"critere":"La masse ne dépend pas du lieu","points":6}],"dureeMin":7,"corrige":"1. Masse : la **balance**, unité le **kilogramme (kg)**. Volume : l'**éprouvette graduée**, unité le **litre (L)**. Température : le **thermomètre**, unité le **degré Celsius (°C)**.\n\n2.\n- a) 1 kg = 1 000 g, donc 2,5 kg = 2,5 × 1 000 = **2 500 g** ;\n- b) 1 g = 1 000 mg, donc 3 g = **3 000 mg** ;\n- c) 1 L = 1 000 mL, donc 750 mL = 750 ÷ 1 000 = **0,75 L** ;\n- d) 1 mL = 1 cm³, donc 40 cm³ = **40 mL**.\n\n3. Sa masse sur la Lune est **2 kg**. La masse est la quantité de matière : elle **ne dépend pas du lieu**."}$exo$::jsonb),
  ('5a33fa8b-f075-5ef8-9867-08b15f235f26'::uuid, 2, 'application', $exo${"titre":"Mesurer la masse et le volume d'un liquide","consigne":"Aide Tom à réaliser ses mesures : réponds aux questions en détaillant tes calculs.","enonce":"Tom veut connaître la masse et le volume d'un peu d'huile.\n\n- Il pèse l'éprouvette graduée **vide** : la balance affiche **120 g**.\n- Il verse l'huile dans l'éprouvette et la pèse à nouveau : **212 g**.\n- Il lit le volume : **100 mL**.\n\n1. Décris, en trois étapes, comment Tom doit s'y prendre pour lire correctement le volume sur l'éprouvette.\n2. Calcule la masse de l'huile.\n3. Convertis le volume d'huile en litres.\n4. Tom verse ensuite 250 mL d'eau dans une autre éprouvette, puis 250 mL de plus. Quel volume d'eau obtient-il en tout, en mL puis en L ?","bareme":[{"critere":"Méthode de lecture de l'éprouvette","points":6},{"critere":"Calcul de la masse de l'huile","points":6},{"critere":"Conversion du volume en litres","points":4},{"critere":"Volume total d'eau en mL et en L","points":4}],"dureeMin":10,"corrige":"1. Tom pose l'éprouvette **bien à plat** sur la table, il place son œil **à la hauteur de la graduation**, puis il lit le volume **au bas du ménisque** (la surface courbée du liquide).\n\n2. Masse de l'huile = masse de l'éprouvette pleine − masse de l'éprouvette vide = 212 − 120 = **92 g**.\n\n3. 1 L = 1 000 mL, donc 100 mL = 100 ÷ 1 000 = **0,1 L**.\n\n4. 250 + 250 = **500 mL**, soit 500 ÷ 1 000 = **0,5 L**."}$exo$::jsonb),
  ('5a33fa8b-f075-5ef8-9867-08b15f235f26'::uuid, 3, 'application', $exo${"titre":"L'air a une masse et chaque substance a sa carte d'identité","consigne":"Exploite les expériences décrites, fais les calculs et justifie chaque conclusion avec le cours.","enonce":"**Expérience 1.** Maya pèse un ballon **dégonflé** : **25,0 g**. Elle le gonfle, le ferme et le pèse de nouveau : **27,4 g**.\n\n**Expérience 2.** Maya refroidit un liquide incolore inconnu. Il commence à se solidifier à **0 °C**, et la température reste à 0 °C tant que la solidification dure.\n\n**Donnée :** un litre d'air pèse environ **1,2 g**.\n\n1. Que montre l'expérience 1 ? Calcule la masse d'air ajoutée dans le ballon.\n2. Calcule le volume approximatif d'air contenu dans le ballon.\n3. Un camarade dit : « L'air, on ne le voit pas, donc ce n'est pas de la matière. » Réponds-lui.\n4. D'après l'expérience 2, quel est probablement ce liquide ? Explique pourquoi la mesure d'une température de changement d'état permet d'identifier une substance.\n5. Explique la différence entre la **masse** et le **poids**.","bareme":[{"critere":"Masse d'air calculée (2,4 g)","points":4},{"critere":"Volume d'air calculé (2 L)","points":4},{"critere":"L'air est de la matière","points":3},{"critere":"Identification de l'eau pure et justification","points":5},{"critere":"Distinction masse et poids","points":4}],"dureeMin":15,"corrige":"1. Le ballon gonflé est **plus lourd** : l'air a donc une masse. Masse d'air = 27,4 − 25,0 = **2,4 g**.\n\n2. Un litre d'air pèse environ 1,2 g. Volume = 2,4 ÷ 1,2 = **2 L** environ.\n\n3. Il se trompe : l'air a une masse (l'expérience 1 le prouve) et il occupe de la place. C'est donc de la matière. **Invisible ne veut pas dire immatériel.**\n\n4. Chaque substance a des **températures de changement d'état qui lui sont propres** : c'est comme une carte d'identité. L'eau pure se solidifie (et fond) à **0 °C**. Ce liquide est donc probablement de **l'eau pure**.\n\n5. La **masse** est la quantité de matière, elle se mesure en kg avec une balance et ne dépend pas du lieu. Le **poids** est l'attraction exercée par la Terre sur l'objet : ce n'est **pas** la même chose que la masse."}$exo$::jsonb),
  ('15fea229-b517-5dd4-b5f9-8f88c667ec32'::uuid, 1, 'application', $exo${"titre":"Corps purs et mélanges","consigne":"Réponds aux questions en utilisant le vocabulaire du cours.","enonce":"1. Explique la différence entre un **corps pur** et un **mélange**.\n2. Classe chaque mélange dans la bonne famille (homogène ou hétérogène) et justifie pour l'un d'eux :\n   - a) eau + sirop ;\n   - b) eau + huile ;\n   - c) eau + sable ;\n   - d) l'air ;\n   - e) jus d'orange avec pulpe.\n3. Dans l'air, quel gaz est le plus abondant ? Donne son pourcentage.","bareme":[{"critere":"Définitions de corps pur et de mélange","points":6},{"critere":"Classement des cinq mélanges avec une justification","points":10},{"critere":"Composition de l'air","points":4}],"dureeMin":6,"corrige":"1. Un **corps pur** ne contient qu'**une seule substance**. Un **mélange** en contient **plusieurs**.\n\n2.\n- a) eau + sirop : **homogène** ;\n- b) eau + huile : **hétérogène** ;\n- c) eau + sable : **hétérogène** ;\n- d) l'air : **homogène** (mélange de gaz) ;\n- e) jus d'orange avec pulpe : **hétérogène**.\n\nJustification (exemple) : dans l'eau + huile, on distingue deux couches, donc au moins deux constituants : le mélange est hétérogène. Dans l'eau + sirop, on ne distingue pas les constituants, même à la loupe : il est homogène.\n\n3. Le gaz le plus abondant est le **diazote** : **78 %** de l'air."}$exo$::jsonb),
  ('15fea229-b517-5dd4-b5f9-8f88c667ec32'::uuid, 2, 'application', $exo${"titre":"Le sel qui disparaît","consigne":"Suis l'expérience de Sam et réponds aux questions en justifiant tes réponses.","enonce":"Sam pose un verre contenant **200 g d'eau** sur une balance. Il ajoute **20 g de sel** et mélange : le sel n'est plus visible.\n\n1. Nomme le soluté, le solvant et le mélange obtenu. Ce mélange est-il homogène ou hétérogène ?\n2. Quelle masse la balance affiche-t-elle après le mélange (le verre n'est pas compté) ? Que prouve ce résultat ?\n3. Sam ajoute encore beaucoup de sel. À partir d'un moment, du sel reste au fond, même en mélangeant. Comment appelle-t-on alors la solution ?\n4. Sam veut récupérer le sel dissous. Il propose de filtrer l'eau salée. Explique pourquoi cela ne marche pas, puis propose la bonne technique.","bareme":[{"critere":"Soluté, solvant, solution et type de mélange","points":5},{"critere":"Masse de la solution et conservation","points":5},{"critere":"Solution saturée","points":3},{"critere":"Filtration inefficace et évaporation proposée","points":7}],"dureeMin":10,"corrige":"1. Le **soluté** est le sel, le **solvant** est l'eau, le mélange obtenu est une **solution** (eau salée). C'est un mélange **homogène** : on ne distingue plus le sel.\n\n2. 200 g + 20 g = **220 g**. La masse s'est conservée : le sel n'a pas disparu, il s'est **dissous** dans l'eau.\n\n3. La solution est **saturée** : l'eau ne peut plus dissoudre de sel, le surplus reste au fond.\n\n4. La filtration retient seulement les **particules solides**. Or le sel est **dissous**, il n'est pas en morceaux : il traverse le filtre et le filtrat reste salé. La filtration ne sépare pas un mélange homogène. Il faut faire une **évaporation** : on chauffe pour faire partir l'eau, et le sel reste au fond du récipient (comme dans les marais salants)."}$exo$::jsonb),
  ('15fea229-b517-5dd4-b5f9-8f88c667ec32'::uuid, 3, 'application', $exo${"titre":"Récupérer le sable et le sel d'une eau boueuse","consigne":"Propose et explique un protocole de séparation, puis calcule les masses obtenues.","enonce":"Inès prépare un mélange avec **500 g d'eau**, **30 g de sable** et **15 g de sel**. Elle agite : le sel se dissout, le sable reste en grains dans l'eau.\n\n1. Ce mélange est-il homogène ou hétérogène ? Justifie.\n2. Quelle est la masse totale du mélange ?\n3. Inès veut récupérer séparément le sable et le sel. Décris dans l'ordre les **trois techniques** qu'elle peut utiliser : décantation, filtration, évaporation. Pour chacune, dis ce qu'elle permet d'obtenir.\n4. Le liquide récupéré après la filtration est-il homogène ou hétérogène ? Comment s'appelle-t-il ?\n5. On suppose qu'il n'y a aucune perte. Quelle masse de sable sec et quelle masse de sel Inès récupère-t-elle ? Justifie.","bareme":[{"critere":"Nature du mélange de départ justifiée","points":3},{"critere":"Masse totale du mélange","points":3},{"critere":"Protocole en trois étapes expliqué","points":7},{"critere":"Nature et nom du liquide filtré","points":3},{"critere":"Masses de sable et de sel récupérées","points":4}],"dureeMin":16,"corrige":"1. Le mélange est **hétérogène** : on distingue au moins deux constituants (les grains de sable et l'eau).\n\n2. 500 + 30 + 15 = **545 g**.\n\n3.\n- **Décantation** : on laisse reposer, le sable (plus lourd) tombe au fond ; on transvase doucement l'eau du dessus.\n- **Filtration** : on verse le liquide dans un filtre qui **retient les grains de sable** restants. On récupère le sable dans le filtre.\n- **Évaporation** : on chauffe le liquide filtré pour faire partir l'eau ; le **sel** reste au fond du récipient.\n\n4. Le liquide filtré est de l'eau salée : c'est un mélange **homogène** (le sel est dissous). On l'appelle le **filtrat**.\n\n5. Sans perte, les masses se conservent : Inès récupère **30 g de sable** et **15 g de sel**, c'est-à-dire exactement ce qu'elle avait mis. Le sel ne s'est pas évaporé : seule l'eau est partie."}$exo$::jsonb),
  ('2b1bbb82-48de-501e-a86f-cf631a7d4adb'::uuid, 1, 'application', $exo${"titre":"Reconnaître les formes et les sources d'énergie","consigne":"Réponds à chaque question par une phrase complète.","enonce":"1. Pour chaque situation, donne la forme d'énergie mise en jeu :\n   - a) une voiture qui roule ;\n   - b) l'eau retenue en hauteur derrière un barrage ;\n   - c) une bûche de bois pas encore brûlée ;\n   - d) un radiateur chaud ;\n   - e) la lumière d'une lampe allumée.\n2. Classe ces sources d'énergie en **renouvelables** ou **non renouvelables** : vent, pétrole, Soleil, charbon, uranium, biomasse.\n3. Dans quelle unité mesure-t-on l'énergie ? Quelle unité trouve-t-on sur une facture d'électricité ?","bareme":[{"critere":"Formes d'énergie des cinq situations","points":10},{"critere":"Classement des six sources","points":6},{"critere":"Unités de l'énergie","points":4}],"dureeMin":7,"corrige":"1.\n- a) énergie **cinétique** (liée au mouvement) ;\n- b) énergie **de position** (liée à la hauteur) ;\n- c) énergie **chimique** (stockée dans le bois) ;\n- d) énergie **thermique** (liée à la température) ;\n- e) énergie **lumineuse**.\n\n2. **Renouvelables** : vent, Soleil, biomasse (elles se reconstituent à l'échelle humaine). **Non renouvelables** : pétrole, charbon, uranium (leurs réserves s'épuisent).\n\n3. L'énergie se mesure en **joules (J)**. Sur une facture d'électricité, on trouve le **kilowattheure (kWh)**."}$exo$::jsonb),
  ('2b1bbb82-48de-501e-a86f-cf631a7d4adb'::uuid, 2, 'application', $exo${"titre":"Les sources d'énergie d'une commune","consigne":"Lis le document, puis réponds aux questions en justifiant avec le cours.","enonce":"**Document.** La commune de Valbois produit ou achète son énergie ainsi :\n\n| Source | Usage |\n|---|---|\n| Gaz naturel | chauffage de l'école |\n| Bois des forêts voisines | chaufferie du gymnase |\n| Vent | éoliennes sur la colline |\n| Pétrole | carburant des bus |\n| Soleil | panneaux sur la mairie |\n\n1. Classe les cinq sources en renouvelables et non renouvelables. Donne la définition de chaque famille.\n2. Parmi les sources non renouvelables, lesquelles sont des énergies **fossiles** ?\n3. Le maire affirme : « Presque toutes nos énergies viennent du Soleil. » Explique pourquoi il a raison en prenant l'exemple du vent et du bois.\n4. Dans une lampe de poche, écris la chaîne d'énergie « source → convertisseur → utilisation », en précisant la forme d'énergie de la source.","bareme":[{"critere":"Classement et définitions des deux familles","points":6},{"critere":"Identification des énergies fossiles","points":4},{"critere":"Le Soleil, source d'origine, expliqué","points":5},{"critere":"Chaîne d'énergie de la lampe de poche","points":5}],"dureeMin":11,"corrige":"1. **Renouvelables** (elles se reconstituent à l'échelle humaine) : le bois (biomasse), le vent, le Soleil. **Non renouvelables** (leurs réserves s'épuisent) : le gaz naturel, le pétrole.\n\n2. Le **gaz naturel** et le **pétrole** sont des énergies fossiles.\n\n3. Le Soleil est la source d'origine de presque toutes les autres énergies. Le **vent** est produit grâce au Soleil qui chauffe l'air. Le **bois** vient des arbres, qui ont poussé grâce à la lumière du Soleil. Même le pétrole descend du Soleil.\n\n4. Pile (énergie **chimique**) → ampoule (convertisseur) → **lumière et chaleur**."}$exo$::jsonb),
  ('2b1bbb82-48de-501e-a86f-cf631a7d4adb'::uuid, 3, 'application', $exo${"titre":"L'énergie du mouvement et ses origines","consigne":"Compare les situations, justifie chaque réponse avec le cours et rédige tes explications.","enonce":"**Situation A.** Un vélo et un camion roulent tous les deux à **30 km/h**.\n\n**Situation B.** La même voiture roule d'abord à **30 km/h**, puis à **50 km/h**.\n\n**Situation C.** Léo mange une tartine au petit-déjeuner, puis pédale jusqu'au collège.\n\n1. Quelle forme d'énergie possèdent tous les véhicules qui roulent ? À quoi est-elle liée ?\n2. Dans la situation A, lequel a le plus d'énergie de mouvement ? Justifie.\n3. Dans la situation B, dans quel cas la voiture a-t-elle le plus d'énergie de mouvement ? Explique pourquoi la vitesse compte **beaucoup**.\n4. Dans la situation C, quelle forme d'énergie contient la tartine ? En quelle forme est-elle transformée quand Léo pédale ?\n5. Explique pourquoi on peut dire que l'énergie de la tartine vient, à l'origine, du Soleil.","bareme":[{"critere":"Énergie cinétique liée au mouvement","points":3},{"critere":"Comparaison selon la masse","points":4},{"critere":"Comparaison selon la vitesse","points":4},{"critere":"Énergie chimique convertie en énergie cinétique","points":5},{"critere":"Le Soleil à l'origine de l'énergie des aliments","points":4}],"dureeMin":15,"corrige":"1. Ils possèdent de l'**énergie cinétique**, liée au **mouvement**.\n\n2. L'énergie cinétique augmente avec la **masse**. À la même vitesse, le **camion**, bien plus lourd que le vélo, a le plus d'énergie cinétique.\n\n3. L'énergie cinétique augmente **beaucoup** avec la vitesse : la voiture en a le plus à **50 km/h**. Une petite hausse de vitesse donne une forte hausse d'énergie : c'est pour cela que les chocs à grande vitesse sont bien plus graves.\n\n4. La tartine contient de l'énergie **chimique** (stockée dans les aliments). Quand Léo pédale, elle est transformée en énergie **cinétique** (le mouvement de Léo et du vélo), avec une partie en chaleur.\n\n5. Le pain est fait avec du blé, une **plante**. Les plantes poussent grâce à la **lumière du Soleil**. L'énergie de la tartine vient donc, à l'origine, du Soleil."}$exo$::jsonb),
  ('98cc7d1d-fd6a-5e8d-b7b6-ce6fca9d58cb'::uuid, 1, 'application', $exo${"titre":"Les convertisseurs d'énergie","consigne":"Pour chaque appareil, indique la conversion d'énergie qu'il réalise, puis réponds aux questions.","enonce":"1. Pour chaque convertisseur, écris « énergie … → énergie … » :\n   - a) une pile ;\n   - b) un moteur électrique ;\n   - c) un panneau solaire ;\n   - d) une éolienne.\n2. Une lampe allumée produit surtout de l'énergie lumineuse. Quelle autre forme d'énergie produit-elle ?\n3. Recopie et complète la phrase : « L'énergie ne se … pas et ne … pas : elle change de … . »","bareme":[{"critere":"Conversions des quatre convertisseurs","points":12},{"critere":"Énergie thermique produite par la lampe","points":3},{"critere":"Principe de conservation de l'énergie","points":5}],"dureeMin":6,"corrige":"1.\n- a) pile : énergie **chimique** → énergie **électrique** ;\n- b) moteur électrique : énergie **électrique** → énergie **cinétique** ;\n- c) panneau solaire : énergie **lumineuse** → énergie **électrique** ;\n- d) éolienne : énergie **cinétique** (du vent) → énergie **électrique**.\n\n2. Elle produit aussi de l'énergie **thermique** (de la chaleur).\n\n3. « L'énergie ne se **crée** pas et ne **disparaît** pas : elle change de **forme**. »"}$exo$::jsonb),
  ('98cc7d1d-fd6a-5e8d-b7b6-ce6fca9d58cb'::uuid, 2, 'application', $exo${"titre":"Ampoule à filament ou LED ?","consigne":"Exploite les données des deux lampes, fais les calculs et justifie ton choix.","enonce":"On fournit **100 J** d'énergie électrique à deux lampes.\n\n| Lampe | Énergie lumineuse | Énergie thermique |\n|---|---|---|\n| Ampoule à filament | 5 J | ? |\n| Lampe LED (dans cet exercice) | 40 J | ? |\n\n1. En utilisant la conservation de l'énergie, calcule l'énergie thermique produite par chaque lampe.\n2. Quelle est l'énergie **utile** pour une lampe ? Laquelle des deux lampes a le meilleur **rendement** ? Justifie.\n3. Explique pourquoi une ampoule à filament allumée brûlait les doigts.\n4. Un camarade dit : « Dans l'ampoule à filament, 95 J ont été détruits. » Corrige-le.","bareme":[{"critere":"Calcul des deux énergies thermiques","points":6},{"critere":"Énergie utile et comparaison des rendements","points":6},{"critere":"Explication de la chaleur de l'ampoule","points":4},{"critere":"L'énergie perdue est dispersée, pas détruite","points":4}],"dureeMin":10,"corrige":"1. L'énergie se conserve : énergie reçue = énergie lumineuse + énergie thermique.\n- Ampoule à filament : 100 − 5 = **95 J** d'énergie thermique.\n- LED : 100 − 40 = **60 J** d'énergie thermique.\n\n2. Pour une lampe, l'énergie **utile** est l'énergie **lumineuse**. Le rendement compare l'énergie utile à l'énergie consommée. Pour la même énergie consommée (100 J), la LED donne 40 J de lumière contre 5 J : la **LED** a le meilleur rendement, elle gaspille moins.\n\n3. L'ampoule à filament transforme **95 %** de l'énergie reçue en **chaleur** : elle devient très chaude, d'où les brûlures.\n\n4. Les 95 J ne sont **pas détruits** : ils sont **dispersés** sous forme de chaleur dans la pièce, une forme qu'on ne peut plus utiliser. L'énergie ne se perd jamais."}$exo$::jsonb),
  ('98cc7d1d-fd6a-5e8d-b7b6-ce6fca9d58cb'::uuid, 3, 'application', $exo${"titre":"Du barrage à la trottinette électrique","consigne":"Analyse les deux chaînes de conversion, fais les calculs et justifie chaque réponse avec le cours.","enonce":"**Document 1 — Le barrage.** L'eau stockée en hauteur descend dans des conduites et fait tourner une machine qui produit de l'électricité. Pour **1 000 J** d'énergie de position au départ, on obtient **900 J** d'énergie électrique.\n\n**Document 2 — La trottinette.** Son moteur électrique reçoit **200 J** d'énergie électrique et fournit **160 J** d'énergie cinétique.\n\n1. Écris les conversions d'énergie successives dans le barrage.\n2. Dans le barrage, que sont devenus les joules qui ne sont pas devenus électriques ? Calcule leur valeur.\n3. Pour la trottinette, quelle est l'énergie utile ? Calcule l'énergie qui part en chaleur.\n4. Pour chaque système, calcule la part d'énergie utile sur 100 J consommés. Lequel a le meilleur rendement ?\n5. Cite deux gestes du quotidien qui permettent d'économiser l'énergie, et explique l'intérêt de choisir des appareils à bon rendement.","bareme":[{"critere":"Conversions successives du barrage","points":4},{"critere":"Pertes du barrage en chaleur calculées","points":4},{"critere":"Énergie utile et pertes de la trottinette","points":4},{"critere":"Comparaison des rendements","points":4},{"critere":"Gestes d'économie et intérêt du bon rendement","points":4}],"dureeMin":18,"corrige":"1. Énergie **de position** → énergie **cinétique** (l'eau en mouvement fait tourner la machine) → énergie **électrique**.\n\n2. Aucune conversion n'est parfaite : les joules manquants sont partis en **chaleur**, dispersée et inutilisable. Valeur : 1 000 − 900 = **100 J**.\n\n3. L'énergie utile est l'énergie **cinétique** (le mouvement de la trottinette) : 160 J. Chaleur : 200 − 160 = **40 J**.\n\n4. Barrage : 900 J utiles pour 1 000 J, soit **90 J pour 100 J**. Trottinette : 160 J utiles pour 200 J, soit 160 ÷ 2 = **80 J pour 100 J**. Le **barrage** a le meilleur rendement : il gaspille moins.\n\n5. Exemples : **éteindre les veilles**, **isoler son logement**, préférer les transports en commun. Un appareil à bon rendement transforme une plus grande part de l'énergie consommée en énergie utile : il en gaspille moins, donc il faut produire moins d'énergie pour le même service."}$exo$::jsonb),
  ('9ea53d6d-ae8f-5d85-9f06-fd87faae0cad'::uuid, 1, 'application', $exo${"titre":"Comment fonctionne une centrale électrique ?","consigne":"Réponds aux questions en rédigeant des phrases complètes.","enonce":"1. Recopie et complète la chaîne commune à la plupart des centrales : « Quelque chose fait tourner une … → elle entraîne un … → qui produit l' … . »\n2. Pour chaque centrale, dis ce qui fait tourner la turbine :\n   - a) une centrale hydraulique ;\n   - b) une centrale nucléaire ;\n   - c) une éolienne.\n3. Quel moyen de production est une exception, car il n'utilise ni turbine ni alternateur ?","bareme":[{"critere":"Chaîne turbine, alternateur, électricité","points":6},{"critere":"Ce qui entraîne la turbine dans les trois centrales","points":9},{"critere":"L'exception du photovoltaïque","points":5}],"dureeMin":6,"corrige":"1. « Quelque chose fait tourner une **turbine** → elle entraîne un **alternateur** → qui produit l'**électricité**. »\n\n2.\n- a) centrale hydraulique : l'**eau d'un barrage** ;\n- b) centrale nucléaire : de la **vapeur**, chauffée par la **fission de l'uranium** ;\n- c) éolienne : le **vent**.\n\n3. Le **panneau photovoltaïque** (solaire) : il produit l'électricité **directement** à partir de la lumière."}$exo$::jsonb),
  ('9ea53d6d-ae8f-5d85-9f06-fd87faae0cad'::uuid, 2, 'application', $exo${"titre":"Le mix énergétique d'un pays","consigne":"Lis le document, fais les calculs demandés et justifie tes réponses.","enonce":"**Document.** Production d'électricité d'un pays imaginaire, en pourcentage :\n\n| Centrale | Part |\n|---|---|\n| Nucléaire | 60 % |\n| Thermique à flamme | 13 % |\n| Hydraulique | 12 % |\n| Éolienne | 10 % |\n| Photovoltaïque | 5 % |\n\n1. Calcule la part totale des énergies **renouvelables** dans ce pays.\n2. Parmi ces centrales, lesquelles utilisent de la **vapeur** pour faire tourner la turbine ?\n3. Donne l'inconvénient principal de la centrale thermique à flamme, puis celui de la centrale nucléaire.\n4. Pourquoi ce pays ne produit-il pas toute son électricité avec des éoliennes et des panneaux solaires ? Explique ce qu'est le **mix énergétique**.","bareme":[{"critere":"Calcul de la part renouvelable","points":5},{"critere":"Centrales utilisant la vapeur","points":4},{"critere":"Inconvénients du thermique et du nucléaire","points":6},{"critere":"Limites des renouvelables et définition du mix","points":5}],"dureeMin":11,"corrige":"1. Renouvelables : hydraulique + éolienne + photovoltaïque = 12 + 10 + 5 = **27 %**.\n\n2. La centrale **thermique à flamme** (vapeur produite en brûlant charbon, gaz ou fioul) et la centrale **nucléaire** (vapeur chauffée par la fission de l'uranium).\n\n3. La centrale thermique à flamme rejette du **dioxyde de carbone**, principal gaz à effet de serre. La centrale nucléaire ne rejette presque pas de CO₂, mais produit des **déchets radioactifs** à stocker très longtemps.\n\n4. Les renouvelables ont peu d'impact en fonctionnement, mais elles **dépendent de la météo** (pas de vent, pas de soleil la nuit) et occupent de l'espace. Aucune source ne convient à tout : on **combine** plusieurs moyens de production. Cette combinaison est le **mix énergétique** du pays."}$exo$::jsonb),
  ('9ea53d6d-ae8f-5d85-9f06-fd87faae0cad'::uuid, 3, 'application', $exo${"titre":"Une famille réduit sa consommation d'électricité","consigne":"Analyse la situation de la famille Martin, fais les calculs et justifie tes propositions avec le cours.","enonce":"La famille Martin consomme **4 000 kWh** d'électricité par an. Sur ce total :\n\n| Poste | Consommation par an |\n|---|---|\n| Chauffage | 2 400 kWh |\n| Veilles des appareils | 200 kWh |\n| Autres usages | 1 400 kWh |\n\n1. Vérifie que la somme des postes correspond bien à la consommation totale.\n2. Quel poste consomme le plus ? Quel geste du cours permet de le réduire ?\n3. Après des travaux d'isolation, la consommation du chauffage est **divisée par deux**. La famille éteint aussi **toutes** ses veilles. Calcule la nouvelle consommation annuelle.\n4. Pour remplacer son vieux réfrigérateur, que doit regarder la famille avant d'acheter ? Pourquoi ?\n5. Explique la phrase : « La meilleure énergie est celle qu'on ne consomme pas », en t'appuyant sur les impacts des centrales.","bareme":[{"critere":"Vérification de la somme","points":3},{"critere":"Poste principal et isolation","points":4},{"critere":"Calcul de la nouvelle consommation","points":5},{"critere":"Étiquette énergie","points":3},{"critere":"Explication liée aux impacts de la production","points":5}],"dureeMin":17,"corrige":"1. 2 400 + 200 + 1 400 = **4 000 kWh** : la somme est juste.\n\n2. Le **chauffage** (2 400 kWh). Il faut **isoler** le logement : c'est le premier poste de consommation.\n\n3. Chauffage : 2 400 ÷ 2 = 1 200 kWh. Veilles : 0 kWh. Nouvelle consommation : 1 200 + 0 + 1 400 = **2 600 kWh** par an, soit 1 400 kWh d'économie.\n\n4. Elle doit lire l'**étiquette énergie** : elle indique si l'appareil consomme peu ou beaucoup, ce qui permet de choisir un appareil économe.\n\n5. Toute production d'électricité a un impact : les centrales thermiques à flamme rejettent du **dioxyde de carbone**, les centrales nucléaires produisent des **déchets radioactifs**, et les renouvelables occupent de l'espace et dépendent de la météo. Une énergie qu'on ne consomme pas n'a pas besoin d'être produite : elle n'a **aucun impact**."}$exo$::jsonb),
  ('75790460-e7f4-5cfc-a29a-91ef157d89b1'::uuid, 1, 'application', $exo${"titre":"Sources de lumière et propagation du son","consigne":"Réponds aux questions en rédigeant des phrases complètes.","enonce":"1. Classe ces objets en **sources primaires** ou **objets diffusants** : le Soleil, la Lune, une flamme de bougie, un mur blanc, une lampe allumée, ton cahier.\n2. Explique pourquoi tu peux voir la Lune la nuit, alors qu'elle ne produit pas de lumière.\n3. Comment la lumière se propage-t-elle dans un milieu transparent et homogène ?\n4. Le son peut-il se propager dans le vide ? Justifie.","bareme":[{"critere":"Classement des six objets","points":6},{"critere":"Explication de la vision de la Lune","points":5},{"critere":"Propagation rectiligne de la lumière","points":4},{"critere":"Le son ne se propage pas dans le vide","points":5}],"dureeMin":7,"corrige":"1. **Sources primaires** (elles produisent leur propre lumière) : le Soleil, la flamme de bougie, la lampe allumée. **Objets diffusants** (ils renvoient la lumière reçue) : la Lune, le mur blanc, le cahier.\n\n2. La Lune **renvoie** (diffuse) la lumière qu'elle reçoit du Soleil. Cette lumière **entre dans notre œil** : c'est pour cela qu'on la voit.\n\n3. Elle se propage **en ligne droite**.\n\n4. Non. Le son a besoin d'un **milieu matériel** (air, eau, solide) pour se propager. Dans le vide, il n'y a pas de matière : le son ne passe pas."}$exo$::jsonb),
  ('75790460-e7f4-5cfc-a29a-91ef157d89b1'::uuid, 2, 'application', $exo${"titre":"À quelle distance est l'orage ?","consigne":"Utilise les données pour calculer la distance de l'orage et explique tes réponses.","enonce":"Pendant un orage, Chloé voit un éclair. Elle compte : elle entend le tonnerre **6 secondes** plus tard.\n\n**Données :** vitesse du son dans l'air : environ **340 m/s** ; vitesse de la lumière : environ **300 000 km/s**.\n\n1. Pourquoi Chloé voit-elle l'éclair avant d'entendre le tonnerre ?\n2. Le son parcourt 340 m en 1 seconde. Calcule la distance parcourue par le son en 6 secondes. Donne le résultat en mètres, puis arrondi au kilomètre.\n3. Un peu plus tard, Chloé entend le tonnerre **3 secondes** après l'éclair. L'orage s'est-il rapproché ou éloigné ? Justifie.\n4. Le tonnerre est un bruit très fort. Explique pourquoi un son trop fort est dangereux pour l'oreille.","bareme":[{"critere":"Comparaison des vitesses de la lumière et du son","points":5},{"critere":"Calcul de la distance de l'orage","points":6},{"critere":"Rapprochement de l'orage justifié","points":4},{"critere":"Danger du bruit pour l'oreille","points":5}],"dureeMin":10,"corrige":"1. La lumière va **beaucoup plus vite** que le son (environ 300 000 km/s contre 340 m/s, près d'un million de fois plus vite). La lumière de l'éclair arrive presque instantanément, le son met plus de temps.\n\n2. Distance = 340 × 6 = **2 040 m**, soit environ **2 km**.\n\n3. En 3 secondes, le son parcourt 340 × 3 = 1 020 m, soit environ 1 km. Le tonnerre met moins de temps à arriver : l'orage s'est **rapproché**.\n\n4. Un son trop fort ou trop long **détruit les cellules de l'oreille interne**. Ces cellules **ne se régénèrent pas** : la perte d'audition est **définitive**."}$exo$::jsonb),
  ('75790460-e7f4-5cfc-a29a-91ef157d89b1'::uuid, 3, 'application', $exo${"titre":"Lumière et son, du Soleil à la plongée","consigne":"Analyse chaque situation, fais les calculs et justifie avec les propriétés de la lumière et du son.","enonce":"**Données :** vitesse de la lumière : environ **300 000 km/s** ; vitesse du son dans l'air : environ **340 m/s** ; distance Terre–Soleil : environ **150 000 000 km**.\n\n1. Il se produit sans cesse d'énormes explosions à la surface du Soleil. Explique pourquoi on voit le Soleil mais on n'entend jamais ces explosions.\n2. La lumière parcourt 300 000 km en 1 seconde. Calcule la durée que met la lumière du Soleil pour arriver sur Terre, en secondes, puis en minutes et secondes.\n3. Dans une piscine, Adam, la tête sous l'eau, entend son ami taper sur l'échelle métallique. Qu'en déduis-tu sur la propagation du son ?\n4. Le soir, une lampe éclaire un ballon posé sur le sol. Nomme les deux sortes d'ombre que l'on observe et dis où se trouve chacune. Quelle propriété de la lumière explique l'ombre ?","bareme":[{"critere":"Lumière dans le vide, son sans milieu matériel","points":5},{"critere":"Calcul de la durée du trajet de la lumière","points":5},{"critere":"Propagation du son dans l'eau et les solides","points":4},{"critere":"Ombre propre, ombre portée et propagation rectiligne","points":6}],"dureeMin":16,"corrige":"1. Entre le Soleil et la Terre, il y a surtout du **vide**. La **lumière traverse le vide** : on voit le Soleil. Le **son ne se propage pas dans le vide**, car il lui faut un milieu matériel : le bruit des explosions ne nous parvient pas.\n\n2. Durée = 150 000 000 ÷ 300 000 = **500 s**. Or 500 s = 8 × 60 s + 20 s, soit **8 min 20 s**.\n\n3. Le son s'est propagé dans le **métal** de l'échelle et dans l'**eau** jusqu'à l'oreille d'Adam. Le son se propage donc aussi dans les **liquides** et les **solides**, pas seulement dans l'air.\n\n4. L'**ombre propre** est la face du ballon **non éclairée** par la lampe. L'**ombre portée** est la zone sombre **sur le sol**, derrière le ballon. Elles s'expliquent par la **propagation rectiligne** de la lumière : la lumière va en ligne droite et ne peut pas contourner le ballon."}$exo$::jsonb),
  ('0ab6cde9-a094-513d-82a0-3abb3beebed8'::uuid, 1, 'application', $exo${"titre":"La chaîne de transmission d'une information","consigne":"Réponds aux questions en rédigeant des phrases complètes.","enonce":"1. Nomme les trois éléments d'une chaîne de transmission et donne le rôle de chacun.\n2. Autrefois, des guetteurs envoyaient des **signaux de fumée** d'une colline à une autre. Dans cette situation, identifie l'émetteur, le canal et le récepteur.\n3. Qu'est-ce que le langage **binaire** ?","bareme":[{"critere":"Les trois éléments et leurs rôles","points":8},{"critere":"Chaîne des signaux de fumée","points":7},{"critere":"Définition du binaire","points":5}],"dureeMin":6,"corrige":"1. L'**émetteur** code l'information ; le **canal** la transporte ; le **récepteur** la décode.\n\n2. L'émetteur est le **guetteur qui fait la fumée** (il code le message avec la fumée). Le canal est **l'air**, dans lequel la fumée est visible. Le récepteur est le **guetteur de l'autre colline**, qui voit la fumée et décode le message.\n\n3. Le binaire est un code qui n'utilise que **deux états : 0 et 1**. Les textes, images et sons sont convertis en 0 et 1 pour être transmis, puis reconvertis à l'arrivée."}$exo$::jsonb),
  ('0ab6cde9-a094-513d-82a0-3abb3beebed8'::uuid, 2, 'application', $exo${"titre":"Supports de transmission et stockage de photos","consigne":"Identifie les supports utilisés, puis fais les calculs de stockage en détaillant tes étapes.","enonce":"Maël envoie des photos de vacances à sa grand-mère.\n\n- Son téléphone se connecte à la box par le **wifi**.\n- La box est reliée au réseau par la **fibre optique**.\n- La box est branchée à la prise par un **câble électrique**.\n\n1. Pour chacun des trois supports (wifi, fibre optique, câble électrique), dis sous quelle forme voyage l'information ou l'énergie.\n2. Parmi ces supports, lequel est le plus rapide et transporte le plus de données ?\n3. Chaque photo pèse **4 Mo**. Maël a une clé USB de **16 Go**. On prend **1 Go = 1 000 Mo**. Combien de photos peut-il stocker au maximum sur sa clé ? Détaille le calcul.\n4. Maël préfère stocker ses photos « dans le cloud ». Explique ce qu'est réellement le cloud.","bareme":[{"critere":"Forme de l'information sur les trois supports","points":6},{"critere":"La fibre, support le plus performant","points":3},{"critere":"Calcul du nombre de photos","points":6},{"critere":"Explication du cloud","points":5}],"dureeMin":10,"corrige":"1. Wifi : des **ondes**, qui se propagent sans fil. Fibre optique : de la **lumière**, dans un fil de verre très fin. Câble électrique : un **courant**.\n\n2. La **fibre optique** est le support le plus rapide et celui qui transporte le plus de données.\n\n3. 16 Go = 16 × 1 000 = 16 000 Mo. Nombre de photos : 16 000 ÷ 4 = **4 000 photos**.\n\n4. Le cloud n'est pas un nuage : c'est un **serveur distant**, c'est-à-dire l'**ordinateur de quelqu'un d'autre**, sur lequel ses photos sont enregistrées."}$exo$::jsonb),
  ('0ab6cde9-a094-513d-82a0-3abb3beebed8'::uuid, 3, 'application', $exo${"titre":"Du tambour au message numérique","consigne":"Analyse l'histoire des transmissions et les situations proposées ; justifie chaque réponse avec le cours.","enonce":"1. Range dans l'ordre chronologique ces moyens de transmission : téléphone, pigeons voyageurs, fibre optique, signaux de fumée, télégraphe, satellites.\n2. Cite les trois choses que chaque progrès a permis d'augmenter.\n3. Pour le réseau, une chanson et un message ne diffèrent que par le nombre de 0 et de 1. Une chanson pèse **5 Mo** et un court message **1 ko**. On prend **1 Mo = 1 000 ko**. Combien de courts messages faut-il pour atteindre la taille de la chanson ?\n4. **Situation.** Emma publie sur un réseau social une photo de sa copine sans lui demander, puis l'efface au bout d'une heure. Elle pense : « Je l'ai supprimée, donc elle n'existe plus. » Explique pourquoi elle se trompe, en utilisant le cours.","bareme":[{"critere":"Ordre chronologique des six moyens","points":5},{"critere":"Vitesse, distance et quantité d'information","points":3},{"critere":"Calcul du nombre de messages","points":5},{"critere":"Analyse de la situation d'Emma","points":7}],"dureeMin":15,"corrige":"1. Signaux de fumée → pigeons voyageurs → télégraphe → téléphone → satellites → fibre optique.\n\n2. Chaque progrès a augmenté la **vitesse**, la **distance** et la **quantité** d'information transmise.\n\n3. 5 Mo = 5 × 1 000 = 5 000 ko. Nombre de messages : 5 000 ÷ 1 = **5 000 messages**.\n\n4. Une information transmise peut être **copiée**, **conservée** et **rediffusée** sans qu'on le sache. Pendant l'heure où la photo était en ligne, d'autres personnes ont pu l'enregistrer ou la partager : elle peut exister encore ailleurs, par exemple sur des serveurs. Ce qu'on publie **échappe vite à son auteur**. Emma aurait dû demander l'accord de sa copine avant de publier."}$exo$::jsonb),
  ('01deaec9-dee1-5717-be7c-2f4efeb815ed'::uuid, 1, 'application', $exo${"titre":"Référentiel, trajectoire et vitesse moyenne","consigne":"Réponds aux questions et détaille ton calcul.","enonce":"1. Paul est assis dans un train qui roule. Est-il immobile ou en mouvement ? Réponds en précisant le **référentiel** : par rapport au train, puis par rapport au quai.\n2. Donne le type de trajectoire (rectiligne, circulaire ou curviligne) :\n   - a) une nacelle de grande roue ;\n   - b) une bille qui roule sur une table lisse ;\n   - c) un ballon lancé vers un panier.\n3. Un cycliste parcourt **60 km en 3 h**. Calcule sa vitesse moyenne en km/h.","bareme":[{"critere":"Mouvement selon le référentiel","points":6},{"critere":"Types de trajectoires","points":6},{"critere":"Calcul de la vitesse moyenne avec unité","points":8}],"dureeMin":7,"corrige":"1. Par rapport au **train**, Paul est **immobile**. Par rapport au **quai**, Paul est **en mouvement**.\n\n2.\n- a) **circulaire** ;\n- b) **rectiligne** ;\n- c) **curviligne**.\n\n3. v = d ÷ t = 60 ÷ 3 = **20 km/h**."}$exo$::jsonb),
  ('01deaec9-dee1-5717-be7c-2f4efeb815ed'::uuid, 2, 'application', $exo${"titre":"La course d'Inès sur la piste","consigne":"Calcule les grandeurs demandées en écrivant la formule, le calcul et l'unité.","enonce":"Inès court **400 m** en **80 s** sur la piste du stade.\n\n1. Calcule sa vitesse moyenne en m/s.\n2. Pour passer de km/h à m/s, on divise par 3,6. Déduis-en la vitesse d'Inès en km/h.\n3. Si elle gardait cette vitesse moyenne pendant **10 minutes**, quelle distance parcourrait-elle ? Attention aux unités.\n4. Son frère court **1 500 m** à la vitesse moyenne de **5 m/s**. Combien de temps met-il ?","bareme":[{"critere":"Vitesse moyenne en m/s","points":5},{"critere":"Conversion en km/h","points":4},{"critere":"Distance en 10 minutes avec conversion de la durée","points":6},{"critere":"Durée de la course du frère","points":5}],"dureeMin":11,"corrige":"1. v = d ÷ t = 400 ÷ 80 = **5 m/s**.\n\n2. On divise par 3,6 pour passer de km/h à m/s, donc on **multiplie par 3,6** pour faire l'inverse : 5 × 3,6 = **18 km/h**.\n\n3. La vitesse est en m/s : la durée doit être en secondes. 10 min = 10 × 60 = 600 s. d = v × t = 5 × 600 = **3 000 m** (soit 3 km).\n\n4. t = d ÷ v = 1 500 ÷ 5 = **300 s**, soit 5 minutes."}$exo$::jsonb),
  ('01deaec9-dee1-5717-be7c-2f4efeb815ed'::uuid, 3, 'application', $exo${"titre":"Le voyage en car de la classe","consigne":"Analyse le voyage, fais les calculs en soignant les unités et justifie tes réponses.","enonce":"Pour une sortie, le car de la classe parcourt **120 km en 1 h 30 min**, en comptant un arrêt de 10 minutes sur une aire.\n\n1. Pendant le trajet, Lina est assise à sa place. Le conducteur dit : « Lina ne bouge pas. » Sa sœur, qui regarde depuis le trottoir, dit : « Lina bouge. » Qui a raison ? Explique.\n2. Convertis la durée du trajet en heures, puis calcule la vitesse moyenne du car en km/h.\n3. Le compteur du car a parfois indiqué 0 km/h, parfois 100 km/h. Est-ce en contradiction avec ta réponse à la question 2 ? Explique.\n4. Sur l'autoroute, le car roule à **72 km/h**. Convertis cette vitesse en m/s.\n5. Au retour, le car roule à la vitesse moyenne de **90 km/h** sur **270 km**. Calcule la durée du trajet.","bareme":[{"critere":"Rôle du référentiel","points":4},{"critere":"Conversion de la durée et vitesse moyenne","points":5},{"critere":"Vitesse moyenne et vitesse non constante","points":4},{"critere":"Conversion de km/h en m/s","points":3},{"critere":"Calcul de la durée du retour","points":4}],"dureeMin":18,"corrige":"1. Les deux ont raison : tout dépend du **référentiel**. Par rapport au **car**, Lina est immobile. Par rapport au **trottoir**, elle est en mouvement. Il faut toujours préciser le référentiel.\n\n2. 1 h 30 min = 1 h + 0,5 h = **1,5 h**. v = d ÷ t = 120 ÷ 1,5 = **80 km/h**.\n\n3. Non. Une vitesse **moyenne** ne veut **pas** dire que la vitesse était constante : le car s'est arrêté (0 km/h), puis a roulé plus vite que 80 km/h à d'autres moments. La moyenne résume l'ensemble du trajet.\n\n4. On divise par 3,6 : 72 ÷ 3,6 = **20 m/s**.\n\n5. t = d ÷ v = 270 ÷ 90 = **3 h**."}$exo$::jsonb),
  ('ce083d23-a734-5ce4-9ca6-ab41f187a0ad'::uuid, 1, 'application', $exo${"titre":"Uniforme, accéléré ou ralenti ?","consigne":"Pour chaque situation, indique la nature du mouvement et justifie en une phrase.","enonce":"1. Dis si le mouvement est **uniforme**, **accéléré** ou **ralenti** :\n   - a) une personne sur un escalator ;\n   - b) une voiture qui démarre au feu vert ;\n   - c) un vélo qui freine avant un stop ;\n   - d) une balle lancée vers le haut, pendant qu'elle monte.\n2. Une nacelle de grande roue tourne toujours à la même vitesse. Décris complètement son mouvement (trajectoire **et** vitesse).\n3. Qu'est-ce qu'un mouvement **rectiligne uniforme** ?","bareme":[{"critere":"Nature des quatre mouvements justifiée","points":10},{"critere":"Mouvement circulaire uniforme de la nacelle","points":5},{"critere":"Définition du rectiligne uniforme","points":5}],"dureeMin":6,"corrige":"1.\n- a) **uniforme** : la vitesse de l'escalator ne change pas ;\n- b) **accéléré** : la vitesse de la voiture augmente ;\n- c) **ralenti** : la vitesse du vélo diminue ;\n- d) **ralenti** : la balle perd de la vitesse en montant.\n\n2. La trajectoire est un cercle et la vitesse ne change pas : le mouvement est **circulaire uniforme**.\n\n3. C'est un mouvement dont la trajectoire est une **ligne droite** et dont la vitesse est **constante**."}$exo$::jsonb),
  ('ce083d23-a734-5ce4-9ca6-ab41f187a0ad'::uuid, 2, 'application', $exo${"titre":"Lire deux chronophotographies","consigne":"Calcule les écarts entre les positions et déduis-en la nature de chaque mouvement.","enonce":"On photographie deux billes toutes les **0,5 seconde**. Les billes se déplacent en ligne droite. On mesure leur position (en cm) sur chaque image.\n\n| Image | 1 | 2 | 3 | 4 | 5 |\n|---|---|---|---|---|---|\n| Bille A (cm) | 0 | 10 | 20 | 30 | 40 |\n| Bille B (cm) | 0 | 2 | 8 | 18 | 32 |\n\n1. Qu'est-ce qu'une chronophotographie ? Pourquoi est-ce l'espacement entre les positions qui renseigne sur la vitesse ?\n2. Calcule les écarts entre deux positions successives pour chaque bille.\n3. Déduis-en la nature du mouvement de chaque bille (trajectoire et vitesse).\n4. L'une des billes dévale une pente, l'autre roule sur un tapis roulant. Laquelle est laquelle ? Justifie.","bareme":[{"critere":"Définition de la chronophotographie et rôle de l'espacement","points":5},{"critere":"Calcul des écarts des deux billes","points":6},{"critere":"Nature des deux mouvements","points":5},{"critere":"Association aux situations justifiée","points":4}],"dureeMin":11,"corrige":"1. Une chronophotographie est une suite de photos prises à **intervalles de temps réguliers**. Comme la durée entre deux images est toujours la même, plus l'écart est grand, plus l'objet a parcouru de distance dans ce temps, donc plus il va vite.\n\n2. Bille A : 10 − 0 = 10 ; 20 − 10 = 10 ; 30 − 20 = 10 ; 40 − 30 = 10 → écarts de **10 cm, 10 cm, 10 cm, 10 cm**.\nBille B : 2 − 0 = 2 ; 8 − 2 = 6 ; 18 − 8 = 10 ; 32 − 18 = 14 → écarts de **2 cm, 6 cm, 10 cm, 14 cm**.\n\n3. Bille A : écarts **égaux** → mouvement **rectiligne uniforme**. Bille B : écarts qui **s'agrandissent** → mouvement **rectiligne accéléré**.\n\n4. La bille A (vitesse constante) roule sur le **tapis roulant**. La bille B (vitesse qui augmente) **dévale la pente**."}$exo$::jsonb),
  ('ce083d23-a734-5ce4-9ca6-ab41f187a0ad'::uuid, 3, 'application', $exo${"titre":"Le freinage d'une voiture et la sécurité","consigne":"Analyse les documents, fais les calculs et rédige une explication justifiée pour chaque question.","enonce":"**Document 1.** Une voiture roule en ligne droite puis freine. On note sa position **toutes les secondes** :\n\n| Temps (s) | 0 | 1 | 2 | 3 | 4 | 5 | 6 |\n|---|---|---|---|---|---|---|---|\n| Position (m) | 0 | 25 | 45 | 60 | 70 | 75 | 75 |\n\n**Document 2.** Distance de freinage sur route sèche (valeurs arrondies) :\n\n| Vitesse | 50 km/h | 100 km/h |\n|---|---|---|\n| Distance de freinage | 14 m | 56 m |\n\n1. Calcule les distances parcourues pendant chaque seconde (document 1).\n2. Décris complètement le mouvement de la voiture entre 0 et 5 s (trajectoire et vitesse). Justifie.\n3. À quel moment la voiture s'arrête-t-elle ? Quelle distance a-t-elle parcourue depuis le début du freinage ?\n4. Document 2 : quand la vitesse est multipliée par 2, par combien la distance de freinage est-elle multipliée ? Que peux-tu en conclure ?\n5. Explique pourquoi on ne doit jamais traverser devant une voiture qui freine.","bareme":[{"critere":"Calcul des distances parcourues chaque seconde","points":4},{"critere":"Mouvement rectiligne ralenti justifié","points":4},{"critere":"Instant d'arrêt et distance totale","points":4},{"critere":"Exploitation du document sur la distance de freinage","points":4},{"critere":"Explication de la règle de sécurité","points":4}],"dureeMin":18,"corrige":"1. Entre 0 et 1 s : 25 m ; entre 1 et 2 s : 45 − 25 = 20 m ; entre 2 et 3 s : 60 − 45 = 15 m ; entre 3 et 4 s : 70 − 60 = 10 m ; entre 4 et 5 s : 75 − 70 = 5 m ; entre 5 et 6 s : 75 − 75 = 0 m.\n\n2. La voiture va en ligne droite : trajectoire **rectiligne**. Les durées sont égales (1 s) et les distances parcourues **se resserrent** (25, 20, 15, 10, 5 m) : la vitesse diminue. Le mouvement est **rectiligne ralenti**.\n\n3. La position ne change plus après **5 s** : la voiture s'arrête à 5 s. Elle a parcouru **75 m** depuis le début du freinage.\n\n4. 100 km/h = 2 × 50 km/h, et 56 ÷ 14 = **4** : la distance de freinage est multipliée par 4. Elle **augmente très vite** avec la vitesse : rouler plus vite rend l'arrêt beaucoup plus long.\n\n5. Un mouvement ralenti **ne s'arrête pas instantanément** : même en freinant, la voiture parcourt encore plusieurs mètres (ici 75 m) avant de s'arrêter. Un piéton qui traverse devant elle risque d'être percuté."}$exo$::jsonb),
  ('82cc1a20-c0cf-526a-b188-84ec864c6402'::uuid, 1, 'probleme', $exo${"titre":"Notations et instruments de géométrie","consigne":"Réponds à chaque question en rédigeant des phrases complètes. Utilise les bonnes notations.","enonce":"On considère deux points A et B.\n\n1. Écris la notation de chacun des objets suivants :\n   a. la droite qui passe par A et B ;\n   b. le segment d’extrémités A et B ;\n   c. la demi-droite d’origine A qui passe par B ;\n   d. la longueur du segment d’extrémités A et B.\n2. Explique la différence entre [AB] et (AB).\n3. Quel instrument utilises-tu pour :\n   a. mesurer un angle ;\n   b. tracer un cercle ;\n   c. vérifier qu’un angle est droit ?","bareme":[{"critere":"Notations de la droite, du segment, de la demi-droite et de la longueur","points":8},{"critere":"Explication de la différence entre segment et droite","points":6},{"critere":"Choix des instruments","points":6}],"dureeMin":6,"corrige":"**1.**\n- a. La droite : **(AB)**.\n- b. Le segment : **[AB]**.\n- c. La demi-droite d’origine A : **[AB)**.\n- d. La longueur : **AB** (sans crochets ni parenthèses).\n\n**2.** [AB] est un segment : il est limité par ses deux extrémités A et B, on peut le mesurer. (AB) est une droite : elle passe par A et B mais elle est illimitée des deux côtés, on ne peut pas la mesurer.\n\n**3.**\n- a. Le **rapporteur** mesure un angle.\n- b. Le **compas** trace un cercle.\n- c. L’**équerre** vérifie un angle droit."}$exo$::jsonb),
  ('82cc1a20-c0cf-526a-b188-84ec864c6402'::uuid, 2, 'probleme', $exo${"titre":"Les rues parallèles du quartier","consigne":"Réponds aux questions en justifiant chaque réponse par une propriété du cours. Un dessin ne suffit pas comme preuve.","enonce":"Sur le plan d’un quartier, les rues sont représentées par des droites.\n\n- La rue (d1) est perpendiculaire à l’avenue (d3).\n- La rue (d2) est perpendiculaire à l’avenue (d3).\n\n1. Que peux-tu dire des rues (d1) et (d2) ? Justifie avec une propriété.\n2. On trace une nouvelle rue (d4) perpendiculaire à (d1). Que peux-tu dire des rues (d4) et (d2) ? Justifie.\n3. Le point M est une fontaine qui n’est pas sur l’avenue (d3). Combien de droites parallèles à (d3) passent par M ? Et combien de perpendiculaires à (d3) ?","bareme":[{"critere":"Question 1 : conclusion et propriété des deux perpendiculaires","points":7},{"critere":"Question 2 : conclusion et propriété parallèles-perpendiculaire","points":7},{"critere":"Question 3 : unicité de la parallèle et de la perpendiculaire","points":3},{"critere":"Rédaction et notations (⊥, //)","points":3}],"dureeMin":10,"corrige":"**1.** On sait que (d1) ⊥ (d3) et (d2) ⊥ (d3).\nPropriété : si deux droites sont perpendiculaires à une même droite, alors elles sont parallèles entre elles.\nDonc **(d1) // (d2)**.\n\n**2.** On sait que (d1) // (d2) et (d4) ⊥ (d1).\nPropriété : si deux droites sont parallèles et qu’une troisième est perpendiculaire à l’une, alors elle est perpendiculaire à l’autre.\nDonc **(d4) ⊥ (d2)**.\n\n**3.** Par un point donné passe **une seule** parallèle à une droite donnée : il y a donc **une seule** parallèle à (d3) passant par M. De même, il passe **une seule** perpendiculaire à (d3) par M."}$exo$::jsonb),
  ('82cc1a20-c0cf-526a-b188-84ec864c6402'::uuid, 3, 'probleme', $exo${"titre":"Médiatrice, bissectrice et droites perpendiculaires","consigne":"Résous le problème en justifiant chaque réponse avec une définition ou une propriété du cours.","enonce":"Le segment [AB] mesure 8 cm. Le point I est le milieu de [AB]. La droite (d) est la médiatrice de [AB].\n\n1. Calcule la longueur AI. Quel angle la droite (d) forme-t-elle avec la droite (AB) ?\n2. Le point M est sur (d) et MA = 5 cm. Quelle est la longueur MB ? Justifie.\n3. La droite (Δ) passe par B et est perpendiculaire à (AB). Quelle est la position des droites (d) et (Δ) l’une par rapport à l’autre ? Justifie avec une propriété.\n4. L’angle xOy mesure 70°. La demi-droite [Oz) est sa bissectrice. Calcule la mesure de l’angle xOz. Justifie.\n5. Décris, en étapes numérotées, comment construire la médiatrice de [AB] avec une règle et un compas.","bareme":[{"critere":"Calcul de AI et angle droit entre (d) et (AB)","points":4},{"critere":"Longueur MB justifiée par la propriété de la médiatrice","points":4},{"critere":"Position de (d) et (Δ) justifiée par une propriété","points":5},{"critere":"Mesure de l’angle xOz avec la définition de la bissectrice","points":3},{"critere":"Étapes de la construction au compas","points":4}],"dureeMin":18,"corrige":"**1.** I est le milieu de [AB], donc AI = 8 ÷ 2 = **4 cm**. La médiatrice est perpendiculaire au segment : (d) forme un **angle droit (90°)** avec (AB).\n\n**2.** Les points de la médiatrice d’un segment sont à égale distance de ses deux extrémités. M est sur (d), médiatrice de [AB], donc MB = MA = **5 cm**.\n\n**3.** On sait que (d) ⊥ (AB) et (Δ) ⊥ (AB).\nPropriété : deux droites perpendiculaires à une même droite sont parallèles entre elles.\nDonc **(d) // (Δ)**.\n\n**4.** La bissectrice partage l’angle en deux angles égaux, donc xOz = 70 ÷ 2 = **35°**.\n\n**5.** Construction :\n1. Pointer le compas sur A, avec un écartement plus grand que la moitié de AB (par exemple 5 cm), et tracer un arc de chaque côté de [AB].\n2. Sans changer l’écartement, pointer le compas sur B et tracer deux arcs qui coupent les premiers.\n3. On obtient deux points d’intersection, un de chaque côté de [AB].\n4. Tracer à la règle la droite qui passe par ces deux points : c’est la médiatrice de [AB]."}$exo$::jsonb),
  ('c6dddd25-5a8c-580b-be68-1e7aeaa3c2a6'::uuid, 1, 'probleme', $exo${"titre":"Nommer et classer des angles","consigne":"Donne la nature de chaque angle et réponds aux questions sur la notation.","enonce":"1. Donne la nature (nul, aigu, droit, obtus ou plat) de chacun des angles suivants :\n   - a. 35°\n   - b. 90°\n   - c. 145°\n   - d. 180°\n   - e. 0°\n   - f. 89°\n2. Quel est le sommet de l’angle RST ? Et celui de l’angle TRS ? Explique comment tu le sais.","bareme":[{"critere":"Nature des six angles","points":14},{"critere":"Sommet des angles et explication de la notation","points":6}],"dureeMin":6,"corrige":"**1.**\n- a. 35° est entre 0° et 90° : angle **aigu**.\n- b. 90° : angle **droit**.\n- c. 145° est entre 90° et 180° : angle **obtus**.\n- d. 180° : angle **plat**.\n- e. 0° : angle **nul**.\n- f. 89° est entre 0° et 90° : angle **aigu** (il n’est pas droit, il lui manque 1°).\n\n**2.** Dans la notation d’un angle à trois lettres, le sommet est la **lettre du milieu**.\n- L’angle RST a pour sommet **S**.\n- L’angle TRS a pour sommet **R**."}$exo$::jsonb),
  ('c6dddd25-5a8c-580b-be68-1e7aeaa3c2a6'::uuid, 2, 'probleme', $exo${"titre":"Angles complémentaires, supplémentaires et rapporteur","consigne":"Calcule les angles demandés en écrivant tes calculs, puis explique l’erreur de lecture du rapporteur.","enonce":"1. Un angle mesure 34°. Calcule la mesure de l’angle qui lui est **complémentaire**.\n2. Un angle mesure 115°. Calcule la mesure de l’angle qui lui est **supplémentaire**.\n3. Deux droites se coupent en O. L’un des angles formés mesure 48°. Quelle est la mesure de l’angle qui lui est **opposé par le sommet** ? Justifie.\n4. Léa mesure un angle qui est visiblement aigu. Elle lit 130° sur son rapporteur.\n   a. Explique pourquoi sa mesure est forcément fausse.\n   b. Quelle erreur a-t-elle faite ? Quelle est la vraie mesure de l’angle ?","bareme":[{"critere":"Calcul de l’angle complémentaire","points":5},{"critere":"Calcul de l’angle supplémentaire","points":5},{"critere":"Angle opposé par le sommet justifié","points":4},{"critere":"Analyse de l’erreur de lecture et vraie mesure","points":6}],"dureeMin":10,"corrige":"**1.** Deux angles complémentaires ont une somme de 90°.\n90 − 34 = **56°**.\n\n**2.** Deux angles supplémentaires ont une somme de 180°.\n180 − 115 = **65°**.\n\n**3.** Deux angles opposés par le sommet sont égaux : l’angle opposé mesure **48°**.\n\n**4.**\n- a. Un angle aigu mesure moins de 90°. Or 130° est plus grand que 90° : c’est la mesure d’un angle obtus. La mesure est donc fausse.\n- b. Le rapporteur a deux graduations, complémentaires à 180°. Léa a lu **la mauvaise échelle** (celle qui ne part pas de zéro sur le côté où elle a aligné le rapporteur). La vraie mesure est 180 − 130 = **50°**."}$exo$::jsonb),
  ('c6dddd25-5a8c-580b-be68-1e7aeaa3c2a6'::uuid, 3, 'probleme', $exo${"titre":"Des angles autour d’une droite","consigne":"Résous le problème en rédigeant chaque calcul et en justifiant avec le vocabulaire du cours.","enonce":"Les points A, O et B sont alignés dans cet ordre. Du même côté de la droite (AB), on trace deux demi-droites [OC) et [OD). En tournant de [OA) vers [OB), on rencontre d’abord [OC), puis [OD).\n\nOn sait que :\n- l’angle AOC mesure 40° ;\n- l’angle COD mesure 90°.\n\n1. Quelle est la nature et la mesure de l’angle AOB ? Justifie.\n2. Calcule la mesure de l’angle DOB.\n3. Calcule la mesure de l’angle AOD et donne sa nature.\n4. Les angles AOC et DOB sont-ils complémentaires ? Justifie.\n5. Les angles AOC et COD sont-ils adjacents ? Justifie en citant les trois conditions.","bareme":[{"critere":"Angle plat AOB justifié","points":3},{"critere":"Calcul de l’angle DOB","points":5},{"critere":"Calcul et nature de l’angle AOD","points":4},{"critere":"Angles complémentaires justifiés","points":4},{"critere":"Angles adjacents justifiés par les trois conditions","points":4}],"dureeMin":16,"corrige":"**1.** A, O et B sont alignés et O est entre A et B : [OA) et [OB) sont deux demi-droites opposées. L’angle AOB est un angle **plat**, il mesure **180°**.\n\n**2.** Les angles AOC, COD et DOB se suivent et forment ensemble l’angle plat AOB :\nAOC + COD + DOB = 180°\n40 + 90 + DOB = 180\nDOB = 180 − 40 − 90 = **50°**.\n\n**3.** AOD = AOC + COD = 40 + 90 = **130°**. Comme 130° est entre 90° et 180°, l’angle AOD est **obtus**.\n(Vérification : AOD + DOB = 130 + 50 = 180°.)\n\n**4.** AOC + DOB = 40 + 50 = 90°. Leur somme vaut 90°, donc **oui**, ils sont complémentaires.\n\n**5.** **Oui**, ils sont adjacents :\n- ils ont le **même sommet** O ;\n- ils ont un **côté commun**, [OC) ;\n- ils sont **de part et d’autre** de ce côté commun ([OA) d’un côté, [OD) de l’autre)."}$exo$::jsonb),
  ('8554a91c-649a-50a6-980c-bde0b6b95732'::uuid, 1, 'probleme', $exo${"titre":"Le troisième angle d’un triangle","consigne":"Calcule les angles demandés en écrivant la propriété utilisée, puis réponds à la dernière question par une phrase.","enonce":"1. Dans le triangle ABC, l’angle A mesure 50° et l’angle B mesure 60°. Calcule la mesure de l’angle C.\n2. Le triangle EFG est rectangle en E. L’angle F mesure 35°. Calcule la mesure de l’angle G.\n3. Un triangle peut-il avoir deux angles obtus ? Explique pourquoi.","bareme":[{"critere":"Calcul de l’angle C avec la somme des angles","points":7},{"critere":"Calcul de l’angle G dans le triangle rectangle","points":7},{"critere":"Justification pour les deux angles obtus","points":6}],"dureeMin":7,"corrige":"**1.** Dans un triangle, la somme des trois angles vaut 180°.\nC = 180 − 50 − 60 = **70°**.\n\n**2.** Le triangle est rectangle en E, donc l’angle E mesure 90°.\nG = 180 − 90 − 35 = **55°**.\n(Autre méthode : les deux angles aigus d’un triangle rectangle sont complémentaires : 90 − 35 = 55°.)\n\n**3.** **Non.** Un angle obtus mesure plus de 90°. Deux angles obtus mesureraient ensemble plus de 180°, alors que la somme des trois angles d’un triangle vaut exactement 180°. C’est impossible."}$exo$::jsonb),
  ('8554a91c-649a-50a6-980c-bde0b6b95732'::uuid, 2, 'probleme', $exo${"titre":"Le cadre triangulaire du jardinier","consigne":"Aide le jardinier en vérifiant les longueurs, en décrivant la construction et en calculant l’angle manquant. Rédige chaque étape.","enonce":"Un jardinier veut fabriquer des cadres triangulaires avec des baguettes de bois. Il a préparé deux lots de trois baguettes :\n\n| Lot | Longueurs des baguettes |\n| Lot 1 | 5 dm, 6 dm, 10 dm |\n| Lot 2 | 4 dm, 7 dm, 12 dm |\n\n1. Pour chaque lot, dis si le jardinier peut fabriquer un triangle. Justifie par un calcul.\n2. Pour le lot qui convient, il veut d’abord faire un plan à l’échelle, avec des côtés de 5 cm, 6 cm et 10 cm. Décris en étapes comment construire ce triangle avec la règle et le compas.\n3. Sur un autre cadre, il mesure deux angles : 48° et 67°. Calcule la mesure du troisième angle.","bareme":[{"critere":"Vérification de l’inégalité triangulaire pour les deux lots","points":7},{"critere":"Étapes de la construction à la règle et au compas","points":5},{"critere":"Calcul du troisième angle","points":5},{"critere":"Rédaction et unités","points":3}],"dureeMin":11,"corrige":"**1.** Un triangle existe si le plus grand côté est plus petit que la somme des deux autres.\n- Lot 1 : 5 + 6 = 11 et 10 < 11. Le triangle est **possible**.\n- Lot 2 : 4 + 7 = 11 et 12 > 11. Le triangle est **impossible** : les deux petites baguettes ne se rejoignent pas.\n\n**2.** Construction (triangle ABC avec AB = 10 cm, AC = 5 cm, BC = 6 cm) :\n1. Tracer à la règle le plus grand côté [AB] de 10 cm.\n2. Pointer le compas sur A avec un écartement de 5 cm et tracer un arc de cercle.\n3. Pointer le compas sur B avec un écartement de 6 cm et tracer un arc qui coupe le premier.\n4. Le point d’intersection des deux arcs est le sommet C. Tracer [AC] et [BC].\n\n**3.** La somme des angles d’un triangle vaut 180°.\n180 − 48 − 67 = **65°**."}$exo$::jsonb),
  ('8554a91c-649a-50a6-980c-bde0b6b95732'::uuid, 3, 'probleme', $exo${"titre":"Triangles possibles ou impossibles","consigne":"Réponds à chaque question en justifiant avec la somme des angles ou l’inégalité triangulaire.","enonce":"1. Dans le triangle ABC, l’angle A mesure 38° et l’angle B mesure 52°. Calcule la mesure de l’angle C. Que peux-tu en déduire sur la nature du triangle ABC ?\n2. Montre que, dans ce triangle, les angles A et B sont complémentaires.\n3. Tom affirme qu’il a construit un triangle dont deux angles mesurent 100° et 90°. Explique pourquoi c’est impossible.\n4. On veut construire le triangle DEF tel que DE = 7 cm, EF = 4 cm et l’angle DEF mesure 60°. Que connaît-on sur ce triangle ? Décris la construction en étapes en nommant les instruments.\n5. Peut-on construire un triangle dont les côtés mesurent 7 cm, 4 cm et 2 cm ? Justifie.","bareme":[{"critere":"Calcul de l’angle C et nature du triangle","points":4},{"critere":"Angles A et B complémentaires","points":4},{"critere":"Impossibilité des angles 100° et 90°","points":4},{"critere":"Construction avec deux côtés et l’angle entre eux","points":4},{"critere":"Inégalité triangulaire appliquée","points":4}],"dureeMin":18,"corrige":"**1.** La somme des angles d’un triangle vaut 180°.\nC = 180 − 38 − 52 = **90°**. L’angle C est droit : le triangle ABC est **rectangle en C**.\n\n**2.** A + B = 38 + 52 = **90°**. Leur somme vaut 90° : ils sont complémentaires. C’est normal : dans un triangle rectangle, les deux angles aigus sont complémentaires.\n\n**3.** 100 + 90 = 190°, ce qui dépasse déjà 180°, alors que la somme des trois angles doit valoir 180°. De plus, un triangle a au plus un angle droit et au plus un angle obtus, et un angle obtus et un angle droit ensemble dépassent 180°. C’est **impossible**.\n\n**4.** On connaît **deux côtés et l’angle compris entre eux** (l’angle en E).\n1. À la règle, tracer [ED] de 7 cm.\n2. Avec le rapporteur, centre sur E et zéro sur [ED), marquer 60° et tracer la demi-droite d’origine E.\n3. À la règle, placer F sur cette demi-droite à 4 cm de E.\n4. Tracer [DF].\n\n**5.** Le plus grand côté mesure 7 cm. 4 + 2 = 6 et 7 > 6. Le plus grand côté n’est pas plus petit que la somme des deux autres : le triangle est **impossible**."}$exo$::jsonb),
  ('d0d7aa65-e861-5b41-8631-1414f4237d2c'::uuid, 1, 'probleme', $exo${"titre":"Les angles des triangles particuliers","consigne":"Calcule les angles demandés en écrivant la propriété utilisée.","enonce":"1. Le triangle ABC est isocèle en A. L’angle au sommet A mesure 50°. Calcule la mesure des angles à la base B et C.\n2. Le triangle DEF est équilatéral. Donne la mesure de chacun de ses angles et justifie.\n3. Le triangle GHK est isocèle et rectangle en G. Donne la mesure de ses trois angles.","bareme":[{"critere":"Angles à la base du triangle isocèle","points":8},{"critere":"Angles du triangle équilatéral justifiés","points":6},{"critere":"Angles du triangle isocèle rectangle","points":6}],"dureeMin":6,"corrige":"**1.** Dans un triangle isocèle, les angles à la base sont égaux. La somme des angles vaut 180°.\n(180 − 50) ÷ 2 = 130 ÷ 2 = **65°**. Donc B = C = 65°.\n\n**2.** Un triangle équilatéral a trois angles égaux. 180 ÷ 3 = **60°**. Chaque angle mesure 60°.\n\n**3.** L’angle G est droit : **G = 90°**. Le triangle est isocèle en G, donc H et K sont égaux : (180 − 90) ÷ 2 = **45°**. Les angles mesurent **90°, 45° et 45°**."}$exo$::jsonb),
  ('d0d7aa65-e861-5b41-8631-1414f4237d2c'::uuid, 2, 'probleme', $exo${"titre":"La charpente isocèle","consigne":"Utilise les propriétés du triangle isocèle pour répondre. Justifie chaque réponse.","enonce":"La charpente d’un abri de jardin a la forme d’un triangle ABC **isocèle en A**. On sait que :\n- AB = 4 m ;\n- l’angle ABC mesure 35°.\n\n1. Quelle est la longueur AC ? Justifie.\n2. Quelle est la mesure de l’angle ACB ? Justifie.\n3. Calcule la mesure de l’angle BAC. Quelle est sa nature ?\n4. Combien ce triangle a-t-il d’axes de symétrie ? Quelle droite est cet axe ?","bareme":[{"critere":"Longueur AC justifiée","points":5},{"critere":"Angle ACB justifié par la propriété des angles à la base","points":5},{"critere":"Calcul et nature de l’angle BAC","points":5},{"critere":"Axe de symétrie du triangle isocèle","points":5}],"dureeMin":10,"corrige":"**1.** Le triangle est isocèle en A, donc les deux côtés issus de A sont égaux : AC = AB = **4 m**.\n\n**2.** Dans un triangle isocèle, les angles à la base sont égaux. La base est [BC], donc ACB = ABC = **35°**.\n\n**3.** La somme des angles d’un triangle vaut 180°.\nBAC = 180 − 35 − 35 = 180 − 70 = **110°**. Comme 110° est entre 90° et 180°, l’angle BAC est **obtus**.\n\n**4.** Un triangle isocèle (non équilatéral) a **un seul** axe de symétrie : la **médiatrice de sa base [BC]**. Elle passe par le sommet principal A."}$exo$::jsonb),
  ('d0d7aa65-e861-5b41-8631-1414f4237d2c'::uuid, 3, 'probleme', $exo${"titre":"Un triangle équilatéral et un isocèle rectangle accolés","consigne":"Résous le problème en utilisant uniquement les données et le codage décrits. Justifie chaque étape.","enonce":"On décrit une figure (on ne mesure rien, on lit les données) :\n- ABC est un triangle **équilatéral** de côté 6 cm ;\n- ACD est un triangle **isocèle rectangle en C** ;\n- les points B et D sont de part et d’autre de la droite (AC).\n\n1. Calcule la longueur CD. Justifie.\n2. Donne la mesure des trois angles du triangle ACD.\n3. Calcule la mesure de l’angle BCD.\n4. Quelle est la nature du triangle BCD ? Calcule la mesure de ses angles CBD et CDB.\n5. Quel est le nom du côté [AD] dans le triangle ACD ? Sa longueur est-elle plus grande ou plus petite que 6 cm ? Justifie.","bareme":[{"critere":"Longueur CD justifiée","points":3},{"critere":"Angles du triangle isocèle rectangle","points":4},{"critere":"Calcul de l’angle BCD","points":4},{"critere":"Nature du triangle BCD et angles à la base","points":5},{"critere":"Hypoténuse et comparaison des longueurs","points":4}],"dureeMin":20,"corrige":"**1.** ABC est équilatéral, donc AC = AB = 6 cm. ACD est isocèle en C, donc CD = CA = **6 cm**.\n\n**2.** L’angle ACD est droit : **90°**. Le triangle est isocèle en C, ses angles à la base sont égaux : (180 − 90) ÷ 2 = **45°**. Donc CAD = CDA = 45°.\n\n**3.** Dans le triangle équilatéral, BCA = 60°. B et D sont de part et d’autre de (AC), donc les angles BCA et ACD sont adjacents :\nBCD = 60 + 90 = **150°**.\n\n**4.** CB = 6 cm (côté du triangle équilatéral) et CD = 6 cm : le triangle BCD est **isocèle en C**. Ses angles à la base sont égaux :\n(180 − 150) ÷ 2 = 30 ÷ 2 = **15°**. Donc CBD = CDB = 15°.\n\n**5.** [AD] est le côté opposé à l’angle droit : c’est l’**hypoténuse** du triangle ACD. L’hypoténuse est toujours le plus long côté d’un triangle rectangle, donc AD est **plus grand que 6 cm** (plus grand que AC et CD)."}$exo$::jsonb),
  ('d2dcb9fb-0efd-5322-a419-5991a19683f8'::uuid, 1, 'probleme', $exo${"titre":"Axes de symétrie et symétrique d’un point","consigne":"Réponds à chaque question avec des phrases complètes.","enonce":"1. Donne le nombre d’axes de symétrie de chacune de ces figures :\n   a. un carré ;\n   b. un rectangle (non carré) ;\n   c. un cercle ;\n   d. un parallélogramme quelconque ;\n   e. un triangle équilatéral.\n2. Le point P est situé **sur** l’axe (d). Où se trouve son symétrique par rapport à (d) ?\n3. Le point A n’est pas sur l’axe (d). Décris en deux étapes comment construire son symétrique A’ par rapport à (d).","bareme":[{"critere":"Nombre d’axes des cinq figures","points":8},{"critere":"Symétrique d’un point de l’axe","points":4},{"critere":"Étapes de construction du symétrique","points":8}],"dureeMin":7,"corrige":"**1.**\n- a. Le carré : **4** axes.\n- b. Le rectangle : **2** axes.\n- c. Le cercle : une **infinité** d’axes (tous ses diamètres).\n- d. Le parallélogramme quelconque : **aucun** axe.\n- e. Le triangle équilatéral : **3** axes.\n\n**2.** Un point situé sur l’axe est son propre symétrique : le symétrique de P est **P lui-même**.\n\n**3.**\n1. Tracer, avec l’équerre, la droite **perpendiculaire** à (d) passant par A. Elle coupe (d) en un point H.\n2. Sur cette perpendiculaire, de l’autre côté de (d), **reporter la même distance** (au compas ou à la règle) : placer A’ tel que HA’ = HA.\nAlors (d) est la médiatrice de [AA’]."}$exo$::jsonb),
  ('d2dcb9fb-0efd-5322-a419-5991a19683f8'::uuid, 2, 'probleme', $exo${"titre":"Le triangle et son reflet","consigne":"Utilise les propriétés de conservation de la symétrie axiale. Justifie chaque réponse.","enonce":"Le triangle A’B’C’ est le symétrique du triangle ABC par rapport à la droite (d). On sait que :\n- AB = 5 cm ;\n- BC = 7 cm ;\n- l’angle ABC mesure 40° ;\n- le point B est situé sur la droite (d).\n\n1. Donne les longueurs A’B’ et B’C’. Justifie.\n2. Donne la mesure de l’angle A’B’C’. Justifie.\n3. Où se trouve le point B’ ? Justifie.\n4. M est le milieu de [AC]. On appelle M’ le symétrique de M. Que peux-tu dire du point M’ ? Justifie.","bareme":[{"critere":"Longueurs conservées","points":5},{"critere":"Mesure d’angle conservée","points":5},{"critere":"Position du point B’","points":5},{"critere":"Conservation du milieu","points":5}],"dureeMin":9,"corrige":"**1.** La symétrie axiale conserve les longueurs : A’B’ = AB = **5 cm** et B’C’ = BC = **7 cm**.\n\n**2.** La symétrie axiale conserve les mesures d’angles : A’B’C’ = ABC = **40°**.\n\n**3.** B est sur l’axe (d). Un point de l’axe est son propre symétrique : **B’ = B**, le point ne bouge pas.\n\n**4.** La symétrie axiale conserve le milieu. M est le milieu de [AC], donc son symétrique M’ est le **milieu de [A’C’]**."}$exo$::jsonb),
  ('d2dcb9fb-0efd-5322-a419-5991a19683f8'::uuid, 3, 'probleme', $exo${"titre":"Lettres, miroir et rectangle symétrique","consigne":"Réponds à chaque question en justifiant avec les propriétés de la symétrie axiale.","enonce":"1. Parmi les lettres majuscules **A, F, H, N, T**, lesquelles possèdent au moins un axe de symétrie ? Pour chacune, précise si l’axe est vertical ou horizontal.\n2. Sami affirme : « Un parallélogramme quelconque a deux axes de symétrie, comme le rectangle. » Explique son erreur.\n3. Le point A est à 3 cm de la droite (d). On construit son symétrique A’ par rapport à (d).\n   a. Calcule la longueur AA’.\n   b. Que représente la droite (d) pour le segment [AA’] ? Quelle est la position de (d) par rapport à (AA’) ?\n4. Un rectangle mesure 8 cm sur 5 cm. On construit son symétrique par rapport à une droite. Calcule le périmètre et l’aire du rectangle obtenu. Justifie.\n5. Un mot écrit sur une feuille est vu dans un miroir. Qu’est-ce qui change ? Qu’est-ce qui ne change pas ?","bareme":[{"critere":"Lettres ayant un axe de symétrie","points":4},{"critere":"Analyse de l’erreur sur le parallélogramme","points":4},{"critere":"Longueur AA’ et médiatrice","points":4},{"critere":"Périmètre et aire du rectangle symétrique","points":5},{"critere":"Ce que le miroir change et conserve","points":3}],"dureeMin":17,"corrige":"**1.** **A** a un axe vertical, **H** a un axe vertical et un axe horizontal, **T** a un axe vertical. Les lettres **F** et **N** n’ont aucun axe de symétrie.\n\n**2.** Sami se trompe : un parallélogramme quelconque n’a **aucun** axe de symétrie. Si on le plie, les deux moitiés ne se superposent pas. Il possède un **centre** de symétrie, ce qui n’est pas la même chose qu’un axe. Seuls certains parallélogrammes particuliers (rectangle, losange, carré) ont des axes.\n\n**3.**\n- a. A’ est de l’autre côté de (d), à la même distance : AA’ = 3 + 3 = **6 cm**.\n- b. (d) est la **médiatrice** de [AA’] : elle est **perpendiculaire** à (AA’) et passe par le milieu de [AA’].\n\n**4.** La symétrie conserve les longueurs et les aires : le rectangle obtenu mesure aussi 8 cm sur 5 cm.\n- Périmètre : 2 × (8 + 5) = 2 × 13 = **26 cm**.\n- Aire : 8 × 5 = **40 cm²**.\n\n**5.** Le **sens** est inversé : le mot se lit à l’envers. Les longueurs, les angles, la taille et la forme des lettres ne changent pas."}$exo$::jsonb),
  ('2b15c01d-221b-51a1-98ae-d8a3447287e5'::uuid, 1, 'probleme', $exo${"titre":"Faces, arêtes et volume du cube","consigne":"Réponds aux questions et écris tes calculs avec les unités.","enonce":"1. Recopie et complète :\n\n| Solide | Nombre de faces | Nombre d’arêtes | Nombre de sommets |\n| Cube | … | … | … |\n| Pavé droit | … | … | … |\n\n2. Calcule le volume d’un cube de 4 cm de côté.\n3. Complète : 1 L = … dm³ et 1 mL = … cm³.","bareme":[{"critere":"Tableau des faces, arêtes et sommets","points":6},{"critere":"Calcul du volume du cube","points":8},{"critere":"Équivalences litres et unités de volume","points":6}],"dureeMin":6,"corrige":"**1.**\n\n| Solide | Faces | Arêtes | Sommets |\n| Cube | 6 (carrés) | 12 | 8 |\n| Pavé droit | 6 (rectangles) | 12 | 8 |\n\n**2.** V = c × c × c = 4 × 4 × 4 = **64 cm³**.\n\n**3.** 1 L = **1** dm³ et 1 mL = **1** cm³."}$exo$::jsonb),
  ('2b15c01d-221b-51a1-98ae-d8a3447287e5'::uuid, 2, 'probleme', $exo${"titre":"Remplir l’aquarium","consigne":"Résous le problème en rédigeant chaque calcul, avec les unités.","enonce":"Un aquarium a la forme d’un pavé droit. Ses dimensions intérieures sont :\n- longueur : 60 cm ;\n- largeur : 30 cm ;\n- hauteur : 40 cm.\n\n1. Calcule le volume de l’aquarium en cm³.\n2. Convertis ce volume en dm³.\n3. Combien de litres d’eau l’aquarium peut-il contenir lorsqu’il est plein ?\n4. On ne remplit l’aquarium que sur une hauteur de 30 cm. Calcule la quantité d’eau versée, en litres.","bareme":[{"critere":"Calcul du volume du pavé droit","points":5},{"critere":"Conversion en dm³","points":4},{"critere":"Contenance en litres","points":4},{"critere":"Volume d’eau pour 30 cm de hauteur","points":7}],"dureeMin":10,"corrige":"**1.** V = L × l × h = 60 × 30 × 40 = **72 000 cm³**.\n\n**2.** 1 dm³ = 1 000 cm³, donc 72 000 cm³ = 72 000 ÷ 1 000 = **72 dm³**.\n\n**3.** 1 dm³ = 1 L, donc l’aquarium contient **72 L**.\n\n**4.** L’eau forme un pavé droit de 60 cm × 30 cm × 30 cm :\n60 × 30 × 30 = **54 000 cm³** = 54 dm³ = **54 L**."}$exo$::jsonb),
  ('2b15c01d-221b-51a1-98ae-d8a3447287e5'::uuid, 3, 'probleme', $exo${"titre":"Ranger des cubes et comparer une boîte de conserve","consigne":"Résous le problème en justifiant chaque étape et en faisant attention aux unités.","enonce":"Un carton a la forme d’un pavé droit de 40 cm de long, 30 cm de large et 20 cm de haut. On veut le remplir de cubes en bois de 10 cm de côté.\n\n1. Calcule le volume du carton en cm³.\n2. Calcule le volume d’un cube en cm³, puis en dm³. À combien de litres cela correspond-il ?\n3. Combien de cubes peut-on ranger dans le carton ? Justifie de deux façons différentes.\n4. Une boîte de conserve est un cylindre de rayon 5 cm et de hauteur 10 cm. Calcule son volume en prenant π ≈ 3,14. Contient-elle plus ou moins d’un litre ?\n5. Convertis le volume du carton en m³.","bareme":[{"critere":"Volume du carton","points":3},{"critere":"Volume d’un cube et équivalence en litres","points":4},{"critere":"Nombre de cubes justifié de deux façons","points":5},{"critere":"Volume du cylindre et comparaison avec 1 L","points":5},{"critere":"Conversion en m³","points":3}],"dureeMin":18,"corrige":"**1.** V = 40 × 30 × 20 = **24 000 cm³**.\n\n**2.** V = 10 × 10 × 10 = **1 000 cm³** = **1 dm³**, soit **1 L**.\n\n**3.**\n- Méthode 1 : en longueur, 40 ÷ 10 = 4 cubes ; en largeur, 30 ÷ 10 = 3 cubes ; en hauteur, 20 ÷ 10 = 2 couches. 4 × 3 × 2 = **24 cubes**.\n- Méthode 2 : 24 000 ÷ 1 000 = **24 cubes**.\n\n**4.** V = π × r × r × h ≈ 3,14 × 5 × 5 × 10 = 3,14 × 250 = **785 cm³**.\n785 cm³ = 785 mL, et 785 < 1 000 : la boîte contient **moins d’un litre**.\n\n**5.** 1 m³ = 1 000 000 cm³, donc 24 000 cm³ = 24 000 ÷ 1 000 000 = **0,024 m³**."}$exo$::jsonb),
  ('dbac06b5-8662-525d-9cc3-1421e0db2d85'::uuid, 1, 'probleme', $exo${"titre":"Périmètre du carré, du rectangle et du triangle","consigne":"Calcule chaque périmètre en écrivant la formule, le calcul et l’unité.","enonce":"1. Calcule le périmètre d’un carré de 7 cm de côté.\n2. Calcule le périmètre d’un rectangle de 12 cm de longueur et 5 cm de largeur.\n3. Calcule le périmètre d’un triangle dont les côtés mesurent 4 cm, 6 cm et 7 cm.","bareme":[{"critere":"Périmètre du carré","points":7},{"critere":"Périmètre du rectangle","points":7},{"critere":"Périmètre du triangle","points":6}],"dureeMin":5,"corrige":"**1.** P = 4 × c = 4 × 7 = **28 cm**.\n\n**2.** P = 2 × (L + l) = 2 × (12 + 5) = 2 × 17 = **34 cm**.\n\n**3.** P = 4 + 6 + 7 = **17 cm**."}$exo$::jsonb),
  ('dbac06b5-8662-525d-9cc3-1421e0db2d85'::uuid, 2, 'probleme', $exo${"titre":"Clôturer le jardin","consigne":"Résous le problème en rédigeant chaque étape, avec les unités.","enonce":"Un jardin rectangulaire mesure 15 m de long et 8 m de large. Le propriétaire veut l’entourer d’un grillage, sauf à l’endroit du portail, qui mesure 3 m de large.\n\n1. Calcule le périmètre du jardin.\n2. Calcule la longueur de grillage nécessaire.\n3. Le grillage coûte 12 € le mètre. Calcule le prix à payer.","bareme":[{"critere":"Calcul du périmètre du rectangle","points":6},{"critere":"Longueur de grillage sans le portail","points":5},{"critere":"Calcul du prix","points":5},{"critere":"Rédaction et unités","points":4}],"dureeMin":9,"corrige":"**1.** P = 2 × (L + l) = 2 × (15 + 8) = 2 × 23 = **46 m**.\n\n**2.** On retire la largeur du portail : 46 − 3 = **43 m** de grillage.\n\n**3.** 43 × 12 = **516 €**.\n(Détail : 43 × 12 = 43 × 10 + 43 × 2 = 430 + 86 = 516.)"}$exo$::jsonb),
  ('dbac06b5-8662-525d-9cc3-1421e0db2d85'::uuid, 3, 'probleme', $exo${"titre":"Le tour de la piste d’athlétisme","consigne":"Résous le problème en justifiant chaque étape. Prends π ≈ 3,14 et fais attention aux conversions.","enonce":"Une piste d’athlétisme est formée de deux lignes droites de 100 m et de deux demi-cercles. Les deux demi-cercles ont le même diamètre : 60 m.\n\nLe contour de la piste est composé seulement des deux lignes droites et des deux demi-cercles. Sur le plan, on a aussi tracé deux segments de 60 m qui ferment les demi-cercles : ce sont des traits intérieurs.\n\n1. Calcule le rayon des demi-cercles.\n2. Explique pourquoi les deux demi-cercles réunis ont la même longueur qu’un cercle entier, puis calcule cette longueur.\n3. Calcule la longueur d’un tour de piste.\n4. Un coureur fait 5 tours. Calcule la distance parcourue en mètres, puis en kilomètres.\n5. Un élève ajoute les deux segments de 60 m dans le calcul du tour. Explique son erreur.","bareme":[{"critere":"Calcul du rayon","points":3},{"critere":"Longueur des deux demi-cercles","points":5},{"critere":"Longueur d’un tour de piste","points":5},{"critere":"Distance pour 5 tours et conversion en km","points":4},{"critere":"Explication sur les traits intérieurs","points":3}],"dureeMin":17,"corrige":"**1.** d = 2 × r, donc r = 60 ÷ 2 = **30 m**.\n\n**2.** Les deux demi-cercles ont le même diamètre : mis bout à bout, ils forment un cercle entier de rayon 30 m.\nP = 2 × π × r ≈ 2 × 3,14 × 30 = **188,4 m**.\n\n**3.** Tour = 100 + 100 + 188,4 = **388,4 m**.\n\n**4.** 5 × 388,4 = **1 942 m**. 1 km = 1 000 m, donc 1 942 m = **1,942 km**.\n\n**5.** Le périmètre d’une figure composée ne compte que les segments du **contour**. Les deux segments de 60 m sont à l’intérieur de la piste, le coureur ne les parcourt pas : il ne faut pas les ajouter."}$exo$::jsonb),
  ('0399dc65-9d41-56cc-a0c0-e68818658988'::uuid, 1, 'probleme', $exo${"titre":"Aires du rectangle et du triangle, conversion","consigne":"Calcule chaque aire en écrivant la formule, puis effectue la conversion demandée.","enonce":"1. Calcule l’aire d’un rectangle de 9 cm de longueur et 4 cm de largeur.\n2. Un triangle a une base de 10 cm et une hauteur relative à cette base de 6 cm. Calcule son aire.\n3. Convertis 3 m² en cm².","bareme":[{"critere":"Aire du rectangle","points":7},{"critere":"Aire du triangle","points":7},{"critere":"Conversion d’aire","points":6}],"dureeMin":6,"corrige":"**1.** A = L × l = 9 × 4 = **36 cm²**.\n\n**2.** A = (base × hauteur) ÷ 2 = (10 × 6) ÷ 2 = 60 ÷ 2 = **30 cm²**.\n\n**3.** 1 m² = 10 000 cm², donc 3 m² = 3 × 10 000 = **30 000 cm²**."}$exo$::jsonb),
  ('0399dc65-9d41-56cc-a0c0-e68818658988'::uuid, 2, 'probleme', $exo${"titre":"Semer un champ","consigne":"Résous le problème en rédigeant chaque étape, avec les unités.","enonce":"Un agriculteur possède un champ rectangulaire de 250 m de long et 120 m de large.\n\n1. Calcule l’aire du champ en m².\n2. Convertis cette aire en ares, puis en hectares.\n3. Un sac de graines permet de semer 50 ares. Combien de sacs faut-il pour semer tout le champ ?","bareme":[{"critere":"Aire du champ","points":6},{"critere":"Conversion en ares et en hectares","points":6},{"critere":"Nombre de sacs","points":5},{"critere":"Rédaction et unités","points":3}],"dureeMin":9,"corrige":"**1.** A = 250 × 120 = **30 000 m²**.\n\n**2.** 1 a = 100 m², donc 30 000 m² = 30 000 ÷ 100 = **300 a**.\n1 ha = 10 000 m², donc 30 000 m² = **3 ha** (c’est aussi 300 ÷ 100).\n\n**3.** 300 ÷ 50 = **6 sacs**."}$exo$::jsonb),
  ('0399dc65-9d41-56cc-a0c0-e68818658988'::uuid, 3, 'probleme', $exo${"titre":"Le jardin avec son bassin","consigne":"Découpe la figure en formes connues, calcule chaque aire et rédige ta démarche. Prends π ≈ 3,14.","enonce":"Un jardin est formé :\n- d’un rectangle de 12 m de long et 8 m de large ;\n- d’un triangle posé sur la longueur du rectangle : sa base est ce côté de 12 m, sa hauteur relative à cette base mesure 5 m, et ses deux côtés obliques mesurent environ 7,8 m chacun.\n\nDans le rectangle, on a creusé un bassin circulaire de 1 m de rayon, qui ne sera pas gazonné.\n\n1. Calcule l’aire du rectangle.\n2. Calcule l’aire du triangle.\n3. Calcule l’aire du bassin.\n4. Calcule l’aire de la partie gazonnée du jardin.\n5. Zoé a calculé l’aire du triangle ainsi : (12 × 7,8) ÷ 2. Explique son erreur.","bareme":[{"critere":"Aire du rectangle","points":3},{"critere":"Aire du triangle avec la hauteur","points":4},{"critere":"Aire du disque","points":4},{"critere":"Aire gazonnée : somme et soustraction du bassin","points":4},{"critere":"Analyse de l’erreur sur la hauteur","points":5}],"dureeMin":18,"corrige":"**1.** A = 12 × 8 = **96 m²**.\n\n**2.** A = (base × hauteur) ÷ 2 = (12 × 5) ÷ 2 = 60 ÷ 2 = **30 m²**.\n\n**3.** A = π × r × r ≈ 3,14 × 1 × 1 = **3,14 m²**.\n\n**4.** On additionne le rectangle et le triangle, puis on soustrait le bassin :\n96 + 30 − 3,14 = 126 − 3,14 = **122,86 m²**.\n\n**5.** Zoé a pris un **côté oblique** (7,8 m) au lieu de la **hauteur**. La hauteur est le segment perpendiculaire à la base, mené du sommet opposé : ici elle mesure 5 m. Un côté oblique n’est pas perpendiculaire à la base, ce n’est donc pas la hauteur. Le bon calcul est (12 × 5) ÷ 2 = 30 m²."}$exo$::jsonb),
  ('4d26d6b1-b65f-5c4a-86c8-4621f7358b26'::uuid, 1, 'probleme', $exo${"titre":"Convertir des durées","consigne":"Effectue chaque conversion en écrivant ton calcul.","enonce":"1. Convertis 3 h en minutes.\n2. Convertis 1 h 45 min en minutes.\n3. Écris 2,5 h en heures et minutes.\n4. Convertis 240 s en minutes.","bareme":[{"critere":"Conversions d’heures en minutes","points":7},{"critere":"Conversion d’une durée décimale","points":7},{"critere":"Conversion de secondes en minutes","points":6}],"dureeMin":5,"corrige":"**1.** 1 h = 60 min, donc 3 h = 3 × 60 = **180 min**.\n\n**2.** 1 h = 60 min, donc 1 h 45 min = 60 + 45 = **105 min**.\n\n**3.** 2,5 h = 2 h + 0,5 h et 0,5 × 60 = 30 min. Donc 2,5 h = **2 h 30 min** (et non 2 h 5 min).\n\n**4.** 1 min = 60 s, donc 240 s = 240 ÷ 60 = **4 min**."}$exo$::jsonb),
  ('4d26d6b1-b65f-5c4a-86c8-4621f7358b26'::uuid, 2, 'probleme', $exo${"titre":"Une soirée au cinéma","consigne":"Résous le problème en détaillant chaque calcul d’horaire ou de durée.","enonce":"Inès va au cinéma.\n- Elle part de chez elle à **20 h 10** et arrive au cinéma à **20 h 32**.\n- Le film commence à **20 h 45** et dure **1 h 50 min**.\n- Pour rentrer, elle met le même temps qu’à l’aller et part dès la fin du film.\n\n1. Calcule la durée du trajet aller.\n2. À quelle heure le film se termine-t-il ?\n3. À quelle heure Inès sera-t-elle rentrée chez elle ?","bareme":[{"critere":"Durée du trajet aller","points":5},{"critere":"Heure de fin du film","points":6},{"critere":"Heure de retour à la maison","points":5},{"critere":"Rédaction des calculs en base 60","points":4}],"dureeMin":10,"corrige":"**1.** De 20 h 10 à 20 h 32 : 32 − 10 = **22 min**.\n\n**2.** 20 h 45 + 1 h 50 min :\n- 20 h 45 + 1 h = 21 h 45 ;\n- 21 h 45 + 50 min = 21 h 95 min ;\n- 95 min = 60 min + 35 min, donc 21 h 95 min = **22 h 35**.\n\n**3.** 22 h 35 + 22 min = 22 h 57 min. Inès est rentrée à **22 h 57**."}$exo$::jsonb),
  ('4d26d6b1-b65f-5c4a-86c8-4621f7358b26'::uuid, 3, 'probleme', $exo${"titre":"Le train Paris–Lyon","consigne":"Résous le problème en justifiant chaque étape. Fais attention à la concordance des unités.","enonce":"Un train part de Paris à **7 h 48** et arrive à Lyon à **9 h 45**. Il parcourt **390 km**.\n\n1. Calcule la durée du trajet en heures et minutes.\n2. Écris cette durée en heures, sous forme d’un nombre décimal.\n3. Calcule la vitesse moyenne du train en km/h.\n4. Une voiture roule à 90 km/h pendant 2 h 30 min. Calcule la distance parcourue.\n5. Noé a écrit : « 1,95 h = 1 h 95 min ». Explique son erreur.","bareme":[{"critere":"Durée du trajet entre deux horaires","points":4},{"critere":"Conversion en heures décimales","points":4},{"critere":"Calcul de la vitesse moyenne","points":5},{"critere":"Calcul de la distance de la voiture","points":4},{"critere":"Analyse de l’erreur de conversion","points":3}],"dureeMin":18,"corrige":"**1.** On avance par étapes rondes :\n- 7 h 48 → 8 h : 12 min ;\n- 8 h → 9 h : 1 h ;\n- 9 h → 9 h 45 : 45 min.\nTotal : 1 h + 12 min + 45 min = **1 h 57 min**.\n\n**2.** 57 min = 57 ÷ 60 h = 0,95 h. Donc la durée est **1,95 h**.\n\n**3.** v = d ÷ t = 390 ÷ 1,95 = **200 km/h**.\n(Vérification : 200 × 1,95 = 390.)\n\n**4.** 2 h 30 min = 2,5 h (car 30 min = 0,5 h).\nd = v × t = 90 × 2,5 = **225 km**.\n\n**5.** Le temps se compte en base 60 : la partie décimale ne donne pas directement des minutes, il faut la convertir. 0,95 h = 0,95 × 60 = 57 min. Donc 1,95 h = **1 h 57 min**. D’ailleurs, 95 min est plus qu’une heure, ce qui ne peut pas s’écrire après « 1 h »."}$exo$::jsonb),
  ('60cda20a-9d42-520c-8531-4653aa8a1cff'::uuid, 1, 'probleme', $exo${"titre":"Algorithme, instruction et coordonnées","consigne":"Réponds à chaque question avec des phrases complètes.","enonce":"1. Qu’est-ce qu’un algorithme ? Donne un exemple de la vie courante.\n2. Un élève écrit l’instruction « Avance un peu » pour un robot. Explique pourquoi ce n’est pas une bonne instruction et propose une correction.\n3. Un lutin doit « aller à (5 ; 3) ». Quelle est l’abscisse du point ? Quelle est son ordonnée ? Laquelle correspond au déplacement horizontal ?","bareme":[{"critere":"Définition et exemple d’algorithme","points":7},{"critere":"Instruction précise et sans ambiguïté","points":6},{"critere":"Abscisse et ordonnée","points":7}],"dureeMin":6,"corrige":"**1.** Un algorithme est une suite **finie** et **ordonnée** d’instructions qui résout un problème. Exemples : une recette de cuisine, un itinéraire, une notice de montage.\n\n**2.** « Avance un peu » n’est pas **précis** : la machine ne devine pas de combien avancer. Une instruction doit être sans ambiguïté, par exemple : « Avance de 100 pas ».\n\n**3.** Dans le couple (5 ; 3), l’abscisse vient en premier : **l’abscisse est 5**, **l’ordonnée est 3**. L’**abscisse** correspond au repérage horizontal, l’ordonnée au repérage vertical."}$exo$::jsonb),
  ('60cda20a-9d42-520c-8531-4653aa8a1cff'::uuid, 2, 'probleme', $exo${"titre":"Un lutin qui trace des polygones","consigne":"Lis le programme, explique ce qu’il fait, puis modifie-le. Justifie tes réponses.","enonce":"Voici un programme Scratch (le stylo est baissé) :\n\n```\nrépéter 3 fois\n    avancer de 60 pas\n    tourner de 120° à droite\n```\n\n1. Quelle figure le lutin trace-t-il ? Justifie avec la règle sur l’angle de rotation.\n2. Quelle longueur totale, en pas, le lutin parcourt-il ?\n3. Réécris le programme pour qu’il trace un hexagone régulier (6 côtés) de côté 60 pas. Justifie l’angle choisi.\n4. Sans boucle, combien d’instructions faudrait-il écrire pour tracer le triangle ? Donne un avantage de la boucle.","bareme":[{"critere":"Figure tracée et justification de l’angle","points":5},{"critere":"Longueur totale parcourue","points":4},{"critere":"Programme de l’hexagone et angle de 60°","points":6},{"critere":"Comparaison avec et sans boucle","points":5}],"dureeMin":11,"corrige":"**1.** Le lutin répète 3 fois « avancer de 60 » : il trace 3 côtés de même longueur. Pour un polygone à n côtés, on tourne de 360 ÷ n degrés ; ici 360 ÷ 3 = 120°. Le lutin trace un **triangle équilatéral** de côté 60 pas.\n\n**2.** 3 × 60 = **180 pas**.\n\n**3.** 360 ÷ 6 = 60°.\n```\nrépéter 6 fois\n    avancer de 60 pas\n    tourner de 60° à droite\n```\n\n**4.** Sans boucle, il faut écrire 3 fois les 2 instructions : 3 × 2 = **6 instructions** (contre 3 avec la boucle). Avantages de la boucle : le programme est plus court et plus facile à **corriger**, car il n’y a qu’un seul endroit à modifier."}$exo$::jsonb),
  ('60cda20a-9d42-520c-8531-4653aa8a1cff'::uuid, 3, 'probleme', $exo${"titre":"Variable, condition et débogage","consigne":"Exécute le programme à la main, explique son fonctionnement puis corrige le programme fautif. Justifie chaque réponse.","enonce":"**Programme A**\n\n```\nmettre score à 0\nrépéter 5 fois\n    demander un nombre\n    si nombre > 10 alors\n        ajouter 2 à score\n    sinon\n        ajouter 1 à score\ndire score\n```\n\nL’utilisateur donne, dans l’ordre, les nombres : **12, 7, 15, 10, 3**.\n\n1. Exécute le programme A pas à pas et donne la valeur finale de score.\n2. Qu’est-ce qu’une variable ? Quel est le rôle de score ?\n3. Dans le programme A, repère la boucle et l’instruction conditionnelle. Explique le rôle de chacune.\n\n**Programme B** (il devait tracer un carré de côté 50 pas)\n\n```\nrépéter 4 fois\n    avancer de 50 pas\n    tourner de 60° à droite\n```\n\n4. Le lutin ne trace pas un carré. Trouve le bug et corrige-le en justifiant.\n5. Décris la démarche à suivre pour déboguer un programme.","bareme":[{"critere":"Exécution pas à pas et valeur finale du score","points":5},{"critere":"Définition et rôle de la variable","points":3},{"critere":"Rôle de la boucle et de la condition","points":4},{"critere":"Bug trouvé et corrigé avec justification","points":5},{"critere":"Démarche de débogage","points":3}],"dureeMin":18,"corrige":"**1.**\n- Début : score = 0.\n- 12 > 10 : on ajoute 2 → score = 2.\n- 7 n’est pas > 10 : on ajoute 1 → score = 3.\n- 15 > 10 : on ajoute 2 → score = 5.\n- 10 n’est pas > 10 (il est égal) : on ajoute 1 → score = 6.\n- 3 n’est pas > 10 : on ajoute 1 → score = 7.\nLe programme dit **7**.\n\n**2.** Une variable est une case mémoire portant un nom, qui retient une valeur qu’on peut lire et modifier. Ici, score sert de **compteur de points** : il retient le total au fil des réponses.\n\n**3.** La **boucle** « répéter 5 fois » fait recommencer 5 fois la demande et le test sans les réécrire. L’**instruction conditionnelle** « si… alors… sinon… » choisit quoi faire selon la condition : ajouter 2 si le nombre dépasse 10, sinon ajouter 1.\n\n**4.** Le bug est l’angle : pour un polygone à 4 côtés, il faut tourner de 360 ÷ 4 = **90°**, pas 60°. Correction :\n```\nrépéter 4 fois\n    avancer de 50 pas\n    tourner de 90° à droite\n```\n\n**5.** Tester le programme pas à pas, isoler l’instruction fautive, la corriger, puis retester."}$exo$::jsonb),
  ('972a14b2-f06b-557c-82f6-f68521a51e80'::uuid, 1, 'probleme', $exo${"titre":"Le prix des cahiers","consigne":"Complète le tableau en écrivant tes calculs, puis réponds à la question par une phrase.","enonce":"Un cahier coûte 1,50 €. Le prix payé est proportionnel au nombre de cahiers achetés.\n\n| Nombre de cahiers | 1 | 2 | 4 | 10 |\n| Prix (en €) | 1,50 | … | … | … |\n\n1. Complète le tableau.\n2. Quel est le coefficient de proportionnalité ?\n3. À la piscine, on paie un abonnement de 20 € puis 2 € par entrée. Le prix payé est-il proportionnel au nombre d’entrées ? Explique.","bareme":[{"critere":"Tableau de proportionnalité complété","points":10},{"critere":"Coefficient de proportionnalité","points":4},{"critere":"Justification du tarif avec abonnement","points":6}],"dureeMin":6,"corrige":"**1.**\n- 2 cahiers : 2 × 1,50 = **3 €** ;\n- 4 cahiers : 4 × 1,50 = **6 €** ;\n- 10 cahiers : 10 × 1,50 = **15 €**.\n\n**2.** On multiplie le nombre de cahiers par **1,5** : c’est le coefficient de proportionnalité.\n\n**3.** **Non.** Avec 0 entrée, on paie déjà 20 € : le prix ne part pas de 0. De plus, le double ne donne pas le double : 1 entrée coûte 20 + 2 = 22 €, mais 2 entrées coûtent 20 + 4 = 24 €, et non 44 €."}$exo$::jsonb),
  ('972a14b2-f06b-557c-82f6-f68521a51e80'::uuid, 2, 'probleme', $exo${"titre":"Adapter la recette de crêpes","consigne":"Résous le problème en indiquant la méthode utilisée (coefficient, passage à l’unité ou linéarité).","enonce":"Voici une recette de crêpes **pour 4 personnes** :\n- 200 g de farine ;\n- 50 cl de lait.\n\nLes quantités sont proportionnelles au nombre de personnes.\n\n1. Calcule les quantités de farine et de lait pour 12 personnes.\n2. Calcule la quantité de farine pour 1 personne, puis pour 6 personnes.\n3. Calcule la quantité de lait pour 6 personnes.\n4. En utilisant la linéarité et tes résultats précédents, calcule la quantité de farine pour 10 personnes.","bareme":[{"critere":"Quantités pour 12 personnes","points":5},{"critere":"Passage à l’unité pour la farine","points":5},{"critere":"Quantité de lait pour 6 personnes","points":5},{"critere":"Utilisation de la linéarité","points":5}],"dureeMin":11,"corrige":"**1.** 12 = 4 × 3, on multiplie par 3 :\n- farine : 200 × 3 = **600 g** ;\n- lait : 50 × 3 = **150 cl**.\n\n**2.** Pour 1 personne : 200 ÷ 4 = **50 g** de farine.\nPour 6 personnes : 50 × 6 = **300 g**.\n\n**3.** Pour 1 personne : 50 ÷ 4 = 12,5 cl de lait. Pour 6 personnes : 12,5 × 6 = **75 cl**.\n(Autre méthode : 6 = 4 + 2, et 2 personnes, c’est la moitié de 4 : 50 + 25 = 75 cl.)\n\n**4.** 10 = 4 + 6. Farine pour 10 personnes = farine pour 4 + farine pour 6 = 200 + 300 = **500 g**."}$exo$::jsonb),
  ('972a14b2-f06b-557c-82f6-f68521a51e80'::uuid, 3, 'probleme', $exo${"titre":"Carte, soldes et tableaux","consigne":"Résous chaque partie en justifiant tes calculs et tes conclusions.","enonce":"**Partie A – La carte**\nUne carte de randonnée est à l’échelle **1/50 000**.\n1. À quelle distance réelle, en mètres, correspond 1 cm sur la carte ?\n2. Sur la carte, deux refuges sont à 7 cm l’un de l’autre. Calcule la distance réelle en km.\n3. Deux villages sont à 2 km l’un de l’autre. À quelle distance sont-ils sur la carte ?\n\n**Partie B – Les soldes**\n4. Un pull coûte 45 €. Pendant les soldes, il bénéficie d’une réduction de 20 %. Calcule le montant de la réduction, puis le nouveau prix.\n\n**Partie C – Est-ce proportionnel ?**\n5. Ce tableau est-il un tableau de proportionnalité ? Justifie.\n\n| Grandeur A | 3 | 5 | 8 |\n| Grandeur B | 12 | 20 | 30 |","bareme":[{"critere":"Échelle : 1 cm en distance réelle","points":4},{"critere":"Distance réelle entre les refuges","points":4},{"critere":"Distance sur la carte entre les villages","points":4},{"critere":"Calcul de la réduction de 20 %","points":4},{"critere":"Test du tableau de proportionnalité","points":4}],"dureeMin":18,"corrige":"**1.** Au 1/50 000, 1 cm sur la carte représente 50 000 cm en réalité. 50 000 cm = **500 m**.\n\n**2.** 7 × 500 = 3 500 m = **3,5 km**.\n\n**3.** 2 km = 2 000 m. 2 000 ÷ 500 = **4 cm** sur la carte.\n\n**4.** Appliquer 20 %, c’est multiplier par 0,2 : 45 × 0,2 = **9 €** de réduction.\nNouveau prix : 45 − 9 = **36 €**.\n\n**5.** On calcule le quotient de chaque colonne :\n- 12 ÷ 3 = 4 ;\n- 20 ÷ 5 = 4 ;\n- 30 ÷ 8 = 3,75.\nLes quotients ne sont pas tous égaux : ce **n’est pas** un tableau de proportionnalité. (Pour qu’il le soit, il faudrait 8 × 4 = 32 à la place de 30.)"}$exo$::jsonb),
  ('59a20ff1-b14d-5cb2-a8fc-7d4a02e3294f'::uuid, 1, 'probleme', $exo${"titre":"Lire, écrire et comparer des nombres décimaux","consigne":"Réponds à chaque question en rédigeant tes réponses. Justifie la comparaison.","enonce":"On considère le nombre **5 407,382**.\n\n1. Donne :\n   a. le chiffre des dizaines ;\n   b. le chiffre des centièmes ;\n   c. le nombre de dizaines.\n2. Écris le nombre **7,46** :\n   a. sous forme fractionnaire (fraction de dénominateur 100) ;\n   b. sous forme décomposée (partie entière + dixièmes + centièmes).\n3. Compare **8,9** et **8,125**. Explique ta méthode.","bareme":[{"critere":"Utilisation du tableau de numération (chiffre / nombre de)","points":8},{"critere":"Écritures fractionnaire et décomposée","points":6},{"critere":"Comparaison justifiée","points":6}],"dureeMin":7,"corrige":"**1.** Dans 5 407,382 :\n- a. le chiffre des dizaines est **0** ;\n- b. le chiffre des centièmes est **8** ;\n- c. le nombre de dizaines est **540** (on lit tout ce qui est à gauche du chiffre des dizaines, lui compris).\n\n**2.**\n- a. 7,46 = **746/100** ;\n- b. 7,46 = **7 + 4/10 + 6/100**.\n\n**3.** Les parties entières sont égales (8 et 8). On compare les dixièmes : 9 dixièmes contre 1 dixième. Donc **8,9 > 8,125**.\nOn peut compléter par des zéros : 8,900 contre 8,125. Le nombre qui a le plus de chiffres n'est pas forcément le plus grand."}$exo$::jsonb),
  ('59a20ff1-b14d-5cb2-a8fc-7d4a02e3294f'::uuid, 2, 'probleme', $exo${"titre":"Le concours de saut en longueur","consigne":"Lis les résultats du concours et réponds aux questions en justifiant tes réponses.","enonce":"Voici les sauts de cinq élèves (en mètres) :\n\n| Élève | Saut |\n| --- | --- |\n| Léa | 3,45 |\n| Tom | 3,5 |\n| Inès | 3,405 |\n| Hugo | 3,54 |\n| Nora | 3,054 |\n\n1. Range les sauts dans l'ordre **décroissant** et donne le classement des élèves.\n2. Pour le saut de Léa :\n   a. encadre-le entre deux nombres entiers consécutifs ;\n   b. arrondis-le au dixième en expliquant ta démarche.\n3. Inès affirme : « Mon saut est meilleur que celui de Tom, car 3,405 a plus de chiffres que 3,5. » Explique pourquoi elle se trompe.","bareme":[{"critere":"Rangement décroissant et classement","points":7},{"critere":"Encadrement à l'unité et arrondi au dixième","points":7},{"critere":"Explication de l'erreur d'Inès","points":6}],"dureeMin":10,"corrige":"**1.** Toutes les parties entières valent 3. On écrit les nombres avec trois décimales : 3,450 ; 3,500 ; 3,405 ; 3,540 ; 3,054.\nOn compare les dixièmes, puis les centièmes, puis les millièmes :\n**3,54 > 3,5 > 3,45 > 3,405 > 3,054**.\nClassement : 1er Hugo, 2e Tom, 3e Léa, 4e Inès, 5e Nora.\n\n**2.**\n- a. **3 < 3,45 < 4**.\n- b. On regarde le chiffre qui suit les dixièmes : le chiffre des centièmes est 5. Comme il vaut 5 ou plus, on arrondit au supérieur : 3,45 arrondi au dixième est **3,5**.\n\n**3.** On ne compare pas des nombres en comptant leurs chiffres. On compare d'abord les parties entières (3 et 3, égales), puis les dixièmes : Tom a 5 dixièmes, Inès 4 dixièmes. Donc 3,5 > 3,405 : c'est Tom qui a sauté le plus loin. En complétant : 3,500 contre 3,405."}$exo$::jsonb),
  ('59a20ff1-b14d-5cb2-a8fc-7d4a02e3294f'::uuid, 3, 'probleme', $exo${"titre":"Des points sur une demi-droite graduée","consigne":"Réponds à chaque question en justifiant soigneusement. Les réponses se rédigent, aucun tracé n'est demandé.","enonce":"Une demi-droite graduée a pour origine le point O d'abscisse 0. Chaque unité est partagée en **10 parts égales** : une graduation vaut donc un dixième.\n\n1. Le point A est situé **23 graduations** après O, le point B **7 graduations** après O. Donne l'abscisse de A et celle de B.\n2. Le point C a pour abscisse **1,65**. Explique pourquoi C n'est pas sur une graduation et précise entre quelles graduations (quelles abscisses) il se trouve.\n3. Trouve un nombre décimal ayant **deux chiffres après la virgule**, compris entre 2,3 et 2,4, dont l'arrondi au dixième est **2,4**. Justifie.\n4. Samir dit : « 4,20 est plus grand que 4,2. » A-t-il raison ? Justifie.\n5. Le point D a pour abscisse **1,605**. Range les abscisses des points A, B, C et D dans l'ordre **croissant**. Quel point est le plus à droite sur la demi-droite ?","bareme":[{"critere":"Lecture des abscisses de A et B","points":4},{"critere":"Position de C justifiée","points":4},{"critere":"Nombre cherché et règle de l'arrondi","points":4},{"critere":"Égalité de 4,20 et 4,2 justifiée","points":4},{"critere":"Rangement croissant et lien avec la position","points":4}],"dureeMin":15,"corrige":"**1.** Une graduation vaut 0,1. A : 23 dixièmes = **2,3**. B : 7 dixièmes = **0,7**.\n\n**2.** Les graduations tombent sur des nombres à un seul chiffre après la virgule (1,6 ; 1,7…). 1,65 a un chiffre des centièmes non nul, donc C n'est pas sur une graduation. Comme 1,60 < 1,65 < 1,70, C est **entre la graduation 1,6 et la graduation 1,7** (16e et 17e graduations), exactement au milieu.\n\n**3.** Par exemple **2,36** : 2,3 < 2,36 < 2,4, et le chiffre des centièmes (6) vaut 5 ou plus, donc on arrondit au supérieur : 2,4. Réponses acceptées : 2,35 ; 2,36 ; 2,37 ; 2,38 ; 2,39.\n\n**4.** Non. Ajouter un zéro à droite de la partie décimale ne change pas le nombre : **4,20 = 4,2** (2 dixièmes et 0 centième).\n\n**5.** On écrit avec trois décimales : 2,300 ; 0,700 ; 1,650 ; 1,605.\n**0,7 < 1,605 < 1,65 < 2,3**, soit B, D, C, A.\nPlus on va à droite, plus le nombre est grand : **A** est le point le plus à droite."}$exo$::jsonb),
  ('ca4fdd67-bd21-5d3b-bccf-85dc817c718a'::uuid, 1, 'probleme', $exo${"titre":"Poser des additions, soustractions et multiplications","consigne":"Calcule chaque opération en détaillant ta méthode (alignement des virgules, nombre de décimales).","enonce":"1. Calcule **23,6 + 8,75**.\n2. Calcule **15 − 7,48**.\n3. Calcule **4,3 × 2,6** : calcule d'abord sans virgule, puis place la virgule en expliquant.\n4. Calcule :\n   a. **5,82 × 100** ;\n   b. **36,5 ÷ 1 000**.","bareme":[{"critere":"Addition et soustraction avec virgules alignées","points":8},{"critere":"Multiplication et placement de la virgule","points":6},{"critere":"Multiplication et division par 100 et 1 000","points":6}],"dureeMin":8,"corrige":"**1.** On aligne les virgules : 23,60 + 8,75 = **32,35**.\n\n**2.** On complète : 15,00 − 7,48 = **7,52**. Vérification : 7,52 + 7,48 = 15.\n\n**3.** 43 × 26 = 1 118. Les facteurs ont 1 + 1 = 2 décimales en tout, donc le produit en a 2 : **4,3 × 2,6 = 11,18**.\n(Ordre de grandeur : 4 × 3 = 12, cohérent.)\n\n**4.**\n- a. × 100 : la virgule se déplace de 2 rangs vers la droite : **5,82 × 100 = 582**.\n- b. ÷ 1 000 : la virgule se déplace de 3 rangs vers la gauche, on complète par des zéros : **36,5 ÷ 1 000 = 0,0365**."}$exo$::jsonb),
  ('ca4fdd67-bd21-5d3b-bccf-85dc817c718a'::uuid, 2, 'probleme', $exo${"titre":"Les courses de la rentrée","consigne":"Résous le problème en détaillant chaque calcul et termine par une phrase réponse.","enonce":"Emma achète :\n- **3 cahiers** à **2,45 €** chacun ;\n- **1 trousse** à **6,80 €** ;\n- **2,5 kg** de pommes à **2,40 €** le kilogramme.\n\n1. Donne un ordre de grandeur du prix des 3 cahiers, puis calcule ce prix exactement.\n2. Calcule le prix des pommes.\n3. Calcule le montant total des achats.\n4. Emma paie avec un billet de **50 €**. Combien la caissière doit-elle lui rendre ?","bareme":[{"critere":"Ordre de grandeur","points":4},{"critere":"Calcul des deux produits","points":6},{"critere":"Somme totale","points":5},{"critere":"Monnaie rendue et phrase réponse","points":5}],"dureeMin":11,"corrige":"**1.** Ordre de grandeur : 3 × 2,5 = 7,5 €, soit environ 7,50 €.\nCalcul exact : 3 × 245 = 735, avec 2 décimales : **3 × 2,45 = 7,35 €**.\n\n**2.** 25 × 240 = 6 000 ; les facteurs ont 1 + 2 = 3 décimales : 6,000. **2,5 × 2,40 = 6 €**.\n\n**3.** 7,35 + 6,80 + 6,00 = **20,15 €**.\n\n**4.** 50,00 − 20,15 = **29,85 €**. Vérification : 29,85 + 20,15 = 50.\n\nPhrase réponse : **La caissière doit rendre 29,85 € à Emma.**"}$exo$::jsonb),
  ('ca4fdd67-bd21-5d3b-bccf-85dc817c718a'::uuid, 3, 'probleme', $exo${"titre":"Priorités, ordre de grandeur et vocabulaire","consigne":"Réponds à chaque question en montrant toutes les étapes de calcul et en justifiant tes réponses.","enonce":"1. Calcule en respectant les priorités opératoires :\n   - A = 12,5 + 3 × 4,2\n   - B = (12,5 + 3) × 4,2\n   - C = 20 − 2,5 × 4 + 0,75\n2. Au cinéma, une famille achète **3 places adulte à 7,80 €** et **2 places enfant à 5,50 €**. Écris **une seule expression** qui donne le prix total, puis calcule-la.\n3. Pour calculer **29,7 × 5,1**, Jules trouve **1 514,7**. Sans poser l'opération, montre avec un ordre de grandeur que son résultat est faux, puis donne le bon résultat.\n4. Dans le calcul 15,5 × 4,2 = 65,1, comment appelle-t-on les nombres 15,5 et 4,2 ? Et le nombre 65,1 ?","bareme":[{"critere":"Calcul de A, B et C avec les priorités","points":6},{"critere":"Mise en expression et calcul du prix","points":5},{"critere":"Contrôle par l'ordre de grandeur","points":5},{"critere":"Vocabulaire des opérations","points":4}],"dureeMin":15,"corrige":"**1.**\n- A = 12,5 + 3 × 4,2 = 12,5 + 12,6 = **25,1** (la multiplication passe avant l'addition).\n- B = (12,5 + 3) × 4,2 = 15,5 × 4,2 = **65,1** (parenthèses d'abord ; 155 × 42 = 6 510, 2 décimales : 65,10).\n- C = 20 − 2,5 × 4 + 0,75 = 20 − 10 + 0,75 = 10 + 0,75 = **10,75** (multiplication d'abord, puis de gauche à droite).\n\nA et B n'ont pas la même valeur : les parenthèses changent l'ordre des calculs.\n\n**2.** Expression : **3 × 7,80 + 2 × 5,50**.\n= 23,40 + 11,00 = **34,40 €**. La famille paie 34,40 €.\n\n**3.** Ordre de grandeur : 29,7 × 5,1 ≈ 30 × 5 = 150. Le résultat 1 514,7 est environ 10 fois trop grand : une virgule s'est déplacée.\nCalcul : 297 × 51 = 15 147, avec 1 + 1 = 2 décimales : **29,7 × 5,1 = 151,47**, cohérent avec 150.\n\n**4.** 15,5 et 4,2 sont les **facteurs** ; 65,1 est le **produit**."}$exo$::jsonb),
  ('a9b856bb-a32e-5b4d-b85e-4a84600b7a4d'::uuid, 1, 'probleme', $exo${"titre":"Effectuer une division euclidienne","consigne":"Effectue la division demandée, écris l'égalité et réponds aux questions en justifiant.","enonce":"1. Effectue la division euclidienne de **158** par **7**, puis écris l'égalité de la forme dividende = diviseur × quotient + reste.\n2. Dans cette division, nomme le dividende, le diviseur, le quotient et le reste.\n3. Le nombre 7 est-il un diviseur de 158 ? Justifie.","bareme":[{"critere":"Division euclidienne et égalité correcte","points":10},{"critere":"Vocabulaire et conclusion sur la divisibilité","points":10}],"dureeMin":6,"corrige":"**1.** 7 × 22 = 154 et 158 − 154 = 4. Le reste 4 est bien plus petit que 7.\n**158 = 7 × 22 + 4**.\n\n**2.** Dividende : **158** ; diviseur : **7** ; quotient : **22** ; reste : **4**.\n\n**3.** **Non** : le reste vaut 4 et non 0, la division ne tombe pas juste. Donc 7 ne divise pas 158 (158 n'est pas un multiple de 7)."}$exo$::jsonb),
  ('a9b856bb-a32e-5b4d-b85e-4a84600b7a4d'::uuid, 2, 'probleme', $exo${"titre":"Les bouquets du fleuriste","consigne":"Résous le problème en rédigeant tes calculs et tes justifications, et réponds par des phrases.","enonce":"Un fleuriste a **250 roses**. Il fait des bouquets de **12 roses** chacun.\n\n1. Effectue la division euclidienne de 250 par 12 et écris l'égalité correspondante.\n2. Combien de bouquets complets peut-il faire ? Combien de roses lui reste-t-il ?\n3. Combien de roses devrait-il ajouter pour pouvoir faire un bouquet complet de plus ?\n4. Le lendemain, il a **282 roses**. Sans poser de division, utilise les critères de divisibilité pour dire si ces roses peuvent être partagées exactement en bouquets de **2**, de **3**, de **5** et de **9** roses. Justifie chaque réponse.","bareme":[{"critere":"Division euclidienne de 250 par 12","points":5},{"critere":"Interprétation du quotient et du reste","points":4},{"critere":"Nombre de roses à ajouter","points":3},{"critere":"Critères de divisibilité justifiés","points":8}],"dureeMin":11,"corrige":"**1.** 12 × 20 = 240 et 250 − 240 = 10, avec 10 < 12.\n**250 = 12 × 20 + 10**.\n\n**2.** Le quotient est le nombre de bouquets : **20 bouquets complets**. Le reste est ce qui ne se partage pas : **il reste 10 roses**.\n\n**3.** Un bouquet compte 12 roses : 12 − 10 = **2 roses** à ajouter (on aurait alors 252 = 12 × 21).\n\n**4.** Pour 282 :\n- par **2** : oui, le chiffre des unités est 2 (282 est pair) ;\n- par **3** : oui, 2 + 8 + 2 = 12, et 12 est divisible par 3 (282 = 3 × 94) ;\n- par **5** : non, le chiffre des unités n'est ni 0 ni 5 ;\n- par **9** : non, la somme des chiffres 12 n'est pas divisible par 9."}$exo$::jsonb),
  ('a9b856bb-a32e-5b4d-b85e-4a84600b7a4d'::uuid, 3, 'probleme', $exo${"titre":"Diviseurs, critères et nombre mystère","consigne":"Réponds à chaque question en justifiant avec les définitions et les critères du cours.","enonce":"1. Donne la liste complète des diviseurs de **36**.\n2. Le nombre **1 530** est-il divisible par 2 ? par 4 ? par 5 ? par 9 ? par 10 ? Justifie chaque réponse avec un critère.\n3. Les nombres **29** et **51** sont-ils premiers ? Justifie.\n4. Trouve le **nombre mystère** :\n   - il est compris entre 100 et 130 ;\n   - il est divisible par 9 ;\n   - dans sa division euclidienne par 5, le reste vaut 1.\n\n   Explique ta démarche et vérifie ta réponse.","bareme":[{"critere":"Liste des diviseurs de 36","points":4},{"critere":"Critères de divisibilité appliqués à 1 530","points":5},{"critere":"Nombres premiers justifiés","points":5},{"critere":"Recherche et vérification du nombre mystère","points":6}],"dureeMin":16,"corrige":"**1.** 36 = 1 × 36 = 2 × 18 = 3 × 12 = 4 × 9 = 6 × 6.\nDiviseurs de 36 : **1, 2, 3, 4, 6, 9, 12, 18, 36**.\n\n**2.** Pour 1 530 :\n- par **2** : oui, chiffre des unités 0 ;\n- par **4** : non, les deux derniers chiffres forment 30, qui n'est pas divisible par 4 ;\n- par **5** : oui, chiffre des unités 0 ;\n- par **9** : oui, 1 + 5 + 3 + 0 = 9, divisible par 9 (1 530 = 9 × 170) ;\n- par **10** : oui, chiffre des unités 0.\n\n**3.**\n- **29 est premier** : il n'est divisible ni par 2, ni par 3 (2 + 9 = 11), ni par 5, ni par 7 (7 × 4 = 28, 7 × 5 = 35). Ses seuls diviseurs sont 1 et 29.\n- **51 n'est pas premier** : 5 + 1 = 6 est divisible par 3, donc 51 = 3 × 17. Il a au moins quatre diviseurs : 1, 3, 17, 51.\n\n**4.** Multiples de 9 entre 100 et 130 : 108 (9 × 12), 117 (9 × 13), 126 (9 × 14).\nDivision par 5 : 108 = 5 × 21 + 3 ; 117 = 5 × 23 + 2 ; 126 = 5 × 25 + 1.\nLe nombre mystère est **126**. Vérification : 1 + 2 + 6 = 9 (divisible par 9), 100 < 126 < 130 et le reste par 5 vaut 1."}$exo$::jsonb),
  ('c6028cff-7a20-551b-bc79-8fe779d49f6e'::uuid, 1, 'probleme', $exo${"titre":"Poser et vérifier une division décimale","consigne":"Effectue les calculs en détaillant les étapes, puis vérifie ton premier résultat.","enonce":"1. Pose et effectue la division **27 ÷ 4** jusqu'à obtenir un reste nul. Décris les étapes (restes, zéros abaissés).\n2. Calcule **9,6 ÷ 0,4** en expliquant comment tu te ramènes à une division par un nombre entier.\n3. Vérifie le résultat de la question 1 à l'aide d'une multiplication.","bareme":[{"critere":"Division posée jusqu'au reste nul","points":8},{"critere":"Division par un nombre décimal","points":7},{"critere":"Vérification par la multiplication","points":5}],"dureeMin":8,"corrige":"**1.**\n- 27 ÷ 4 : 6, reste 3 (4 × 6 = 24) ; on écrit la virgule au quotient.\n- On abaisse un zéro : 30 ÷ 4 = 7, reste 2.\n- On abaisse un zéro : 20 ÷ 4 = 5, reste 0.\n\n**27 ÷ 4 = 6,75**.\n\n**2.** On ne divise pas par un décimal : on multiplie le dividende **et** le diviseur par 10, le quotient ne change pas.\n9,6 ÷ 0,4 = 96 ÷ 4 = **24**.\n\n**3.** 6,75 × 4 = 27 : on retrouve le dividende, le résultat est juste."}$exo$::jsonb),
  ('c6028cff-7a20-551b-bc79-8fe779d49f6e'::uuid, 2, 'probleme', $exo${"titre":"Prix au kilo et partage d'une addition","consigne":"Résous chaque partie du problème en détaillant tes calculs et en employant le bon signe (= ou ≈).","enonce":"**Partie A.** Au marché, Nadia paie **11,25 €** pour **2,5 kg** de cerises.\n\n1. Calcule le prix d'un kilogramme de cerises.\n2. Vérifie ton résultat par une multiplication.\n\n**Partie B.** Trois amis partagent équitablement une addition de **20 €**.\n\n3. La division 20 ÷ 3 ne s'arrête pas. Donne la valeur approchée au centième **par défaut**, **par excès**, puis l'**arrondi** au centième.\n4. Chloé écrit : « 20 ÷ 3 = 6,67 ». Corrige son écriture et explique.","bareme":[{"critere":"Prix au kilo par division par un décimal","points":6},{"critere":"Vérification par la multiplication","points":4},{"critere":"Valeurs approchées au centième","points":7},{"critere":"Emploi du signe ≈","points":3}],"dureeMin":12,"corrige":"**1.** On multiplie les deux nombres par 10 : 11,25 ÷ 2,5 = 112,5 ÷ 25.\n112,5 ÷ 25 = **4,5**. Le kilogramme de cerises coûte **4,50 €**.\n\n**2.** 4,5 × 2,5 = 11,25 : on retrouve le prix payé.\n\n**3.** 20 ÷ 3 = 6,666… (le chiffre 6 se répète sans fin).\n- par défaut (on tronque) : **6,66** ;\n- par excès : **6,67** ;\n- arrondi au centième : le chiffre des millièmes est 6 (5 ou plus), donc **6,67**.\n\nChaque ami paie environ 6,67 €.\n\n**4.** 6,67 n'est pas la valeur exacte (6,67 × 3 = 20,01). Il faut écrire **20 ÷ 3 ≈ 6,67** : le signe ≈ indique une valeur approchée, le signe = une égalité exacte."}$exo$::jsonb),
  ('c6028cff-7a20-551b-bc79-8fe779d49f6e'::uuid, 3, 'probleme', $exo${"titre":"Le voyage en voiture","consigne":"Résous le problème en rédigeant chaque étape, vérifie tes divisions et analyse l'erreur proposée.","enonce":"Pour un trajet de **450 km**, la voiture de la famille Martin a consommé **31,5 L** d'essence. Le plein de ces 31,5 L a coûté **58,59 €**.\n\n1. Calcule la consommation de la voiture **aux 100 km** (indice : combien de fois 100 km dans 450 km ?).\n2. Calcule le prix d'un litre d'essence.\n3. Les trois adultes du voyage partagent équitablement le prix du plein. Calcule la part de chacun, puis vérifie par une multiplication.\n4. Pierre propose, pour la question 2 : « Je multiplie seulement 31,5 par 10 et je calcule 58,59 ÷ 315 : j'aurai le même résultat. » Explique pourquoi il se trompe et ce qu'il aurait dû faire.","bareme":[{"critere":"Consommation aux 100 km","points":5},{"critere":"Prix du litre par division par un décimal","points":6},{"critere":"Partage et vérification","points":4},{"critere":"Analyse de l'erreur de Pierre","points":5}],"dureeMin":16,"corrige":"**1.** 450 km = 4,5 fois 100 km. Consommation aux 100 km : 31,5 ÷ 4,5 = 315 ÷ 45 = **7 L**.\nVérification : 7 × 4,5 = 31,5. La voiture consomme **7 L aux 100 km**.\n\n**2.** Prix du litre : 58,59 ÷ 31,5. On multiplie les deux nombres par 10 : 585,9 ÷ 315 = **1,86**.\nVérification : 1,86 × 31,5 = 58,59. Le litre coûte **1,86 €**.\n\n**3.** 58,59 ÷ 3 = **19,53 €**. Vérification : 19,53 × 3 = 58,59. Chaque adulte paie 19,53 €.\n\n**4.** Pierre a multiplié **un seul** des deux nombres : le diviseur est 10 fois plus grand, donc son quotient est 10 fois trop petit (58,59 ÷ 315 = 0,186 au lieu de 1,86). Il faut multiplier le dividende **et** le diviseur par le même nombre : 585,9 ÷ 315."}$exo$::jsonb),
  ('2d954c16-5948-5fc7-93f3-bc385021c076'::uuid, 1, 'probleme', $exo${"titre":"Le sens d'une fraction","consigne":"Réponds à chaque question par des phrases et justifie tes comparaisons.","enonce":"1. Dans la fraction **5/8** :\n   a. quel est le numérateur ? le dénominateur ?\n   b. explique ce que représente 5/8 d'une tarte.\n2. Écris le quotient **7 ÷ 4** sous forme de fraction, puis donne son écriture décimale.\n3. Pour chaque fraction, dis si elle est plus petite que 1, égale à 1 ou plus grande que 1, et justifie : **3/5** ; **9/9** ; **11/6**.","bareme":[{"critere":"Vocabulaire et sens du partage","points":7},{"critere":"Fraction et quotient décimal","points":6},{"critere":"Comparaison à 1 justifiée","points":7}],"dureeMin":7,"corrige":"**1.**\n- a. Le numérateur est **5**, le dénominateur est **8**.\n- b. On coupe la tarte en **8 parts égales** et on en prend **5**.\n\n**2.** 7 ÷ 4 = **7/4** = **1,75** (7 ÷ 4 : 1, reste 3 ; 30 ÷ 4 = 7, reste 2 ; 20 ÷ 4 = 5, reste 0).\n\n**3.**\n- **3/5 < 1** : le numérateur 3 est plus petit que le dénominateur 5.\n- **9/9 = 1** : numérateur et dénominateur sont égaux.\n- **11/6 > 1** : le numérateur 11 est plus grand que le dénominateur 6."}$exo$::jsonb),
  ('2d954c16-5948-5fc7-93f3-bc385021c076'::uuid, 2, 'probleme', $exo${"titre":"La classe et la cantine","consigne":"Résous le problème en détaillant tes calculs et réponds par des phrases.","enonce":"Une classe compte **28 élèves**. Les **3/4** des élèves mangent à la cantine, les autres rentrent chez eux.\n\n1. Calcule le nombre d'élèves qui mangent à la cantine.\n2. Quelle fraction de la classe rentre à la maison ? Combien d'élèves cela représente-t-il ?\n3. Dans cette classe, **16 élèves** font du sport en club. Écris la fraction de la classe que cela représente, puis simplifie-la jusqu'à obtenir une fraction irréductible.\n4. Donne l'écriture décimale de 3/4 et de 1/4.","bareme":[{"critere":"Fraction d'une quantité","points":6},{"critere":"Fraction complémentaire et effectif","points":4},{"critere":"Simplification jusqu'à l'irréductible","points":6},{"critere":"Écritures décimales","points":4}],"dureeMin":11,"corrige":"**1.** Les 3/4 de 28 : 28 ÷ 4 × 3 = 7 × 3 = **21**. **21 élèves** mangent à la cantine.\n\n**2.** La classe entière vaut 4/4 ; 4/4 − 3/4 = **1/4** de la classe rentre à la maison, soit 28 ÷ 4 = **7 élèves** (vérification : 21 + 7 = 28).\n\n**3.** 16 élèves sur 28 : **16/28**.\nOn divise en haut et en bas par 2 : 8/14, puis encore par 2 : **4/7**. 4 et 7 n'ont plus de diviseur commun autre que 1 : 4/7 est irréductible (on peut aussi diviser directement par 4).\n\n**4.** 3/4 = **0,75** et 1/4 = **0,25**."}$exo$::jsonb),
  ('2d954c16-5948-5fc7-93f3-bc385021c076'::uuid, 3, 'probleme', $exo${"titre":"Fractions égales et partage d'un jardin","consigne":"Réponds à chaque question en justifiant, en détaillant les calculs et en simplifiant les fractions.","enonce":"1. Complète les égalités et explique ta méthode : **3/5 = …/20 = 60/…** . Donne aussi l'écriture décimale de 3/5.\n2. Simplifie **36/48** jusqu'à obtenir une fraction irréductible.\n3. Un jardin a une aire de **360 m²**. Les **2/9** du jardin sont un potager et les **5/12** sont une pelouse ; le reste est une allée.\n   a. Calcule l'aire du potager et celle de la pelouse.\n   b. Calcule l'aire de l'allée.\n4. Léo affirme : « 7/4 est plus petit que 1, car on ne peut pas prendre 7 parts d'une tarte coupée en 4. » Explique son erreur.","bareme":[{"critere":"Fractions égales et écriture décimale","points":4},{"critere":"Simplification de 36/48","points":4},{"critere":"Aires calculées avec des fractions d'une quantité","points":7},{"critere":"Analyse de l'erreur de Léo","points":5}],"dureeMin":16,"corrige":"**1.** On multiplie le numérateur et le dénominateur par le même nombre :\n- 3/5 = **12/20** (× 4) ;\n- 3/5 = **60/100** (× 20).\n\n3/5 = 3 ÷ 5 = **0,6**.\n\n**2.** 36/48 : on divise par 2 → 18/24, par 2 → 9/12, par 3 → **3/4**. (En une fois : on divise par 12.) 3/4 est irréductible.\n\n**3.**\n- a. Potager : 360 ÷ 9 × 2 = 40 × 2 = **80 m²**. Pelouse : 360 ÷ 12 × 5 = 30 × 5 = **150 m²**.\n- b. Allée : 360 − 80 − 150 = **130 m²**.\n\n**4.** 7/4 = 7 ÷ 4 = 1,75, et le numérateur 7 est plus grand que le dénominateur 4 : **7/4 > 1**. On peut prendre 7 quarts si on a plusieurs tartes : une tarte entière (4/4) plus 3 parts d'une deuxième tarte. Une fraction peut dépasser 1."}$exo$::jsonb),
  ('5d74948a-dfff-5ae9-ac74-67bcf1714896'::uuid, 1, 'probleme', $exo${"titre":"Comparer et encadrer des fractions","consigne":"Réponds à chaque question en citant la règle du cours qui justifie ta réponse.","enonce":"1. Compare chaque fraction à 1 : **4/9** ; **12/7** ; **6/6**.\n2. Compare les fractions suivantes et justifie :\n   a. **5/11** et **8/11** ;\n   b. **4/7** et **4/9**.\n3. Encadre **23/5** entre deux nombres entiers consécutifs. Montre ton calcul.","bareme":[{"critere":"Comparaison à 1","points":6},{"critere":"Comparaison à dénominateur ou numérateur égal","points":8},{"critere":"Encadrement entre deux entiers","points":6}],"dureeMin":8,"corrige":"**1.**\n- 4/9 **< 1** (4 < 9) ;\n- 12/7 **> 1** (12 > 7) ;\n- 6/6 **= 1** (6 = 6).\n\n**2.**\n- a. Même dénominateur : on compare les numérateurs. 5 < 8 donc **5/11 < 8/11**.\n- b. Même numérateur : le plus grand dénominateur donne la plus petite fraction (les parts sont plus petites). 9 > 7 donc **4/9 < 4/7**.\n\n**3.** 23 ÷ 5 = 4,6. Donc **4 < 23/5 < 5**."}$exo$::jsonb),
  ('5d74948a-dfff-5ae9-ac74-67bcf1714896'::uuid, 2, 'probleme', $exo${"titre":"Qui a mangé le plus de pizza ?","consigne":"Résous le problème en justifiant chaque comparaison et chaque rangement.","enonce":"Des amis ont chacun une pizza de même taille. Voici la part de sa pizza que chacun a mangée :\n\n| Ami | Part mangée |\n| --- | --- |\n| Adam | 3/4 |\n| Béa | 5/8 |\n| Chloé | 1/2 |\n\n1. Écris les trois fractions avec le même dénominateur **8**.\n2. Range les trois fractions dans l'ordre **croissant**. Qui a mangé le plus ?\n3. Exprime la part de Chloé et celle d'Adam en pourcentage.\n4. Dan a mangé **5/6** de sa pizza. A-t-il mangé plus ou moins que Béa ? Justifie sans calcul.","bareme":[{"critere":"Mise au même dénominateur","points":6},{"critere":"Rangement croissant et conclusion","points":5},{"critere":"Passage aux pourcentages","points":4},{"critere":"Comparaison à numérateur égal","points":5}],"dureeMin":11,"corrige":"**1.**\n- 3/4 = 6/8 (× 2 en haut et en bas) ;\n- 5/8 reste 5/8 ;\n- 1/2 = 4/8 (× 4 en haut et en bas).\n\n**2.** Même dénominateur : on compare les numérateurs, 4 < 5 < 6.\n**1/2 < 5/8 < 3/4**. C'est **Adam** qui a mangé le plus.\n\n**3.** Chloé : 1/2 = **50 %**. Adam : 3/4 = **75 %**.\n\n**4.** 5/6 et 5/8 ont le même numérateur. Le plus petit dénominateur donne la plus grande fraction (des sixièmes sont plus gros que des huitièmes) : **5/6 > 5/8**. Dan a mangé **plus** que Béa."}$exo$::jsonb),
  ('5d74948a-dfff-5ae9-ac74-67bcf1714896'::uuid, 3, 'probleme', $exo${"titre":"Ranger, encadrer, placer et intercaler","consigne":"Réponds à chaque question en justifiant ; décris les étapes par écrit, aucun tracé n'est demandé.","enonce":"On considère les fractions : **7/6** ; **2/3** ; **5/6** ; **1/2** ; **3/2**.\n\n1. Écris-les toutes avec le dénominateur 6, puis range-les dans l'ordre **croissant**.\n2. Encadre **7/6** et **3/2** entre deux nombres entiers consécutifs.\n3. Décris en étapes comment placer **5/6** puis **7/6** sur une demi-droite graduée d'origine O dont l'unité est donnée. Précise de quel côté du point d'abscisse 1 se trouve chacun des deux points.\n4. Existe-t-il une fraction de dénominateur 12 **strictement** comprise entre 2/3 et 3/4 ? Justifie. Trouve ensuite une fraction de dénominateur **24** comprise entre ces deux fractions.","bareme":[{"critere":"Rangement avec un dénominateur commun","points":6},{"critere":"Encadrements entre deux entiers","points":4},{"critere":"Placement décrit sur la demi-droite","points":4},{"critere":"Fraction intercalée justifiée","points":6}],"dureeMin":17,"corrige":"**1.** 7/6 ; 2/3 = 4/6 ; 5/6 ; 1/2 = 3/6 ; 3/2 = 9/6.\nOn compare les numérateurs : 3 < 4 < 5 < 7 < 9.\n**1/2 < 2/3 < 5/6 < 7/6 < 3/2**.\n\n**2.**\n- 7/6 : 7 ÷ 6 = 1,166…, et 6/6 < 7/6 < 12/6, donc **1 < 7/6 < 2**.\n- 3/2 = 1,5, donc **1 < 3/2 < 2**.\n\n**3.** On partage chaque unité en **6 parts égales** (le dénominateur).\n- Pour 5/6 : on compte **5 parts** à partir de O. Le point est **avant** 1 (5/6 < 1).\n- Pour 7/6 : on compte **7 parts** à partir de O, c'est-à-dire 1 part après le point d'abscisse 1. Le point est **après** 1 (7/6 > 1).\n\n**4.** Avec le dénominateur 12 : 2/3 = 8/12 et 3/4 = 9/12. Il n'y a aucun nombre entier strictement entre 8 et 9, donc **aucune** fraction de dénominateur 12 ne convient.\nAvec le dénominateur 24 : 2/3 = 16/24 et 3/4 = 18/24. Comme 16 < 17 < 18 : **2/3 < 17/24 < 3/4**. La fraction cherchée est **17/24**."}$exo$::jsonb),
  ('77846829-9fa4-554e-8179-737d7b9d1502'::uuid, 1, 'probleme', $exo${"titre":"Calculer avec des fractions","consigne":"Calcule chaque expression en détaillant et donne le résultat sous forme irréductible.","enonce":"Calcule et simplifie si possible :\n\n1. **3/11 + 5/11**\n2. **9/10 − 4/10**\n3. **4 × 2/9**\n4. **3/5 × 2/7**","bareme":[{"critere":"Addition et soustraction au même dénominateur","points":8},{"critere":"Multiplications de fractions","points":7},{"critere":"Résultats sous forme irréductible","points":5}],"dureeMin":7,"corrige":"**1.** On ajoute les numérateurs et on garde le dénominateur : 3/11 + 5/11 = **8/11** (irréductible).\n\n**2.** 9/10 − 4/10 = 5/10 = **1/2** (on divise en haut et en bas par 5).\n\n**3.** Par un entier, on multiplie le numérateur seul : 4 × 2/9 = **8/9**.\n\n**4.** Numérateurs entre eux, dénominateurs entre eux : 3/5 × 2/7 = (3 × 2)/(5 × 7) = **6/35** (irréductible)."}$exo$::jsonb),
  ('77846829-9fa4-554e-8179-737d7b9d1502'::uuid, 2, 'probleme', $exo${"titre":"La lecture de Mathis","consigne":"Résous le problème en détaillant les calculs sur les fractions et réponds par des phrases.","enonce":"Mathis lit un roman de **240 pages**. Lundi, il en lit **1/4**. Mardi, il en lit **1/3**.\n\n1. Quelle fraction du livre a-t-il lue en deux jours ? Détaille la mise au même dénominateur.\n2. Quelle fraction du livre lui reste-t-il à lire ?\n3. Combien de pages lui reste-t-il à lire ?\n4. Combien de pages a-t-il lues lundi ? et mardi ? Vérifie la cohérence avec la question 3.","bareme":[{"critere":"Addition au dénominateur commun","points":6},{"critere":"Fraction restante","points":4},{"critere":"Fraction d'une quantité","points":6},{"critere":"Vérification et phrases réponses","points":4}],"dureeMin":12,"corrige":"**1.** On prend le dénominateur 4 × 3 = 12 : 1/4 = 3/12 et 1/3 = 4/12.\n1/4 + 1/3 = 3/12 + 4/12 = **7/12**. Mathis a lu les 7/12 du livre.\n\n**2.** Le livre entier vaut 12/12 : 12/12 − 7/12 = **5/12**. Il lui reste les 5/12 du livre.\n\n**3.** Les 5/12 de 240 : 240 ÷ 12 × 5 = 20 × 5 = **100 pages**.\n\n**4.** Lundi : 240 ÷ 4 = **60 pages**. Mardi : 240 ÷ 3 = **80 pages**.\nVérification : 60 + 80 + 100 = 240. Il lui reste bien 100 pages à lire."}$exo$::jsonb),
  ('77846829-9fa4-554e-8179-737d7b9d1502'::uuid, 3, 'probleme', $exo${"titre":"Calculs, erreur à corriger et budget d'un club","consigne":"Réponds à chaque question en détaillant tes calculs, en simplifiant tes résultats et en justifiant.","enonce":"1. Calcule et donne le résultat sous forme irréductible :\n   - A = 5/6 − 1/4\n   - B = 3/4 × 8/9\n   - C = 2/5 + 3/10\n2. Sam écrit : « 1/3 + 1/4 = 2/7 ». Explique son erreur et donne le bon résultat.\n3. Un club dispose d'un budget de **450 €**. Il consacre les **3/5** du budget aux sorties, puis **1/3 de ce qui reste** au matériel.\n   a. Calcule la somme consacrée aux sorties, puis celle consacrée au matériel.\n   b. Quelle somme reste-t-il après ces deux dépenses ?\n4. Montre que la somme consacrée au matériel représente les **2/15** du budget total, en calculant 1/3 × 2/5, puis vérifie avec le résultat de la question 3.","bareme":[{"critere":"Calcul de A, B et C","points":7},{"critere":"Analyse de l'erreur de Sam","points":4},{"critere":"Sommes du budget","points":5},{"critere":"Produit de fractions et vérification","points":4}],"dureeMin":18,"corrige":"**1.**\n- A : dénominateur commun 12 : 5/6 = 10/12 et 1/4 = 3/12. A = 10/12 − 3/12 = **7/12**.\n- B : on simplifie avant (8 et 4 par 4, 3 et 9 par 3) : B = (1 × 2)/(1 × 3) = **2/3**. (Sans simplifier : 24/36 = 2/3.)\n- C : 2/5 = 4/10. C = 4/10 + 3/10 = **7/10**.\n\n**2.** Sam a additionné les numérateurs **et** les dénominateurs : c'est interdit, on n'additionne que des parts de même taille. Avec le dénominateur 12 : 1/3 + 1/4 = 4/12 + 3/12 = **7/12**.\n\n**3.**\n- a. Sorties : 450 ÷ 5 × 3 = 90 × 3 = **270 €**. Reste : 450 − 270 = 180 €. Matériel : 180 ÷ 3 = **60 €**.\n- b. 180 − 60 = **120 €** restent au club.\n\n**4.** Après les sorties, il reste 1 − 3/5 = 2/5 du budget. Le matériel vaut 1/3 de ces 2/5 : 1/3 × 2/5 = **2/15**.\nVérification : les 2/15 de 450 = 450 ÷ 15 × 2 = 30 × 2 = 60 €. On retrouve bien 60 €."}$exo$::jsonb),
  ('282d55b7-97ac-5962-b07a-de876ca38f11'::uuid, 1, 'probleme', $exo${"titre":"Écrire et calculer des pourcentages","consigne":"Réponds à chaque question en montrant tes calculs.","enonce":"1. Écris **40 %** :\n   a. sous forme d'une fraction de dénominateur 100 ;\n   b. sous forme d'une fraction irréductible ;\n   c. sous forme décimale.\n2. Calcule en expliquant ta méthode :\n   a. **10 %** de 350 ;\n   b. **25 %** de 64 ;\n   c. **75 %** de 64.","bareme":[{"critere":"Écritures d'un pourcentage","points":8},{"critere":"Calcul de pourcentages avec les repères","points":12}],"dureeMin":7,"corrige":"**1.**\n- a. 40 % = **40/100** ;\n- b. 40/100 = 4/10 = **2/5** (on divise par 10 puis par 2) ;\n- c. 40 % = **0,4**.\n\n**2.**\n- a. 10 % : on divise par 10 : 350 ÷ 10 = **35**.\n- b. 25 % : on divise par 4 : 64 ÷ 4 = **16**.\n- c. 75 % = 50 % + 25 % : 64 ÷ 2 + 64 ÷ 4 = 32 + 16 = **48**. (Ou 64 × 75 ÷ 100 = 48.)"}$exo$::jsonb),
  ('282d55b7-97ac-5962-b07a-de876ca38f11'::uuid, 2, 'probleme', $exo${"titre":"Soldes et sondage","consigne":"Résous chaque partie en détaillant tes calculs et termine par des phrases réponses.","enonce":"**Partie A.** Une veste coûte **80 €**. Pendant les soldes, son prix baisse de **30 %**.\n\n1. Calcule le montant de la réduction.\n2. Calcule le nouveau prix de la veste de deux façons : en soustrayant la réduction, puis en multipliant 80 par le nombre qui convient.\n\n**Partie B.**\n\n3. Dans une classe de **25 élèves**, **9** ont un chien. Quel pourcentage des élèves cela représente-t-il ?\n4. Calcule **35 %** de 60 en utilisant les repères 25 % et 10 %.","bareme":[{"critere":"Montant de la réduction","points":5},{"critere":"Prix soldé par deux méthodes","points":5},{"critere":"Calcul d'une proportion en pourcentage","points":5},{"critere":"Calcul mental 25 % + 10 %","points":5}],"dureeMin":12,"corrige":"**1.** 30 % de 80 = 80 × 30 ÷ 100 = **24 €**. La réduction est de 24 €.\n\n**2.**\n- Méthode 1 : 80 − 24 = **56 €**.\n- Méthode 2 : après une baisse de 30 %, on garde 70 % du prix : 80 × 0,7 = **56 €**.\n\nLa veste soldée coûte 56 €.\n\n**3.** 9 ÷ 25 = 0,36 = **36 %**. 36 % des élèves de la classe ont un chien.\n\n**4.** 25 % de 60 = 60 ÷ 4 = 15 ; 10 % de 60 = 60 ÷ 10 = 6.\n35 % de 60 = 15 + 6 = **21**."}$exo$::jsonb),
  ('282d55b7-97ac-5962-b07a-de876ca38f11'::uuid, 3, 'probleme', $exo${"titre":"Hausse puis baisse : le piège des pourcentages","consigne":"Résous le problème en détaillant tes calculs et explique clairement le piège.","enonce":"**Partie A.** Un vélo coûte **250 €**. Le magasin augmente son prix de **20 %**, puis, un mois plus tard, baisse le nouveau prix de **20 %**.\n\n1. Calcule le prix après l'augmentation.\n2. Calcule le prix après la baisse.\n3. Lina affirme : « +20 % puis −20 %, le vélo revient à 250 €. » Explique pourquoi elle se trompe. Calcule ensuite de combien d'euros le prix a baissé au total, et quel pourcentage de 250 € cela représente.\n\n**Partie B.**\n\n4. Un collège compte **480 élèves** ; **45 %** d'entre eux sont demi-pensionnaires. Calcule leur nombre, puis vérifie en décomposant 45 % avec les repères 25 % et 10 %. Écris aussi 45 % sous forme de fraction irréductible.","bareme":[{"critere":"Prix après l'augmentation","points":4},{"critere":"Prix après la baisse","points":4},{"critere":"Explication du piège et pourcentage global","points":7},{"critere":"Pourcentage d'un effectif et vérification","points":5}],"dureeMin":16,"corrige":"**1.** Une hausse de 20 % : on garde 120 % du prix : 250 × 1,2 = **300 €**.\n\n**2.** Une baisse de 20 % : on garde 80 % du prix : 300 × 0,8 = **240 €**.\n\n**3.** Lina se trompe : les deux pourcentages ne portent pas sur la même quantité. La hausse de 20 % porte sur 250 € (+50 €), la baisse de 20 % porte sur 300 € (−60 €). Le prix final est 240 €, pas 250 €.\nBaisse totale : 250 − 240 = **10 €**. Proportion : 10 ÷ 250 = 0,04 = **4 %**. Le prix a baissé de 4 % au total.\n\n**4.** 45 % de 480 = 480 × 45 ÷ 100 = **216 élèves**.\nVérification : 45 % = 25 % + 10 % + 10 % ; 480 ÷ 4 = 120 ; 480 ÷ 10 = 48 ; 120 + 48 + 48 = 216.\n45 % = 45/100 = **9/20** (on divise par 5).\n216 élèves sont demi-pensionnaires."}$exo$::jsonb),
  ('37ab8b16-89e6-5898-973b-14ce23b49525'::uuid, 1, 'probleme', $exo${"titre":"Trouver un nombre inconnu","consigne":"Pour chaque question, écris l'égalité, trouve le nombre inconnu avec l'opération inverse, vérifie et réponds par une phrase.","enonce":"1. Résous : **x + 18 = 45**.\n2. Résous : **6 × x = 84**.\n3. « Je pense à un nombre. Je le multiplie par 7 et j'obtiens 91. » Écris l'égalité avec une lettre, puis trouve le nombre.","bareme":[{"critere":"Résolution avec l'opération inverse","points":12},{"critere":"Vérification et phrase réponse","points":8}],"dureeMin":7,"corrige":"**1.** L'inverse de l'addition est la soustraction : x = 45 − 18 = **27**.\nVérification : 27 + 18 = 45. Le nombre cherché est 27.\n\n**2.** L'inverse de la multiplication est la division : x = 84 ÷ 6 = **14**.\nVérification : 6 × 14 = 84. Le nombre cherché est 14.\n\n**3.** Égalité : **7 × x = 91** (ou x × 7 = 91).\nx = 91 ÷ 7 = **13**. Vérification : 7 × 13 = 91.\nLe nombre auquel je pensais est 13."}$exo$::jsonb),
  ('37ab8b16-89e6-5898-973b-14ce23b49525'::uuid, 2, 'probleme', $exo${"titre":"Les billes de Léna et Hugo","consigne":"Résous le problème en suivant la méthode du cours : repère les données, modélise, calcule, vérifie et réponds par des phrases.","enonce":"Léna a **3 fois plus** de billes que Hugo. À eux deux, ils ont **84 billes**.\n\n1. Décris par écrit un schéma en barres qui représente la situation : combien de parts égales pour Hugo, pour Léna, et au total ?\n2. Calcule le nombre de billes de Hugo, puis celui de Léna.\n3. Vérifie tes résultats avec les deux informations de l'énoncé.\n4. Hugo gagne ensuite **15 billes** à la récréation. Combien a-t-il alors de billes de moins que Léna ?","bareme":[{"critere":"Modélisation par un schéma en barres","points":5},{"critere":"Calcul des deux quantités","points":6},{"critere":"Vérification","points":4},{"critere":"Dernière question et phrases réponses","points":5}],"dureeMin":12,"corrige":"**1.** Hugo : **1 part**. Léna : **3 parts** de la même longueur. Au total : 1 + 3 = **4 parts égales**, qui représentent 84 billes.\n\n**2.** Une part : 84 ÷ 4 = **21**. Hugo a **21 billes**. Léna a 3 × 21 = **63 billes**.\n\n**3.** 21 + 63 = 84 (le total est bon) et 63 = 3 × 21 (Léna en a bien 3 fois plus).\n\n**4.** Hugo a maintenant 21 + 15 = 36 billes. 63 − 36 = **27**.\nHugo a 27 billes de moins que Léna."}$exo$::jsonb),
  ('37ab8b16-89e6-5898-973b-14ce23b49525'::uuid, 3, 'probleme', $exo${"titre":"Les ballons du club de sport","consigne":"Résous le problème en plusieurs étapes, en justifiant le choix de chaque opération et en répondant par des phrases.","enonce":"Un club de football achète **12 ballons identiques** et **un filet à 38 €**. La facture totale est de **206 €**.\n\n1. Quelle question intermédiaire faut-il se poser avant de trouver le prix d'un ballon ? Réponds-y.\n2. On note **x** le prix d'un ballon en euros. Écris une égalité qui traduit l'énoncé, puis trouve x.\n3. Vérifie ton résultat en recalculant la facture, puis explique pourquoi l'ordre de grandeur de ta réponse est raisonnable pour un ballon.\n4. Un autre club dépense **3 fois moins** que le premier pour ses ballons, qui sont au même prix. Combien a-t-il dépensé pour ses ballons, et combien en a-t-il acheté ? Explique pourquoi on fait une division alors que l'énoncé contient le mot « fois ».","bareme":[{"critere":"Question intermédiaire et prix des 12 ballons","points":4},{"critere":"Égalité avec une lettre et résolution","points":5},{"critere":"Vérification et ordre de grandeur","points":3},{"critere":"Interprétation de « 3 fois moins »","points":5},{"critere":"Phrases réponses","points":3}],"dureeMin":16,"corrige":"**1.** Question intermédiaire : « Combien coûtent les 12 ballons ? »\n206 − 38 = **168 €**. Les 12 ballons coûtent 168 €.\n\n**2.** Égalité : **12 × x + 38 = 206**, donc 12 × x = 168.\nx = 168 ÷ 12 = **14**. Un ballon coûte 14 €.\n\n**3.** 12 × 14 + 38 = 168 + 38 = 206 : on retrouve la facture.\n14 € est un prix plausible pour un ballon (ni 1 €, ni 400 €) ; et 12 ballons à environ 10 € coûtent environ 120 €, du même ordre que 168 €.\n\n**4.** « 3 fois moins » signifie qu'on partage en 3 : c'est la situation qui décide, pas le mot « fois ». 168 ÷ 3 = **56 €**. Nombre de ballons : 56 ÷ 14 = **4 ballons**.\nVérification : 4 × 14 = 56 et 56 × 3 = 168.\nLe deuxième club a dépensé 56 € et acheté 4 ballons."}$exo$::jsonb),
  ('15b3551e-f499-5560-b197-00898aa3d9bf'::uuid, 1, 'probleme', $exo${"titre":"Les couleurs préférées de la classe","consigne":"Lis le tableau et réponds aux questions avec le vocabulaire des statistiques.","enonce":"On a demandé à chaque élève d'une classe de 6e sa couleur préférée.\n\n| Couleur | Bleu | Rouge | Vert | Jaune |\n| --- | --- | --- | --- | --- |\n| Effectif | 10 | 6 | 5 | 4 |\n\n1. Quelle est la population étudiée ? Quel est le caractère observé ? Calcule l'effectif total.\n2. Calcule la fréquence de la couleur bleue, en écriture décimale puis en pourcentage.\n3. On veut **comparer** les couleurs entre elles. Quel type de graphique faut-il choisir ? Justifie.","bareme":[{"critere":"Vocabulaire et effectif total","points":7},{"critere":"Calcul de la fréquence","points":8},{"critere":"Choix de la représentation justifié","points":5}],"dureeMin":8,"corrige":"**1.** Population : **les élèves de la classe**. Caractère : **la couleur préférée**. Effectif total : 10 + 6 + 5 + 4 = **25 élèves**.\n\n**2.** Fréquence du bleu = effectif ÷ effectif total = 10 ÷ 25 = **0,4 = 40 %**.\n\n**3.** Un **diagramme en barres** : c'est la représentation qui permet le mieux de comparer des catégories (la hauteur des barres se compare d'un coup d'œil)."}$exo$::jsonb),
  ('15b3551e-f499-5560-b197-00898aa3d9bf'::uuid, 2, 'probleme', $exo${"titre":"Deux élèves, une même moyenne","consigne":"Calcule les moyennes en détaillant, puis rédige une analyse des résultats.","enonce":"Voici les notes sur 20 de deux élèves au premier trimestre :\n\n| Élève | Notes |\n| --- | --- |\n| Anna | 8 ; 14 ; 11 ; 17 ; 10 |\n| Basile | 12 ; 12 ; 12 ; 12 ; 12 |\n\n1. Calcule la moyenne d'Anna.\n2. Calcule la moyenne de Basile.\n3. Les deux élèves ont-ils des résultats semblables ? Explique ce que la moyenne ne dit pas.\n4. Anna obtient ensuite une sixième note : **18**. Calcule sa nouvelle moyenne.","bareme":[{"critere":"Moyenne d'Anna","points":5},{"critere":"Moyenne de Basile","points":3},{"critere":"Analyse de la dispersion","points":6},{"critere":"Nouvelle moyenne avec six notes","points":6}],"dureeMin":11,"corrige":"**1.** Somme : 8 + 14 + 11 + 17 + 10 = 60. Moyenne : 60 ÷ 5 = **12**.\n\n**2.** Somme : 5 × 12 = 60. Moyenne : 60 ÷ 5 = **12**.\n\n**3.** Les deux moyennes sont égales (12), mais les résultats ne se ressemblent pas : les notes de Basile sont toutes identiques, celles d'Anna vont de 8 à 17, elles sont très **dispersées**. La moyenne ne dit rien de la dispersion : il faut regarder le détail des notes.\n\n**4.** Nouvelle somme : 60 + 18 = 78. Nombre de notes : 6. Moyenne : 78 ÷ 6 = **13**.\nLa nouvelle moyenne d'Anna est 13."}$exo$::jsonb),
  ('15b3551e-f499-5560-b197-00898aa3d9bf'::uuid, 3, 'probleme', $exo${"titre":"Le trajet des élèves : diagramme et graphique trompeur","consigne":"Réponds aux questions en détaillant tes calculs et rédige une analyse critique du graphique décrit.","enonce":"On a demandé à **40 élèves** leur moyen de transport pour venir au collège.\n\n| Transport | Bus | Voiture | Vélo | À pied |\n| --- | --- | --- | --- | --- |\n| Effectif | 18 | 10 | 8 | 4 |\n\n1. Vérifie que la somme des effectifs est bien égale à l'effectif total.\n2. Calcule la fréquence de chaque moyen de transport, en pourcentage.\n3. On veut représenter ces données par un diagramme circulaire. Calcule l'angle de chaque secteur, puis vérifie la somme des angles.\n4. Un journal publie un diagramme en barres de ces données, mais son axe vertical **commence à 8** au lieu de 0. On y voit une barre « Bus » de 10 carreaux de haut et une barre « Voiture » de 2 carreaux.\n   a. D'après ce dessin, combien de fois le bus semble-t-il plus utilisé que la voiture ?\n   b. Combien de fois l'est-il réellement ?\n   c. Explique le problème de ce graphique.","bareme":[{"critere":"Vérification de l'effectif total","points":3},{"critere":"Fréquences en pourcentage","points":5},{"critere":"Angles du diagramme circulaire","points":6},{"critere":"Analyse du graphique trompeur","points":6}],"dureeMin":18,"corrige":"**1.** 18 + 10 + 8 + 4 = **40** : aucune donnée n'a été perdue.\n\n**2.** Fréquence = effectif ÷ 40 :\n- Bus : 18 ÷ 40 = 0,45 = **45 %** ;\n- Voiture : 10 ÷ 40 = 0,25 = **25 %** ;\n- Vélo : 8 ÷ 40 = 0,2 = **20 %** ;\n- À pied : 4 ÷ 40 = 0,1 = **10 %**.\n\nTotal : 100 %.\n\n**3.** Angle = fréquence × 360° :\n- Bus : 0,45 × 360 = **162°** ;\n- Voiture : 0,25 × 360 = **90°** ;\n- Vélo : 0,2 × 360 = **72°** ;\n- À pied : 0,1 × 360 = **36°**.\n\nVérification : 162 + 90 + 72 + 36 = 360°.\n\n**4.**\n- a. Sur le dessin, la barre du bus est 10 ÷ 2 = **5 fois** plus haute.\n- b. En réalité : 18 ÷ 10 = **1,8 fois** plus.\n- c. L'axe ne part pas de zéro : on a coupé les 8 premières unités de chaque barre, ce qui **exagère visuellement** l'écart. Il faut toujours vérifier où commence l'échelle avant de comparer des barres."}$exo$::jsonb),
  ('7c0536c3-5d68-5cfc-b877-7064e51a0fcf'::uuid, 1, 'probleme', $exo${"titre":"Probabilités avec un dé","consigne":"Réponds à chaque question en rédigeant et en justifiant tes probabilités.","enonce":"On lance un dé équilibré à six faces numérotées de 1 à 6.\n\n1. Explique pourquoi cette expérience est aléatoire. Quelles sont ses issues ?\n2. Calcule la probabilité :\n   a. d'obtenir **5** ;\n   b. d'obtenir un **multiple de 3**.\n3. Quelle est la probabilité d'obtenir **0** ? Comment appelle-t-on un tel événement ?","bareme":[{"critere":"Expérience aléatoire et issues","points":4},{"critere":"Calcul des probabilités","points":10},{"critere":"Événement impossible reconnu","points":6}],"dureeMin":7,"corrige":"**1.** On ne peut pas prévoir le résultat du lancer à l'avance : l'expérience est **aléatoire**. Les issues sont **1, 2, 3, 4, 5 et 6** (6 issues qui ont toutes la même chance).\n\n**2.** P = nombre de cas favorables ÷ nombre de cas possibles.\n- a. Un seul cas favorable (5) : P = **1/6**.\n- b. Multiples de 3 : 3 et 6, soit 2 cas : P = 2/6 = **1/3**.\n\n**3.** Aucune face ne porte 0 : P = **0**. C'est un événement **impossible**."}$exo$::jsonb),
  ('7c0536c3-5d68-5cfc-b877-7064e51a0fcf'::uuid, 2, 'probleme', $exo${"titre":"Le sac de billes","consigne":"Réponds aux questions en justifiant et en écrivant les probabilités sous plusieurs formes quand c'est demandé.","enonce":"Un sac contient **5 billes rouges**, **3 billes bleues** et **2 billes vertes**, indiscernables au toucher. On tire une bille au hasard.\n\n1. Combien y a-t-il d'issues possibles ?\n2. Calcule la probabilité de tirer une bille rouge, puis une bille verte. Écris chaque résultat sous forme de fraction irréductible, de nombre décimal et de pourcentage.\n3. Quel est l'événement contraire de « tirer une bille verte » ? Calcule sa probabilité de deux façons.\n4. Quelle est la probabilité de tirer une bille jaune ? Justifie.","bareme":[{"critere":"Nombre d'issues","points":3},{"critere":"Probabilités sous plusieurs écritures","points":7},{"critere":"Événement contraire","points":6},{"critere":"Événement impossible","points":4}],"dureeMin":11,"corrige":"**1.** 5 + 3 + 2 = **10 billes**, donc 10 issues possibles, toutes avec la même chance.\n\n**2.**\n- Rouge : P = 5/10 = **1/2 = 0,5 = 50 %**.\n- Verte : P = 2/10 = **1/5 = 0,2 = 20 %**.\n\n**3.** L'événement contraire est « **ne pas tirer une bille verte** » (tirer une bille rouge ou bleue).\n- Première façon : 5 + 3 = 8 cas favorables : P = 8/10 = **4/5**.\n- Deuxième façon : P(contraire) = 1 − P(verte) = 1 − 1/5 = **4/5** (soit 0,8 = 80 %).\n\n**4.** Il n'y a aucune bille jaune dans le sac : P = **0**, l'événement est impossible."}$exo$::jsonb),
  ('7c0536c3-5d68-5cfc-b877-7064e51a0fcf'::uuid, 3, 'probleme', $exo${"titre":"La roue de la kermesse","consigne":"Réponds à chaque question en justifiant par le calcul ou par une explication rédigée.","enonce":"À la kermesse, une roue est partagée en **8 secteurs égaux** numérotés de **1 à 8**. On fait tourner la roue et on note le numéro indiqué.\n\n1. Calcule la probabilité d'obtenir un nombre pair.\n2. Liste les nombres premiers compris entre 1 et 8, puis calcule la probabilité d'obtenir un nombre premier.\n3. Calcule la probabilité d'obtenir un multiple de 3, puis celle de l'événement contraire.\n4. Tim a obtenu un nombre pair **4 fois de suite**. Il dit : « Au prochain tour, j'ai plus de chances d'avoir un nombre impair. » Qu'en penses-tu ?\n5. Sur **20 tours**, le numéro 8 est sorti **7 fois**. Calcule la fréquence de sortie du 8 et compare-la à sa probabilité. La roue est-elle forcément truquée ? Explique.","bareme":[{"critere":"Probabilité d'un nombre pair","points":3},{"critere":"Nombres premiers et probabilité","points":4},{"critere":"Événement contraire","points":4},{"critere":"Indépendance des tours expliquée","points":4},{"critere":"Fréquence et probabilité comparées","points":5}],"dureeMin":18,"corrige":"Les 8 issues ont la même chance.\n\n**1.** Nombres pairs : 2, 4, 6, 8, soit 4 cas. P = 4/8 = **1/2**.\n\n**2.** Nombres premiers entre 1 et 8 : **2, 3, 5, 7** (1 n'est pas premier : il n'a qu'un seul diviseur). P = 4/8 = **1/2**.\n\n**3.** Multiples de 3 : 3 et 6, soit 2 cas. P = 2/8 = **1/4**.\nContraire (« ne pas obtenir un multiple de 3 ») : P = 1 − 1/4 = **3/4** (6 cas sur 8).\n\n**4.** Tim se trompe : la roue n'a pas de mémoire. Les tours précédents ne changent rien : au prochain tour, la probabilité d'obtenir un nombre impair reste **1/2**.\n\n**5.** Fréquence du 8 : 7 ÷ 20 = **0,35** (35 %). Probabilité : 1/8 = **0,125** (12,5 %).\nLa fréquence est bien plus grande que la probabilité, mais 20 tours, c'est peu : sur peu d'essais, la fréquence s'écarte souvent de la probabilité. On ne peut pas conclure que la roue est truquée ; il faudrait faire beaucoup plus de tours : la fréquence se rapprocherait alors de 0,125 si la roue est équilibrée."}$exo$::jsonb),
  ('beb5b557-794c-5051-802f-05a3546b457e'::uuid, 1, 'application', $exo${"titre":"À quoi sert cet objet ? Trouver la fonction d'usage","consigne":"Lis les questions et réponds par des phrases complètes. Pour la fonction d'usage, utilise un verbe à l'infinitif suivi d'un complément.","enonce":"1. Explique ce qu'est un **objet technique**. Dis pourquoi un caillou n'en est pas un, alors qu'un marteau en est un.\n\n2. Écris la **fonction d'usage** de chacun de ces objets :\n   - a) une paire de ciseaux ;\n   - b) un réveil ;\n   - c) une gourde ;\n   - d) un casque de vélo.\n\n3. Explique à quelle question répond la fonction d'usage.","bareme":[{"critere":"Définition de l'objet technique et exemple du caillou","points":6},{"critere":"Fonctions d'usage correctes pour les quatre objets","points":10},{"critere":"Question à laquelle répond la fonction d'usage","points":4}],"dureeMin":6,"corrige":"1. Un objet technique est un objet **fabriqué par l'humain** pour **répondre à un besoin**. Le caillou existe dans la nature, personne ne l'a fabriqué : ce n'est pas un objet technique. Le marteau a été fabriqué pour répondre à un besoin (enfoncer des clous) : c'est un objet technique.\n\n2. Réponses attendues (verbe à l'infinitif + complément ; d'autres formulations proches sont acceptées) :\n   - a) ciseaux : **Couper du papier** (ou couper une matière fine) ;\n   - b) réveil : **Réveiller une personne** à l'heure voulue ;\n   - c) gourde : **Transporter de l'eau** (contenir une boisson) ;\n   - d) casque de vélo : **Protéger la tête** du cycliste.\n\n3. La fonction d'usage répond à la question : **« À quoi ça sert ? »**. Elle explique pourquoi l'objet existe."}$exo$::jsonb),
  ('beb5b557-794c-5051-802f-05a3546b457e'::uuid, 2, 'application', $exo${"titre":"Deux gourdes au choix : fonction d'usage et fonction d'estime","consigne":"Étudie le tableau qui compare deux gourdes, puis réponds aux questions en justifiant avec le vocabulaire du cours.","enonce":"Léa doit acheter une gourde pour le collège. Au magasin, elle hésite entre deux modèles.\n\n| | Gourde A | Gourde B |\n|---|---|---|\n| Contenance | 50 cL | 50 cL |\n| Couleur | Grise | Violette avec des étoiles |\n| Marque | Sans marque | Marque connue |\n| Prix | 8 € | 15 € |\n| Forme | Cylindre simple | Forme arrondie, poignée |\n\n1. Écris la **fonction d'usage** commune aux deux gourdes.\n\n2. Relève dans le tableau les éléments qui relèvent de la **fonction d'estime**. Explique ce qu'est la fonction d'estime.\n\n3. Léa choisit finalement la gourde B, alors que les deux gourdes rendent le même service. Explique ce choix en utilisant les mots « fonction d'usage » et « fonction d'estime ».","bareme":[{"critere":"Fonction d'usage commune bien formulée","points":5},{"critere":"Éléments de la fonction d'estime relevés et définis","points":8},{"critere":"Explication du choix avec les deux notions","points":7}],"dureeMin":10,"corrige":"1. Les deux gourdes ont la même fonction d'usage : **Transporter de l'eau** (ou contenir une boisson). Elles ont d'ailleurs la même contenance (50 cL).\n\n2. La fonction d'estime, c'est ce qui fait **préférer un objet à un autre** alors qu'ils rendent le même service. Dans le tableau, relèvent de la fonction d'estime : la **couleur** (grise / violette avec des étoiles), la **marque** (sans marque / marque connue), le **prix** (8 € / 15 €) et la **forme** (cylindre simple / forme arrondie avec poignée). La contenance, elle, est identique et concerne le service rendu.\n\n3. Les deux gourdes ont la **même fonction d'usage** : elles servent toutes les deux à transporter de l'eau. La fonction d'usage explique pourquoi l'objet existe, mais pas pourquoi Léa choisit celle-là. Ce qui la fait choisir la gourde B, c'est la **fonction d'estime** : sa couleur, sa forme et sa marque lui plaisent davantage, même si elle coûte 7 € de plus (15 − 8 = 7)."}$exo$::jsonb),
  ('beb5b557-794c-5051-802f-05a3546b457e'::uuid, 3, 'application', $exo${"titre":"Concevoir une cuillère : besoin, cahier des charges et utilisateur","consigne":"Une entreprise veut créer une cuillère pour les bébés. Réponds à chaque question en justifiant avec les notions du cours.","enonce":"Une entreprise prépare une nouvelle cuillère destinée aux **bébés qui apprennent à manger seuls**.\n\n1. Quel **besoin** cette cuillère doit-elle satisfaire ? Explique pourquoi on dit que « le besoin précède toujours l'objet ».\n\n2. Propose une **contrainte** du cahier des charges pour chacune de ces catégories : dimensions et poids ; prix ; sécurité ; matériaux et durée de vie ; impact sur l'environnement.\n\n3. Un stagiaire a écrit dans le cahier des charges :\n> « La cuillère sera fabriquée en plastique moulé, avec un manche de 12 cm collé sur la tête. »\n\nExplique pourquoi cette phrase n'a pas sa place dans un cahier des charges, puis réécris-la sous la forme d'une vraie contrainte.\n\n4. Une autre équipe conçoit une cuillère pour une **personne qui n'a qu'une main valide**. Explique pourquoi les deux cuillères seront différentes alors que le besoin est le même.","bareme":[{"critere":"Besoin identifié et idée que le besoin précède l'objet","points":3},{"critere":"Contraintes adaptées pour les cinq catégories","points":6},{"critere":"Analyse de la phrase du stagiaire et réécriture","points":5},{"critere":"Lien entre l'utilisateur et la forme de l'objet","points":6}],"dureeMin":16,"corrige":"1. Le besoin : **porter la nourriture à la bouche** (manger) pour un bébé qui apprend à le faire seul. Le besoin de manger existait bien avant la cuillère : on n'a pas inventé la cuillère puis cherché à quoi elle servait. C'est pour cela que **le besoin précède toujours l'objet**.\n\n2. Exemples de contraintes (toute contrainte cohérente est acceptée) :\n   - dimensions et poids : la cuillère doit être **petite et légère** pour tenir dans la main d'un bébé et entrer dans sa bouche ;\n   - prix : elle doit coûter **peu cher** (par exemple moins de 5 €) ;\n   - sécurité : elle ne doit **pas blesser** (pas de bord coupant), ne pas pouvoir être avalée, ne contenir **aucun produit dangereux** ;\n   - matériaux et durée de vie : elle doit **supporter le lave-vaisselle** et être utilisable pendant plusieurs années ;\n   - environnement : elle doit être **recyclable** ou réutilisable longtemps.\n\n3. Le cahier des charges dit **ce que l'objet doit faire**, jamais **comment** le faire : c'est un contrat, pas une notice. Or la phrase du stagiaire impose déjà une solution (plastique moulé, manche collé). Réécriture possible : « La cuillère doit être légère, supporter le lave-vaisselle et ne pas se casser si le bébé la fait tomber ; le manche doit être assez long pour être tenu par une petite main. »\n\n4. Le besoin est le même (manger), mais **l'utilisateur** est différent. Le bébé a une petite main et une petite bouche : il lui faut une cuillère petite, douce, sans danger. La personne qui n'a qu'une main valide doit pouvoir manger sans tenir l'assiette : sa cuillère aura par exemple un manche épais facile à saisir ou une forme qui évite que la nourriture tombe. **Un même besoin appelle des objets différents selon qui s'en sert** : concevoir, c'est d'abord regarder l'utilisateur."}$exo$::jsonb),
  ('2d642a5c-891b-52bb-bcd8-ceca9ae91d98'::uuid, 1, 'application', $exo${"titre":"Le vélo : relier les organes à leur fonction technique","consigne":"Réponds aux questions sur le vélo en utilisant le vocabulaire du cours.","enonce":"Un vélo a pour fonction d'usage : **se déplacer**.\n\n1. Pour chacun des organes suivants, écris la **fonction technique** qu'il assure (transmettre le mouvement, diriger, freiner ou soutenir l'utilisateur) :\n   - a) la chaîne ;\n   - b) le guidon ;\n   - c) la selle ;\n   - d) les patins ;\n   - e) la fourche ;\n   - f) le pédalier.\n\n2. Explique la différence entre une **fonction d'usage** et une **fonction technique**.","bareme":[{"critere":"Fonctions techniques des six organes","points":12},{"critere":"Différence entre fonction d'usage et fonction technique","points":8}],"dureeMin":7,"corrige":"1. (2 points par organe)\n   - a) la chaîne : **transmettre le mouvement** ;\n   - b) le guidon : **diriger** ;\n   - c) la selle : **soutenir l'utilisateur** ;\n   - d) les patins : **freiner** ;\n   - e) la fourche : **diriger** ;\n   - f) le pédalier : **transmettre le mouvement**.\n\n2. La **fonction d'usage** dit **à quoi sert** l'objet (le vélo sert à se déplacer). Les **fonctions techniques** disent **comment** l'objet y parvient : pour permettre de se déplacer, le vélo doit transmettre le mouvement, se diriger, freiner et soutenir l'utilisateur."}$exo$::jsonb),
  ('2d642a5c-891b-52bb-bcd8-ceca9ae91d98'::uuid, 2, 'application', $exo${"titre":"La trottinette : de la fonction d'usage aux solutions","consigne":"Étudie la trottinette décrite ci-dessous et réponds aux questions en rédigeant.","enonce":"Voici la description d'une trottinette (sans moteur) :\n\n| L'organe | Sa description |\n|---|---|\n| Le guidon et la colonne | L'utilisateur les tourne pour changer de direction |\n| Le plateau | L'utilisateur pose ses pieds dessus |\n| Le garde-boue arrière | L'utilisateur appuie dessus avec le pied : il frotte sur la roue arrière |\n\n1. Écris la **fonction d'usage** de la trottinette.\n\n2. Pour chaque organe du tableau, écris la **fonction technique** qu'il assure.\n\n3. Le garde-boue qui frotte sur la roue est **une solution technique** pour freiner. Cite **deux autres solutions** possibles pour freiner, vues dans le cours. Explique pourquoi on dit qu'« il n'y a jamais une seule bonne solution ».\n\n4. Décris, en une ou deux phrases, comment on organise le **diagramme** qui relie la fonction d'usage, les fonctions techniques et les solutions.","bareme":[{"critere":"Fonction d'usage de la trottinette","points":3},{"critere":"Fonctions techniques des trois organes","points":7},{"critere":"Autres solutions pour freiner et justification","points":6},{"critere":"Organisation du diagramme","points":4}],"dureeMin":11,"corrige":"1. Fonction d'usage : **se déplacer**.\n\n2. \n   - le guidon et la colonne : **diriger** ;\n   - le plateau : **soutenir l'utilisateur** ;\n   - le garde-boue arrière : **freiner**.\n\n3. Autres solutions pour freiner : des **patins sur la jante**, un **frein à disque** (le rétropédalage est aussi accepté pour un vélo). Une fonction technique est un **problème à résoudre** ; une solution technique n'est **qu'une réponse parmi d'autres**. Le concepteur choisit la solution selon le **cahier des charges** (coût, poids, entretien, sécurité) : c'est pourquoi il n'y a jamais une seule bonne solution.\n\n4. Le diagramme se lit **en arbre, de haut en bas** : en haut la **fonction d'usage** (se déplacer), en dessous les **fonctions techniques** (diriger, freiner, soutenir), et tout en bas les **solutions retenues** (guidon, garde-boue, plateau)."}$exo$::jsonb),
  ('2d642a5c-891b-52bb-bcd8-ceca9ae91d98'::uuid, 3, 'application', $exo${"titre":"Chaîne ou courroie ? Choisir une solution pour des vélos de location","consigne":"Une ville équipe ses vélos de location. Utilise les données pour comparer deux solutions techniques, calcule et justifie ton choix.","enonce":"Une ville veut acheter **200 vélos** de location. Pour la fonction « transmettre le mouvement », elle hésite entre deux solutions. Voici les données du fournisseur :\n\n| Critère | Chaîne | Courroie |\n|---|---|---|\n| Prix pour un vélo | 15 € | 60 € |\n| Masse | 300 g | 150 g |\n| Entretien | À graisser chaque mois | Aucun graissage |\n| Réparation | Facile, pièces courantes | Difficile, il faut la remplacer entière |\n\nExtrait du **cahier des charges** : « Le budget pour la transmission des 200 vélos est de **10 000 €** au maximum. Les vélos doivent demander **peu d'entretien** et être **faciles à réparer**. »\n\n1. Explique la différence entre la **fonction technique** « transmettre le mouvement » et les **solutions techniques** proposées.\n\n2. Calcule le coût total de la transmission pour les 200 vélos avec chaque solution. Laquelle respecte le budget ?\n\n3. Compare les deux solutions critère par critère, puis choisis-en une pour la ville. Justifie ton choix avec le cahier des charges.\n\n4. Un coureur cycliste veut, lui, le vélo le plus **léger** possible et a un budget élevé. Choisirait-il la même solution ? Explique ce que cela montre.","bareme":[{"critere":"Distinction fonction technique et solution technique","points":4},{"critere":"Calcul des coûts et vérification du budget","points":5},{"critere":"Comparaison des critères et choix justifié","points":7},{"critere":"Analyse du cas du coureur cycliste","points":4}],"dureeMin":16,"corrige":"1. « Transmettre le mouvement » est une **fonction technique** : c'est un **problème à résoudre** (faire passer le mouvement des pédales à la roue). La chaîne et la courroie sont deux **solutions techniques** : deux réponses possibles à ce même problème (le cardan en est une troisième).\n\n2. Chaîne : 200 × 15 = **3 000 €**. Courroie : 200 × 60 = **12 000 €**. Le budget est de 10 000 € : **seule la chaîne respecte le budget** (12 000 € dépasse 10 000 € de 2 000 €).\n\n3. Comparaison :\n   - prix : la chaîne est 4 fois moins chère (60 ÷ 15 = 4) ;\n   - masse : la courroie est 2 fois plus légère (300 ÷ 150 = 2) ;\n   - entretien : la courroie gagne (aucun graissage) ;\n   - réparation : la chaîne gagne (facile, pièces courantes).\n\nChoix : **la chaîne**. La courroie demande moins d'entretien, mais elle **dépasse le budget** et elle est **difficile à réparer**, alors que le cahier des charges impose ces deux points. La chaîne demande un graissage mensuel, mais elle respecte le budget et se répare facilement. Le tableau de comparaison rend le choix **explicite**.\n\n4. Non : pour le coureur, le critère le plus important est la **masse** et le prix compte peu ; il choisirait plutôt la **courroie** (150 g au lieu de 300 g). Cela montre qu'**il n'y a jamais une seule bonne solution** : le choix dépend du **cahier des charges** et de l'utilisateur."}$exo$::jsonb),
  ('03bdc09b-46eb-5ca6-a7a3-6b8af8a1d49c'::uuid, 1, 'application', $exo${"titre":"La lignée de l'éclairage : ce qui change, ce qui reste","consigne":"Réponds aux questions sur l'évolution des objets d'éclairage en rédigeant des phrases complètes.","enonce":"1. Remets ces objets d'éclairage dans l'**ordre chronologique**, du plus ancien au plus récent :\n\n> lampe à incandescence · bougie · LED · feu · bec de gaz · lampe à huile · lampe fluocompacte\n\n2. Tout au long de cette évolution, qu'est-ce qui **n'a pas changé** ? Qu'est-ce qui **a changé** ? Utilise les mots « fonction d'usage » et « solutions techniques ».\n\n3. Explique la différence entre une **famille** d'objets et une **lignée** d'objets.","bareme":[{"critere":"Ordre chronologique des objets d'éclairage","points":8},{"critere":"Ce qui reste et ce qui change","points":6},{"critere":"Différence entre famille et lignée","points":6}],"dureeMin":7,"corrige":"1. Ordre : **feu → bougie → lampe à huile → bec de gaz → lampe à incandescence → lampe fluocompacte → LED**.\n\n2. Ce qui n'a pas changé, c'est la **fonction d'usage** : **éclairer**. Ce qui a changé, ce sont les **solutions techniques** utilisées pour produire la lumière (flamme, gaz, filament, LED…). À chaque étape, on a obtenu plus de lumière, avec moins d'énergie et moins de danger.\n\n3. Une **famille** regroupe les objets qui remplissent la **même fonction d'usage à une même époque** (par exemple aujourd'hui : la lampe de bureau, la lampe torche, le lampadaire). Une **lignée**, c'est **un objet suivi à travers le temps** (par exemple la lampe, de la bougie à la LED)."}$exo$::jsonb),
  ('03bdc09b-46eb-5ca6-a7a3-6b8af8a1d49c'::uuid, 2, 'application', $exo${"titre":"De l'ampoule à filament à la LED : calculer l'économie","consigne":"Utilise les données pour calculer la consommation des deux lampes, puis explique ce qui a poussé cette évolution.","enonce":"Dans le salon de Noah, une ampoule à filament consomme **7,2 kWh** d'énergie par mois. On rappelle qu'une LED consomme environ **dix fois moins** qu'une ampoule à filament, pour le même éclairage.\n\n1. Calcule l'énergie consommée **en un mois** par une LED qui éclaire autant.\n\n2. Calcule l'énergie consommée **en un an** (12 mois) par chaque lampe, puis l'**économie** réalisée en un an grâce à la LED.\n\n3. Lis ce document :\n> « Une loi européenne a interdit la vente des ampoules à filament classiques, car elles gaspillaient trop d'énergie. »\n\nQuel **moteur de l'évolution** ce document illustre-t-il ? Cite un **autre moteur** qui a permis l'arrivée de la LED et explique-le.","bareme":[{"critere":"Consommation mensuelle de la LED","points":5},{"critere":"Consommations annuelles et économie","points":7},{"critere":"Moteurs de l'évolution identifiés et expliqués","points":6},{"critere":"Rédaction et unités","points":2}],"dureeMin":10,"corrige":"1. La LED consomme dix fois moins : 7,2 ÷ 10 = **0,72 kWh par mois**.\n\n2. En un an :\n   - ampoule à filament : 7,2 × 12 = **86,4 kWh** ;\n   - LED : 0,72 × 12 = **8,64 kWh** ;\n   - économie : 86,4 − 8,64 = **77,76 kWh** par an.\n\n3. Ce document illustre le moteur **« la société »** : une **loi** (une norme) oblige à changer d'objet, pour des raisons de préoccupation environnementale (économiser l'énergie).\nAutre moteur : les **progrès techniques** — l'électronique a permis de fabriquer des LED qui donnent autant de lumière avec beaucoup moins d'énergie. (On accepte aussi l'**économie** : produire des lampes moins chères en grande quantité, ou les **besoins** qui changent.)\n\nLes résultats doivent être accompagnés de leur unité (kWh)."}$exo$::jsonb),
  ('03bdc09b-46eb-5ca6-a7a3-6b8af8a1d49c'::uuid, 3, 'application', $exo${"titre":"Vélo d'hier, vélo électrique d'aujourd'hui : le progrès est-il automatique ?","consigne":"Compare les deux vélos du document, puis réponds aux questions en justifiant avec les notions du cours.","enonce":"Document : deux vélos de la même lignée.\n\n| Critère | Vélo classique (années 1990) | Vélo à assistance électrique (aujourd'hui) |\n|---|---|---|\n| Masse | 14 kg | 24 kg |\n| Vitesse moyenne en ville | 15 km/h | 20 km/h |\n| Effort pour monter une côte | Important | Faible |\n| Réparation | Pièces standard, réparable à la maison | Batterie et moteur à faire changer par un spécialiste |\n| Matériaux | Acier, caoutchouc | Aluminium, cuivre, lithium, électronique |\n\n1. Ces deux vélos ont-ils la même **fonction d'usage** ? Explique pourquoi on dit qu'ils appartiennent à la même **lignée**.\n\n2. Cite **deux moteurs de l'évolution** qui expliquent l'apparition du vélo électrique. Appuie-toi sur le document.\n\n3. Montre, avec au moins **trois critères** du document, que le vélo récent **n'est pas meilleur sur tous les critères**.\n\n4. Explique ce qu'est l'**analyse du cycle de vie**, cite ses quatre étapes, et dis pourquoi elle est utile pour juger ces deux vélos.","bareme":[{"critere":"Fonction d'usage identique et notion de lignée","points":4},{"critere":"Deux moteurs de l'évolution justifiés","points":5},{"critere":"Comparaison critère par critère des deux vélos","points":6},{"critere":"Analyse du cycle de vie et son intérêt","points":5}],"dureeMin":15,"corrige":"1. Oui, les deux vélos ont la même fonction d'usage : **se déplacer**. Ils appartiennent à la même **lignée** car c'est le même objet, le vélo, **suivi à travers le temps** : la fonction d'usage reste, ce sont les solutions techniques qui changent.\n\n2. Moteurs possibles :\n   - les **progrès techniques** : nouveaux matériaux (aluminium), nouvelles énergies (batterie au lithium), électronique ;\n   - les **besoins qui changent** : aller plus vite (20 km/h au lieu de 15 km/h), plus loin, plus confortablement (effort faible dans les côtes).\n(La société, avec les préoccupations environnementales qui poussent à remplacer la voiture, est aussi acceptée.)\n\n3. Le vélo électrique est meilleur pour la **vitesse** (20 contre 15 km/h) et l'**effort** (faible). Mais il est moins bon pour :\n   - la **masse** : 24 kg contre 14 kg, soit 10 kg de plus ;\n   - la **réparation** : batterie et moteur à faire changer par un spécialiste, alors que le vélo classique se répare à la maison ;\n   - les **matériaux** : il dépend de matériaux rares ou coûteux à produire (lithium, électronique).\nUn objet plus récent **n'est donc pas meilleur sur tous les critères**.\n\n4. L'analyse du cycle de vie étudie l'objet **de sa naissance à sa fin** : **extraction** des matières, **fabrication**, **usage**, **fin de vie**. Elle est utile ici car le vélo électrique semble plus pratique à l'usage, mais sa batterie demande l'extraction de lithium et sa fin de vie est plus compliquée. Regarder tout le cycle de vie permet de juger les deux vélos honnêtement, et pas seulement sur leur vitesse."}$exo$::jsonb),
  ('14f83a33-63c3-5829-b7bb-89bffb4ae51f'::uuid, 1, 'application', $exo${"titre":"Ranger les matériaux dans leur famille","consigne":"Classe chaque matériau dans sa famille, puis définis deux propriétés des matériaux.","enonce":"1. Range chacun de ces matériaux dans sa **famille** (métaux, plastiques, céramiques et verres, matériaux organiques, composites) :\n\n> acier · verre · bois · fibre de carbone · plastique d'une bouteille d'eau · cuivre · papier · béton armé\n\n2. Explique ce que signifient ces deux propriétés :\n   - a) la **dureté** ;\n   - b) l'**élasticité**.","bareme":[{"critere":"Classement des huit matériaux","points":12},{"critere":"Définitions de la dureté et de l'élasticité","points":8}],"dureeMin":7,"corrige":"1. (1,5 point par matériau)\n   - **métaux** : acier, cuivre ;\n   - **plastiques** : plastique de la bouteille d'eau ;\n   - **céramiques et verres** : verre ;\n   - **matériaux organiques** : bois, papier ;\n   - **composites** : fibre de carbone, béton armé.\n\n2. \n   - a) La **dureté** : le matériau **résiste à la rayure**.\n   - b) L'**élasticité** : le matériau **reprend sa forme** après avoir été déformé."}$exo$::jsonb),
  ('14f83a33-63c3-5829-b7bb-89bffb4ae51f'::uuid, 2, 'application', $exo${"titre":"La casserole et le cadre de vélo : choisir selon les propriétés","consigne":"Réponds aux questions en utilisant les propriétés des matériaux et les données du tableau.","enonce":"1. Une casserole a un **corps en métal** et un **manche en plastique**. Explique ce choix en utilisant le mot « conductivité ».\n\n2. On pèse trois petits blocs qui ont tous le **même volume : 10 cm³**.\n\n| Le bloc | Sa masse |\n|---|---|\n| Aluminium | 27 g |\n| Acier | 78 g |\n| Plastique | 9 g |\n\n   - a) Calcule la masse de **1 cm³** de chaque matériau.\n   - b) Quelle propriété compare-t-on ainsi ? Range les trois matériaux du plus léger au plus lourd à volume égal.\n\n3. Un fabricant hésite entre l'aluminium et l'acier pour le **cadre d'un vélo** qui doit être léger et résistant. Lequel conseilles-tu ? Justifie.\n\n4. L'aluminium est très recyclable. Est-il pour autant un matériau bon marché à produire ? Explique.","bareme":[{"critere":"Explication du choix des matériaux de la casserole","points":5},{"critere":"Calculs et comparaison des masses volumiques","points":6},{"critere":"Choix justifié du matériau du cadre","points":5},{"critere":"Coût de production de l'aluminium","points":4}],"dureeMin":11,"corrige":"1. Le **métal conduit la chaleur** : le corps de la casserole transmet bien la chaleur de la plaque aux aliments. Le **plastique isole** : le manche ne chauffe pas et on peut le tenir sans se brûler. Ce sont deux matériaux dans un même objet, chacun pour une raison précise et opposée.\n\n2. a) On divise la masse par 10 :\n   - aluminium : 27 ÷ 10 = **2,7 g** pour 1 cm³ ;\n   - acier : 78 ÷ 10 = **7,8 g** pour 1 cm³ ;\n   - plastique : 9 ÷ 10 = **0,9 g** pour 1 cm³.\n\nb) On compare la **masse volumique** (léger ou lourd à volume égal). Du plus léger au plus lourd : **plastique (0,9 g) → aluminium (2,7 g) → acier (7,8 g)**.\n\n3. On conseille l'**aluminium** : c'est un métal, donc **résistant**, et il est presque **3 fois plus léger** que l'acier à volume égal (7,8 ÷ 2,7 ≈ 2,9). Le plastique est plus léger, mais moins résistant pour un cadre.\n\n4. Non. L'aluminium se recycle très bien, mais sa **production initiale consomme énormément d'électricité**. Un matériau recyclable n'est pas forcément bon marché à produire."}$exo$::jsonb),
  ('14f83a33-63c3-5829-b7bb-89bffb4ae51f'::uuid, 3, 'application', $exo${"titre":"Verre, plastique ou métal : quelle gourde pour le collège ?","consigne":"Compare trois matériaux possibles pour une gourde, choisis-en un et justifie avec leurs propriétés, leurs limites et leur recyclage.","enonce":"Un fabricant veut créer une gourde pour les collégiens. Extrait du cahier des charges :\n> « La gourde voyage dans un sac à dos : elle peut tomber. Elle doit être assez légère, durer plusieurs années et avoir un faible impact sur l'environnement. »\n\nTrois matériaux sont envisagés : le **verre**, le **plastique** et l'**acier inoxydable** (un métal).\n\n1. Pour chacun des trois matériaux, indique sa **famille**, **une qualité** et **une limite**, d'après le cours.\n\n2. Quel matériau choisis-tu pour cette gourde ? Justifie avec **au moins deux propriétés** et le cahier des charges. Explique pourquoi tu écartes les deux autres.\n\n3. Au bout de plusieurs années, la gourde est jetée dans la bonne poubelle. Compare ce que deviennent le **verre**, le **métal** et le **plastique** au recyclage.\n\n4. Explique la phrase du cours : « On ne choisit pas un matériau parce qu'il est meilleur, mais parce que ses propriétés correspondent aux contraintes. »","bareme":[{"critere":"Famille, qualité et limite des trois matériaux","points":5},{"critere":"Choix argumenté avec les propriétés et les contraintes","points":6},{"critere":"Comparaison du recyclage des trois matériaux","points":5},{"critere":"Explication de la phrase du cours","points":4}],"dureeMin":15,"corrige":"1. \n   - **Verre** : famille des céramiques et verres ; qualité : dur, résiste à la chaleur ; limite : **fragile**, il casse net.\n   - **Plastique** : famille des plastiques ; qualité : léger, facile à mouler, peu cher ; limite : **issu du pétrole**, long à se dégrader.\n   - **Acier inoxydable** : famille des métaux ; qualité : **résistant**, recyclable à l'infini ; limite : souvent plus **lourd**.\n\n2. Choix attendu : **l'acier inoxydable**. Il est **résistant** : il supporte une chute sans casser. Il **résiste à la corrosion** (à l'eau) et dure longtemps. Il est **recyclable à l'infini**, ce qui limite l'impact. Il est un peu plus lourd, mais une gourde reste un petit objet.\nOn écarte le **verre** car il est fragile : il casserait en tombant du sac. On écarte le **plastique** car, même s'il est léger, il vient du pétrole et se recycle mal.\n(Un autre choix est accepté s'il est justifié par des propriétés et les contraintes.)\n\n3. Le **verre** et le **métal** se recyclent **presque indéfiniment**. Le **plastique** se **dégrade à chaque cycle** de recyclage et finit par sortir de la boucle.\n\n4. Aucun matériau n'est le meilleur partout : le verre est dur mais fragile, le plastique léger mais issu du pétrole, le métal résistant mais lourd. On choisit donc le matériau dont les **propriétés** répondent aux **contraintes** de l'objet (ici : résister aux chutes, durer, peu polluer)."}$exo$::jsonb),
  ('6fb7180b-9054-5ddb-9a94-721619109053'::uuid, 1, 'application', $exo${"titre":"Le cycle de vie et les leviers pour réduire l'impact","consigne":"Réponds aux questions sur l'impact environnemental des objets en rédigeant des phrases complètes.","enonce":"1. Remets dans l'ordre les **cinq étapes du cycle de vie** d'un objet :\n\n> utilisation · fabrication · fin de vie · extraction · transport\n\n2. Classe ces leviers du **plus efficace** au **moins efficace** pour réduire l'impact d'un objet :\n\n> recycler · ne pas produire l'objet · valoriser · allonger sa durée de vie · réemployer\n\n3. Explique ce qu'est l'**obsolescence** et donne un exemple.","bareme":[{"critere":"Ordre des étapes du cycle de vie","points":6},{"critere":"Classement des cinq leviers","points":8},{"critere":"Définition de l'obsolescence et exemple","points":6}],"dureeMin":7,"corrige":"1. **Extraction → fabrication → transport → utilisation → fin de vie**.\n\n2. Du plus efficace au moins efficace :\n   1. **ne pas produire** l'objet (s'en passer, le partager, le louer) ;\n   2. **allonger sa durée de vie** (entretenir, réparer, revendre) ;\n   3. **réemployer** (seconde vie sans transformation) ;\n   4. **recycler** (refaire de la matière) ;\n   5. **valoriser** (incinérer en récupérant la chaleur).\n\n3. L'**obsolescence**, c'est quand un objet **cesse d'être utilisé alors qu'il fonctionne encore**. Exemples : un téléphone dont le logiciel ne se met plus à jour ; un appareil dont les pièces de rechange ne sont plus vendues ; un vêtement qu'on ne porte plus parce qu'il n'est plus à la mode."}$exo$::jsonb),
  ('6fb7180b-9054-5ddb-9a94-721619109053'::uuid, 2, 'application', $exo${"titre":"Tom veut changer de smartphone : quel geste est le plus utile ?","consigne":"Lis la situation, classe chaque option parmi les leviers du cours et calcule pour justifier la meilleure décision.","enonce":"Tom a un smartphone depuis 2 ans. Il fonctionne bien, mais Tom a envie d'un nouveau modèle. Il hésite entre trois options :\n\n- **Option A** : il achète un téléphone neuf et dépose l'ancien dans un bac de **recyclage** ;\n- **Option B** : il **change la batterie** et garde son téléphone **deux ans de plus** ;\n- **Option C** : il achète un téléphone neuf et **donne** l'ancien à sa sœur, qui l'utilise tel quel.\n\n1. Pour un smartphone, quelle étape du cycle de vie pèse le plus lourd dans l'impact ?\n\n2. À quel **levier** correspond chaque option ?\n\n3. Sur une période de **12 ans**, combien de smartphones Tom utilisera-t-il s'il en change tous les **2 ans** ? Et s'il en change tous les **4 ans** ? Compare.\n\n4. Quelle option est la meilleure pour l'environnement ? Justifie avec tes réponses précédentes.","bareme":[{"critere":"Étape dominante pour le smartphone","points":4},{"critere":"Levier correspondant à chaque option","points":6},{"critere":"Calcul du nombre de smartphones","points":5},{"critere":"Choix justifié de la meilleure option","points":5}],"dureeMin":11,"corrige":"1. Pour un smartphone, c'est la **fabrication** qui domine l'impact.\n\n2. \n   - Option A : **recycler** (4e levier) ;\n   - Option B : **allonger la durée de vie** (2e levier) ;\n   - Option C : **réemployer** (3e levier) — le téléphone a une seconde vie sans transformation.\n\n3. Tous les 2 ans : 12 ÷ 2 = **6 smartphones**. Tous les 4 ans : 12 ÷ 4 = **3 smartphones**. En gardant chaque téléphone deux ans de plus, Tom utilise **deux fois moins** de smartphones, donc il en fait fabriquer deux fois moins.\n\n4. La meilleure option est l'**option B**. Comme la fabrication est l'étape qui pèse le plus, le geste le plus utile est d'éviter d'en fabriquer un nouveau : garder son téléphone deux ans de plus. Allonger la durée de vie est le 2e levier, plus efficace que le réemploi (3e) et que le recyclage (4e), qui n'est pas le premier levier."}$exo$::jsonb),
  ('6fb7180b-9054-5ddb-9a94-721619109053'::uuid, 3, 'application', $exo${"titre":"Réduire l'impact d'une famille : là où il se trouve vraiment","consigne":"Analyse les situations et le document, puis réponds en justifiant avec le cycle de vie, les leviers et l'écoconception.","enonce":"La famille Martin veut réduire l'impact environnemental de ses appareils.\n\n1. Le père propose : « Débranchons le chargeur du smartphone dès qu'il est chargé. » La mère propose : « Pour le nouveau réfrigérateur, choisissons un modèle qui consomme peu. » Pour chaque appareil, indique **l'étape du cycle de vie qui domine**, puis dis quelle proposition a le plus d'effet et pourquoi.\n\n2. La famille doit aussi acheter une bouilloire.\n\n| | Bouilloire A | Bouilloire B |\n|---|---|---|\n| Assemblage | Coque collée | Coque vissée |\n| Pièces détachées | Non vendues | Disponibles |\n| Indice de réparabilité | 3 sur 10 | 8 sur 10 |\n\nQuelle bouilloire respecte le mieux les principes de l'**écoconception** ? Cite deux principes qu'elle applique.\n\n3. Depuis quelle année l'**indice de réparabilité** est-il obligatoire en France ? Explique en quoi il aide à lutter contre l'**obsolescence**.\n\n4. Le fils affirme : « Pour protéger la planète, le plus important, c'est de bien recycler. » Es-tu d'accord ? Argumente avec l'ordre des leviers.","bareme":[{"critere":"Étapes dominantes et proposition la plus efficace","points":5},{"critere":"Choix de la bouilloire et principes d'écoconception","points":5},{"critere":"Indice de réparabilité et obsolescence","points":4},{"critere":"Argumentation sur l'ordre des leviers","points":6}],"dureeMin":17,"corrige":"1. Pour le **smartphone**, l'étape qui domine est la **fabrication** : débrancher le chargeur ne change presque rien. Pour le **réfrigérateur**, l'étape qui domine est l'**utilisation**, pendant une quinzaine d'années : choisir un modèle qui consomme peu (bon rendement) a donc un vrai effet. La proposition de la **mère** a le plus d'effet. L'impact n'est pas toujours là où on le croit : il faut savoir où il se trouve avant de vouloir le réduire.\n\n2. La **bouilloire B** respecte le mieux l'écoconception. Principes appliqués : un **assemblage démontable** (vis plutôt que colle) et des **pièces détachées disponibles**. On peut donc la réparer au lieu de la jeter.\n\n3. L'indice de réparabilité est obligatoire en France depuis **2021**. Il indique, par une note sur 10, si l'objet est facile à réparer. En choisissant un objet bien noté, on peut le réparer quand il tombe en panne au lieu de le remplacer : on évite qu'il cesse d'être utilisé faute de pièces ou de réparation possible.\n\n4. Pas tout à fait d'accord. Recycler est **utile**, mais c'est seulement le **4e levier**, et il est **coûteux en énergie**. Les leviers plus efficaces sont, dans l'ordre : **ne pas produire** l'objet (s'en passer, le partager, le louer), **allonger sa durée de vie** (entretenir, réparer, revendre), puis **réemployer**. Le plus important est donc d'abord de moins acheter et de garder ses objets plus longtemps ; le recyclage vient après."}$exo$::jsonb),
  ('a4015043-2efc-542d-99ab-508226b73e2c'::uuid, 1, 'application', $exo${"titre":"Chaîne d'information ou chaîne d'énergie ?","consigne":"Classe chaque composant dans la bonne chaîne et la bonne étape, puis explique la comparaison du cours.","enonce":"1. Pour chacun de ces composants, indique s'il appartient à la **chaîne d'information** ou à la **chaîne d'énergie**, et à quelle **étape** (acquérir, traiter, communiquer, alimenter, distribuer, convertir, transmettre) :\n   - a) un capteur de température ;\n   - b) une pile ;\n   - c) un moteur ;\n   - d) une carte programmable ;\n   - e) un interrupteur ;\n   - f) des engrenages ;\n   - g) un écran.\n\n2. Le cours dit : « Le capteur est l'oreille, le microcontrôleur le cerveau, l'actionneur le muscle. » Explique cette comparaison.","bareme":[{"critere":"Chaîne et étape des sept composants","points":14},{"critere":"Explication de la comparaison oreille, cerveau, muscle","points":6}],"dureeMin":7,"corrige":"1. (2 points par composant)\n   - a) capteur de température : chaîne d'**information**, **acquérir** ;\n   - b) pile : chaîne d'**énergie**, **alimenter** ;\n   - c) moteur : chaîne d'**énergie**, **convertir** (c'est un actionneur) ;\n   - d) carte programmable : chaîne d'**information**, **traiter** ;\n   - e) interrupteur : chaîne d'**énergie**, **distribuer** ;\n   - f) engrenages : chaîne d'**énergie**, **transmettre** ;\n   - g) écran : chaîne d'**information**, **communiquer**.\n\n2. Le **capteur** est comme l'oreille : il **perçoit** ce qui se passe (il transforme une grandeur physique en signal). Le **microcontrôleur** est comme le cerveau : il **décide** selon le programme. L'**actionneur** est comme le muscle : il **agit** en convertissant l'énergie (mouvement, lumière, chaleur, son)."}$exo$::jsonb),
  ('a4015043-2efc-542d-99ab-508226b73e2c'::uuid, 2, 'application', $exo${"titre":"Le ventilateur automatique : décrire ses deux chaînes","consigne":"Étudie le fonctionnement du ventilateur automatique, puis décris ses deux chaînes étape par étape.","enonce":"Un ventilateur automatique se met en marche tout seul quand il fait trop chaud dans la chambre. Il comporte :\n\n- un **capteur de température** ;\n- une **carte programmable** ;\n- un **voyant lumineux** qui s'allume quand le ventilateur tourne ;\n- un **branchement sur le secteur** ;\n- un **relais** ;\n- un **moteur** ;\n- les **pales** (l'hélice), fixées sur l'axe du moteur.\n\n1. Écris la **fonction d'usage** de cet objet.\n\n2. Décris la **chaîne d'information** : pour chaque étape (acquérir, traiter, communiquer), donne le composant et son rôle.\n\n3. Décris la **chaîne d'énergie** : pour chaque étape (alimenter, distribuer, convertir, transmettre), donne le composant et son rôle.\n\n4. Le moteur est l'**actionneur**. Explique ce qu'il convertit.","bareme":[{"critere":"Fonction d'usage du ventilateur","points":3},{"critere":"Chaîne d'information complète","points":6},{"critere":"Chaîne d'énergie complète","points":7},{"critere":"Rôle de conversion de l'actionneur","points":4}],"dureeMin":11,"corrige":"1. Fonction d'usage : **rafraîchir l'air de la chambre** (ventiler une pièce).\n\n2. Chaîne d'information :\n   - **acquérir** : le **capteur de température** mesure la température et la transforme en signal ;\n   - **traiter** : la **carte programmable** décide, selon le programme, s'il fait trop chaud ;\n   - **communiquer** : la carte envoie l'ordre vers la chaîne d'énergie (le relais) et le **voyant lumineux** informe l'utilisateur.\n\n3. Chaîne d'énergie :\n   - **alimenter** : le **secteur** fournit l'énergie ;\n   - **distribuer** : le **relais** laisse passer ou non le courant vers le moteur ;\n   - **convertir** : le **moteur** transforme l'énergie électrique en mouvement ;\n   - **transmettre** : l'axe et les **pales** portent le mouvement jusqu'à l'air.\n\n4. Le moteur convertit l'**énergie électrique** en **mouvement** (rotation), qui fait tourner les pales."}$exo$::jsonb),
  ('a4015043-2efc-542d-99ab-508226b73e2c'::uuid, 3, 'application', $exo${"titre":"Panne d'un éclairage automatique : chercher dans la bonne chaîne","consigne":"Analyse les deux pannes de l'éclairage automatique, trouve dans quelle chaîne se trouve chaque problème et justifie.","enonce":"Dans le couloir d'un collège, un éclairage automatique fonctionne ainsi :\n\n> capteur de présence → carte programmable → relais → lampe (alimentation : secteur)\n\nLe capteur possède un petit **témoin lumineux** qui s'allume quand il détecte quelqu'un.\n\n1. Classe chaque composant (capteur de présence, carte programmable, relais, lampe, secteur) dans sa **chaîne** et à son **étape**.\n\n2. Le technicien observe deux pannes, à deux jours différents :\n   - **Panne 1** : un élève passe, le témoin du capteur **reste éteint** et la lampe ne s'allume pas. Le technicien branche la lampe directement sur le secteur : **elle s'allume**.\n   - **Panne 2** : un élève passe, le témoin du capteur **s'allume**, la carte envoie bien l'ordre, mais la lampe ne s'allume pas. Le technicien constate que le **disjoncteur est coupé**.\n\nPour chaque panne, dis dans quelle **chaîne** se trouve le problème et justifie avec les observations.\n\n3. Explique pourquoi on dit que « distinguer les deux chaînes, c'est diviser le problème en deux ».\n\n4. Le collège veut que la lampe **ne s'allume pas en plein jour**. Quel composant faut-il ajouter ? Dans quelle chaîne et à quelle étape ? Qu'est-ce qui doit changer dans la carte ?","bareme":[{"critere":"Classement des composants dans les deux chaînes","points":5},{"critere":"Diagnostic justifié des deux pannes","points":6},{"critere":"Intérêt de séparer les deux chaînes","points":4},{"critere":"Amélioration proposée et chaîne concernée","points":5}],"dureeMin":16,"corrige":"1. \n   - capteur de présence : chaîne d'**information**, **acquérir** ;\n   - carte programmable : chaîne d'**information**, **traiter** ;\n   - relais : chaîne d'**énergie**, **distribuer** ;\n   - lampe : chaîne d'**énergie**, **convertir** (actionneur : électricité → lumière) ;\n   - secteur : chaîne d'**énergie**, **alimenter**.\n\n2. **Panne 1** : problème dans la chaîne d'**information**. Le témoin reste éteint : le capteur n'a rien détecté. Et la lampe s'allume quand on la branche directement : la lampe et l'alimentation fonctionnent. Le capteur « n'a rien vu ».\n**Panne 2** : problème dans la chaîne d'**énergie**. Le capteur a détecté l'élève et la carte a envoyé l'ordre : l'information circule. Mais le disjoncteur coupé empêche l'**alimentation** : l'énergie n'arrive pas à la lampe.\n\n3. Les pannes **ne se cherchent pas au même endroit**. Quand la lampe ne s'allume pas, soit le capteur n'a rien vu (information), soit l'alimentation est coupée (énergie). En vérifiant d'abord de quelle chaîne vient le problème, le technicien élimine la moitié des causes possibles.\n\n4. Il faut ajouter un **capteur de luminosité**. Il appartient à la chaîne d'**information**, à l'étape **acquérir**. Le **programme** de la carte doit être modifié : elle n'allume la lampe que si une présence est détectée **et** s'il fait sombre."}$exo$::jsonb),
  ('88c473ff-8210-5cb9-96f7-77dd8c1bfb61'::uuid, 1, 'application', $exo${"titre":"Les briques d'un programme et les symboles de l'organigramme","consigne":"Réponds aux questions sur la programmation en utilisant le vocabulaire du cours.","enonce":"1. Explique en une phrase ce qu'est chacune de ces briques de programme :\n   - a) une **instruction** ;\n   - b) une **boucle** ;\n   - c) une **condition** ;\n   - d) une **variable**.\n\n2. Voici un programme :\n> répéter indéfiniment : si le capteur de présence est activé, alors allumer la lampe et attendre 30 s ; sinon éteindre la lampe\n\nRelève la **boucle** et la **condition**. Explique ce que permet la condition.\n\n3. Dans un **organigramme**, que représentent le **rectangle**, le **losange** et la **flèche** ?","bareme":[{"critere":"Définition des quatre briques","points":8},{"critere":"Boucle et condition repérées dans le programme","points":6},{"critere":"Symboles de l'organigramme","points":6}],"dureeMin":7,"corrige":"1. \n   - a) Une **instruction** est une **action simple** : allumer, attendre, lire un capteur.\n   - b) Une **boucle** permet de **répéter** des instructions sans les réécrire.\n   - c) Une **condition** (si … alors … sinon …) permet de choisir une action selon une situation.\n   - d) Une **variable** est une **case mémoire nommée** (un compteur, une mesure).\n\n2. La boucle : **« répéter indéfiniment »**. La condition : **« si le capteur de présence est activé, alors … sinon … »**. La condition rend l'objet capable de **réagir** : il allume la lampe seulement quand quelqu'un est détecté.\n\n3. Le **rectangle** représente une **action** ; le **losange** une **décision** ; la **flèche** l'**ordre d'exécution**."}$exo$::jsonb),
  ('88c473ff-8210-5cb9-96f7-77dd8c1bfb61'::uuid, 2, 'application', $exo${"titre":"Un compteur de visiteurs : lire et analyser un programme","consigne":"Lis attentivement le programme, puis réponds aux questions en expliquant ton raisonnement.","enonce":"Pour compter les visiteurs d'une exposition au CDI, des élèves ont écrit ce programme :\n\n```\nmettre compteur à 0\nrépéter indéfiniment :\n    si le capteur de présence est activé alors\n        ajouter 1 à compteur\n        afficher compteur\n        attendre 2 s\n```\n\n1. Dans ce programme, relève la **variable**, la **boucle** et la **condition**.\n\n2. Le programme démarre, puis **5 visiteurs** passent l'un après l'autre devant le capteur, à plusieurs secondes d'intervalle. Quel nombre s'affiche à la fin ? Explique.\n\n3. Un élève supprime l'instruction « attendre 2 s ». Un visiteur reste alors **immobile 3 secondes** devant le capteur. Que risque-t-il de se passer ? Explique pourquoi.\n\n4. On veut représenter ce programme par un **organigramme**. Indique quelles étapes seront dans un **rectangle** et laquelle sera dans un **losange**. Justifie.","bareme":[{"critere":"Variable, boucle et condition repérées","points":4},{"critere":"Valeur affichée après cinq visiteurs","points":5},{"critere":"Analyse de la suppression de l'attente","points":6},{"critere":"Symboles de l'organigramme justifiés","points":5}],"dureeMin":12,"corrige":"1. Variable : **compteur**. Boucle : **répéter indéfiniment**. Condition : **si le capteur de présence est activé alors**.\n\n2. Le compteur part de **0**. À chaque visiteur, la condition est vraie et on ajoute 1 : 0 + 1 + 1 + 1 + 1 + 1 = **5**. L'écran affiche **5**.\n\n3. Sans l'attente, la boucle se répète **très vite**. Tant que le visiteur reste devant le capteur, celui-ci est activé à chaque tour de boucle, donc le programme ajoute 1 **à chaque tour** : un seul visiteur sera compté **beaucoup de fois**. La machine exécute exactement ce qui est écrit : le programme « a raison », c'est l'intention qui n'était pas assez précise. L'attente de 2 s servait à ne compter qu'une fois chaque passage.\n\n4. Dans des **rectangles** (actions) : « mettre compteur à 0 », « ajouter 1 à compteur », « afficher compteur », « attendre 2 s ». Dans un **losange** (décision) : « le capteur de présence est-il activé ? », car c'est une question avec deux sorties (oui / non). Les **flèches** indiquent l'ordre et le retour au début de la boucle."}$exo$::jsonb),
  ('88c473ff-8210-5cb9-96f7-77dd8c1bfb61'::uuid, 3, 'application', $exo${"titre":"Déboguer une veilleuse automatique et la connecter","consigne":"Trouve l'erreur dans le programme de la veilleuse, corrige-la et analyse les conséquences d'en faire un objet connecté.","enonce":"Une veilleuse doit **s'allumer quand il fait sombre** (luminosité **inférieure à 30**) et **s'éteindre sinon**. Voici le programme écrit par Sami :\n\n```\nrépéter indéfiniment :\n    lire la luminosité\n    si luminosité > 30 alors\n        allumer la lampe\n    sinon\n        éteindre la lampe\n```\n\n1. Que fait **réellement** ce programme quand la luminosité vaut **80** (en plein jour) ? Et quand elle vaut **10** (la nuit) ?\n\n2. Isole l'**instruction fautive** et écris la version corrigée.\n\n3. Sami dit : « La carte s'est trompée ! » Explique pourquoi c'est faux, en utilisant la phrase du cours sur le programme et l'intention.\n\n4. Cite la **variable** de ce programme et explique pourquoi elle change à chaque tour de boucle.\n\n5. Sami modifie sa veilleuse pour qu'elle envoie chaque soir ses mesures à une application sur Internet. Comment appelle-t-on ce type d'objet ? Quelles **questions** cela pose-t-il ?","bareme":[{"critere":"Comportement réel du programme pour les deux valeurs","points":5},{"critere":"Instruction fautive isolée et corrigée","points":5},{"critere":"Explication du bug avec l'idée d'intention","points":3},{"critere":"Rôle de la variable dans la boucle","points":3},{"critere":"Objet connecté et questions soulevées","points":4}],"dureeMin":18,"corrige":"1. Luminosité **80** : 80 > 30 est **vrai**, donc la lampe **s'allume** en plein jour. Luminosité **10** : 10 > 30 est **faux**, donc on passe au « sinon » : la lampe **s'éteint** la nuit. La veilleuse fait **exactement l'inverse** de ce qu'on veut.\n\n2. L'instruction fautive est la condition **« si luminosité > 30 »**. Correction :\n```\nsi luminosité < 30 alors\n    allumer la lampe\nsinon\n    éteindre la lampe\n```\n(Autre correction acceptée : garder « > 30 » et échanger « allumer » et « éteindre ».)\n\n3. Une machine **n'interprète pas** : elle exécute exactement ce qui est écrit. La carte a appliqué correctement l'instruction « > 30 ». Quand le résultat surprend, c'est presque toujours **le programme qui a raison** et **l'intention qui était floue** (ou mal écrite). Le bug est une étape normale : tester → isoler l'instruction fautive → corriger → retester.\n\n4. La variable est **luminosité** : c'est une case mémoire qui contient la mesure du capteur. À chaque tour de boucle, l'instruction « lire la luminosité » remplace l'ancienne valeur par la nouvelle mesure, car la lumière de la pièce change.\n\n5. C'est un **objet connecté** : la carte envoie ses mesures sur un réseau. Cela pose des questions de **sécurité** et de **données personnelles** : **qui reçoit** ces mesures, et **pour en faire quoi** ? (Par exemple, les heures d'allumage révèlent quand la famille est à la maison ou dort.)"}$exo$::jsonb),
  ('b9efad07-39af-5d74-9261-8dbbd463217b'::uuid, 1, 'application', $exo${"titre":"Bits, octets et supports de transmission","consigne":"Réponds aux questions sur l'information numérique. Détaille tes calculs.","enonce":"1. Explique ce qu'est le **binaire**.\n\n2. On rappelle que **1 octet = 8 bits**.\n   - a) Combien de bits y a-t-il dans **3 octets** ?\n   - b) Combien d'octets y a-t-il dans **40 bits** ?\n\n3. Pour chaque support de transmission, indique **sous quelle forme** voyage l'information :\n   - a) le câble électrique ;\n   - b) le wifi ;\n   - c) la fibre optique.","bareme":[{"critere":"Définition du binaire","points":5},{"critere":"Conversions entre bits et octets","points":8},{"critere":"Forme de l'information pour les trois supports","points":7}],"dureeMin":7,"corrige":"1. Le **binaire** est un code qui n'utilise que **deux états : 0 et 1**. Les textes, images, sons et mesures sont convertis en 0 et 1 pour être transmis, puis reconvertis à l'arrivée.\n\n2. \n   - a) 3 × 8 = **24 bits**.\n   - b) 40 ÷ 8 = **5 octets**.\n\n3. \n   - a) câble électrique : sous forme de **courant électrique** ;\n   - b) wifi : sous forme d'**ondes**, sans fil, dans l'air ;\n   - c) fibre optique : sous forme de **lumière**, dans un fil de verre."}$exo$::jsonb),
  ('b9efad07-39af-5d74-9261-8dbbd463217b'::uuid, 2, 'application', $exo${"titre":"Photos sur une carte SD et message envoyé par Internet","consigne":"Réponds aux questions en détaillant tes calculs et en utilisant le vocabulaire du cours.","enonce":"Données : **1 octet = 8 bits** ; pour simplifier, on prend **1 Go = 1 000 Mo**.\n\n1. Un court message texte occupe **12 octets**. Combien de **bits** faut-il transmettre ?\n\n2. Emma a une carte SD de **32 Go**. Chaque photo de son téléphone pèse **4 Mo**.\n   - a) Convertis 32 Go en Mo.\n   - b) Combien de photos peut-elle stocker au maximum sur la carte vide ?\n\n3. Emma envoie une photo à un ami par Internet. Explique comment les données voyagent : parle des **paquets** et de l'**adresse IP**.\n\n4. Emma range aussi ses photos dans le « cloud ». Où sont-elles réellement stockées ?","bareme":[{"critere":"Conversion du message en bits","points":4},{"critere":"Calcul du nombre de photos","points":6},{"critere":"Circulation par paquets et adresse IP","points":6},{"critere":"Réalité matérielle du cloud","points":4}],"dureeMin":12,"corrige":"1. 12 × 8 = **96 bits**.\n\n2. \n   - a) 32 × 1 000 = **32 000 Mo**.\n   - b) 32 000 ÷ 4 = **8 000 photos** au maximum.\n\n3. La photo est convertie en **0 et 1**. Les données sont **découpées en paquets** ; **chaque paquet emprunte son propre chemin** sur le réseau Internet ; les paquets sont **réassemblés à l'arrivée** pour reformer la photo. Chaque machine du réseau possède une **adresse IP**, ce qui permet d'envoyer les paquets vers le bon destinataire.\n\n4. Le « cloud » n'a rien d'immatériel : les photos sont stockées sur un **serveur distant**, c'est-à-dire **l'ordinateur de quelqu'un d'autre**, dans un **centre de données** bien réel, qui consomme de l'électricité."}$exo$::jsonb),
  ('b9efad07-39af-5d74-9261-8dbbd463217b'::uuid, 3, 'application', $exo${"titre":"Le voyage d'une vidéo : transmission, stockage et prudence","consigne":"Suis le trajet de la vidéo d'Inès, fais les calculs demandés et analyse les risques en justifiant avec le cours.","enonce":"Inès filme l'anniversaire de sa petite sœur. La vidéo pèse **2 Go**. Elle l'envoie à sa grand-mère par Internet, la range dans un service de « cloud », et publie une photo de la fête sur un réseau social, en public.\n\nDonnées : on prend **1 Go = 1 000 Mo**.\n\n1. Décris le trajet de la vidéo, depuis le téléphone d'Inès (relié à la box en **wifi**) jusqu'à la grand-mère (sa maison est reliée à Internet par la **fibre optique**). Utilise les mots : **binaire**, **ondes**, **lumière**, **réseau**, **adresse IP**.\n\n2. Pour simplifier, on imagine que la vidéo est découpée en paquets de **25 Mo** chacun. Calcule le nombre de paquets. Que se passe-t-il pour ces paquets pendant le trajet et à l'arrivée ?\n\n3. Un camarade dit : « Dans le cloud, ma vidéo ne prend de place nulle part et ne pollue pas. » Explique pourquoi il a tort.\n\n4. Cite **trois gestes** de sécurité du cours. Puis explique le risque de la photo publiée en public.","bareme":[{"critere":"Trajet de la vidéo avec le vocabulaire demandé","points":5},{"critere":"Calcul du nombre de paquets et leur circulation","points":4},{"critere":"Critique de l'idée d'un cloud immatériel","points":5},{"critere":"Gestes de sécurité et risque de la publication","points":6}],"dureeMin":17,"corrige":"1. La vidéo est convertie en **binaire** (des 0 et des 1). Le téléphone l'envoie à la box sous forme d'**ondes** (wifi), sans fil. Elle circule ensuite sur le **réseau** Internet, le réseau des réseaux, jusqu'à la maison de la grand-mère où elle arrive par la **fibre optique**, sous forme de **lumière** dans un fil de verre. Chaque machine possède une **adresse IP**, qui permet d'acheminer les données vers le bon ordinateur. À l'arrivée, les 0 et 1 sont reconvertis en vidéo.\n\n2. 2 Go = 2 × 1 000 = 2 000 Mo. Nombre de paquets : 2 000 ÷ 25 = **80 paquets**. Pendant le trajet, **chaque paquet emprunte son propre chemin** ; à l'arrivée, les 80 paquets sont **réassemblés** pour reformer la vidéo.\n\n3. Le « cloud », c'est **l'ordinateur de quelqu'un d'autre** : la vidéo est stockée sur un **serveur distant**, dans un **centre de données bien réel** (un bâtiment climatisé plein de machines). Elle prend donc de la place sur un disque, et ces machines **consomment de l'électricité** en permanence.\n\n4. Gestes : utiliser un **mot de passe solide** ; faire les **mises à jour** ; être **prudent sur ce qu'on publie**.\nRisque : une donnée transmise peut être **copiée**, **conservée** et **rediffusée** sans qu'on le sache. La photo publiée en public (avec la petite sœur) **échappe vite à son auteur** : Inès ne peut plus contrôler qui la voit ni ce qu'on en fait."}$exo$::jsonb),
  ('aa23b9a5-3ea4-5f87-9ea0-bed7365ca6f2'::uuid, 1, 'application', $exo${"titre":"Croquis, schéma ou plan ? Et que signifie l'échelle ?","consigne":"Réponds aux questions sur les dessins techniques en rédigeant des phrases complètes.","enonce":"1. Pour chaque situation, indique s'il faut un **croquis**, un **schéma** ou un **plan**, et explique pourquoi :\n   - a) Lina veut montrer rapidement à son groupe son idée de boîte à crayons.\n   - b) Le professeur veut expliquer comment la pile, l'interrupteur et la lampe sont reliés dans une lampe de poche.\n   - c) L'atelier doit fabriquer la boîte avec les bonnes dimensions.\n\n2. Explique ce que signifient les échelles **1:1**, **1:10** et **10:1**.\n\n3. On veut dessiner une vis très petite pour bien voir ses détails. Quelle échelle choisis-tu parmi les trois ? Justifie.","bareme":[{"critere":"Type de dessin adapté à chaque situation","points":8},{"critere":"Signification des trois échelles","points":7},{"critere":"Choix justifié de l'échelle pour la vis","points":5}],"dureeMin":7,"corrige":"1. \n   - a) Un **croquis** : il montre une **idée**, à main levée, sans échelle exacte.\n   - b) Un **schéma** : il montre le **fonctionnement** et les liaisons, avec des **symboles normalisés** ; il ne ressemble pas à l'objet.\n   - c) Un **plan** (dessin technique) : il montre comment **fabriquer**, à l'**échelle** et **coté**.\n\n2. \n   - **1:1** : le dessin est à la **taille réelle** ;\n   - **1:10** : le dessin est **10 fois plus petit** que l'objet ;\n   - **10:1** : le dessin est **10 fois plus grand** que l'objet.\n\n3. On choisit **10:1** : le dessin sera 10 fois plus grand que la vis, ce qui permet de voir ses petits détails. Cette échelle sert justement pour les petites pièces."}$exo$::jsonb),
  ('aa23b9a5-3ea4-5f87-9ea0-bed7365ca6f2'::uuid, 2, 'application', $exo${"titre":"Lire les cotes et appliquer l'échelle d'un plan","consigne":"Utilise l'échelle et les cotes pour répondre. Détaille tes calculs et indique les unités.","enonce":"1. Sur le plan d'une table dessiné à l'échelle **1:10**, la cote de la longueur du plateau indique **800**.\n   - a) Quelle est la longueur **réelle** du plateau ? Donne l'unité.\n   - b) Quelle longueur mesure ce plateau **sur le dessin** ?\n\n2. Sur le plan d'une petite pièce dessinée à l'échelle **10:1**, la cote d'un trou indique **6**.\n   - a) Quel est le diamètre réel du trou ?\n   - b) Combien mesure ce trou sur le dessin ?\n\n3. Tom a photocopié le plan de la table en le réduisant. Il mesure le plateau sur sa copie avec une règle pour connaître sa longueur. Explique pourquoi c'est une erreur et ce qu'il aurait dû faire.\n\n4. Dans quelle **unité** les cotes sont-elles indiquées ? Dépendent-elles de l'échelle du dessin ?","bareme":[{"critere":"Longueurs réelle et dessinée du plateau","points":6},{"critere":"Dimensions réelle et dessinée du trou","points":6},{"critere":"Explication de l'erreur de Tom","points":5},{"critere":"Unité et indépendance des cotes","points":3}],"dureeMin":10,"corrige":"1. \n   - a) Les cotes indiquent les dimensions **réelles** en millimètres : le plateau mesure **800 mm** (soit 80 cm).\n   - b) À l'échelle 1:10, le dessin est 10 fois plus petit : 800 ÷ 10 = **80 mm** sur le dessin (8 cm).\n\n2. \n   - a) La cote donne la dimension réelle : le trou mesure **6 mm**.\n   - b) À l'échelle 10:1, le dessin est 10 fois plus grand : 6 × 10 = **60 mm** sur le dessin.\n\n3. Sur une photocopie réduite, le dessin n'est plus à l'échelle 1:10 : la mesure à la règle donnera une valeur fausse. Même sur le plan d'origine, **on ne mesure jamais sur le papier : on lit la cote**. Tom aurait dû **lire la cote 800** : le plateau mesure 800 mm.\n\n4. Les cotes sont en **millimètres**. Elles indiquent les dimensions **réelles**, **quelle que soit l'échelle** du dessin : elles ne dépendent pas de l'échelle."}$exo$::jsonb),
  ('aa23b9a5-3ea4-5f87-9ea0-bed7365ca6f2'::uuid, 3, 'application', $exo${"titre":"Du croquis à la fabrication d'un support de téléphone","consigne":"Suis le projet d'un groupe d'élèves et justifie chaque choix de dessin, d'échelle et d'outil avec le cours.","enonce":"Un groupe d'élèves conçoit un **support de téléphone** pliant. Il mesure **150 mm** de long et contient une petite vis de **3 mm** de diamètre.\n\n1. Le projet passe par trois moments :\n   - a) les élèves partagent leurs premières idées ;\n   - b) ils expliquent au professeur comment la partie pliante tourne autour de la vis ;\n   - c) ils envoient le dessin à l'atelier pour la fabrication.\nPour chaque moment, dis quel dessin utiliser et justifie.\n\n2. Un élève envoie à l'atelier un joli dessin en **perspective**, sans cotes. L'atelier le refuse. Explique pourquoi, et dis ce que l'atelier attend.\n\n3. Le support doit être dessiné sur une feuille A4 (297 mm de long).\n   - a) À l'échelle **1:1**, quelle longueur aura le support sur le dessin ? Tient-il sur la feuille ?\n   - b) À l'échelle **1:10**, quelle longueur aurait-il ? Pourquoi est-ce un mauvais choix ici ?\n   - c) Pour un dessin de détail de la vis à l'échelle **10:1**, quelle serait la taille du diamètre sur le dessin ?\n\n4. Donne deux avantages de la **CAO** pour ce projet.","bareme":[{"critere":"Choix du dessin pour chaque moment du projet","points":5},{"critere":"Limites de la perspective et vues attendues","points":5},{"critere":"Calculs et choix des échelles","points":6},{"critere":"Avantages de la CAO","points":4}],"dureeMin":16,"corrige":"1. \n   - a) Un **croquis** : à main levée, il sert à montrer une **idée** rapidement.\n   - b) Un **schéma** : il montre le **fonctionnement** (la rotation autour de la vis) avec des symboles, sans ressembler à l'objet.\n   - c) Un **plan** : à l'**échelle** et **coté**, il dit **comment fabriquer**.\n\n2. La **perspective** donne une idée du volume, mais **ne permet pas de mesurer** : ce n'est pas un dessin de fabrication. De plus, sans **cotes**, l'atelier ne connaît pas les dimensions réelles. L'atelier attend un plan avec les **trois vues** (vue de face, vue de dessus, vue de gauche), qui décrivent l'objet **sans ambiguïté**, et les **cotes en millimètres**.\n\n3. \n   - a) À 1:1, le dessin a la taille réelle : **150 mm**. 150 mm < 297 mm : **il tient sur la feuille**.\n   - b) À 1:10 : 150 ÷ 10 = **15 mm**. C'est trop petit : on ne verrait pas les détails, alors que le support tient déjà à taille réelle.\n   - c) À 10:1 : 3 × 10 = **30 mm** sur le dessin.\n\n4. La CAO permet de **dessiner en 3D**, de **tester le support avant de le fabriquer** (par exemple vérifier le pliage), et d'**envoyer le fichier directement** à une imprimante 3D ou à une découpeuse. (Deux avantages suffisent.)"}$exo$::jsonb),
  ('b83df816-835e-5261-8888-e3668a808edc'::uuid, 1, 'application', $exo${"titre":"Les étapes de fabrication et les types d'assemblage","consigne":"Réponds aux questions sur la fabrication d'un objet en rédigeant des phrases complètes.","enonce":"1. Remets dans l'ordre les grandes opérations de la **gamme de fabrication** :\n\n> assembler · finir · mesurer et tracer · contrôler · découper · percer, usiner, poncer\n\n2. Classe ces moyens d'assemblage en **démontables** ou **permanents** :\n\n> vis · colle · soudure · clips · boulon · rivet\n\nDonne une conséquence de chaque type d'assemblage.\n\n3. Cite **deux consignes de sécurité** à respecter dans l'atelier.","bareme":[{"critere":"Ordre de la gamme de fabrication","points":7},{"critere":"Classement des assemblages et conséquences","points":8},{"critere":"Consignes de sécurité","points":5}],"dureeMin":7,"corrige":"1. **Mesurer et tracer → découper → percer, usiner, poncer → assembler → contrôler → finir**.\n\n2. \n   - **Démontables** : vis, clips, boulon. Conséquence : on peut **réparer** l'objet et le **recycler** plus facilement.\n   - **Permanents** : colle, soudure, rivet. Conséquence : l'assemblage est **plus solide**, mais l'objet est **difficile à réparer**.\n\n3. Consignes possibles (deux suffisent) : porter des **lunettes** ; porter des **gants** ; **attacher ses cheveux** ; **arrêter la machine avant tout réglage** ; **un seul opérateur à la fois** sur une machine."}$exo$::jsonb),
  ('b83df816-835e-5261-8888-e3668a808edc'::uuid, 2, 'application', $exo${"titre":"Contrôle qualité : accepter ou refuser les pièces","consigne":"Utilise la cote et la tolérance pour décider si chaque pièce est acceptée ou refusée. Justifie chaque décision.","enonce":"Un atelier fabrique des baguettes en bois. Sur le plan, la longueur est cotée **80 mm**, avec une **tolérance de 1 mm** en plus ou en moins.\n\n1. Explique ce qu'est la **tolérance**. Entre quelles longueurs une baguette est-elle acceptée (limites comprises) ?\n\n2. Voici les longueurs mesurées sur cinq baguettes :\n\n| Baguette | A | B | C | D | E |\n|---|---|---|---|---|---|\n| Longueur mesurée | 80,5 mm | 78,6 mm | 81 mm | 81,4 mm | 79,2 mm |\n\nPour chaque baguette, dis si elle est **acceptée** ou **refusée** et justifie.\n\n3. Avec quel **instrument** mesure-t-on précisément ces longueurs ?\n\n4. À quel moment de la gamme de fabrication se fait ce contrôle ? Cite deux autres choses que l'on vérifie lors du contrôle qualité.","bareme":[{"critere":"Définition de la tolérance et limites calculées","points":4},{"critere":"Décision justifiée pour les cinq baguettes","points":8},{"critere":"Instrument de mesure adapté","points":3},{"critere":"Place du contrôle et autres vérifications","points":5}],"dureeMin":11,"corrige":"1. La **tolérance** est l'**écart acceptable autour de la cote**. Limites : 80 − 1 = **79 mm** et 80 + 1 = **81 mm**. Une baguette est acceptée si sa longueur est comprise entre 79 mm et 81 mm.\n\n2. \n   - A (80,5 mm) : entre 79 et 81 → **acceptée** ;\n   - B (78,6 mm) : plus petite que 79 mm → **refusée** (0,4 mm trop courte) ;\n   - C (81 mm) : égale à la limite 81 mm, limites comprises → **acceptée** ;\n   - D (81,4 mm) : plus grande que 81 mm → **refusée** (0,4 mm trop longue) ;\n   - E (79,2 mm) : entre 79 et 81 → **acceptée**.\nBilan : 3 baguettes acceptées (A, C, E), 2 refusées (B, D). Une pièce hors tolérance est refusée.\n\n3. On utilise un **pied à coulisse** (un gabarit est aussi accepté).\n\n4. Le contrôle se fait **après l'assemblage et avant la finition** (on vérifie que la pièce est conforme au plan). On vérifie aussi l'**aspect** (à l'œil) et le **fonctionnement** (en essai)."}$exo$::jsonb),
  ('b83df816-835e-5261-8888-e3668a808edc'::uuid, 3, 'application', $exo${"titre":"Fabriquer une série de boîtes en bois : du prototype à la série","consigne":"Organise la fabrication d'une série de boîtes, fais les calculs demandés et justifie tes choix avec le cours.","enonce":"La classe de 6e veut fabriquer **25 boîtes en bois** pour la kermesse. Chaque boîte a un couvercle fixé par **4 vis**. Avant la série, les élèves fabriquent **1 prototype**, identique aux boîtes.\n\n1. Écris la **gamme de fabrication** d'une boîte, étape par étape, en citant un outil ou un moyen pour au moins trois étapes.\n\n2. Un élève propose de **coller** le couvercle au lieu de le visser, « pour aller plus vite ». Explique ce que ce choix change pour la **durée de vie** de la boîte.\n\n3. \n   - a) À quoi sert le **prototype** ? Qu'est-ce qui permettra ensuite d'obtenir des boîtes **identiques** ?\n   - b) Les vis sont vendues par boîtes de **50**. Combien de vis faut-il au total (prototype compris) ? Combien de boîtes de vis faut-il acheter ?\n\n4. Cite **trois vérifications** du contrôle qualité et l'outil ou le moyen utilisé pour chacune.\n\n5. Au moment de percer les trous des vis, cite **deux consignes de sécurité** et explique pourquoi elles ne sont pas des formalités.","bareme":[{"critere":"Gamme de fabrication ordonnée avec outils","points":5},{"critere":"Conséquence du choix colle ou vis","points":4},{"critere":"Rôle du prototype et calcul des vis","points":4},{"critere":"Vérifications du contrôle qualité","points":4},{"critere":"Consignes de sécurité justifiées","points":3}],"dureeMin":18,"corrige":"1. Gamme de fabrication :\n   1. **mesurer et tracer** : reporter les cotes du plan sur la planche (règle, crayon) ;\n   2. **découper** : scie ou découpeuse laser ;\n   3. **percer, usiner, poncer** : perceuse pour les trous des vis, papier de verre ;\n   4. **assembler** : fixer le couvercle avec les vis (visseuse, tournevis) ;\n   5. **contrôler** : vérifier que la boîte est conforme au plan ;\n   6. **finir** : vernis ou peinture pour protéger le bois.\n\n2. La colle est un assemblage **permanent** : plus solide, mais **difficile à réparer**. Choisir la colle, c'est décider **dès la conception** que la boîte ne sera jamais réparée (on ne pourra pas démonter le couvercle abîmé). Les vis sont **démontables** : on peut réparer et recycler. Ce n'est pas un détail : c'est un **choix de durée de vie**.\n\n3. \n   - a) Le **prototype** est le premier exemplaire : il sert à **tester et corriger** les défauts avant de lancer la série. Pour la **série**, on utilise des **outillages** (gabarits…) qui rendent chaque pièce **identique**.\n   - b) Nombre de boîtes : 25 + 1 = 26. Nombre de vis : 26 × 4 = **104 vis**. 2 boîtes de vis = 100 vis, ce n'est pas assez ; il faut donc **3 boîtes de vis** (150 vis).\n\n4. \n   - les **dimensions** : avec un **pied à coulisse** ou un **gabarit** (la pièce doit être dans la tolérance) ;\n   - l'**aspect** : **à l'œil** ;\n   - le **fonctionnement** : **en essai** (le couvercle se ferme bien).\n\n5. Consignes (deux suffisent) : porter des **lunettes** ; **attacher ses cheveux** ; **arrêter la machine avant tout réglage** ; **un seul opérateur à la fois**. Ce ne sont pas des formalités car les machines de l'atelier **coupent, percent et chauffent** : un copeau dans l'œil ou des cheveux pris dans la perceuse provoquent des blessures graves."}$exo$::jsonb),
  ('e66a476a-caba-50e4-8ec3-d3dd433616c3'::uuid, 1, 'traduction', $exo${"titre":"Les pronoms personnels : trois phrases à traduire","consigne":"Traduis ces trois phrases du français vers l'anglais (thème). Fais attention au choix du pronom sujet ou complément.","enonce":"**Thème : traduis en anglais.**\n\n1. Il pleut.\n2. Je la connais.\n3. Les livres ? Ils sont sur la table.","bareme":[{"critere":"Choix des pronoms sujets (it, they, I)","points":8},{"critere":"Pronom complément placé après le verbe","points":6},{"critere":"Orthographe et ponctuation","points":6}],"dureeMin":6,"corrige":"**Traduction modèle**\n\n1. *It's raining.* (ou *It is raining.*)\n2. *I know her.*\n3. *The books? They are on the table.* (ou *They're on the table.*)\n\n**Points attendus**\n- Phrase 1 : « il pleut » ne désigne personne, mais l'anglais exige un sujet : *it*.\n- Phrase 2 : *I* toujours en majuscule ; « la » (une personne, féminin) est complément → *her*, placé **après** le verbe (ordre sujet → verbe → complément). « I her know » est faux.\n- Phrase 3 : *they* remplace tous les pluriels, même des objets. Pas de « it » ni de « them » en position sujet."}$exo$::jsonb),
  ('e66a476a-caba-50e4-8ec3-d3dd433616c3'::uuid, 2, 'traduction', $exo${"titre":"La lettre de Tom : traduire les pronoms en français","consigne":"Traduis le petit texte de l'anglais vers le français (version), puis réponds à la question 2.","enonce":"**1. Version : traduis ce texte en français.**\n\n> Hi! I have a sister, Lucy. She is ten. I love her and she loves me. We have two cats. They are black. My dad plays with them every day. It's cold today and it's snowing.\n\n*Aide : to snow = neiger ; cold = froid.*\n\n**2.** Dans la dernière phrase, explique en une ou deux phrases à quoi sert le mot *it*.","bareme":[{"critere":"Traduction des pronoms sujets et compléments","points":8},{"critere":"Sens général et vocabulaire","points":6},{"critere":"Explication du rôle de it","points":3},{"critere":"Orthographe et ponctuation en français","points":3}],"dureeMin":10,"corrige":"**1. Traduction modèle**\n\n- *Hi! I have a sister, Lucy.* → Salut ! J'ai une sœur, Lucy.\n- *She is ten.* → Elle a dix ans.\n- *I love her and she loves me.* → Je l'aime et elle m'aime.\n- *We have two cats. They are black.* → Nous avons deux chats. Ils sont noirs. (« On a deux chats » accepté.)\n- *My dad plays with them every day.* → Mon père joue avec eux tous les jours. (« Mon papa » accepté.)\n- *It's cold today and it's snowing.* → Il fait froid aujourd'hui et il neige.\n\nPoints attendus : *her* (complément) → « l' » ; *me* → « m' » ; *them* après la préposition *with* → « eux » ; *they* désigne ici des animaux → « ils ». Attention : *She is ten* se traduit par « elle a dix ans » (pas « elle est dix »).\n\n**2.** *It* sert de sujet pour parler du temps qu'il fait. « Il fait froid », « il neige » ne parlent de personne, mais en anglais une phrase doit toujours avoir un sujet : on emploie donc *it*, qui se traduit par « il »."}$exo$::jsonb),
  ('e66a476a-caba-50e4-8ec3-d3dd433616c3'::uuid, 3, 'traduction', $exo${"titre":"Une matinée avant l'école : pronoms, it et they","consigne":"Traduis les six phrases du français vers l'anglais (thème), puis justifie tes choix de pronoms à la question 2.","enonce":"**1. Thème : traduis en anglais.**\n\n1. Il est 7 heures et il pleut.\n2. Mon école ? Elle est à 3 km.\n3. Mes chaussures ? Elles sont sous le lit.\n4. Ma mère me donne un sandwich.\n5. Je le donne à mon ami Sam.\n6. Il l'aime !\n\n*Aide : shoes = chaussures ; under = sous ; to give = donner.*\n\n**2.** Aux phrases 2 et 3, le français dit « elle » et « elles ». Explique quels pronoms tu as choisis en anglais et pourquoi.","bareme":[{"critere":"Pronoms sujets, dont it et they pour les choses","points":6},{"critere":"Pronoms compléments et leur place","points":5},{"critere":"Ordre sujet-verbe-complément","points":3},{"critere":"Justification des choix de pronoms","points":4},{"critere":"Orthographe (I majuscule) et ponctuation","points":2}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n1. *It's 7 o'clock and it's raining.* (ou *It is 7 o'clock and it is raining.*)\n2. *My school? It's 3 km away.* (*It's 3 km.* ou *It is 3 km from here.* acceptés)\n3. *My shoes? They are under the bed.*\n4. *My mother gives me a sandwich.* (*My mum* accepté)\n5. *I give it to my friend Sam.*\n6. *He likes it!* (*He loves it!* accepté)\n\nPoints attendus :\n- *it* pour l'heure, le temps qu'il fait et la distance (phrase 1 et 2).\n- *me* complément après le verbe (phrase 4), *it* complément après le verbe et *to my friend* après (phrase 5) : on ne dit jamais « I it give ».\n- Phrase 6 : « il » = Sam → *he* ; « l' » = le sandwich (une chose) → *it*, placé après le verbe.\n- *I* en majuscule ; *gives*, *likes* avec -s à la 3e personne.\n\n**2. Justification**\nEn anglais, les choses n'ont pas de genre : on ne dit pas *she* pour une école. Une chose au singulier se reprend par *it* (« mon école » → *it*). Au pluriel, *they* remplace tous les pluriels, personnes ou objets (« mes chaussures » → *they*)."}$exo$::jsonb),
  ('b4426e48-7529-5c04-8715-4088b05f6888'::uuid, 1, 'traduction', $exo${"titre":"Trois questions fermées à traduire","consigne":"Traduis ces trois questions du français vers l'anglais (thème). Choisis bien ce que tu places devant le sujet.","enonce":"**Thème : traduis en anglais.**\n\n1. Est-ce que tu es content ?\n2. Est-ce que tu sais nager ?\n3. Est-ce que tu aimes la pizza ?\n\n*Aide : happy = content ; to swim = nager.*","bareme":[{"critere":"Choix de l'auxiliaire (be, can, do)","points":10},{"critere":"Ordre auxiliaire-sujet-verbe","points":6},{"critere":"Orthographe et point d'interrogation","points":4}],"dureeMin":6,"corrige":"**Traduction modèle**\n\n1. *Are you happy?*\n2. *Can you swim?*\n3. *Do you like pizza?*\n\n**Points attendus**\n- Phrase 1 : le verbe est *be* : on le place lui-même devant le sujet (*Are you…*).\n- Phrase 2 : « savoir nager » = *can swim* ; le modal *can* passe devant le sujet.\n- Phrase 3 : *like* n'est ni *be* ni un modal : on appelle *do* (*Do you like…*). Pas d'article devant *pizza* (goût en général).\n- « Est-ce que » ne se traduit pas mot à mot. Point d'interrogation collé à la fin."}$exo$::jsonb),
  ('b4426e48-7529-5c04-8715-4088b05f6888'::uuid, 2, 'traduction', $exo${"titre":"Interroger un nouvel élève","consigne":"Un nouvel élève anglais arrive dans ta classe. Traduis tes questions du français vers l'anglais (thème), avec la réponse courte quand elle est demandée.","enonce":"**Thème : traduis en anglais.**\n\n1. Où habites-tu ?\n2. Quel âge as-tu ?\n3. Est-ce que ta sœur joue au tennis ? — Oui. *(Traduis aussi la réponse courte.)*\n4. Pourquoi est-elle triste ?\n5. Qui habite ici ?\n\n*Aide : sad = triste ; to live = habiter ; here = ici.*","bareme":[{"critere":"Mots interrogatifs et How old","points":5},{"critere":"Auxiliaire : choix et place","points":7},{"critere":"Réponse courte et question sur le sujet","points":5},{"critere":"Orthographe et ponctuation","points":3}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n1. *Where do you live?*\n2. *How old are you?*\n3. *Does your sister play tennis? — Yes, she does.*\n4. *Why is she sad?*\n5. *Who lives here?*\n\n**Points attendus**\n- Ordre : mot interrogatif → auxiliaire → sujet → verbe. Le mot interrogatif ne remplace pas l'auxiliaire : « Where you live? » est faux.\n- Phrase 2 : l'âge se dit avec *be* : *How old are you?* (et non « How old do you have? »).\n- Phrase 3 : *does* à la 3e personne, puis la base verbale *play* (pas « plays »). Pas d'article devant *tennis*. La réponse courte reprend l'auxiliaire : *Yes, she does.*\n- Phrase 4 : verbe *be* → *is* passe devant *she*.\n- Phrase 5 : *who* est le sujet → pas d'auxiliaire : *Who lives here?* et non « Who does live here? »."}$exo$::jsonb),
  ('b4426e48-7529-5c04-8715-4088b05f6888'::uuid, 3, 'traduction', $exo${"titre":"Comprendre et corriger des questions en anglais","consigne":"Traduis les cinq questions de l'anglais vers le français (version), puis corrige les trois questions fausses en justifiant chaque correction.","enonce":"**1. Version : traduis en français.**\n\n1. *Why did he leave?*\n2. *What is she doing?*\n3. *How much is it?*\n4. *Which bike do you want?*\n5. *Can your brother swim? — No, he can't.*\n\n*Aide : to leave = partir ; bike = vélo ; to want = vouloir.*\n\n**2.** Ces trois questions contiennent une erreur. Réécris-les correctement et explique chaque fois la règle.\n\n- a) « Where you live? »\n- b) « Who does live here? »\n- c) « Does he plays football? »","bareme":[{"critere":"Version : sens des mots interrogatifs","points":6},{"critere":"Version : français correct et naturel","points":4},{"critere":"Correction des questions fautives","points":6},{"critere":"Justification des corrections","points":4}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n1. Pourquoi est-il parti ? (« Pourquoi il est parti ? » accepté à l'oral)\n2. Qu'est-ce qu'elle fait ? / Que fait-elle ?\n3. Combien ça coûte ? / C'est combien ?\n4. Quel vélo veux-tu ? / Lequel des vélos veux-tu ? (*which* = lequel, quel, parmi un choix)\n5. Est-ce que ton frère sait nager ? — Non. (« Non, il ne sait pas. » accepté)\n\n**2. Corrections**\n- a) *Where do you live?* — Le mot interrogatif ne remplace pas l'auxiliaire ; *live* n'est ni *be* ni un modal, il faut *do* : mot interrogatif → auxiliaire → sujet → verbe.\n- b) *Who lives here?* — *Who* est lui-même le sujet de la question : dans ce cas, pas d'auxiliaire, le verbe prend le -s de la 3e personne.\n- c) *Does he play football?* — Avec *does*, c'est l'auxiliaire qui porte la marque de la 3e personne ; le verbe revient à la base verbale *play*."}$exo$::jsonb),
  ('1ece81b2-1c56-59a7-a6f7-5d9ac25ffc95'::uuid, 1, 'traduction', $exo${"titre":"Dire non : trois phrases négatives","consigne":"Traduis ces trois phrases du français vers l'anglais (thème). Place bien la négation.","enonce":"**Thème : traduis en anglais.**\n\n1. Je ne suis pas français.\n2. Je ne sais pas nager.\n3. Il n'aime pas le poisson.\n\n*Aide : fish = poisson ; to swim = nager.*","bareme":[{"critere":"Place et forme de not selon le verbe","points":10},{"critere":"Base verbale après doesn't","points":5},{"critere":"Orthographe et apostrophes","points":5}],"dureeMin":6,"corrige":"**Traduction modèle**\n\n1. *I'm not French.* (ou *I am not French.*)\n2. *I can't swim.* (ou *I cannot swim.*)\n3. *He doesn't like fish.* (ou *He does not like fish.*)\n\n**Points attendus**\n- *not* se place après l'auxiliaire : après *be* (*am not*), après le modal (*cannot*, en un seul mot, ou *can't*).\n- Phrase 3 : *like* n'est ni *be* ni un modal → *doesn't* à la 3e personne, puis la base verbale *like* (pas « likes »).\n- Nationalité avec majuscule : *French*. Pas d'article devant *fish* (goût en général).\n- Une seule négation : « ne… pas » donne un seul *not*."}$exo$::jsonb),
  ('1ece81b2-1c56-59a7-a6f7-5d9ac25ffc95'::uuid, 2, 'traduction', $exo${"titre":"Le journal de Léo : une journée sans","consigne":"Léo écrit dans son journal. Traduis ses phrases du français vers l'anglais (thème) en n'utilisant qu'une seule négation par phrase.","enonce":"**Thème : traduis en anglais.**\n\n1. Mes parents ne sont pas à la maison.\n2. Il n'y a pas de lait.\n3. Je ne mange jamais de viande.\n4. Ma sœur ne regarde pas la télé.\n5. Je ne vois rien.\n\n*Aide : milk = lait ; meat = viande ; to watch TV = regarder la télé.*","bareme":[{"critere":"Négation avec be et do/does","points":7},{"critere":"Emploi de no et de not","points":4},{"critere":"Mots déjà négatifs sans not","points":6},{"critere":"Orthographe et apostrophes","points":3}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n1. *My parents aren't at home.* (ou *are not at home*)\n2. *There is no milk.* ou *There isn't any milk.* (les deux sont justes)\n3. *I never eat meat.*\n4. *My sister doesn't watch TV.* (ou *does not watch*)\n5. *I don't see anything.* ou *I see nothing.*\n\n**Points attendus**\n- Phrase 1 : verbe *be* au pluriel → *aren't*.\n- Phrase 2 : *no* + nom, ou *not* (contracté en *isn't*) + *any*.\n- Phrase 3 : *never* est déjà négatif : pas de *don't* (« I don't never eat meat » est faux).\n- Phrase 4 : *doesn't* + base verbale *watch* (pas « watches »).\n- Phrase 5 : le français a deux mots (ne… rien), l'anglais un seul. « I don't see nothing » voudrait dire « je vois quelque chose »."}$exo$::jsonb),
  ('1ece81b2-1c56-59a7-a6f7-5d9ac25ffc95'::uuid, 3, 'traduction', $exo${"titre":"Négations : traduire, corriger, expliquer","consigne":"Traduis les cinq phrases de l'anglais vers le français (version), puis corrige les trois phrases fausses et explique chaque erreur.","enonce":"**1. Version : traduis en français.**\n\n1. *We didn't go to school yesterday.*\n2. *Nobody was at home.*\n3. *There isn't any bread, and there is no water.*\n4. *My brother doesn't like music.*\n5. *You mustn't be late.*\n\n*Aide : yesterday = hier ; late = en retard.*\n\n**2.** Corrige ces phrases et explique la règle qui n'a pas été respectée.\n\n- a) « I don't see nothing. »\n- b) « She doesn't likes dogs. »\n- c) « I don't never eat fish. »","bareme":[{"critere":"Version : sens des négations","points":6},{"critere":"Version : français correct","points":3},{"critere":"Correction des phrases fautives","points":5},{"critere":"Justification (une seule négation, base verbale)","points":6}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n\n1. Nous ne sommes pas allés à l'école hier. (« On n'est pas allés » accepté)\n2. Personne n'était à la maison.\n3. Il n'y a pas de pain, et il n'y a pas d'eau.\n4. Mon frère n'aime pas la musique.\n5. Tu ne dois pas être en retard. (« Vous ne devez pas » accepté)\n\nAttention : en français la négation a deux mots (ne… pas, ne… personne) ; *didn't* renvoie au passé ; *mustn't* = interdiction.\n\n**2. Corrections**\n- a) *I don't see anything.* ou *I see nothing.* — Une seule négation par phrase : deux négations s'annulent (« I don't see nothing » = je vois quelque chose).\n- b) *She doesn't like dogs.* — Après *doesn't*, le verbe revient à la base verbale : le -s est déjà porté par *does*.\n- c) *I never eat fish.* — *never* est un mot déjà négatif : on ne lui ajoute pas *not* / *don't*."}$exo$::jsonb),
  ('bd594123-7056-5cf4-a4d4-d85413e58d59'::uuid, 1, 'traduction', $exo${"titre":"Donner un ordre : trois phrases à l'impératif","consigne":"Traduis ces trois phrases du français vers l'anglais (thème) en utilisant l'impératif.","enonce":"**Thème : traduis en anglais.**\n\n1. Viens ici !\n2. Ne touche pas ça !\n3. Assieds-toi, s'il te plaît.\n\n*Aide : to touch = toucher ; to sit down = s'asseoir.*","bareme":[{"critere":"Forme de l'impératif (base verbale sans sujet)","points":8},{"critere":"Impératif négatif avec don't","points":7},{"critere":"Orthographe et ponctuation","points":5}],"dureeMin":5,"corrige":"**Traduction modèle**\n\n1. *Come here!*\n2. *Don't touch that!* (*Don't touch it!* accepté)\n3. *Sit down, please.* (ou *Please sit down.*)\n\n**Points attendus**\n- L'impératif = la base verbale, sans sujet et sans terminaison (pas de « You come »).\n- Négation : *Don't* + base verbale.\n- *please* adoucit l'ordre, en début ou en fin de phrase."}$exo$::jsonb),
  ('bd594123-7056-5cf4-a4d4-d85413e58d59'::uuid, 2, 'traduction', $exo${"titre":"Les consignes du professeur","consigne":"Ton professeur d'anglais donne des consignes à la classe. Traduis-les du français vers l'anglais (thème).","enonce":"**Thème : traduis en anglais.**\n\n1. Lisez le texte.\n2. Répondez aux questions.\n3. Ne soyez pas en retard.\n4. Allons jouer au football !\n5. N'oublie pas ton livre.\n\n*Aide : late = en retard ; to forget = oublier ; to answer = répondre à.*","bareme":[{"critere":"Impératif affirmatif, une seule forme","points":6},{"critere":"Négation avec don't, même avec be","points":6},{"critere":"Let's pour une proposition collective","points":4},{"critere":"Orthographe et ponctuation","points":4}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Read the text.*\n2. *Answer the questions.*\n3. *Don't be late.*\n4. *Let's play football!*\n5. *Don't forget your book.*\n\n**Points attendus**\n- Une seule forme d'impératif, qu'on parle à une personne ou à toute la classe : « lisez » et « lis » = *Read*.\n- Phrase 2 : *answer* se construit sans « to » (*Answer the questions*).\n- Phrase 3 : même avec *be*, la négation se fait avec *Don't* (« Be not late » est faux).\n- Phrase 4 : proposition collective → *Let's* + base verbale ; pas d'article devant *football*. (« Let's go and play football! » accepté.)\n- Phrase 5 : *Don't forget* = n'oublie pas."}$exo$::jsonb),
  ('bd594123-7056-5cf4-a4d4-d85413e58d59'::uuid, 3, 'traduction', $exo${"titre":"Une recette de sandwich : l'impératif en action","consigne":"Traduis la recette de l'anglais vers le français (version), puis réponds aux questions 2 à 4.","enonce":"**1. Version : traduis en français.**\n\n> 1. Let's make a sandwich!\n> 2. Wash your hands, please.\n> 3. Take two pieces of bread.\n> 4. Put some cheese on the bread.\n> 5. Don't use a big knife. Ask an adult.\n> 6. Let's eat!\n\n*Aide : to wash = laver ; a piece = un morceau ; cheese = fromage ; a knife = un couteau ; to ask = demander.*\n\n**2.** Relève dans la recette un impératif affirmatif, un impératif négatif et une proposition avec *let's*.\n\n**3.** Explique la différence de sens entre *Don't forget* et *Forget it*.\n\n**4.** Réécris l'ordre *Sit down.* de deux façons plus polies.","bareme":[{"critere":"Version : traduction juste et naturelle","points":8},{"critere":"Repérage des trois formes","points":4},{"critere":"Sens de Don't forget et Forget it","points":3},{"critere":"Formes polies (please, could)","points":5}],"dureeMin":16,"corrige":"**1. Traduction modèle** (tutoiement ou vouvoiement acceptés, s'ils restent cohérents)\n\n1. Faisons un sandwich !\n2. Lave-toi les mains, s'il te plaît.\n3. Prends deux morceaux de pain.\n4. Mets du fromage sur le pain.\n5. N'utilise pas de grand couteau. Demande à un adulte.\n6. Mangeons ! (« On mange ! » accepté)\n\nPoints : *Let's* → première personne du pluriel (« faisons », « mangeons ») ; *your hands* → « les mains » en français.\n\n**2.** Affirmatif : *Wash*, *Take*, *Put* ou *Ask*. Négatif : *Don't use*. Proposition : *Let's make* ou *Let's eat*.\n\n**3.** *Don't forget* = n'oublie pas (il faut s'en souvenir) ; *Forget it* = laisse tomber (ce n'est pas important). Même verbe, sens opposés.\n\n**4.** *Sit down, please.* (ou *Please sit down.*) et *Could you sit down?* (la question avec le modal *could* est plus polie)."}$exo$::jsonb),
  ('139927eb-fa01-5665-b1d6-872ead8f30cd'::uuid, 1, 'traduction', $exo${"titre":"Plus grand, plus intéressant, le meilleur","consigne":"Traduis ces trois phrases du français vers l'anglais (thème). Choisis entre -er et more selon la longueur de l'adjectif.","enonce":"**Thème : traduis en anglais.**\n\n1. Il est plus grand que moi.\n2. Ce livre est plus intéressant que le film.\n3. Paul est le meilleur élève.\n\n*Aide : tall = grand (taille) ; interesting = intéressant ; good = bon ; a pupil = un élève.*","bareme":[{"critere":"Choix de -er ou more selon la longueur","points":10},{"critere":"Irrégulier good → the best","points":6},{"critere":"Orthographe et ponctuation","points":4}],"dureeMin":7,"corrige":"**Traduction modèle**\n\n1. *He is taller than me.* (*He's taller than me.*)\n2. *This book is more interesting than the film.* (*the movie* accepté)\n3. *Paul is the best pupil.* (*the best student* accepté)\n\n**Points attendus**\n- *tall* est court (1 syllabe) → *taller than*.\n- *interesting* est long → *more interesting than*, sans -er.\n- *good* est irrégulier : *good → better → the best* (jamais « the goodest »).\n- On ne cumule jamais les deux formes (« more taller » est faux)."}$exo$::jsonb),
  ('139927eb-fa01-5665-b1d6-872ead8f30cd'::uuid, 2, 'traduction', $exo${"titre":"Comparer ses animaux, sa famille et sa ville","consigne":"Traduis ces cinq phrases du français vers l'anglais (thème) en soignant l'orthographe des comparatifs et superlatifs.","enonce":"**Thème : traduis en anglais.**\n\n1. Mon chien est plus gros que ton chat.\n2. Ma sœur est plus heureuse que moi.\n3. Londres est la plus grande ville d'Angleterre.\n4. Ce film est pire que le livre.\n5. Tom est aussi grand que Léa.\n\n*Aide : big = gros, grand ; happy = heureux ; bad = mauvais ; tall = grand (taille) ; a city = une ville.*","bareme":[{"critere":"Orthographe du -er (doublement, -ier)","points":5},{"critere":"Superlatif the … -est","points":4},{"critere":"Irrégulier bad et égalité as … as","points":7},{"critere":"Vocabulaire et ordre de la phrase","points":4}],"dureeMin":12,"corrige":"**Traduction modèle**\n\n1. *My dog is bigger than your cat.*\n2. *My sister is happier than me.*\n3. *London is the biggest city in England.* (*the largest* accepté)\n4. *This film is worse than the book.*\n5. *Tom is as tall as Léa.*\n\n**Points attendus**\n- *big* : consonne-voyelle-consonne → on double le g : *bigger*, *biggest*.\n- *happy* : consonne + y → *happier* (2 syllabes en -y = adjectif court).\n- Superlatif court : *the biggest*. Après un superlatif, « d'Angleterre » se dit *in England*.\n- *bad* est irrégulier : *worse* (« badder » ou « more bad » sont faux).\n- Égalité : *as tall as*."}$exo$::jsonb),
  ('139927eb-fa01-5665-b1d6-872ead8f30cd'::uuid, 3, 'traduction', $exo${"titre":"Comparer trois élèves à partir d'un tableau","consigne":"Lis le tableau, traduis les six phrases du français vers l'anglais (thème), puis réponds aux questions 2 et 3.","enonce":"| Élève | Âge | Taille |\n|---|---|---|\n| Sam | 11 ans | 1,40 m |\n| Mia | 12 ans | 1,45 m |\n| Noah | 11 ans | 1,40 m |\n\n**1. Thème : traduis en anglais.**\n\n1. Mia est plus âgée que Sam.\n2. Sam est aussi grand que Noah.\n3. Mia est la plus grande des trois.\n4. Noah n'est pas aussi grand que Mia.\n5. Le vélo rouge est moins cher que le vélo bleu.\n6. C'est le pire jour de la semaine !\n\n*Aide : old = âgé ; tall = grand ; expensive = cher ; a bike = un vélo ; a day = un jour ; the week = la semaine.*\n\n**2.** Un camarade a écrit « Mia is more taller than Sam. » Corrige la phrase et explique l'erreur.\n\n**3.** Explique pourquoi on dit *more expensive* mais *older*.","bareme":[{"critere":"Comparatifs de supériorité et d'infériorité","points":5},{"critere":"Égalité et égalité niée (as … as)","points":4},{"critere":"Superlatifs réguliers et irréguliers","points":4},{"critere":"Correction et justification de more taller","points":4},{"critere":"Explication du choix -er ou more","points":3}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n1. *Mia is older than Sam.*\n2. *Sam is as tall as Noah.*\n3. *Mia is the tallest of the three.*\n4. *Noah is not as tall as Mia.* (*isn't as tall as* accepté)\n5. *The red bike is less expensive than the blue bike.* (*than the blue one* accepté)\n6. *It's the worst day of the week!*\n\nPoints : *old* court → *older* ; égalité *as … as*, égalité niée *not as … as* ; superlatif court *the tallest* ; infériorité *less … than* ; *bad* irrégulier → *the worst*. Les phrases 1 à 4 sont vraies d'après le tableau (Mia a 12 ans et mesure 1,45 m).\n\n**2.** *Mia is taller than Sam.* On ne cumule jamais les deux formes : *tall* est court, il prend seulement -er ; *more* est réservé aux adjectifs longs.\n\n**3.** Le choix dépend de la longueur de l'adjectif : *old* a une syllabe → -er (*older*) ; *expensive* a trois syllabes → *more* (ou *less*) devant l'adjectif."}$exo$::jsonb),
  ('c371d142-8ced-5f94-9a25-77ab3f83fd24'::uuid, 1, 'traduction', $exo${"titre":"Des chats, des boîtes et des enfants","consigne":"Traduis ces trois phrases du français vers l'anglais (thème). Fais attention à la forme du pluriel.","enonce":"**Thème : traduis en anglais.**\n\n1. J'ai deux chats et trois livres.\n2. Il y a cinq boîtes sur la table.\n3. Les enfants ont des chiens.\n\n*Aide : a box = une boîte ; a child = un enfant.*","bareme":[{"critere":"Pluriel régulier et pluriel en -es","points":8},{"critere":"Pluriel irrégulier (children)","points":6},{"critere":"Orthographe et ponctuation","points":6}],"dureeMin":6,"corrige":"**Traduction modèle**\n\n1. *I have two cats and three books.*\n2. *There are five boxes on the table.*\n3. *The children have dogs.*\n\n**Points attendus**\n- Règle générale : on ajoute -s (*cats*, *books*, *dogs*).\n- *box* finit par -x → *boxes*.\n- *child* est irrégulier → *children* (jamais « childs »).\n- « des chiens » : pas d'article devant le pluriel (*have dogs*)."}$exo$::jsonb),
  ('c371d142-8ced-5f94-9a25-77ab3f83fd24'::uuid, 2, 'traduction', $exo${"titre":"Une visite à la ferme : pluriels particuliers","consigne":"Tu racontes une visite à la ferme. Traduis ces cinq phrases du français vers l'anglais (thème).","enonce":"**Thème : traduis en anglais.**\n\n1. À la ferme, il y a dix moutons et deux chevaux.\n2. Les femmes ont des couteaux.\n3. Les souris mangent du pain.\n4. Les garçons visitent deux villes en trois jours.\n5. Les feuilles sont jaunes.\n\n*Aide : a farm = une ferme ; a sheep = un mouton ; a horse = un cheval ; a knife = un couteau ; a mouse = une souris ; a city = une ville ; a leaf = une feuille ; yellow = jaune.*","bareme":[{"critere":"Pluriels irréguliers et invariables (sheep, women, mice)","points":7},{"critere":"Pluriels en -ies, en -ys et en -ves","points":6},{"critere":"Indénombrable sans -s (bread)","points":3},{"critere":"Orthographe et ponctuation","points":4}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n1. *On the farm, there are ten sheep and two horses.*\n2. *The women have knives.*\n3. *The mice eat bread.* (*Mice eat bread.* accepté)\n4. *The boys visit two cities in three days.*\n5. *The leaves are yellow.*\n\n**Points attendus**\n- *sheep* ne change pas au pluriel (jamais « sheeps »).\n- *woman → women*, *mouse → mice* : pluriels irréguliers.\n- *knife → knives*, *leaf → leaves* (-f / -fe → -ves).\n- *city → cities* (consonne + y → -ies) mais *day → days* (voyelle + y → -s seulement).\n- *bread* est indénombrable : ni -s, ni *a*."}$exo$::jsonb),
  ('c371d142-8ced-5f94-9a25-77ab3f83fd24'::uuid, 3, 'traduction', $exo${"titre":"Pluriels, indénombrables et prononciation du -s","consigne":"Traduis les six phrases du français vers l'anglais (thème), puis réponds aux questions 2 et 3.","enonce":"**1. Thème : traduis en anglais.**\n\n1. Mes devoirs sont difficiles.\n2. Merci pour les informations.\n3. Il y a deux personnes et trois bébés dans le bus.\n4. Je voudrais de l'eau, s'il vous plaît.\n5. Mes pieds et mes dents sont propres.\n6. Il a deux montres et trois boîtes.\n\n*Aide : homework = devoirs ; information = informations ; a baby = un bébé ; I would like = je voudrais ; a foot = un pied ; a tooth = une dent ; clean = propre ; a watch = une montre ; a box = une boîte.*\n\n**2.** Explique pourquoi on n'écrit pas « informations » en anglais, et pourquoi on ne dit pas « a water ».\n\n**3.** Classe ces trois mots selon la prononciation de leur -s final (/s/, /z/ ou /ɪz/) : *watches*, *cats*, *dogs*.","bareme":[{"critere":"Pluriels réguliers, en -es et en -ies","points":4},{"critere":"Pluriels irréguliers (people, feet, teeth)","points":5},{"critere":"Indénombrables (homework, information, water)","points":5},{"critere":"Justification du piège des indénombrables","points":3},{"critere":"Prononciation du -s final","points":3}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n1. *My homework is difficult.* (*hard* accepté)\n2. *Thank you for the information.* (*Thanks for the information.* accepté)\n3. *There are two people and three babies on the bus.* (*in the bus* accepté)\n4. *I would like some water, please.* (*I'd like some water, please.*)\n5. *My feet and my teeth are clean.*\n6. *He has two watches and three boxes.*\n\nPoints : *homework* est indénombrable → verbe au singulier *is* ; *person → people* ; *baby → babies* ; *foot → feet*, *tooth → teeth* ; *watch → watches*, *box → boxes* (-ch, -x → -es) ; *some water*.\n\n**2.** *Information* et *homework* sont indénombrables en anglais, alors qu'on les met au pluriel en français : ils ne prennent jamais de -s. *Water* est aussi indénombrable : ni pluriel, ni *a/an* ; on dit *some water*.\n\n**3.** /s/ : *cats* (après t) ; /z/ : *dogs* (après une sonore) ; /ɪz/ : *watches* (après un sifflement)."}$exo$::jsonb),
  ('e36d9e8d-8bf2-5795-9fa8-aed2e4f389f9'::uuid, 1, 'traduction', $exo${"titre":"A, an ou the : trois phrases","consigne":"Traduis ces trois phrases du français vers l'anglais (thème). Choisis bien l'article.","enonce":"**Thème : traduis en anglais.**\n\n1. J'ai un chien et une pomme.\n2. Le chien est noir.\n3. C'est une orange.\n\n*Aide : an apple = une pomme ; black = noir.*","bareme":[{"critere":"Choix de a ou an selon le son","points":10},{"critere":"Article défini the","points":5},{"critere":"Orthographe et ponctuation","points":5}],"dureeMin":5,"corrige":"**Traduction modèle**\n\n1. *I have a dog and an apple.*\n2. *The dog is black.*\n3. *It's an orange.* (ou *It is an orange.*)\n\n**Points attendus**\n- *a* devant un son de consonne (*a dog*), *an* devant un son de voyelle (*an apple*, *an orange*).\n- Phrase 2 : le chien est déjà connu → *the*. D'abord on présente (*a dog*), ensuite on désigne (*the dog*).\n- « C'est » → *It's*."}$exo$::jsonb),
  ('e36d9e8d-8bf2-5795-9fa8-aed2e4f389f9'::uuid, 2, 'traduction', $exo${"titre":"Parler de ses goûts : l'article zéro","consigne":"Traduis ces cinq phrases du français vers l'anglais (thème). Attention : l'anglais met moins d'articles que le français.","enonce":"**Thème : traduis en anglais.**\n\n1. J'aime la musique.\n2. Les chats sont indépendants.\n3. Mon frère joue au tennis.\n4. Nous allons à l'école en France.\n5. J'ai un livre ; le livre est rouge.\n\n*Aide : independent = indépendant ; red = rouge.*","bareme":[{"critere":"Article zéro (généralités, sports, pays, école)","points":9},{"critere":"A ou the : présenter puis désigner","points":5},{"critere":"Vocabulaire et ordre de la phrase","points":3},{"critere":"Orthographe et ponctuation","points":3}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *I like music.* (*I love music.* accepté)\n2. *Cats are independent.*\n3. *My brother plays tennis.*\n4. *We go to school in France.*\n5. *I have a book; the book is red.* (*…and the book is red* accepté)\n\n**Points attendus**\n- Pas d'article devant un indénombrable pris en général (*music*), ni devant un pluriel de généralité (*cats*).\n- Pas d'article devant un sport (*play tennis*), un pays (*France*), ni devant *school* dans sa fonction (*go to school*).\n- Phrase 5 : *a book* (on présente), puis *the book* (on désigne un livre déjà connu)."}$exo$::jsonb),
  ('e36d9e8d-8bf2-5795-9fa8-aed2e4f389f9'::uuid, 3, 'traduction', $exo${"titre":"Le texte de Jack : articles et article zéro","consigne":"Traduis le texte de l'anglais vers le français (version) en rétablissant les articles français, puis réponds aux questions 2 à 4.","enonce":"**1. Version : traduis en français.**\n\n> I live in London with my family. I have a cat and an old dog. The cat is white. My sister studies maths at university. We usually have breakfast at home. My uncle lives in the United States.\n\n*Aide : usually = d'habitude ; to have breakfast = prendre le petit déjeuner ; uncle = oncle.*\n\n**2.** On écrit *a university* mais *an hour*. Explique pourquoi.\n\n**3.** Le texte ne met pas d'article devant *maths* ni devant *breakfast*, alors que le français en met. Explique cette différence.\n\n**4.** Pourquoi écrit-on *the United States* alors qu'on écrit *France* sans article ?","bareme":[{"critere":"Version : traduction juste et naturelle","points":7},{"critere":"Articles français rétablis","points":3},{"critere":"Justification a / an par le son","points":4},{"critere":"Explication de l'article zéro","points":4},{"critere":"Exception the United States","points":2}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n\nJ'habite à Londres avec ma famille. J'ai un chat et un vieux chien. Le chat est blanc. Ma sœur étudie les maths à l'université. D'habitude, nous prenons le petit déjeuner à la maison. Mon oncle habite aux États-Unis.\n\n(« Nous prenons généralement… », « On prend… » acceptés.) Articles rétablis : **les** maths, **l'**université, **le** petit déjeuner, **la** maison, **les** États-Unis. *an old dog* → « un vieux chien » (*an* car *old* commence par un son de voyelle).\n\n**2.** C'est le son, et non la lettre, qui décide. *University* commence par le son « you », un son de consonne → *a*. Dans *hour*, le h ne se prononce pas : le mot commence par un son de voyelle → *an*.\n\n**3.** L'anglais n'emploie pas d'article devant les matières (*study maths*), les repas (*have breakfast*), ni devant *school, home, work, bed* dans leur fonction (*at home*, *at university* dans le texte). Le français, lui, met un article presque partout.\n\n**4.** Les noms de pays n'ont pas d'article (*France*), sauf quelques exceptions : les pays au nom pluriel ou contenant un nom commun, comme *the United States* (*states* = des États)."}$exo$::jsonb),
  ('6189bb4a-dbc2-592e-86e6-046830208547'::uuid, 1, 'traduction', $exo${"titre":"This, that, these ou those ?","consigne":"Traduis ces trois phrases du français vers l'anglais (thème). Pour chaque démonstratif, demande-toi : proche ou éloigné ? singulier ou pluriel ?","enonce":"**Thème : traduis en anglais.**\n\n1. Ce livre (ici) est à moi.\n2. Ces chaussures (ici) sont neuves.\n3. Cette voiture là-bas est rouge.\n\n*Aide : mine = à moi ; shoes = chaussures ; new = neuf ; red = rouge.*","bareme":[{"critere":"Choix proche ou éloigné","points":8},{"critere":"Choix singulier ou pluriel","points":8},{"critere":"Orthographe et ponctuation","points":4}],"dureeMin":6,"corrige":"**Traduction modèle**\n\n1. *This book is mine.*\n2. *These shoes are new.*\n3. *That car is red.*\n\n**Points attendus**\n- Proche + singulier → *this* ; proche + pluriel → *these*.\n- Éloigné + singulier → *that* : « là-bas » est déjà contenu dans *that*, on n'ajoute pas *there* (*That car over there* est toutefois accepté).\n- Le verbe s'accorde : *is* au singulier, *are* au pluriel."}$exo$::jsonb),
  ('6189bb4a-dbc2-592e-86e6-046830208547'::uuid, 2, 'traduction', $exo${"titre":"Au téléphone et en présentant sa famille","consigne":"Traduis ces cinq phrases du français vers l'anglais (thème) en choisissant le bon démonstratif.","enonce":"**Thème : traduis en anglais.**\n\n1. (Au téléphone) Allô, c'est Tom à l'appareil.\n2. Voici ma sœur, Emma.\n3. Qu'est-ce que c'est (ici, dans ma main) ? — C'est mon sac.\n4. Ces oiseaux là-bas sont grands.\n5. Ces jours-ci, il fait froid.\n\n*Aide : a bag = un sac ; a bird = un oiseau ; big = grand ; cold = froid.*","bareme":[{"critere":"Emplois particuliers (téléphone, présentation)","points":5},{"critere":"Démonstratifs pronoms, sans nom","points":4},{"critere":"Choix selon la distance et le nombre","points":8},{"critere":"Orthographe et ponctuation","points":3}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *Hello, this is Tom.*\n2. *This is my sister, Emma.*\n3. *What's this? — That's my bag.* (*It's my bag.* accepté)\n4. *Those birds are big.*\n5. *These days, it's cold.*\n\n**Points attendus**\n- Au téléphone, on se présente avec *this is* (et non « I am Tom »).\n- Pour présenter quelqu'un : *This is my sister.*\n- Phrase 3 : démonstratifs employés seuls, comme pronoms. L'objet est près de celui qui demande → *this* ; celui qui répond peut dire *that* (l'objet est chez l'autre).\n- Phrase 4 : éloigné + pluriel → *those* (« -là » est déjà dans le mot).\n- Phrase 5 : dans le temps, *these days* ; *it* sujet pour le temps qu'il fait."}$exo$::jsonb),
  ('6189bb4a-dbc2-592e-86e6-046830208547'::uuid, 3, 'traduction', $exo${"titre":"Dans la chambre de Ben : démonstratifs en dialogue","consigne":"Traduis le dialogue de l'anglais vers le français (version), puis réponds aux questions 2 et 3.","enonce":"**1. Version : traduis en français.**\n\n> **Anna:** What's this?\n> **Ben:** This is my new game.\n> **Anna:** And those boxes over there?\n> **Ben:** Those are my old games.\n> **Anna:** Is that your bike?\n> **Ben:** Yes! These days, I ride it every morning.\n\n*Aide : a game = un jeu ; over there = là-bas ; a bike = un vélo ; to ride a bike = faire du vélo ; every morning = tous les matins.*\n\n**2.** Pour *this*, *those* et *that* dans le dialogue, explique le choix du mot avec les deux critères du cours.\n\n**3.** À l'oral, qu'est-ce qui distingue *this* de *these* ? Pourquoi est-ce important ?","bareme":[{"critere":"Version : traduction juste et naturelle","points":8},{"critere":"Analyse : distance et nombre","points":5},{"critere":"Prononciation de this et these","points":4},{"critere":"Orthographe du français","points":3}],"dureeMin":15,"corrige":"**1. Traduction modèle**\n\n- Anna : Qu'est-ce que c'est ?\n- Ben : C'est mon nouveau jeu.\n- Anna : Et ces boîtes, là-bas ?\n- Ben : Ce sont mes vieux jeux.\n- Anna : C'est ton vélo, ça ? (« Est-ce que c'est ton vélo ? » accepté)\n- Ben : Oui ! Ces temps-ci, j'en fais tous les matins. (« Ces jours-ci, je le prends tous les matins » accepté)\n\n**2. Analyse**\n- *this* (« What's this? », « This is my new game ») : un seul objet, proche (Ben l'a sous la main) → singulier + proche.\n- *those* (« those boxes », « Those are ») : plusieurs boîtes, éloignées (*over there*) → pluriel + éloigné.\n- *that* (« Is that your bike? ») : un seul vélo, loin d'Anna → singulier + éloigné.\n\n**3.** *this* /ðɪs/ se prononce avec une voyelle courte, *these* /ðiːz/ avec une voyelle longue. C'est le seul indice à l'oral : si on les confond, on change le nombre (un seul objet ou plusieurs)."}$exo$::jsonb),
  ('8fefaa83-c23d-51ce-ae85-da9c9c22a34b'::uuid, 1, 'traduction', $exo${"titre":"Le vélo de Paul, sa sœur, son frère","consigne":"Traduis ces trois phrases du français vers l'anglais (thème). Accorde le possessif avec le possesseur.","enonce":"**Thème : traduis en anglais.**\n\n1. Le vélo de Paul est bleu.\n2. Sa sœur (la sœur de Paul) s'appelle Anna.\n3. Son frère (le frère d'Anna) a dix ans.\n\n*Aide : a bike = un vélo ; blue = bleu ; to be called = s'appeler.*","bareme":[{"critere":"Génitif 's et ordre possesseur-objet","points":8},{"critere":"His ou her selon le possesseur","points":8},{"critere":"Orthographe et apostrophe","points":4}],"dureeMin":6,"corrige":"**Traduction modèle**\n\n1. *Paul's bike is blue.*\n2. *His sister is called Anna.* (*His sister's name is Anna.* accepté)\n3. *Her brother is ten.* (*Her brother is ten years old.* accepté)\n\n**Points attendus**\n- Génitif : possesseur → ’s → objet (*Paul's bike*), l'ordre est inversé par rapport au français.\n- « sa sœur » : le possesseur est Paul, un garçon → *his*, même si « sœur » est féminin.\n- « son frère » : la possesseure est Anna, une fille → *her*.\n- L'âge se dit avec *be* : *is ten*."}$exo$::jsonb),
  ('8fefaa83-c23d-51ce-ae85-da9c9c22a34b'::uuid, 2, 'traduction', $exo${"titre":"Chez les voisins : ’s, of et possessifs","consigne":"Tu décris la famille de tes voisins. Traduis ces cinq phrases du français vers l'anglais (thème).","enonce":"**Thème : traduis en anglais.**\n\n1. La voiture de mes parents est rouge.\n2. La chambre des enfants est grande.\n3. Julie aime son chat.\n4. Tom et Léo ont un chien. Leur chien est noir.\n5. La porte de la maison est verte.\n\n*Aide : a room = une chambre ; big = grand ; the door = la porte ; green = vert.*","bareme":[{"critere":"Génitif (parents', children's)","points":6},{"critere":"Of pour les choses","points":3},{"critere":"Adjectifs possessifs accordés au possesseur","points":8},{"critere":"Orthographe et apostrophes","points":3}],"dureeMin":12,"corrige":"**Traduction modèle**\n\n1. *My parents' car is red.*\n2. *The children's room is big.*\n3. *Julie loves her cat.* (*likes* accepté)\n4. *Tom and Léo have a dog. Their dog is black.*\n5. *The door of the house is green.*\n\n**Points attendus**\n- *parents* est un pluriel déjà en -s → seulement l'apostrophe : *parents'*.\n- *children* est un pluriel irrégulier → on garde ’s : *children's*.\n- Phrase 3 : la possesseure est Julie → *her cat* (le genre du chat ne compte pas).\n- Phrase 4 : deux possesseurs → *their*, invariable.\n- Phrase 5 : pour une chose, on emploie *of* : *the door of the house*."}$exo$::jsonb),
  ('8fefaa83-c23d-51ce-ae85-da9c9c22a34b'::uuid, 3, 'traduction', $exo${"titre":"À qui est-ce ? Possessifs, its et it's","consigne":"Traduis les six phrases du français vers l'anglais (thème), puis réponds aux questions 2 et 3.","enonce":"**1. Thème : traduis en anglais.**\n\n1. Ce livre est à moi, pas à toi.\n2. Marc aime sa mère.\n3. Le chien de ma sœur est petit.\n4. Son panier (le panier du chien) est bleu.\n5. C'est un gentil chien.\n6. Ces sacs sont à nous ; ceux-là sont à eux.\n\n*Aide : a basket = un panier ; nice = gentil ; a bag = un sac ; ceux-là = those.*\n\n**2.** Aux phrases 4 et 5, tu as écrit *its* ou *it's*. Explique la différence entre ces deux mots.\n\n**3.** À la phrase 2, explique pourquoi on écrit *his* alors que « mère » est féminin.","bareme":[{"critere":"Génitif et ordre des mots","points":4},{"critere":"Adjectifs possessifs selon le possesseur","points":5},{"critere":"Pronoms possessifs (mine, yours, ours, theirs)","points":5},{"critere":"Distinction its / it's justifiée","points":3},{"critere":"Explication de his mother","points":3}],"dureeMin":18,"corrige":"**1. Traduction modèle**\n\n1. *This book is mine, not yours.*\n2. *Marc loves his mother.* (*his mum* accepté)\n3. *My sister's dog is small.* (*little* accepté)\n4. *Its basket is blue.*\n5. *It's a nice dog.*\n6. *These bags are ours; those are theirs.*\n\nPoints : pronoms possessifs employés sans nom derrière (*mine*, *yours*, *ours*, *theirs*) ; génitif *my sister's dog* (possesseur → ’s → objet) ; *its* pour le possesseur animal/chose.\n\n**2.** *its* (sans apostrophe) est l'adjectif possessif : « son, sa » pour une chose ou un animal → *Its basket*. *it's* est la contraction de *it is* → *It's a nice dog* = *It is a nice dog*.\n\n**3.** En anglais, le possessif s'accorde avec le possesseur, pas avec l'objet possédé. Le possesseur est Marc, un garçon → *his*. Le genre du mot « mère » ne compte pas."}$exo$::jsonb),
  ('ad4cd5f4-49f1-5bb3-abc1-ab77aa0431c0'::uuid, 1, 'traduction', $exo${"titre":"Some, any, many : trois phrases","consigne":"Traduis ces trois phrases du français vers l'anglais (thème). Choisis some ou any selon le type de phrase.","enonce":"**Thème : traduis en anglais.**\n\n1. J'ai de l'argent.\n2. Je n'ai pas de pommes.\n3. Combien de livres ?\n\n*Aide : money = argent ; an apple = une pomme.*","bareme":[{"critere":"Some ou any selon le type de phrase","points":10},{"critere":"Many avec un dénombrable","points":5},{"critere":"Orthographe et ponctuation","points":5}],"dureeMin":6,"corrige":"**Traduction modèle**\n\n1. *I have some money.*\n2. *I don't have any apples.*\n3. *How many books?*\n\n**Points attendus**\n- Phrase affirmative → *some* ; *money* est indénombrable (pas de -s).\n- Phrase négative → *any* ; *apples* au pluriel.\n- *books* est un dénombrable pluriel → *How many* (et non *How much*)."}$exo$::jsonb),
  ('ad4cd5f4-49f1-5bb3-abc1-ab77aa0431c0'::uuid, 2, 'traduction', $exo${"titre":"Préparer les courses : ce qu'il y a dans la cuisine","consigne":"Avec ta mère, tu regardes ce qu'il y a dans la cuisine. Traduis ces cinq phrases du français vers l'anglais (thème).","enonce":"**Thème : traduis en anglais.**\n\n1. Il y a du lait dans le frigo.\n2. Est-ce qu'il y a des œufs ?\n3. Il n'y a pas de pain.\n4. Combien d'argent as-tu ?\n5. Tu veux du thé ? *(on te propose une tasse)*\n\n*Aide : milk = lait ; the fridge = le frigo ; an egg = un œuf ; bread = pain ; money = argent ; tea = thé ; Would you like…? = Veux-tu… ?*","bareme":[{"critere":"Some et any, y compris some pour proposer","points":8},{"critere":"Much ou many","points":4},{"critere":"There is ou there are","points":5},{"critere":"Orthographe et ponctuation","points":3}],"dureeMin":11,"corrige":"**Traduction modèle**\n\n1. *There is some milk in the fridge.*\n2. *Are there any eggs?*\n3. *There isn't any bread.* (*There is no bread.* accepté)\n4. *How much money do you have?*\n5. *Would you like some tea?*\n\n**Points attendus**\n- *there is* + singulier ou indénombrable (*milk*, *bread*) ; *there are* + pluriel (*eggs*), inversé dans la question : *Are there…?*\n- *some* en phrase affirmative ; *any* en question neutre et en négation.\n- *money* est indénombrable → *How much*.\n- Phrase 5 : on propose quelque chose → *some*, même dans une question."}$exo$::jsonb),
  ('ad4cd5f4-49f1-5bb3-abc1-ab77aa0431c0'::uuid, 3, 'traduction', $exo${"titre":"Beaucoup, quelques, peu : traduire et corriger","consigne":"Traduis les cinq phrases de l'anglais vers le français (version), puis corrige les trois phrases fausses en justifiant.","enonce":"**1. Version : traduis en français.**\n\n1. *I have a lot of friends at school.*\n2. *There are a few apples on the table.*\n3. *There is a little milk in my glass.*\n4. *Few people like this film.*\n5. *Can I have some water, please?*\n\n*Aide : a glass = un verre ; people = les gens.*\n\n**2.** Corrige chaque phrase et explique la règle.\n\n- a) « I have much money. »\n- b) « There is many books. »\n- c) « Do you have some brothers? » *(question simple, sans rien proposer)*","bareme":[{"critere":"Version : a lot of, a few, a little, few","points":7},{"critere":"Version : français correct","points":3},{"critere":"Corrections des trois phrases","points":5},{"critere":"Justifications","points":5}],"dureeMin":16,"corrige":"**1. Traduction modèle**\n\n1. J'ai beaucoup d'amis à l'école.\n2. Il y a quelques pommes sur la table.\n3. Il y a un peu de lait dans mon verre.\n4. Peu de gens aiment ce film.\n5. Est-ce que je peux avoir de l'eau, s'il vous plaît ? (« Je peux avoir de l'eau, s'il te plaît ? » accepté)\n\nPoints : *a few* = quelques (positif), *few* = peu (négatif), *a little* = un peu ; *a lot of* = beaucoup de.\n\n**2. Corrections**\n- a) *I have a lot of money.* — Dans une phrase affirmative, on emploie *a lot of* et non *much* : c'est une règle d'usage.\n- b) *There are many books.* (ou *There are a lot of books.*) — *books* est pluriel → *there are* ; *many* va bien avec un dénombrable pluriel.\n- c) *Do you have any brothers?* — Dans une question neutre (on ne propose ni ne demande rien), on emploie *any* ; *some* est réservé aux offres et aux demandes."}$exo$::jsonb),
  ('c625d09a-d589-5f5b-b4be-f8c4a7b72dd4'::uuid, 1, 'traduction', $exo${"titre":"Place et accord de l'adjectif","consigne":"Traduis ces trois phrases du français vers l'anglais (thème). Attention à la place de l'adjectif et à son accord.","enonce":"**Thème : traduis en anglais.**\n\n1. J'ai une voiture rouge.\n2. Il a deux vieilles maisons.\n3. Elle est française.\n\n*Aide : red = rouge ; old = vieux ; a house = une maison.*","bareme":[{"critere":"Place de l'adjectif devant le nom","points":8},{"critere":"Invariabilité et majuscule des nationalités","points":8},{"critere":"Orthographe et ponctuation","points":4}],"dureeMin":6,"corrige":"**Traduction modèle**\n\n1. *I have a red car.*\n2. *He has two old houses.*\n3. *She is French.* (*She's French.*)\n\n**Points attendus**\n- L'adjectif se place devant le nom : *a red car* (et non « a car red »).\n- L'adjectif est invariable : *old houses* (jamais « olds »).\n- Nationalité : majuscule obligatoire, et pas d'article après *is*."}$exo$::jsonb),
  ('c625d09a-d589-5f5b-b4be-f8c4a7b72dd4'::uuid, 2, 'traduction', $exo${"titre":"Une soirée ennuyeuse : -ed, -ing, very et too","consigne":"Tu racontes une soirée devant la télé. Traduis ces cinq phrases du français vers l'anglais (thème).","enonce":"**Thème : traduis en anglais.**\n\n1. Le film est ennuyeux.\n2. Je m'ennuie.\n3. Il fait très chaud.\n4. Ce thé est trop chaud.\n5. Ma sœur a l'air fatiguée.\n\n*Aide : bored / boring ; hot = chaud ; tea = thé ; tired = fatigué ; to look = avoir l'air.*","bareme":[{"critere":"Adjectifs en -ed et en -ing","points":7},{"critere":"Very ou too","points":6},{"critere":"Adjectif après be et look","points":4},{"critere":"Orthographe et ponctuation","points":3}],"dureeMin":10,"corrige":"**Traduction modèle**\n\n1. *The film is boring.* (*The movie is boring.* accepté)\n2. *I am bored.* (*I'm bored.*)\n3. *It's very hot.*\n4. *This tea is too hot.*\n5. *My sister looks tired.*\n\n**Points attendus**\n- *-ing* décrit ce qui provoque l'ennui (le film) ; *-ed* décrit ce qu'on ressent (moi). « I am boring » voudrait dire « je suis ennuyeux ».\n- *very* = très, un simple constat ; *too* = trop, un excès qui pose problème (le thé ne se boit pas).\n- *it* sujet pour le temps qu'il fait.\n- L'adjectif peut suivre *be* ou *look* : *looks tired* (invariable)."}$exo$::jsonb),
  ('c625d09a-d589-5f5b-b4be-f8c4a7b72dd4'::uuid, 3, 'traduction', $exo${"titre":"Décrire des objets : ordre et sens des adjectifs","consigne":"Traduis les six phrases du français vers l'anglais (thème), puis réponds aux questions 2 et 3.","enonce":"**1. Thème : traduis en anglais.**\n\n1. J'ai un joli petit chat noir.\n2. Mes grands-parents ont une vieille table en bois.\n3. Les chaussures rouges sont trop petites.\n4. Ce livre est très intéressant.\n5. Je suis intéressé par les voitures italiennes.\n6. Le film est ennuyeux et je m'ennuie.\n\n*Aide : beautiful = joli ; little = petit ; grandparents = grands-parents ; wooden = en bois ; shoes = chaussures ; small = petit ; interested in = intéressé par ; Italian = italien.*\n\n**2.** Justifie l'ordre des adjectifs dans ta phrase 1.\n\n**3.** Explique pourquoi « I am boring » serait un contresens à la phrase 6.","bareme":[{"critere":"Place et invariabilité de l'adjectif","points":5},{"critere":"Ordre des adjectifs","points":4},{"critere":"Adjectifs en -ed et en -ing","points":4},{"critere":"Very, too et nationalité avec majuscule","points":3},{"critere":"Justifications","points":4}],"dureeMin":17,"corrige":"**1. Traduction modèle**\n\n1. *I have a beautiful little black cat.* (*pretty* accepté à la place de *beautiful*)\n2. *My grandparents have an old wooden table.*\n3. *The red shoes are too small.*\n4. *This book is very interesting.*\n5. *I am interested in Italian cars.*\n6. *The film is boring and I am bored.* (*I'm bored* accepté)\n\nPoints : adjectifs devant le nom et invariables (*red shoes*, *Italian cars*) ; *an old* (son de voyelle) ; *too small* = trop petites (un problème) ; *very interesting* = un constat ; *Italian* avec majuscule ; *interesting* (ce qui provoque) / *interested* (ce qu'on ressent).\n\n**2.** L'ordre est : opinion → taille → âge → forme → couleur → origine → matière. *beautiful* (opinion) vient avant *little* (taille), qui vient avant *black* (couleur). De même en phrase 2 : *old* (âge) avant *wooden* (matière).\n\n**3.** Les adjectifs en -ing décrivent ce qui provoque le sentiment : « I am boring » signifierait « je suis ennuyeux » (c'est moi qui ennuie les autres). Pour dire ce que je ressens, il faut -ed : *I am bored* (je m'ennuie)."}$exo$::jsonb),
  ('dee815b8-34fa-5c98-a28e-31f31cfaa69f'::uuid, 1, 'traduction', $exo${"titre":"BE au présent : trois petites phrases","consigne":"Traduis ces trois phrases du français vers l'anglais (thème). Attention : là où le français dit « avoir », l'anglais dit parfois BE.","enonce":"**Traduis en anglais :**\n\n1. J'ai 11 ans.\n2. Ils ne sont pas anglais.\n3. Est-ce que tu as froid ?","bareme":[{"critere":"Conjugaison de BE au présent (affirmatif, négatif, interrogatif)","points":8},{"critere":"Emploi de BE là où le français dit « avoir »","points":8},{"critere":"Orthographe et ponctuation","points":4}],"dureeMin":6,"corrige":"1. **I am 11.** (ou *I'm 11.* / *I am 11 years old.*) — âge : BE et non have. Refuser « I have 11 ».\n2. **They are not English.** (ou *They aren't English.* / *They're not English.*) — négation : not après BE, sans DO. *English* prend une majuscule.\n3. **Are you cold?** — question par inversion de BE et du sujet, sans DO ; « avoir froid » = *be cold*.\n\nPoints attendus : I am / they are / are you ; BE pour l'âge et pour « avoir froid » ; majuscule à *English*, point d'interrogation."}$exo$::jsonb),
  ('dee815b8-34fa-5c98-a28e-31f31cfaa69f'::uuid, 2, 'traduction', $exo${"titre":"Dans le parc : il y a, avoir faim, avoir raison","consigne":"Traduis ce petit texte du français vers l'anglais (thème). Pense à « there is / there are » et aux emplois de BE.","enonce":"**Traduis en anglais :**\n\n1. Il y a un chat dans le jardin.\n2. Il y a deux garçons dans le parc.\n3. Tom a faim et il a soif.\n4. Nous n'avons pas peur.\n5. Tu as raison !","bareme":[{"critere":"Emploi de there is / there are selon singulier ou pluriel","points":5},{"critere":"BE pour avoir faim, soif, peur, raison","points":7},{"critere":"Forme négative de BE et accord avec le sujet","points":5},{"critere":"Orthographe et ponctuation","points":3}],"dureeMin":10,"corrige":"1. **There is a cat in the garden.** (ou *There's a cat…*) — singulier : *there is*.\n2. **There are two boys in the park.** — pluriel : *there are*.\n3. **Tom is hungry and (he is) thirsty.** (ou *Tom is hungry and he's thirsty.*) — avoir faim = *be hungry*, avoir soif = *be thirsty* ; 3e personne : *is*.\n4. **We are not afraid.** (ou *We aren't afraid.* / *We're not afraid.*) — avoir peur = *be afraid* ; négation : not après BE, sans DO.\n5. **You are right!** (ou *You're right!*) — avoir raison = *be right*.\n\nErreurs à sanctionner : « Tom has hungry », « We don't are afraid », « There is two boys »."}$exo$::jsonb),
  ('dee815b8-34fa-5c98-a28e-31f31cfaa69f'::uuid, 3, 'traduction', $exo${"titre":"Hier et aujourd'hui : BE sous toutes ses formes","consigne":"Traduis ces phrases du français vers l'anglais (thème), puis explique en une phrase pourquoi, dans la phrase 4, l'anglais n'emploie pas le verbe have.","enonce":"**Traduis en anglais :**\n\n1. Hier, j'étais malade.\n2. Mes parents n'étaient pas à la maison.\n3. Est-ce que tu étais à l'école ?\n4. Aujourd'hui, j'ai 12 ans et je n'ai pas froid.\n5. Il y a des gâteaux sur la table.\n6. Ma sœur est en train de chanter.\n\n**Question :** dans la phrase 4, pourquoi l'anglais n'emploie-t-il pas *have* ?","bareme":[{"critere":"BE au présent (affirmatif et négatif)","points":4},{"critere":"Prétérit de BE : was / were, wasn't / weren't, question","points":5},{"critere":"BE là où le français dit « avoir », avec justification","points":5},{"critere":"There are et BE + -ing","points":4},{"critere":"Orthographe et ponctuation","points":2}],"dureeMin":15,"corrige":"1. **Yesterday, I was ill.** (ou *I was sick.*) — prétérit : *was* avec I.\n2. **My parents weren't at home.** (ou *were not*) — *they* → *were* ; négation : *weren't*.\n3. **Were you at school?** — question par inversion, sans DO.\n4. **Today, I am 12 and I am not cold.** (ou *I'm 12 and I'm not cold* / *12 years old*) — âge et « avoir froid » : BE.\n5. **There are cakes on the table.** (*There are some cakes…* accepté) — pluriel : *there are*.\n6. **My sister is singing.** — présent BE + -ing (action en cours).\n\n**Justification attendue :** en anglais, l'âge (*I am 12*) et les sensations comme avoir froid (*be cold*) se disent avec BE, là où le français dit « avoir ». Dire « I have 12 » ou « I haven't cold » est faux."}$exo$::jsonb),
  ('304b7ac9-f45f-5390-be6a-50a0ffbafe37'::uuid, 1, 'traduction', $exo${"titre":"Ce que j'ai : have got et has got","consigne":"Traduis ces trois phrases du français vers l'anglais (thème) en employant have got.","enonce":"**Traduis en anglais avec *have got* :**\n\n1. J'ai un vélo.\n2. Elle a deux frères.\n3. Il n'a pas de chat.","bareme":[{"critere":"Choix de have got ou has got selon la personne","points":8},{"critere":"Forme négative sans DO","points":6},{"critere":"Vocabulaire et orthographe","points":6}],"dureeMin":6,"corrige":"1. **I have got a bike.** (ou *I've got a bike.*)\n2. **She has got two brothers.** (ou *She's got two brothers.*) — 3e personne : *has got*.\n3. **He hasn't got a cat.** (ou *He has not got a cat.*) — négation sans DO.\n\nLa consigne demande *have got* ; la forme américaine cohérente (*I have a bike / She has two brothers / He doesn't have a cat*) est correcte en anglais mais ne respecte pas la consigne (perte de points sur le premier critère seulement). À refuser : « He doesn't have got a cat » (mélange des deux formes), « She have got »."}$exo$::jsonb),
  ('304b7ac9-f45f-5390-be6a-50a0ffbafe37'::uuid, 2, 'traduction', $exo${"titre":"Portrait de Sam","consigne":"Traduis ce portrait de l'anglais vers le français (version). Attention : he's peut vouloir dire he is ou he has.","enonce":"**Traduis en français :**\n\n1. My best friend is called Sam.\n2. He's got blue eyes and brown hair.\n3. He's got a sister, but he hasn't got a brother.\n4. Have you got a dog?\n5. Sam's got a headache today.","bareme":[{"critere":"Compréhension de he's / Sam's = has (possession)","points":6},{"critere":"Traduction de la description physique","points":5},{"critere":"Traduction de la question et de la négation","points":5},{"critere":"Français correct et naturel","points":4}],"dureeMin":10,"corrige":"1. **Mon meilleur ami s'appelle Sam.**\n2. **Il a les yeux bleus et les cheveux bruns.** (*châtains* accepté) — *He's got* = *He has got* ; en français on dit « les yeux », pas « des yeux ».\n3. **Il a une sœur, mais il n'a pas de frère.** — *hasn't got* = négation de *has got*.\n4. **Est-ce que tu as un chien ?** (ou *As-tu un chien ?* / *Tu as un chien ?*)\n5. **Sam a mal à la tête aujourd'hui.** — *Sam's got* = *Sam has got* ; *a headache* = mal à la tête (la maladie).\n\nContresens à sanctionner : « Il est yeux bleus », « Sam est un mal de tête » (lire *'s* comme *is*)."}$exo$::jsonb),
  ('304b7ac9-f45f-5390-be6a-50a0ffbafe37'::uuid, 3, 'traduction', $exo${"titre":"Famille, maladie et souvenirs : have got et had","consigne":"Traduis ces phrases du français vers l'anglais (thème) avec have got au présent. Puis explique, pour ta phrase 6, ce que signifie chaque he's.","enonce":"**Traduis en anglais :**\n\n1. Est-ce que ta sœur a un téléphone ?\n2. Non, elle n'a pas de téléphone, mais elle a un ordinateur.\n3. Mes cousins ont un grand chien noir.\n4. Est-ce que tu as mal à la tête ?\n5. Quand j'avais dix ans, j'avais un lapin.\n6. Il est grand et il a les cheveux blonds. (utilise deux fois la contraction *he's*)\n\n**Question :** dans ta phrase 6, chaque *he's* veut-il dire *he is* ou *he has* ? Justifie.","bareme":[{"critere":"Have got / has got selon la personne","points":5},{"critere":"Question et négation sans DO","points":4},{"critere":"Prétérit had au lieu de have got","points":4},{"critere":"He's = he is ou he has, avec justification","points":4},{"critere":"Orthographe et ordre des mots","points":3}],"dureeMin":16,"corrige":"1. **Has your sister got a phone?** — question par inversion, sans DO.\n2. **No, she hasn't got a phone, but she has got a computer.** (ou *she's got a computer*) — *No, she hasn't.* seul est incomplet ici.\n3. **My cousins have got a big black dog.** — pluriel : *have got* ; les adjectifs se placent avant le nom (*big black dog*).\n4. **Have you got a headache?**\n5. **When I was ten, I had a rabbit.** — au passé, pas de « had got » : on emploie *had*.\n6. **He's tall and he's got blond hair.** (*fair hair* accepté)\n\n**Justification :** le premier *he's* = *he is*, car il est suivi d'un adjectif (*tall*) ; le second = *he has*, car il est suivi de *got* (possession, description).\n\nLa forme américaine (*Does your sister have a phone?*) est correcte mais ne suit pas la consigne ; ne jamais mélanger les deux dans une phrase (« Does she have got » est faux)."}$exo$::jsonb),
  ('34cc8b05-a7a8-5678-bf0b-538ba6111f77'::uuid, 1, 'traduction', $exo${"titre":"Questions et négations avec DO","consigne":"Traduis ces trois phrases du français vers l'anglais (thème) en utilisant l'auxiliaire DO.","enonce":"**Traduis en anglais :**\n\n1. Est-ce que tu aimes la pizza ?\n2. Je n'aime pas le poisson.\n3. Est-ce qu'il joue au football ?","bareme":[{"critere":"Question avec do / does","points":8},{"critere":"Négation avec don't","points":6},{"critere":"Base verbale après l'auxiliaire","points":6}],"dureeMin":6,"corrige":"1. **Do you like pizza?** — DO + sujet + base verbale.\n2. **I don't like fish.** (ou *I do not like fish.*) — pas d'article devant *fish* pour une généralité.\n3. **Does he play football?** — avec *does*, le verbe perd son -s : jamais « Does he plays ».\n\nPoints attendus : place de l'auxiliaire, *does* à la 3e personne, base verbale après l'auxiliaire."}$exo$::jsonb),
  ('34cc8b05-a7a8-5678-bf0b-538ba6111f77'::uuid, 2, 'traduction', $exo${"titre":"Le week-end de Léa : présent et passé avec DO","consigne":"Traduis ces phrases du français vers l'anglais (thème). Pour la phrase 2, réponds par une réponse courte.","enonce":"**Traduis en anglais :**\n\n1. Léa ne parle pas français.\n2. Est-ce que ton frère joue au tennis ? — Oui. *(réponse courte)*\n3. Je ne suis pas allé à l'école hier.\n4. Est-ce que tu as fait tes devoirs ?\n5. Non, je n'ai pas fait mes devoirs.","bareme":[{"critere":"Does / doesn't suivi de la base verbale","points":6},{"critere":"Did / didn't suivi de la base verbale","points":6},{"critere":"Réponse courte avec l'auxiliaire","points":4},{"critere":"Orthographe et ponctuation","points":4}],"dureeMin":11,"corrige":"1. **Léa doesn't speak French.** — jamais « doesn't speaks ».\n2. **Does your brother play tennis? — Yes, he does.** — réponse courte avec l'auxiliaire seul.\n3. **I didn't go to school yesterday.** — jamais « didn't went ».\n4. **Did you do your homework?** — premier *do* (did) = auxiliaire, second *do* = verbe « faire ».\n5. **No, I didn't do my homework.** (*No, I didn't.* accepté pour le début, mais la phrase complète est attendue)\n\nPoints attendus : un seul -s (sur *does*), passé marqué une seule fois (sur *did*), *French* avec majuscule."}$exo$::jsonb),
  ('34cc8b05-a7a8-5678-bf0b-538ba6111f77'::uuid, 3, 'traduction', $exo${"titre":"Le samedi de Ben : DO auxiliaire ou verbe ?","consigne":"Traduis ce dialogue de l'anglais vers le français (version), puis réponds aux deux questions d'analyse.","enonce":"**Traduis en français :**\n\n1. What do you do on Saturdays?\n2. I don't go to school, I play football with my friends.\n3. Does your sister play too?\n4. No, she doesn't. She plays the piano.\n5. Last Saturday, we didn't play: it was cold.\n6. Did you do your homework? — Yes, I did.\n\n**Questions :**\n- a) Dans les phrases 1 et 6, lequel des deux *do* est l'auxiliaire, lequel est le verbe « faire » ?\n- b) Pourquoi écrit-on *play* dans la phrase 3 mais *plays* dans la phrase 4 ?","bareme":[{"critere":"Traduction des questions et des négations","points":6},{"critere":"Traduction des réponses courtes","points":3},{"critere":"Identification de l'auxiliaire et du verbe « faire »","points":5},{"critere":"Explication du -s de la 3e personne","points":4},{"critere":"Français correct","points":2}],"dureeMin":17,"corrige":"**Traduction :**\n1. **Qu'est-ce que tu fais le samedi ?** (*Que fais-tu le samedi ?*)\n2. **Je ne vais pas à l'école, je joue au football avec mes amis.**\n3. **Est-ce que ta sœur joue aussi ?**\n4. **Non.** (ou *Non, elle ne joue pas.*) **Elle joue du piano.**\n5. **Samedi dernier, nous n'avons pas joué : il faisait froid.**\n6. **Est-ce que tu as fait tes devoirs ? — Oui.** (ou *Oui, je les ai faits.*)\n\n**a)** Phrase 1 : le premier *do* est l'auxiliaire (il fabrique la question), le second est le verbe « faire ». Phrase 6 : *did* est l'auxiliaire au prétérit, *do* est le verbe « faire » ; dans *Yes, I did*, *did* est l'auxiliaire seul de la réponse courte.\n\n**b)** Le -s de la 3e personne ne se met qu'une fois : dans la question (phrase 3), il est déjà sur *does*, donc le verbe reste à la base verbale *play* ; dans la phrase affirmative (phrase 4), il n'y a pas d'auxiliaire, donc le -s va sur le verbe : *plays*."}$exo$::jsonb),
  ('3171cbbc-b384-527f-84cd-0c41a199fa13'::uuid, 1, 'traduction', $exo${"titre":"CAN : savoir faire et demander","consigne":"Traduis ces trois phrases du français vers l'anglais (thème) avec le modal CAN.","enonce":"**Traduis en anglais :**\n\n1. Je sais nager.\n2. Il ne sait pas chanter.\n3. Est-ce que je peux sortir ?","bareme":[{"critere":"Can suivi de la base verbale sans to","points":8},{"critere":"Négation can't / cannot","points":6},{"critere":"Question par inversion","points":6}],"dureeMin":6,"corrige":"1. **I can swim.** — capacité ; « savoir nager » = *can swim*.\n2. **He can't sing.** (ou *He cannot sing.* en un seul mot) — pas de -s à *can*, pas de DO.\n3. **Can I go out?** — permission ; question par inversion.\n\nÀ refuser : « He cans », « can to swim », « He doesn't can sing », « Do I can go out? », « can not » en deux mots (toléré mais la forme attendue est *cannot*)."}$exo$::jsonb),
  ('3171cbbc-b384-527f-84cd-0c41a199fa13'::uuid, 2, 'traduction', $exo${"titre":"Hier et aujourd'hui : can et could","consigne":"Traduis ces phrases du français vers l'anglais (thème). Emploie could pour le passé.","enonce":"**Traduis en anglais :**\n\n1. Mon frère sait jouer du piano.\n2. Est-ce que tu peux m'aider, s'il te plaît ?\n3. Quand j'avais cinq ans, je savais nager.\n4. Ma sœur ne savait pas lire.\n5. Est-ce que je peux utiliser ton téléphone ?","bareme":[{"critere":"Les trois règles des modaux (pas de -s, pas de to, pas de DO)","points":6},{"critere":"Could et couldn't au passé","points":6},{"critere":"Capacité, permission et demande polie","points":4},{"critere":"Vocabulaire et orthographe","points":4}],"dureeMin":11,"corrige":"1. **My brother can play the piano.** — pas de « cans ».\n2. **Can you help me, please?** — demande ; *Could you help me, please?* (plus poli) est aussi accepté.\n3. **When I was five, I could swim.** (ou *I could swim when I was five.*) — passé de *can* : *could*.\n4. **My sister couldn't read.** (ou *could not read*)\n5. **Can I use your phone?** — permission ; *Could I use your phone?* accepté.\n\nÀ refuser : « didn't can », « could to swim », « Do you can »."}$exo$::jsonb),
  ('3171cbbc-b384-527f-84cd-0c41a199fa13'::uuid, 3, 'traduction', $exo${"titre":"Can, could, be able to : qui fait quoi ?","consigne":"Traduis ce texte de l'anglais vers le français (version), puis réponds aux questions d'analyse.","enonce":"**Traduis en français :**\n\n1. Can I go to the cinema tonight, Mum?\n2. No, you can't. You've got a test tomorrow.\n3. Could you help me with my homework, please?\n4. My grandfather could run fast when he was young.\n5. Now he can't run, but he can swim.\n6. My sister is seventeen: next year, she will be able to drive.\n\n**Questions :**\n- a) Pour chaque *can* ou *could* des phrases 1, 3, 4 et 5, indique l'emploi : capacité, permission, demande polie, ou capacité passée.\n- b) Pourquoi la phrase 6 emploie-t-elle *will be able to* et pas « will can » ?","bareme":[{"critere":"Traduction fidèle et en bon français","points":8},{"critere":"Identification des emplois de can","points":5},{"critere":"Distinction entre could passé et could poli","points":3},{"critere":"Justification de be able to","points":4}],"dureeMin":17,"corrige":"**Traduction :**\n1. **Est-ce que je peux aller au cinéma ce soir, maman ?**\n2. **Non, tu ne peux pas. Tu as un contrôle demain.**\n3. **Pourrais-tu m'aider pour mes devoirs, s'il te plaît ?** (*Est-ce que tu pourrais…* ; *Pourriez-vous* accepté)\n4. **Mon grand-père savait courir vite (courait vite) quand il était jeune.** (*pouvait courir vite* accepté)\n5. **Maintenant, il ne peut pas courir, mais il sait nager.** (*il peut nager* accepté)\n6. **Ma sœur a dix-sept ans : l'année prochaine, elle pourra conduire.** (*elle saura conduire* accepté)\n\n**a)** Phrase 1 : permission (et *can't* en phrase 2 : refus de la permission). Phrase 3 : demande polie (*could* au présent, plus poli que *can*). Phrase 4 : capacité passée (*could* = passé de *can*). Phrase 5 : capacité (*can't run*, *can swim*).\n\n**b)** *Can* n'a ni infinitif ni participe : on ne peut pas le mettre après *will*. Pour le futur, on emploie *be able to* : *will be able to drive*."}$exo$::jsonb),
  ('a535df67-d7d9-52cb-b4d0-8a1cdb8856af'::uuid, 1, 'traduction', $exo${"titre":"Must, mustn't et should","consigne":"Traduis ces trois phrases du français vers l'anglais (thème).","enonce":"**Traduis en anglais :**\n\n1. Tu dois porter un casque.\n2. Tu ne dois pas y aller : c'est interdit.\n3. Tu devrais dormir plus.","bareme":[{"critere":"Must suivi de la base verbale","points":7},{"critere":"Mustn't pour l'interdiction","points":7},{"critere":"Should pour le conseil","points":6}],"dureeMin":6,"corrige":"1. **You must wear a helmet.** — *must* + base verbale, sans *to*.\n2. **You mustn't go (there).** (ou *You must not go.*) — interdiction : *mustn't*. *You don't have to go* est un contresens (= tu n'es pas obligé).\n3. **You should sleep more.** — conseil : *should*, plus faible que *must*.\n\nÀ refuser : « must to wear », « You don't must go »."}$exo$::jsonb),
  ('a535df67-d7d9-52cb-b4d0-8a1cdb8856af'::uuid, 2, 'traduction', $exo${"titre":"Le règlement de mon collège","consigne":"Traduis ces phrases de l'anglais vers le français (version). Attention au sens de mustn't et de don't have to.","enonce":"**Traduis en français :**\n\n1. At my school, we have to wear a uniform.\n2. You mustn't run in the corridors.\n3. You don't have to eat at the canteen.\n4. I must call my grandmother tonight.\n5. Yesterday, I had to stay at home.","bareme":[{"critere":"Mustn't compris comme une interdiction","points":6},{"critere":"Don't have to compris comme une absence d'obligation","points":6},{"critere":"Had to traduit au passé","points":4},{"critere":"Français correct et naturel","points":4}],"dureeMin":11,"corrige":"1. **Dans mon collège, nous devons porter un uniforme.** (*nous sommes obligés de…*) — *have to* : règle extérieure.\n2. **Il est interdit de courir dans les couloirs.** (*Tu ne dois pas / Vous ne devez pas courir…* ; *Il ne faut pas courir…*) — *mustn't* = interdiction.\n3. **Tu n'es pas obligé de manger à la cantine.** (*Vous n'êtes pas obligés…*) — *don't have to* = c'est ton choix. « Tu ne dois pas manger à la cantine » est un contresens.\n4. **Je dois appeler ma grand-mère ce soir.** — *must* : obligation personnelle.\n5. **Hier, j'ai dû rester à la maison.** (*j'ai été obligé de…*) — *had to* = passé de *must*."}$exo$::jsonb),
  ('a535df67-d7d9-52cb-b4d0-8a1cdb8856af'::uuid, 3, 'traduction', $exo${"titre":"Interdit, obligatoire ou au choix ?","consigne":"Traduis ces phrases du français vers l'anglais (thème), puis justifie tes choix pour les phrases 1-2 et 3-4.","enonce":"**Traduis en anglais :**\n\n1. Tu ne dois pas toucher ce chien : c'est interdit !\n2. Demain, c'est samedi : tu n'es pas obligé de te lever tôt.\n3. Je dois ranger ma chambre. *(c'est moi qui le décide)*\n4. À l'école, nous devons arriver à 8 heures. *(c'est le règlement)*\n5. Hier, mon frère a dû faire ses devoirs.\n6. L'année prochaine, je devrai porter des lunettes.\n7. Tu devrais boire de l'eau.\n\n**Questions :**\n- a) Pourquoi emploies-tu deux formes différentes dans les phrases 1 et 2 ?\n- b) Pourquoi emploies-tu *must* dans une phrase et *have to* dans l'autre (phrases 3 et 4) ?","bareme":[{"critere":"Mustn't et don't have to, avec justification","points":5},{"critere":"Must et have to, avec justification","points":5},{"critere":"Had to et will have to","points":5},{"critere":"Should pour le conseil","points":2},{"critere":"Orthographe et ponctuation","points":3}],"dureeMin":18,"corrige":"1. **You mustn't touch this dog!** (*that dog* accepté)\n2. **Tomorrow is Saturday: you don't have to get up early.**\n3. **I must tidy my room.** (*clean my room* accepté)\n4. **At school, we have to arrive at 8 (o'clock).**\n5. **Yesterday, my brother had to do his homework.** — *must* n'a pas de passé.\n6. **Next year, I will have to wear glasses.** (*I'll have to*)\n7. **You should drink water.** (*some water* accepté)\n\n**a)** Phrase 1 : c'est interdit → *mustn't*. Phrase 2 : ce n'est pas obligatoire, c'est un choix → *don't have to*. Les deux formes ont des sens opposés.\n\n**b)** Phrase 3 : l'obligation vient de celui qui parle → *must*. Phrase 4 : l'obligation vient de l'extérieur (le règlement) → *have to*."}$exo$::jsonb),
  ('22657918-814e-598d-bbb8-af157046296e'::uuid, 1, 'traduction', $exo${"titre":"Mes habitudes au présent simple","consigne":"Traduis ces trois phrases du français vers l'anglais (thème) au présent simple.","enonce":"**Traduis en anglais :**\n\n1. Je vais à l'école tous les jours.\n2. Ma sœur aime le chocolat.\n3. Il regarde la télévision le lundi.","bareme":[{"critere":"Emploi du présent simple","points":8},{"critere":"Le -s de la 3e personne et son orthographe","points":8},{"critere":"Place du repère de temps","points":4}],"dureeMin":6,"corrige":"1. **I go to school every day.** — habitude ; *every day* en fin de phrase.\n2. **My sister likes chocolate.** — goût ; 3e personne : *likes*. Pas d'article devant *chocolate*.\n3. **He watches TV on Mondays.** (*television* accepté) — verbe en -ch → *-es* : *watches* ; *on Mondays* en fin de phrase.\n\nÀ refuser : « I am going to school every day », « My sister like », « He watchs »."}$exo$::jsonb),
  ('22657918-814e-598d-bbb8-af157046296e'::uuid, 2, 'traduction', $exo${"titre":"La famille de Hugo au quotidien","consigne":"Traduis ces phrases du français vers l'anglais (thème) au présent simple.","enonce":"**Traduis en anglais :**\n\n1. Mon père travaille à Paris.\n2. Son train part à 8 heures.\n3. Ma sœur étudie l'anglais.\n4. Elle joue souvent au tennis.\n5. Mon frère n'aime pas le football.","bareme":[{"critere":"Le -s de la 3e personne et l'orthographe en -ies","points":6},{"critere":"Place de often dans la phrase","points":4},{"critere":"Négation doesn't suivie de la base verbale","points":5},{"critere":"Vocabulaire et orthographe","points":5}],"dureeMin":11,"corrige":"1. **My father works in Paris.** (*My dad* accepté)\n2. **His train leaves at 8.** (*at 8 o'clock*) — horaire : présent simple.\n3. **My sister studies English.** — consonne + y → *-ies* ; *English* avec majuscule.\n4. **She often plays tennis.** — *often* avant le verbe ; pas de *the* devant le sport.\n5. **My brother doesn't like football.** (*does not like*) — le verbe perd son -s après *doesn't*.\n\nÀ refuser : « studys », « She plays often tennis », « doesn't likes »."}$exo$::jsonb),
  ('22657918-814e-598d-bbb8-af157046296e'::uuid, 3, 'traduction', $exo${"titre":"Léo à Londres : habitudes, vérités et moment présent","consigne":"Traduis ces phrases du français vers l'anglais (thème), puis réponds aux deux questions.","enonce":"**Traduis en anglais :**\n\n1. Mon cousin Léo habite à Londres.\n2. Il est toujours en retard.\n3. Il ne regarde jamais la télévision.\n4. Est-ce qu'il fait ses devoirs le soir ?\n5. L'eau bout à 100 degrés.\n6. En ce moment, il joue au tennis.\n\n**Questions :**\n- a) Pourquoi *always* n'a-t-il pas la même place dans ta phrase 2 que *never* dans ta phrase 3 ?\n- b) Pourquoi la phrase 6 n'est-elle pas au présent simple ?","bareme":[{"critere":"Présent simple et -s de la 3e personne","points":5},{"critere":"Question avec does et base verbale","points":4},{"critere":"Place des adverbes de fréquence, avec justification","points":4},{"critere":"Contraste présent simple / BE + -ing, avec justification","points":4},{"critere":"Orthographe et ponctuation","points":3}],"dureeMin":17,"corrige":"1. **My cousin Léo lives in London.**\n2. **He is always late.** — *always* après BE.\n3. **He never watches TV.** (*television*) — *never* avant le verbe ; *never* est déjà négatif, donc pas de *doesn't*.\n4. **Does he do his homework in the evening?** — *does* auxiliaire, *do* verbe « faire » à la base verbale.\n5. **Water boils at 100 degrees.** — vérité générale ; pas d'article devant *water*.\n6. **At the moment, he is playing tennis.** (*Right now* / *Now* accepté)\n\n**a)** Les adverbes de fréquence se placent avant le verbe (*never watches*), mais après BE (*is always*).\n\n**b)** Le présent simple dit ce qui est habituel ; la phrase 6 décrit une action en cours en ce moment, donc on emploie BE + -ing."}$exo$::jsonb),
  ('4f9b2dff-94d8-5018-88d3-15218116883f'::uuid, 1, 'traduction', $exo${"titre":"En ce moment : BE + -ING","consigne":"Traduis ces trois phrases du français vers l'anglais (thème) au présent en BE + -ing.","enonce":"**Traduis en anglais :**\n\n1. Je suis en train de travailler.\n2. Elle est en train de nager.\n3. Ils ne mangent pas en ce moment.","bareme":[{"critere":"BE conjugué au présent","points":7},{"critere":"Orthographe du -ing","points":7},{"critere":"Forme négative sans DO","points":6}],"dureeMin":6,"corrige":"1. **I am working.** (*I'm working.*)\n2. **She is swimming.** (*She's swimming.*) — *swim* : consonne-voyelle-consonne → on double le *m*.\n3. **They aren't eating at the moment.** (*They are not eating* / *They're not eating* ; *right now* accepté)\n\nÀ refuser : « swiming », « They don't eating »."}$exo$::jsonb),
  ('4f9b2dff-94d8-5018-88d3-15218116883f'::uuid, 2, 'traduction', $exo${"titre":"Une semaine chez ma tante","consigne":"Traduis ces phrases de l'anglais vers le français (version).","enonce":"**Traduis en français :**\n\n1. Look! It's raining.\n2. My mum is writing a letter and my dad is making a cake.\n3. I'm staying with my aunt this week.\n4. Are you watching TV? — No, I'm reading a book.\n5. We are meeting Tom at 6.","bareme":[{"critere":"Traduction des actions en cours","points":6},{"critere":"Traduction de l'action temporaire et du projet","points":6},{"critere":"Traduction de la question","points":4},{"critere":"Français correct et naturel","points":4}],"dureeMin":11,"corrige":"1. **Regarde ! Il pleut.** — action en cours.\n2. **Ma mère écrit une lettre et mon père fait un gâteau.** (*est en train d'écrire… est en train de faire…* accepté)\n3. **Je loge chez ma tante cette semaine.** (*Je reste chez ma tante…* / *Je suis chez ma tante…*) — action temporaire.\n4. **Est-ce que tu regardes la télé ? — Non, je lis un livre.** (*es-tu en train de regarder…* accepté)\n5. **Nous retrouvons Tom à 6 heures.** (*On retrouve / Nous avons rendez-vous avec Tom à 18 h* accepté) — projet déjà organisé : le français emploie aussi le présent (ou le futur proche *nous allons retrouver*).\n\nContresens à sanctionner : « nous rencontrons Tom tous les jours à 6 heures » (habitude)."}$exo$::jsonb),
  ('4f9b2dff-94d8-5018-88d3-15218116883f'::uuid, 3, 'traduction', $exo${"titre":"Chut, le bébé dort ! Présent simple ou -ING ?","consigne":"Traduis ces phrases du français vers l'anglais (thème), puis justifie tes choix pour les phrases 2 et 4.","enonce":"**Traduis en anglais :**\n\n1. Chut ! Le bébé dort.\n2. Je connais la réponse.\n3. Mon frère court dans le parc en ce moment.\n4. Je lis beaucoup de livres, mais en ce moment je lis un livre sur les chiens.\n5. Est-ce que tu es en train d'écrire à Julie ?\n6. Il perd toujours ses clés ! *(ça m'agace)*\n\n**Questions :**\n- a) Pourquoi la phrase 2 n'est-elle pas en BE + -ing ?\n- b) Pourquoi emploies-tu deux formes différentes du verbe *read* dans la phrase 4 ?","bareme":[{"critere":"Forme BE + -ing","points":4},{"critere":"Orthographe du -ing (doublement, e muet)","points":4},{"critere":"Verbe d'état sans -ing, avec justification","points":4},{"critere":"Contraste habitude / action en cours, avec justification","points":5},{"critere":"Question sans DO et emploi avec always","points":3}],"dureeMin":17,"corrige":"1. **Shh! The baby is sleeping.** (*Sh!* / *Be quiet!* accepté)\n2. **I know the answer.** — verbe d'état : jamais « I am knowing ».\n3. **My brother is running in the park at the moment.** — *run* → *running* (doublement).\n4. **I read a lot of books, but at the moment I am reading a book about dogs.** (*many books* accepté)\n5. **Are you writing to Julie?** — *write* → *writing* (e muet retiré) ; question sans DO.\n6. **He is always losing his keys!** — *always* + BE + -ing = irritation.\n\n**a)** *Know* est un verbe d'état (ce qu'on sait, pas ce qu'on fait) : il refuse la forme en -ing.\n\n**b)** *I read* (présent simple) dit une habitude, en général ; *I am reading* dit ce que je suis en train de faire en ce moment."}$exo$::jsonb),
  ('fbca82b1-9d7f-5da1-b5f3-ed6eaf7f9367'::uuid, 1, 'traduction', $exo${"titre":"Ce que j'ai fait : premiers prétérits","consigne":"Traduis ces trois phrases du français vers l'anglais (thème) au prétérit simple.","enonce":"**Traduis en anglais :**\n\n1. J'ai joué au football hier.\n2. Elle a étudié l'anglais.\n3. Nous sommes allés au cinéma la semaine dernière.","bareme":[{"critere":"Prétérit des verbes réguliers et orthographe du -ed","points":8},{"critere":"Prétérit irrégulier de go","points":6},{"critere":"Repères de temps","points":6}],"dureeMin":6,"corrige":"1. **I played football yesterday.** (*Yesterday, I played football.*) — voyelle + y : *played*.\n2. **She studied English.** — consonne + y → *-ied*.\n3. **We went to the cinema last week.** (*to the movies* accepté) — *go* → *went*.\n\nLe passé composé français se traduit ici par le prétérit, car l'action est terminée. À refuser : « I have played football yesterday », « studyed », « goed »."}$exo$::jsonb),
  ('fbca82b1-9d7f-5da1-b5f3-ed6eaf7f9367'::uuid, 2, 'traduction', $exo${"titre":"Une matinée pressée","consigne":"Traduis ces phrases du français vers l'anglais (thème) au prétérit simple.","enonce":"**Traduis en anglais :**\n\n1. Hier, je me suis levé, j'ai pris mon petit-déjeuner et je suis parti.\n2. Il y a deux jours, j'ai vu Tom.\n3. Est-ce que tu as mangé une pizza ?\n4. Non, je n'ai pas mangé de pizza, j'ai mangé une salade.\n5. Le bus s'est arrêté.","bareme":[{"critere":"Prétérit des verbes irréguliers","points":6},{"critere":"Did / didn't suivi de la base verbale","points":6},{"critere":"Orthographe du -ed (doublement)","points":4},{"critere":"Repères de temps, dont ago","points":4}],"dureeMin":12,"corrige":"1. **Yesterday, I got up, had breakfast and left.** — suite d'actions ; *get → got*, *have → had*, *leave → left*.\n2. **Two days ago, I saw Tom.** (*I saw Tom two days ago.*) — *ago* après la durée ; *see → saw*.\n3. **Did you eat a pizza?** — *did* + base verbale.\n4. **No, I didn't eat a pizza, I ate a salad.** (*No, I didn't. I ate a salad.* accepté) — jamais « didn't ate ».\n5. **The bus stopped.** — *stop* : consonne-voyelle-consonne → on double le *p*.\n\nÀ refuser : « Did you ate », « stoped », « There is two days »."}$exo$::jsonb),
  ('fbca82b1-9d7f-5da1-b5f3-ed6eaf7f9367'::uuid, 3, 'traduction', $exo${"titre":"Retour au village : prétérit et prononciation","consigne":"Traduis ce texte de l'anglais vers le français (version), puis réponds aux trois questions.","enonce":"**Traduis en français :**\n\n1. When I was young, I lived in a small village.\n2. Every Sunday, I played football with my friends.\n3. Last summer, I went back to the village.\n4. I looked at my old school, but I didn't see my friends.\n5. Did they leave? Yes, they moved to London in 2020.\n6. I wanted to stay, but we took the train home in the evening.\n\n**Questions :**\n- a) Donne la base verbale de *went*, *took* et *was*.\n- b) Classe *lived*, *played*, *looked*, *moved*, *wanted* selon la prononciation du -ed : /t/, /d/ ou /ɪd/.\n- c) Pourquoi écrit-on *didn't see* et non « didn't saw » ?","bareme":[{"critere":"Traduction au passé (passé composé ou imparfait selon le sens)","points":7},{"critere":"Base verbale des irréguliers","points":4},{"critere":"Prononciation du -ed","points":5},{"critere":"Explication de didn't + base verbale","points":4}],"dureeMin":18,"corrige":"**Traduction :**\n1. **Quand j'étais jeune, j'habitais dans un petit village.**\n2. **Tous les dimanches, je jouais au football avec mes amis.** — habitude passée : imparfait en français.\n3. **L'été dernier, je suis retourné au village.**\n4. **J'ai regardé mon ancienne école, mais je n'ai pas vu mes amis.**\n5. **Est-ce qu'ils sont partis ? Oui, ils ont déménagé à Londres en 2020.** (*Étaient-ils partis ?* accepté)\n6. **Je voulais rester, mais nous avons pris le train pour rentrer le soir.** (*nous sommes rentrés en train le soir* accepté)\n\n**a)** went → *go* ; took → *take* ; was → *be*.\n\n**b)** /t/ : *looked* (son sourd k). /d/ : *lived*, *played*, *moved* (sons sonores). /ɪd/ : *wanted* (après un t).\n\n**c)** Le passé n'est marqué qu'une fois dans la phrase : il est déjà sur l'auxiliaire *didn't*, donc le verbe revient à la base verbale *see*."}$exo$::jsonb),
  ('1fa9acb6-b9d3-58e4-a5bb-1aee662876a6'::uuid, 1, 'traduction', $exo${"titre":"Reconnaître les verbes irréguliers","consigne":"Traduis ces trois phrases de l'anglais vers le français (version), puis donne la base verbale de chaque verbe.","enonce":"**Traduis en français :**\n\n1. I bought a book.\n2. She wrote a letter.\n3. We drank orange juice.\n\n**Puis :** donne la base verbale de *bought*, *wrote* et *drank*.","bareme":[{"critere":"Sens des prétérits irréguliers","points":8},{"critere":"Base verbale des trois verbes","points":6},{"critere":"Français correct au passé","points":6}],"dureeMin":6,"corrige":"1. **J'ai acheté un livre.**\n2. **Elle a écrit une lettre.**\n3. **Nous avons bu du jus d'orange.** (*On a bu* accepté)\n\n(L'imparfait *j'achetais…* est un contresens de temps : ici, action terminée.)\n\nBases verbales : *bought* → **buy** ; *wrote* → **write** ; *drank* → **drink**."}$exo$::jsonb),
  ('1fa9acb6-b9d3-58e4-a5bb-1aee662876a6'::uuid, 2, 'traduction', $exo${"titre":"Une journée au prétérit irrégulier","consigne":"Traduis ces phrases du français vers l'anglais (thème). Tous les verbes sont irréguliers.","enonce":"**Traduis en anglais :**\n\n1. Hier, j'ai mangé une pomme et j'ai bu de l'eau.\n2. Mon père a acheté un vélo.\n3. Ma sœur a chanté une chanson.\n4. Nous avons trouvé un chat.\n5. Il a dit « bonjour ».","bareme":[{"critere":"Prétérits irréguliers (ate, drank, bought, found, said)","points":10},{"critere":"Famille -i → -a → -u (sing)","points":4},{"critere":"Vocabulaire et orthographe","points":6}],"dureeMin":10,"corrige":"1. **Yesterday, I ate an apple and drank water.** (*and I drank some water* accepté) — *eat → ate*, *drink → drank* ; *an* devant *apple*.\n2. **My father bought a bike.** (*My dad* ; *a bicycle* accepté) — *buy → bought*.\n3. **My sister sang a song.** — *sing → sang* (famille *drink — drank — drunk*).\n4. **We found a cat.** — *find → found*.\n5. **He said hello.** (*He said « hello ».* accepté) — *say → said*.\n\nÀ refuser : « eated », « buyed », « singed », « sung » (participe passé, pas prétérit), « drunk » à la place de *drank*."}$exo$::jsonb),
  ('1fa9acb6-b9d3-58e4-a5bb-1aee662876a6'::uuid, 3, 'traduction', $exo${"titre":"Familles de verbes et piège de READ","consigne":"Traduis ces phrases du français vers l'anglais (thème), puis réponds aux deux questions.","enonce":"**Traduis en anglais :**\n\n1. La semaine dernière, j'ai lu un livre.\n2. Mon oncle m'a donné un cadeau.\n3. J'ai pensé à toi.\n4. Tom a apporté un gâteau et nous l'avons coupé.\n5. Ils sont venus et ils ont nagé dans la mer.\n6. Elle a posé son sac sur la table.\n\n**Questions :**\n- a) Classe *brought*, *thought*, *cut*, *put*, *swam* dans leur famille : « les trois pareils », « les deux derniers pareils » ou « -i → -a → -u ». Donne à chaque fois les trois formes.\n- b) Dans la phrase 1, *read* s'écrit comme au présent. Qu'est-ce qui change ?","bareme":[{"critere":"Prétérits irréguliers dans les phrases","points":7},{"critere":"Classement dans les familles avec les trois formes","points":5},{"critere":"Piège de read (prononciation)","points":4},{"critere":"Vocabulaire, orthographe et ponctuation","points":4}],"dureeMin":17,"corrige":"1. **Last week, I read a book.** — prononcé /red/.\n2. **My uncle gave me a present.** (*a gift* accepté) — *give → gave*.\n3. **I thought of you.** (*I thought about you.* accepté) — *think → thought*.\n4. **Tom brought a cake and we cut it.** — *bring → brought* ; *cut → cut*.\n5. **They came and swam in the sea.** (*and they swam*) — *come → came* ; *swim → swam*.\n6. **She put her bag on the table.** — *put → put*.\n\n**a)** Les trois pareils : *cut — cut — cut*, *put — put — put*. Les deux derniers pareils : *bring — brought — brought*, *think — thought — thought*. -i → -a → -u : *swim — swam — swum*.\n\n**b)** *Read* s'écrit pareil, mais se prononce /riːd/ au présent et /red/ au passé : seule la prononciation change."}$exo$::jsonb),
  ('f7b07e0b-039e-5987-98a6-0612beb468bc'::uuid, 1, 'traduction', $exo${"titre":"Parler de demain : going to et will","consigne":"Traduis ces trois phrases du français vers l'anglais (thème).","enonce":"**Traduis en anglais :**\n\n1. Je vais étudier ce soir. *(c'est décidé)*\n2. Je t'aiderai. *(c'est une promesse)*\n3. Il ne viendra pas demain.","bareme":[{"critere":"Be going to pour l'intention","points":7},{"critere":"Will et won't suivis de la base verbale","points":7},{"critere":"Orthographe et repères de temps","points":6}],"dureeMin":6,"corrige":"1. **I am going to study tonight.** (*I'm going to study…*) — intention déjà décidée : *be going to*.\n2. **I will help you.** (*I'll help you.*) — promesse : *will*.\n3. **He won't come tomorrow.** (*He will not come tomorrow.*) — négation : *won't* + base verbale.\n\nÀ refuser : « I go to study », « I will to help », « He doesn't will come »."}$exo$::jsonb),
  ('f7b07e0b-039e-5987-98a6-0612beb468bc'::uuid, 2, 'traduction', $exo${"titre":"Nuages, téléphone et rendez-vous","consigne":"Traduis ces phrases du français vers l'anglais (thème). Choisis la forme du futur adaptée à chaque situation.","enonce":"**Traduis en anglais :**\n\n1. Regarde ces nuages : il va pleuvoir.\n2. Le téléphone sonne : je vais répondre. *(décision prise à l'instant)*\n3. Je retrouve Tom à 6 heures demain. *(c'est organisé)*\n4. Le film commence à 8 heures.\n5. Je pense qu'il fera beau demain.","bareme":[{"critere":"Going to pour une prévision fondée sur un indice","points":5},{"critere":"Will pour la décision immédiate et la prédiction","points":6},{"critere":"Présent en BE + -ing et présent simple pour le futur","points":5},{"critere":"Orthographe et ponctuation","points":4}],"dureeMin":12,"corrige":"1. **Look at those clouds: it is going to rain.** (*it's going to rain*) — indice visible.\n2. **The phone is ringing: I'll answer it.** (*I will answer it*) — décision prise à l'instant : *will*, même si le français dit « je vais ».\n3. **I am meeting Tom at 6 tomorrow.** (*I'm meeting Tom at 6 o'clock tomorrow.*) — rendez-vous organisé : BE + -ing.\n4. **The film starts at 8.** (*The movie* ; *at 8 o'clock*) — horaire : présent simple.\n5. **I think it will be sunny tomorrow.** (*it'll be sunny* ; *the weather will be nice* accepté) — prédiction, opinion : *will*.\n\nÀ refuser : « I'm going to answer it » en 2 (la décision n'était pas prise avant). En 1, « it will rain » est de l'anglais correct mais ne tient pas compte de l'indice visible : perte partielle de points."}$exo$::jsonb),
  ('f7b07e0b-039e-5987-98a6-0612beb468bc'::uuid, 3, 'traduction', $exo${"titre":"Projets de famille : quel futur, et pourquoi ?","consigne":"Traduis ce dialogue de l'anglais vers le français (version), puis justifie la forme du futur employée dans les phrases 1, 3 et 6.","enonce":"**Traduis en français :**\n\n1. My sister is going to study medicine.\n2. Next week, we are meeting our cousins in London.\n3. The train leaves at 7 tomorrow morning.\n4. Are you going to come with us?\n5. No, I won't come: I'm tired.\n6. OK, I'll bring you a present!\n\n**Question :** pour les phrases 1, 3 et 6, explique pourquoi l'anglais emploie *going to*, le présent simple, puis *will*.","bareme":[{"critere":"Traduction fidèle et en bon français","points":8},{"critere":"Justification de going to","points":4},{"critere":"Justification du présent simple pour un horaire","points":4},{"critere":"Justification de will","points":4}],"dureeMin":18,"corrige":"**Traduction :**\n1. **Ma sœur va faire des études de médecine.** (*va étudier la médecine*)\n2. **La semaine prochaine, nous retrouvons nos cousins à Londres.** (*nous allons retrouver* accepté)\n3. **Le train part à 7 heures demain matin.**\n4. **Est-ce que tu vas venir avec nous ?** (*Tu viens avec nous ?* accepté)\n5. **Non, je ne viendrai pas : je suis fatigué(e).**\n6. **D'accord, je te rapporterai un cadeau !** (*je vais te rapporter* accepté)\n\n**Justifications :**\n- Phrase 1 : *going to* exprime une intention déjà décidée : le projet existe avant qu'on en parle.\n- Phrase 3 : le présent simple sert pour les horaires (trains, avions, cinémas).\n- Phrase 6 : *will* ('ll) exprime une décision prise à l'instant, en réaction à la réponse précédente ; c'est aussi une forme de promesse.\n\n(La phrase 2 emploie BE + -ing pour un rendez-vous organisé.)"}$exo$::jsonb),
  ('ac165b13-446f-5097-bc4c-887ba7eef21e'::uuid, 1, 'redaction', $exo${"titre":"Le vers, la strophe et la rime dans un quatrain","consigne":"Lis attentivement le petit poème, puis réponds à chaque question par une phrase complète.","enonce":"Lis ce poème.\n\n> La lune glisse sur le toit,\n> Le chat la suit d’un pas léger ;\n> Elle se pose au bout d’un doigt,\n> Puis s’endort au fond du verger.\n\n1. Découpe le premier vers en syllabes (en les séparant par des tirets), puis donne leur nombre. Comment appelle-t-on un vers de cette longueur ?\n2. Combien de vers compte cette strophe ? Donne le nom de ce type de strophe.\n3. Relève les mots qui riment à la fin des vers. Écris le schéma des rimes avec des lettres (A, B…) et donne le nom de cette disposition.","bareme":[{"critere":"Découpage juste du vers 1, compte de 8 syllabes et nom « octosyllabe »","points":8},{"critere":"Strophe de 4 vers identifiée comme un quatrain","points":4},{"critere":"Rimes relevées, schéma ABAB et nom « rimes croisées »","points":8}],"dureeMin":7,"corrige":"1. La-lu-ne-glis-se-sur-le-toit : **8 syllabes**. Le *e* de « lune » et celui de « glisse » se prononcent, car ils sont suivis d’une consonne. Un vers de 8 syllabes est un **octosyllabe** (tous les vers du poème en sont).\n\n2. La strophe compte **4 vers** : c’est un **quatrain**.\n\n3. Les mots à la rime sont : toit (A), léger (B), doigt (A), verger (B). « Toit » et « doigt » riment en [wa] ; « léger » et « verger » riment en [é]. Le schéma est **ABAB** : ce sont des **rimes croisées**.\n\nOn accepte « rimes alternées » si l’élève donne bien le schéma ABAB, mais le terme du cours est « croisées »."}$exo$::jsonb),
  ('ac165b13-446f-5097-bc4c-887ba7eef21e'::uuid, 2, 'redaction', $exo${"titre":"Comparaison, métaphore ou personnification ?","consigne":"Identifie l’image utilisée dans chaque phrase en justifiant ta réponse, puis transforme et invente des images.","enonce":"Voici cinq phrases.\n\na. Les étoiles sont des lanternes accrochées au ciel.\nb. La rivière chante sous le pont.\nc. Ses yeux brillent comme deux étoiles.\nd. Le brouillard, semblable à un drap blanc, couvre la vallée.\ne. La nuit venue, la forêt respire doucement.\n\n1. Pour chaque phrase, dis s’il s’agit d’une **comparaison**, d’une **métaphore** ou d’une **personnification**. Justifie chaque fois ta réponse (relève l’outil de comparaison s’il y en a un, ou le mot qui prête un trait humain).\n2. Réécris les phrases **c** et **d** pour transformer chaque comparaison en métaphore.\n3. Écris deux phrases sur la mer : la première doit contenir une comparaison, la seconde une personnification. Souligne (entoure de *) le mot qui crée l’image.","bareme":[{"critere":"Identification juste des cinq images","points":6},{"critere":"Justifications précises (outil de comparaison, trait humain)","points":5},{"critere":"Transformation correcte des deux comparaisons en métaphores","points":4},{"critere":"Invention d’une comparaison et d’une personnification correctes sur la mer","points":5}],"dureeMin":10,"corrige":"1.\n- a. **Métaphore** : les étoiles sont rapprochées de lanternes **sans outil** de comparaison (verbe « sont »).\n- b. **Personnification** : la rivière « chante », une action humaine.\n- c. **Comparaison** : les yeux et les étoiles sont rapprochés par l’outil **« comme »**.\n- d. **Comparaison** : le brouillard et le drap sont rapprochés par l’outil **« semblable à »**.\n- e. **Personnification** : la forêt « respire », comme un être vivant qui dort.\n\n2. Exemples de réponses :\n- c. Ses yeux sont deux étoiles.\n- d. Le brouillard, ce drap blanc, couvre la vallée. (ou : Le brouillard est un drap blanc qui couvre la vallée.)\nL’essentiel : l’outil de comparaison (« comme », « semblable à ») a disparu.\n\n3. Exemples :\n- La mer est bleue *comme* un ciel d’été. (comparaison avec « comme », « tel » ou « semblable à »)\n- La mer *gronde* et *se fâche* contre les rochers. (personnification : colère humaine prêtée à la mer)\n\nOn valorise toute phrase correcte dont l’image est bien construite et bien identifiée. Une « comparaison » sans outil est une erreur."}$exo$::jsonb),
  ('ac165b13-446f-5097-bc4c-887ba7eef21e'::uuid, 3, 'redaction', $exo${"titre":"Analyser un poème nocturne : vers, rimes, images et sons","consigne":"Analyse le poème en répondant aux questions avec des phrases complètes et des citations, puis écris à ton tour deux vers ou deux phrases poétiques.","enonce":"Lis ce poème.\n\n> Le vent siffle et s’enfuit sur les champs endormis,\n> La lune est un miroir posé sur l’eau qui dort ;\n> Les arbres, tels des rois, lèvent leurs bras amis,\n> Et la nuit, doucement, verse sa poudre d’or.\n\n1. Compte les syllabes du vers 4 en les séparant par des tirets. Quel est le nom de ce vers ? Quel est le nom de cette strophe ?\n2. Donne le schéma des rimes et le nom de leur disposition.\n3. Relève dans le poème **une comparaison**, **une métaphore** et **une personnification**. Pour chacune, explique comment tu l’as reconnue.\n4. Au vers 1, quels sons de consonnes se répètent ? Comment s’appelle ce procédé ? Que semble-t-il imiter ?\n5. À ton tour, écris deux vers (ou deux phrases poétiques) sur le lever du soleil : le premier doit contenir une **métaphore**, le second une **personnification**.","bareme":[{"critere":"Vers et strophe : 12 syllabes, alexandrin, quatrain","points":4},{"critere":"Rimes : schéma ABAB, rimes croisées","points":3},{"critere":"Trois images relevées et justifiées","points":6},{"critere":"Allitération en [s] et [f] identifiée et son effet expliqué","points":3},{"critere":"Écriture : une métaphore et une personnification correctes","points":4}],"dureeMin":18,"corrige":"1. Et-la-nuit-dou-ce-ment-ver-se-sa-pou-dre-d’or : **12 syllabes** (les *e* de « doucement », « verse » et « poudre » se prononcent car ils sont suivis d’une consonne). C’est un **alexandrin**. Les quatre vers forment un **quatrain**.\n\n2. endormis (A) / dort (B) / amis (A) / d’or (B) : schéma **ABAB**, **rimes croisées**.\n\n3.\n- **Comparaison** : « Les arbres, tels des rois » – les arbres sont rapprochés des rois grâce à l’outil **« tels »**.\n- **Métaphore** : « La lune est un miroir » – la lune est rapprochée d’un miroir **sans outil** de comparaison. (On accepte aussi « sa poudre d’or » pour la lumière des étoiles.)\n- **Personnification** : « l’eau qui dort », « les champs endormis », « lèvent leurs bras amis » ou « la nuit […] verse » – on prête à des choses des actions ou des traits humains (dormir, avoir des bras, être amical, verser).\n\n4. Les sons **[s]** et **[f]** se répètent : « siffle », « s’enfuit », « sur ». C’est une **allitération** (répétition de consonnes). Elle imite le **sifflement du vent** qui passe sur les champs.\n\n5. Exemples :\n- Le soleil est une orange posée sur la colline. (métaphore, sans outil)\n- Le matin ouvre les yeux et sourit aux maisons. (personnification)\n\nOn valorise l’exactitude du vocabulaire (comparaison ≠ métaphore), les citations entre guillemets et, en écriture, des images originales et correctement construites."}$exo$::jsonb),
  ('64df3209-e4e8-548e-a89f-fb120625e366'::uuid, 1, 'redaction', $exo${"titre":"Repérer les marques du lyrisme","consigne":"Lis le poème, puis relève les marques du lyrisme demandées en répondant par des phrases complètes.","enonce":"Lis ce poème.\n\n> Ô mer, ma vieille amie, que j’aime ton murmure !\n> Je t’écoute le soir, assis sur les rochers,\n> Et mon cœur plein de joie oublie tous ses chagrins.\n\n1. Relève tous les mots qui montrent que le poète parle à la **première personne**.\n2. Relève l’**apostrophe** (le passage où le poète s’adresse directement à quelqu’un ou à quelque chose) et la phrase **exclamative**.\n3. Relève trois mots qui appartiennent au **champ lexical du sentiment**. Quel sentiment le poète exprime-t-il surtout ?","bareme":[{"critere":"Marques de la première personne relevées","points":6},{"critere":"Apostrophe et exclamation identifiées","points":6},{"critere":"Champ lexical du sentiment et sentiment dominant","points":8}],"dureeMin":6,"corrige":"1. Première personne : **ma** (ma vieille amie), **j’** (j’aime), **Je** (Je t’écoute), **mon** (mon cœur).\n\n2. L’apostrophe est **« Ô mer, ma vieille amie »** : le poète s’adresse directement à la mer, comme à une personne. La phrase exclamative est **« Ô mer, ma vieille amie, que j’aime ton murmure ! »** (elle se termine par un point d’exclamation).\n\n3. Champ lexical du sentiment : **aime**, **cœur**, **joie**, **chagrins** (on accepte aussi « amie »). Le poète exprime surtout **la joie et l’amour** de la mer : elle le console, puisqu’à son écoute il « oublie tous ses chagrins ».\n\nOn valorise les réponses rédigées et les citations exactes entre guillemets."}$exo$::jsonb),
  ('64df3209-e4e8-548e-a89f-fb120625e366'::uuid, 2, 'redaction', $exo${"titre":"Le regard du poète : une flaque devenue ciel","consigne":"Lis ce poème en prose, explique comment le poète transforme un objet banal, puis transforme à ton tour un objet du quotidien.","enonce":"Lis ce texte.\n\n> Après l’averse, au milieu de la cour, il reste une flaque. Personne ne la regarde. Moi, je m’arrête : c’est un morceau de ciel tombé sur le bitume ! Les nuages y passent comme des bateaux lents, et le soleil y allume une étoile d’or. Ô petite flaque, tu es un miroir pour les oiseaux ! Demain tu auras disparu, et j’en suis déjà triste.\n\n1. Quel objet banal le poète regarde-t-il ? Relève la phrase qui montre que les autres ne le remarquent pas.\n2. Relève deux images qui transforment cet objet en quelque chose d’extraordinaire, et dis pour chacune si c’est une comparaison ou une métaphore.\n3. Quels sentiments le poète exprime-t-il au début et à la fin du texte ? Justifie avec des mots du texte.\n4. À ton tour, choisis un objet banal (un caillou, une feuille morte, une tasse…) et écris deux ou trois phrases à la première personne qui le rendent extraordinaire grâce à au moins une image.","bareme":[{"critere":"Objet banal identifié avec la phrase justificative","points":3},{"critere":"Deux images relevées et correctement nommées","points":6},{"critere":"Sentiments identifiés et justifiés par le texte","points":5},{"critere":"Court écrit lyrique : première personne et image réussie","points":6}],"dureeMin":12,"corrige":"1. Le poète regarde une **flaque** d’eau laissée par la pluie dans la cour. La phrase « **Personne ne la regarde.** » montre que les autres ne la remarquent pas : c’est le **regard** du poète qui la rend extraordinaire, pas la flaque elle-même.\n\n2. Images possibles :\n- « c’est un morceau de ciel tombé sur le bitume » : **métaphore** (pas d’outil de comparaison) ;\n- « Les nuages y passent comme des bateaux lents » : **comparaison** (outil « comme ») ;\n- « tu es un miroir pour les oiseaux » : **métaphore** ;\n- « le soleil y allume une étoile d’or » : métaphore (le reflet devient une étoile) ; on accepte aussi personnification (le soleil « allume »).\n\n3. Au début, le poète exprime l’**émerveillement** et la joie : il « s’arrête », emploie une exclamation (« c’est un morceau de ciel tombé sur le bitume ! ») et une apostrophe (« Ô petite flaque »). À la fin, il exprime la **tristesse** : « j’en suis déjà triste », car la flaque aura disparu demain.\n\n4. Exemple : « Ce matin, j’ai ramassé un caillou gris. Dans ma main, c’est une planète minuscule, avec ses montagnes et ses cratères. Je le garde contre moi comme un trésor ! »\nÉléments valorisés : la première personne, une image correcte (métaphore ou comparaison), une émotion exprimée (exclamation, mots du sentiment)."}$exo$::jsonb),
  ('64df3209-e4e8-548e-a89f-fb120625e366'::uuid, 3, 'redaction', $exo${"titre":"Un poème qui chante : refrain, sons et lyrisme","consigne":"Analyse la musique et le lyrisme de ce poème en justifiant tes réponses par des citations, puis explique comment tu le dirais à voix haute.","enonce":"Lis ce poème.\n\n> Il pleut, il pleut sur la ville,\n> Tic, tac, tic, sur les toits gris ;\n> Il pleut, il pleut sur la ville,\n> Et mon cœur est tout petit.\n>\n> Les passants pressent le pas,\n> Les parapluies font des fleurs ;\n> Il pleut, il pleut sur la ville,\n> Et je chante pour mon cœur.\n\n1. Relève le vers qui revient plusieurs fois. Comment appelle-t-on cette répétition dans une chanson ? Quel effet produit-elle ?\n2. Relève deux passages où les sons imitent la pluie. Comment s’appelle ce procédé ? Explique ce que l’on entend.\n3. Relève deux marques du lyrisme. Quel sentiment le poète exprime-t-il au début, et comment ce sentiment change-t-il à la fin ?\n4. Relève une métaphore dans la deuxième strophe et explique-la.\n5. Pourquoi peut-on dire que ce poème ressemble à une chanson ? Appuie-toi sur l’origine du mot « lyrique ». Puis explique en deux ou trois phrases comment tu dirais ce poème à voix haute.","bareme":[{"critere":"Refrain identifié et effet expliqué","points":4},{"critere":"Harmonie imitative repérée et expliquée","points":4},{"critere":"Marques du lyrisme et évolution du sentiment","points":4},{"critere":"Métaphore relevée et expliquée","points":3},{"critere":"Lien poésie-chanson et conseils de diction justifiés","points":5}],"dureeMin":20,"corrige":"1. Le vers « **Il pleut, il pleut sur la ville** » revient trois fois (vers 1, 3 et 7). C’est un **refrain**. Il installe une **mélodie** et imite la pluie qui ne s’arrête pas ; le poème semble se chanter.\n\n2. « **Tic, tac, tic** » : ces petits mots imitent le bruit des gouttes sur les toits. « **Les passants pressent le pas, / Les parapluies** » : la répétition du son **[p]** (allitération) fait entendre les gouttes qui tapent ou les pas pressés. On peut aussi citer la répétition de « il pleut, il pleut ». Ce procédé, où les sonorités imitent le réel, s’appelle l’**harmonie imitative**.\n\n3. Marques du lyrisme : la **première personne** (« mon cœur », « je chante ») et le **champ lexical du sentiment** (« cœur »). On accepte aussi le refrain comme musique lyrique. Au début, le poète est **triste** : « mon cœur est tout petit » (il se sent serré, abattu). À la fin, il se **console** : « je chante pour mon cœur » ; le chant l’aide à supporter la pluie.\n\n4. « **Les parapluies font des fleurs** » : les parapluies ouverts, ronds et colorés, sont vus comme des fleurs, sans outil de comparaison. Le regard du poète transforme un objet banal en quelque chose de beau.\n\n5. Le mot « lyrique » vient de la **lyre**, l’instrument d’Orphée : à l’origine, le poème se chantait. Ce poème ressemble à une chanson car il a un **refrain**, des **rimes** (gris / petit, fleurs / cœur) et des **images**, les mêmes outils que ceux d’une chanson.\nPour le dire : je **respecterais les pauses** (aux virgules et à la fin des vers), je **détacherais les images** (« Les parapluies font des fleurs ») et je **varierais le volume** : plus bas et lent pour « mon cœur est tout petit », plus léger et rythmé pour « Tic, tac, tic ».\n\nOn valorise les citations exactes et les explications reliées au sens du poème."}$exo$::jsonb),
  ('5a396493-5b55-5ed9-8879-3481b3d8fdda'::uuid, 1, 'redaction', $exo${"titre":"Roubaud et l’Oulipo : les notions clés","consigne":"Réponds à chaque question par une ou deux phrases complètes, en t’appuyant sur ce que tu as appris.","enonce":"1. Qui a écrit **Les Animaux de tout le monde** et en quelle année ? Comment ce recueil est-il construit ?\n2. Que signifient les lettres **OULIPO** ? Explique en une phrase ce que font les écrivains de ce groupe.\n3. Le mot « **ani-mots** » est un **mot-valise**. Quels sont les deux mots qui le composent ? Explique ce qu’est un mot-valise.\n4. *Sardine* et *sourdine* sont des **paronymes**. Explique ce mot, puis trouve un autre couple de paronymes (qui peut concerner un animal).","bareme":[{"critere":"Auteur, date et construction du recueil","points":4},{"critere":"Sens du sigle OULIPO et principe de la contrainte","points":5},{"critere":"Mot-valise expliqué et décomposé","points":5},{"critere":"Paronymie définie et nouvel exemple juste","points":6}],"dureeMin":8,"corrige":"1. **Les Animaux de tout le monde** a été écrit par **Jacques Roubaud** en **1990**. Chaque poème est consacré à **un animal** (de la sardine au morse) ; ce sont des poèmes courts et drôles où l’animal sert de prétexte à jouer avec la langue.\n\n2. OULIPO signifie **OUvroir de LIttérature POtentielle**. C’est un groupe d’écrivains qui s’imposent des **contraintes volontaires** pour écrire (par exemple ne jamais employer la lettre *e*) : la contrainte les oblige à trouver des idées qu’ils n’auraient pas cherchées.\n\n3. « Ani-mots » est formé de **animaux** et de **mots**. Un mot-valise est un mot inventé qui **fond deux mots en un** : ici, il dit que les animaux du recueil sont aussi des jeux de mots.\n\n4. Des **paronymes** sont des mots qui **se ressemblent** par leurs sons ou leur orthographe mais n’ont pas le même sens. Exemples acceptés : *baleine* / *haleine*, *poisson* / *poison*, *loup* / *loupe*, *chameau* / *chapeau*…\n\nOn refuse un couple de mots identiques (homonymes parfaits) ou sans ressemblance."}$exo$::jsonb),
  ('5a396493-5b55-5ed9-8879-3481b3d8fdda'::uuid, 2, 'redaction', $exo${"titre":"Reconnaître les jeux de langue d’un poète animalier","consigne":"Identifie le jeu de langue de chaque phrase en justifiant, explique un détournement, puis invente un mot-valise.","enonce":"Voici quatre phrases écrites à la manière de Jacques Roubaud.\n\na. Le **hérissonge** est un hérisson qui passe ses nuits à faire des songes.\nb. Qui vole un bœuf a très mal au dos.\nc. Après sa longue plongée, la baleine a perdu haleine.\nd. Le ver de terre boit un verre d’eau.\n\n1. Pour chaque phrase, nomme le jeu de langue utilisé : **calembour**, **mot-valise**, **paronymie** ou **détournement**. Justifie ta réponse.\n2. La phrase **b** détourne un proverbe. Écris le proverbe d’origine. Explique ensuite pourquoi la nouvelle phrase fait rire.\n3. Invente à ton tour un **mot-valise** qui désigne un animal imaginaire. Écris une phrase qui le définit, en montrant les deux mots qui le composent.","bareme":[{"critere":"Identification juste des quatre jeux de langue","points":6},{"critere":"Justifications précises","points":4},{"critere":"Proverbe retrouvé et effet comique expliqué","points":5},{"critere":"Mot-valise inventé, défini et décomposé","points":5}],"dureeMin":12,"corrige":"1.\n- a. **Mot-valise** : « hérissonge » fond deux mots, *hérisson* et *songe*.\n- b. **Détournement** : un proverbe connu est retourné et sa fin est changée.\n- c. **Paronymie** : *baleine* et *haleine* sont des mots qui se ressemblent (une seule lettre change). « Perdre haleine » signifie être essoufflé.\n- d. **Calembour** : *ver* (l’animal) et *verre* (le récipient) se prononcent de la même façon ; la phrase joue sur ces deux sens pour un même son.\n\n2. Le proverbe d’origine est **« Qui vole un œuf vole un bœuf »** (celui qui commet un petit vol finira par en commettre de plus grands). La phrase fait rire parce qu’elle prend le mot « bœuf » **au sens propre** : un bœuf est très lourd, donc celui qui le vole (au sens de l’emporter) a mal au dos. Il y a un **décalage** entre la forme sérieuse du proverbe et la chute absurde.\n\n3. Exemple : « Le **girafleur** (*girafe* + *fleur*) est une girafe dont le long cou se termine par une tulipe. »\nÉléments valorisés : un mot vraiment fondu (pas deux mots simplement collés avec un tiret sans fusion), les deux mots d’origine nommés, une définition amusante et correctement écrite."}$exo$::jsonb),
  ('5a396493-5b55-5ed9-8879-3481b3d8fdda'::uuid, 3, 'redaction', $exo${"titre":"Écrire un ani-mot sous contrainte","consigne":"Écris un court poème sur un animal en respectant une contrainte oulipienne, puis explique tes choix d’écriture.","enonce":"Comme Jacques Roubaud, tu vas consacrer un court poème à un animal.\n\n1. **Prépare** : choisis un animal. Note au moins quatre mots que son nom contient, évoque ou rappelle par le son (paronymes, homophones…).\n2. **Choisis une contrainte** parmi les suivantes et écris-la en tête de ton poème :\n   - un **acrostiche** : la première lettre de chaque vers, lue de haut en bas, forme le nom de l’animal ;\n   - une **rime imposée** : tous les vers se terminent par le même son que le nom de l’animal ;\n   - une **seule voyelle** : tous les mots du poème n’utilisent qu’une seule voyelle (par exemple seulement le *a*).\n3. **Écris** ton poème (4 à 6 vers). Il doit contenir au moins **un jeu de langue** du recueil (calembour, mot-valise, paronymie ou détournement) et être **drôle**.\n4. **Explique** en trois ou quatre phrases : quel jeu de langue as-tu utilisé et où ? Comment la contrainte t’a-t-elle aidé(e) à trouver des idées ? D’où vient l’humour de ton poème ?","bareme":[{"critere":"Préparation : animal choisi et mots associés pertinents","points":3},{"critere":"Contrainte choisie et respectée dans tout le poème","points":5},{"critere":"Présence d’un jeu de langue correct et d’un ton humoristique","points":5},{"critere":"Explication : jeu nommé, rôle de la contrainte, source de l’humour","points":4},{"critere":"Orthographe et syntaxe correctes","points":3}],"dureeMin":20,"corrige":"**Exemple de préparation** : le loup → *loupe*, *loupé*, *louper*, *pou*, *loup de mer*, « à pas de loup ».\n\n**Contrainte** : acrostiche sur LOUP.\n\n**Exemple de poème** :\n> **L**ent le matin, il bâille au bord du bois,\n> **O**uvre un œil, puis deux, puis compte ses proies ;\n> **U**n loup ? Non : un loupé ! Il rate tout, ma foi,\n> **P**auvre bête affamée qui se ronge les doigts.\n\n**Exemple d’explication** : J’ai utilisé une **paronymie** entre « loup » et « loupé » au vers 3 : les deux mots se ressemblent, et le loup devient un animal qui rate tout. La contrainte de l’acrostiche m’a obligé(e) à commencer par *U*, ce qui m’a fait penser à « Un loup ? » puis à « loupé » : c’est la contrainte qui a fait surgir l’idée. L’humour vient du **décalage** entre la forme sérieuse du poème (vers, rimes) et ce loup ridicule, loin du loup terrible des contes.\n\n**Éléments valorisés** :\n- la contrainte est respectée sans erreur (vérifier chaque première lettre, chaque rime ou chaque voyelle) ;\n- le jeu de langue est réel et bien nommé (calembour = double sens ou sons identiques ; mot-valise = deux mots fondus ; paronymie = mots qui se ressemblent ; détournement = expression figée retournée) ;\n- l’élève explique que la contrainte n’empêche pas d’écrire mais **oblige à trouver** (idée de l’Oulipo) ;\n- l’humour naît du décalage entre forme poétique et sujet drôle.\n\nUne contrainte « une seule voyelle » est plus difficile : on sera indulgent sur la longueur si elle est parfaitement respectée."}$exo$::jsonb),
  ('8f69c9d1-7cdd-5e7e-b37d-ff57ba7a4e4b'::uuid, 1, 'redaction', $exo${"titre":"Passé simple et imparfait dans un récit de création","consigne":"Relève les verbes conjugués du texte et classe-les selon leur temps, puis explique le rôle de chaque temps.","enonce":"Lis ce court récit de création.\n\n> Au commencement, la terre était vide et l’obscurité couvrait tout. Puis une voix s’éleva. La lumière jaillit et sépara le jour de la nuit. Le deuxième jour, le ciel apparut au-dessus des eaux, qui dormaient encore.\n\n1. Relève les verbes conjugués à l’**imparfait** et ceux conjugués au **passé simple**. Présente ta réponse en deux listes.\n2. Explique à quoi sert chacun de ces deux temps dans le récit.\n3. Relève trois **connecteurs de temps** (mots ou groupes de mots) qui organisent ce récit.","bareme":[{"critere":"Verbes correctement classés à l’imparfait et au passé simple","points":8},{"critere":"Rôle de chaque temps expliqué","points":6},{"critere":"Trois connecteurs de temps relevés","points":6}],"dureeMin":7,"corrige":"1.\n- **Imparfait** : était, couvrait, dormaient.\n- **Passé simple** : s’éleva, jaillit, sépara, apparut.\n\n2. Le **passé simple** exprime les **actions principales, achevées**, qui font **avancer** l’histoire (la voix s’élève, la lumière jaillit…). L’**imparfait** **installe le décor** et décrit l’état des choses (la terre était vide, l’obscurité couvrait tout, les eaux dormaient).\n\n3. Connecteurs de temps : **Au commencement**, **Puis**, **Le deuxième jour**. (On accepte aussi « encore » en complément, mais les trois attendus sont ceux-ci.)"}$exo$::jsonb),
  ('8f69c9d1-7cdd-5e7e-b37d-ff57ba7a4e4b'::uuid, 2, 'redaction', $exo${"titre":"Conjuguer et comprendre la parole créatrice","consigne":"Conjugue les verbes au temps qui convient en justifiant, puis réponds aux questions sur le récit de la Genèse.","enonce":"1. Recopie ce texte en conjuguant les verbes entre parenthèses au **passé simple** ou à l’**imparfait**. Puis justifie ton choix pour deux des verbes.\n\n> Au commencement, tout (être) noir et silencieux. Le premier jour, Dieu (dire) : « Que la lumière soit ! » Et la lumière (être). Le troisième jour, il (séparer) les eaux, et la terre sèche (apparaître). Les eaux (briller) sous le ciel.\n\n2. Explique comment est formé le mot « **monothéiste** ». Cite les trois religions monothéistes qui partagent, avec des variantes, ce récit de création.\n3. Dans la Genèse, la formule « Dieu dit… et cela fut ainsi » revient à chaque étape. Comment s’appelle ce procédé ? Quel effet produit-il ? Que montre cette formule sur le pouvoir de la parole dans ce récit ?","bareme":[{"critere":"Six verbes conjugués correctement au bon temps","points":6},{"critere":"Deux choix de temps justifiés","points":4},{"critere":"Formation du mot monothéiste et trois religions citées","points":4},{"critere":"Répétition, rythme solennel et parole créatrice expliqués","points":6}],"dureeMin":12,"corrige":"1. Texte attendu :\n> Au commencement, tout **était** noir et silencieux. Le premier jour, Dieu **dit** : « Que la lumière soit ! » Et la lumière **fut**. Le troisième jour, il **sépara** les eaux, et la terre sèche **apparut**. Les eaux **brillaient** sous le ciel.\n\nJustifications possibles :\n- « était » et « brillaient » sont à l’**imparfait** car ils décrivent le **décor**, l’état des choses ;\n- « dit », « fut », « sépara », « apparut » sont au **passé simple** car ce sont des **actions principales, achevées**, qui font avancer le récit.\n\n2. « Monothéiste » vient du grec **monos** (seul) et **theos** (dieu) : il désigne une religion qui croit en **un seul dieu**. Les trois monothéismes sont le **judaïsme**, le **christianisme** et l’**islam**.\n\n3. C’est une **répétition**. Reprise à chaque étape, elle donne au texte un **rythme solennel**, régulier, presque comme un chant. Elle montre que, dans ce récit, **dire suffit à faire exister** : il suffit que Dieu parle pour que la chose soit créée. C’est la **parole créatrice**, un choix littéraire fort."}$exo$::jsonb),
  ('8f69c9d1-7cdd-5e7e-b37d-ff57ba7a4e4b'::uuid, 3, 'redaction', $exo${"titre":"Lire et imiter le début de la Genèse","consigne":"Analyse l’extrait de la Genèse en t’appuyant sur des citations, puis écris la suite en imitant son écriture.","enonce":"Lis ce début de la Genèse (d’après la traduction de Louis Segond, 1910).\n\n> Au commencement, Dieu créa les cieux et la terre. La terre était informe et vide : il y avait des ténèbres à la surface de l’abîme, et l’esprit de Dieu se mouvait au-dessus des eaux. Dieu dit : Que la lumière soit ! Et la lumière fut. Dieu vit que la lumière était bonne ; et Dieu sépara la lumière d’avec les ténèbres. Dieu appela la lumière jour, et il appela les ténèbres nuit. Ainsi, il y eut un soir, et il y eut un matin : ce fut le premier jour.\n\n1. Relève deux verbes à l’imparfait et trois verbes au passé simple. Explique pourquoi l’auteur emploie ces deux temps.\n2. Relève une répétition dans l’extrait. Quel effet produit-elle ?\n3. Montre, en citant une phrase, que la parole de Dieu suffit à créer.\n4. Par quoi commence la création dans ce récit ? Par quoi se termine-t-elle au sixième jour ? Que montre cette progression ?\n5. En classe, pourquoi étudie-t-on ce texte ? Réponds en une ou deux phrases.\n6. **Écriture** : rédige le récit du « deuxième jour » en 4 à 6 phrases. Tu dois imiter l’extrait : un connecteur de temps, la formule de la parole créatrice, le passé simple pour les actions et l’imparfait pour le décor, et la phrase finale « … ce fut le deuxième jour ».","bareme":[{"critere":"Temps relevés et leur rôle expliqué","points":4},{"critere":"Répétition relevée et effet expliqué","points":3},{"critere":"Parole créatrice et progression de la création expliquées","points":4},{"critere":"Statut de texte fondateur compris","points":2},{"critere":"Écriture : imitation réussie (connecteur, formule, temps, clôture)","points":7}],"dureeMin":20,"corrige":"1. **Imparfait** : était, avait (il y avait), se mouvait. **Passé simple** : créa, dit, fut, vit, sépara, appela, eut. Le passé simple raconte les **actions principales, achevées**, qui font avancer la création ; l’imparfait **décrit le décor** d’avant la création (une terre informe, des ténèbres).\n\n2. Répétitions possibles : « Dieu » (sujet de presque toutes les phrases), « il appela… et il appela », « il y eut un soir, et il y eut un matin ». Elles créent un **rythme solennel** et régulier, qui donne de la grandeur au texte.\n\n3. « **Dieu dit : Que la lumière soit ! Et la lumière fut.** » La lumière existe aussitôt que Dieu la nomme : **dire suffit à faire exister**.\n\n4. La création commence par la **lumière** (puis le ciel) et se termine par l’**humain**, après les animaux. C’est une **progression** du plus général au plus particulier.\n\n5. On l’étudie comme un **texte fondateur** : une œuvre littéraire qui a façonné la culture, les arts et la langue. On y cherche la construction et les images, **pas une vérité scientifique**.\n\n6. Exemple :\n> Le deuxième jour, les eaux couvraient encore toute chose et le silence régnait. Dieu dit : Qu’il y ait un ciel au-dessus des eaux ! Et cela fut ainsi. Le ciel s’étendit, immense et clair, et sépara les eaux d’en haut des eaux d’en bas. Dieu regarda le ciel, et il vit qu’il était beau. Ainsi, il y eut un soir, et il y eut un matin : ce fut le deuxième jour.\n\nÉléments valorisés : connecteur de temps en tête ; formule « Dieu dit… et cela fut ainsi » ; passé simple pour les actions (dit, s’étendit, sépara, vit), imparfait pour le décor (couvraient, régnait, était) ; répétition finale ; conjugaisons exactes."}$exo$::jsonb),
  ('1f0ed8c8-b29a-5bd3-89ab-46dee89079f5'::uuid, 1, 'redaction', $exo${"titre":"Les dieux grecs et la naissance du monde","consigne":"Réponds aux questions sur la mythologie grecque par des phrases complètes.","enonce":"1. Explique comment est formé le mot « **polythéiste** » et ce qu’il signifie.\n2. Recopie et complète en indiquant le domaine de chaque dieu :\n   - Zeus : …\n   - Poséidon : …\n   - Hadès : …\n   - Athéna : …\n   - Arès : …\n3. Remets dans l’ordre ces étapes de la naissance du monde chez les Grecs, puis indique quel poète les raconte et dans quelle œuvre :\n   - Zeus renverse Cronos.\n   - Au début, il y a le Chaos.\n   - Cronos renverse son père.\n   - Gaïa (la Terre) et Ouranos (le Ciel) apparaissent.","bareme":[{"critere":"Formation et sens du mot polythéiste","points":4},{"critere":"Domaines des cinq dieux","points":8},{"critere":"Ordre des étapes, auteur et œuvre","points":8}],"dureeMin":7,"corrige":"1. « Polythéiste » vient du grec **poly** (nombreux) et **theos** (dieu). Une religion polythéiste croit en **plusieurs dieux**.\n\n2.\n- Zeus : **le ciel** (il règne sur l’Olympe) ;\n- Poséidon : **la mer** ;\n- Hadès : **les Enfers** ;\n- Athéna : **la sagesse** ;\n- Arès : **la guerre**.\n\n3. Ordre :\n1) Au début, il y a le **Chaos**.\n2) **Gaïa** (la Terre) et **Ouranos** (le Ciel) apparaissent.\n3) **Cronos renverse son père** (Ouranos).\n4) **Zeus renverse Cronos**, puis s’installe sur l’Olympe avec les douze dieux.\n\nCe récit est raconté par le poète grec **Hésiode**, dans **La Théogonie**."}$exo$::jsonb),
  ('1f0ed8c8-b29a-5bd3-89ab-46dee89079f5'::uuid, 2, 'redaction', $exo${"titre":"Les mots venus des mythes, Prométhée et Pandore","consigne":"Complète des phrases avec des mots issus de la mythologie, puis explique deux grands mythes grecs.","enonce":"1. Complète chaque phrase avec l’un de ces mots : **panique**, **titanesque**, **narcissique**, **olympien**, **dédale**. Puis indique de quel personnage ou lieu mythologique vient chaque mot.\n   - a. En entendant l’alarme, la foule fut prise de …\n   - b. Construire cette tour immense fut un travail …\n   - c. Il passe des heures à s’admirer dans le miroir : il est vraiment …\n   - d. Malgré le bruit, l’arbitre garda un calme …\n   - e. Nous nous sommes perdus dans le … des ruelles de la vieille ville.\n2. Raconte en deux ou trois phrases ce que fait **Prométhée** et ce qui lui arrive. Que peut-on comprendre de ce mythe ?\n3. Raconte en deux ou trois phrases le mythe de **Pandore**. Qu’est-ce qui reste dans la jarre à la fin, et pourquoi est-ce important ?","bareme":[{"critere":"Cinq mots bien placés","points":5},{"critere":"Origine mythologique de chaque mot","points":5},{"critere":"Mythe de Prométhée raconté et interprété","points":5},{"critere":"Mythe de Pandore raconté et interprété","points":5}],"dureeMin":11,"corrige":"1.\n- a. la foule fut prise de **panique** – du dieu **Pan**, qui provoquait des peurs soudaines ;\n- b. un travail **titanesque** (gigantesque) – des **Titans**, géants fils de Gaïa et d’Ouranos ;\n- c. il est vraiment **narcissique** (trop amoureux de lui-même) – de **Narcisse**, amoureux de son propre reflet ;\n- d. un calme **olympien** (majestueux, que rien ne trouble) – de l’**Olympe**, séjour des dieux ;\n- e. le **dédale** des ruelles (un lieu où l’on se perd) – de **Dédale**, l’architecte du labyrinthe.\n\n2. **Prométhée** vole le **feu** aux dieux pour le donner aux humains. Il est **puni** par les dieux pour cette désobéissance. Ce mythe montre que le **savoir** (le feu, la technique) a été **conquis contre les dieux**, et qu’il a un prix.\n\n3. **Pandore** ouvre une **jarre** d’où s’échappent tous les **maux** qui frappent désormais les humains. Seule l’**espérance** reste à l’intérieur. C’est important : malgré les malheurs, les humains gardent l’espoir. Ce mythe explique ainsi l’origine des malheurs du monde.\n\nOn accepte « boîte de Pandore » si l’élève connaît l’expression, mais le cours parle d’une jarre."}$exo$::jsonb),
  ('1f0ed8c8-b29a-5bd3-89ab-46dee89079f5'::uuid, 3, 'redaction', $exo${"titre":"Comparer la naissance du monde chez les Grecs et dans la Genèse","consigne":"Lis ce récit de la naissance des dieux, analyse-le et compare-le avec le récit de la Genèse, en justifiant tes réponses.","enonce":"Lis ce récit inspiré de *La Théogonie* d’Hésiode.\n\n> Au commencement était le Chaos, un vide immense et obscur. Puis apparut Gaïa, la Terre aux larges flancs. Gaïa donna naissance à Ouranos, le Ciel étoilé, qui devint son époux. Leurs enfants, les Titans, étaient puissants et nombreux. Mais Ouranos les détestait ; alors le plus jeune, Cronos, se révolta et renversa son père. Cronos régna à son tour. Craignant d’être détrôné, il avalait chacun de ses enfants dès leur naissance. Rhéa, son épouse, cacha le petit Zeus et donna à Cronos une pierre enveloppée de langes. Devenu grand, Zeus libéra ses frères et sœurs et vainquit son père. Il s’installa alors sur l’Olympe.\n\n1. Relève les trois générations de dieux qui se succèdent à la tête du monde. Quel événement fait passer le pouvoir d’une génération à l’autre ?\n2. Les dieux grecs sont **anthropomorphes**. Explique ce mot, puis relève deux passages qui montrent que ces dieux ont des sentiments ou des défauts humains.\n3. Donne deux différences entre ce récit et celui de la Genèse (le nombre de dieux, la manière dont le monde naît).\n4. Le récit du **déluge** existe dans plusieurs cultures. Cite deux cultures, autres que la Bible, qui le racontent. Que nous apprend *L’Épopée de Gilgamesh* à ce sujet ? Pourquoi est-il intéressant de comparer ces récits ?","bareme":[{"critere":"Trois générations et renversements identifiés","points":5},{"critere":"Anthropomorphisme expliqué et illustré par deux citations","points":5},{"critere":"Deux différences justes avec la Genèse","points":5},{"critere":"Motif du déluge : cultures, ancienneté de Gilgamesh, intérêt de la comparaison","points":5}],"dureeMin":18,"corrige":"1. Les trois générations sont : **Ouranos** (avec Gaïa), puis **Cronos**, puis **Zeus**. Le pouvoir passe d’une génération à l’autre par un **renversement** : le fils se révolte contre son père (« Cronos […] renversa son père », « Zeus […] vainquit son père »). Le monde naît d’une **succession de générations et de conflits de famille**.\n\n2. **Anthropomorphe** signifie « qui a une forme humaine » : les dieux ont un corps, un caractère et des défauts humains. Citations possibles : « Ouranos les détestait » (la haine) ; « Craignant d’être détrôné » (la peur, la jalousie du pouvoir) ; « Rhéa […] cacha le petit Zeus et donna à Cronos une pierre » (la ruse, l’amour maternel) ; « Cronos se révolta » (la colère).\n\n3. Différences :\n- Chez les Grecs, il y a **plusieurs dieux** (récit polythéiste) ; dans la Genèse, il y a **un dieu unique**, sans image (récit monothéiste).\n- Chez les Grecs, le monde naît d’une **succession de générations** et de conflits ; dans la Genèse, il naît d’une **parole** (« Dieu dit… et cela fut »).\n- On accepte aussi : les dieux grecs ont chacun leur **domaine** et ressemblent aux humains, alors que le dieu de la Genèse n’a pas d’image.\n\n4. Le déluge existe aussi chez les **Grecs** (avec **Deucalion**) et chez les **Mésopotamiens**. *L’Épopée de Gilgamesh*, qui contient un déluge, est **bien plus ancienne que la Bible**. Le même motif traverse donc des cultures différentes. Il est intéressant de **comparer** ces récits plutôt que de les classer : on voit comment des peuples différents ont imaginé des réponses proches aux mêmes questions."}$exo$::jsonb),
  ('26e5fcc3-931a-5cc7-8118-27f00ecde058'::uuid, 1, 'redaction', $exo${"titre":"Le conte étiologique et le chameau de Kipling","consigne":"Réponds aux questions sur le conte étiologique et sur l’histoire de Kipling par des phrases complètes.","enonce":"1. D’où vient le mot « **étiologique** » ? Explique ce qu’est un conte étiologique et donne un exemple de question à laquelle il peut répondre.\n2. Dans « Comment le chameau eut sa bosse », tiré des *Histoires comme ça* (1902) de Rudyard Kipling, retrouve les trois étapes du conte : la situation initiale, l’événement, la situation finale.\n3. À la fin, ce chameau n’est pas le seul à avoir une bosse. Explique pourquoi.","bareme":[{"critere":"Origine du mot et définition du conte étiologique avec exemple","points":6},{"critere":"Trois étapes du conte retrouvées","points":9},{"critere":"Valeur de la situation finale pour toute l’espèce","points":5}],"dureeMin":8,"corrige":"1. « Étiologique » vient du grec **aitia**, qui signifie **la cause**. Un conte étiologique explique **pourquoi une chose est comme elle est** (en réalité, il fait semblant de l’expliquer). Exemples : pourquoi le chameau a une bosse, pourquoi la mer est salée, pourquoi le léopard a des taches.\n\n2.\n- **Situation initiale** : le chameau n’a pas encore de bosse. Il est paresseux, refuse de travailler et répond toujours « Bof ! ».\n- **Événement** : à cause de cette faute, le **Djinn du désert** le punit ; le « Bof » se change en **bosse**.\n- **Situation finale** : le chameau a désormais une bosse, qui lui permet de **travailler trois jours sans manger**.\n\n3. La situation finale vaut **pour toujours** et **pour toute l’espèce** : depuis ce jour, **tous les chameaux** ont une bosse. Le conte explique ainsi l’état actuel des choses."}$exo$::jsonb),
  ('26e5fcc3-931a-5cc7-8118-27f00ecde058'::uuid, 2, 'redaction', $exo${"titre":"Pourquoi la tortue porte sa maison","consigne":"Lis ce conte étiologique écrit à la manière de Kipling et réponds aux questions en citant le texte.","enonce":"Lis ce conte.\n\n> Il y a très, très longtemps, ô Bien-Aimé, quand le monde était tout neuf, la Tortue n’avait pas de carapace. Elle était douce, rose et terriblement curieuse. Chaque soir, elle entrait sans frapper dans les terriers des autres bêtes et fouillait partout. Un jour, le Grand Esprit de la Forêt perdit patience. « Puisque tu aimes tant les maisons des autres, dit-il, tu porteras désormais la tienne ! » Et, pouf ! une lourde maison de corne tomba sur son dos. Depuis ce jour, ô Bien-Aimé, toutes les tortues portent leur maison, et elles marchent lentement, lentement, lentement.\n\n1. Retrouve les trois étapes du conte (situation initiale, événement, situation finale) en citant le texte.\n2. Relève deux verbes à l’imparfait et deux verbes au passé simple. Explique le rôle de chacun de ces temps.\n3. Relève l’**apostrophe** du conteur. À qui s’adresse-t-il ? Quel effet cela produit-il ?\n4. Relève un autre procédé qui fait entendre la voix d’un conteur et rend le texte drôle. Explique pourquoi on peut dire que ce conte « fait semblant » d’expliquer.","bareme":[{"critere":"Trois étapes retrouvées avec citations","points":6},{"critere":"Imparfait et passé simple relevés et expliqués","points":5},{"critere":"Apostrophe relevée et effet expliqué","points":4},{"critere":"Procédés de la voix du conteur et faux savoir expliqués","points":5}],"dureeMin":12,"corrige":"1.\n- **Situation initiale** : « la Tortue n’avait pas de carapace. Elle était douce, rose et terriblement curieuse. »\n- **Événement** : sa **faute** (« elle entrait sans frapper dans les terriers des autres bêtes et fouillait partout ») entraîne une **punition** : le Grand Esprit « perdit patience » et « une lourde maison de corne tomba sur son dos ».\n- **Situation finale** : « Depuis ce jour, […] toutes les tortues portent leur maison » ; elle vaut pour toujours et pour **toute l’espèce**.\n\n2. **Imparfait** : était, n’avait, entrait, fouillait. Il décrit le **décor**, l’état des choses et les habitudes. **Passé simple** : perdit, dit, tomba. Il raconte les **actions principales** qui font avancer l’histoire.\n\n3. L’apostrophe est « **ô Bien-Aimé** » (deux fois). Le conteur s’adresse **directement au lecteur** (ou à l’enfant qui écoute), comme Kipling. Cela crée une complicité et donne l’impression d’entendre une histoire racontée à voix haute.\n\n4. Procédés : la **répétition** « très, très longtemps » et « lentement, lentement, lentement » ; le mot sonore « **pouf !** » ; l’**humour** de la punition (celle qui entrait chez les autres doit porter sa propre maison). On entend une **voix de conteur**. Le conte **fait semblant** d’expliquer : la vraie raison de la carapace n’est pas une punition ; c’est une explication inventée et amusante, et c’est ce jeu qui plaît."}$exo$::jsonb),
  ('26e5fcc3-931a-5cc7-8118-27f00ecde058'::uuid, 3, 'redaction', $exo${"titre":"Écrire son propre conte étiologique","consigne":"Invente un conte étiologique à la manière de Kipling qui explique une particularité d’un animal, en suivant les étapes indiquées.","enonce":"Choisis une particularité animale : pourquoi le zèbre a des rayures, pourquoi la girafe a un long cou, pourquoi le hibou ne dort que le jour, etc.\n\n1. **Prépare** en trois lignes : la particularité choisie ; la **faute** (ou la ruse) de l’animal ; la **sanction** (ou la conséquence).\n2. **Écris** ton conte (10 à 15 lignes) en respectant ces consignes :\n   - une **situation initiale** où la particularité n’existe pas encore, un **événement**, une **situation finale** ;\n   - les actions au **passé simple**, le décor et les habitudes à l’**imparfait** ;\n   - au moins une **apostrophe** au lecteur et une **répétition** qui fait entendre la voix du conteur ;\n   - une touche d’**humour** ;\n   - une dernière phrase qui commence par « **Et depuis ce jour…** » et qui concerne **toute l’espèce**.\n3. En deux phrases, explique pourquoi ton conte « fait semblant » d’expliquer.","bareme":[{"critere":"Préparation claire : particularité, faute, sanction","points":3},{"critere":"Structure en trois étapes et fin valable pour toute l’espèce","points":5},{"critere":"Emploi correct du passé simple et de l’imparfait","points":5},{"critere":"Ton du conteur : apostrophe, répétition, humour","points":4},{"critere":"Explication du faux savoir et correction de la langue","points":3}],"dureeMin":20,"corrige":"**Exemple de préparation** : pourquoi la girafe a un long cou ; faute : elle était gourmande et volait les fruits des autres ; sanction : le Djinn de la savane lui étire le cou pour qu’elle ne mange plus que les feuilles du haut des arbres.\n\n**Exemple de conte** :\n> Il y a très, très longtemps, ô Bien-Aimé, la Girafe avait un petit cou, court comme celui d’un mouton. Elle était gourmande, si gourmande qu’elle volait chaque matin les fruits tombés sous le nez des autres bêtes. Le Zèbre se plaignait, l’Éléphant soupirait, mais la Girafe mâchait, mâchait, mâchait. Un jour, le Djinn de la savane arriva dans un nuage de poussière. « Puisque tu prends tout ce qui est en bas, dit-il, tu mangeras désormais ce qui est en haut ! » Il saisit la Girafe par la tête et tira, tira, tira. Son cou s’allongea jusqu’aux branches les plus hautes des acacias. La Girafe ouvrit la bouche pour protester, mais elle ne trouva plus que des feuilles à mâcher. Et depuis ce jour, ô Bien-Aimé, toutes les girafes ont un long cou, et elles laissent les fruits tombés aux autres animaux.\n\n**Exemple d’explication** : Mon conte ne donne pas la vraie raison du long cou des girafes : c’est une explication inventée, présentée comme si elle était vraie. Il fait semblant d’expliquer pour amuser le lecteur et glisser une petite leçon contre la gourmandise.\n\n**Éléments valorisés** :\n- la faute et la sanction sont liées de façon logique et amusante ;\n- passé simple bien conjugué (arriva, dit, saisit, tira, s’allongea, ouvrit, trouva) et imparfait pour le décor (avait, était, volait, se plaignait) ;\n- apostrophe (« ô Bien-Aimé »), répétitions, mots sonores ;\n- la fin « Et depuis ce jour… » concerne **toutes** les girafes ;\n- le texte est lisible, ponctué, et les paroles sont entre guillemets."}$exo$::jsonb),
  ('90d6b904-720c-518a-ba2f-3826e18909db'::uuid, 1, 'redaction', $exo${"titre":"Le Médecin malgré lui : la pièce et le vocabulaire du théâtre","consigne":"Réponds aux questions sur la pièce de Molière et sur le vocabulaire du théâtre par des phrases complètes.","enonce":"1. Qui a écrit *Le Médecin malgré lui* ? En quelle année ? De quel genre de pièce s’agit-il et combien d’actes compte-t-elle ?\n2. Définis ces cinq mots du théâtre : **réplique**, **tirade**, **monologue**, **aparté**, **didascalies**.\n3. Pour chaque situation, indique la forme de comique utilisée (de gestes, de mots, de situation ou de caractère) :\n   - a. Sganarelle reçoit des coups de bâton.\n   - b. Sganarelle débite du faux latin.\n   - c. On prend un simple bûcheron pour un grand médecin.\n   - d. Sganarelle est un ivrogne qui aime trop la bouteille.","bareme":[{"critere":"Auteur, date, genre et nombre d’actes","points":4},{"critere":"Cinq définitions justes","points":10},{"critere":"Quatre formes de comique identifiées","points":6}],"dureeMin":8,"corrige":"1. *Le Médecin malgré lui* a été écrit par **Molière** en **1666**. C’est une **comédie** en **trois actes**.\n\n2.\n- **Réplique** : ce que dit un personnage quand il prend la parole.\n- **Tirade** : une longue réplique.\n- **Monologue** : les paroles d’un personnage seul en scène.\n- **Aparté** : ce qu’un personnage dit sans être entendu des autres personnages (mais le public l’entend).\n- **Didascalies** : les indications de mise en scène (gestes, ton, déplacements), écrites en italique.\n\n3.\n- a. comique de **gestes** (les coups) ;\n- b. comique de **mots** (le latin de cuisine) ;\n- c. comique de **situation** (le déguisement, l’imposture) ;\n- d. comique de **caractère** (l’ivrogne)."}$exo$::jsonb),
  ('90d6b904-720c-518a-ba2f-3826e18909db'::uuid, 2, 'redaction', $exo${"titre":"Une consultation du faux médecin","consigne":"Lis cette scène inspirée de Molière et réponds aux questions en citant le texte.","enonce":"Lis cette scène, inspirée de l’acte II du *Médecin malgré lui*. Géronte a fait venir Sganarelle pour soigner sa fille, qui ne parle plus.\n\n> GÉRONTE. — Monsieur, ma fille ne dit plus un mot depuis huit jours. Qu’a-t-elle donc ?\n> SGANARELLE, *prenant un air savant*. — C’est très simple : votre fille est muette parce qu’elle a perdu la parole.\n> GÉRONTE. — Oui, mais d’où cela vient-il ?\n> SGANARELLE, *levant le doigt*. — *Rhubarbus, ventrilis, bonum potagium !* Voilà la cause.\n> GÉRONTE, *admiratif*. — Ah ! quel grand homme ! Je n’ai rien compris.\n> SGANARELLE, *à part*. — Moi non plus.\n\n1. Relève deux **didascalies**. À quoi servent-elles ?\n2. Relève l’**aparté**. Qu’apprend le spectateur que Géronte ignore ?\n3. Explique pourquoi la première réponse de Sganarelle est comique. Puis relève le passage en faux latin et explique pourquoi Géronte ne proteste pas.\n4. D’après cette scène, que Molière dénonce-t-il derrière le rire ?","bareme":[{"critere":"Deux didascalies relevées et leur rôle expliqué","points":4},{"critere":"Aparté relevé et expliqué","points":4},{"critere":"Comique de mots analysé (réponse vide et faux latin)","points":6},{"critere":"Cible de la satire : médecins et crédulité","points":6}],"dureeMin":12,"corrige":"1. Didascalies : « *prenant un air savant* », « *levant le doigt* », « *admiratif* », « *à part* ». Elles sont en **italique** et donnent des **indications de mise en scène** : le ton, les gestes, l’attitude des personnages.\n\n2. L’aparté est « **Moi non plus.** » (indiqué par la didascalie « à part »). Géronte ne l’entend pas. Le spectateur apprend que Sganarelle **ne sait rien** : il n’est pas médecin et ne comprend pas lui-même ce qu’il dit.\n\n3. La première réponse est comique car elle **ne dit rien** : être muet et avoir perdu la parole, c’est la même chose. Sganarelle répète la question en prenant un air savant (**comique de mots**). Le faux latin est « *Rhubarbus, ventrilis, bonum potagium !* » : ce sont des mots inventés qui imitent le latin des médecins. Géronte ne proteste pas parce qu’il est **impressionné** par ce vocabulaire qu’il ne comprend pas : il croit que c’est de la science (« quel grand homme ! »).\n\n4. Molière dénonce les **médecins** de son temps : leur **jargon** incompréhensible, leur **assurance** et leur **incapacité à guérir**. Il se moque aussi de la **crédulité** de ceux qui, comme Géronte, se laissent impressionner par des mots savants qu’ils ne comprennent pas. Sganarelle ne trompe pas par son savoir, mais par son assurance."}$exo$::jsonb),
  ('90d6b904-720c-518a-ba2f-3826e18909db'::uuid, 3, 'redaction', $exo${"titre":"Écrire la scène où Sganarelle « avoue » être médecin","consigne":"Explique la ruse de Martine, puis écris une courte scène de farce en respectant les règles d’écriture du théâtre.","enonce":"Au début du *Médecin malgré lui*, Martine veut se venger de son mari Sganarelle, qui l’a battue. Deux serviteurs, Valère et Lucas, cherchent un médecin pour la fille de leur maître.\n\n1. Explique en trois ou quatre phrases la ruse de Martine : que fait-elle croire à Valère et Lucas, et que leur conseille-t-elle ? Pourquoi cette ruse est-elle une vengeance ?\n2. Quelles formes de comique cette ruse va-t-elle produire ? Nommes-en deux et justifie.\n3. **Écriture** : rédige la scène où Valère et Lucas trouvent Sganarelle en train de couper du bois. Sganarelle refuse d’abord d’être médecin, reçoit des coups de bâton, puis finit par « avouer ».\n   Ta scène doit comporter :\n   - 8 à 12 répliques, avec le nom du personnage avant chaque réplique ;\n   - au moins trois didascalies en italique (ou entre parenthèses) ;\n   - au moins un aparté ;\n   - du comique de gestes et du comique de mots.","bareme":[{"critere":"Ruse de Martine expliquée et liée à la vengeance","points":4},{"critere":"Deux formes de comique nommées et justifiées","points":3},{"critere":"Scène cohérente avec l’intrigue (refus, coups, aveu)","points":5},{"critere":"Présentation théâtrale : répliques, didascalies, aparté","points":5},{"critere":"Comique de gestes et de mots présent, langue correcte","points":3}],"dureeMin":20,"corrige":"1. Martine fait croire à Valère et Lucas que son mari est un **médecin génial**, mais un peu fou : il refuse d’avouer son talent et **ne le reconnaît que sous les coups**. Elle leur conseille donc de le **battre** jusqu’à ce qu’il accepte. C’est une vengeance : Sganarelle, qui l’a battue, va à son tour recevoir des coups de bâton.\n\n2. **Comique de gestes** : les coups de bâton. **Comique de situation** : un bûcheron est pris pour un médecin (déguisement, imposture, quiproquo). On accepte aussi le comique de caractère (Valère et Lucas sont crédules).\n\n3. **Exemple de scène** :\n> VALÈRE, *saluant très bas*. — Monsieur, n’êtes-vous pas le célèbre médecin ?\n> SGANARELLE. — Médecin, moi ? Je suis fagotier, et je vends mes fagots.\n> LUCAS. — Allons, Monsieur, ne vous cachez pas : on sait tout.\n> SGANARELLE. — Je vous dis que je ne suis pas médecin !\n> VALÈRE, *à part*. — Sa femme nous avait prévenus.\n> LUCAS, *prenant un bâton*. — Alors, voilà pour vous rafraîchir la mémoire ! *(Il le frappe.)*\n> SGANARELLE, *sautant de douleur*. — Aïe ! Aïe ! Arrêtez !\n> VALÈRE, *le frappant aussi*. — Êtes-vous médecin, oui ou non ?\n> SGANARELLE. — Oui, oui ! Médecin, apothicaire, tout ce que vous voudrez !\n> SGANARELLE, *à part*. — Puisqu’on paie en coups de bâton pour ne pas l’être, je serai médecin !\n> LUCAS, *ravi*. — Vous voyez qu’il fallait insister !\n\n**Éléments valorisés** : l’intrigue est respectée (Valère et Lucas, le bois, les coups, l’aveu forcé) ; le nom de chaque personnage précède sa réplique ; les didascalies sont en italique ou entre parenthèses ; un aparté est clairement signalé (« à part ») ; le comique de gestes (coups, sauts) et de mots (répétitions, énumération) est présent ; orthographe et ponctuation soignées."}$exo$::jsonb),
  ('663aaaa7-2515-599e-84c4-9184cf6eb0bd'::uuid, 1, 'redaction', $exo${"titre":"Les Fourberies de Scapin : personnages et fourberies","consigne":"Réponds aux questions sur la pièce de Molière par des phrases complètes.","enonce":"1. En quelle année Molière a-t-il écrit *Les Fourberies de Scapin* ? De quel genre de pièce s’agit-il ?\n2. Présente en une phrase chacun de ces personnages ou groupes de personnages : **Scapin** ; **Octave et Léandre** ; **Argante et Géronte**.\n3. Qu’est-ce qu’une « **fourberie** » ? Cite deux fourberies inventées par Scapin.\n4. La réplique « **Que diable allait-il faire dans cette galère ?** » est passée en proverbe. Que veut-on dire aujourd’hui quand on l’emploie ?","bareme":[{"critere":"Date et genre de la pièce","points":4},{"critere":"Rôle des personnages","points":6},{"critere":"Définition de la fourberie et deux exemples","points":6},{"critere":"Sens actuel de la réplique proverbiale","points":4}],"dureeMin":7,"corrige":"1. *Les Fourberies de Scapin* date de **1671**. C’est une **comédie** en **trois actes**.\n\n2.\n- **Scapin** est le **valet rusé** qui mène le jeu.\n- **Octave et Léandre** sont les **jeunes gens amoureux**.\n- **Argante et Géronte** sont **leurs pères**, qui s’opposent à leurs mariages.\n\n3. Une fourberie est une **ruse**, une **tromperie habile**. Scapin invente par exemple **un mariage forcé**, **un frère vengeur**, **une galère turque** (on accepte aussi la scène du sac).\n\n4. Aujourd’hui, on emploie cette phrase pour dire : **« Pourquoi est-il allé se mettre dans une situation aussi compliquée ? »** On s’étonne que quelqu’un se soit fourré dans une affaire difficile ou dangereuse."}$exo$::jsonb),
  ('663aaaa7-2515-599e-84c4-9184cf6eb0bd'::uuid, 2, 'redaction', $exo${"titre":"La scène du sac : analyser la ruse de Scapin","consigne":"Lis cette scène inspirée de l’acte III, puis analyse la ruse de Scapin et le comique de la scène en citant le texte.","enonce":"Lis cette scène, inspirée de la célèbre scène du sac (acte III).\n\n> SCAPIN. — Vite, Monsieur, cachez-vous dans ce sac ! Des ennemis vous cherchent partout.\n> GÉRONTE. — Dans ce sac ? Mais…\n> SCAPIN. — Pas de « mais » ! Ils arrivent !\n> *Géronte entre dans le sac.*\n> SCAPIN, *d’une grosse voix*. — Où est ce Géronte ? Je veux le trouver !\n> SCAPIN, *de sa voix ordinaire*. — Il n’est pas ici, Monsieur.\n> SCAPIN, *d’une grosse voix*. — Tiens, voilà pour toi, et pour ton maître ! *(Il frappe le sac à coups de bâton.)*\n> GÉRONTE, *dans le sac*. — Aïe ! Aïe ! Aïe !\n> SCAPIN, *de sa voix ordinaire*. — Ah ! Monsieur, je suis tout moulu de coups !\n\n1. Explique en quelques phrases, étape par étape, comment Scapin trompe Géronte.\n2. Pourquoi Scapin prend-il deux voix différentes ? Relève les didascalies qui le montrent.\n3. Relève un exemple de comique de gestes et un exemple de comique de mots (ou de répétition).\n4. Observe la longueur des répliques. Quel effet produit ce rythme ? Pourquoi est-il important de le retrouver en lisant à voix haute ?","bareme":[{"critere":"Étapes de la ruse expliquées","points":5},{"critere":"Double voix expliquée avec didascalies","points":5},{"critere":"Comique de gestes et de mots relevé","points":5},{"critere":"Rythme des répliques analysé","points":5}],"dureeMin":12,"corrige":"1. Scapin **fait peur** à Géronte en inventant des ennemis qui le cherchent. Il le **persuade de se cacher dans un sac**. Puis il **imite la voix d’un ennemi** et **frappe le sac à coups de bâton**, tout en **faisant semblant de protéger** son maître. Enfin, il se plaint d’avoir lui-même reçu les coups, pour paraître fidèle.\n\n2. Scapin prend deux voix pour faire croire qu’un **ennemi** est présent et qu’il parle avec lui : Géronte, enfermé, ne voit rien et croit tout ce qu’il entend. Didascalies : « *d’une grosse voix* », « *de sa voix ordinaire* ». Le spectateur, lui, voit que Scapin est seul.\n\n3. **Comique de gestes** : Scapin frappe le sac à coups de bâton ; Géronte se glisse dans un sac. **Comique de mots / de répétition** : « Aïe ! Aïe ! Aïe ! » ; l’alternance « grosse voix » / « voix ordinaire » qui revient ; « Pas de “mais” ! » ; « je suis tout moulu de coups ! » alors que c’est Géronte qui les a reçus.\n\n4. Les répliques sont **courtes** et s’enchaînent **très vite**. Cette **vitesse** crée l’essentiel du comique : Géronte n’a pas le temps de réfléchir, et les voix se répondent en écho. En lisant à voix haute, il faut garder ce rythme rapide, sinon la scène perd son effet comique."}$exo$::jsonb),
  ('663aaaa7-2515-599e-84c4-9184cf6eb0bd'::uuid, 3, 'redaction', $exo${"titre":"Scapin, un valet plus malin que ses maîtres","consigne":"Analyse le personnage de Scapin et le moteur de la pièce, puis écris un monologue où Scapin prépare une nouvelle fourberie.","enonce":"1. « Chaque mensonge en appelle un autre. » Explique cette phrase en t’appuyant sur les fourberies inventées par Scapin. Pourquoi peut-on dire que c’est le **moteur** de la pièce ?\n2. Scapin appartient à un **type** de personnage très ancien. Nomme ses deux ancêtres et indique d’où ils viennent.\n3. Explique pourquoi la pièce repose sur un « **ordre renversé** ». Qui a le pouvoir social ? Qui a l’intelligence ? Pourquoi cela fait-il rire ?\n4. **Écriture** : rédige un **monologue** de Scapin (8 à 12 lignes). Seul en scène, il prépare une nouvelle fourberie pour obtenir de l’argent d’Argante. Il doit expliquer son plan, se moquer gentiment de son maître et montrer sa fierté. Ajoute au moins deux didascalies.","bareme":[{"critere":"Enchaînement des mensonges expliqué avec exemples","points":5},{"critere":"Ancêtres du valet rusé et leur origine","points":3},{"critere":"Ordre renversé : pouvoir social et intelligence","points":4},{"critere":"Monologue cohérent : plan, moquerie, fierté","points":5},{"critere":"Forme théâtrale (monologue, didascalies) et langue correcte","points":3}],"dureeMin":20,"corrige":"1. Pour aider Octave et Léandre, Scapin ment : il invente **un mariage forcé**, puis **un frère vengeur**, puis **une galère turque**. Chaque mensonge l’oblige à en inventer un nouveau pour obtenir de l’argent ou pour se protéger, jusqu’à la **scène du sac**. Ces ruses font avancer l’action scène après scène : c’est donc le **moteur** de la pièce.\n\n2. Ses ancêtres sont **l’esclave malin** de la **comédie latine** et le **zanni** de la **commedia dell’arte** italienne.\n\n3. Normalement, le maître commande et le valet obéit. Ici, c’est **l’inverse** : **le valet mène, les maîtres suivent**. Les pères (Argante, Géronte) ont le **pouvoir social** (l’argent, l’autorité), mais c’est Scapin, le valet, qui a l’**intelligence**. Scapin est **plus intelligent que ses maîtres** : ce décalage rend la pièce piquante et fait rire, car on voit les puissants se faire berner.\n\n4. **Exemple de monologue** :\n> SCAPIN, *seul, se frottant les mains*. — Ah ! mon pauvre Argante, tu serres ta bourse comme un trésor, mais Scapin saura bien l’ouvrir. Voyons… Je lui dirai que son fils a cassé le carrosse d’un grand seigneur, et que ce seigneur furieux demande deux cents pistoles. Argante criera, il pleurera, il jurera qu’il n’a pas un sou… puis il paiera, car il a plus peur du scandale que de la dépense. *(Il rit.)* Quel maître ! Il commande à toute la maison, et c’est moi qui mène la danse. Allons, Scapin, prends ta mine la plus triste : voici le bonhomme qui arrive. *(Il prend un air désolé.)*\n\n**Éléments valorisés** : le personnage est seul et parle à lui-même (monologue) ; le plan est clair et cohérent avec la pièce ; la moquerie et la fierté de Scapin se sentent ; au moins deux didascalies ; phrases correctes et ponctuées."}$exo$::jsonb),
  ('e77034bb-2c62-5e62-8c94-b3d3a29313a2'::uuid, 1, 'redaction', $exo${"titre":"Le vocabulaire de la représentation théâtrale","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Définis ces mots : **mise en scène**, **coulisses**, **plateau**. Puis explique les deux sens du mot **scène**.\n2. Pour chaque outil de l’illusion, indique ce qu’il apporte au spectacle : le **décor** et les **accessoires** ; le **costume** et le **maquillage** ; la **lumière** ; le **son** et la **musique**.\n3. Recopie et complète ce tableau :\n\n| Genre | Personnages | Fin |\n| La comédie | … | … |\n| La tragédie | … | … |","bareme":[{"critere":"Définitions du vocabulaire de la représentation","points":8},{"critere":"Rôle des outils de l’illusion","points":6},{"critere":"Tableau comédie et tragédie complété","points":6}],"dureeMin":7,"corrige":"1.\n- **Mise en scène** : le travail du **metteur en scène**, qui décide comment le texte devient spectacle.\n- **Coulisses** : l’**espace caché** au public, sur les côtés ou derrière la scène.\n- **Plateau** : l’**espace de jeu** où évoluent les comédiens.\n- **Scène** : c’est à la fois le **lieu** où l’on joue et une **unité du texte** (une pièce est découpée en actes et en scènes).\n\n2.\n- Le décor et les accessoires représentent **le lieu**.\n- Le costume et le maquillage construisent **le personnage**.\n- La lumière **isole, colore et rythme** le spectacle.\n- Le son et la musique créent **l’atmosphère**.\n\n3.\n| Genre | Personnages | Fin |\n| La comédie | **ordinaires** | elle finit **bien** |\n| La tragédie | **illustres**, pris dans un destin funeste | elle finit **mal** |"}$exo$::jsonb),
  ('e77034bb-2c62-5e62-8c94-b3d3a29313a2'::uuid, 2, 'redaction', $exo${"titre":"Un soir au théâtre : l’illusion et l’ironie dramatique","consigne":"Lis le récit d’un spectateur, puis explique comment fonctionne l’illusion théâtrale en citant le texte.","enonce":"Lis ce récit.\n\n> Le rideau s’ouvre. Une lumière bleue éclaire une table et deux chaises : nous sommes dans une cuisine, la nuit. Un bruit de pluie remplit la salle. Une comédienne entre, vêtue d’un tablier, les cheveux gris poudrés de blanc. Je sais bien que c’est une jeune actrice et que la pluie vient d’un haut-parleur. Pourtant, je frissonne avec elle. Soudain, un voleur se glisse sous la table. Elle ne le voit pas et dit en souriant : « Enfin seule et bien tranquille ! » Toute la salle éclate de rire.\n\n1. Relève quatre outils de l’illusion utilisés dans ce spectacle et dis ce que chacun apporte.\n2. Relève la phrase qui montre que le spectateur sait qu’il est au théâtre, puis celle qui montre qu’il accepte d’y croire. Comment s’appelle cette attitude ?\n3. Pourquoi la salle rit-elle ? Explique en utilisant l’expression **ironie dramatique**.","bareme":[{"critere":"Quatre outils de l’illusion relevés et expliqués","points":7},{"critere":"Convention théâtrale expliquée avec les deux citations","points":7},{"critere":"Ironie dramatique expliquée à partir de la scène","points":6}],"dureeMin":11,"corrige":"1. Outils de l’illusion :\n- la **lumière** (« Une lumière bleue ») : elle colore la scène et suggère la nuit ;\n- le **décor** et les **accessoires** (« une table et deux chaises ») : ils représentent le lieu, une cuisine ;\n- le **son** (« Un bruit de pluie ») : il crée l’atmosphère ;\n- le **costume** et le **maquillage** (« vêtue d’un tablier, les cheveux gris poudrés de blanc ») : ils construisent le personnage d’une vieille femme ;\n- on accepte aussi le **jeu** de l’actrice (sourire, voix).\n\n2. Le spectateur sait qu’il est au théâtre : « **Je sais bien que c’est une jeune actrice et que la pluie vient d’un haut-parleur.** » Il accepte pourtant d’y croire : « **Pourtant, je frissonne avec elle.** » C’est la **convention théâtrale**, ou « suspension volontaire de l’incrédulité » : on ne se laisse pas tromper, on **accepte** d’être trompé. C’est un contrat, pas une naïveté.\n\n3. La salle rit parce que les spectateurs **savent** qu’un voleur est caché sous la table, alors que le personnage **l’ignore** et se croit « seul et bien tranquille ». Ce décalage entre ce que sait le public et ce qu’ignore le personnage s’appelle l’**ironie dramatique** ; c’est une grande source de plaisir."}$exo$::jsonb),
  ('e77034bb-2c62-5e62-8c94-b3d3a29313a2'::uuid, 3, 'redaction', $exo${"titre":"Devenir metteur en scène : le vase brisé","consigne":"Lis la courte scène, analyse-la, puis rédige tes choix de mise en scène en les justifiant.","enonce":"Lis cette courte scène.\n\n> *Un salon. Au sol, les morceaux d’un vase. Lise, la servante, les cache vite sous le tapis.*\n> LISE, *à part*. — Pourvu que Madame ne s’aperçoive de rien !\n> MADAME PERNELLE, *entrant*. — Lise, où est mon beau vase de Chine ?\n> LISE. — Votre vase, Madame ? Il… il prend l’air à la fenêtre.\n> MADAME PERNELLE, *marchant sur le tapis*. — Tiens, ce tapis fait un drôle de bruit…\n> LISE, *à part*. — Je suis perdue !\n\n1. S’agit-il d’une comédie ou d’une tragédie ? Justifie avec deux arguments tirés du cours et du texte.\n2. Relève les deux apartés. Explique ce que le spectateur sait et que Madame Pernelle ignore. Comment appelle-t-on ce décalage ? Quel effet produit-il ?\n3. **Écriture** : tu es metteur en scène. Rédige une **note de mise en scène** (8 à 12 lignes) pour cette scène. Présente tes choix pour : le **décor** et les **accessoires**, les **costumes**, la **lumière**, le **son**, et le **jeu** des deux actrices (voix, gestes, regard, silence). Justifie chaque choix en expliquant ce qu’il apporte au spectateur.\n4. Explique en une ou deux phrases pourquoi on dit qu’un texte de théâtre n’est achevé que sur une scène.","bareme":[{"critere":"Genre identifié et justifié","points":4},{"critere":"Apartés relevés et ironie dramatique expliquée","points":5},{"critere":"Note de mise en scène : cinq outils traités","points":5},{"critere":"Choix justifiés par leur effet sur le spectateur","points":4},{"critere":"Théâtre écrit pour être joué expliqué","points":2}],"dureeMin":20,"corrige":"1. C’est une **comédie** : les personnages sont **ordinaires** (une servante et sa maîtresse), la situation est quotidienne et **drôle** (un vase cassé, un mensonge maladroit), et rien ne laisse prévoir une fin funeste ; ce n’est pas un destin tragique de personnages illustres.\n\n2. Apartés : « **Pourvu que Madame ne s’aperçoive de rien !** » et « **Je suis perdue !** ». Le spectateur sait que le vase est **cassé** et que les morceaux sont **sous le tapis**, alors que Madame Pernelle l’ignore. Ce décalage s’appelle l’**ironie dramatique**. Il crée du **plaisir** et du **suspense comique** : on attend le moment où elle va découvrir la vérité, surtout quand elle marche sur le tapis.\n\n3. **Exemple de note de mise en scène** :\n> Le décor sera un salon bourgeois : un fauteuil, un guéridon vide bien visible et un grand tapis au centre, pour que le public n’oublie pas la cachette. Lise portera un tablier et une coiffe simples ; Madame Pernelle une robe longue et un éventail, pour montrer tout de suite qui commande. La lumière sera vive et chaude, comme dans une comédie ; au moment des apartés, un faisceau isolera Lise pour montrer que Madame ne l’entend pas. Un craquement de porcelaine, exagéré, retentira quand Madame marchera sur le tapis, pour faire rire. Lise parlera vite, avec un sourire forcé, et jettera des regards inquiets vers le tapis ; avant « Je suis perdue ! », un court silence fera monter la tension. Madame Pernelle, lente et majestueuse, ne regardera jamais vers le sol.\n\nÉléments valorisés : les cinq outils traités ; chaque choix est **justifié** (ce qu’il montre ou fait ressentir) ; les choix sont cohérents avec une comédie.\n\n4. Le théâtre est écrit **pour être joué** : le texte attend des **corps**, des **voix**, une **lumière** et un **public**. Sur la page, il n’est qu’une partition ; c’est la représentation qui l’achève."}$exo$::jsonb),
  ('fd7d8ba4-d56d-5ba6-990f-6b6f69cbb3ae'::uuid, 1, 'redaction', $exo${"titre":"Le Petit Chaperon Rouge de Pommerat : l’essentiel","consigne":"Réponds aux questions sur la pièce de Joël Pommerat par des phrases complètes.","enonce":"1. Qui est **Joël Pommerat** ? En quelle année a-t-il créé son *Petit Chaperon Rouge*, et quel conte réécrit-il ? De quel auteur est ce conte ?\n2. Cite deux éléments que Pommerat **garde** du conte et deux éléments qu’il **change**.\n3. Définis les verbes **réécrire**, **adapter** et **parodier**. Lesquels s’appliquent au travail de Pommerat ? Lequel ne s’applique pas, et pourquoi ?","bareme":[{"critere":"Auteur, date, conte et auteur d’origine","points":5},{"critere":"Deux éléments gardés et deux éléments changés","points":7},{"critere":"Trois définitions et application à Pommerat","points":8}],"dureeMin":8,"corrige":"1. Joël Pommerat est un **auteur et metteur en scène contemporain**. Son *Petit Chaperon Rouge* date de **2004**. Il réécrit pour la scène le conte du **Petit Chaperon rouge** de **Charles Perrault**.\n\n2. **Il garde** : la petite fille, la mère, la grand-mère ; le loup, le chemin, la dévoration.\n**Il change** : un **narrateur** vient sur scène raconter et commenter ; les personnages **n’ont pas de nom** (« la petite fille », « la mère ») ; le cadre devient **quotidien** (une mère trop occupée, une enfant qui s’ennuie).\n\n3.\n- **Réécrire** : reprendre une trame et la traiter autrement.\n- **Adapter** : faire passer une œuvre d’un genre à un autre (ici, du conte au théâtre).\n- **Parodier** : imiter en exagérant, pour faire rire.\nPommerat **réécrit** et **adapte** le conte. Il **ne le parodie pas**, car son texte est **grave** : il ne cherche pas à faire rire."}$exo$::jsonb),
  ('fd7d8ba4-d56d-5ba6-990f-6b6f69cbb3ae'::uuid, 2, 'redaction', $exo${"titre":"Comparer Perrault et Pommerat","consigne":"Lis la fin du conte de Perrault, puis compare-la avec les choix de Pommerat en justifiant tes réponses.","enonce":"Voici la fin du conte de **Charles Perrault** (1697) et sa moralité.\n\n> Et en disant ces mots, ce méchant Loup se jeta sur le petit Chaperon rouge, et la mangea.\n>\n> MORALITÉ\n> On voit ici que de jeunes enfants,\n> Surtout de jeunes filles\n> Belles, bien faites, et gentilles,\n> Font très mal d’écouter toute sorte de gens,\n> Et que ce n’est pas chose étrange,\n> S’il en est tant que le loup mange.\n\n1. Explique avec tes mots la moralité de Perrault. À qui s’adresse-t-elle ?\n2. Chez Pommerat, l’accent n’est plus mis sur cette morale. Sur quoi le déplace-t-il ? Comment le rôle de la mère change-t-il ?\n3. Chez Pommerat, la pièce se joue presque dans le noir et le loup est souvent une ombre ou une voix. Pourquoi ce choix fait-il peur ? En quoi le noir est-il « le décor » ?\n4. Le conte parle de l’enfance qui grandit. Retrouve les quatre étapes de ce parcours.","bareme":[{"critere":"Moralité de Perrault expliquée et destinataires identifiés","points":5},{"critere":"Déplacement de l’accent et rôle de la mère","points":5},{"critere":"Rôle de la lumière et de l’obscurité expliqué","points":5},{"critere":"Quatre étapes du parcours de l’enfant","points":5}],"dureeMin":12,"corrige":"1. La moralité dit que les enfants, et surtout les **jeunes filles** jolies et gentilles, ont **tort d’écouter n’importe qui** : il n’est pas étonnant que le « loup » en dévore beaucoup. Autrement dit : **« n’écoutez pas les inconnus »**. Elle s’adresse aux **jeunes enfants**, en particulier aux jeunes filles (et aux adultes qui les éduquent). La morale est **explicite** : elle est écrite à part, à la fin.\n\n2. Pommerat déplace l’accent de la morale vers la **solitude** de l’enfant et son **désir d’aventure**. La mère n’est plus seulement celle qui envoie sa fille chez la grand-mère : c’est une **mère trop occupée**, et l’enfant **s’ennuie** ; le cadre devient **quotidien**.\n\n3. La **peur naît de ce qu’on ne voit pas** : le spectateur imagine le loup, et ce qu’il imagine est plus effrayant qu’un costume. Le noir, traversé de faisceaux de lumière, n’est pas une absence de décor : c’est **le décor lui-même** et le **sujet** du spectacle, qui parle de la peur.\n\n4. Les quatre étapes : **quitter la maison** → **désobéir** → **affronter la peur** → **revenir changé**."}$exo$::jsonb),
  ('fd7d8ba4-d56d-5ba6-990f-6b6f69cbb3ae'::uuid, 3, 'redaction', $exo${"titre":"Réécrire le début du conte pour la scène","consigne":"Réécris le début du conte de Perrault sous forme de scène de théâtre, à la manière de Pommerat, puis justifie tes choix.","enonce":"Voici le début du conte de **Charles Perrault**.\n\n> Il était une fois une petite fille de Village, la plus jolie qu’on eût su voir ; sa mère en était folle, et sa mère-grand plus folle encore. Cette bonne femme lui fit faire un petit chaperon rouge, qui lui seyait si bien, que partout on l’appelait le petit Chaperon rouge.\n\n1. **Écriture** : réécris ce début pour la scène, à la manière de Pommerat (10 à 15 lignes). Ta scène doit contenir :\n   - un **narrateur** qui raconte et commente ;\n   - des personnages **sans nom** (« la petite fille », « la mère ») ;\n   - un cadre **quotidien** : une mère trop occupée, une enfant qui s’ennuie ;\n   - au moins deux **didascalies** qui utilisent la **lumière** et l’**obscurité** ;\n   - un ton **grave**, pas parodique.\n2. Explique en trois ou quatre phrases ce que tu as **gardé** du texte de Perrault et ce que tu as **changé**.\n3. Ton travail est-il une réécriture, une adaptation ou une parodie ? Justifie en utilisant les définitions du cours.","bareme":[{"critere":"Présence d’un narrateur et personnages sans nom","points":5},{"critere":"Cadre quotidien et ton grave respectés","points":4},{"critere":"Didascalies utilisant la lumière et l’obscurité","points":4},{"critere":"Éléments gardés et changés expliqués","points":4},{"critere":"Réécriture et adaptation justifiées par les définitions","points":3}],"dureeMin":20,"corrige":"1. **Exemple de scène** :\n> *Le noir. Un faisceau de lumière s’allume sur un homme debout, face au public.*\n> LE NARRATEUR. — Il y avait une fois une petite fille qui ne sortait jamais seule de chez elle. Sa mère l’aimait, oui. Mais sa mère travaillait beaucoup.\n> *Une lampe éclaire faiblement une table. La mère, penchée sur des papiers, ne lève pas la tête. La petite fille est assise dans l’ombre.*\n> LA PETITE FILLE. — Maman, on peut jouer ?\n> LA MÈRE. — Pas maintenant. Plus tard.\n> LA PETITE FILLE. — Tu dis toujours « plus tard ».\n> LE NARRATEUR. — La petite fille s’ennuyait. Elle attendait. Elle regardait la fenêtre, et derrière la fenêtre, le chemin, et au bout du chemin, la forêt.\n> *La lampe s’éteint. Seule la silhouette de l’enfant reste visible, découpée contre la fenêtre.*\n> LA PETITE FILLE, *tout bas*. — Un jour, j’irai toute seule.\n\n2. **Exemple d’explication** : J’ai gardé la petite fille, sa mère et l’idée du début de conte (« Il était une fois » devient « Il y avait une fois »). J’ai supprimé le chaperon rouge et la beauté de l’enfant. J’ai ajouté un narrateur, j’ai enlevé les noms et j’ai placé l’histoire dans une maison ordinaire, avec une mère trop occupée. La lumière et l’obscurité montrent la solitude de l’enfant et annoncent la peur.\n\n3. C’est une **réécriture**, car je reprends la trame de Perrault en la traitant autrement ; et une **adaptation**, car je fais passer le texte du **conte** au **théâtre**. Ce n’est **pas une parodie** : je n’exagère pas pour faire rire, le ton reste **grave**.\n\n**Éléments valorisés** : narrateur présent ; personnages désignés par leur rôle ; didascalies en italique avec lumière et noir ; thème de la solitude et du désir d’aventure ; présentation théâtrale correcte ; orthographe soignée."}$exo$::jsonb),
  ('5a4bc8ef-ec15-5356-af90-cb8ef5afcf17'::uuid, 1, 'redaction', $exo${"titre":"Les familles de couleurs","consigne":"Réponds à chaque question par une ou deux phrases complètes. Utilise le vocabulaire du cours.","enonce":"1. Cite les **trois couleurs primaires** et explique ce qui les rend particulières.\n2. Qu’est-ce qu’une **couleur secondaire** ? Donne un exemple en précisant les deux couleurs mélangées.\n3. Qu’est-ce qu’une **couleur tertiaire** ? Donne un exemple.\n4. Classe ces couleurs en **chaudes** ou **froides** : rouge, bleu, orange, vert, jaune.","bareme":[{"critere":"Primaires citées et définies (impossibles à obtenir par mélange)","points":6},{"critere":"Secondaires et tertiaires définies avec un exemple juste","points":8},{"critere":"Classement correct des couleurs chaudes et froides","points":6}],"dureeMin":6,"corrige":"1. Les trois primaires sont le **magenta** (rouge), le **cyan** (bleu) et le **jaune**. On ne peut **pas les obtenir en mélangeant** d’autres couleurs.\n2. Une secondaire s’obtient en mélangeant **deux primaires**. Exemples : jaune + cyan = **vert** ; jaune + magenta = **orange** ; magenta + cyan = **violet**.\n3. Une tertiaire s’obtient en mélangeant **une primaire et une secondaire voisine**. Exemples : jaune + orange = jaune-orangé ; cyan (bleu) + vert = bleu-vert ; magenta (rouge) + violet = rouge-violet.\n4. **Chaudes** : rouge, orange, jaune. **Froides** : bleu, vert.\n\nÉléments valorisés : l’idée que les primaires sont la base de tous les mélanges ; la précision « voisine » pour la tertiaire."}$exo$::jsonb),
  ('5a4bc8ef-ec15-5356-af90-cb8ef5afcf17'::uuid, 2, 'redaction', $exo${"titre":"Choisir ses couleurs pour une affiche","consigne":"Lis la situation, puis réponds aux questions en justifiant chaque choix avec le vocabulaire du cours.","enonce":"Léa prépare une **affiche pour la fête du collège**. Elle veut que le mot « FÊTE », écrit en **orange**, se voie de très loin.\n\n1. Quelle couleur de fond lui conseilles-tu pour faire ressortir le mot au maximum ? Comment s’appelle ce couple de couleurs ?\n2. Léa hésite : elle a envie de mélanger un peu de cette couleur de fond dans son orange « pour que ça aille bien ensemble ». Explique ce qui risque de se passer.\n3. En bas de l’affiche, elle dessine une scène avec un soleil et des montagnes au loin. Quelles familles de couleurs lui conseilles-tu pour le soleil au premier plan et pour les montagnes au loin ? Pourquoi ?","bareme":[{"critere":"Fond bleu proposé et notion de complémentaires nommée","points":6},{"critere":"Effet du mélange de complémentaires expliqué (gris, couleur éteinte)","points":6},{"critere":"Chaudes devant, froides au loin, avec l’idée d’avancer et de reculer","points":6},{"critere":"Réponses rédigées et justifiées","points":2}],"dureeMin":10,"corrige":"1. Il faut un fond **bleu** : le bleu et l’orange sont des **couleurs complémentaires** (elles se font face sur le cercle chromatique). **Posées côte à côte, elles se renforcent** : le mot orange ressortira très fortement.\n2. Si Léa **mélange** du bleu dans son orange, les deux complémentaires vont **s’éteindre** : l’orange deviendra **terne, grisâtre, brunâtre**. Le mot ressortira beaucoup moins. Le même couple donne l’effet le plus vif côte à côte et le plus terne mélangé.\n3. Pour le soleil au premier plan : des **couleurs chaudes** (jaune, orange, rouge), qui semblent **avancer**. Pour les montagnes lointaines : des **couleurs froides** (bleus, verts), qui semblent **reculer**. On crée ainsi de la **profondeur** sans perspective.\n\nÉléments valorisés : l’emploi des mots « complémentaires », « cercle chromatique », « profondeur » ; toute proposition cohérente et justifiée (par exemple ajouter des bleus pâles pour les montagnes)."}$exo$::jsonb),
  ('5a4bc8ef-ec15-5356-af90-cb8ef5afcf17'::uuid, 3, 'redaction', $exo${"titre":"Analyser les couleurs d’un paysage imaginaire","consigne":"Analyse le tableau décrit en mobilisant plusieurs notions du cours (complémentaires, chaudes et froides, valeur, saturation). Justifie chaque réponse.","enonce":"Voici la description d’un tableau imaginaire.\n\n> Au premier plan, un **bateau rouge vif** flotte sur une **eau verte**. Au fond, des collines peintes dans un **bleu très pâle**. Le ciel est d’un **bleu marine très sombre mais très intense**. Dans un coin, une petite zone a été peinte avec un **mélange de rouge et de vert** : elle paraît **grise et terne**.\n\n1. Pourquoi le bateau attire-t-il immédiatement le regard ? Nomme la notion.\n2. Explique pourquoi la petite zone du coin paraît grise, alors qu’elle est faite avec les mêmes couleurs que le bateau et l’eau.\n3. Comment le peintre donne-t-il l’impression que les collines sont loin ? Utilise deux notions.\n4. Le ciel est « très sombre mais très intense ». Explique cette phrase avec les mots **valeur** et **saturation**.\n5. Conclus : en quoi la couleur est-elle ici « un outil de composition » et pas un simple décor ?","bareme":[{"critere":"Contraste des complémentaires rouge et vert côte à côte identifié","points":4},{"critere":"Mélange de complémentaires qui s’éteignent en gris expliqué","points":4},{"critere":"Profondeur expliquée par les couleurs froides et la pâleur","points":4},{"critere":"Valeur et saturation distinguées correctement","points":4},{"critere":"Conclusion argumentée sur le rôle de la couleur","points":4}],"dureeMin":16,"corrige":"1. Le bateau **rouge** est posé sur une eau **verte** : ce sont des **couleurs complémentaires**. **Côte à côte, elles se renforcent**, d’où un contraste très fort. De plus le rouge est une couleur **chaude**, qui semble **avancer**.\n2. Dans le coin, le rouge et le vert sont **mélangés** (l’un dans l’autre) : des complémentaires mélangées **s’éteignent en gris**. Même couple, effet opposé : vif côte à côte, terne mélangé.\n3. Les collines sont **bleues** : une couleur **froide**, qui semble **reculer**. Elles sont aussi **très pâles** (peu saturées, claires), ce qui donne l’impression de lointain. (On peut valoriser l’élève qui cite la perspective atmosphérique : au loin, les objets deviennent pâles et bleutés.)\n4. La **valeur** mesure le degré de clair ou de sombre : le ciel a une valeur **sombre**. La **saturation** mesure l’intensité : le ciel est **très saturé**. Les deux notions sont **indépendantes** : une couleur peut être à la fois sombre et vive.\n5. Chaque couleur a un rôle : attirer le regard (bateau), créer la profondeur (collines), installer une ambiance (ciel). La couleur **organise l’image** et guide le regard : c’est un outil de composition.\n\nÉléments valorisés : vocabulaire précis, justification de chaque réponse, lien entre plusieurs notions."}$exo$::jsonb),
  ('d385ebb2-0f30-5639-af46-c6cc002f48b3'::uuid, 1, 'redaction', $exo${"titre":"Les procédés pour représenter l’espace","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Explique la règle de chacun de ces trois procédés simples : la **superposition**, l’**étagement**, la **taille relative**.\n2. À quelle époque la **perspective linéaire** a-t-elle été inventée ?\n3. Que sont la **ligne d’horizon** et le **point de fuite** ?\n4. Combien de points de fuite utilise-t-on pour une **vue frontale** ? Et pour une **vue d’angle** ?","bareme":[{"critere":"Les trois procédés simples expliqués correctement","points":9},{"critere":"Perspective linéaire : époque, ligne d’horizon et point de fuite","points":7},{"critere":"Nombre de points de fuite selon la vue","points":4}],"dureeMin":7,"corrige":"1. **Superposition** : ce qui **cache** une autre chose est **devant**. **Étagement** : ce qui est placé **plus haut** sur la feuille paraît **plus loin**. **Taille relative** : plus un objet est dessiné **petit**, plus il paraît **loin**.\n2. La perspective linéaire a été inventée à la **Renaissance** (XVe siècle, en Italie).\n3. La **ligne d’horizon** est une ligne horizontale placée **à hauteur des yeux** de celui qui regarde. Le **point de fuite** est le point, situé **sur la ligne d’horizon**, vers lequel **convergent** (se rejoignent) les lignes parallèles qui s’éloignent.\n4. Vue frontale : **un** point de fuite. Vue d’angle : **deux** points de fuite.\n\nÉléments valorisés : exemples personnels (un arbre qui cache une maison, etc.)."}$exo$::jsonb),
  ('d385ebb2-0f30-5639-af46-c6cc002f48b3'::uuid, 2, 'redaction', $exo${"titre":"Construire la profondeur d’une rue","consigne":"Lis la description du dessin, puis explique par écrit comment Tom peut créer la profondeur. Utilise le vocabulaire du cours.","enonce":"Tom veut dessiner une **longue rue droite** vue **de face**, comme s’il se tenait au milieu du trottoir. Il y a des maisons de chaque côté, des lampadaires tous de la même hauteur, une voiture garée devant une maison et des montagnes tout au fond.\n\n1. Tom utilise la perspective linéaire. Combien de points de fuite lui faut-il ? Où doit-il les placer ?\n2. Décris, en étapes numérotées, comment il doit tracer les bords de la rue et les toits des maisons.\n3. Comment doit-il dessiner les lampadaires pour qu’ils paraissent s’éloigner ? Nomme le procédé.\n4. La voiture cache une partie d’une maison. Quel procédé est utilisé et que comprend-on ?\n5. Comment peindre les montagnes du fond pour renforcer l’impression de lointain ?","bareme":[{"critere":"Un seul point de fuite sur la ligne d’horizon, à hauteur d’œil","points":5},{"critere":"Étapes de tracé cohérentes (lignes qui convergent vers le point)","points":5},{"critere":"Taille relative et superposition identifiées et expliquées","points":6},{"critere":"Perspective atmosphérique appliquée aux montagnes","points":4}],"dureeMin":11,"corrige":"1. La rue est vue **de face** : c’est une **vue frontale**, donc **un seul point de fuite**. Tom le place **sur la ligne d’horizon**, qu’il trace **à hauteur de ses yeux**, au bout de la rue.\n2. Étapes attendues : 1) tracer la **ligne d’horizon** ; 2) placer le **point de fuite** au milieu ; 3) tracer les **bords de la rue** et des trottoirs comme des lignes qui partent du bas de la feuille et **se rejoignent au point de fuite** ; 4) tracer aussi les lignes des **toits** et du bas des maisons vers ce même point ; 5) ajouter les verticales des façades.\n3. Les lampadaires ont en réalité la même hauteur, mais Tom doit les dessiner **de plus en plus petits** en s’approchant du point de fuite : c’est la **taille relative** (plus c’est petit, plus c’est loin).\n4. C’est la **superposition** : ce qui cache est devant, donc on comprend que la **voiture est devant la maison**.\n5. Il utilise la **perspective atmosphérique** : les montagnes lointaines doivent être **pâles, bleutées, un peu floues et peu contrastées**.\n\nÉléments valorisés : l’idée que les lignes parallèles dans la réalité se rejoignent sur le dessin ; la citation de Léonard de Vinci."}$exo$::jsonb),
  ('d385ebb2-0f30-5639-af46-c6cc002f48b3'::uuid, 3, 'redaction', $exo${"titre":"Deux tableaux, deux façons de traiter l’espace","consigne":"Compare les deux œuvres décrites en mobilisant plusieurs notions du cours, puis donne ton avis argumenté.","enonce":"**Œuvre A** – un tableau de la Renaissance : une salle au carrelage en damier dont les lignes se rejoignent en un point, au centre, derrière un personnage. Au fond, par une fenêtre, un paysage de collines **bleutées et floues**.\n\n**Œuvre B** – un tableau cubiste du début du XXe siècle : une guitare et une bouteille sur une table. On voit **en même temps** le dessus de la table et son côté, la bouteille **de face et de dessus**. Il n’y a ni point de fuite ni horizon.\n\n1. Dans l’œuvre A, nomme les **deux perspectives** utilisées et explique comment chacune fonctionne.\n2. Où se trouve probablement la **ligne d’horizon** de l’œuvre A ? Justifie.\n3. Explique ce que fait l’artiste de l’œuvre B avec l’espace. Nomme le mouvement et un artiste qui en fait partie.\n4. Un camarade dit : « Le peintre de l’œuvre B ne savait pas dessiner en perspective. » Réponds-lui en argumentant.\n5. Selon toi, laquelle des deux œuvres donne le plus d’informations sur les objets ? Justifie.","bareme":[{"critere":"Perspectives linéaire et atmosphérique identifiées et expliquées","points":5},{"critere":"Ligne d’horizon située au niveau du point de fuite","points":3},{"critere":"Cubisme : plusieurs points de vue à la fois, artiste juste","points":4},{"critere":"Réponse argumentée sur la rupture volontaire avec la règle","points":5},{"critere":"Avis personnel justifié","points":3}],"dureeMin":18,"corrige":"1. **Perspective linéaire** : les lignes du carrelage, parallèles dans la réalité, **convergent vers un point de fuite** situé au centre. **Perspective atmosphérique** : les collines du fond sont **bleutées et floues** car plus un objet est loin, plus il devient pâle, bleuté, flou et peu contrasté.\n2. La ligne d’horizon passe **par le point de fuite**, au centre, derrière le personnage : le point de fuite est toujours **sur la ligne d’horizon**, à hauteur d’œil.\n3. L’œuvre B montre **plusieurs points de vue à la fois** (de face et de dessus) : c’est le **cubisme**. Artistes : **Pablo Picasso** ou **Georges Braque**.\n4. Réponse attendue : c’est un **choix délibéré**. Au XXe siècle, des artistes ont **volontairement cassé** les règles de la perspective. Ils les connaissaient : **connaître la règle permet d’en jouer**. Le cubiste veut montrer l’objet sous toutes ses faces, pas imiter la vue d’un seul œil.\n5. Réponse libre si elle est justifiée. Exemple : l’œuvre B donne plus d’informations sur la **forme** des objets (on voit plusieurs faces) ; l’œuvre A donne une impression plus **réaliste de profondeur**.\n\nÉléments valorisés : vocabulaire précis (convergent, point de fuite, horizon), lien entre les deux œuvres, argument nuancé."}$exo$::jsonb),
  ('2093a9de-c71f-58d1-b146-507bede95b8e'::uuid, 1, 'redaction', $exo${"titre":"Gestes, matériaux et supports","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Cite **quatre gestes** plastiques.\n2. Donne **un exemple** pour chaque famille de matériaux : les traçants, les peintures, les matières rapportées.\n3. Qu’apporte le **collage** dans une œuvre ? À quelle époque est-il apparu ?\n4. Explique la phrase : « Le support n’est jamais neutre. »","bareme":[{"critere":"Quatre gestes plastiques corrects","points":5},{"critere":"Un exemple juste pour chaque famille de matériaux","points":6},{"critere":"Collage : époque et introduction du réel","points":4},{"critere":"Rôle du support expliqué","points":5}],"dureeMin":7,"corrige":"1. Quatre gestes parmi : **tracer, frotter, gratter, déchirer, coller, superposer, effacer, tamponner**.\n2. **Traçants** : crayon, fusain, encre. **Peintures** : gouache, aquarelle (le cours cite aussi le pastel). **Matières rapportées** : papiers, tissus, objets récupérés.\n3. Le collage, apparu **au début du XXe siècle**, fait entrer **le réel** dans l’œuvre : on colle de vrais morceaux de papier, de journal, de tissu au lieu de les représenter.\n4. Le support (sa **taille**, sa **texture**, sa **nature**) change le sens de l’œuvre : un même dessin ne produit pas le même effet sur un petit papier lisse, un papier froissé ou une grande toile.\n\nÉléments valorisés : exemples précis ; citer Picasso ou Braque pour le collage."}$exo$::jsonb),
  ('2093a9de-c71f-58d1-b146-507bede95b8e'::uuid, 2, 'redaction', $exo${"titre":"Un même motif, trois outils","consigne":"Lis la situation et réponds en décrivant précisément les effets obtenus. Utilise le vocabulaire du cours.","enonce":"En classe, Inès peint **trois fois le même cercle bleu**, avec la **même gouache** : la première fois au **pinceau**, la deuxième au **rouleau**, la troisième à l’**éponge**.\n\n1. Décris, pour chaque outil, la trace que l’on peut s’attendre à voir.\n2. Quelle idée du cours cette expérience montre-t-elle ?\n3. Inès refait ensuite son cercle au pinceau, mais sur un **papier journal froissé** puis défroissé. Qu’est-ce qui change ? Nomme la caractéristique du support qui a été modifiée.\n4. Propose un **quatrième geste** qu’elle pourrait essayer et décris l’effet attendu.","bareme":[{"critere":"Traces du pinceau, du rouleau et de l’éponge décrites","points":6},{"critere":"Idée que chaque geste laisse une trace reconnaissable","points":4},{"critere":"Effet du support froissé et notion de texture","points":6},{"critere":"Quatrième geste pertinent et effet décrit","points":4}],"dureeMin":10,"corrige":"1. **Pinceau** : on voit les **traces des poils**, des bords plus ou moins nets, une couleur parfois inégale. **Rouleau** : une couleur **plus uniforme et plate**, avec parfois un léger grain et des bords moins précis. **Éponge** : une trace **tachetée, pleine de petits trous**, une matière vibrante et moins couvrante.\n2. **Chaque geste laisse une trace reconnaissable** : une même couleur n’a pas le même effet selon l’outil. Le geste fait partie de l’œuvre.\n3. Sur le papier froissé, la peinture se dépose **irrégulièrement** : elle s’accroche aux reliefs, laisse des plis visibles, des cassures. C’est la **texture** du support qui a changé. Le support **n’est jamais neutre**.\n4. Exemples : **tamponner** avec un bouchon (cercles répétés), **gratter** la peinture fraîche (lignes claires qui apparaissent), **frotter** sur une surface en relief, **déchirer** un papier peint puis le coller.\n\nÉléments valorisés : descriptions précises et imagées ; vocabulaire (trace, texture, support, geste)."}$exo$::jsonb),
  ('2093a9de-c71f-58d1-b146-507bede95b8e'::uuid, 3, 'redaction', $exo${"titre":"Le hasard maîtrisé : projet et analyse","consigne":"Analyse les deux démarches d’artistes, puis décris ton propre projet en étapes. Justifie tes choix avec le vocabulaire du cours.","enonce":"1. Explique ce que sont le **frottage** de **Max Ernst** et le **dripping** de **Jackson Pollock**. Pour chacun, précise le geste, l’outil ou le matériau, et la part de hasard.\n2. Explique la phrase : « Le hasard en art n’est pas de la négligence : c’est une décision. »\n3. **Projet** : tu dois réaliser une œuvre intitulée « La forêt secrète » en utilisant **le hasard maîtrisé**. Décris ton projet en **quatre étapes au moins** : le **support** choisi (taille, texture, nature), les **matériaux**, les **gestes**, et ce que tu fais des « accidents » obtenus.\n4. Justifie le choix de ton support : quel effet veux-tu produire sur le spectateur ?","bareme":[{"critere":"Frottage et dripping décrits avec justesse","points":6},{"critere":"Hasard provoqué puis choisi : explication claire","points":4},{"critere":"Projet en étapes utilisant le hasard maîtrisé","points":6},{"critere":"Choix du support justifié par l’effet recherché","points":4}],"dureeMin":18,"corrige":"1. **Frottage (Max Ernst)** : on pose une feuille sur une surface en relief (plancher, feuilles d’arbre, tissu) et on **frotte** dessus avec un crayon ou du graphite ; les textures apparaissent sans être dessinées. Le hasard vient des motifs qui surgissent ; l’artiste les **regarde** et y voit des forêts, des animaux, qu’il **choisit** de garder ou de compléter. **Dripping (Jackson Pollock)** : la toile est posée **au sol** ; l’artiste fait **couler et goutter** la peinture depuis un bâton ou un pot en se déplaçant autour. Le hasard est dans les coulures et les éclaboussures, mais le **geste du corps** est contrôlé.\n2. L’artiste **provoque** volontairement un accident (coulure, empreinte, tache), puis **décide** de le garder, de le transformer ou de le refuser. C’est un **savoir-faire**, pas un manque de soin.\n3. Exemple de projet : 1) support : **grand format**, papier épais ; 2) **frottage** d’écorces et de feuilles au crayon gras pour créer les textures d’arbres ; 3) **coulures** d’encre verte et brune en inclinant la feuille pour former des troncs ; 4) **tamponner** à l’éponge pour le feuillage ; 5) observer les taches, **choisir** celles qui ressemblent à des yeux ou des créatures et les **garder**, en recouvrant les autres par **superposition** de papiers collés.\nToute démarche cohérente est acceptée si elle contient : support, matériaux, gestes, et **tri des accidents**.\n4. Exemple : un **grand format** pour que le spectateur se sente entouré par la forêt ; un papier **froissé** pour évoquer l’écorce. Le support **n’est jamais neutre**.\n\nÉléments valorisés : vocabulaire précis, cohérence entre titre, gestes et support."}$exo$::jsonb),
  ('f5fe06c7-f924-5f8d-becd-c362ada910fb'::uuid, 1, 'redaction', $exo${"titre":"Les quatre paramètres du son","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Cite les **quatre paramètres du son** et dis ce que chacun décrit.\n2. Un son de **fréquence élevée** est-il aigu ou grave ? Quelle est la fréquence du **la du diapason** ?\n3. Range ces figures de note de la **plus longue à la plus courte** : noire, ronde, croche, blanche.\n4. Que veulent dire les nuances ***piano*** et ***forte*** ?","bareme":[{"critere":"Quatre paramètres nommés et définis","points":8},{"critere":"Hauteur : fréquence et la 440 Hz","points":4},{"critere":"Figures de note correctement rangées","points":4},{"critere":"Nuances piano et forte expliquées","points":4}],"dureeMin":6,"corrige":"1. La **hauteur** (aigu ou grave), la **durée** (long ou court), l’**intensité** (le volume, fort ou doux), le **timbre** (la « couleur » du son, ce qui permet de reconnaître l’instrument).\n2. Une fréquence élevée donne un son **aigu**. Le la du diapason vibre à **440 Hz** (hertz).\n3. **Ronde → blanche → noire → croche**. Chaque figure vaut la moitié de la précédente.\n4. ***Piano*** : **doux**. ***Forte*** : **fort**.\n\nÉléments valorisés : l’unité hertz, l’idée de division par deux."}$exo$::jsonb),
  ('f5fe06c7-f924-5f8d-becd-c362ada910fb'::uuid, 2, 'redaction', $exo${"titre":"Décrire une situation d’écoute","consigne":"Lis la description de l’extrait, puis réponds en nommant à chaque fois le paramètre du son concerné.","enonce":"Voici la description d’un extrait musical.\n\n> Au début, une **flûte** joue une mélodie **très douce** dans l’**aigu**. Puis un **violon** reprend **exactement les mêmes notes**. Ensuite, un **tuba** entre avec une note **grave** qui dure **longtemps**. Enfin, tout l’orchestre joue de **plus en plus fort** jusqu’à un final **très fort**.\n\n1. Quelle nuance italienne correspond au début de l’extrait ? Et au final ?\n2. Comment s’appelle le passage où l’orchestre joue « de plus en plus fort » ?\n3. La flûte et le violon jouent les mêmes notes. Quel paramètre permet quand même de les distinguer ? D’où vient-il ?\n4. Compare la note du tuba à celle de la flûte selon **deux paramètres**.\n5. Si la note du tuba dure une **ronde**, combien de **noires** faut-il pour obtenir la même durée ? Explique.","bareme":[{"critere":"Nuances piano, fortissimo et crescendo nommées","points":6},{"critere":"Timbre identifié et lié aux harmoniques","points":5},{"critere":"Comparaison tuba et flûte en hauteur et en durée","points":5},{"critere":"Calcul ronde et noires justifié","points":4}],"dureeMin":11,"corrige":"1. Début très doux : ***piano*** (on accepte *pianissimo* s’il est justifié). Final très fort : ***fortissimo***.\n2. C’est un ***crescendo*** : l’intensité **augmente progressivement**.\n3. C’est le **timbre** : la « couleur » du son. Il vient des **harmoniques** produites par chaque instrument ; elles ne sont pas les mêmes pour une flûte et un violon.\n4. **Hauteur** : le tuba est **grave**, la flûte est **aiguë** (fréquence plus basse pour le tuba). **Durée** : la note du tuba est **longue**. (On accepte aussi le timbre comme paramètre de comparaison.)\n5. Une ronde vaut **deux blanches**, et une blanche vaut **deux noires** : il faut donc **4 noires** pour une ronde.\n\nÉléments valorisés : vocabulaire italien bien orthographié, raisonnement par division par deux."}$exo$::jsonb),
  ('f5fe06c7-f924-5f8d-becd-c362ada910fb'::uuid, 3, 'redaction', $exo${"titre":"Composer un paysage sonore avec les paramètres","consigne":"Imagine et décris par écrit un court paysage sonore. Pour chaque moment, justifie tes choix en nommant les paramètres du son.","enonce":"Tu dois imaginer la musique d’une courte scène : **« Un orage approche puis s’éloigne »**. Tu n’écris pas de partition : tu **décris** ta musique avec des mots.\n\n1. Découpe ta scène en **trois moments** (avant, pendant, après l’orage). Pour chacun, précise la **hauteur**, la **durée** des sons et l’**intensité** (avec une nuance italienne).\n2. Indique où tu places un ***crescendo*** et un ***decrescendo***, et explique pourquoi.\n3. Choisis **deux instruments** différents pour ta scène et explique ce que leur **timbre** apporte.\n4. Un camarade dit : « Un son aigu, c’est forcément un son fort. » Explique-lui pourquoi il se trompe, en t’appuyant sur la différence entre deux paramètres.","bareme":[{"critere":"Trois moments décrits avec hauteur, durée et intensité","points":6},{"critere":"Crescendo et decrescendo placés avec logique","points":4},{"critere":"Deux instruments choisis et rôle du timbre expliqué","points":4},{"critere":"Distinction hauteur et intensité argumentée","points":4},{"critere":"Vocabulaire musical précis et bien employé","points":2}],"dureeMin":18,"corrige":"Réponse libre ; exemple attendu :\n1. **Avant** : sons **aigus**, **courts** (croches), nuance ***piano*** (oiseaux, calme). **Pendant** : sons **graves**, **longs** (rondes, blanches) pour le tonnerre, nuance ***fortissimo***. **Après** : retour à des sons **aigus** et plus **longs**, nuance ***piano*** ou ***mezzo forte***.\n2. ***Crescendo*** quand l’orage **approche** (le bruit augmente) ; ***decrescendo*** quand il **s’éloigne** (le bruit diminue progressivement).\n3. Exemple : la **flûte** (timbre léger, aérien) pour les oiseaux ; les **timbales** ou le **tuba** (timbre sombre et puissant) pour le tonnerre. Le **timbre** permet de reconnaître chaque instrument et crée l’ambiance ; il vient des **harmoniques**.\n4. La **hauteur** (aigu/grave, liée à la **fréquence**) et l’**intensité** (fort/doux, le volume) sont **deux paramètres différents**. On peut jouer une note aiguë très doucement (flûte *piano*) ou une note grave très fort (tuba *forte*).\n\nÉléments valorisés : cohérence entre la scène et les choix sonores, nuances italiennes justes, usage des figures de note."}$exo$::jsonb),
  ('2a938ef3-f5f8-50d7-b584-05109a97b260'::uuid, 1, 'redaction', $exo${"titre":"Les familles d’instruments et les voix","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Dans la famille des **cordes**, explique la différence entre cordes **frottées**, **pincées** et **frappées**, avec un instrument pour chacune.\n2. Comment naît le son chez les **cuivres** ? Cite deux cuivres.\n3. Range ces instruments du **plus aigu au plus grave** : contrebasse, violon, violoncelle, alto.\n4. Cite les trois voix de femmes et les trois voix d’hommes.","bareme":[{"critere":"Trois types de cordes expliqués avec un instrument juste","points":6},{"critere":"Production du son des cuivres et deux exemples","points":4},{"critere":"Cordes frottées rangées de l’aigu au grave","points":4},{"critere":"Six voix citées et classées","points":6}],"dureeMin":7,"corrige":"1. **Frottées** : le son naît avec un **archet** (violon, alto, violoncelle, contrebasse). **Pincées** : la corde est pincée avec le **doigt** (harpe, guitare). **Frappées** : un **marteau** frappe la corde (piano).\n2. Chez les cuivres, le son naît de la **vibration des lèvres** dans l’embouchure. Exemples : **trompette, cor, trombone, tuba**.\n3. **Violon → alto → violoncelle → contrebasse**.\n4. Femmes : **soprano, mezzo-soprano, alto**. Hommes : **ténor, baryton, basse**.\n\nÉléments valorisés : l’ordre des voix de l’aigu au grave."}$exo$::jsonb),
  ('2a938ef3-f5f8-50d7-b584-05109a97b260'::uuid, 2, 'redaction', $exo${"titre":"Classer les instruments d’un concert","consigne":"Lis la description du concert, puis classe et justifie. Rappelle-toi : c’est la façon de produire le son qui compte.","enonce":"Au concert de fin d’année, Hugo voit sur scène : une **clarinette**, un **saxophone** en métal doré, une **trompette**, une **harpe**, un **xylophone**, un **triangle**, un **piano** et une **flûte traversière** en métal.\n\n1. Classe chaque instrument dans sa famille (et sa sous-famille).\n2. Hugo pense que le saxophone et la flûte sont des cuivres « parce qu’ils sont en métal ». Explique-lui son erreur.\n3. Quelle différence y a-t-il entre le **xylophone** et le **triangle** ?\n4. À la fin, un chœur chante **sans aucun instrument**. Comment dit-on cela ?","bareme":[{"critere":"Classement correct des huit instruments","points":8},{"critere":"Erreur sur le métal expliquée par le mode de production du son","points":5},{"critere":"Percussions à hauteur déterminée et indéterminée distinguées","points":4},{"critere":"Terme a cappella employé","points":3}],"dureeMin":10,"corrige":"1. **Vents – bois** : clarinette, saxophone, flûte traversière. **Vents – cuivres** : trompette. **Cordes pincées** : harpe. **Cordes frappées** : piano. **Percussions à hauteur déterminée** : xylophone. **Percussions à hauteur indéterminée** : triangle.\n2. Ce n’est **pas la matière** qui classe un instrument mais **la façon dont le son est produit**. Le saxophone a une **anche** et la flûte fonctionne par un **souffle sur un biseau** : ce sont des **bois**. Les cuivres, eux, font vibrer les **lèvres** du musicien.\n3. Le **xylophone** produit des notes de **hauteur précise** (on peut jouer une mélodie) ; le **triangle** n’a **pas de hauteur définie**.\n4. Le chœur chante ***a cappella***.\n\nÉléments valorisés : précision des sous-familles ; accepter « piano = percussion » seulement si l’élève précise « cordes frappées »."}$exo$::jsonb),
  ('2a938ef3-f5f8-50d7-b584-05109a97b260'::uuid, 3, 'redaction', $exo${"titre":"Organiser un orchestre pour un conte","consigne":"Choisis des instruments et des voix pour les personnages d’un conte et justifie chaque choix avec plusieurs notions du cours.","enonce":"Tu dois mettre en musique un conte avec quatre personnages :\n- un **géant** lent et lourd ;\n- une **fée** légère et rapide ;\n- un **roi** majestueux qui entre en scène ;\n- un **chœur de villageois** qui chante sans accompagnement.\n\n1. Pour le **géant**, la **fée** et le **roi**, choisis un instrument et donne sa **famille**, sa **façon de produire le son** et la raison de ton choix (aigu ou grave, caractère du timbre).\n2. Parmi les cordes frottées, lesquelles choisirais-tu pour accompagner le géant ? Et la fée ? Justifie avec l’ordre des cordes.\n3. Pour le **chœur de villageois**, quelles voix prévois-tu si le chœur est mixte ? Comment appelle-t-on un chant sans accompagnement ?\n4. Tu veux ajouter le bruit des **pas du géant** et une **petite mélodie magique** pour la fée avec des percussions. Quel type de percussion pour chacun ? Justifie.","bareme":[{"critere":"Trois instruments choisis avec famille et production du son","points":6},{"critere":"Cordes graves et aiguës choisies selon leur ordre","points":4},{"critere":"Voix du chœur mixte et terme a cappella","points":4},{"critere":"Percussions déterminées et indéterminées bien réparties","points":3},{"critere":"Justifications cohérentes avec le caractère des personnages","points":3}],"dureeMin":18,"corrige":"Réponses libres si elles sont exactes et justifiées. Exemple :\n1. **Géant** : le **tuba** (cuivre, vibration des lèvres), très **grave**, timbre lourd ; ou le **basson** (bois à anche), grave. **Fée** : la **flûte traversière** (bois, souffle sur un biseau), **aiguë**, timbre léger ; ou la **harpe** (corde pincée). **Roi** : la **trompette** (cuivre, vibration des lèvres), timbre éclatant, idéale pour une entrée solennelle.\n2. Géant : **contrebasse** ou **violoncelle**, les cordes frottées **les plus graves**. Fée : **violon**, le **plus aigu** (ordre : violon → alto → violoncelle → contrebasse).\n3. Chœur mixte : **soprano, mezzo-soprano, alto** pour les femmes ; **ténor, baryton, basse** pour les hommes (un chœur simple peut se limiter à soprano, alto, ténor, basse). Sans accompagnement : ***a cappella***.\n4. Pas du géant : une percussion à **hauteur indéterminée** (grosse caisse, caisse claire) car on veut un bruit, pas une note. Mélodie de la fée : une percussion à **hauteur déterminée** (**xylophone**, ou glockenspiel) car une mélodie demande des notes précises.\n\nÉléments valorisés : lien clair entre caractère du personnage, hauteur et timbre ; classement exact (ex. le saxophone est un bois)."}$exo$::jsonb),
  ('e7680197-e832-59d3-bf44-d92057c28d8d'::uuid, 1, 'redaction', $exo${"titre":"Pulsation, tempo, rythme et mesure","consigne":"Réponds à chaque question par une ou deux phrases complètes.","enonce":"1. Définis la **pulsation**, le **tempo** et le **rythme**.\n2. En quelle unité mesure-t-on le tempo ?\n3. Range ces indications de la **plus lente à la plus rapide** : *allegro*, *largo*, *presto*, *andante*, *adagio*.\n4. Combien de temps compte une mesure de **valse** ? Comment s’appelle le premier temps d’une mesure ?","bareme":[{"critere":"Pulsation, tempo et rythme définis sans confusion","points":9},{"critere":"Unité du tempo et indications italiennes rangées","points":7},{"critere":"Valse à trois temps et temps fort","points":4}],"dureeMin":7,"corrige":"1. **Pulsation** : le **battement régulier** sous la musique, celui qu’on tape du pied. **Tempo** : la **vitesse** de cette pulsation. **Rythme** : l’organisation des **durées** (notes longues et courtes) posées **par-dessus** la pulsation.\n2. En **battements par minute** (**bpm**).\n3. ***Largo*** (très lent) → ***adagio*** (lent) → ***andante*** (allant) → ***allegro*** (vif) → ***presto*** (très rapide).\n4. La valse est à **3 temps**. Le premier temps est le **temps fort**.\n\nÉléments valorisés : exemples personnels (taper du pied sur une chanson)."}$exo$::jsonb),
  ('e7680197-e832-59d3-bf44-d92057c28d8d'::uuid, 2, 'redaction', $exo${"titre":"Deux chansons au même tempo","consigne":"Lis la situation d’écoute décrite et réponds en distinguant bien les notions du cours.","enonce":"Sarah écoute deux morceaux avec un métronome réglé sur **120 bpm**. Les deux morceaux suivent exactement ce battement.\n\n- **Morceau A** : une **marche** militaire, avec des notes toutes de même durée, régulières comme des pas.\n- **Morceau B** : une chanson pop à **4 temps**, avec des notes très courtes et très longues qui s’enchaînent de façon surprenante.\n\n1. Les deux morceaux ont-ils le même **tempo** ? Justifie.\n2. Ont-ils le même **rythme** ? Justifie.\n3. Combien de temps compte probablement la mesure du morceau A ? Et celle du morceau B ?\n4. Combien de pulsations Sarah entend-elle en **30 secondes** ? Explique ton calcul.\n5. Quelle indication italienne irait le mieux avec ce tempo : *largo* ou *allegro* ? Pourquoi ?","bareme":[{"critere":"Même tempo reconnu et justifié par les bpm","points":4},{"critere":"Rythmes différents expliqués par l’organisation des durées","points":5},{"critere":"Mesures à 2 et 4 temps identifiées","points":4},{"critere":"Calcul des pulsations en 30 secondes juste et expliqué","points":4},{"critere":"Indication italienne choisie et justifiée","points":3}],"dureeMin":12,"corrige":"1. **Oui** : les deux suivent **120 bpm**, donc la pulsation a **la même vitesse** : même tempo.\n2. **Non** : le morceau A a des durées **toutes égales**, le morceau B mélange des notes **très courtes et très longues**. Le rythme est l’organisation des durées **par-dessus** la pulsation : deux morceaux au même tempo peuvent avoir des rythmes très différents.\n3. Morceau A : une marche, donc **2 temps**. Morceau B : **4 temps** (indiqué, la mesure la plus courante).\n4. 120 battements par minute, 30 secondes = une demi-minute : 120 ÷ 2 = **60 pulsations**.\n5. ***Allegro*** (vif) : 120 bpm est un tempo **rapide**, alors que *largo* signifie **très lent**.\n\nÉléments valorisés : la phrase-clé « même tempo, rythmes différents » ; calcul rédigé."}$exo$::jsonb),
  ('e7680197-e832-59d3-bf44-d92057c28d8d'::uuid, 3, 'redaction', $exo${"titre":"Choisir le mouvement musical d’une scène de film","consigne":"Analyse les deux scènes décrites et propose pour chacune une musique. Justifie chaque choix en combinant pulsation, tempo, rythme et mesure.","enonce":"Un réalisateur te demande de décrire la musique de deux scènes de son film.\n\n- **Scène 1** : un bal dans un château. Les couples tournent en rond, élégamment.\n- **Scène 2** : une course-poursuite sur les toits, de plus en plus haletante.\n\n1. Pour chaque scène, propose un **type de mesure** (nombre de temps) et justifie.\n2. Pour chaque scène, propose une **indication de tempo italienne** et un ordre de grandeur en **bpm**. Justifie.\n3. Décris le **rythme** que tu imagines pour chaque scène (notes longues ou courtes, régulières ou irrégulières).\n4. Dans la scène 1, où les danseurs doivent-ils marquer leur premier pas ? Pourquoi ?\n5. Le réalisateur propose de garder **le même tempo** pour les deux scènes. Explique comment tu pourrais quand même les rendre très différentes.","bareme":[{"critere":"Mesures choisies et justifiées (valse à 3 temps)","points":4},{"critere":"Tempos italiens et bpm cohérents avec les scènes","points":4},{"critere":"Rythmes décrits de façon adaptée","points":4},{"critere":"Temps fort identifié comme repère du premier pas","points":3},{"critere":"Distinction tempo et rythme argumentée","points":5}],"dureeMin":20,"corrige":"Réponses libres si elles sont cohérentes. Exemple :\n1. Scène 1 : une mesure à **3 temps**, car c’est la mesure de la **valse**, danse où les couples tournent. Scène 2 : une mesure à **2 temps** (énergie de la course, comme une marche rapide) ou à **4 temps** (la plus courante) ; les deux sont acceptées si elles sont justifiées.\n2. Scène 1 : ***andante*** ou ***allegro*** modéré, par exemple autour de **90 à 130 bpm** (on accepte une fourchette raisonnable) : élégant, sans précipitation. Scène 2 : ***presto*** (**très rapide**), par exemple **170 bpm ou plus**, pour traduire la poursuite haletante.\n3. Scène 1 : un rythme **régulier**, une note plus longue sur le premier temps puis des notes plus légères. Scène 2 : des notes **courtes et rapides** (croches), avec des **irrégularités** qui créent de la tension.\n4. Sur le **premier temps**, le **temps fort** : c’est le repère de la mesure, celui qu’on cherche pour « retrouver la mesure ».\n5. Le **tempo** (vitesse de la pulsation) peut rester identique, mais on change le **rythme** (durées posées sur la pulsation) et la **mesure** : notes longues et régulières en 3 temps pour le bal ; notes courtes et hachées en 2 ou 4 temps pour la course. **Deux morceaux au même tempo peuvent avoir des rythmes très différents.**\n\nÉléments valorisés : enchaînement logique pulsation → tempo → rythme → mesure ; vocabulaire italien juste."}$exo$::jsonb),
  ('6798a012-7a4d-5227-a2c4-1e0a89ad556b'::uuid, 1, 'application', $exo${"titre":"Sexuée ou asexuée ? Trier des façons de se reproduire","consigne":"Lis la liste d’observations, puis réponds aux questions en faisant des phrases complètes.","enonce":"Pendant une sortie au jardin du collège, ta classe relève plusieurs façons dont les êtres vivants donnent des descendants.\n\n| N° | Observation |\n|---|---|\n| A | Un fraisier produit de longues tiges rampantes (stolons) ; au bout de chacune pousse un nouveau fraisier. |\n| B | Une chatte met au monde 4 chatons après s’être accouplée avec un mâle. |\n| C | Le jardinier coupe un morceau de tige de géranium et le plante : il donne un nouveau géranium (bouturage). |\n| D | Au microscope, une bactérie se divise en deux bactéries. |\n| E | Dans la mare, une grenouille femelle pond des œufs que le mâle recouvre de spermatozoïdes. |\n\n1. Donne la différence entre la reproduction sexuée et la reproduction asexuée : combien d’individus ou de cellules reproductrices faut-il dans chaque cas ?\n2. Classe les observations A à E dans un tableau à deux colonnes : « reproduction sexuée » et « reproduction asexuée ».\n3. Les nouveaux géraniums de l’observation C sont-ils identiques ou différents du géranium de départ ? Et les chatons de l’observation B, entre eux ? Justifie.\n4. Complète la phrase : spermatozoïde + … → … → cellule-œuf → nouvel être vivant.","bareme":[{"critere":"Définir correctement les deux formes de reproduction","points":6},{"critere":"Classer sans erreur les cinq observations","points":8},{"critere":"Justifier l’identité ou la diversité des descendants et compléter la chaîne de la fécondation","points":6}],"dureeMin":6,"corrige":"1. La **reproduction sexuée** demande **deux** cellules reproductrices : un **spermatozoïde** (venant d’un mâle) et un **ovule** (venant d’une femelle). La **reproduction asexuée** se fait à partir d’**un seul** individu, sans cellules reproductrices.\n\n2.\n| Reproduction sexuée | Reproduction asexuée |\n|---|---|\n| B (chatte), E (grenouille) | A (stolons du fraisier), C (bouturage), D (division de la bactérie) |\n\n3. Les nouveaux géraniums sont **identiques** au géranium de départ : ils viennent d’un seul individu, ce sont des copies (reproduction asexuée). Les chatons sont **tous différents** entre eux : ils sont issus de la rencontre d’un spermatozoïde et d’un ovule (reproduction sexuée), qui fabrique de la diversité.\n\n4. Spermatozoïde + **ovule** → **fécondation** → cellule-œuf → nouvel être vivant."}$exo$::jsonb),
  ('6798a012-7a4d-5227-a2c4-1e0a89ad556b'::uuid, 2, 'application', $exo${"titre":"Du cerisier en fleurs aux jeunes cerisiers","consigne":"Lis le document sur le cerisier du verger, puis réponds aux questions en rédigeant ta démarche.","enonce":"Monsieur Martin possède un cerisier dans son verger. Il note ce qu’il observe au fil de l’année.\n\n| Période | Observation |\n|---|---|\n| Début avril | L’arbre est couvert de fleurs blanches. De nombreuses abeilles passent de fleur en fleur ; leurs pattes sont couvertes de poudre jaune (du pollen). |\n| Fin avril | Les pétales tombent. Au centre de chaque fleur, la base du pistil (l’ovaire) commence à grossir. |\n| Juin | Les cerises sont mûres. Chaque cerise contient un noyau dur, à l’intérieur duquel se trouve une graine. |\n| Juillet | Des merles mangent les cerises et rejettent les noyaux plus loin, parfois à plusieurs centaines de mètres. |\n| Printemps suivant | De jeunes cerisiers poussent au bord du champ voisin, loin de l’arbre. |\n\n1. Comment s’appelle le transport du pollen jusqu’au pistil ? Qui l’assure ici ? Cite un autre moyen possible.\n2. Explique ce qui se passe entre début avril et juin : que devient l’ovaire de la fleur ? Que devient l’ovule ? Quelle étape doit avoir eu lieu avant ?\n3. Quel rôle jouent les merles en juillet ? Explique pourquoi c’est utile pour la plante.\n4. Une année, un gel tardif détruit toutes les fleurs du cerisier juste après leur ouverture. Monsieur Martin aura-t-il des cerises cette année-là ? Justifie à l’aide de tes réponses précédentes.","bareme":[{"critere":"Nommer la pollinisation et ses agents (insectes, vent)","points":5},{"critere":"Expliquer la fécondation puis la transformation ovaire → fruit et ovule → graine","points":7},{"critere":"Expliquer la dispersion des graines par les animaux et son intérêt","points":4},{"critere":"Raisonner sur le cas du gel à partir des étapes","points":4}],"dureeMin":10,"corrige":"1. C’est la **pollinisation**. Ici, elle est assurée par des **insectes pollinisateurs** (les abeilles), qui transportent le pollen d’une fleur à l’autre. Elle peut aussi être assurée par le **vent**.\n\n2. Après la pollinisation, a lieu la **fécondation** dans la fleur. Ensuite, l’**ovaire** de la fleur grossit et devient un **fruit** (la cerise), et l’**ovule** devient une **graine** (la graine contenue dans le noyau).\n\n3. Les merles assurent la **dispersion des graines** : ils mangent les cerises et rejettent les noyaux (qui contiennent les graines) loin de l’arbre. C’est utile car les jeunes plantes poussent **loin de la plante mère** ; elles colonisent de nouveaux endroits (ici le champ voisin).\n\n4. Non. Si les fleurs sont détruites, il n’y a ni pollinisation ni fécondation. Or c’est l’ovaire de la fleur fécondée qui devient le fruit : **sans fleur, pas de cerise** (et donc pas de graines) cette année-là."}$exo$::jsonb),
  ('6798a012-7a4d-5227-a2c4-1e0a89ad556b'::uuid, 3, 'application', $exo${"titre":"Beaucoup d’œufs ou peu de petits : comparer des stratégies de reproduction","consigne":"Exploite le tableau de données, puis rédige des réponses justifiées en t’appuyant sur les chiffres.","enonce":"Un élève a rassemblé des informations sur la reproduction de cinq animaux (valeurs moyennes, arrondies).\n\n| Animal | Lieu de la fécondation | Nombre d’œufs ou de petits par ponte ou par portée | Jeune à la naissance ou à l’éclosion |\n|---|---|---|---|\n| Morue (poisson) | Dans l’eau | 4 000 000 œufs | Larve, très différente de l’adulte |\n| Grenouille rousse | Dans l’eau | 2 000 œufs | Têtard |\n| Lézard des murailles | Dans le corps de la femelle | 6 œufs | Petit lézard |\n| Mésange charbonnière | Dans le corps de la femelle | 9 œufs | Oisillon |\n| Chat | Dans le corps de la femelle | 4 chatons | Chaton |\n\n1. Pour chaque animal, indique si la fécondation est externe ou interne.\n2. Compare le nombre d’œufs des animaux à fécondation externe et de ceux à fécondation interne. Propose une explication à cette différence.\n3. Classe ces animaux selon leur type de développement (direct ou indirect). Pour le développement indirect, nomme l’étape qui transforme le jeune en adulte.\n4. Un élève affirme : « La morue pond 4 millions d’œufs, donc dans quelques années la mer sera remplie de morues. » Explique pourquoi il se trompe.\n5. En hiver, on ne voit presque plus de grenouilles ni de lézards près de la mare, puis ils réapparaissent et se reproduisent au printemps. Cite deux formes de résistance à la mauvaise saison vues en cours et explique comment le milieu se repeuple au printemps.","bareme":[{"critere":"Identifier le type de fécondation de chaque animal","points":3},{"critere":"Comparer les nombres et relier nombre de descendants et protection","points":5},{"critere":"Classer les développements et nommer la métamorphose","points":4},{"critere":"Réfuter l’affirmation sur la morue","points":4},{"critere":"Expliquer le repeuplement du milieu au printemps","points":4}],"dureeMin":16,"corrige":"1. **Externe** (dans l’eau) : morue, grenouille rousse. **Interne** (dans le corps de la femelle) : lézard des murailles, mésange charbonnière, chat.\n\n2. Les animaux à fécondation externe produisent **beaucoup** plus d’œufs (2 000 à 4 000 000) que ceux à fécondation interne (4 à 9). Explication : quand les cellules reproductrices et les œufs sont libérés dans l’eau, ils ne sont pas protégés ; **peu survivent**, il en faut donc beaucoup. Avec la fécondation interne, il y a **moins de descendants, mais mieux protégés**, donc davantage survivent.\n\n3. **Développement indirect** : morue (larve) et grenouille rousse (têtard) ; le jeune est une **larve** qui devient adulte par une **métamorphose** (têtard → grenouille). **Développement direct** : lézard, mésange, chat ; le jeune ressemble à l’adulte en plus petit.\n\n4. Il se trompe : la fécondation est externe, les œufs et les larves ne sont pas protégés et **la très grande majorité meurt** (mangés, courants, froid…). Seuls quelques individus deviennent adultes : le grand nombre d’œufs compense ces pertes, il ne fait pas exploser la population.\n\n5. Formes de résistance possibles : les **œufs**, l’**hibernation** (grenouilles et lézards passent l’hiver cachés, au ralenti), la **migration** ; chez les plantes, les **graines** et les **bulbes**. Au printemps, les animaux qui ont hiberné ou migré redeviennent actifs ou reviennent, les œufs éclosent, les graines germent : ils se reproduisent et le milieu se **repeuple**."}$exo$::jsonb),
  ('c5ff4f24-ac14-508b-badc-19eb829c9e6f'::uuid, 1, 'application', $exo${"titre":"Les transformations de la puberté","consigne":"Lis la situation et la liste de transformations, puis réponds aux questions avec des phrases complètes.","enonce":"Au cours de sciences, le professeur écrit au tableau une liste de transformations du corps :\n\n| N° | Transformation |\n|---|---|\n| 1 | Mue de la voix |\n| 2 | Développement des seins |\n| 3 | Croissance rapide (on grandit vite) |\n| 4 | Apparition de poils (pilosité) plus importante sur le visage |\n| 5 | Élargissement du bassin |\n| 6 | Les testicules commencent à produire des spermatozoïdes |\n| 7 | Premières règles |\n\n1. Définis la puberté et indique à quel âge elle commence en général.\n2. Range les transformations 1 à 7 dans trois groupes : « chez le garçon », « chez la fille », « chez les deux ».\n3. Parmi ces transformations, lesquelles montrent que les organes reproducteurs entrent en fonction ?\n4. Dans la cour, des élèves se moquent de Nathan parce que sa voix n’a pas encore mué, alors que celle de ses camarades a changé. Explique-leur, avec les connaissances du cours, pourquoi cette moquerie n’a pas lieu d’être.","bareme":[{"critere":"Définir la puberté et donner la fourchette d’âge","points":5},{"critere":"Classer les transformations et repérer celles des organes reproducteurs","points":10},{"critere":"Expliquer que les écarts d’âge sont normaux et rappeler le respect","points":5}],"dureeMin":7,"corrige":"1. La **puberté** est le **passage de l’enfance à l’âge adulte**. Elle commence en général **entre 10 et 15 ans**.\n\n2. **Chez le garçon** : 1 (mue de la voix), 4 (pilosité du visage), 6 (production de spermatozoïdes). **Chez la fille** : 2 (seins), 5 (élargissement du bassin), 7 (premières règles). **Chez les deux** : 3 (croissance rapide).\n(On accepte aussi de noter que la pilosité augmente chez les deux, mais celle du visage concerne surtout le garçon.)\n\n3. La **production de spermatozoïdes par les testicules** (6) et les **premières règles** (7) montrent que les organes reproducteurs entrent en fonction.\n\n4. L’âge de la puberté **varie beaucoup d’une personne à l’autre** : il n’y a pas d’âge « normal », mais une **fourchette** (10 à 15 ans). Être en avance ou en retard sur ses camarades est **normal** et ne veut rien dire. De plus, aucune moquerie sur le corps des autres n’est acceptable : le corps de chacun lui appartient et doit être respecté."}$exo$::jsonb),
  ('c5ff4f24-ac14-508b-badc-19eb829c9e6f'::uuid, 2, 'application', $exo${"titre":"Le cycle, les règles et le dépliant de l’infirmerie","consigne":"Lis les documents, puis réponds aux questions en rédigeant des explications précises.","enonce":"**Document 1 — Le carnet de Jade.** Jade, 13 ans, note dans un carnet le premier jour de ses règles.\n\n| Mois | Premier jour des règles | Durée des règles |\n|---|---|---|\n| Janvier | 4 janvier | 5 jours |\n| Février | 2 février | 4 jours |\n| Mars | 3 mars | 5 jours |\n\n**Document 2 — Extrait d’un dépliant de l’infirmerie.** « La pilule empêche une grossesse. Le préservatif empêche une grossesse. »\n\n1. À l’aide du document 1, indique environ tous les combien de temps reviennent les règles de Jade, et combien de temps elles durent. Compare avec ce que dit le cours.\n2. Explique, dans l’ordre, les étapes qui conduisent aux règles (tu dois utiliser les mots : ovaire, ovule, ovulation, fécondation, utérus).\n3. Le dépliant (document 2) est incomplet. Quelle information importante manque-t-il à propos du préservatif ? Réécris la phrase correctement.\n4. Un élève dit : « La pilule et le préservatif, c’est pareil, ils servent à la même chose. » Est-ce exact ? Justifie.","bareme":[{"critere":"Exploiter le carnet : fréquence et durée des règles","points":5},{"critere":"Décrire les étapes qui mènent aux règles avec le vocabulaire demandé","points":6},{"critere":"Compléter le dépliant sur la protection contre les IST","points":5},{"critere":"Distinguer les fonctions de la pilule et du préservatif","points":4}],"dureeMin":10,"corrige":"1. Du 4 janvier au 2 février, puis du 2 février au 3 mars : les règles reviennent environ **tous les 29 à 30 jours**, soit **environ une fois par mois**. Elles durent **4 à 5 jours**, c’est-à-dire **quelques jours**. C’est conforme au cours.\n\n2. Un **ovaire** libère un **ovule** : c’est l’**ovulation**. S’il n’y a **pas de fécondation** (l’ovule ne rencontre pas de spermatozoïde), la paroi de l’**utérus** est évacuée : ce sont les **règles**.\n\n3. Il manque le fait que le préservatif protège **aussi des infections sexuellement transmissibles (IST)**. Phrase correcte : « Le préservatif empêche une grossesse **et** protège des infections sexuellement transmissibles. »\n\n4. Non. La pilule (et les autres contraceptifs) évite **seulement une grossesse**. Le préservatif évite une grossesse **et** les IST : c’est **le seul moyen** qui remplit les deux fonctions."}$exo$::jsonb),
  ('c5ff4f24-ac14-508b-badc-19eb829c9e6f'::uuid, 3, 'application', $exo${"titre":"Neuf mois pour devenir un bébé : exploiter des mesures","consigne":"Exploite le texte et le tableau de mesures, puis rédige des réponses justifiées.","enonce":"**Document 1.** Après un rapport sexuel, un spermatozoïde rencontre un ovule. La cellule-œuf obtenue se divise pendant qu’elle descend vers l’utérus, puis s’implante dans sa paroi. Le futur bébé est d’abord appelé embryon, puis fœtus. Il est relié par le cordon ombilical au placenta.\n\n**Document 2. Taille et masse moyennes du futur bébé (valeurs arrondies)**\n\n| Âge de la grossesse | Taille | Masse |\n|---|---|---|\n| 3 mois | 10 cm | 45 g |\n| 5 mois | 25 cm | 500 g |\n| 7 mois | 40 cm | 1 200 g |\n| 9 mois (naissance) | 50 cm | 3 300 g |\n\n1. Où a lieu la fécondation ? Comment appelle-t-on l’implantation de la cellule-œuf dans l’utérus ?\n2. Remets dans l’ordre : fœtus – accouchement – fécondation – embryon – nidation – division de la cellule-œuf. Indique vers quand l’embryon devient un fœtus.\n3. Calcule la prise de masse entre 3 et 7 mois, puis entre 7 et 9 mois. Pendant quelle période le fœtus prend-il le plus de masse chaque mois ? Montre ton calcul.\n4. Le fœtus ne mange pas et ne respire pas d’air. Explique comment il reçoit ce dont il a besoin pour grandir et comment ses déchets sont évacués.\n5. Un bébé né à 7 mois a besoin de soins particuliers. À l’aide du tableau, propose une raison.","bareme":[{"critere":"Situer la fécondation et nommer la nidation","points":3},{"critere":"Ordonner les étapes et situer le passage au fœtus","points":4},{"critere":"Calculer les prises de masse et conclure","points":5},{"critere":"Expliquer le rôle du placenta et du cordon ombilical","points":5},{"critere":"Proposer une explication cohérente pour la naissance à 7 mois","points":3}],"dureeMin":15,"corrige":"1. La fécondation a lieu dans une **trompe**. L’implantation dans la paroi de l’utérus s’appelle la **nidation**.\n\n2. Fécondation → division de la cellule-œuf → nidation → embryon → fœtus → accouchement. L’embryon devient un fœtus **vers la fin du 2e mois**.\n\n3. Entre 3 et 7 mois : 1 200 − 45 = **1 155 g** en 4 mois, soit environ 290 g par mois.\nEntre 7 et 9 mois : 3 300 − 1 200 = **2 100 g** en 2 mois, soit **1 050 g par mois**.\nC’est donc pendant les **deux derniers mois** que le fœtus prend le plus de masse chaque mois (sa masse fait presque ×3).\n\n4. Le fœtus reçoit tout **par le sang de sa mère**. Le **placenta** assure les **échanges** entre la mère et le fœtus. Le **cordon ombilical**, qui relie le fœtus au placenta, lui **apporte le dioxygène et les nutriments** et **évacue ses déchets** (vers le placenta, puis la mère).\n\n5. À 7 mois, le bébé ne pèse qu’environ 1 200 g, bien moins que les 3 300 g d’un bébé né à 9 mois : il n’a pas terminé sa croissance (la grossesse dure normalement environ **9 mois**). Il est donc plus fragile et a besoin de soins pour continuer à se développer."}$exo$::jsonb),
  ('a96e9734-6df3-535c-aa09-d18ce65f4d9b'::uuid, 1, 'application', $exo${"titre":"À chaque nutriment son rôle","consigne":"Lis la liste d’aliments, puis réponds aux questions en faisant des phrases complètes.","enonce":"Voici le contenu du panier de courses de la famille de Lina : **pâtes, huile d’olive, poisson, riz, beurre, œufs, lentilles, pommes, noix**.\n\n1. Recopie et complète le tableau en plaçant chaque aliment du panier dans la famille de nutriments qu’il apporte surtout.\n\n| Glucides | Lipides | Protides |\n|---|---|---|\n| … | … | … |\n\n2. Donne le rôle principal de chacune de ces trois familles de nutriments.\n3. Le calcium et le fer ne sont nécessaires qu’en très petite quantité. Sont-ils pour autant inutiles ? Justifie.\n4. Quelle part de la masse de notre corps l’eau représente-t-elle ? Quelle est la seule boisson indispensable ?","bareme":[{"critere":"Classer correctement les aliments du panier","points":9},{"critere":"Donner le rôle des glucides, lipides et protides","points":6},{"critere":"Expliquer l’importance des minéraux et de l’eau","points":5}],"dureeMin":7,"corrige":"1.\n| Glucides | Lipides | Protides |\n|---|---|---|\n| pâtes, riz, pommes | huile d’olive, beurre, noix | poisson, œufs, lentilles |\n\n(Les noix sont des fruits secs : riches en lipides. Les lentilles sont des légumineuses : riches en protides.)\n\n2. Les **glucides** (sucres) sont le **carburant principal** du corps. Les **lipides** (graisses) servent de **réserve d’énergie** et de constituants des membranes. Les **protides** (protéines) sont les **matériaux de construction** du corps.\n\n3. Non : les vitamines et les minéraux comme le calcium et le fer sont nécessaires **en très petite quantité, mais ils sont indispensables** au bon fonctionnement de l’organisme.\n\n4. L’eau représente **environ 60 %** de la masse du corps. L’**eau** est la seule boisson indispensable."}$exo$::jsonb),
  ('a96e9734-6df3-535c-aa09-d18ce65f4d9b'::uuid, 2, 'application', $exo${"titre":"La journée alimentaire de Tom","consigne":"Analyse les repas de Tom à l’aide des repères du cours, puis propose des améliorations argumentées.","enonce":"Tom, 12 ans, joue au football trois fois par semaine. Voici ce qu’il a mangé et bu mardi.\n\n| Repas | Ce que Tom a consommé |\n|---|---|\n| Petit déjeuner | Un grand verre de soda, deux pains au chocolat |\n| Déjeuner | Un steak haché, des frites, une crème dessert |\n| Goûter | Un paquet de chips, un soda |\n| Dîner | Des pâtes au fromage, une compote |\n\n**Repères du cours** : fruits et légumes à chaque repas ; féculents à chaque repas ; protéines une à deux fois par jour ; gras, sucré, salé : peu ; l’eau est la seule boisson indispensable.\n\n1. Pour chaque repère, indique s’il est respecté ou non dans la journée de Tom. Donne un exemple tiré du tableau à chaque fois.\n2. Propose deux changements précis pour améliorer la journée de Tom, en expliquant ce que chacun apporte.\n3. La mère de Tom dit : « Tant pis, cette journée est ratée, son alimentation est déséquilibrée. » Nuance cette phrase avec le cours.\n4. Tom mange davantage que sa grand-mère. Explique pourquoi ses besoins sont différents.","bareme":[{"critere":"Confronter la journée aux cinq repères avec des exemples","points":8},{"critere":"Proposer deux améliorations justifiées","points":5},{"critere":"Nuancer avec l’idée d’équilibre sur la semaine","points":3},{"critere":"Expliquer la variation des besoins","points":4}],"dureeMin":11,"corrige":"1.\n- **Fruits et légumes à chaque repas** : non respecté. Seule une compote au dîner ; aucun légume (les frites sont des pommes de terre frites, comptées comme féculent), rien au petit déjeuner ni au déjeuner.\n- **Féculents à chaque repas** : plutôt respecté (pain des viennoiseries, frites, pâtes).\n- **Protéines une à deux fois par jour** : respecté (steak haché à midi, fromage le soir).\n- **Gras, sucré, salé : peu** : non respecté (sodas, pains au chocolat, frites, chips, crème dessert).\n- **Eau, seule boisson indispensable** : non respecté, Tom ne boit que du soda.\n\n2. Exemples attendus (deux suffisent) : remplacer les sodas par de l’**eau** (moins de sucre, l’eau suffit) ; remplacer les frites par des **légumes** ou ajouter une crudité (fibres, vitamines et minéraux) ; remplacer les chips par un **fruit** et du pain ; prendre du pain et un fruit au petit déjeuner plutôt que deux viennoiseries (moins de gras et de sucre).\n\n3. **Équilibré ne veut pas dire parfait à chaque repas, mais varié sur la semaine.** Une journée peu équilibrée n’est pas grave si les autres jours compensent ; il faut regarder l’ensemble de la semaine.\n\n4. Les besoins varient selon l’**âge**, la **taille** et l’**activité physique**. Tom est un adolescent **en croissance** et **sportif** : il a besoin de plus d’énergie et de matériaux de construction qu’une personne âgée."}$exo$::jsonb),
  ('a96e9734-6df3-535c-aa09-d18ce65f4d9b'::uuid, 3, 'application', $exo${"titre":"Lire un tableau de composition des aliments","consigne":"Exploite le tableau de composition, puis rédige des réponses justifiées par les valeurs.","enonce":"Voici la composition de cinq aliments (en grammes pour 100 g d’aliment, valeurs arrondies).\n\n| Aliment | Eau | Glucides | Lipides | Protides | Fibres |\n|---|---|---|---|---|---|\n| Pain | 35 | 52 | 1 | 9 | 3 |\n| Beurre | 16 | 0,6 | 82 | 0,7 | 0 |\n| Blanc de poulet cuit | 66 | 0 | 3 | 30 | 0 |\n| Lentilles cuites | 70 | 13 | 0,5 | 9 | 7 |\n| Pomme | 85 | 12 | 0,3 | 0,3 | 2 |\n\n1. Pour chaque nutriment (glucides, lipides, protides), indique l’aliment qui en contient le plus. Précise à chaque fois le rôle de ce nutriment.\n2. Sarah ne mange pas de viande. Quel aliment du tableau peut lui apporter des matériaux de construction ? Compare sa teneur à celle du poulet.\n3. Quel aliment contient le plus de fibres ? Les fibres nourrissent-elles le corps ? À quoi servent-elles ?\n4. Quel aliment contient le plus d’eau ? Pourquoi l’eau est-elle si importante pour le corps ?\n5. Sarah mange une assiette de lentilles. Explique ce que deviennent les protides des lentilles depuis la bouche jusqu’aux muscles. Utilise les mots : digestion, nutriments, absorption, intestin grêle, sang.","bareme":[{"critere":"Identifier dans le tableau l’aliment le plus riche en chaque nutriment et son rôle","points":6},{"critere":"Proposer les lentilles et comparer les valeurs","points":3},{"critere":"Exploiter les valeurs de fibres et d’eau","points":5},{"critere":"Décrire le trajet des nutriments avec le vocabulaire demandé","points":6}],"dureeMin":16,"corrige":"1.\n- **Glucides** : le **pain** (52 g). Rôle : **carburant principal** du corps.\n- **Lipides** : le **beurre** (82 g). Rôle : **réserve d’énergie**, constituants des membranes.\n- **Protides** : le **blanc de poulet** (30 g). Rôle : **matériaux de construction** du corps.\n\n2. Les **lentilles**, qui sont des légumineuses : 9 g de protides pour 100 g. C’est environ **trois fois moins** que le poulet (30 g) ; Sarah devra en manger davantage ou les associer à d’autres aliments riches en protéines (œufs, fromage, pain…).\n\n3. Les **lentilles** (7 g de fibres). Les fibres **ne nourrissent pas** le corps, mais elles **font fonctionner l’intestin**.\n\n4. La **pomme** (85 g d’eau pour 100 g). L’eau représente **environ 60 % de la masse du corps** ; c’est la seule boisson indispensable.\n\n5. Les lentilles sont **trop grosses** pour passer dans le sang. La **digestion** les réduit en **nutriments** (les protides deviennent de petites molécules). Puis, lors de l’**absorption**, ces nutriments traversent la paroi de l’**intestin grêle** et passent dans le **sang**. Le sang les **distribue à tous les organes**, dont les muscles, qui les utilisent pour se construire et se réparer."}$exo$::jsonb),
  ('3c61fab7-0860-5302-af34-7442657abdab'::uuid, 1, 'application', $exo${"titre":"Ce qu’un organe reçoit et ce qu’il rejette","consigne":"Lis le texte, puis réponds aux questions en faisant des phrases complètes.","enonce":"Le muscle du mollet de Léo travaille quand il marche. Pour fonctionner, ce muscle échange des substances avec le sang qui circule dans ses vaisseaux.\n\nListe de substances : **dioxygène, urée, nutriments, dioxyde de carbone**.\n\n1. Recopie et complète le tableau avec les substances de la liste.\n\n| Le muscle reçoit du sang | Le muscle rejette dans le sang |\n|---|---|\n| … | … |\n\n2. Quel est le rôle du sang ? Quel organe le fait circuler sans arrêt ?\n3. Recopie et complète l’équation de la respiration cellulaire : nutriments + … → énergie + … + eau.\n4. Quel organe évacue l’urée, et sous quelle forme ? Quel organe évacue le dioxyde de carbone ?","bareme":[{"critere":"Compléter le tableau des échanges","points":8},{"critere":"Expliquer le rôle du sang et du cœur et compléter l’équation","points":7},{"critere":"Nommer les organes qui éliminent les déchets","points":5}],"dureeMin":6,"corrige":"1.\n| Le muscle reçoit du sang | Le muscle rejette dans le sang |\n|---|---|\n| du **dioxygène**, des **nutriments** | du **dioxyde de carbone**, de l’**urée** |\n\n2. Le sang est le **livreur** : il **apporte** le dioxygène et les nutriments aux organes et **emporte** leurs déchets. Le **cœur** est la **pompe** qui le fait circuler sans arrêt dans les vaisseaux.\n\n3. Nutriments + **dioxygène** → énergie + **dioxyde de carbone** + eau. C’est la respiration cellulaire, qui a lieu dans chaque organe.\n\n4. Les **reins** filtrent le sang et fabriquent l’**urine**, qui évacue l’urée. Les **poumons** évacuent le **dioxyde de carbone**."}$exo$::jsonb),
  ('3c61fab7-0860-5302-af34-7442657abdab'::uuid, 2, 'application', $exo${"titre":"Le voyage d’une bouffée d’air et d’une bouchée de pain","consigne":"Suis le trajet des substances dans le corps et rédige tes réponses étape par étape.","enonce":"Emma mange une tartine de pain puis part courir. Les muscles de ses jambes vont avoir besoin de dioxygène et de nutriments.\n\n1. Décris, dans l’ordre, le trajet du dioxygène depuis l’air jusqu’au muscle de la jambe. Utilise les mots : poumons, alvéoles pulmonaires, sang, cœur.\n2. Les alvéoles pulmonaires sont très nombreuses et ont une paroi extrêmement fine. Explique pourquoi ces caractéristiques facilitent le passage du dioxygène dans le sang.\n3. Décris, dans l’ordre, le trajet des nutriments du pain jusqu’au muscle de la jambe.\n4. Le muscle produit du dioxyde de carbone. Décris le trajet de ce déchet jusqu’à sa sortie du corps.\n5. Pourquoi dit-on que le sang est « le livreur » du corps ?","bareme":[{"critere":"Décrire le trajet du dioxygène","points":6},{"critere":"Relier la structure des alvéoles au passage du dioxygène","points":3},{"critere":"Décrire le trajet des nutriments","points":5},{"critere":"Décrire l’élimination du dioxyde de carbone et le rôle de livreur du sang","points":6}],"dureeMin":10,"corrige":"1. L’air entre dans les **poumons** et arrive jusqu’aux **alvéoles pulmonaires** ; le dioxygène traverse leur paroi et passe dans le **sang**. Le sang, mis en mouvement par le **cœur**, circule dans les vaisseaux jusqu’au muscle de la jambe, qui prélève le dioxygène.\n\n2. Comme les alvéoles sont **très nombreuses**, la surface d’échange entre l’air et le sang est très grande ; comme leur paroi est **extrêmement fine**, le dioxygène la traverse facilement. Beaucoup de dioxygène peut donc passer dans le sang.\n\n3. Le pain est **digéré** : il est réduit en **nutriments**. Ces nutriments sont **absorbés** : ils traversent la paroi de l’**intestin grêle** et passent dans le **sang**. Le sang, poussé par le cœur, les apporte au muscle.\n\n4. Le dioxyde de carbone passe du muscle dans le **sang**, qui le transporte jusqu’aux **poumons** ; il passe des vaisseaux vers les alvéoles (trajet **inverse** du dioxygène) puis est rejeté dans l’air lors de l’expiration.\n\n5. Parce que le sang **apporte** à chaque organe ce dont il a besoin (dioxygène, nutriments) et **emporte** ses déchets (dioxyde de carbone, urée) vers les organes qui les éliminent (poumons, reins)."}$exo$::jsonb),
  ('3c61fab7-0860-5302-af34-7442657abdab'::uuid, 3, 'application', $exo${"titre":"Au repos et pendant la course : exploiter des mesures","consigne":"Exploite le tableau de mesures, fais les calculs demandés et explique les résultats avec le cours.","enonce":"Lors d’une séance d’EPS, on a mesuré plusieurs valeurs chez Hugo, d’abord assis au repos, puis à la fin d’une course de 10 minutes.\n\n| Mesure | Au repos | Pendant la course |\n|---|---|---|\n| Rythme cardiaque (battements par minute) | 70 | 150 |\n| Rythme respiratoire (mouvements par minute) | 15 | 40 |\n| Volume de sang reçu par les muscles des jambes (litres par minute) | 1 | 12 |\n| Dioxygène consommé par le corps (litres par minute) | 0,3 | 2,4 |\n\n1. Décris l’évolution de chaque mesure entre le repos et la course.\n2. Calcule par combien est multiplié le volume de sang reçu par les muscles, puis la consommation de dioxygène.\n3. Explique pourquoi les muscles consomment beaucoup plus de dioxygène pendant la course. Appuie-toi sur l’équation de la respiration cellulaire.\n4. Explique le lien entre l’augmentation du rythme respiratoire, celle du rythme cardiaque et les besoins des muscles.\n5. Pendant la course, les muscles rejettent aussi davantage de dioxyde de carbone. Comment ce déchet est-il évacué ? Relie ta réponse à l’une des mesures du tableau.\n6. Un camarade s’inquiète : « Le cœur d’Hugo bat à 150, il est en difficulté ! » Réponds-lui.","bareme":[{"critere":"Décrire l’évolution des quatre mesures","points":4},{"critere":"Effectuer les deux calculs de multiplication","points":3},{"critere":"Expliquer la hausse de consommation par la respiration cellulaire","points":4},{"critere":"Relier respiration, rythme cardiaque, redistribution du sang et élimination du CO2","points":6},{"critere":"Rassurer le camarade avec un argument scientifique","points":3}],"dureeMin":18,"corrige":"1. Toutes les mesures **augmentent** pendant la course : le rythme cardiaque passe de 70 à 150 battements/min, le rythme respiratoire de 15 à 40 mouvements/min, le sang reçu par les muscles des jambes de 1 à 12 L/min, et la consommation de dioxygène de 0,3 à 2,4 L/min.\n\n2. Sang reçu par les muscles : 12 ÷ 1 = **12 fois plus**. Dioxygène consommé : 2,4 ÷ 0,3 = **8 fois plus**.\n\n3. Nutriments + dioxygène → **énergie** + dioxyde de carbone + eau. Pendant la course, les muscles travaillent beaucoup et ont besoin de beaucoup plus d’**énergie**. Pour la produire, ils réalisent davantage de respiration cellulaire, donc consomment plus de **dioxygène** (et de nutriments).\n\n4. La **respiration s’accélère** pour faire entrer plus de dioxygène dans le sang au niveau des poumons. Le **rythme cardiaque augmente** pour que le sang circule plus vite et **livre plus vite** ce dioxygène et les nutriments aux muscles. De plus, le sang est **redistribué en priorité vers les muscles** : c’est pourquoi ils reçoivent 12 fois plus de sang.\n\n5. Le dioxyde de carbone passe dans le sang, qui le transporte jusqu’aux **poumons**, qui l’évacuent dans l’air expiré. L’augmentation du **rythme respiratoire** (15 → 40) permet aussi d’évacuer plus vite ce dioxyde de carbone plus abondant.\n\n6. Un cœur qui bat plus vite pendant un effort **n’est pas un cœur en difficulté** : c’est un cœur qui **livre plus vite** le dioxygène et les nutriments dont les muscles ont besoin. C’est une réponse normale à l’effort."}$exo$::jsonb),
  ('70ef7f33-c6e9-505d-aca6-a52213207f2e'::uuid, 1, 'application', $exo${"titre":"Agriculture, élevage et besoins d’une plante","consigne":"Lis la liste, puis réponds aux questions en faisant des phrases complètes.","enonce":"Dans une ferme, on trouve : **un champ de blé, un poulailler, un potager de tomates, un troupeau de vaches laitières, un verger de pommiers, un élevage de moutons**.\n\n1. Classe ces productions dans deux groupes : « agriculture » et « élevage ». Pour chaque groupe, indique ce qu’il produit.\n2. Recopie et complète le tableau des besoins du blé.\n\n| Ce qu’il faut au blé | D’où ça vient |\n|---|---|\n| La lumière | … |\n| L’eau | … |\n| Le dioxyde de carbone | … |\n| Les sels minéraux | … |\n\n3. Comment s’appelle la fabrication de sa propre matière par la plante ? Pourquoi dit-on qu’une plante est « productrice primaire » ?","bareme":[{"critere":"Classer les productions et dire ce que produit chaque voie","points":7},{"critere":"Compléter l’origine des quatre besoins de la plante","points":8},{"critere":"Nommer la photosynthèse et expliquer « productrice primaire »","points":5}],"dureeMin":6,"corrige":"1. **Agriculture** : champ de blé, potager de tomates, verger de pommiers ; elle produit des **végétaux** (céréales, légumes, fruits). **Élevage** : poulailler, vaches laitières, moutons ; il produit des **animaux et leurs produits** (viande, lait, œufs, laine…).\n\n2.\n| Ce qu’il faut au blé | D’où ça vient |\n|---|---|\n| La lumière | Le **Soleil** |\n| L’eau | Le **sol**, par les **racines** |\n| Le dioxyde de carbone | L’**air** |\n| Les sels minéraux | Le **sol**, par les **racines** |\n\n3. C’est la **photosynthèse** : avec l’eau, le dioxyde de carbone, les sels minéraux et la lumière, la plante fabrique sa propre matière. Elle est **productrice primaire** car **elle ne mange pas, elle produit** : c’est le point de départ de toute la chaîne alimentaire."}$exo$::jsonb),
  ('70ef7f33-c6e9-505d-aca6-a52213207f2e'::uuid, 2, 'application', $exo${"titre":"L’expérience des radis : de quoi une plante a-t-elle besoin ?","consigne":"Exploite l’expérience et ses résultats, puis rédige des conclusions justifiées.","enonce":"Une classe sème des radis dans quatre bacs identiques (même nombre de graines, même température). Au bout de 3 semaines, on pèse les plants de chaque bac.\n\n| Bac | Conditions | Masse des plants | Aspect |\n|---|---|---|---|\n| A | Terreau, arrosé, à la lumière | 25 g | Plants verts et vigoureux |\n| B | Terreau, arrosé, à l’obscurité | 3 g | Tiges longues et jaunâtres, puis plants morts |\n| C | Terreau, non arrosé, à la lumière | 2 g | Plants flétris |\n| D | Sable lavé sans sels minéraux, arrosé à l’eau pure, à la lumière | 6 g | Petits plants aux feuilles jaunissantes |\n\n1. Quel bac sert de témoin ? Explique à quoi il sert.\n2. Pour chacun des bacs B, C et D, indique la seule condition qui change par rapport au bac A et conclus sur le besoin de la plante mis en évidence.\n3. Explique pourquoi, sans lumière, la plante ne peut pas fabriquer sa matière.\n4. Un agriculteur cultive des radis au même endroit depuis de nombreuses années sans rien ajouter au sol ; ses récoltes diminuent. Avec l’aide du bac D, explique pourquoi et propose deux solutions.","bareme":[{"critere":"Identifier le témoin et son rôle","points":3},{"critere":"Comparer chaque bac au témoin et conclure sur les besoins","points":8},{"critere":"Relier la lumière à la photosynthèse","points":3},{"critere":"Expliquer l’appauvrissement du sol et proposer engrais et rotation","points":6}],"dureeMin":12,"corrige":"1. Le **bac A** est le témoin : il réunit toutes les conditions (lumière, eau, sels minéraux du terreau, air). Il sert de **référence** pour comparer les autres bacs.\n\n2.\n- **Bac B** : seule la **lumière** manque. Les plants pèsent 3 g contre 25 g et meurent : la plante a **besoin de lumière**.\n- **Bac C** : seule l’**eau** manque. 2 g, plants flétris : la plante a **besoin d’eau**, prélevée dans le sol par les racines.\n- **Bac D** : seuls les **sels minéraux** manquent. 6 g, feuilles jaunissantes : la plante a **besoin de sels minéraux**, prélevés dans le sol par les racines.\n(Le dioxyde de carbone de l’air est présent dans tous les bacs.)\n\n3. La plante fabrique sa matière par **photosynthèse**, à partir de l’eau, du dioxyde de carbone et des sels minéraux, **grâce à la lumière**. Sans lumière, la photosynthèse ne peut pas se faire : la plante ne produit plus de matière et finit par mourir.\n\n4. Les cultures **prélèvent des sels minéraux** dans le sol. Sans apport, le sol **s’appauvrit**, comme le sable du bac D : les plantes poussent moins bien. Solutions : apporter des **engrais** (organiques comme le fumier, ou minéraux) ; pratiquer la **rotation des cultures** (alterner les espèces pour ménager le sol)."}$exo$::jsonb),
  ('70ef7f33-c6e9-505d-aca6-a52213207f2e'::uuid, 3, 'application', $exo${"titre":"Le vrai coût d’un kilo de nourriture","consigne":"Exploite les données, effectue les calculs et construis une argumentation scientifique.","enonce":"**Document 1. Ressources nécessaires pour produire 1 kg d’aliment (ordres de grandeur)**\n\n| Aliment | Végétaux consommés par les animaux | Eau utilisée |\n|---|---|---|\n| Blé | aucun | 1 800 L |\n| Viande de poulet | environ 3 kg | 4 300 L |\n| Viande de bœuf | environ 10 kg | 15 000 L |\n\n**Document 2.** Dans le monde, environ un tiers de la nourriture produite est perdue ou gaspillée.\n\n**Document 3.** Une exploitation en agriculture intensive utilise beaucoup d’engrais et de pesticides ; une exploitation en agriculture biologique s’en passe largement.\n\n1. Calcule combien de fois plus d’eau il faut pour produire 1 kg de bœuf que 1 kg de blé (arrondis à l’unité).\n2. Explique pourquoi produire 1 kg de bœuf demande environ 10 kg de végétaux. Utilise la notion de chaîne alimentaire.\n3. Classe les trois aliments du plus économe au plus coûteux en ressources, et justifie.\n4. Une cantine prépare 300 kg de nourriture par semaine. Selon le document 2, quelle masse risque d’être perdue ? Propose deux gestes pour réduire l’impact de notre alimentation.\n5. Compare les deux modèles agricoles du document 3 : ce que chacun permet et ce qu’il coûte.","bareme":[{"critere":"Calculer le rapport de consommation d’eau","points":3},{"critere":"Expliquer la perte d’énergie à chaque maillon","points":5},{"critere":"Classer les aliments en justifiant par les données","points":3},{"critere":"Calculer le gaspillage et proposer des gestes","points":4},{"critere":"Comparer agriculture intensive et biologique","points":5}],"dureeMin":18,"corrige":"1. 15 000 ÷ 1 800 ≈ 8,3, soit environ **8 fois plus d’eau** pour le bœuf que pour le blé.\n\n2. Le bœuf mange des végétaux (herbe, céréales). À **chaque maillon** de la chaîne alimentaire, une **grande partie de l’énergie est perdue** : l’animal utilise la plus grande partie de ce qu’il mange pour vivre (bouger, se chauffer, respirer…) et seule une petite partie devient de la viande. Il faut donc beaucoup de végétaux (environ 10 kg) pour obtenir 1 kg de viande.\n\n3. **Blé** (aucun végétal intermédiaire, 1 800 L) → **poulet** (3 kg de végétaux, 4 300 L) → **bœuf** (10 kg de végétaux, 15 000 L). Manger directement des végétaux coûte moins de végétaux, d’eau (et de surface) que nourrir un animal pour le manger ensuite.\n\n4. Un tiers de 300 kg : 300 ÷ 3 = **100 kg** risquent d’être perdus. Gestes possibles : **limiter le gaspillage** (se servir selon sa faim, finir son assiette), **manger local** et **de saison**, manger un peu moins de viande.\n\n5. L’**agriculture intensive** donne **beaucoup de production**, mais ses engrais et **pesticides** **polluent l’eau** et **réduisent la biodiversité**. L’**agriculture biologique** se passe largement de ces produits, donc pollue moins, mais ses **rendements sont souvent inférieurs**."}$exo$::jsonb),
  ('97a493ed-ceed-57c3-bdcb-2455e67162c9'::uuid, 1, 'application', $exo${"titre":"Conserver les aliments : à chaque technique son effet","consigne":"Lis les situations, puis réponds aux questions en faisant des phrases complètes.","enonce":"Dans la cuisine de la famille Diallo, on trouve : un yaourt, une baguette, des pommes séchées, un pot de confiture, une boîte de conserve de haricots, une pizza surgelée, un litre de lait pasteurisé.\n\n1. Deux de ces aliments sont fabriqués grâce à des micro-organismes. Lesquels ? Nomme le micro-organisme en jeu dans chaque cas et comment s’appelle cette transformation.\n2. Les micro-organismes qui abîment les aliments ont besoin de trois choses pour se multiplier. Lesquelles ?\n3. Recopie et complète le tableau.\n\n| Aliment | Technique de conservation | Effet sur les micro-organismes |\n|---|---|---|\n| Pommes séchées | … | … |\n| Confiture | … | … |\n| Conserve de haricots | … | … |\n| Pizza surgelée | … | … |","bareme":[{"critere":"Identifier les deux aliments fermentés et leur micro-organisme","points":6},{"critere":"Citer les trois besoins des micro-organismes","points":4},{"critere":"Associer chaque aliment à sa technique et à son effet","points":10}],"dureeMin":7,"corrige":"1. Le **pain** (la baguette) : la **levure** produit du dioxyde de carbone qui fait lever la pâte. Le **yaourt** : des **bactéries** transforment le lait. Cette transformation s’appelle la **fermentation**.\n\n2. De la **chaleur**, de l’**eau** et des **nutriments**. Toute technique de conservation leur retire au moins l’un des trois.\n\n3.\n| Aliment | Technique de conservation | Effet sur les micro-organismes |\n|---|---|---|\n| Pommes séchées | **Séchage** | Retire l’**eau** dont ils ont besoin |\n| Confiture | **Sucre** | Rend l’eau **indisponible** |\n| Conserve de haricots | **Stérilisation** (plus de 100 °C) | Les **élimine** |\n| Pizza surgelée | **Congélation** (−18 °C) | Arrête **presque** leur multiplication (sans les tuer) |"}$exo$::jsonb),
  ('97a493ed-ceed-57c3-bdcb-2455e67162c9'::uuid, 2, 'application', $exo${"titre":"Retour de courses : étiquettes et chaîne du froid","consigne":"Aide Karim à ranger ses courses en justifiant chacune de tes réponses avec le cours.","enonce":"Le 17 septembre, Karim rentre des courses. Il lit les étiquettes :\n\n| Produit | Mention sur l’emballage |\n|---|---|\n| Steak haché frais | À consommer jusqu’au 16/09 |\n| Paquet de pâtes | À consommer de préférence avant le 10/09 |\n| Yaourts nature | À consommer jusqu’au 25/09 |\n| Biscuits | À consommer de préférence avant le 30/11 |\n\n1. Quelle est la signification des mentions DLC et DDM ? Associe chaque produit à la bonne mention.\n2. Pour chaque produit, indique si Karim peut le consommer et justifie.\n3. Karim a laissé ses courses deux heures dans la voiture au soleil avant de ranger les yaourts. Quel geste d’hygiène n’a-t-il pas respecté ? Explique le risque.\n4. La veille, Karim a sorti un poisson du congélateur pour le décongeler, mais il ne l’a pas cuisiné. Il veut le remettre au congélateur. Que lui conseilles-tu ? Justifie.\n5. Cite deux autres gestes simples qui évitent la plupart des intoxications alimentaires.","bareme":[{"critere":"Définir DLC et DDM et les associer aux produits","points":5},{"critere":"Décider pour chaque produit avec une justification","points":5},{"critere":"Expliquer la chaîne du froid et l’interdiction de recongeler","points":7},{"critere":"Citer deux autres gestes d’hygiène","points":3}],"dureeMin":11,"corrige":"1. La **DLC** (« à consommer jusqu’au ») concerne les **produits frais** : elle **ne se dépasse pas**. La **DDM** (« à consommer de préférence avant ») indique seulement une **baisse de qualité**, pas un danger. DLC : steak haché, yaourts. DDM : pâtes, biscuits.\n\n2.\n- **Steak haché** : **non**, la DLC (16/09) est dépassée ; il faut le jeter.\n- **Pâtes** : **oui**, la DDM est dépassée mais ce n’est pas un danger (qualité un peu moindre ; les pâtes sont séchées).\n- **Yaourts** : **oui**, la DLC (25/09) n’est pas atteinte, à condition de les garder au froid.\n- **Biscuits** : **oui**, la DDM n’est pas atteinte.\n\n3. Il n’a pas respecté la **chaîne du froid**. Au chaud, les micro-organismes trouvent la **chaleur** dont ils ont besoin et se **multiplient** : le produit peut devenir dangereux.\n\n4. Il ne faut **jamais recongeler** un produit décongelé. **Le froid ne tue pas les micro-organismes, il les met en pause** : pendant la décongélation, ils ont **repris leur multiplication**. Karim doit cuisiner et manger le poisson rapidement, en le gardant au réfrigérateur, ou le jeter.\n\n5. **Se laver les mains** ; **séparer le cru et le cuit**."}$exo$::jsonb),
  ('97a493ed-ceed-57c3-bdcb-2455e67162c9'::uuid, 3, 'application', $exo${"titre":"L’expérience des tubes de lait : tuer ou mettre en pause ?","consigne":"Exploite le tableau de résultats de l’expérience, puis rédige des conclusions justifiées.","enonce":"Un laboratoire partage un même lait cru en cinq tubes fermés. Au départ, chaque tube contient **1 000 bactéries par millilitre**. On compte les bactéries après 3 jours.\n\n| Tube | Traitement puis conservation pendant 3 jours | Bactéries par mL après 3 jours |\n|---|---|---|\n| A | Aucun traitement, à 30 °C | 10 000 000 |\n| B | Aucun traitement, au réfrigérateur (4 °C) | 5 000 |\n| C | Aucun traitement, au congélateur (−18 °C) | 1 000 |\n| D | Chauffé à 70 °C (pasteurisation), puis au réfrigérateur | 20 |\n| E | Chauffé à plus de 100 °C (stérilisation), tube fermé, à 30 °C | 0 |\n\n1. À quoi sert le tube A ? Quel besoin des bactéries lui fournit-on en abondance ?\n2. Compare les tubes B et C au tube A. Que fait le froid aux bactéries ? Dis précisément la différence entre réfrigérateur et congélateur.\n3. Le tube C contient toujours 1 000 bactéries par mL. Qu’en déduis-tu ? Que se passerait-il si on le laissait ensuite 3 jours à 30 °C ?\n4. Compare D et E. Explique la différence entre pasteurisation et stérilisation.\n5. Le tube E est resté 3 jours à 30 °C et ne contient aucune bactérie. Pourquoi ce résultat ne contredit-il pas la réponse 1 ?\n6. Utilise ces résultats pour expliquer la règle : « un produit décongelé ne doit jamais être recongelé ».","bareme":[{"critere":"Identifier le tube témoin et le rôle de la chaleur","points":3},{"critere":"Interpréter l’effet du réfrigérateur et du congélateur","points":5},{"critere":"Comparer pasteurisation et stérilisation","points":4},{"critere":"Expliquer le résultat du tube E","points":3},{"critere":"Justifier la règle sur la recongélation","points":5}],"dureeMin":17,"corrige":"1. Le tube A est le **témoin** : sans traitement, il montre ce qui se passe quand les bactéries ont tout ce qu’il faut. À 30 °C, elles ont de la **chaleur** (et l’eau et les nutriments du lait) : elles passent de 1 000 à 10 000 000 par mL, elles se sont beaucoup multipliées.\n\n2. Au **réfrigérateur** (B), les bactéries passent de 1 000 à 5 000 : elles se multiplient encore, mais bien moins que dans A. Le réfrigérateur **ralentit** leur multiplication. Au **congélateur** (C), le nombre reste à 1 000 : le congélateur **arrête presque** leur multiplication.\n\n3. Au congélateur, les bactéries ne se sont pas multipliées, mais **elles n’ont pas été tuées** (il en reste 1 000). **Le froid ne tue pas : il met en pause.** À 30 °C, elles reprendraient leur multiplication et leur nombre augmenterait fortement, comme dans le tube A.\n\n4. Après **pasteurisation** (≈ 70 °C), il reste quelques bactéries (20 par mL) : elle en **détruit une grande partie**, mais pas toutes (c’est pourquoi le lait pasteurisé se garde au froid). La **stérilisation** (plus de 100 °C) les **élimine** toutes : 0 bactérie.\n\n5. Le tube E a été chauffé à plus de 100 °C puis gardé **fermé** : toutes les bactéries ont été éliminées et aucune ne peut entrer. Même avec la chaleur, l’eau et les nutriments, il n’y a plus de bactéries pour se multiplier. C’est le principe de la **conserve**.\n\n6. Le tube C montre que la congélation laisse les bactéries **vivantes**. Pendant la décongélation, elles **reprennent leur multiplication** et sont plus nombreuses. Recongeler ne les tuerait pas : on garderait un produit plus chargé en bactéries, qui se multiplieraient à nouveau à la décongélation suivante. D’où la règle."}$exo$::jsonb),
  ('b71f99c4-65f3-5068-976e-9d874d5122ad'::uuid, 1, 'application', $exo${"titre":"Les éléments de la cellule","consigne":"Lis le texte, puis réponds aux questions en faisant des phrases complètes.","enonce":"Un élève affirme : « Une bactérie, un chêne, une fourmi et moi, on n’a rien en commun. »\n\n1. Qu’ont en commun tous ces êtres vivants ? Définis une cellule.\n2. Pourquoi faut-il un microscope pour observer une cellule ?\n3. Recopie et complète le tableau des éléments présents dans toute cellule.\n\n| Élément | Rôle |\n|---|---|\n| … | Elle délimite la cellule et contrôle les échanges |\n| Le cytoplasme | … |\n| … | Il contient l’information génétique et commande la cellule |\n\n4. Classe les êtres vivants suivants en « unicellulaires » et « pluricellulaires » : bactérie, chêne, paramécie, fourmi, levure, humain.","bareme":[{"critere":"Identifier la cellule comme point commun et la définir","points":6},{"critere":"Compléter le tableau des éléments communs","points":8},{"critere":"Classer unicellulaires et pluricellulaires","points":6}],"dureeMin":6,"corrige":"1. Ils sont **tous faits de cellules**. Une cellule est la **plus petite unité capable de vivre**.\n\n2. Une cellule mesure **quelques centièmes de millimètre** : elle est trop petite pour être vue à l’œil nu.\n\n3.\n| Élément | Rôle |\n|---|---|\n| La **membrane** | Elle délimite la cellule et contrôle les échanges |\n| Le cytoplasme | **Milieu gélatineux où se déroulent les réactions** |\n| Le **noyau** | Il contient l’information génétique et commande la cellule |\n\n4. **Unicellulaires** (une seule cellule) : bactérie, paramécie, levure. **Pluricellulaires** (de très nombreuses cellules) : chêne, fourmi, humain."}$exo$::jsonb),
  ('b71f99c4-65f3-5068-976e-9d874d5122ad'::uuid, 2, 'application', $exo${"titre":"Deux préparations au microscope : animale ou végétale ?","consigne":"Exploite les observations au microscope, puis rédige des réponses justifiées.","enonce":"En classe, on observe deux préparations au microscope, mais leurs étiquettes se sont décollées. L’une vient d’une feuille d’élodée (une plante aquatique), l’autre de cellules de l’intérieur de la joue d’un élève.\n\n| | Préparation 1 | Préparation 2 |\n|---|---|---|\n| Forme des cellules | Arrondies, contours souples | Rectangulaires, à angles droits, bien alignées |\n| Contour | Une fine limite | Un contour épais et rigide autour de la fine limite |\n| Contenu | Un noyau bien visible, pas de grains colorés | De nombreux petits grains verts ; au centre, un grand espace rempli de liquide |\n| Taille moyenne | 0,05 mm | 0,1 mm de long |\n\n1. Quelle préparation correspond à la feuille d’élodée ? Donne au moins deux arguments tirés du tableau.\n2. Nomme les éléments de la préparation 2 : le contour épais et rigide, les petits grains verts, le grand espace rempli de liquide. Donne le rôle de chacun.\n3. Quels éléments les deux types de cellules ont-ils en commun ?\n4. Un élève dit : « Les cellules sont si petites qu’on pourrait en aligner des centaines sur 1 cm. » Vérifie en calculant combien de cellules de la préparation 1 on peut aligner sur 1 mm, puis sur 1 cm.","bareme":[{"critere":"Identifier la cellule végétale avec deux arguments","points":5},{"critere":"Nommer paroi, chloroplastes et vacuole avec leur rôle","points":6},{"critere":"Citer les éléments communs","points":4},{"critere":"Calculer le nombre de cellules alignées et conclure","points":5}],"dureeMin":11,"corrige":"1. La **préparation 2** vient de la feuille d’élodée : ses cellules ont des **angles droits** et un **contour épais et rigide** (la paroi), et elles contiennent des **grains verts** (chloroplastes), qu’on ne trouve que chez les végétaux. La préparation 1 (cellules arrondies, sans grains verts) correspond aux cellules de la joue.\n\n2.\n- Le contour épais et rigide : la **paroi**, qui **donne la forme** à la cellule et **soutient la plante** (d’où les angles droits).\n- Les grains verts : les **chloroplastes**, qui contiennent la **chlorophylle** ; c’est là que se fait la **photosynthèse**.\n- Le grand espace : la **vacuole**, remplie de liquide.\n\n3. Les deux ont une **membrane**, un **cytoplasme** et un **noyau** (dans la préparation 2, le noyau peut être caché par les chloroplastes).\n\n4. 1 mm ÷ 0,05 mm = **20 cellules** sur 1 mm. 1 cm = 10 mm, donc 20 × 10 = **200 cellules** sur 1 cm. L’élève a raison : on peut en aligner des centaines (200) sur 1 cm."}$exo$::jsonb),
  ('b71f99c4-65f3-5068-976e-9d874d5122ad'::uuid, 3, 'application', $exo${"titre":"D’une bactérie à une colonie : la division cellulaire","consigne":"Exploite le document et le tableau, effectue les calculs puis rédige des explications justifiées.","enonce":"**Document 1.** On place **une seule** bactérie dans un milieu nutritif, à 37 °C. On compte les bactéries toutes les 20 minutes.\n\n| Temps (minutes) | 0 | 20 | 40 | 60 | 80 | 100 | 120 |\n|---|---|---|---|---|---|---|---|\n| Nombre de bactéries | 1 | 2 | 4 | 8 | … | … | … |\n\n**Document 2.** Le corps humain compte environ 30 000 milliards de cellules. Il s’est formé à partir d’une seule cellule, la cellule-œuf.\n\n**Document 3.** Quand on se coupe le doigt, la plaie se referme en quelques jours : de nouvelles cellules de peau apparaissent.\n\n1. La bactérie est-elle un être unicellulaire ou pluricellulaire ? Justifie.\n2. Décris ce qui se passe toutes les 20 minutes, puis complète le tableau jusqu’à 120 minutes.\n3. Un élève pense que les nouvelles bactéries apparaissent « toutes seules » dans le milieu nutritif. Explique pourquoi il se trompe.\n4. À l’aide des documents 2 et 3, explique comment on grandit et comment une blessure cicatrise.\n5. Compare l’organisation d’une bactérie et celle d’un humain : nombre de cellules et organisation.","bareme":[{"critere":"Justifier le caractère unicellulaire de la bactérie","points":3},{"critere":"Décrire la division et compléter le tableau","points":5},{"critere":"Réfuter l’apparition spontanée des cellules","points":4},{"critere":"Expliquer croissance et cicatrisation par la division","points":5},{"critere":"Comparer unicellulaire et pluricellulaire","points":3}],"dureeMin":15,"corrige":"1. La bactérie est **unicellulaire** : elle est formée d’**une seule cellule**, qui assure à elle seule toute la vie de l’organisme.\n\n2. Toutes les 20 minutes, **chaque bactérie se divise en deux** : le nombre de bactéries **double**.\n| Temps (minutes) | 0 | 20 | 40 | 60 | 80 | 100 | 120 |\n|---|---|---|---|---|---|---|---|\n| Nombre de bactéries | 1 | 2 | 4 | 8 | **16** | **32** | **64** |\n\n3. Au départ, il n’y avait qu’**une** bactérie, et toutes les autres sont apparues par **divisions successives** de cette bactérie puis de ses descendantes. **Une cellule ne naît jamais de rien : toute cellule vient d’une cellule.**\n\n4. La cellule-œuf **se divise** en deux cellules, qui se divisent à leur tour, et ainsi de suite : c’est ainsi qu’on passe d’une cellule à environ 30 000 milliards, et qu’on **grandit**. Lors d’une blessure, les cellules de la peau autour de la plaie **se divisent** et produisent de nouvelles cellules qui referment la plaie : c’est la **cicatrisation**.\n\n5. La bactérie est faite d’**une seule cellule**. L’humain est **pluricellulaire** : il compte environ **30 000 milliards** de cellules, **organisées en tissus et en organes**."}$exo$::jsonb),
  ('ac14a405-8cc2-51a0-8e0b-6823bfa23e5b'::uuid, 1, 'application', $exo${"titre":"Classer selon ce qu’on possède","consigne":"Lis les informations, puis réponds aux questions en justifiant avec les attributs.","enonce":"Un élève propose de classer ensemble **la chauve-souris, le pigeon et le papillon**, « parce qu’ils volent tous ».\n\nInformations : la chauve-souris a des poils et des mamelles ; le pigeon a des plumes et un squelette interne avec des vertèbres ; le papillon a un squelette externe et 6 pattes articulées.\n\n1. Qu’est-ce qu’un attribut ? « Voler » est-il un attribut ? Justifie.\n2. Dans quel groupe faut-il ranger la chauve-souris ? Justifie à l’aide de ses attributs.\n3. Recopie et complète le tableau.\n\n| Groupe | Attribut | Exemple |\n|---|---|---|\n| Vertébrés | … | … |\n| Arthropodes | … | … |\n| Mollusques | … | … |\n\n4. Une araignée a 8 pattes articulées. Est-ce un insecte ? Justifie.","bareme":[{"critere":"Définir un attribut et écarter « voler »","points":6},{"critere":"Classer la chauve-souris parmi les mammifères avec justification","points":4},{"critere":"Compléter le tableau des grands groupes et classer l’araignée","points":10}],"dureeMin":8,"corrige":"1. Un **attribut** est un caractère que l’on **possède** (squelette interne, vertèbres, poils, plumes, quatre membres, mamelles…). « Voler » **n’est pas un attribut** : c’est ce qu’un animal **fait**. On ne classe pas par ce qu’on fait ni par l’endroit où l’on vit, mais par ce qu’on possède.\n\n2. La chauve-souris est un **mammifère** : elle possède des **poils** et des **mamelles**, comme le chat ou l’humain. Elle vole comme l’oiseau, mais cela ne compte pas pour la classer.\n\n3.\n| Groupe | Attribut | Exemple |\n|---|---|---|\n| Vertébrés | Squelette **interne** et **vertèbres** | pigeon, chauve-souris (ou poisson, grenouille…) |\n| Arthropodes | Squelette **externe** et **pattes articulées** | papillon (ou fourmi, crabe…) |\n| Mollusques | **Corps mou**, souvent une coquille | escargot, moule, poulpe |\n\n4. Non. Les **insectes** ont **6 pattes**. Avec **8 pattes**, l’araignée est un **arachnide**. Les deux sont des arthropodes."}$exo$::jsonb),
  ('ac14a405-8cc2-51a0-8e0b-6823bfa23e5b'::uuid, 2, 'application', $exo${"titre":"Construire des groupes emboîtés à partir d’un tableau d’attributs","consigne":"Exploite le tableau d’attributs, puis décris par écrit les groupes emboîtés que tu construis.","enonce":"Voici des attributs observés chez sept animaux (+ : présent ; − : absent).\n\n| Animal | Squelette interne et vertèbres | Poils et mamelles | Plumes | Squelette externe et pattes articulées | Nombre de pattes | Corps mou et coquille |\n|---|---|---|---|---|---|---|\n| Chat | + | + | − | − | 4 | − |\n| Chauve-souris | + | + | − | − | 4 membres (2 transformés en ailes) | − |\n| Pigeon | + | − | + | − | 4 membres (2 transformés en ailes) | − |\n| Truite | + | − | − | − | 0 | − |\n| Fourmi | − | − | − | + | 6 | − |\n| Araignée | − | − | − | + | 8 | − |\n| Escargot | − | − | − | − | 0 | + |\n\n1. Quels animaux appartiennent au groupe des vertébrés ? Quel attribut partagent-ils ?\n2. À l’intérieur des vertébrés, quels animaux forment le groupe des mammifères ? Justifie.\n3. Décris par écrit les groupes emboîtés « vertébrés » et « mammifères » : quel groupe est inclus dans l’autre ? Quels attributs possède un mammifère ?\n4. Classe la fourmi, l’araignée et l’escargot dans leur grand groupe, puis distingue la fourmi de l’araignée.\n5. Le chat partage-t-il plus d’attributs avec la chauve-souris ou avec le pigeon ? Qu’est-ce que cela indique sur leur parenté ?","bareme":[{"critere":"Identifier les vertébrés et les mammifères avec leurs attributs","points":6},{"critere":"Décrire correctement l’emboîtement des groupes","points":4},{"critere":"Classer les invertébrés et distinguer insecte et arachnide","points":5},{"critere":"Comparer les attributs et conclure sur la parenté","points":5}],"dureeMin":12,"corrige":"1. **Chat, chauve-souris, pigeon, truite** : ils ont un **squelette interne et des vertèbres**.\n\n2. **Chat et chauve-souris** : ce sont les seuls à posséder des **poils et des mamelles**.\n\n3. Le groupe des **mammifères** est **inclus** dans celui des **vertébrés** (une boîte dans une plus grande boîte). Un mammifère possède **tous les attributs de la grande boîte** (squelette interne, vertèbres) **plus** ceux de sa propre boîte (poils, mamelles).\n\n4. Fourmi et araignée : **arthropodes** (squelette externe, pattes articulées). Escargot : **mollusque** (corps mou, coquille). La fourmi a **6 pattes** : c’est un **insecte** ; l’araignée a **8 pattes** : c’est un **arachnide**.\n\n5. Le chat partage plus d’attributs avec la **chauve-souris** (squelette interne, vertèbres, poils, mamelles) qu’avec le pigeon (seulement squelette interne et vertèbres, quatre membres). Partager des attributs, c’est partager un **ancêtre commun** : le chat est donc **plus proche parent** de la chauve-souris que du pigeon."}$exo$::jsonb),
  ('ac14a405-8cc2-51a0-8e0b-6823bfa23e5b'::uuid, 3, 'application', $exo${"titre":"Cheval, âne et mulet : qu’est-ce qu’une espèce ?","consigne":"Exploite les documents, puis construis des réponses argumentées avec les notions du cours.","enonce":"**Document 1.** Un cheval et une ânesse, ou un âne et une jument, peuvent se reproduire. Le petit d’un âne et d’une jument s’appelle un mulet (ou une mule s’il s’agit d’une femelle). Les mulets et les mules sont presque toujours stériles : ils ne peuvent pas avoir de petits.\n\n**Document 2.** Deux chiens de races très différentes, un chihuahua et un berger allemand, peuvent avoir des chiots, qui pourront eux-mêmes avoir des petits.\n\n**Document 3. Noms de quelques animaux**\n\n| Nom en français | Nom en anglais | Nom en espagnol | Nom scientifique |\n|---|---|---|---|\n| Cheval | horse | caballo | *Equus caballus* |\n| Âne | donkey | burro | *Equus asinus* |\n| Loup | wolf | lobo | *Canis lupus* |\n| Humain | human | humano | *Homo sapiens* |\n| Chimpanzé | chimpanzee | chimpancé | *Pan troglodytes* |\n\n1. Donne la définition d’une espèce.\n2. Le cheval et l’âne appartiennent-ils à la même espèce ? Justifie avec le document 1.\n3. Le chihuahua et le berger allemand appartiennent-ils à la même espèce ? Justifie avec le document 2, même s’ils ne se ressemblent pas.\n4. À l’aide du document 3, explique comment est construit un nom scientifique et pourquoi il est utile. Que montre le premier mot commun à *Equus caballus* et *Equus asinus* ?\n5. L’humain et le chimpanzé possèdent tous deux un pouce opposable, des poils et des mamelles. Décris les groupes emboîtés auxquels ils appartiennent ensemble, et explique ce que cela nous apprend sur leur histoire.","bareme":[{"critere":"Donner la définition complète de l’espèce","points":3},{"critere":"Appliquer la définition au cheval, à l’âne et aux chiens","points":6},{"critere":"Expliquer le nom scientifique et la notion de genre","points":5},{"critere":"Situer humain et chimpanzé dans les groupes emboîtés et parler d’ancêtre commun","points":6}],"dureeMin":18,"corrige":"1. Une **espèce** regroupe les individus qui **peuvent se reproduire entre eux ET donner une descendance elle-même féconde**.\n\n2. **Non**. Le cheval et l’âne peuvent se reproduire, mais leurs descendants (mulets, mules) sont presque toujours **stériles** : la descendance n’est pas féconde. Ce sont donc **deux espèces différentes**.\n\n3. **Oui**. Ils peuvent avoir des chiots qui pourront eux-mêmes avoir des petits : la descendance est **féconde**. Ils appartiennent à la même espèce, même s’ils ne se ressemblent pas : l’apparence ne suffit pas à définir une espèce.\n\n4. Le nom scientifique est en **latin** et comporte **deux mots** (ex. *Homo sapiens*). Il est **le même dans tous les pays**, alors que le nom courant change selon la langue (cheval, horse, caballo) : il **évite les confusions entre langues**. Le premier mot, commun à *Equus caballus* et *Equus asinus*, est le **genre** : le cheval et l’âne sont deux espèces différentes d’un **même genre**, *Equus*, ce qui montre qu’ils sont proches.\n\n5. L’humain et le chimpanzé sont des **vertébrés** ; dans cette boîte, ils sont dans celle des **mammifères** (poils, mamelles) ; dans celle-ci, dans celle des **primates** (pouce opposable). Partager tous ces attributs, c’est partager un **ancêtre commun** : ils sont proches parents. La classification raconte une **histoire de famille**."}$exo$::jsonb),
  ('8cd9957e-24d3-5f58-8560-236933326f10'::uuid, 1, 'application', $exo${"titre":"Fossiles, frise du temps et biodiversité","consigne":"Lis les informations, puis réponds aux questions en faisant des phrases complètes.","enonce":"Au musée, Inès lit trois panneaux mélangés :\n\n| Panneau | Texte |\n|---|---|\n| A | Les mammifères se diversifient dans la place libérée. |\n| B | Apparition de la vie sur Terre, il y a 3,8 milliards d’années. |\n| C | Il y a 66 millions d’années, une extinction de masse fait disparaître les dinosaures non-aviens. |\n\n1. Remets les panneaux dans l’ordre chronologique, du plus ancien au plus récent.\n2. Qu’est-ce qu’un fossile ? Donne deux exemples de fossiles.\n3. Que prouvent les fossiles ?\n4. Qu’est-ce que la biodiversité ? Cite trois menaces qui la font diminuer aujourd’hui.","bareme":[{"critere":"Ordonner les panneaux chronologiquement","points":5},{"critere":"Définir un fossile, donner des exemples et ce qu’il prouve","points":9},{"critere":"Définir la biodiversité et citer trois menaces","points":6}],"dureeMin":6,"corrige":"1. **B** (apparition de la vie, 3,8 milliards d’années) → **C** (extinction des dinosaures non-aviens, 66 millions d’années) → **A** (diversification des mammifères, ensuite).\n\n2. Un **fossile** est un **reste ou une trace d’un être vivant du passé, conservé dans la roche**. Exemples : un os, une coquille, une empreinte, un terrier.\n\n3. Les fossiles prouvent que **des espèces différentes des espèces actuelles ont vécu** autrefois, et ils permettent de les **dater**.\n\n4. La **biodiversité** est la **variété du vivant**. Menaces (trois parmi) : la **destruction des milieux**, la **pollution**, la **surexploitation**, le **réchauffement**."}$exo$::jsonb),
  ('8cd9957e-24d3-5f58-8560-236933326f10'::uuid, 2, 'application', $exo${"titre":"Lire les couches d’une falaise","consigne":"Exploite la description de la falaise, puis rédige des réponses justifiées.","enonce":"Des géologues étudient une falaise formée de couches de roches empilées les unes sur les autres (exemple simplifié). Les couches n’ont pas été retournées.\n\n| Couche | Position | Fossiles trouvés |\n|---|---|---|\n| 1 | En haut (surface) | Coquilles de moules et de coques, espèces qui vivent encore aujourd’hui |\n| 2 | Au milieu | Ammonites (animaux marins à coquille enroulée, disparus il y a 66 millions d’années) |\n| 3 | En bas (profond) | Trilobites (arthropodes marins, disparus bien avant les ammonites) |\n\n1. Classe les trois couches de la plus ancienne à la plus récente. Énonce la règle que tu utilises.\n2. Parmi les fossiles trouvés, lesquels appartiennent à des espèces éteintes ? Que prouvent-ils ?\n3. Les ammonites ont disparu il y a 66 millions d’années. Quel autre grand groupe d’animaux a disparu lors du même événement ? Comment appelle-t-on ce type d’événement, et combien en a-t-on connu ?\n4. Un visiteur dit : « Toutes les espèces qui ont existé vivent encore aujourd’hui. » Réponds-lui à l’aide de la falaise et du cours.","bareme":[{"critere":"Ordonner les couches avec la règle de superposition","points":6},{"critere":"Identifier les espèces éteintes et ce qu’elles prouvent","points":5},{"critere":"Relier la disparition des ammonites aux crises biologiques","points":5},{"critere":"Réfuter l’affirmation du visiteur","points":4}],"dureeMin":10,"corrige":"1. De la plus ancienne à la plus récente : **couche 3 → couche 2 → couche 1**. Règle : une **couche profonde est ancienne**, une **couche superficielle est récente** (les couches se déposent les unes sur les autres).\n\n2. Les **ammonites** et les **trilobites** sont des espèces **éteintes**. Ils prouvent que **des espèces différentes des actuelles ont vécu** autrefois ; leur position dans les couches permet de les **dater** les unes par rapport aux autres.\n\n3. Les **dinosaures non-aviens** ont disparu lors de cet événement. C’est une **extinction de masse** (crise biologique). On en a connu **cinq**, qui ont éliminé une grande part du vivant.\n\n4. C’est faux. La falaise montre des espèces (ammonites, trilobites) qui **n’existent plus** aujourd’hui. Les espèces apparaissent, se transforment et disparaissent : **l’immense majorité des espèces qui ont existé sont éteintes**."}$exo$::jsonb),
  ('8cd9957e-24d3-5f58-8560-236933326f10'::uuid, 3, 'application', $exo${"titre":"La phalène du bouleau : une espèce qui change","consigne":"Exploite le document et le tableau, puis construis une explication scientifique rédigée.","enonce":"**Document 1.** La phalène du bouleau est un papillon de nuit qui se repose le jour sur les troncs d’arbres. Dans une même population, certains individus sont **clairs**, d’autres **sombres** ; cette couleur se transmet des parents aux descendants. Les oiseaux mangent surtout les papillons qu’ils repèrent facilement.\n\nAu XIXe siècle, dans la région de Manchester (Angleterre), la fumée des usines a noirci les troncs. Au XXe siècle, des lois ont réduit cette pollution et les troncs sont redevenus clairs.\n\n**Document 2. Part des phalènes sombres dans la région (données simplifiées)**\n\n| Année | 1850 | 1900 | 1960 | 2000 |\n|---|---|---|---|---|\n| Phalènes sombres (%) | 2 % | 95 % | 90 % | 10 % |\n\n1. Décris l’évolution de la part des phalènes sombres entre 1850 et 2000.\n2. Sur un tronc noirci, quels papillons les oiseaux repèrent-ils le plus facilement ? Explique pourquoi les papillons sombres ont alors laissé plus de descendants.\n3. Explique la baisse observée entre 1960 et 2000.\n4. Un élève affirme : « Chaque papillon clair a foncé pendant sa vie pour se cacher sur les troncs noirs. » Explique pourquoi il se trompe.\n5. Rédige en quelques lignes le mécanisme général qui transforme une espèce, en utilisant l’exemple de la phalène : variation des individus, changement du milieu, avantage, descendants, générations.","bareme":[{"critere":"Décrire l’évolution des pourcentages","points":3},{"critere":"Expliquer l’avantage des formes sombres sur troncs noircis","points":5},{"critere":"Expliquer l’inversion après la baisse de la pollution","points":3},{"critere":"Réfuter l’idée d’une adaptation de l’individu","points":4},{"critere":"Rédiger le mécanisme général de transformation de l’espèce","points":5}],"dureeMin":18,"corrige":"1. La part des phalènes sombres **augmente fortement** de 2 % (1850) à 95 % (1900), reste élevée en 1960 (90 %), puis **diminue fortement** jusqu’à 10 % en 2000.\n\n2. Sur un tronc noirci, les oiseaux repèrent surtout les papillons **clairs**. Les papillons **sombres**, moins visibles, sont moins mangés : ils survivent plus souvent, se reproduisent davantage et **laissent plus de descendants**, qui sont sombres eux aussi (la couleur se transmet). Génération après génération, les sombres deviennent majoritaires.\n\n3. Après la baisse de la pollution, les troncs redeviennent clairs : ce sont maintenant les papillons **sombres** qui sont les plus visibles et les plus mangés. Les **clairs** ont l’avantage et laissent plus de descendants : la part des sombres diminue.\n\n4. **Ce n’est pas l’individu qui s’adapte au cours de sa vie.** Un papillon garde la couleur qu’il a reçue de ses parents. Des papillons sombres **existaient déjà** en 1850 (2 %) ; ce qui a changé, c’est la **proportion** de sombres dans la population, parce que ceux-ci ont laissé plus de descendants. C’est l’**espèce** (la population) qui change, comme la girafe n’a pas allongé son cou en tirant dessus.\n\n5. Les individus d’une espèce **varient** (phalènes claires ou sombres). Quand le **milieu change** (troncs noircis), certaines variations donnent un **avantage** (être sombre, moins visible des oiseaux). Les individus qui la possèdent **laissent plus de descendants**, qui héritent de cette variation. **Sur de nombreuses générations**, cette variation devient fréquente et l’espèce se transforme."}$exo$::jsonb),
  ('debe24da-84b1-53a0-9ff0-b267f85cac4e'::uuid, 1, 'redaction', $exo${"titre":"Les trois temps de l’échauffement","consigne":"Lis chaque question et réponds par des phrases complètes, avec les mots du cours.","enonce":"**Question 1.** À quoi sert l’échauffement ? Donne deux raisons.\n\n**Question 2.** L’échauffement se déroule en trois temps. Recopie et complète le tableau.\n\n| Le temps | Sa durée | Un exemple de contenu |\n|---|---|---|\n| Général | … | … |\n| Articulaire | … | … |\n| Spécifique | … | … |\n\n**Question 3.** Pendant l’échauffement, la température des muscles monte. Explique pourquoi c’est utile.\n\n**Question 4.** Faut-il faire de longs étirements immobiles avant l’effort ? Réponds par oui ou non, puis dis à quel moment de la séance ils ont leur place.","bareme":[{"critere":"Rôle de l’échauffement et effet de la température sur le muscle","points":7},{"critere":"Tableau des trois temps correctement complété","points":9},{"critere":"Place des étirements dans la séance","points":4}],"dureeMin":7,"corrige":"**Question 1.** L’échauffement **prépare le corps à l’effort** et **réduit le risque de blessure**. On valorise aussi : le cœur accélère progressivement, les articulations sont lubrifiées, on réagit plus vite.\n\n**Question 2.**\n\n| Le temps | Sa durée | Un exemple de contenu |\n|---|---|---|\n| Général | 5 à 10 minutes | Activité douce et continue : trottiner, sautiller |\n| Articulaire | Quelques minutes | Rotations lentes, de la nuque aux chevilles |\n| Spécifique | Jusqu’à l’effort | Les gestes de l’activité à venir, de plus en plus vite |\n\nToute activité douce et continue est acceptée pour le temps général ; tout geste propre au sport pratiqué pour le temps spécifique.\n\n**Question 3.** La température du muscle monte de 1 à 2 °C : le muscle devient **plus élastique**, donc il risque moins le **claquage**. Un muscle froid se déchire plus facilement, comme un élastique sorti du réfrigérateur.\n\n**Question 4.** **Non.** Les étirements longs et statiques avant l’effort diminuent temporairement la force et n’empêchent pas les blessures. Leur place est au **retour au calme**, en fin de séance."}$exo$::jsonb),
  ('debe24da-84b1-53a0-9ff0-b267f85cac4e'::uuid, 2, 'redaction', $exo${"titre":"L’échauffement de Tom avant le match de handball","consigne":"Lis la description de l’échauffement de Tom, puis réponds aux questions en justifiant avec le cours.","enonce":"Avant un match de handball, Tom s’échauffe ainsi :\n\n1. il commence tout de suite par trois sprints à fond sur la longueur du terrain ;\n2. il fait ensuite des tirs puissants au but ;\n3. il termine par des rotations lentes des chevilles et des épaules ;\n4. juste avant le coup d’envoi, il tient chaque étirement une minute sans bouger.\n\nIl n’a fait aucune activité douce au début.\n\n**Question 1.** Rappelle les trois règles du principe de progressivité (on va « du … vers le … »).\n\n**Question 2.** Relève deux erreurs de Tom qui ne respectent pas ce principe. Explique le risque de chacune.\n\n**Question 3.** Que penses-tu de l’étape 4 ? Justifie.\n\n**Question 4.** Propose à Tom un échauffement corrigé en trois temps, dans le bon ordre, adapté au handball.","bareme":[{"critere":"Les trois règles de la progressivité","points":4},{"critere":"Deux erreurs repérées et risques expliqués","points":6},{"critere":"Jugement argumenté sur les étirements avant le match","points":4},{"critere":"Échauffement corrigé en trois temps adapté au handball","points":6}],"dureeMin":10,"corrige":"**Question 1.** Du **lent** vers le **rapide** ; du **général** vers le **spécifique** ; du **petit** vers le **grand**.\n\n**Question 2.** Erreurs attendues (deux parmi) :\n- **Commencer par des sprints à fond** : il va du rapide vers le lent, avec un muscle encore froid. Risque de **claquage** : un échauffement qui commence par un sprint n’échauffe rien, il blesse.\n- **Tirer fort au but avant d’avoir chauffé les épaules** : le spécifique et le grand arrivent avant le général et le petit ; risque de blessure à l’épaule.\n- **Faire les rotations articulaires à la fin** : elles devaient venir avant les gestes spécifiques, pour lubrifier les articulations.\n- **Aucune activité douce au début** : pas de temps général, le cœur n’a pas accéléré progressivement.\n\n**Question 3.** C’est une erreur : les **étirements longs et statiques** avant l’effort **diminuent temporairement la force** et **n’empêchent pas les blessures**. Ils ont leur place au retour au calme.\n\n**Question 4.** Exemple attendu :\n1. **Temps général** (5 à 10 min) : trottiner autour du terrain, sautiller, pas chassés, de plus en plus vite.\n2. **Temps articulaire** (quelques minutes) : rotations lentes de la nuque, des épaules, des poignets, des hanches, des genoux et des chevilles.\n3. **Temps spécifique** (jusqu’au match) : passes courtes puis longues, dribbles, tirs d’abord doux puis de plus en plus puissants, courses avec changements de direction, un ou deux sprints à la fin.\n\nOn valorise le respect de l’ordre et de la progressivité, et le lien avec les gestes du handball."}$exo$::jsonb),
  ('debe24da-84b1-53a0-9ff0-b267f85cac4e'::uuid, 3, 'redaction', $exo${"titre":"Organiser l’échauffement de la classe par temps froid","consigne":"Tu es chargé d’organiser l’échauffement de ta classe. Réponds à chaque question en justifiant tes choix avec le cours.","enonce":"Un matin de décembre, il fait 4 °C. Ta classe de 6e a EPS dehors pendant une heure, avec au programme une course de vitesse de 50 m. Le professeur te demande de préparer l’échauffement. Il ne reste que **15 minutes** avant les premières courses chronométrées.\n\nUn camarade propose : « On fait trois sprints tout de suite, comme ça on est chauds, et on s’étire bien longtemps juste avant de courir. »\n\n**Question 1.** Explique à ton camarade pourquoi sa proposition est dangereuse et peu efficace. Utilise au moins deux arguments du cours.\n\n**Question 2.** Pourquoi l’échauffement est-il encore plus important un matin froid ? Appuie-toi sur ce que l’échauffement produit dans le corps.\n\n**Question 3.** Construis le programme des 15 minutes : pour chaque temps, donne une durée, des exercices précis et explique comment tu respectes la progressivité.\n\n**Question 4.** La séance est finie. Que proposes-tu pour les 5 dernières minutes, et pourquoi ?","bareme":[{"critere":"Réfutation argumentée de la proposition du camarade","points":5},{"critere":"Lien entre temps froid et effets de l’échauffement","points":4},{"critere":"Programme de 15 minutes cohérent en trois temps","points":6},{"critere":"Progressivité justifiée dans le programme","points":2},{"critere":"Retour au calme proposé et justifié","points":3}],"dureeMin":15,"corrige":"**Question 1.** Arguments attendus (au moins deux) :\n- Commencer par un **sprint** avec un muscle froid, c’est aller du rapide vers le lent : le muscle, peu élastique, risque le **claquage**. Un échauffement qui commence par un sprint n’échauffe rien, il blesse.\n- Il manque le **temps général** et le **temps articulaire**.\n- Les **étirements longs et statiques** juste avant la course **diminuent temporairement la force** (donc la vitesse) et **n’empêchent pas les blessures**.\n\n**Question 2.** Par temps froid, les muscles sont encore plus froids : comme un élastique sorti du réfrigérateur, ils se déchirent plus facilement. L’échauffement fait monter la **température musculaire de 1 à 2 °C**, ce qui rend le muscle **élastique**. Il fait aussi **accélérer le cœur progressivement** (plus de sang aux muscles), **lubrifie les articulations** (liquide synovial) et améliore la **vigilance**, utile pour réagir au départ.\n\n**Question 3.** Exemple de programme valorisé :\n- **Temps général, 7 min** : trottiner lentement, puis un peu plus vite ; sautiller, pas chassés, montées de genoux légères. Garder une tenue chaude au début.\n- **Temps articulaire, 3 min** : rotations lentes de la nuque, des épaules, des hanches, des genoux, des chevilles.\n- **Temps spécifique, 5 min** : gammes (talons-fesses, montées de genoux), puis accélérations progressives sur 20 à 30 m à vitesse moyenne, puis plus vite ; quelques départs.\n\nToute répartition cohérente (général 5 à 10 min, articulaire quelques minutes, spécifique jusqu’à l’effort) est acceptée.\n\n**Progressivité** : du **lent** vers le **rapide** (trottiner puis accélérations), du **général** vers le **spécifique** (course douce puis gestes du sprint), du **petit** vers le **grand** (petites amplitudes puis grandes foulées).\n\n**Question 4.** Un **retour au calme** d’environ **5 minutes** : marche ou trottinement très doux, puis étirements. Il fait **redescendre le rythme cardiaque** et **facilite la récupération** ; c’est le bon moment pour les étirements."}$exo$::jsonb),
  ('f6ca766e-4529-54fd-a322-8fa7fcd5bed4'::uuid, 1, 'redaction', $exo${"titre":"Ce que fait le corps pendant l’effort","consigne":"Réponds à chaque question par des phrases complètes, en utilisant le vocabulaire du cours.","enonce":"**Question 1.** Pendant un effort, qu’est-ce que les muscles réclament en plus grande quantité ?\n\n**Question 2.** Cite quatre changements qui se produisent dans le corps quand on court. Pour la température, explique à quoi sert la transpiration.\n\n**Question 3.** Explique la différence entre l’effort **aérobie** et l’effort **anaérobie** (durée et intensité de l’effort, dioxygène, ce qu’on ressent).\n\n**Question 4.** Quand faut-il boire lors d’une activité sportive ? Pourquoi ne faut-il pas attendre d’avoir soif ?","bareme":[{"critere":"Besoins des muscles et quatre changements du corps","points":8},{"critere":"Distinction aérobie et anaérobie","points":8},{"critere":"Règles d’hydratation","points":4}],"dureeMin":7,"corrige":"**Question 1.** Les muscles réclament plus de **dioxygène** et de **nutriments**.\n\n**Question 2.**\n- Le **rythme cardiaque** augmente (d’environ 70 à 150-190 battements par minute).\n- La **respiration** devient plus rapide et plus ample.\n- La **température** du corps monte ; la **transpiration** permet de **refroidir** le corps.\n- Le **sang** est envoyé en priorité vers les **muscles actifs**.\n\n**Question 3.**\n- **Aérobie** : effort **modéré et long** ; le dioxygène **suffit** ; on peut **parler en courant**. C’est l’endurance.\n- **Anaérobie** : effort **intense et bref** ; le dioxygène **ne suffit plus** ; l’**acide lactique** s’accumule : les jambes brûlent, on s’essouffle vite.\n\n**Question 4.** On boit **avant, pendant et après** l’effort. La **soif** apparaît quand la **déshydratation a déjà commencé** : c’est un signal en retard."}$exo$::jsonb),
  ('f6ca766e-4529-54fd-a322-8fa7fcd5bed4'::uuid, 2, 'redaction', $exo${"titre":"Le cross du collège : lire son cœur et son souffle","consigne":"Lis la situation, puis réponds aux questions en montrant tes calculs et en justifiant avec le cours.","enonce":"Inès a **11 ans**. Elle prépare le cross du collège. Elle mesure son rythme cardiaque à trois moments :\n\n| Moment | Battements par minute | Ce qu’elle ressent |\n|---|---|---|\n| Au repos, assise | 72 | Calme |\n| Pendant 15 minutes de course | 145 | Elle discute avec son amie |\n| Pendant un sprint final de 100 m | 195 | Jambes qui brûlent, ne peut plus parler |\n\n**Question 1.** Calcule la fréquence cardiaque maximale (FCmax) estimée d’Inès. Écris le calcul.\n\n**Question 2.** La zone d’endurance va de 60 à 75 % de la FCmax. Calcule ces deux valeurs pour Inès (arrondis à l’unité). Pendant ses 15 minutes de course, est-elle dans cette zone ?\n\n**Question 3.** Pendant sa course de 15 minutes, Inès discute. Que montre ce test simple ? Dans quel régime d’effort est-elle ?\n\n**Question 4.** Dans quel régime est-elle pendant le sprint final ? Explique pourquoi ses jambes brûlent.","bareme":[{"critere":"Calcul de la FCmax","points":4},{"critere":"Calcul de la zone d’endurance et comparaison","points":6},{"critere":"Test de la conversation et régime aérobie","points":5},{"critere":"Régime anaérobie et acide lactique","points":5}],"dureeMin":10,"corrige":"**Question 1.** FCmax estimée = 220 − âge = 220 − 11 = **209 battements par minute**.\n\n**Question 2.**\n- 60 % de 209 = 0,60 × 209 = 125,4, soit environ **125** battements par minute.\n- 75 % de 209 = 0,75 × 209 = 156,75, soit environ **157** battements par minute.\n\nLa zone d’endurance d’Inès va donc d’environ 125 à 157 battements par minute. À **145**, elle est **dans la zone d’endurance**. (Accepter 156 ou 157 pour la borne haute selon l’arrondi.)\n\n**Question 3.** Si on peut **tenir une conversation en courant**, on est **en endurance** : c’est le test le plus fiable, sans matériel. Inès est en régime **aérobie** : l’effort est modéré et long, le dioxygène suffit.\n\n**Question 4.** Pendant le sprint, elle est en régime **anaérobie** : l’effort est intense et bref, le dioxygène ne suffit plus. L’**acide lactique** s’accumule dans les muscles, d’où la sensation de jambes qui brûlent et l’essoufflement rapide. Elle ne peut plus parler : elle est au-delà de l’endurance. Son cœur à 195 n’est pas en difficulté : il livre plus vite le sang aux muscles."}$exo$::jsonb),
  ('f6ca766e-4529-54fd-a322-8fa7fcd5bed4'::uuid, 3, 'redaction', $exo${"titre":"Conseiller Hugo : signaux d’alerte et progrès en endurance","consigne":"Lis la situation d’Hugo, puis réponds en argumentant avec les connaissances du cours.","enonce":"Hugo, 12 ans, veut progresser en course longue. Voici ce qu’il raconte :\n\n« Mardi, en EPS, j’ai couru sans boire parce que je n’avais pas soif. Au bout de 10 minutes, j’ai eu la tête qui tournait et envie de vomir, mais j’ai continué : un vrai sportif ne s’arrête pas. Mon cœur battait très vite, j’ai eu peur qu’il soit malade. Je veux courir tous les jours pour que mon cœur batte moins vite au repos, mais je ne vois pas à quoi ça sert. »\n\n**Question 1.** Relève les signaux d’alerte dans le récit d’Hugo. Qu’aurait-il dû faire ? Commente sa phrase « un vrai sportif ne s’arrête pas ».\n\n**Question 2.** Explique à Hugo son erreur sur l’hydratation.\n\n**Question 3.** Rassure Hugo sur son cœur qui battait vite pendant l’effort : explique ce qui se passait.\n\n**Question 4.** Explique à Hugo deux effets à long terme d’un entraînement régulier, dont la baisse du rythme cardiaque au repos, et à quoi ils servent.","bareme":[{"critere":"Signaux d’alerte repérés et conduite à tenir","points":6},{"critere":"Erreur d’hydratation expliquée","points":4},{"critere":"Explication de l’accélération du cœur à l’effort","points":4},{"critere":"Deux effets à long terme expliqués","points":6}],"dureeMin":14,"corrige":"**Question 1.** Signaux d’alerte : **vertiges** (la tête qui tourne) et **nausée** (envie de vomir). Hugo aurait dû **s’arrêter** et **prévenir l’enseignant**. Sa phrase est fausse : **la douleur ou le malaise ne sont pas un signe de courage, c’est une information**. Continuer l’expose à un malaise. Les autres signaux à connaître : douleur vive, point de côté persistant, essoufflement anormal.\n\n**Question 2.** Il faut boire **avant, pendant et après** l’effort, sans attendre la soif. La **soif apparaît quand la déshydratation a déjà commencé** : c’est un retardataire, pas un avertisseur. Ses vertiges pouvaient aussi venir du manque d’eau, car il transpirait.\n\n**Question 3.** Pendant l’effort, les muscles réclament plus de **dioxygène** et de **nutriments**. Le cœur accélère (de 70 à 150-190 battements par minute) pour envoyer plus de sang aux **muscles actifs**. Un cœur qui accélère à l’effort n’est pas en difficulté : **c’est un cœur qui livre plus vite**.\n\n**Question 4.** Deux effets parmi :\n- Le **rythme cardiaque au repos baisse** : le cœur travaille **moins** pour le même résultat.\n- Le **volume de sang par battement augmente** : plus d’oxygène livré à chaque battement.\n- **Muscles et os se renforcent** : moins de blessures.\n- **Sommeil et humeur s’améliorent**.\n\nOn valorise un conseil de régularité et d’effort en endurance (pouvoir parler en courant)."}$exo$::jsonb),
  ('59344544-872d-54f6-83a5-d6bc32ec0120'::uuid, 1, 'redaction', $exo${"titre":"Sommeil, alimentation et activité : les repères","consigne":"Réponds à chaque question par des phrases complètes, avec les repères chiffrés du cours.","enonce":"**Question 1.** Combien d’heures de sommeil par nuit faut-il à un adolescent ? Cite deux choses que fait le corps pendant le sommeil.\n\n**Question 2.** Recopie et complète le tableau.\n\n| L’apport | Son rôle | Deux sources |\n|---|---|---|\n| Glucides complexes | … | … |\n| Protéines | … | … |\n| Fruits et légumes | … | … |\n\n**Question 3.** Quelle est la seule boisson indispensable ?\n\n**Question 4.** Selon l’OMS, combien de temps d’activité physique faut-il chaque jour entre 5 et 17 ans ? Donne deux exemples d’activité qui comptent en dehors du sport encadré.","bareme":[{"critere":"Besoin de sommeil et rôles du sommeil","points":6},{"critere":"Tableau de l’alimentation et boisson indispensable","points":9},{"critere":"Recommandation de l’OMS et exemples","points":5}],"dureeMin":7,"corrige":"**Question 1.** Un adolescent a besoin de **8 à 10 heures** de sommeil par nuit. Pendant le sommeil, le corps **répare les muscles**, **sécrète l’hormone de croissance** et **consolide les apprentissages** (deux attendues).\n\n**Question 2.**\n\n| L’apport | Son rôle | Deux sources |\n|---|---|---|\n| Glucides complexes | Le carburant de l’effort | Pâtes, riz, pain, légumes secs |\n| Protéines | Réparer le muscle | Viande, poisson, œufs, légumineuses |\n| Fruits et légumes | Apporter vitamines et minéraux | Frais, cuits ou surgelés (par exemple pomme, carottes) |\n\n**Question 3.** L’**eau**.\n\n**Question 4.** Au moins **60 minutes par jour**. Exemples : **marcher**, **prendre l’escalier**, **faire du vélo** (deux attendus)."}$exo$::jsonb),
  ('59344544-872d-54f6-83a5-d6bc32ec0120'::uuid, 2, 'redaction', $exo${"titre":"La journée de Léa avant son cours d’EPS","consigne":"Lis la journée de Léa, puis réponds aux questions en t’appuyant sur le cours.","enonce":"Léa a 11 ans. Voici sa journée :\n\n- La veille, elle regarde des vidéos sur son téléphone dans son lit jusqu’à 23 h 30. Elle se lève à 6 h 45.\n- Le matin, elle n’a pas faim : elle part sans petit-déjeuner.\n- À 10 h, elle a EPS. Avant le cours, elle boit une canette de boisson énergisante « pour avoir de la force ».\n- Pendant le cours, elle se sent pâle et a des vertiges.\n\n**Question 1.** Calcule combien d’heures Léa a dormi. Est-ce suffisant pour son âge ?\n\n**Question 2.** Explique, étape par étape, comment le téléphone au lit a pu nuire à sa nuit et à sa journée.\n\n**Question 3.** Relève deux autres erreurs de Léa ce matin-là et explique pourquoi ce sont des erreurs.\n\n**Question 4.** Propose-lui un petit-déjeuner adapté et une boisson pour le cours d’EPS.","bareme":[{"critere":"Calcul du temps de sommeil et comparaison au besoin","points":4},{"critere":"Enchaînement écran, mélatonine, sommeil, performance","points":6},{"critere":"Deux autres erreurs repérées et expliquées","points":6},{"critere":"Petit-déjeuner et boisson adaptés","points":4}],"dureeMin":10,"corrige":"**Question 1.** De 23 h 30 à 6 h 45 : **7 h 15 min** de sommeil au maximum (sans compter le temps d’endormissement). C’est **insuffisant** : un adolescent a besoin de **8 à 10 heures**.\n\n**Question 2.**\n1. La **lumière bleue** de l’écran **retarde la sécrétion de mélatonine**.\n2. L’**endormissement est décalé**.\n3. La **nuit est raccourcie**.\n4. Le lendemain, la **concentration** et la **performance baissent**.\n\n**Question 3.**\n- **Venir en EPS à jeun** : sans petit-déjeuner, elle s’expose au **malaise** (pâleur, vertiges). Le petit-déjeuner compte.\n- **La boisson énergisante** : elle est **inutile** et **parfois dangereuse** ; elle ne donne pas de force. Le principal facteur de performance à cet âge, c’est le **sommeil**, pas une boisson.\n\n**Question 4.** Exemple : du **pain** (glucides complexes, le carburant de l’effort), un **œuf** ou un laitage, un **fruit** (vitamines et minéraux). Boisson : de l’**eau**, la seule boisson indispensable, bue avant, pendant et après le cours. Toute proposition variée et cohérente est acceptée."}$exo$::jsonb),
  ('59344544-872d-54f6-83a5-d6bc32ec0120'::uuid, 3, 'redaction', $exo${"titre":"Sportif mais sédentaire ? Analyser la semaine de Karim","consigne":"Analyse la semaine de Karim et justifie chacune de tes réponses avec le cours.","enonce":"Karim a 12 ans. Il fait 2 heures de football le samedi et 2 heures d’EPS dans la semaine. Il dit : « Je fais du sport, donc je suis en forme. »\n\nSa journée type du lundi au vendredi :\n\n| Activité | Durée |\n|---|---|\n| Trajet en voiture jusqu’au collège | 10 min |\n| Assis en classe | 6 h |\n| Assis devant les jeux vidéo | 3 h, jusqu’à 22 h 30 |\n| Marche dans la journée | 10 min |\n\nIl prend aussi des compléments protéinés « pour avoir plus de muscles », et il se couche à 22 h 30 pour se lever à 6 h 30.\n\n**Question 1.** Karim respecte-t-il la recommandation de l’OMS les jours d’école ? Justifie avec un chiffre.\n\n**Question 2.** Karim fait du sport : peut-il quand même être sédentaire ? Explique ce qu’est ce risque et pourquoi il est distinct du manque de sport.\n\n**Question 3.** Que penses-tu des compléments protéinés ? Selon le cours, quel est le principal facteur de performance à son âge, et Karim en profite-t-il assez ?\n\n**Question 4.** Propose-lui trois changements concrets pour sa semaine, chacun justifié.","bareme":[{"critere":"Comparaison avec la recommandation de l’OMS","points":4},{"critere":"Explication de la sédentarité comme risque distinct","points":5},{"critere":"Analyse des compléments et du sommeil","points":5},{"critere":"Trois changements concrets et justifiés","points":6}],"dureeMin":15,"corrige":"**Question 1.** **Non.** L’OMS recommande **au moins 60 minutes d’activité physique par jour** pour les 5-17 ans. Les jours sans EPS, Karim ne bouge qu’environ **10 minutes** (marche), et le trajet se fait en voiture. On accepte une réponse nuancée pour les jours avec EPS.\n\n**Question 2.** **Oui.** Rester assis longtemps est un risque **distinct** du manque de sport : on peut faire de l’EPS ou du football et être **sédentaire** le reste du temps. Karim passe environ **9 heures assis** par jour (classe et jeux vidéo). **Se lever quelques minutes chaque heure** compte réellement.\n\n**Question 3.** Les compléments protéinés sont **inutiles à cet âge** : un adolescent qui **mange varié** n’a besoin d’**aucun complément**. Les protéines de la viande, du poisson, des œufs ou des légumineuses suffisent pour réparer le muscle. Le principal facteur de performance à son âge est le **sommeil**. Karim dort **8 heures**, le bas de la fourchette (8 à 10 heures), et les écrans jusqu’au coucher retardent la mélatonine, donc son endormissement : son sommeil réel est sans doute plus court.\n\n**Question 4.** Trois changements parmi (chacun justifié) :\n- **Aller au collège à pied ou à vélo** : cela compte dans les 60 minutes quotidiennes.\n- **Prendre l’escalier**, marcher davantage.\n- **Se lever quelques minutes chaque heure** pendant les jeux ou les devoirs : lutter contre la sédentarité.\n- **Arrêter les écrans avant le coucher** : éviter la lumière bleue qui retarde la mélatonine, pour dormir plus et mieux.\n- **Se coucher plus tôt** pour approcher 9 à 10 heures.\n- **Arrêter les compléments** et manger varié.\n- Rejoindre l’**association sportive** ou une activité régulière dans la semaine."}$exo$::jsonb),
  ('66d97fde-f6ce-5200-9dd5-c10705d91966'::uuid, 1, 'redaction', $exo${"titre":"Les quatre champs d’apprentissage de l’EPS","consigne":"Réponds aux questions en utilisant les mots exacts du cours.","enonce":"**Question 1.** Le programme d’EPS n’est pas une simple liste de sports. Qu’est-ce qu’il propose à la place ?\n\n**Question 2.** Recopie et complète le tableau.\n\n| Le champ | Le problème posé | Un exemple d’activité |\n|---|---|---|\n| 1. Produire une performance mesurée | … | … |\n| 2. Adapter son déplacement à des environnements variés | … | … |\n| 3. S’exprimer par une prestation artistique | … | … |\n| 4. Conduire un affrontement | … | … |\n\n**Question 3.** Qu’est-ce que l’AS du collège ? À qui est-elle ouverte ?","bareme":[{"critere":"Idée des quatre familles de problèmes","points":3},{"critere":"Tableau des quatre champs complété","points":12},{"critere":"Rôle et ouverture de l’association sportive","points":5}],"dureeMin":7,"corrige":"**Question 1.** Il propose **quatre familles de problèmes à résoudre**, les quatre champs d’apprentissage. Chaque année d’EPS couvre normalement les quatre champs.\n\n**Question 2.**\n\n| Le champ | Le problème posé | Un exemple d’activité |\n|---|---|---|\n| 1 | Se **dépasser** et **mesurer** son progrès | Athlétisme, natation de vitesse, demi-fond |\n| 2 | Gérer sa **sécurité** dans un milieu incertain | Escalade, course d’orientation, sauvetage aquatique, VTT |\n| 3 | **Assumer un regard**, construire une intention | Danse, acrosport, arts du cirque, gymnastique |\n| 4 | **Décider vite** dans un rapport de force | Sports collectifs (hand, basket, foot, volley), raquettes (badminton, tennis de table), combat (judo, lutte) |\n\n**Question 3.** L’**association sportive** du collège **prolonge l’EPS le mercredi**. Elle est **ouverte à tous**, pas seulement aux meilleurs, et permet de **découvrir des activités absentes des cours**."}$exo$::jsonb),
  ('66d97fde-f6ce-5200-9dd5-c10705d91966'::uuid, 2, 'redaction', $exo${"titre":"Classer les activités de l’année dans leur champ","consigne":"Lis le programme de l’année de la classe de 6e B, puis réponds aux questions en justifiant.","enonce":"Voici le programme d’EPS de la 6e B :\n\n| Période | Activité |\n|---|---|\n| Septembre-octobre | Demi-fond |\n| Novembre-décembre | Badminton |\n| Janvier-février | Acrosport |\n| Mars-avril | Course d’orientation |\n| Mai-juin | Handball |\n\n**Question 1.** Pour chaque activité, indique le numéro de son champ d’apprentissage.\n\n**Question 2.** Choisis deux activités de champs différents. Pour chacune, explique quel problème l’élève doit résoudre.\n\n**Question 3.** Le programme de la 6e B couvre-t-il les quatre champs ? Justifie.\n\n**Question 4.** Pendant le cycle de handball, Yanis ne marque aucun but mais arbitre très bien et respecte toujours les autres. Cite deux critères d’évaluation qui peuvent valoriser son travail.","bareme":[{"critere":"Classement des cinq activités","points":5},{"critere":"Problème posé expliqué pour deux activités","points":6},{"critere":"Couverture des quatre champs justifiée","points":4},{"critere":"Critères d’évaluation adaptés à la situation","points":5}],"dureeMin":10,"corrige":"**Question 1.** Demi-fond : **champ 1** ; badminton : **champ 4** ; acrosport : **champ 3** ; course d’orientation : **champ 2** ; handball : **champ 4**.\n\n**Question 2.** Exemples :\n- **Demi-fond (champ 1)** : se **dépasser** et **mesurer** son progrès (un temps, une distance).\n- **Badminton ou handball (champ 4)** : **décider vite** dans un **rapport de force** face à un adversaire.\n- **Acrosport (champ 3)** : **assumer le regard** des autres et construire une **intention** artistique.\n- **Course d’orientation (champ 2)** : gérer sa **sécurité** et son déplacement dans un **milieu incertain**, qui change (la nature).\n\n**Question 3.** **Oui** : le champ 1 (demi-fond), le champ 2 (course d’orientation), le champ 3 (acrosport) et le champ 4 (badminton et handball) sont tous présents. Le champ 4 apparaît deux fois, ce qui n’empêche pas la couverture complète.\n\n**Question 4.** Le **rôle tenu** (arbitre, observateur, coach) et le **respect** (des règles et des autres). On valorise aussi la **progression** (l’écart avec le point de départ) ou la **méthode**, si l’élève les justifie."}$exo$::jsonb),
  ('66d97fde-f6ce-5200-9dd5-c10705d91966'::uuid, 3, 'redaction', $exo${"titre":"Un programme d’EPS « rien que du foot » ? Argumenter","consigne":"Réponds à la proposition de tes camarades en construisant une argumentation appuyée sur le cours.","enonce":"Des élèves de ta classe proposent au professeur : « Cette année, on ne fait que du football, du basket et du tennis de table. Ce sont les sports qu’on préfère, et on sera notés seulement sur les buts marqués et les matchs gagnés. »\n\n**Question 1.** Dans quel champ d’apprentissage se trouvent ces trois activités ? Quel problème posent-elles ?\n\n**Question 2.** Explique pourquoi ce programme ne respecte pas l’idée du programme d’EPS. Cite les champs oubliés et, pour chacun, une activité et le problème qu’elle ferait rencontrer.\n\n**Question 3.** Les élèves veulent être notés seulement sur les buts et les victoires. Montre que l’évaluation en EPS regarde d’autres choses : cite au moins trois autres critères et explique ce que chacun regarde.\n\n**Question 4.** Un élève qui adore le foot mais n’aime pas la danse demande où il pourrait découvrir d’autres activités ou jouer plus. Que lui conseilles-tu ?","bareme":[{"critere":"Champ 4 identifié et problème posé","points":3},{"critere":"Champs oubliés, activités et problèmes associés","points":8},{"critere":"Critères d’évaluation expliqués","points":6},{"critere":"Conseil sur l’association sportive","points":3}],"dureeMin":15,"corrige":"**Question 1.** Football et basket (sports collectifs) et tennis de table (raquettes) appartiennent au **champ 4 : conduire un affrontement**. Le problème : **décider vite dans un rapport de force**.\n\n**Question 2.** Le programme d’EPS n’est **pas une collection de sports** : c’est un parcours pensé pour rencontrer **quatre types de difficultés**, et chaque année couvre normalement **les quatre champs**. Champs oubliés :\n- **Champ 1, produire une performance mesurée** : athlétisme, natation de vitesse, demi-fond ; se **dépasser** et **mesurer** son progrès.\n- **Champ 2, adapter son déplacement à des environnements variés** : escalade, course d’orientation, sauvetage aquatique, VTT ; gérer sa **sécurité** dans un **milieu incertain** (hauteur, eau profonde, nature).\n- **Champ 3, s’exprimer par une prestation artistique** : danse, acrosport, arts du cirque, gymnastique ; **assumer un regard** et construire une **intention**.\n\n**Question 3.** Critères attendus (au moins trois parmi) :\n- La **performance** : le résultat mesuré (les buts et victoires n’en sont qu’une partie).\n- La **progression** : l’écart avec le point de départ.\n- La **méthode** : la façon de s’entraîner et de se corriger.\n- Le **rôle tenu** : arbitre, observateur, coach.\n- Le **respect** : des règles et des autres.\n\nOn valorise l’idée qu’un élève qui ne gagne pas peut réussir en EPS.\n\n**Question 4.** Lui conseiller l’**association sportive (AS)** du collège : elle **prolonge l’EPS le mercredi**, elle est **ouverte à tous**, pas seulement aux meilleurs, et permet de **découvrir des activités absentes des cours**. On rappelle qu’en cours, il rencontrera quand même les quatre champs, y compris le champ 3."}$exo$::jsonb),
  ('7086b6ae-37dd-5c5a-a05b-d7a00f3ed64b'::uuid, 1, 'redaction', $exo${"titre":"Les clés pour progresser en EPS","consigne":"Réponds à chaque question par des phrases complètes, avec les idées du cours.","enonce":"**Question 1.** Selon le cours, progresse-t-on grâce à un don ? Qu’est-ce qui distingue les élèves qui progressent ?\n\n**Question 2.** Un objectif utile a trois qualités. Cite-les et donne un exemple d’objectif utile.\n\n**Question 3.** Qu’est-ce qui marche le mieux : 3 séances de 20 minutes par semaine ou 1 séance de 2 heures ? Comment s’appelle le fait que le corps s’adapte entre les séances ?\n\n**Question 4.** Cite deux choses à noter dans un carnet de suivi.","bareme":[{"critere":"Rôle de la méthode et qualités d’un objectif utile","points":9},{"critere":"Régularité et surcompensation","points":7},{"critere":"Contenu du carnet de suivi","points":4}],"dureeMin":7,"corrige":"**Question 1.** **Non** : on progresse par la **répétition organisée**, pas par des dons. Ce qui distingue les élèves qui progressent, c’est leur **méthode**.\n\n**Question 2.** Un objectif utile est **précis**, **mesurable** et **atteignable**. Exemple : « Courir 8 minutes sans m’arrêter. » Tout exemple précis et vérifiable est accepté (par exemple « réussir 7 passes sur 10 »).\n\n**Question 3.** **3 séances de 20 minutes par semaine** donnent le meilleur progrès ; une séance de 2 heures est beaucoup moins efficace. Le corps s’adapte **entre** les séances, pas pendant : c’est la **surcompensation**.\n\n**Question 4.** Ses **performances**, ses **ressentis** et ses **objectifs** (deux attendus). Le carnet transforme une suite de séances en **progression consciente**."}$exo$::jsonb),
  ('7086b6ae-37dd-5c5a-a05b-d7a00f3ed64b'::uuid, 2, 'redaction', $exo${"titre":"Le carnet de Sarah en course longue","consigne":"Lis le carnet de suivi de Sarah, puis réponds aux questions en justifiant avec le cours.","enonce":"Sarah prépare la course longue. Au début, elle écrit : « Mon objectif : être meilleure en course. » Voici son carnet :\n\n| Séance | Temps couru sans s’arrêter | Ressenti |\n|---|---|---|\n| Semaine 1, lundi | 4 min | Très essoufflée |\n| Semaine 1, mercredi | 5 min | Essoufflée |\n| Semaine 1, vendredi | 5 min | Un peu mieux |\n| Semaine 2, lundi | 6 min | Je peux parler |\n| Semaine 2, vendredi | 7 min | Fière |\n\n**Question 1.** L’objectif de départ de Sarah est-il utile ? Justifie, puis réécris-le pour le rendre utile.\n\n**Question 2.** Pourquoi était-il important de noter le temps de la première séance ?\n\n**Question 3.** Calcule la progression de Sarah entre la première et la dernière séance. Pourquoi son organisation en séances courtes et régulières est-elle efficace ?\n\n**Question 4.** Sarah trouve qu’elle ne sait pas bien poser ses pieds, mais elle ne le sent pas. Propose-lui deux moyens d’observation et dis ce que chacun apporte.","bareme":[{"critere":"Analyse et réécriture de l’objectif","points":5},{"critere":"Rôle de la mesure de départ","points":4},{"critere":"Calcul de la progression et régularité expliquée","points":6},{"critere":"Deux moyens d’observation et leurs apports","points":5}],"dureeMin":10,"corrige":"**Question 1.** **Non** : « être meilleure en course » n’est **pas précis** et **pas mesurable** ; on ne peut rien vérifier. Objectif utile : par exemple « **Courir 8 minutes sans m’arrêter** » : précis, mesurable et atteignable (elle en est à 7 min).\n\n**Question 2.** Il faut **se situer avant de progresser**. Sans **mesure de départ**, **aucun progrès n’est visible**, et un progrès invisible décourage. « Ce qui se mesure se travaille. »\n\n**Question 3.** Progression : 7 − 4 = **3 minutes de plus** en deux semaines. Des séances **courtes et régulières** donnent le meilleur progrès (comme 3 séances de 20 minutes par semaine) : le corps s’adapte **entre** les séances, c’est la **surcompensation**. On valorise aussi la remarque « je peux parler » : elle court en endurance.\n\n**Question 4.** Deux moyens parmi :\n- **Être observée** par un camarade : il lui donne un **retour chiffré**.\n- **Se filmer** : corriger ce que la **sensation seule ne montre pas**.\n- **Regarder un camarade** : voir le geste **de l’extérieur**."}$exo$::jsonb),
  ('7086b6ae-37dd-5c5a-a05b-d7a00f3ed64b'::uuid, 3, 'redaction', $exo${"titre":"Aider Noé, découragé au lancer franc","consigne":"Analyse la situation de Noé et construis un plan de progrès argumenté avec le cours.","enonce":"Noé, 11 ans, veut réussir ses lancers francs au basket. Il dit : « Je rate tout le temps, je ne suis pas doué. De toute façon, les bons joueurs ne ratent jamais. » Il décide de s’entraîner une seule fois, le dimanche, pendant 2 heures, et n’a jamais compté ses réussites.\n\nSon ami a compté ses tirs pendant deux séances :\n\n| Séance | Tirs tentés | Tirs réussis |\n|---|---|---|\n| 1 | 20 | 4 |\n| 2 | 20 | 7 |\n\n**Question 1.** Réponds à Noé sur les phrases « je ne suis pas doué » et « les bons joueurs ne ratent jamais », en utilisant ce que dit le cours sur l’erreur et le don.\n\n**Question 2.** Que montre le tableau de son ami ? Explique pourquoi Noé n’avait pas vu ce progrès.\n\n**Question 3.** Critique son organisation d’entraînement et propose-en une meilleure. Justifie avec la notion de surcompensation.\n\n**Question 4.** Fixe à Noé un objectif utile et vérifie qu’il a les trois qualités attendues.\n\n**Question 5.** Explique comment un carnet de suivi pourrait l’aider, et avec quel principe d’autres matières le cours le compare.","bareme":[{"critere":"Réponse sur le don et le rôle de l’erreur","points":4},{"critere":"Lecture du tableau et rôle de la mesure","points":4},{"critere":"Critique et nouvelle organisation justifiée","points":4},{"critere":"Objectif utile vérifié selon trois qualités","points":4},{"critere":"Intérêt du carnet de suivi","points":4}],"dureeMin":16,"corrige":"**Question 1.** On ne progresse pas grâce à un **don** mais par la **répétition organisée** et la **méthode**. Rater n’est pas échouer : un geste **s’automatise après des centaines de répétitions, dont beaucoup d’échecs**. Les bons joueurs ont beaucoup raté pour apprendre ; **l’élève qui refuse de rater refuse d’apprendre**.\n\n**Question 2.** Noé est passé de **4 réussites sur 20** à **7 réussites sur 20** : il **progresse** (3 réussites de plus). Il ne le voyait pas car il **ne mesurait rien** : sans mesure, aucun progrès n’est visible, et un progrès invisible décourage. Ce qui se mesure se travaille.\n\n**Question 3.** Une seule séance de 2 heures est **beaucoup moins efficace** que des séances courtes et régulières. Meilleure organisation : par exemple **3 séances de 20 minutes par semaine**. Le corps s’adapte **entre** les séances, pas pendant : c’est la **surcompensation**.\n\n**Question 4.** Exemple : « Réussir **10 lancers francs sur 20** d’ici un mois. » Il est **précis** (lancers francs, 10 sur 20), **mesurable** (on compte les réussites), **atteignable** (il en est à 7 sur 20, donc cela motive au lieu de décourager). Tout objectif répondant aux trois qualités est accepté.\n\n**Question 5.** En notant ses **performances** (réussites sur 20), ses **ressentis** et ses **objectifs**, Noé transforme ses séances en **progression consciente** et voit ses progrès. Le cours le compare à la **révision espacée** des autres matières. On valorise aussi l’idée d’être observé ou de se filmer."}$exo$::jsonb),
  ('b8188cf2-b705-5b9a-b850-b8a5ecc1dbe6'::uuid, 1, 'redaction', $exo${"titre":"Arbitre, observateur, coach, organisateur","consigne":"Réponds à chaque question par des phrases complètes, avec les mots du cours.","enonce":"**Question 1.** Recopie et complète le tableau.\n\n| Le rôle | Ce qu’il fait | Ce qu’il demande |\n|---|---|---|\n| L’arbitre | … | … |\n| L’observateur | … | … |\n| Le coach | … | … |\n| L’organisateur | … | … |\n\n**Question 2.** Parmi ces deux relevés d’observateur, lequel est utile ? Pourquoi ?\n- a) « Il a bien joué. »\n- b) « 7 passes sur 10 réussies. »\n\n**Question 3.** Si tu n’es pas d’accord avec une décision de l’arbitre, que peux-tu faire et que ne dois-tu jamais faire ?","bareme":[{"critere":"Tableau des quatre rôles complété","points":12},{"critere":"Choix et justification du relevé utile","points":4},{"critere":"Attitude face à l’arbitre","points":4}],"dureeMin":7,"corrige":"**Question 1.**\n\n| Le rôle | Ce qu’il fait | Ce qu’il demande |\n|---|---|---|\n| L’arbitre | Il fait appliquer la règle | La connaître, décider vite, assumer une décision contestée |\n| L’observateur | Il relève des données précises | Un critère mesurable |\n| Le coach | Il conseille, encourage, propose une stratégie | Des conseils précis et positifs |\n| L’organisateur | Il gère le matériel, le score, le chronomètre, les équipes | Sans lui, la séance n’a pas lieu |\n\n**Question 2.** Le relevé **b** est utile : il est **chiffré** et **précis**, donc il **se travaille**. Le relevé a est **inutilisable** : il ne dit pas quoi corriger. Les relevés servent au camarade à **voir ce qu’il ne sent pas**.\n\n**Question 3.** On peut **demander une explication** calmement ; on **n’insulte pas** et on ne conteste pas systématiquement, car cela rend le rôle d’arbitre intenable, qu’il soit élève ou adulte."}$exo$::jsonb),
  ('b8188cf2-b705-5b9a-b850-b8a5ecc1dbe6'::uuid, 2, 'redaction', $exo${"titre":"Un match de basket vu depuis le banc","consigne":"Lis la situation du match, puis réponds aux questions en t’appuyant sur le cours.","enonce":"Pendant un match de basket en EPS, quatre élèves tiennent un rôle.\n\n- **Chloé**, arbitre, hésite longtemps avant de siffler un marcher ; les joueurs se disputent pendant ce temps.\n- **Adam**, observateur, note sur sa fiche : « L’équipe bleue a pas mal joué. »\n- **Lina**, coach de l’équipe rouge, crie à un joueur : « Tu joues mal ! »\n- **Enzo** a oublié le chronomètre et le tableau des scores.\n\n**Question 1.** Pour chaque élève, explique ce qui ne va pas dans la façon dont il tient son rôle.\n\n**Question 2.** Réécris la fiche d’Adam avec un relevé utile, adapté au basket.\n\n**Question 3.** Réécris le conseil de Lina pour qu’il soit précis et positif.\n\n**Question 4.** Pourquoi une arbitre qui hésite pose-t-elle un problème pour le match ?","bareme":[{"critere":"Erreurs des quatre rôles expliquées","points":8},{"critere":"Relevé d’observation chiffré et adapté","points":4},{"critere":"Conseil de coach précis et positif","points":4},{"critere":"Conséquence de l’hésitation de l’arbitre","points":4}],"dureeMin":10,"corrige":"**Question 1.**\n- **Chloé** : l’arbitre doit **décider vite** et **assumer** sa décision ; elle hésite.\n- **Adam** : son relevé n’est pas **précis** ni **chiffré**, il est **inutilisable** ; il lui manque un **critère mesurable**.\n- **Lina** : son conseil n’est ni **précis** ni **positif** : « Tu joues mal » ne donne **rien à corriger**.\n- **Enzo** : l’organisateur gère matériel, score et chronomètre ; **sans lui, la séance n’a pas lieu** correctement.\n\n**Question 2.** Exemples : « Équipe bleue : **12 passes réussies sur 18** », « **5 tirs réussis sur 14** », « temps de possession », « zones de tir ». Tout relevé chiffré est accepté.\n\n**Question 3.** Exemples : « **Place-toi plus haut** pour recevoir la balle », « Démarque-toi dans un espace libre », « Lève les bras pour demander la balle ». Le conseil doit proposer **une action possible**, sur un ton encourageant.\n\n**Question 4.** **Un arbitre qui hésite perd le match** : le jeu s’arrête, les joueurs contestent et se disputent, la règle n’est plus appliquée. On valorise aussi : en arbitrant, on apprend ce qu’on ressent quand on est contesté."}$exo$::jsonb),
  ('b8188cf2-b705-5b9a-b850-b8a5ecc1dbe6'::uuid, 3, 'redaction', $exo${"titre":"Organiser les rôles d’un tournoi de handball","consigne":"Tu organises les rôles d’un tournoi de classe. Réponds en justifiant chacun de tes choix avec le cours.","enonce":"Ta classe organise un tournoi de handball. Il y a 4 équipes de 5 joueurs ; deux équipes jouent pendant que les deux autres tiennent les rôles. Une élève, Maëlle, refuse d’arbitrer : « Ça ne sert à rien, ce n’est pas du sport, et les autres vont me crier dessus. » Pendant le premier match, un joueur insulte l’arbitre après une décision.\n\n**Question 1.** Pour les 5 élèves d’une équipe qui ne joue pas, propose une répartition des rôles (arbitre, observateurs, coach, organisateur). Pour l’observateur, choisis un critère précis.\n\n**Question 2.** Réponds à Maëlle : explique ce que tenir un rôle apporte, en EPS et hors du gymnase. Cite au moins trois compétences.\n\n**Question 3.** Analyse le comportement du joueur qui insulte l’arbitre. Qu’aurait-il dû faire ?\n\n**Question 4.** Pourquoi le cours dit-il que tenir un rôle fait passer « du statut de participant à celui de responsable » ?","bareme":[{"critere":"Répartition des rôles cohérente avec critère d’observation","points":5},{"critere":"Apports des rôles et compétences transférables","points":6},{"critere":"Analyse du comportement envers l’arbitre","points":5},{"critere":"Explication du passage de participant à responsable","points":4}],"dureeMin":15,"corrige":"**Question 1.** Exemple : **1 arbitre** (il connaît la règle, décide vite, assume) ; **2 observateurs**, un par équipe, avec un critère mesurable (nombre de passes réussies, tirs réussis sur tirs tentés, zones de tir) ; **1 coach** pour une équipe (conseils précis et positifs, stratégie) ; **1 organisateur** (chronomètre, score, matériel, rotation des équipes). Toute répartition cohérente est acceptée si chaque rôle est justifié.\n\n**Question 2.** En EPS, on ne fait pas que pratiquer : on arbitre, on observe, on conseille, on organise, et le **rôle tenu** fait partie de l’évaluation. Compétences qui servent partout : **décider sous pression**, **formuler un retour utile**, **accepter une décision qu’on juge injuste**, **organiser un groupe**. L’EPS est l’un des rares endroits à les faire pratiquer vraiment. Sur la peur d’être contestée : l’arbitre apprend ce qu’on ressent quand on est contesté, ce qui change durablement sa façon de jouer ensuite ; et les joueurs doivent la respecter.\n\n**Question 3.** Insulter l’arbitre est **inacceptable** : contester systématiquement l’arbitre, élève ou adulte, **rend le rôle intenable**. Le joueur aurait dû **demander une explication** calmement. **On n’insulte pas.** On valorise un lien avec le fair-play et le respect de la règle.\n\n**Question 4.** Le participant ne s’occupe que de son jeu. Celui qui tient un rôle devient **responsable** du bon déroulement pour tous : sans arbitre, pas de règle appliquée ; sans organisateur, pas de séance ; sans observateur, pas de retour pour progresser. C’est ce qui distingue **un groupe d’élèves d’une classe qui travaille**."}$exo$::jsonb),
  ('c19d53bc-c34e-5db9-b36c-e206881236f6'::uuid, 1, 'redaction', $exo${"titre":"Les familles de règles et le fair-play","consigne":"Réponds à chaque question par des phrases complètes, avec les mots du cours.","enonce":"**Question 1.** Pourquoi a-t-on besoin de règles pour jouer ?\n\n**Question 2.** Cite les trois familles de règles et dis ce que chacune fixe.\n\n**Question 3.** Donne le geste de fair-play attendu dans chaque situation :\n- a) l’arbitre n’a pas vu ta faute ;\n- b) un joueur est à terre ;\n- c) le match est fini.\n\n**Question 4.** Cite les trois valeurs olympiques.","bareme":[{"critere":"Rôle de la règle et trois familles de règles","points":9},{"critere":"Gestes de fair-play","points":6},{"critere":"Valeurs olympiques","points":5}],"dureeMin":7,"corrige":"**Question 1.** Sans règle commune, il n’y a pas de match : **il y a une bagarre**. **La règle crée le jeu.**\n\n**Question 2.**\n- Les règles de **but** : comment on **marque** et comment on **gagne**.\n- Les règles d’**espace et de temps** : le **terrain**, les **zones**, la **durée**.\n- Les règles de **sécurité** : les **contacts** autorisés ou non, le **matériel obligatoire**.\n\n**Question 3.**\n- a) **Reconnaître** la faute.\n- b) L’**aider** à se relever.\n- c) **Serrer la main** (des adversaires, de l’arbitre).\n\n**Question 4.** L’**excellence** (donner son meilleur), l’**amitié** (le lien avant le résultat), le **respect** (de la règle, de l’adversaire, de soi)."}$exo$::jsonb),
  ('c19d53bc-c34e-5db9-b36c-e206881236f6'::uuid, 2, 'redaction', $exo${"titre":"Classer les règles d’un match de football","consigne":"Lis la situation, puis réponds aux questions en justifiant avec le cours.","enonce":"Voici des règles d’un match de football en EPS :\n\n1. Le match dure deux fois 10 minutes.\n2. Un but est marqué quand le ballon franchit entièrement la ligne entre les poteaux.\n3. Les protège-tibias sont obligatoires.\n4. Le ballon ne doit pas sortir des limites du terrain.\n5. Les tacles par derrière sont interdits.\n6. L’équipe qui a marqué le plus de buts gagne.\n\nPendant le match, l’équipe verte gagne 6 à 0. Ses joueurs se moquent des adversaires et crient « Nuls ! ». Après le match, un joueur de l’équipe perdante dit : « On a perdu à cause de l’arbitre et du terrain. »\n\n**Question 1.** Classe chaque règle dans sa famille (but ; espace et temps ; sécurité).\n\n**Question 2.** Quelle erreur de fair-play commet l’équipe verte ? Que devrait-elle faire ?\n\n**Question 3.** Analyse la phrase du joueur perdant. Que se prive-t-il de faire ?\n\n**Question 4.** Quelle valeur olympique est oubliée par l’équipe verte ? Justifie.","bareme":[{"critere":"Classement des six règles","points":6},{"critere":"Erreur de fair-play des gagnants","points":5},{"critere":"Analyse du comportement du perdant","points":5},{"critere":"Valeur olympique justifiée","points":4}],"dureeMin":10,"corrige":"**Question 1.**\n- **But** : règles 2 et 6.\n- **Espace et temps** : règles 1 et 4.\n- **Sécurité** : règles 3 et 5.\n\n**Question 2.** Elle **humilie un adversaire dominé**. Le fair-play demande de **ne pas humilier** l’adversaire et de **gagner sans mépriser**, ce qui produit le respect de l’adversaire. Elle devrait continuer à jouer sérieusement, sans moquerie, et serrer la main à la fin.\n\n**Question 3.** Il **cherche une excuse** (l’arbitre, le terrain) : c’est un **mauvais perdant**. Il se **prive du principal bénéfice de la défaite** : **identifier ce qu’il y avait à corriger**. Il faudrait **perdre sans accuser**.\n\n**Question 4.** Le **respect** : de la règle, **de l’adversaire** et de soi. Se moquer, c’est manquer de respect à l’adversaire. On accepte aussi l’**amitié** (le lien avant le résultat) si c’est justifié."}$exo$::jsonb),
  ('c19d53bc-c34e-5db9-b36c-e206881236f6'::uuid, 3, 'redaction', $exo${"titre":"Arbitrer un cas de triche et débattre du dopage","consigne":"Analyse chaque situation et donne ton avis argumenté avec les idées du cours.","enonce":"**Situation A.** Lors d’un match de handball en EPS, Mathis marche avec le ballon (plus de trois pas). L’arbitre ne le voit pas, Mathis marque le but de la victoire. Un coéquipier lui dit : « Tant que l’arbitre ne voit rien, ce n’est pas grave. »\n\n**Situation B.** Un grand frère raconte : « Certains coureurs prennent des produits interdits pour aller plus vite. Si ça marche, où est le problème ? »\n\n**Question 1.** Situation A : explique la différence entre l’**obéissance** et le **fair-play**. Qu’aurait dû faire Mathis ?\n\n**Question 2.** Situation A : la victoire de l’équipe de Mathis prouve-t-elle qu’elle est meilleure ? Justifie.\n\n**Question 3.** Situation B : réponds au grand frère avec au moins trois arguments du cours sur le dopage.\n\n**Question 4.** Pourquoi contester la règle en permanence revient-il à « détruire ce à quoi on veut jouer » ? Appuie-toi sur le rôle des règles.","bareme":[{"critere":"Distinction obéissance et fair-play avec conduite attendue","points":6},{"critere":"Analyse de la victoire obtenue en trichant","points":4},{"critere":"Arguments sur le dopage","points":6},{"critere":"Rôle des règles dans l’existence du jeu","points":4}],"dureeMin":15,"corrige":"**Question 1.** Respecter la règle **quand l’arbitre regarde**, c’est de l’**obéissance** ; la respecter **quand il ne regarde pas**, c’est du **fair-play**. Le fair-play commence exactement là où finit la surveillance. Mathis aurait dû **reconnaître sa faute** (le marcher) auprès de l’arbitre. La phrase du coéquipier est donc fausse.\n\n**Question 2.** **Non.** La triche peut faire gagner un match, mais **une victoire obtenue en trichant ne prouve rien, pas même à celui qui triche**. On valorise : l’adversaire n’a pas été battu selon les mêmes règles.\n\n**Question 3.** Arguments attendus (trois parmi) :\n- Le dopage est **interdit**.\n- Il est **dangereux** : effets sur le **cœur**, les **hormones**, le **psychisme**.\n- Des **contrôles** existent **à tous les niveaux**.\n- Les **sanctions** vont **jusqu’à l’exclusion des compétitions**.\n- C’est une forme de triche : la victoire ne prouve rien, et cela trahit le **respect** (valeur olympique) de la règle, de l’adversaire et de soi.\n\n**Question 4.** Les règles **créent le jeu** : les règles de **but** disent comment marquer et gagner, celles d’**espace et de temps** fixent le terrain et la durée, celles de **sécurité** protègent les joueurs. Sans règle commune, il n’y a plus de match, **il y a une bagarre**. Contester sans cesse la règle, c’est donc supprimer le jeu lui-même."}$exo$::jsonb),
  ('54a051e6-36a8-56ba-a832-18fb593022a3'::uuid, 1, 'redaction', $exo${"titre":"Prévenir les accidents et alerter les secours","consigne":"Réponds à chaque question par des phrases complètes, avec les mots du cours.","enonce":"**Question 1.** Cite quatre règles de prévention à respecter avant et pendant un cours d’EPS.\n\n**Question 2.** Associe chaque numéro d’urgence à son service : **15**, **18**, **112**, **114**.\n\n**Question 3.** Quelles sont, dans l’ordre, les trois étapes de l’action face à un accident ?\n\n**Question 4.** Que signifient les quatre lettres du protocole **RICE** ?","bareme":[{"critere":"Quatre règles de prévention","points":4},{"critere":"Numéros d’urgence et étapes de l’action","points":10},{"critere":"Les quatre lettres du protocole RICE","points":6}],"dureeMin":8,"corrige":"**Question 1.** Quatre parmi : une **tenue adaptée** (chaussures de sport lacées) ; **pas de bijoux** ; **cheveux attachés** et lunettes sécurisées ; **échauffement** systématique ; **matériel vérifié** (tapis en place, agrès stables, terrain dégagé) ; **respect des consignes**.\n\n**Question 2.**\n- **15** : le **SAMU**.\n- **18** : les **pompiers**.\n- **112** : le numéro d’urgence **européen**.\n- **114** : le numéro d’urgence **par SMS**.\n\n**Question 3.** 1. **Protéger** (supprimer le danger sans se mettre en danger) ; 2. **Alerter** ; 3. **Secourir** (dans la limite de ce qu’on sait faire).\n\n**Question 4.**\n- **R** : **Repos**, arrêter l’effort.\n- **I** : **Ice**, de la glace 15 à 20 minutes, jamais à même la peau.\n- **C** : **Compression**, un bandage sans couper la circulation.\n- **E** : **Élévation**, surélever le membre.\n\nPuis un avis médical."}$exo$::jsonb),
  ('54a051e6-36a8-56ba-a832-18fb593022a3'::uuid, 2, 'redaction', $exo${"titre":"Une cheville tordue pendant le cours de basket","consigne":"Lis la situation, puis réponds aux questions en t’appuyant sur le cours.","enonce":"Pendant un match de basket, Jade retombe mal après un saut. Elle a mal à la cheville, qui a tourné, et celle-ci commence à gonfler. Elle peut encore bouger un peu le pied, et rien n’est déformé. Avant le cours, Jade portait un bracelet et avait des chaussures mal lacées.\n\n**Question 1.** Quelle blessure Jade a-t-elle probablement ? Justifie avec les signes décrits. Pourquoi n’est-ce probablement pas une fracture ?\n\n**Question 2.** Décris ce qu’il faut faire, lettre par lettre, en appliquant le protocole RICE à la cheville de Jade. Que faut-il faire ensuite ?\n\n**Question 3.** Relève les deux erreurs de prévention de Jade et explique le risque de chacune.\n\n**Question 4.** Un camarade veut poser un glaçon directement sur la peau de Jade. Que lui dis-tu ?","bareme":[{"critere":"Identification de l’entorse et distinction avec la fracture","points":5},{"critere":"Protocole RICE appliqué et avis médical","points":8},{"critere":"Deux erreurs de prévention expliquées","points":4},{"critere":"Utilisation correcte de la glace","points":3}],"dureeMin":10,"corrige":"**Question 1.** Probablement une **entorse** : articulation **tordue**, **douleur**, **gonflement**. Ce n’est probablement pas une **fracture**, qui donnerait une douleur intense, une **déformation** et l’**impossibilité de bouger** ; or Jade bouge un peu le pied et rien n’est déformé. On valorise la prudence : seul un médecin peut confirmer.\n\n**Question 2.**\n- **R, Repos** : Jade **arrête** de jouer et s’assoit.\n- **I, Ice** : de la **glace** sur la cheville **15 à 20 minutes**, **jamais à même la peau**.\n- **C, Compression** : un **bandage** autour de la cheville, **sans serrer** au point de couper la circulation.\n- **E, Élévation** : **surélever** la jambe (pied posé plus haut).\n\nEnsuite : **prévenir l’enseignant** et demander un **avis médical**.\n\n**Question 3.**\n- Le **bracelet** : les bijoux **accrochent et blessent** ; il faut les retirer.\n- Les **chaussures mal lacées** : une **tenue adaptée** demande des chaussures de sport **lacées** ; sinon le pied est mal tenu et on se tord plus facilement la cheville.\n\n**Question 4.** Il ne faut **jamais** mettre la glace **à même la peau** : l’envelopper dans un linge, et ne pas dépasser **15 à 20 minutes**."}$exo$::jsonb),
  ('54a051e6-36a8-56ba-a832-18fb593022a3'::uuid, 3, 'redaction', $exo${"titre":"Un malaise en course d’orientation : agir et alerter","consigne":"Analyse la situation et explique, dans l’ordre, comment tu agis. Justifie chaque choix avec le cours.","enonce":"Pendant une course d’orientation dans un parc, tu es en binôme avec Lucas. Il est venu sans petit-déjeuner. Soudain, il devient très pâle, transpire et dit avoir des vertiges ; il s’assoit au bord d’une piste cyclable où passent des vélos. L’enseignant est à 500 mètres. Tu as un téléphone pour les urgences.\n\n**Question 1.** Quel est probablement le problème de Lucas ? Justifie avec les signes et avec ce qui s’est passé le matin.\n\n**Question 2.** Décris, dans l’ordre, les trois étapes de ton action et ce que tu fais concrètement à chacune.\n\n**Question 3.** L’état de Lucas s’aggrave et tu dois appeler les secours. Quel numéro peux-tu composer ? Que dois-tu dire, et quelle règle dois-tu respecter à la fin de l’appel ?\n\n**Question 4.** Quelle règle de prévention Lucas n’a pas respectée ? Explique pourquoi une consigne de sécurité n’est pas « une précaution théorique ».\n\n**Question 5.** Quelle formation te permettrait d’en savoir plus, et qu’y apprend-on ?","bareme":[{"critere":"Identification du malaise justifiée","points":3},{"critere":"Protéger, alerter, secourir appliqués à la situation","points":6},{"critere":"Numéro d’urgence et contenu de l’appel","points":5},{"critere":"Prévention et sens des consignes de sécurité","points":3},{"critere":"La formation PSC1 et son contenu","points":3}],"dureeMin":18,"corrige":"**Question 1.** Un **malaise** : **pâleur**, **sueurs**, **vertiges**. Lucas est venu **à jeun** : venir en EPS sans petit-déjeuner **expose au malaise**.\n\n**Question 2.**\n1. **Protéger** : supprimer le danger **sans se mettre en danger** ; éloigner Lucas de la piste cyclable, l’installer assis ou allongé dans un endroit sûr.\n2. **Alerter** : prévenir l’**enseignant** (l’appeler, ou demander à un autre binôme d’aller le chercher) ; appeler les secours si besoin.\n3. **Secourir** : **dans la limite de ce qu’on sait faire** ; rester avec lui, le rassurer, surveiller son état.\n\n**Question 3.** Le **15** (SAMU) ; on accepte le **112** (européen) ou le **18** (pompiers). Le **114** sert à alerter par SMS. Il faut donner **le lieu précis** (le parc, l’endroit exact), **ce qui s’est passé** et **l’état de la victime**. Il ne faut **jamais raccrocher le premier**.\n\n**Question 4.** Lucas n’a pas pris de **petit-déjeuner** avant l’effort. Une consigne de sécurité **existe parce qu’un accident a déjà eu lieu** : c’est **la trace d’un accident réel** qu’on ne veut pas revoir. On valorise aussi un rappel sur l’hydratation.\n\n**Question 5.** Le **PSC1** (Prévention et secours civiques de niveau 1), qu’on peut obtenir **dès le collège**. On y apprend la **position latérale de sécurité**, le **massage cardiaque** et l’utilisation du **défibrillateur**."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
    FROM public.chapter_exercices e
    JOIN public.chapters c ON c.id = e.chapter_id
   WHERE e.origine = 'catalogue' AND c.level = '6e';
  RAISE NOTICE '365 : % sujets de 6e au catalogue (attendu : 402)', n;
  IF n < 402 THEN
    RAISE WARNING '365 : il manque des sujets — des fiches de 6e ont-elles changé d''identifiant ?';
  END IF;
END $$;
